def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            best = s.copy()
            best_r = R_of(best)

    # Bootstrap if no start
    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    # Multi-scale refinement: start at current N, then grow
    # Strategy: polish at current N, then prolongate and polish again.
    cur = best.copy()
    cur_r = best_r

    # First, polish current
    if time.process_time() < deadline:
        cand = _lbfgs_log(cur, maxiter=2000, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # Scale ladder
    ladder = [cur.size]
    while ladder[-1] * 2 <= 4000:
        ladder.append(ladder[-1] * 2)

    for N in ladder[1:]:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _prolongate(cur, N)
        # smooth a bit to help
        cand = _smooth_conv(cand, 2)
        cand = _rescale(cand)
        cand = _lbfgs_log(cand, maxiter=3000, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
