    # NEW: periodic modulation multistart on coarse grid.
    Nc_list = (2048, 4096)
    ks = (8, 16, 32, 64)
    epss = (0.01, 0.03, 0.10)
    for Nc in Nc_list:
        if time.process_time() >= deadline - 4.0:
            break
        hc0 = _coarse(best, Nc)
        for k in ks:
            P = max(1.0, Nc / float(k))
            for eps in epss:
                if time.process_time() >= deadline - 3.0:
                    break
                for mode in ('mod', 'comb'):
                    if time.process_time() >= deadline - 3.0:
