        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    alt = None
    altR = 0.0

    # NEW primary idea: smooth multiplicative perturbations of the fine start,
    # followed by re-optimisation. The start is a fine local optimum; small
    # smooth bumps in log-heights push it into neighbouring basins that are
    # still close in shape (so cheap to optimise) but have better R.
    # Try several perturbation scales; keep the best result as alternative.
    perturb_specs = [
