    h0 = (h ** power) * np.exp(tilt * x)
    if h0.max() <= 0:
        return h
    h0 = np.where(h0 < thresh_frac * h0.max(), 0.0, h0)
    s = h0.sum()
    if s <= 0:
        return h
    h0 = h0 * (h.sum() / s)
    return _rescale(h0)


