    base_r = best_r

    # Experiment: asymmetric sparse starts from the base
    configs = [(4, -2.5), (6, -3.5), (3, -2.0)]
    results = []

    # Allocate budget: first config gets most, others share remainder
    # Run each config sequentially with a share of remaining time.
    for idx, (power, tilt) in enumerate(configs):
        if time.process_time() >= deadline - 1.0:
            break
        # remaining time share
        remaining = deadline - time.process_time()
        n_left = len(configs) - idx
        share = remaining / n_left
        sub_deadline = time.process_time() + share

        h0 = _sparsify(base, power, tilt)
        cand = _lbfgs_log(h0, maxiter=5000, deadline=sub_deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand.copy(), r
        results.append((r, cand))

        # window polish around peak
        if time.process_time() < sub_deadline - 0.5:
            for frac, extra in [(0.5, 4), (0.2, 4)]:
                if time.process_time() >= sub_deadline - 0.5:
                    break
                c2 = _window_polish_peak(cand, sub_deadline, frac, extra, maxiter=600)
                r2 = R_of(c2)
                if r2 > r:
                    cand, r = c2, r2
                if r2 > best_r:
                    best, best_r = c2.copy(), r2

    # Final polish of best with remaining time
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(best, maxiter=5000, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
