    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _components(h, thresh):
    mask = h > thresh
    if not mask.any():
        return []
    d = np.diff(mask.astype(np.int8))
    starts = list(np.flatnonzero(d == 1) + 1)
    ends = list(np.flatnonzero(d == -1))
    if mask[0]:
        starts = [0] + starts
    if mask[-1]:
        ends = ends + [mask.size - 1]
    return list(zip(starts, ends))


def _relocate(h, lo, hi, new_lo):
    """Remove component [lo,hi], reinsert its shape starting at new_lo."""
    n = h.size
    seg = h[lo:hi + 1].copy()
    h2 = h.copy()
    h2[lo:hi + 1] = 0.0
    end = new_lo + seg.size
    if new_lo < 0:
        seg = seg[-new_lo:]
        new_lo = 0
        end = new_lo + seg.size
    if end > n:
        seg = seg[:n - new_lo]
        end = n
    if seg.size > 0:
        h2[new_lo:end] += seg
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size

    # NEW IDEA: global relocation of the largest components.
    n_cand = 24
    pass_no = 0
    while time.process_time() < deadline - 3.0:
        pass_no += 1
        thresh = 1e-6 * best.max()
        comps = _components(best, thresh)
        if len(comps) == 0:
            break
        masses = np.array([best[lo:hi + 1].sum() for lo, hi in comps])
        order = np.argsort(-masses)[:10]
        improved_this_pass = False
        for ci in order:
            if time.process_time() >= deadline - 2.5:
                break
            lo, hi = comps[ci]
            width = hi - lo + 1
            cand_positions = np.linspace(0, N - width, n_cand).astype(int)
            best_cand = None
            best_candR = bestR
            for new_lo in cand_positions:
                if time.process_time() >= deadline - 2.0:
                    break
                if abs(new_lo - lo) < max(4, width // 4):
                    continue
                hc = _relocate(best, lo, hi, int(new_lo))
                if hc.sum() <= 0:
                    continue
                hc = _rescale(hc)
                wlo = max(0, min(lo, new_lo) - max(8, width // 2))
                whi = min(N - 1, max(hi, new_lo + width) + max(8, width // 2))
                free = np.arange(wlo, whi + 1)
                hc = _lbfgs_block(hc, free, maxiter=150, deadline=deadline)
                if time.process_time() >= deadline - 1.5:
                    break
                hc = _lbfgs_log(hc, 200, deadline)
                r = R_of(hc)
                if r > best_candR + 1e-9:
                    best_cand, best_candR = hc, r
            if best_cand is not None:
                best, bestR = best_cand, best_candR
                improved_this_pass = True
                print("relocate pass=%d comp=%d R=%.7f" %
                      (pass_no, ci, bestR))
        if not improved_this_pass:
            break

    # Final polish.
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)[:2 * h.size - 1]
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    if delta == 0:
        return h
    x = np.arange(n) + delta
    return np.interp(x, np.arange(n), h, left=0.0, right=0.0)


def _smooth_conv(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    out = np.convolve(h, ker, mode='same')
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = best.copy()
    cur_r = best_r

    # 1) full log-space polish of the starting construction
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(cur, maxiter=2000, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # 2) coarse-to-fine: solve at reduced resolution, then prolongate & polish.
    #    This is the new idea: optimize a small surrogate where each iteration
    #    is cheap, then lift to the current fine grid.  It explores shape space
    #    more broadly than the previous pure "grow N and polish" ladder.
    n_cur = cur.size
    coarse_sizes = [max(64, n_cur // 32), max(128, n_cur // 16),
                    max(256, n_cur // 8), max(512, n_cur // 4),
                    max(1024, n_cur // 2)]
    for Nc in coarse_sizes:
        if time.process_time() >= deadline - 3.0:
            break
        if Nc >= cur.size:
            continue
        hc = _coarse(cur, Nc)
        hc = _rescale(hc)
        hc = _lbfgs_log(hc, maxiter=1500, deadline=min(deadline, time.process_time() + 6.0))
        # prolongate back to current resolution and polish
        hf = _prolongate(hc, cur.size)
        hf = _smooth_conv(hf, 2)
        hf = _rescale(hf)
        hf = _lbfgs_log(hf, maxiter=800, deadline=deadline)
        r = R_of(hf)
        if r > cur_r + 1e-9:
            cur, cur_r = hf, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # 3) grow N and polish (kept from before, but with the improved base)
    N = cur.size
    while time.process_time() < deadline - 3.0:
        N = min(1000000, max(N * 2, N + 50))
        if N <= cur.size:
            break
        cand = _prolongate(cur, N)
        cand = _smooth_conv(cand, 2)
        cand = _rescale(cand)
        cand = _lbfgs_log(cand, maxiter=3000, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if r <= best_r - 1e-6 and N > 4000:
            break

    # 4) peak-window polishing
    for frac, extra in [(0.5, 4), (0.25, 4), (0.1, 4)]:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=800)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # 5) final full polish
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(best, maxiter=3000, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            rs = R_of(s)
            if rs >= best_r:
                return {"best": best, "alternative": s}
    return best

