        hi = int(edges[i + 1] * N)
        if hi <= lo:
            hi = lo + 1
        lo = min(lo, N - 1)
        hi = min(hi, N)
        h[lo:hi] = np.maximum(h[lo:hi], heights[i])
    frac_zero = rng.uniform(0.5, 0.75)
    mask = rng.random(N) < frac_zero
    h[mask] = 0.0
    if h.sum() <= 0:
        h = np.ones(N)
    return _rescale(h)


def _maxmean(h):
    m = h.mean()
    if m <= 0:
        return 0.0
    return h.max() / m


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(12345)

    # Phase 1: random sparse multiscale starts at N0=1024
    N0 = 1024
    n_starts = 24
    cands = []
    for i in range(n_starts):
        if time.process_time() >= deadline - 1.0:
            break
        h = _random_sparse_start(rng, N0)
        h = _lbfgs_log(h, maxiter=600, deadline=deadline)
        r = R_of(h)
        cands.append((r, h))
        if r > best_r:
            best, best_r = h.copy(), r

    cands.sort(key=lambda x: -x[0])
    top = [h for r, h in cands[:4]]
    if not top:
        top = [best.copy()]

    # Phase 2: ladder top candidates upward
    levels = [2048, 4096, 8192, 16384, 32000]
    pool = [(R_of(h), h) for h in top]
    for N in levels:
        if time.process_time() >= deadline - 1.0:
            break
        new_pool = []
        for r, h in pool:
            if time.process_time() >= deadline - 1.0:
                new_pool.append((r, h))
                continue
            cand = _prolongate(h, N)
            cand = _smooth_conv(cand, 2)
            cand = _rescale(cand)
            cand = _lbfgs_log(cand, maxiter=500, deadline=deadline)
            cand = _window_polish_peak(cand, deadline, 0.25, 16, maxiter=400)
            rr = R_of(cand)
            new_pool.append((rr, cand))
            if rr > best_r:
                best, best_r = cand.copy(), rr
        new_pool.sort(key=lambda x: -x[0])
        pool = new_pool[:4]

    cur = best.copy()
    cur_r = best_r

    # Phase 3: alternate full polish + peak window on best
    while time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(cur, maxiter=1500, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.5:
            break
        cand = _window_polish_peak(cur, deadline, 0.10, 4, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.5:
            break
        cand = _window_polish_peak(cur, deadline, 0.30, 8, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # EXPERIMENT: erosion of p0044 to seed spiky basin
    if start_arr is not None and time.process_time() < deadline - 1.0:
        h0 = start_arr.copy()
        mu = h0.mean()
        eroded_best = None
        eroded_best_r = -1.0
        for c in [1.0, 1.5, 2.0, 2.5]:
            if time.process_time() >= deadline - 1.0:
                break
            hs = np.clip(h0 - c * mu, 0.0, None)
            if hs.sum() <= 0:
                continue
            hs = _rescale(hs)
            hs = _lbfgs_log(hs, maxiter=800, deadline=deadline)
            hs = _window_polish_peak(hs, deadline, 0.10, 4, maxiter=600)
            hs = _window_polish_peak(hs, deadline, 0.30, 8, maxiter=600)
            rr = R_of(hs)
            if rr > eroded_best_r:
                eroded_best, eroded_best_r = hs.copy(), rr
            if rr > best_r:
                best, best_r = hs.copy(), rr

        if eroded_best is not None and _maxmean(eroded_best) > 8.0:
            # ladder the spiky candidate upward
            for N in [64000, 128000]:
                if time.process_time() >= deadline - 1.0:
                    break
                cand = _prolongate(eroded_best, N)
                cand = _rescale(cand)
                cand = _lbfgs_log(cand, maxiter=600, deadline=deadline)
                cand = _window_polish_peak(cand, deadline, 0.10, 8, maxiter=600)
                rr = R_of(cand)
                if rr > eroded_best_r:
                    eroded_best, eroded_best_r = cand, rr
                if rr > best_r:
                    best, best_r = cand.copy(), rr

        # spend remaining time polishing eroded and p0044 alternately
        while time.process_time() < deadline - 0.5:
            if eroded_best is not None:
                cand = _lbfgs_log(eroded_best, maxiter=1500, deadline=deadline)
                rr = R_of(cand)
                if rr > eroded_best_r:
                    eroded_best, eroded_best_r = cand, rr
                if rr > best_r:
                    best, best_r = cand.copy(), rr
                if time.process_time() >= deadline - 0.5:
                    break
                cand = _window_polish_peak(eroded_best, deadline, 0.10, 4, maxiter=600)
                rr = R_of(cand)
                if rr > eroded_best_r:
                    eroded_best, eroded_best_r = cand, rr
                if rr > best_r:
                    best, best_r = cand.copy(), rr
                if time.process_time() >= deadline - 0.5:
                    break
                cand = _window_polish_peak(eroded_best, deadline, 0.30, 8, maxiter=600)
                rr = R_of(cand)
                if rr > eroded_best_r:
                    eroded_best, eroded_best_r = cand, rr
                if rr > best_r:
                    best, best_r = cand.copy(), rr
            if time.process_time() >= deadline - 0.5:
                break
            cand = _lbfgs_log(h0, maxiter=1500, deadline=deadline)
            rr = R_of(cand)
            if rr > best_r:
                best, best_r = cand.copy(), rr
                h0 = cand
            if time.process_time() >= deadline - 0.5:
                break
            cand = _window_polish_peak(h0, deadline, 0.10, 4, maxiter=600)
            rr = R_of(cand)
            if rr > best_r:
                best, best_r = cand.copy(), rr
                h0 = cand

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h, p=0.0):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = Lf.max()
    if m <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    if p <= 0:
        im = int(np.argmax(Lf))
        gLf[im] += 1.0 / m
        val = -np.log(num) + 2.0 * np.log(s) + np.log(m)
    else:
        y = Lf / m
        yp = np.power(y, p)
        S = yp.sum()
        Lsoft = m * np.power(S, 1.0 / p)
        gLf += np.power(y, p - 1) / Lsoft
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lsoft)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, p=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh, p)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, p=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh, p)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_best = best.copy()
    alt_bestR = bestR
    N0 = best.size

    # NEW IDEA: soft-max (p-norm) surrogate homotopy.
    # The hard max in the denominator is non-smooth; optimising a smooth
    # p-norm approximation (large but finite p), then annealing p upward
    # to a very large value, escapes the flat ridge the hard-max L-BFGS
    # gets stuck on. This is a genuinely different route for the landscape.
    for p in (4.0, 8.0, 16.0, 32.0):
        if time.process_time() >= deadline - 6.0:
            break
        h = _lbfgs_log(best, 600, deadline, p=p)
        # polish peak window with the same soft surrogate
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(24, int(span * 0.4))
        lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
        h = _lbfgs_block(h, np.arange(lo, hi + 1), 400, deadline, p=p)
        r = R_of(h)
        print("soft p=%.0f R=%.7f" % (p, r))
        if r > alt_bestR + 1e-15:
            alt_best, alt_bestR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("new best R=%.7f" % bestR)

    # Fine-grid soft homotopy at 2x resolution to smooth staircase.
    if time.process_time() < deadline - 8.0:
        Nt = min(N0 * 2, 1000000)
        hp = _prolongate(best, Nt)
        hp = _rescale(hp)
        for p in (8.0, 16.0, 32.0):
            if time.process_time() >= deadline - 5.0:
                break
            hp = _lbfgs_log(hp, 500, deadline, p=p)
        r = R_of(hp)
        print("fine2x R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("new best R=%.7f" % bestR)

    # Coarsen back and refine with hard max.
    if time.process_time() < deadline - 4.0:
        hc = _coarse(best, N0)
        hc = _rescale(hc)
        hc = _lbfgs_log(hc, 600, deadline, p=0.0)
        r = R_of(hc)
        print("coarsen R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = hc, r
            print("new best R=%.7f" % bestR)

    # Final alternating polish until deadline.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline, p=0.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        lo, hi = _peak_region(best)
        span = hi - lo
        pad = max(24, int(span * 0.4))
        lo = max(0, lo - pad); hi = min(best.size - 1, hi + pad)
        h = _lbfgs_block(best, np.arange(lo, hi + 1), 400, deadline, p=0.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if alt_bestR > start_bestR + 1e-12:
        return {"best": best if bestR >= alt_bestR else alt_best,
                "alternative": alt_best}
    return {"best": start_best, "alternative": best}

