    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _smooth_conv(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    out = np.convolve(h, ker, mode='same')
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = best.copy()
    cur_r = best_r

    # High-resolution ladder
    levels = [64000, 128000, 256000]
    for N in levels:
        if time.process_time() >= deadline - 8.0:
            break
        if cur.size == N:
            cand = cur.copy()
        else:
            cand = _prolongate(cur, N)
            cand = _rescale(cand)
            cand = _lbfgs_log(cand, maxiter=800, deadline=deadline)
        if time.process_time() >= deadline - 8.0:
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            break
        cand = _window_polish_peak(cand, deadline, 0.05, 4, maxiter=600)
        if time.process_time() >= deadline - 8.0:
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            break
        cand = _window_polish_peak(cand, deadline, 0.10, 8, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # Continuous polish loop until deadline
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1500, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break
        for frac, extra in ((0.05, 4), (0.10, 8), (0.20, 16)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=600)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


# ---- NEW: spike-family construction ----
K_SPIKES = 10


def _spike_h(params, N):
    h = np.zeros(N)
    for i in range(K_SPIKES):
        x = params[3 * i]
        w = params[3 * i + 1]
        a = np.exp(params[3 * i + 2])
        lo = int(round(x * N))
        hi = int(round((x + w) * N))
        if hi <= lo:
            hi = lo + 1
        lo = max(0, min(N - 1, lo))
        hi = max(lo + 1, min(N, hi))
        h[lo:hi] += a
    return h


def _spike_obj(params, N):
    h = _spike_h(params, N)
    if h.sum() <= 0:
        return 1e9
    return -R_of(h)


def _spike_bounds():
    b = []
    for _ in range(K_SPIKES):
        b.append((0.0, 0.98))
        b.append((0.002, 0.06))
        b.append((np.log(0.05), np.log(20.0)))
    return b


def _run_de(seed, N, deadline):
    # budget in DE iterations; use maxiter small enough to fit
    try:
        res = differential_evolution(
            _spike_obj, _spike_bounds(), args=(N,),
            strategy='best1bin', maxiter=80, popsize=20, tol=1e-6,
            mutation=(0.5, 1.0), recombination=0.7, seed=seed,
            polish=False, workers=1, updating='immediate')
        return res.x, -res.fun
    except Exception as e:
        print("DE fail:", e)
        return None, 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N_target = best.size
    N_de = 1024

    # --- Global search over spike family at N=1024 ---
    configs = []
    for seed in (1, 2):
        if time.process_time() >= deadline - 8.0:
            break
        x, r = _run_de(seed, N_de, deadline)
        if x is not None:
            print("DE seed=%d R=%.7f" % (seed, r))
            configs.append((r, x))

    if not configs:
        # fall back to base behaviour: just polish the start
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        return {"best": start_best, "alternative": best}

    configs.sort(key=lambda t: -t[0])
    configs = configs[:2]

    # --- Polish each config at 1024, then ladder up ---
    ladder = [N_de]
    for Nt in (4096, 16384, N_target):
        if Nt > ladder[-1]:
            ladder.append(Nt)

    candidates = []
    for r0, x in configs:
        if time.process_time() >= deadline - 4.0:
            break
        h = _spike_h(x, N_de)
        if h.sum() <= 0:
            continue
        h = _rescale(h)
        h = _lbfgs_log(h, 800, deadline)
        r = R_of(h)
        print("polish1024 R=%.7f" % r)
        cur = h
        for Nt in ladder[1:]:
            if time.process_time() >= deadline - 3.0:
                break
            hp = _prolongate(cur, Nt)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 600, deadline)
            hp = _window_polish_peak(hp, deadline, 0.15, 8)
            r = R_of(hp)
            print("ladder %d R=%.7f" % (Nt, r))
            cur = hp
        candidates.append((R_of(cur), cur))

    # pick best candidate
    new_best, new_bestR = None, 0.0
    for r, h in candidates:
        if r > new_bestR:
            new_best, new_bestR = h, r

    if new_best is not None and new_bestR > bestR + 1e-15:
        best, bestR = new_best, new_bestR
        print("new basin wins R=%.7f" % bestR)

    # --- Spend remaining time alternating polish on best ---
    fracs = (0.05, 0.15, 0.30)
    fi = 0
    while time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 1000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish_peak(best, deadline, fracs[fi % 3], 16)
        fi += 1
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

