    """Return list of (index, height) spikes from runs of nonzero steps."""
    mx = h.max()
    if mx <= 0:
        return []
    mask = h > thresh_frac * mx
    if not mask.any():
        return []
    d = np.diff(mask.astype(np.int8))
    starts = list(np.flatnonzero(d == 1) + 1)
    ends = list(np.flatnonzero(d == -1))
    if mask[0]:
