import numpy as np
import time


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    m = L.max()
    if m <= 0:
        return -1.0
    # ||f*f||_2^2 with L = [0, *conv, 0]
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    return sq / (s * s * m)


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _rescale(h):
    m = h.max()
    if m > 0:
        return h / m
    return h


def _lbfgs_log(h0, maxiter, deadline):
    """Optimize log(h) with L-BFGS on R. Returns best h found."""
    from scipy.optimize import minimize
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-6)
    best_h = h0.copy()
    best_R = _R_of(h0)
    n = h0.size
    x0 = np.log(h0)

    def negR(x):
        h = np.exp(x)
        return -_R_of(h)

    # simple gradient via finite differences is too slow; use scipy numerical grad
    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-12, 'gtol': 1e-10})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except Exception:
        pass
    return best_h, best_R


def _lbfgs_sm(h0, beta, maxiter, deadline):
    """Logsumexp soft-max surrogate: minimize -||f*f||_2^2/(sum h)^2 * softmax_beta(L)."""
    from scipy.optimize import minimize
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-6)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def negR(x):
        h = np.exp(x)
        s = h.sum()
        if s <= 0:
            return 1e10
        L = np.convolve(h, h)
        Lp = np.empty(L.size + 2, dtype=float)
        Lp[0] = 0.0
        Lp[1:-1] = L
        Lp[-1] = 0.0
        a = Lp[:-1]
        b = Lp[1:]
        sq = np.sum(a * a + a * b + b * b) / 3.0
        # soft max
        m = L.max()
        w = np.exp(beta * (L - m))
        sm = m + np.log(w.sum()) / beta
        return -(sq / (s * s * sm))

    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-12, 'gtol': 1e-10})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except Exception:
        pass
    return best_h, best_R


def _window_polish_peak(h, frac, extra, deadline):
    """Polish a window around the peak of f*f by re-optimizing with log-LBFGS on a sub-window."""
    from scipy.optimize import minimize
    h = np.asarray(h, dtype=float)
    n = h.size
    if n < 8:
        return h, _R_of(h)
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    # map peak index (0..2n-2) to center in h (0..n-1)
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half + extra)
    if hi - lo < 4:
        return h, _R_of(h)
    best_h = h.copy()
    best_R = _R_of(h)
    sub = h[lo:hi].copy()
    if np.any(sub <= 0):
        sub = np.maximum(sub, 1e-6)
    x0 = np.log(sub)

    def negR(x):
        hh = h.copy()
        hh[lo:hi] = np.exp(x)
        return -_R_of(hh)

    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       options={'maxiter': 200, 'maxfun': 600,
                                'ftol': 1e-12, 'gtol': 1e-10})
        hh = h.copy()
        hh[lo:hi] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except Exception:
        pass
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = _R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    ladder = [64, 128, 256, 512, 1024, 2048, 4096, 8192, 16000, 32000, 64000]

    for N in ladder:
        if time.process_time() > deadline - 6.0:
            break
        if h.size != N:
            h = _prolongate(h, N)
        h = _rescale(h)
        h, R = _lbfgs_log(h, 400, deadline)
        if R > best_R:
            best_R = R
            best_h = h.copy()
        # logsumexp homotopy
        for beta in (4, 8, 16, 32, 64):
            if time.process_time() > deadline:
                break
            h2, R2 = _lbfgs_sm(h, beta, 200, deadline)
            if R2 > R:
                h = h2
                R = R2
                if R > best_R:
                    best_R = R
                    best_h = h.copy()
        # peak polish
        for frac, extra in ((0.05, 4), (0.10, 8)):
            if time.process_time() > deadline:
                break
            h2, R2 = _window_polish_peak(h, frac, extra, deadline)
            if R2 > R:
                h = h2
                R = R2
                if R > best_R:
                    best_R = R
                    best_h = h.copy()
        print("level N=%d R=%.6f best=%.6f" % (N, R, best_R))

    # final phase at largest N
    h = best_h.copy()
    N = h.size
    while time.process_time() < deadline:
        h2, R2 = _lbfgs_log(h, 1500, deadline)
        if R2 > best_R:
            best_R = R2
            h = h2
            best_h = h2.copy()
