    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(256)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # ---- Primary new idea: refine on a finer grid, then map back and
    # accept only if the mapped-back version beats the start. ----
    alt_returned = None

    if time.process_time() < deadline - 25.0:
        N_up = min(cur.size * 2, 500000)
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=400, deadline=deadline - 20.0)
        # polish peak window on the fine grid
        up2 = _window_polish_peak(up, deadline - 18.0, 0.15, 20, maxiter=300)
        if R_of(up2) > R_of(up):
            up = up2
        up_r = R_of(up)
        print("alt refine fine R = %.6f (N_up=%d)" % (up_r, N_up))
        # Map back to original size
        back = _rescale(_coarsen(up, cur.size))
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        elif up_r > best_r:
            # keep fine version directly if it scores better at fine N
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r
        else:
            # alternative candidate: fine-grid result (genuinely different)
            alt_returned = up.copy()

    # Coarsen-and-reprolong
    if cur.size >= 16384 and time.process_time() < deadline - 15.0:
        c = _rescale(_coarsen(cur, 16384))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        c = _rescale(_prolongate(c, cur.size))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        rc = R_of(c)
        if rc > best_r:
            best, best_r = c.copy(), rc
            cur, cur_r = c.copy(), rc
        print("coarsen-reprolong R = %.6f" % rc)

    # Smoothing continuation
    for beta in (4, 16, 64):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_sm(cur, beta, maxiter=150, deadline=deadline)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # Main loop
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, extra in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
