def _peak_sharpness(h):
    """Return ratio: how flat is the peak region of f*f."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    # count knots within 1% of max
    return float(np.sum(Lf >= 0.99 * mx)) / Lf.size


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(256)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Key new idea: try several smoothing scales (beta) on the start, pick best
    # This is a "continuation" from a rounded peak — smoothing the sharp max
    # can unlock a better basin than polishing the exact peak directly.
    best_sm = cur.copy()
    best_sm_r = cur_r
    for beta in (2, 6, 20, 80, 320):
        if time.process_time() >= deadline - 30.0:
            break
        c2 = _lbfgs_sm(cur, beta, maxiter=200, deadline=deadline)
        r2 = R_of(c2)
        if r2 > best_sm_r:
            best_sm, best_sm_r = c2, r2
        # follow-up exact polish
        c3 = _lbfgs_log(c2, maxiter=400, deadline=deadline)
        r3 = R_of(c3)
        if r3 > best_sm_r:
            best_sm, best_sm_r = c3, r3
    if best_sm_r > best_r:
        best, best_r = best_sm.copy(), best_sm_r
        cur, cur_r = best_sm.copy(), best_sm_r
        print("sm-continuation R = %.6f" % best_r)

    # Refine at higher resolution (prolongate) — more DOF allow sharper peaks
    # while keeping the overall shape.
    if time.process_time() < deadline - 25.0 and cur.size < 500000:
        for N_up in (cur.size * 2, cur.size * 3):
            N_up = int(min(N_up, 900000))
            if N_up <= cur.size:
                continue
            up = _rescale(_prolongate(cur, N_up))
            up = _lbfgs_log(up, maxiter=400, deadline=deadline)
            up_r = R_of(up)
            print("refine R = %.6f (N_up=%d)" % (up_r, N_up))
            if up_r > best_r:
                # keep it at high resolution — return the finer one
                best, best_r = up.copy(), up_r
                cur, cur_r = up.copy(), up_r
                # stop trying higher; just polish this
                break

    # Main loop: alternate full polish, peak window polish, and perturbation restarts
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, extra in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    m = L.max()
    if m <= 0:
        return -1.0
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    return sq / (s * s * m)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _rescale(h):
    m = h.max()
    if m > 0:
        return h / m
    return h


def _knots(h):
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    return Lp


def _num_and_dq(h):
    Lp = _knots(h)
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lp)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return sq, dq, Lp


def _backprop(h, dL):
    n = h.size
    if n > 1500:
        g = 2.0 * fftconvolve(dL, h[::-1], mode='full')
        return g[n - 1:2 * n - 1]
    else:
        g = np.zeros(n)
        for j in range(dL.size):
            if dL[j] == 0.0:
                continue
            i_lo = max(0, j - (n - 1))
            i_hi = min(n - 1, j)
            for i in range(i_lo, i_hi + 1):
                k = j - i
                g[i] += dL[j] * h[k]
                g[k] += dL[j] * h[i]
        return g


def _fun_grad(x):
    h = np.exp(x)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(x)
    sq, dq, Lp = _num_and_dq(h)
    m = Lp.max()
    if m <= 0:
        return 1e10, np.zeros_like(x)
    R = sq / (s * s * m)
    gsq = _backprop(h, dq[1:-1])
    idx = np.argmax(Lp)
    dmask = np.zeros_like(Lp)
    dmask[idx] = 1.0
    gm = _backprop(h, dmask[1:-1])
    dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
    gx = dR * h
    return -R, -gx


def _fun_grad_sm(x, beta):
    h = np.exp(x)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(x)
    sq, dq, Lp = _num_and_dq(h)
    L = Lp[1:-1]
    m = L.max()
    if m <= 0:
        return 1e10, np.zeros_like(x)
    w = np.exp(beta * (L - m))
    W = w.sum()
    sm = m + np.log(W) / beta
    dsm_dL = w / W
    dsm = np.zeros_like(Lp)
    dsm[1:-1] = dsm_dL
    R = sq / (s * s * sm)
    gsq = _backprop(h, dq[1:-1])
    gsm = _backprop(h, dsm[1:-1])
    dR = gsq / (s * s * sm) - R * (2.0 / s + gsm / sm)
    gx = dR * h
    return -R, -gx


class _Timeout(Exception):
    pass


def _lbfgs_log(h0, maxiter, deadline):
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        return _fun_grad(x)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _lbfgs_sm(h0, beta, maxiter, deadline):
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        return _fun_grad_sm(x, beta)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _active_set_log(h, maxiter, deadline, tol=1e-10):
    h = np.asarray(h, dtype=float)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h, _R_of(h)
    active = h > tol * mx
    if active.sum() < 4:
        return h, _R_of(h)
    idx = np.where(active)[0]
    sub = h[idx].copy()
    best_h = h.copy()
    best_R = _R_of(h)
    x0 = np.log(sub)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        hh = h.copy()
        hh[idx] = np.exp(x)
        return _fun_grad(np.log(np.maximum(hh, 1e-300)))

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h.copy()
        hh[idx] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _window_polish_peak(h, frac, extra, deadline, maxiter=200):
    h = np.asarray(h, dtype=float)
    n = h.size
    if n < 8:
        return h, _R_of(h)
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half + extra)
    if hi - lo < 4:
        return h, _R_of(h)
    best_h = h.copy()
    best_R = _R_of(h)
    sub = h[lo:hi].copy()
    if np.any(sub <= 0):
        sub = np.maximum(sub, 1e-12)
    x0 = np.log(sub)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        hh = h.copy()
        hh[lo:hi] = np.exp(x)
        s = hh.sum()
        sq, dq, Lp = _num_and_dq(hh)
        m = Lp.max()
        if m <= 0 or s <= 0:
            return 1e10, np.zeros_like(x)
        R = sq / (s * s * m)
        gsq = _backprop(hh, dq[1:-1])
        idx = np.argmax(Lp)
        dmask = np.zeros_like(Lp)
        dmask[idx] = 1.0
        gm = _backprop(hh, dmask[1:-1])
        dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
        gx = dR * hh
        return -R, -gx[lo:hi]

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h.copy()
        hh[lo:hi] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _prune(h, tol=1e-12):
    h = np.asarray(h, dtype=float)
    mx = h.max()
    if mx <= 0:
        return h
    h = h.copy()
    h[h < tol * mx] = 0.0
    return h


def _polish_level(h, deadline, betas, polish_fracs, maxiter=200):
    """Run active-set + high-beta homotopy + window polishes at fixed N."""
    cur_h = np.asarray(h, dtype=float).copy()
    cur_R = _R_of(cur_h)

    # Active-set exact polish first.
    if time.process_time() < deadline - 3.0:
        hp = _prune(cur_h, 1e-12)
        h3, R3 = _active_set_log(hp, maxiter, deadline, tol=1e-10)
        if R3 > cur_R:
            cur_h, cur_R = h3, R3

    for beta in betas:
        if time.process_time() > deadline - 4.0:
            break
        h2, R2 = _lbfgs_sm(cur_h, beta, maxiter, deadline)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if time.process_time() < deadline - 3.0:
            hp = _prune(cur_h, 1e-12)
            h3, R3 = _active_set_log(hp, maxiter, deadline, tol=1e-10)
            if R3 > cur_R:
                cur_h, cur_R = h3, R3

    for frac, extra in polish_fracs:
        if time.process_time() > deadline - 3.0:
            break
        h2, R2 = _window_polish_peak(cur_h, frac, extra, deadline, maxiter=300)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2

    return cur_h, cur_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = _R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    betas = (128, 512, 1024, 2048, 4096)
    polish_fracs = ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2))

    # Ladder of prolongations.
    ladder = [16384, 32768]
    cur_h = h.copy()
    cur_R = best_R
    best_N = h.size

    for N in ladder:
        if time.process_time() > deadline - 5.0:
            break
        if cur_h.size == N:
            hN = cur_h.copy()
        else:
            hN = _prolongate_mass(cur_h, N)
            hN = _rescale(hN)
        RN = _R_of(hN)
        print("prolongated to N=%d R=%.6f" % (N, RN))

        # Skip if too far below incumbent.
        if RN < best_R - 0.002 and N == 16384:
            print("  N=%d too far below, skipping to next" % N)
            cur_h = hN
            cur_R = RN
            continue

        hP, RP = _polish_level(hN, deadline, betas, polish_fracs, maxiter=200)
        print("N=%d polished R=%.6f" % (N, RP))
        if RP > best_R:
            best_R, best_h, best_N = RP, hP.copy(), N
        cur_h, cur_R = hP, RP

    # Spend remaining time alternating at best N.
    alt_betas = (2048, 1024, 512, 256, 4096)
    ai = 0
    while time.process_time() < deadline - 3.0:
        beta = alt_betas[ai % len(alt_betas)]
        ai += 1
        h2, R2 = _lbfgs_sm(cur_h, beta, 200, deadline)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if time.process_time() > deadline - 3.0:
            break
        h2, R2 = _window_polish_peak(cur_h, 0.15, 8, deadline, maxiter=250)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h, best_N = cur_R, cur_h.copy(), cur_h.size
        print("  alt beta=%d R=%.6f best=%.6f N=%d" % (beta, cur_R, best_R, best_N))

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
