    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, logspace=False):
    if time.process_time() >= deadline - 0.25:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    if logspace:
        x0 = np.log(np.clip(h[active], 1e-300, None))

        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = h.copy()
            hh[active] = np.exp(uu)
            val, g = _fun_grad(hh)
            return val, g[active] * hh[active]

        res = _run_lbfgs(f, x0, [(-30.0, 30.0)] * active.size,
                         maxiter, deadline - 0.15)
        if res is None:
            return h0
        h2 = h.copy()
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale(h2)
    else:
        x0 = h[active].copy()

        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = _fun_grad(hh)
            return val, g[active]

        res = _run_lbfgs(f, x0, [(0.0, None)] * active.size,
                         maxiter, deadline - 0.15)
        if res is None:
            return h0
        h2 = h.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)


# ---------- peak helpers ----------

def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, logspace=False):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline,
                        logspace=logspace)


# ---------- isotropic coordinate transforms ----------

def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


# ---------- ladder polish (operates on given N, no size change) ----------

def _polish(h, deadline, budget_sub):
    """Local polish of h at its current N. Returns (h, r)."""
    cur = _rescale(np.asarray(h, dtype=float))
    cur_r = R_of(cur)
    t_end = min(deadline - 0.5, time.process_time() + budget_sub)

    # alternating log & block polish, smoothing ladder
    for _ in range(3):
        if time.process_time() >= t_end:
            break
        c = _lbfgs_log(cur, maxiter=800, deadline=t_end)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
        for beta in (32, 64, 128):
            if time.process_time() >= t_end:
                break
            c = _lbfgs_sm(cur, beta, maxiter=400, deadline=t_end)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        for frac, extra in ((0.05, 4), (0.10, 8), (0.20, 16)):
            if time.process_time() >= t_end:
                break
            c = _window_polish_peak(cur, t_end, frac, extra, maxiter=600,
                                    logspace=False)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        if time.process_time() >= t_end:
            break
    return cur, cur_r


# ---------- seeds ----------

def _random_seed(N0, rng):
    h = np.zeros(N0)
    K = int(rng.integers(6, 21))
    for _ in range(K):
        w = int(rng.integers(1, 9))
        pos = int(rng.integers(0, max(1, N0 - w)))
        ht = 10.0 ** rng.uniform(0.0, 2.5)
        h[pos:pos + w] = np.maximum(h[pos:pos + w], ht)
    if h.sum() <= 0:
        h[N0 // 2] = 1.0
    return h


def _ladder_from(h, target_N, deadline):
    """Grow h up to target_N via prolongation, polishing at each level."""
    cur = _rescale(np.asarray(h, dtype=float))
    cur_r = R_of(cur)
    levels = []
    n = cur.size
    while n < target_N:
        n = min(target_N, n * 2)
        levels.append(n)
    if not levels:
        levels = [target_N]
    for N in levels:
        if time.process_time() > deadline - 4.0:
            break
        if cur.size != N:
            cur = _rescale(_prolongate(cur, N))
        c, r = _polish(cur, deadline, budget_sub=min(6.0,
                        max(1.0, (deadline - time.process_time()) / max(1, len(levels)))))
        if r > cur_r:
            cur, cur_r = c, r
    return cur, cur_r


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    print("start R = %.6f, N = %d" % (best_r, best.size))

    # ---- Main strategy: polish start at its own N (the strongest base) ----
    if start_arr is not None:
        cur, cur_r = _polish(start_arr.copy(), deadline,
                             budget_sub=min(20.0, budget_seconds * 0.35))
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            print("  polish start -> R=%.6f" % best_r)

    # ---- Try to grow to higher N if budget allows ----
    if start_arr is not None and time.process_time() < deadline - 8.0:
        for target_N in (start_arr.size * 2, start_arr.size * 4):
            if target_N > 200000:
                break
            if time.process_time() > deadline - 8.0:
                break
            # seed from current best
            base = _rescale(best.copy())
            if base.size != target_N:
                # upscale by prolongation
                base = _rescale(_prolongate(base, target_N))
            cur, cur_r = _ladder_from(base, target_N, deadline)
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
                print("  grow N=%d -> R=%.6f" % (target_N, best_r))

    # ---- Final continuous polish of best, at its own N ----
    if time.process_time() < deadline - 1.0:
        cur, cur_r = _polish(best.copy(), deadline,
                             budget_sub=max(1.0, deadline - time.process_time() - 0.5))
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            print("  final polish -> R=%.6f" % best_r)

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        # return the polished version as best; keep original start as alternative
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    m = L.max()
    if m <= 0:
        return -1.0
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    return sq / (s * s * m)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _rescale(h):
    m = h.max()
    if m > 0:
        return h / m
    return h


def _knots(h):
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    return Lp


def _num_and_dq(h):
    Lp = _knots(h)
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lp)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return sq, dq, Lp


def _backprop(h, dL):
    n = h.size
    if n > 1500:
        g = 2.0 * fftconvolve(dL, h[::-1], mode='full')
        return g[n - 1:2 * n - 1]
    else:
        g = np.zeros(n)
        for j in range(dL.size):
            if dL[j] == 0.0:
                continue
            i_lo = max(0, j - (n - 1))
            i_hi = min(n - 1, j)
            for i in range(i_lo, i_hi + 1):
                k = j - i
                g[i] += dL[j] * h[k]
                g[k] += dL[j] * h[i]
        return g


def _fun_grad(x):
    h = np.exp(x)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(x)
    sq, dq, Lp = _num_and_dq(h)
    m = Lp.max()
    if m <= 0:
        return 1e10, np.zeros_like(x)
    R = sq / (s * s * m)
    gsq = _backprop(h, dq[1:-1])
    idx = np.argmax(Lp)
    dmask = np.zeros_like(Lp)
    dmask[idx] = 1.0
    gm = _backprop(h, dmask[1:-1])
    dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
    gx = dR * h
    return -R, -gx


def _fun_grad_sm(x, beta):
    h = np.exp(x)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(x)
    sq, dq, Lp = _num_and_dq(h)
    L = Lp[1:-1]
    m = L.max()
    if m <= 0:
        return 1e10, np.zeros_like(x)
    w = np.exp(beta * (L - m))
    W = w.sum()
    sm = m + np.log(W) / beta
    dsm_dL = w / W
    dsm = np.zeros_like(Lp)
    dsm[1:-1] = dsm_dL
    R = sq / (s * s * sm)
    gsq = _backprop(h, dq[1:-1])
    gsm = _backprop(h, dsm[1:-1])
    dR = gsq / (s * s * sm) - R * (2.0 / s + gsm / sm)
    gx = dR * h
    return -R, -gx


# Direct (non-log) objective: gradient wrt h directly.
def _fun_grad_direct(h):
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(h)
    sq, dq, Lp = _num_and_dq(h)
    m = Lp.max()
    if m <= 0:
        return 1e10, np.zeros_like(h)
    R = sq / (s * s * m)
    gsq = _backprop(h, dq[1:-1])
    idx = np.argmax(Lp)
    dmask = np.zeros_like(Lp)
    dmask[idx] = 1.0
    gm = _backprop(h, dmask[1:-1])
    dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
    return -R, -dR


class _Timeout(Exception):
    pass


def _lbfgs_log(h0, maxiter, deadline):
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        return _fun_grad(x)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _lbfgs_sm(h0, beta, maxiter, deadline):
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        return _fun_grad_sm(x, beta)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _lbfgs_direct(h0, idx, maxiter, deadline):
    """Direct non-negative L-BFGS-B on entries idx of h0 (others fixed)."""
    h0 = np.asarray(h0, dtype=float)
    best_h = h0.copy()
    best_R = _R_of(h0)
    if idx is None:
        idx = np.arange(h0.size)
    if idx.size == 0:
        return best_h, best_R
    x0 = np.maximum(h0[idx], 0.0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        hh = h0.copy()
        hh[idx] = np.maximum(x, 0.0)
        return _fun_grad_direct(hh)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * idx.size,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h0.copy()
        hh[idx] = np.maximum(res.x, 0.0)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _window_polish_peak_direct(h, frac, extra, deadline, maxiter=200):
    h = np.asarray(h, dtype=float)
    n = h.size
    if n < 8:
        return h, _R_of(h)
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half + extra)
    if hi - lo < 4:
        return h, _R_of(h)
    idx = np.arange(lo, hi)
    return _lbfgs_direct(h, idx, maxiter, deadline)


def _active_set_log(h, maxiter, deadline, tol=1e-10):
    h = np.asarray(h, dtype=float)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h, _R_of(h)
    active = h > tol * mx
    if active.sum() < 4:
        return h, _R_of(h)
    idx = np.where(active)[0]
    sub = h[idx].copy()
    best_h = h.copy()
    best_R = _R_of(h)
    x0 = np.log(sub)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        hh = h.copy()
        hh[idx] = np.exp(x)
        return _fun_grad(np.log(np.maximum(hh, 1e-300)))

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h.copy()
        hh[idx] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _window_polish_peak(h, frac, extra, deadline, maxiter=200):
    h = np.asarray(h, dtype=float)
    n = h.size
    if n < 8:
        return h, _R_of(h)
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half + extra)
    if hi - lo < 4:
        return h, _R_of(h)
    best_h = h.copy()
    best_R = _R_of(h)
    sub = h[lo:hi].copy()
    if np.any(sub <= 0):
        sub = np.maximum(sub, 1e-12)
    x0 = np.log(sub)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        hh = h.copy()
        hh[lo:hi] = np.exp(x)
        s = hh.sum()
        sq, dq, Lp = _num_and_dq(hh)
        m = Lp.max()
        if m <= 0 or s <= 0:
            return 1e10, np.zeros_like(x)
        R = sq / (s * s * m)
        gsq = _backprop(hh, dq[1:-1])
        idx = np.argmax(Lp)
        dmask = np.zeros_like(Lp)
        dmask[idx] = 1.0
        gm = _backprop(hh, dmask[1:-1])
        dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
        gx = dR * hh
        return -R, -gx[lo:hi]

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h.copy()
        hh[lo:hi] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _prune(h, tol=1e-12):
    h = np.asarray(h, dtype=float)
    mx = h.max()
    if mx <= 0:
        return h
    h = h.copy()
    h[h < tol * mx] = 0.0
    return h


def _perturb_peak(h, sigma, frac=0.30):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half)
    if hi <= lo:
        return h
    noise = np.random.randn(hi - lo) * sigma
    h[lo:hi] = np.maximum(h[lo:hi] * np.exp(noise), 0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    np.random.seed(12345)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = _R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Prolongate to N=8192 by cumulative mass.
    if h.size < 8192:
        h8 = _prolongate_mass(h, 8192)
        h8 = _rescale(h8)
        R8 = _R_of(h8)
        print("prolongated to N=8192 R=%.6f" % R8)
        if R8 > best_R:
            best_R, best_h = R8, h8.copy()
    else:
        h8 = h.copy()

    cur_h = h8.copy()
    cur_R = _R_of(cur_h)

    # --- Experiment: direct non-negative L-BFGS-B polishing ---
    # 1) Full-vector direct L-BFGS-B, maxiter 800.
    if time.process_time() < deadline - 3.0:
        h2, R2 = _lbfgs_direct(cur_h, None, 800, deadline)
        print("direct full R=%.6f (cur %.6f)" % (R2, cur_R))
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # 2) Prune + direct L-BFGS-B on remaining positive entries (400 iters).
    if time.process_time() < deadline - 3.0:
        hp = _prune(cur_h, 1e-10)
        idx = np.where(hp > 0)[0]
        if idx.size >= 4:
            h3, R3 = _lbfgs_direct(hp, idx, 400, deadline)
            print("  prune+direct R=%.6f" % R3)
            if R3 > cur_R:
                cur_h, cur_R = h3, R3
            if cur_R > best_R:
                best_R, best_h = cur_R, cur_h.copy()

    # 3) Peak-window direct polish at fracs.
    polish_fracs = ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2))
    for frac, extra in polish_fracs:
        if time.process_time() > deadline - 3.0:
            break
        h2, R2 = _window_polish_peak_direct(cur_h, frac, extra, deadline, maxiter=300)
