import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    m = L.max()
    if m <= 0:
        return -1.0
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    return sq / (s * s * m)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _rescale(h):
    m = h.max()
    if m > 0:
        return h / m
    return h


def _knots(h):
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    return Lp


def _num_and_dq(h):
    Lp = _knots(h)
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lp)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return sq, dq, Lp


def _backprop(h, dL):
    n = h.size
    if n > 1500:
        g = 2.0 * fftconvolve(dL, h[::-1], mode='full')
        return g[n - 1:2 * n - 1]
    else:
        g = np.zeros(n)
        for j in range(dL.size):
            if dL[j] == 0.0:
                continue
            i_lo = max(0, j - (n - 1))
            i_hi = min(n - 1, j)
            for i in range(i_lo, i_hi + 1):
                k = j - i
                g[i] += dL[j] * h[k]
                g[k] += dL[j] * h[i]
        return g


def _fun_grad(x):
    h = np.exp(x)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(x)
    sq, dq, Lp = _num_and_dq(h)
    m = Lp.max()
    if m <= 0:
        return 1e10, np.zeros_like(x)
    R = sq / (s * s * m)
    gsq = _backprop(h, dq[1:-1])
    idx = np.argmax(Lp)
    dmask = np.zeros_like(Lp)
    dmask[idx] = 1.0
    gm = _backprop(h, dmask[1:-1])
    dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
    gx = dR * h
    return -R, -gx


def _fun_grad_sm(x, beta):
    h = np.exp(x)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros_like(x)
    sq, dq, Lp = _num_and_dq(h)
    L = Lp[1:-1]
    m = L.max()
    if m <= 0:
        return 1e10, np.zeros_like(x)
    w = np.exp(beta * (L - m))
    W = w.sum()
    sm = m + np.log(W) / beta
    dsm_dL = w / W
    dsm = np.zeros_like(Lp)
    dsm[1:-1] = dsm_dL
    R = sq / (s * s * sm)
    gsq = _backprop(h, dq[1:-1])
    gsm = _backprop(h, dsm[1:-1])
    dR = gsq / (s * s * sm) - R * (2.0 / s + gsm / sm)
    gx = dR * h
    return -R, -gx


class _Timeout(Exception):
    pass


def _lbfgs_log(h0, maxiter, deadline):
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        return _fun_grad(x)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _lbfgs_sm(h0, beta, maxiter, deadline):
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        return _fun_grad_sm(x, beta)

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _window_polish_peak(h, frac, extra, deadline, maxiter=200):
    h = np.asarray(h, dtype=float)
    n = h.size
    if n < 8:
        return h, _R_of(h)
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half + extra)
    if hi - lo < 4:
        return h, _R_of(h)
    best_h = h.copy()
    best_R = _R_of(h)
    sub = h[lo:hi].copy()
    if np.any(sub <= 0):
        sub = np.maximum(sub, 1e-12)
    x0 = np.log(sub)

    def f(x):
        if time.process_time() > deadline - 0.5:
            raise _Timeout()
        hh = h.copy()
        hh[lo:hi] = np.exp(x)
        s = hh.sum()
        sq, dq, Lp = _num_and_dq(hh)
        m = Lp.max()
        if m <= 0 or s <= 0:
            return 1e10, np.zeros_like(x)
        R = sq / (s * s * m)
        gsq = _backprop(hh, dq[1:-1])
        idx = np.argmax(Lp)
        dmask = np.zeros_like(Lp)
        dmask[idx] = 1.0
        gm = _backprop(hh, dmask[1:-1])
        dR = gsq / (s * s * m) - R * (2.0 / s + gm / m)
        gx = dR * hh
        return -R, -gx[lo:hi]

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h.copy()
        hh[lo:hi] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except _Timeout:
        pass
    except Exception:
        pass
    return best_h, best_R


def _stats(h):
    L = np.convolve(h, h)
    m = L.max()
    near = np.mean(L >= 0.999 * m)
    pos = np.argmax(L) / max(1, L.size - 1)
    return near, pos


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = _R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Prolongate to N=8192 (incumbent).
    if h.size < 8192:
        h8 = _rescale(_prolongate_mass(h, 8192))
    else:
        h8 = h.copy()
    R8 = _R_of(h8)
    if R8 > best_R:
        best_R, best_h = R8, h8.copy()
    print("incumbent N=8192 R=%.6f" % R8)

    # Coarsen to N=1024 by cumulative mass.
    hc = _rescale(_prolongate_mass(h8, 1024))
    Rc = _R_of(hc)
    near, pos = _stats(hc)
    print("coarse N=1024 R=%.6f near=%.4f pos=%.3f" % (Rc, near, pos))

    cur_h = hc.copy()
    cur_R = Rc

    # Low-beta logsumexp homotopy on coarse grid.
    for beta in (8, 16, 32, 64, 128):
        if time.process_time() > deadline - 4.0:
            break
        h2, R2 = _lbfgs_sm(cur_h, beta, 400, deadline)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if time.process_time() > deadline - 3.5:
            break
        h3, R3 = _lbfgs_log(cur_h, 600, deadline)
        if R3 > cur_R:
            cur_h, cur_R = h3, R3
        if time.process_time() > deadline - 3.0:
            break
        h4, R4 = _window_polish_peak(cur_h, 0.20, 8, deadline, maxiter=300)
        if R4 > cur_R:
            cur_h, cur_R = h4, R4
        near, pos = _stats(cur_h)
        print("coarse beta=%d R=%.6f near=%.4f pos=%.3f" % (beta, cur_R, near, pos))
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # Gated ladder.
    ladder = (1024, 2048, 4096, 8192)
    level_h = cur_h.copy()
    level_R = cur_R
    for N in ladder[1:]:
        if time.process_time() > deadline - 3.0:
            break
        hn = _rescale(_prolongate_mass(level_h, N))
        Rn = _R_of(hn)
        if Rn > best_R:
            best_R, best_h = Rn, hn.copy()
        cur_h, cur_R = hn, Rn
        near, pos = _stats(cur_h)
        print("ladder N=%d prolong R=%.6f near=%.4f pos=%.3f" % (N, Rn, near, pos))

        for beta in (64, 256, 1024):
            if time.process_time() > deadline - 3.0:
                break
            h2, R2 = _lbfgs_sm(cur_h, beta, 300, deadline)
            if R2 > cur_R:
                cur_h, cur_R = h2, R2
            if cur_R > best_R:
                best_R, best_h = cur_R, cur_h.copy()

        if time.process_time() < deadline - 2.5:
            h3, R3 = _lbfgs_log(cur_h, 400, deadline)
            if R3 > cur_R:
                cur_h, cur_R = h3, R3
            if cur_R > best_R:
                best_R, best_h = cur_R, cur_h.copy()

        for frac in (0.30, 0.15, 0.05):
            if time.process_time() > deadline - 2.5:
                break
            h4, R4 = _window_polish_peak(cur_h, frac, 8, deadline, maxiter=250)
            if R4 > cur_R:
                cur_h, cur_R = h4, R4
            if cur_R > best_R:
                best_R, best_h = cur_R, cur_h.copy()

        near, pos = _stats(cur_h)
        print("ladder N=%d R=%.6f near=%.4f pos=%.3f" % (N, cur_R, near, pos))

        # Gate: advance only if within 0.002 of best.
        if cur_R >= best_R - 0.002:
            level_h, level_R = cur_h.copy(), cur_R
        else:
            # keep polishing current level
            while time.process_time() < deadline - 2.5:
                h5, R5 = _window_polish_peak(cur_h, 0.15, 8, deadline, maxiter=200)
                if R5 > cur_R:
                    cur_h, cur_R = h5, R5
                else:
                    break
                if cur_R > best_R:
                    best_R, best_h = cur_R, cur_h.copy()
            level_h, level_R = cur_h.copy(), cur_R

    # Final alternation until deadline.
    alt_betas = (1024, 512, 256, 128)
    ai = 0
    while time.process_time() < deadline - 2.0:
        beta = alt_betas[ai % len(alt_betas)]
        ai += 1
        h2, R2 = _lbfgs_sm(cur_h, beta, 200, deadline)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if time.process_time() > deadline - 2.0:
            break
        h2, R2 = _window_polish_peak(cur_h, 0.10, 8, deadline, maxiter=200)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    near, pos = _stats(best_h)
    print("final R=%.6f N=%d near=%.4f pos=%.3f" % (best_R, best_h.size, near, pos))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    n_full = cur.size
    N_fine = 64000 if n_full < 64000 else n_full

    # ---------------- Phase 1: prolongate to fine N, flatten-then-sharpen ----
    phase1_end = t0 + 0.30 * (deadline - t0)
    try:
        h = _prolongate(cur, N_fine)
        h = _rescale(h)
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= phase1_end - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=400, deadline=phase1_end)
            r = R_of(c)
            if r > R_of(h):
                h = c
        if time.process_time() < phase1_end - 0.5:
            c = _lbfgs_log(h, maxiter=800, deadline=phase1_end)
            if R_of(c) > R_of(h):
                h = c
        if time.process_time() < phase1_end - 0.5:
            c = _window_polish_peak(h, phase1_end, 0.30, 16, maxiter=400, beta=800.0)
            if R_of(c) > R_of(h):
                h = c
        if time.process_time() < phase1_end - 0.5:
            c = _window_polish_peak(h, phase1_end, 0.15, 8, maxiter=400, beta=None)
            if R_of(c) > R_of(h):
                h = c
        _consider(h, R_of(h))
        print("phase1 R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Phase 2: coarse-escape at the fine level --------------
    phase2_end = t0 + 0.65 * (deadline - t0)

    def _coarse_escape(h, N_small, t_end):
        if time.process_time() >= t_end - 1.0:
            return h
        hs = _prolongate(h, N_small)
        slice_end = min(t_end - 0.5, time.process_time() + 3.0)
        for beta in (300.0, 1000.0):
            if time.process_time() >= slice_end - 0.5:
                break
            c = _lbfgs_sm(hs, beta, maxiter=200, deadline=slice_end)
            if R_of(c) > R_of(hs):
                hs = c
        if time.process_time() < slice_end - 0.5:
            c = _lbfgs_log(hs, maxiter=400, deadline=slice_end)
            if R_of(c) > R_of(hs):
                hs = c
        hb = _prolongate(hs, h.size)
        if time.process_time() < t_end - 0.5:
            c = _lbfgs_log(hb, maxiter=600, deadline=t_end)
            if R_of(c) > R_of(hb):
                hb = c
        if time.process_time() < t_end - 0.5:
            c = _window_polish_peak(hb, t_end, 0.30, 16, maxiter=400, beta=600.0)
            if R_of(c) > R_of(hb):
                hb = c
        return hb

    try:
        for N_small in (16000, 8000):
            if time.process_time() >= phase2_end - 1.0:
                break
            hb = _coarse_escape(cur, N_small, phase2_end)
            _consider(hb, R_of(hb))
        if time.process_time() < phase2_end - 2.0:
            hb = _coarse_escape(cur, 16000, phase2_end)
            _consider(hb, R_of(hb))
        print("phase2 R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Phase 3: descending-beta flatten-then-sharpen --------
    try:
        while time.process_time() < deadline - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= deadline - 1.0:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=deadline - 0.5)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < deadline - 1.0:
                c = _lbfgs_log(h, maxiter=600, deadline=deadline - 0.5)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= deadline - 1.0:
                    break
                c = _window_polish_peak(h, deadline - 0.5, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= deadline - 1.0:
                break
        print("phase3 R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # Final: make sure best is at least start
    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    n_full = cur.size
    # NEW: try several coarse resolutions, pick the best result rather than one.
    if n_full >= 4000:
        N_smalls = [max(1000, n_full // 8), max(1000, n_full // 4), max(1000, n_full // 2)]
    elif n_full >= 1500:
        N_smalls = [max(500, n_full // 3), max(500, n_full // 2)]
    else:
        N_smalls = [n_full]

    did_coarse = 0
    coarse_idx = 0

    while time.process_time() < deadline - 0.8:
        # 1) smoothing-phase polish at several betas, then sharpen
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline - 0.5)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # 2) wide window polish on peak region
        cand = _window_polish_peak(cur, deadline - 0.5, 0.4, 20, maxiter=500, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # 2b) NEW: cycle through different coarse resolutions for escaping minima
        do_coarse = (did_coarse < len(N_smalls)) or (rng.random() < 0.4)
        if do_coarse and time.process_time() < deadline - 4.0:
            N_small = N_smalls[coarse_idx % len(N_smalls)]
            coarse_idx += 1
            if N_small < n_full:
                did_coarse += 1
                h_small = _prolongate(cur, N_small)
                slice_end = min(deadline - 0.5, time.process_time() + 3.5)
                for beta in (300.0, 1000.0):
                    if time.process_time() >= slice_end - 0.5:
                        break
                    h_small = _lbfgs_sm(h_small, beta, maxiter=200, deadline=slice_end)
                h_small = _lbfgs_log(h_small, maxiter=400, deadline=slice_end)
                h_big = _prolongate(h_small, n_full)
                h_big = _lbfgs_log(h_big, maxiter=600, deadline=deadline - 0.5)
                h_big = _window_polish_peak(h_big, deadline - 0.5, 0.3, 16,
                                            maxiter=400, beta=600.0)
                r = R_of(h_big)
                if r > cur_r:
                    cur, cur_r = h_big, r
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                elif r > alt_r:
                    alternative, alt_r = h_big.copy(), r
        if time.process_time() >= deadline - 0.8:
            break

        # 3) perturb + refine
        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine_best(trial, deadline - 0.5,
                                          time_slice=min(6.0, deadline - time.process_time() - 0.5))
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

