def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


# ---- NEW: single-knot local max polish, exact and cheap ----
def _lift_max_knot(h, deadline, iters=200):
    """Directly attack max_j L_j: find argmax knot, add a small bump to h
    around the two contributing locations to raise that knot, renormalise.
    Uses the fact that L_j = sum_k h_k h_{j-k}."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    best = h.copy()
    best_r = R_of(best)
    step = 0.02 * h.max()
    for it in range(iters):
        if time.process_time() > deadline - 0.3:
            break
        Lf = _knots(best)
        j = int(np.argmax(Lf))
        # L_j = sum_{k} h[k] h[j-1-k]  (conv index j-1 -> Lf[j])
        c = j - 1  # conv index
        if c < 0 or c >= 2 * n - 1:
            break
        # gradient of L_j wrt h
        g = np.zeros(n)
        kmin = max(0, c - (n - 1))
        kmax = min(n - 1, c)
        if kmax >= kmin:
            ks = np.arange(kmin, kmax + 1)
            g[ks] = best[c - ks]
            g[c - ks] += best[ks]
        gn = g / (np.linalg.norm(g) + 1e-30)
        # Try adding a scaled gradient step and rescaling
        cand = best + step * gn * (h.max())
        cand = _rescale(np.clip(cand, 0, None))
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
            step *= 1.5
        else:
            step *= 0.6
            if step < 1e-6 * h.max():
                break
    return best


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    n_full = cur.size
    N_fine = 64000 if n_full < 64000 else n_full

    # ---------------- Phase 1: prolongate to fine N, flatten-then-sharpen ----
    phase1_end = t0 + 0.30 * (deadline - t0)
    try:
        h = _prolongate(cur, N_fine)
        h = _rescale(h)
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= phase1_end - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=400, deadline=phase1_end)
            r = R_of(c)
            if r > R_of(h):
                h = c
        if time.process_time() < phase1_end - 0.5:
            c = _lbfgs_log(h, maxiter=800, deadline=phase1_end)
            if R_of(c) > R_of(h):
                h = c
        if time.process_time() < phase1_end - 0.5:
            c = _window_polish_peak(h, phase1_end, 0.30, 16, maxiter=400, beta=800.0)
            if R_of(c) > R_of(h):
                h = c
        if time.process_time() < phase1_end - 0.5:
            c = _window_polish_peak(h, phase1_end, 0.15, 8, maxiter=400, beta=None)
            if R_of(c) > R_of(h):
                h = c
        _consider(h, R_of(h))
        print("phase1 R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Phase 2: coarse-escape at the fine level --------------
    phase2_end = t0 + 0.65 * (deadline - t0)

    def _coarse_escape(h, N_small, t_end):
        if time.process_time() >= t_end - 1.0:
            return h
        hs = _prolongate(h, N_small)
        slice_end = min(t_end - 0.5, time.process_time() + 3.0)
        for beta in (300.0, 1000.0):
            if time.process_time() >= slice_end - 0.5:
                break
            c = _lbfgs_sm(hs, beta, maxiter=200, deadline=slice_end)
            if R_of(c) > R_of(hs):
                hs = c
        if time.process_time() < slice_end - 0.5:
            c = _lbfgs_log(hs, maxiter=400, deadline=slice_end)
            if R_of(c) > R_of(hs):
                hs = c
        hb = _prolongate(hs, h.size)
        if time.process_time() < t_end - 0.5:
            c = _lbfgs_log(hb, maxiter=600, deadline=t_end)
            if R_of(c) > R_of(hb):
                hb = c
        if time.process_time() < t_end - 0.5:
            c = _window_polish_peak(hb, t_end, 0.30, 16, maxiter=400, beta=600.0)
            if R_of(c) > R_of(hb):
                hb = c
        return hb

    try:
        for N_small in (16000, 8000):
            if time.process_time() >= phase2_end - 1.0:
                break
            hb = _coarse_escape(cur, N_small, phase2_end)
            _consider(hb, R_of(hb))
        if time.process_time() < phase2_end - 2.0:
            hb = _coarse_escape(cur, 16000, phase2_end)
            _consider(hb, R_of(hb))
        print("phase2 R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Phase 3: descending-beta + NEW max-knot lift ----------
    try:
        while time.process_time() < deadline - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= deadline - 1.0:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=deadline - 0.5)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < deadline - 1.0:
                c = _lbfgs_log(h, maxiter=600, deadline=deadline - 0.5)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= deadline - 1.0:
                    break
                c = _window_polish_peak(h, deadline - 0.5, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            # NEW: direct lift of the max knot
            if time.process_time() < deadline - 1.0:
                c = _lift_max_knot(h, deadline - 0.5, iters=150)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= deadline - 1.0:
                break
        print("phase3 R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # Final: make sure best is at least start
    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    # NEW: coordinate-wise "peak-flattening" attack. The dominant loss in
    # R comes from the spread of near-max knots of f*f. We directly target
    # that by (a) finding all knots within a small relative band of the max
    # and (b) running a focused smooth-max polish whose beta is tuned so that
    # precisely that band is flattened, plus a sharp polish afterward.
    while time.process_time() < deadline - 0.8:
        # Focused band-flattening: choose beta from actual knot spread.
        Lf = _knots(cur)
        M = Lf.max()
        near = Lf[Lf >= 0.98 * M]
        if near.size > 1:
            spread = (M - near.min()) / max(M, 1e-12)
            beta_focus = 4.0 / max(spread, 1e-6)
        else:
            beta_focus = 1500.0
        beta_focus = float(np.clip(beta_focus, 100.0, 8000.0))

        cand = _lbfgs_sm(cur, beta_focus, maxiter=400, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # Smooth-max at several betas, then sharpen (as before).
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline - 0.5)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        cand = _window_polish_peak(cur, deadline - 0.5, 0.4, 20, maxiter=500, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine_best(trial, deadline - 0.5,
                                          time_slice=min(6.0, deadline - time.process_time() - 0.5))
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

