                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt = None
    altR = 0.0

    def try_improve(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s R=%.7f" % (tag, bestR))
            return True
        else:
            if alt is None or r > altR:
                alt, altR = h, r
            return False

    # Smooth-max polish (soft peak) to escape the hard-max kink, then exact.
    for beta in (2.0e4, 5.0e4, 1.5e5, 5.0e5, 1.5e6):
        if time.process_time() >= deadline - 3.0:
            break
        h = _lbfgs_log(best, 400, deadline) if False else best
        # soft-max on full support via log-param
        n = best.size
        thresh = 1e-13 * best.max()
        active = np.flatnonzero(best > thresh)
        if active.size == 0:
            break
        u0 = np.log(np.clip(best[active], 1e-300, None))

        def f(u, beta=beta):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = _fun_grad_sm(hh, beta)
            return val, g[active] * hh[active]

        cb = _make_cb(deadline - 0.3)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * active.size,
                           callback=cb,
                           options={'maxiter': 300, 'maxfun': 600,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            h2 = _rescale(h2)
            h2 = _lbfgs_log(h2, 400, deadline)
            try_improve(h2, "sm%.0e" % beta)
        except (TimeoutError, Exception):
            break

    # Main loop: alternate exact full polish and peak-window polishes.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        if try_improve(h, "full"):
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        for frac, extra in ((0.40, 24), (0.20, 12), (0.10, 8)):
            if time.process_time() >= deadline - 1.0:
                break
            h = _window_polish_peak(best, deadline, frac, extra)
            if try_improve(h, "win%.2f" % frac):
                improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None and alt is not None and altR > 0 and bestR <= startR + 1e-12:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h, Nc):
    """Mass-preserving coarsening by cumulative-mass integration."""
    n = h.size
    if Nc >= n:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _softmax_pass(h, beta, deadline, maxiter=200):
    """Mild logsumexp soft-max smoothing pass then exact polish."""
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    # Soft-max smoothing of the profile: replace h by a smooth envelope
    # via logsumexp over a small window, then re-polish exactly.
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    r = max(1, int(n / (2 * beta)) if beta > 0 else 1)
    r = min(r, max(1, n // 20))
    if r <= 1:
        return _lbfgs_log(h, maxiter, deadline)
    # logsumexp smoothing
    logh = np.log(np.clip(h, 1e-300, None))
    # windowed logsumexp via cumulative trick is complex; use simple
    # convolution-based soft-max approximation on a coarse grid.
    k = np.ones(2 * r + 1)
    # approximate softmax: shift by max, exp, convolve, log
    m = logh.max()
    e = np.exp(logh - m)
    if n > 4000:
        sm = fftconvolve(e, k / k.sum(), mode='same')
    else:
        sm = np.convolve(e, k / k.sum(), mode='same')
    hs = np.exp(np.log(np.clip(sm, 1e-300, None)) + m)
    hs = _rescale(hs)
    return _lbfgs_log(hs, maxiter, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
            startR = bestR
        else:
            best, bestR, startR = None, 0.0, 0.0
    else:
        best, bestR, startR = None, 0.0, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
        startR = bestR

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    alt = None
    altR = 0.0

    def _try(h, tag):
        nonlocal best, bestR, alt, altR
        if h is None or h.sum() <= 0:
            return
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))
        elif alt is None or r > altR:
            alt, altR = h, r

    def _coarse_cycle(Nc, tag):
        """Coarsen, optimize coarse, prolongate, polish at full N."""
        if time.process_time() >= deadline - 6.0:
            return
        hc = _rescale(_coarsen(best, Nc))
        hc = _lbfgs_log(hc, 300, deadline)
        if time.process_time() < deadline - 5.0:
            hc = _softmax_pass(hc, 100, deadline, 150)
        if time.process_time() < deadline - 4.5:
            hc = _softmax_pass(hc, 300, deadline, 150)
        if time.process_time() < deadline - 4.0:
            hc = _lbfgs_log(hc, 300, deadline)
        rc = R_of(hc)
        print("%s coarse R=%.7f (Nc=%d)" % (tag, rc, Nc))
        if time.process_time() >= deadline - 3.0:
            return
        hp = _rescale(_prolongate(hc, N))
        hp = _lbfgs_log(hp, 400, deadline)
        for frac, extra in ((0.05, 4), (0.10, 8), (0.20, 16)):
            if time.process_time() >= deadline - 2.0:
                break
            hp = _window_polish_peak(hp, deadline, frac, extra)
            hp = _lbfgs_log(hp, 300, deadline)
        _try(hp, tag)

    # First coarse cycle at 1/8 and 1/4.
    _coarse_cycle(max(1, N // 8), "c8")
    _coarse_cycle(max(1, N // 4), "c4")

    # If time remains, one more coarsen-to-1/4 cycle.
    if time.process_time() < deadline - 8.0:
        _coarse_cycle(max(1, N // 4), "c4b")

    # Final full-resolution polish loop.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt is not None and altR > 0 and bestR <= startR + 1e-12:
        return {"best": best, "alternative": alt}
    return best

