def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _perturb_window(h, rng):
    """Perturb the right-half window [0.55N, N) with block multiplications."""
    h = h.copy()
    n = h.size
    lo = int(0.55 * n)
    hi = n
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    cuts = np.sort(rng.choice(np.arange(1, W), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(nblocks):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, 0.25))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _perturb_left(h, rng):
    """Perturb the left-half window [0, 0.50N) with block multiplications."""
    h = h.copy()
    n = h.size
    lo = 0
    hi = int(0.50 * n)
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    # block widths 0.02-0.10 of window; build cuts accordingly
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, 0.30))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # ---------------- Experiment: seeded LEFT-half perturbations ----------
    hard_end = deadline - 0.5
    n_seeds = 12
    for seed in range(n_seeds):
        if time.process_time() >= hard_end - 1.0:
            break
        rng_s = np.random.default_rng(2000 + seed)
        h = _perturb_left(cur, rng_s)
        for beta in (300.0, 800.0, 2000.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=300, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=800, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        for frac in (0.15, 0.30):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _window_polish_peak(h, hard_end, frac, 8, maxiter=400, beta=None)
            if R_of(c) >= R_of(h):
                h = c
        r = R_of(h)
        _consider(h, r)

    print("experiment R=%.6f N=%d" % (best_r, best.size))

    # ---------------- Fallback: base-style refinement if time remains ------
    try:
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

