        if time.process_time() >= deadline - 2.5:
            try_improve(cand, "pert%d" % seed)
            break
        cand = _lbfgs_log(cand, 400, deadline)
        for frac, extra in ((0.40, 24), (0.20, 12), (0.10, 8)):
            if time.process_time() >= deadline - 1.5:
                break
            cand = _window_polish_peak(cand, deadline, frac, extra)
        try_improve(cand, "pert%d" % seed)

    # --- Base program's smooth-max sweep on the (possibly improved) best ---
    for beta in (2.0e4, 5.0e4, 1.5e5, 5.0e5, 1.5e6):
        if time.process_time() >= deadline - 3.0:
            break
        h2 = _sm_polish(best, (beta,), 300, deadline)
        h2 = _lbfgs_log(h2, 400, deadline)
        try_improve(h2, "sm%.0e" % beta)

    # Main loop: alternate exact full polish and peak-window polishes.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        if try_improve(h, "full"):
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        for frac, extra in ((0.40, 24), (0.20, 12), (0.10, 8)):
            if time.process_time() >= deadline - 1.0:
                break
            h = _window_polish_peak(best, deadline, frac, extra)
            if try_improve(h, "win%.2f" % frac):
                improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None and alt is not None and altR > 0 and bestR <= startR + 1e-12:
        return {"best": best, "alternative": alt}
    return best

