import numpy as np
import time


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    return float(sq / (s * s * m))


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    # piecewise-constant resample via cumulative mass
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    res = h[idx]
    return np.maximum(res, 0.0)


def _softmax_obj(h, beta):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e30
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    # logsumexp soft max
    mx = L.max()
    lse = mx + np.log(np.sum(np.exp(beta * (L - mx)))) / beta
    return -(sq / (s * s * lse))


def _lbfgs_sm(h, beta, maxiter, deadline):
    try:
        from scipy.optimize import minimize
    except Exception:
        return h
    x0 = np.asarray(h, dtype=float).copy()
    n = x0.size
    if n > 20000:
        maxiter = min(maxiter, 60)
    def fun(x):
        return _softmax_obj(x, beta)
    try:
        res = minimize(fun, x0, method='L-BFGS-B',
                       bounds=[(0, None)] * n,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = np.maximum(res.x, 0.0)
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _lbfgs_log(h, maxiter, deadline):
    try:
        from scipy.optimize import minimize
    except Exception:
        return h
    x0 = np.asarray(h, dtype=float).copy()
    n = x0.size
    if n > 20000:
        maxiter = min(maxiter, 60)
    def fun(x):
        hh = np.exp(np.clip(x, -50, 50))
        return -_R_of(hh)
    try:
        res = minimize(fun, np.log(np.maximum(x0, 1e-12)), method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = np.exp(np.clip(res.x, -50, 50))
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _window_polish_peak(h, frac, extra, maxiter, deadline):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    L = np.convolve(h, h)
    Lp = np.concatenate(([0.0], L, [0.0]))
    k = int(np.argmax(Lp))
    # peak of f*f at index k in Lp (0..2n). Map to h index range.
    half = max(2, int(frac * n))
    lo = max(0, (k - half) // 2 - extra)
    hi = min(n, (k + half) // 2 + extra + 1)
    if hi - lo < 2:
        return h
    sub = h[lo:hi].copy()
    m = sub.size
    try:
        from scipy.optimize import minimize
    except Exception:
        return h
    def fun(x):
        hh = h.copy()
        hh[lo:hi] = np.maximum(x, 0.0)
        return -_R_of(hh)
    try:
        res = minimize(fun, sub, method='L-BFGS-B',
                       bounds=[(0, None)] * m,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = h.copy()
        out[lo:hi] = np.maximum(res.x, 0.0)
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = _R_of(best)

    h = np.ones(64)
    levels = (64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384)
    betas = (2, 4, 8, 16, 32, 64, 128, 256)

    for N in levels:
        if not time_left():
            break
        h = _prolongate(h, N)
        r_before = _R_of(h)
        for beta in betas:
            if not time_left():
                break
            cand = _lbfgs_sm(h, beta, 300, deadline)
            rc = _R_of(cand)
            if rc > _R_of(h):
                h = cand
        if time_left():
            cand = _lbfgs_log(h, 800, deadline)
            if _R_of(cand) > _R_of(h):
                h = cand
        if time_left():
            cand = _window_polish_peak(h, 0.25, 8, 400, deadline)
            if _R_of(cand) > _R_of(h):
                h = cand
        if time_left():
            cand = _window_polish_peak(h, 0.10, 8, 400, deadline)
            if _R_of(cand) > _R_of(h):
                h = cand
        r_after = _R_of(h)
        if r_after < r_before - 0.01 and time_left():
            cand = _lbfgs_log(h, 800, deadline)
            if _R_of(cand) > _R_of(h):
                h = cand
            cand = _window_polish_peak(h, 0.25, 8, 400, deadline)
            if _R_of(cand) > _R_of(h):
                h = cand
        rh = _R_of(h)
        if rh > bestR:
            bestR = rh
            best = h.copy()

    fracs = (0.05, 0.15, 0.30)
    fi = 0
    while time_left() and best is not None:
        cand = _lbfgs_log(best, 600, deadline)
        if _R_of(cand) > bestR:
            bestR = _R_of(cand)
            best = cand
        f = fracs[fi % len(fracs)]
        fi += 1
        cand = _window_polish_peak(best, f, 8, 400, deadline)
        if _R_of(cand) > bestR:
            bestR = _R_of(cand)
            best = cand

    if best is None:
        best = np.ones(64)
    return best

import numpy as np
import time


# ---------- exact R ----------
def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or h.max() <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.max() <= 0:
        return -1.0
    s = np.sum(h)
    if s <= 0:
        return -1.0
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    a = Lp[:-1]
    b = Lp[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = (s * s) * L.max()
    return num / den


def _rescale(h):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    m = h.max()
    if m <= 0:
        return np.ones_like(h)
    return h / m


# ---------- prolongation by cumulative mass ----------
def _prolongate(h, Nnew):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == Nnew:
        return h.copy()
    # cumulative mass at old step boundaries
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    # new boundaries at k/Nnew of old-step units
    xs = np.arange(Nnew + 1) * (N / Nnew)
    newc = np.interp(xs, np.arange(N + 1), c)
    out = np.diff(newc)
    out = np.maximum(out, 0.0)
    return _rescale(out)


# ---------- softmax parametrisation ----------
def _softmax(z, beta):
    z = np.asarray(z, dtype=float)
    m = z.max()
    e = np.exp(beta * (z - m))
    return e / e.sum() * z.size  # mean 1


def _logparam(z):
    return np.exp(np.clip(z, -30, 30))


# ---------- L-BFGS (simple, self-contained) ----------
def _lbfgs(fun, x0, maxiter=200, m=10, tol=1e-12):
    x = np.array(x0, dtype=float)
    n = x.size
    f, g = fun(x)
    if not np.isfinite(f):
        return x, f
    s_hist = []
    y_hist = []
    for it in range(maxiter):
        # two-loop recursion
        q = g.copy()
        alphas = []
        for s, y in reversed(list(zip(s_hist, y_hist))):
            rho = 1.0 / (y @ s + 1e-30)
            a = rho * (s @ q)
            alphas.append(a)
            q -= a * y
        if s_hist:
            s, y = s_hist[-1], y_hist[-1]
            gamma = (s @ y) / (y @ y + 1e-30)
        else:
            gamma = 0.01
        r = gamma * q
        for (s, y), a in zip(zip(s_hist, y_hist), reversed(alphas)):
            rho = 1.0 / (y @ s + 1e-30)
            b = rho * (y @ r)
            r += (a - b) * s
        d = -r
        gd = g @ d
        if gd >= 0:
            d = -g
            gd = -(g @ g)
        # backtracking line search
        step = 1.0
        if s_hist:
            s, y = s_hist[-1], y_hist[-1]
            step = min(1.0, 1.0 / (np.linalg.norm(d) + 1e-30) * 1.0)
        c1 = 1e-4
        accepted = False
        for _ in range(30):
            xn = x + step * d
            fn, gn = fun(xn)
            if np.isfinite(fn) and fn <= f + c1 * step * gd:
                accepted = True
                break
            step *= 0.5
        if not accepted:
            break
        s = xn - x
        y = gn - g
        sy = s @ y
        if sy > 1e-12:
            s_hist.append(s)
            y_hist.append(y)
            if len(s_hist) > m:
                s_hist.pop(0)
                y_hist.pop(0)
        x, f, g = xn, fn, gn
        if np.linalg.norm(g) < tol:
            break
    return x, f


def _lbfgs_sm(h0, beta, maxiter=250):
    h0 = _rescale(h0)
    z0 = np.log(np.maximum(h0, 1e-6))

    def fun(z):
        h = _softmax(z, beta)
        return -_R_of(h), np.zeros_like(z)

    # numeric gradient via finite differences (small N cheap enough)
    def fun_num(z):
        f0 = -_R_of(_softmax(z, beta))
        g = np.zeros_like(z)
        eps = 1e-4
        for i in range(z.size):
            zp = z.copy()
            zp[i] += eps
            g[i] = (-_R_of(_softmax(zp, beta)) - f0) / eps
        return f0, g

    z, _ = _lbfgs(fun_num, z0, maxiter=maxiter)
    return _rescale(_softmax(z, beta))


def _lbfgs_log(h0, maxiter=600):
    h0 = _rescale(h0)
    z0 = np.log(np.maximum(h0, 1e-6))

    def fun(z):
        h = _logparam(z)
        return -_R_of(h), np.zeros_like(z)

    def fun_num(z):
        f0 = -_R_of(_logparam(z))
        g = np.zeros_like(z)
        eps = 1e-4
        for i in range(z.size):
            zp = z.copy()
            zp[i] += eps
            g[i] = (-_R_of(_logparam(zp)) - f0) / eps
        return f0, g

    z, _ = _lbfgs(fun_num, z0, maxiter=maxiter)
    return _rescale(_logparam(z))


def _window_polish_peak(h, frac=0.2, extra=8, iters=40):
    h = _rescale(h).copy()
    N = h.size
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    # window in h-space around the peak (peak of f*f at index ~ 2*center)
    center = peak // 2
    w = max(2, int(frac * N))
    lo = max(0, center - w)
    hi = min(N, center + w)
    best = _R_of(h)
    for _ in range(iters):
        improved = False
        for i in range(lo, hi):
            for delta in (1.5, 0.7, 0.3):
                for sgn in (1.0, -1.0):
                    hn = h.copy()
                    hn[i] = max(0.0, hn[i] * (1.0 + sgn * (delta - 1.0) * 0.5))
                    hn = _rescale(hn)
                    r = _R_of(hn)
                    if r > best + 1e-12:
                        best = r
                        h = hn
                        improved = True
        if not improved:
            break
    return h


def _random_blocks(N, nblocks, zero_frac=0.0, rng=None):
    if rng is None:
        rng = np.random.default_rng()
    h = np.zeros(N)
    widths = np.exp(rng.uniform(np.log(0.5), np.log(6.0), size=nblocks))
    widths = widths / widths.sum() * N
    widths = np.maximum(widths, 1.0)
    widths = widths / widths.sum() * N
    # place contiguously
    pos = 0.0
    bounds = [0]
    for w in widths:
        pos += w
        bounds.append(int(round(pos)))
    bounds[-1] = N
    bounds = np.clip(bounds, 0, N)
    # ensure monotone
    for i in range(1, len(bounds)):
        if bounds[i] < bounds[i - 1]:
            bounds[i] = bounds[i - 1]
    heights = np.exp(rng.normal(0, 1.0, size=nblocks))
    for k in range(nblocks):
        a, b = bounds[k], bounds[k + 1]
        if b > a:
            h[a:b] = heights[k]
    if zero_frac > 0:
        nz = int(zero_frac * nblocks)
        if nz > 0:
            idx = rng.choice(nblocks, size=nz, replace=False)
            for k in idx:
                a, b = bounds[k], bounds[k + 1]
                if b > a:
                    h[a:b] = 0.0
    return _rescale(h)


def _chain(h, betas, log_iters, polish_specs, deadline):
    best = _rescale(h)
    bestR = _R_of(best)
    for beta in betas:
        if time.process_time() > deadline:
            return best, bestR
        cand = _lbfgs_sm(best, beta, maxiter=250)
        r = _R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    if time.process_time() < deadline:
        cand = _lbfgs_log(best, maxiter=log_iters)
        r = _R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    for frac, extra in polish_specs:
        if time.process_time() > deadline:
            break
        cand = _window_polish_peak(best, frac=frac, extra=extra)
        r = _R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    rng = np.random.default_rng(12345)
    N1 = 8192
    nseeds = 8

    seeds = []
    for s in range(nseeds):
        nblocks = int(rng.integers(12, 31))
        zf = 0.2 if (s % 2 == 1) else 0.0
        h = _random_blocks(N1, nblocks, zero_frac=zf, rng=rng)
        seeds.append(h)

    results = []
    betas1 = [8, 32, 128, 512]
    specs1 = [(0.20, 8), (0.5, 16)]
    for s, h in enumerate(seeds):
        if time.process_time() > deadline:
            break
        hb, rb = _chain(h, betas1, 600, specs1, deadline)
        results.append((rb, hb))
        print(f"seed {s}: R={rb:.6f}")

    if not results:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    results.sort(key=lambda x: -x[0])
    bestR, bestH = results[0]

    # second-best as alternative
    altH = results[1][1] if len(results) > 1 else None

    # prolongate best to N=32768
    N2 = 32768
    if time.process_time() < deadline:
        h2 = _prolongate(bestH, N2)
        betas2 = [16, 64, 256, 1024]
        specs2 = [(0.20, 8), (0.5, 16)]
        hb, rb = _chain(h2, betas2, 600, specs2, deadline)
        if rb > bestR:
            bestR, bestH = rb, hb
        print(f"prolongated: R={rb:.6f}")

    # remaining time: alternate log polish and peak polish
    while time.process_time() < deadline:
        cand = _lbfgs_log(bestH, maxiter=300)
        r = _R_of(cand)
        if r > bestR:
            bestR, bestH = r, cand
        cand = _window_polish_peak(bestH, frac=0.3, extra=12, iters=20)
        r = _R_of(cand)
        if r > bestR:
            bestR, bestH = r, cand
        else:
            # no improvement; small perturbation to escape
            h = bestH.copy()
            idx = rng.integers(0, h.size, size=max(1, h.size // 50))
            h[idx] *= np.exp(rng.normal(0, 0.3, size=idx.size))
            h = _rescale(h)
            cand = _lbfgs_log(h, maxiter=200)
            r = _R_of(cand)
            if r > bestR:
                bestR, bestH = r, cand

    bestH = _rescale(bestH)

    # compare with start
    if start is not None:
        st = np.asarray(start, dtype=float)
        if _R_of(st) > bestR:
            if altH is not None:
                return {"best": st, "alternative": _rescale(altH)}
            return st

    print(f"final R={_R_of(bestH):.6f}, N={bestH.size}")
    if altH is not None and _R_of(altH) > 0:
        return {"best": bestH, "alternative": _rescale(altH)}
    return bestH

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_window_at(h, lo, hi, rng, sigma=0.30):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _prolongate(h, M):
    """Cumulative-mass resample: each new height = mass of old interval it covers * M/N_old."""
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    # cumulative mass at old edges
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    # new edges in old-index coordinates
    edges = np.linspace(0.0, N, M + 1)
    # mass at each new edge via interpolation of cm
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    # scale so that total mass matches original (should already)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _polish_chain(h, deadline, log_iters, sm_betas, sm_iters, polish_fracs,
                  polish_extra, polish_iters):
    """Run exact log L-BFGS, softmax ladder, then peak-window polishes."""
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for beta in sm_betas:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_lbfgs_sm(cur, beta, maxiter=sm_iters, deadline=deadline))
    if time.process_time() < deadline - 0.5:
