    return cb


def _opt_log(h0, fun, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fun(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    return _opt_log(h0, _fun_grad, maxiter, deadline)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    return _opt_log(h0, lambda h: _fun_grad_sm(h, beta), maxiter, deadline)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _restrict(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _refine_full(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        improved = False
        for beta in (500.0, 200.0, 80.0, 30.0):
            if time.process_time() >= t_end - 0.5:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=1200, deadline=t_end)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
                improved = True
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=2000, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            improved = True
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.2, 8, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            improved = True
        if not improved:
            break
    return cur, cur_r


def _resample_blocks(h, rng, lo_b, hi_b):
    """Randomly perturb by shifting a block's mass. Returns new array or None."""
    n = h.size
    blk = int(rng.integers(lo_b, hi_b + 1))
    if blk >= n or blk < 2:
        return None
    lo = int(rng.integers(0, n - blk))
    trial = h.copy()
    # shift mass: move a fraction of a block's mass sideways
    seg = trial[lo:lo + blk]
    shift = int(rng.integers(1, max(2, blk)))
    direction = 1 if rng.random() < 0.5 else -1
    amount = float(rng.uniform(0.1, 0.9))
    moved = seg * amount
    trial[lo:lo + blk] -= moved
    target = lo + direction * shift
    tlo = max(0, min(n - blk, target))
    trial[tlo:tlo + blk] += moved
    trial = np.clip(trial, 0, None)
    if trial.sum() <= 0:
        return None
    return _rescale(trial)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(246813579)

    if start_arr is None:
        N0 = 1024
        cands = []
        for i in range(16):
            if time.process_time() >= deadline - 2.0:
                break
            h = np.zeros(N0)
            B = int(rng.integers(12, 40))
            widths = np.exp(rng.uniform(np.log(1.0), np.log(60.0), size=B))
            widths /= widths.sum()
            heights = np.exp(rng.uniform(np.log(1.0), np.log(200.0), size=B))
            edges = np.concatenate(([0.0], np.cumsum(widths)))
            for j in range(B):
                lo = int(edges[j] * N0); hi = int(edges[j + 1] * N0)
                hi = max(hi, lo + 1); lo = min(lo, N0 - 1); hi = min(hi, N0)
                h[lo:hi] = np.maximum(h[lo:hi], heights[j])
            h[rng.random(N0) < 0.55] = 0.0
            if h.sum() <= 0:
                h = np.ones(N0)
            h = _rescale(h)
            h = _lbfgs_log(h, maxiter=600, deadline=deadline)
            r = R_of(h)
            cands.append((r, h))
        cands.sort(key=lambda x: -x[0])
        pool = [(r, h) for r, h in cands[:4]] or [(best_r, best)]
        for N in (2048, 4096, 8192, 16384, 32000):
            if time.process_time() >= deadline - 1.0:
                break
            new_pool = []
            for r, h in pool:
                if time.process_time() >= deadline - 1.0:
                    new_pool.append((r, h)); continue
                cand = _prolongate(h, N)
                cand = _rescale(cand)
                cand = _lbfgs_log(cand, maxiter=500, deadline=deadline)
                cand = _window_polish_peak(cand, deadline, 0.25, 16, maxiter=400)
                rr = R_of(cand)
                new_pool.append((rr, cand))
                if rr > best_r:
                    best, best_r = cand.copy(), rr
            new_pool.sort(key=lambda x: -x[0])
            pool = new_pool[:4]
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < deadline - 0.5:
            cur, cur_r = _refine_full(cur, deadline,
                                      time_slice=min(15.0, deadline - time.process_time() - 0.5))
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        return best

    # Warm start
    cur = start_arr.copy()
    cur_r = best_r
    n = cur.size
    alternative = None
    alt_r = -1.0

    # Phase 1: full-vector smooth-max refinement + resample-block perturbation.
    while time.process_time() < deadline - 1.0:
        slice_t = min(10.0, deadline - time.process_time() - 1.0)
        if slice_t <= 0.5:
            break
        cand, cand_r = _refine_full(cur, deadline, time_slice=slice_t)
        if cand_r > cur_r + 1e-12:
            cur, cur_r = cand, cand_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif cand_r > alt_r:
            alternative, alt_r = cand.copy(), cand_r
        if time.process_time() >= deadline - 1.0:
            break
        # Mass-shift perturbation (structure-preserving, unlike multiplicative noise)
        trial = _resample_blocks(cur, rng, max(4, n // 60), max(8, n // 6))
        if trial is not None:
            trial_r = R_of(trial)
            if trial_r > 0.3 * cur_r:
                trial, trial_r = _refine_full(
                    trial, deadline,
                    time_slice=min(6.0, deadline - time.process_time() - 1.0))
            if trial_r > cur_r:
                cur, cur_r = trial, trial_r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
            elif trial_r > alt_r:
                alternative, alt_r = trial.copy(), trial_r

    # Phase 2: peak-window polishing with smooth-max (helps with kinks near peak).
    while time.process_time() < deadline - 0.6:
        slice_t = min(6.0, deadline - time.process_time() - 0.6)
        if slice_t <= 0.4:
            break
        t_end = time.process_time() + slice_t
        cand = _window_polish_peak(cur, t_end, 0.15, 6, maxiter=800, beta=200.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r
        if time.process_time() >= t_end - 0.3:
            continue
        cand = _window_polish_peak(cur, t_end, 0.3, 10, maxiter=800, beta=80.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
