        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    n_full = cur.size

    # Primary strategy: work on a larger grid than start (prolongate up),
    # which was the key lever in the prior program. Keep pushing resolution.
    target_N = min(1000000, max(n_full * 2, 64000))
    h_big = _prolongate(cur, target_N)
    slice_end = min(deadline - 0.5, time.process_time() + 6.0)
    for beta in (300.0, 800.0, 1500.0):
        if time.process_time() >= slice_end - 0.5:
            break
        h_big = _lbfgs_sm(h_big, beta, maxiter=250, deadline=slice_end)
    h_big = _lbfgs_log(h_big, maxiter=800, deadline=slice_end)
    h_big = _window_polish_peak(h_big, slice_end, 0.3, 16, maxiter=500, beta=600.0)
    h_big = _lbfgs_log(h_big, maxiter=500, deadline=slice_end)
    r = R_of(h_big)
    if r > cur_r:
        cur, cur_r = h_big, r
        n_full = target_N
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
    elif r > alt_r:
        alternative, alt_r = h_big.copy(), r

    # Coarse re-parameterisation candidates
    if n_full >= 4000:
        N_smalls = [max(1000, n_full // 8), max(1000, n_full // 4), max(1000, n_full // 2)]
    elif n_full >= 1500:
        N_smalls = [max(500, n_full // 3), max(500, n_full // 2)]
    else:
        N_smalls = [n_full]

    did_coarse = 0
    coarse_idx = 0

    while time.process_time() < deadline - 0.8:
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline - 0.5)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        cand = _window_polish_peak(cur, deadline - 0.5, 0.4, 20, maxiter=500, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # Grow resolution upward more aggressively than before.
        if n_full <= 500000 and time.process_time() < deadline - 5.0 and rng.random() < 0.5:
            N_up = min(1000000, n_full * 2)
            h_up = _prolongate(cur, N_up)
            slice_end = min(deadline - 0.5, time.process_time() + 4.0)
            h_up = _lbfgs_log(h_up, maxiter=700, deadline=slice_end)
            h_up = _window_polish_peak(h_up, slice_end, 0.3, 16, maxiter=400, beta=600.0)
            h_up = _lbfgs_log(h_up, maxiter=500, deadline=slice_end)
            r = R_of(h_up)
            if r > cur_r:
                cur, cur_r = h_up, r
                n_full = N_up
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
            elif r > alt_r:
                alternative, alt_r = h_up.copy(), r

        do_coarse = (did_coarse < len(N_smalls)) or (rng.random() < 0.4)
        if do_coarse and time.process_time() < deadline - 4.0:
            N_small = N_smalls[coarse_idx % len(N_smalls)]
            coarse_idx += 1
            if N_small < n_full:
                did_coarse += 1
                h_small = _prolongate(cur, N_small)
                slice_end = min(deadline - 0.5, time.process_time() + 3.5)
                for beta in (300.0, 1000.0):
                    if time.process_time() >= slice_end - 0.5:
                        break
                    h_small = _lbfgs_sm(h_small, beta, maxiter=200, deadline=slice_end)
                h_small = _lbfgs_log(h_small, maxiter=400, deadline=slice_end)
                h_big2 = _prolongate(h_small, n_full)
                h_big2 = _lbfgs_log(h_big2, maxiter=600, deadline=deadline - 0.5)
                h_big2 = _window_polish_peak(h_big2, deadline - 0.5, 0.3, 16,
                                             maxiter=400, beta=600.0)
                r = R_of(h_big2)
                if r > cur_r:
                    cur, cur_r = h_big2, r
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                elif r > alt_r:
                    alternative, alt_r = h_big2.copy(), r
        if time.process_time() >= deadline - 0.8:
            break

        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine_best(trial, deadline - 0.5,
                                          time_slice=min(6.0, deadline - time.process_time() - 0.5))
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    return float(sq / (s * s * m))


def _knots(h):
    L = fftconvolve(h, h)
    n = h.size
    L = L[:2 * n - 1]
    return np.concatenate(([0.0], L, [0.0]))


def _num_and_dq(L):
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return num, dq


def _backprop(gLf, h):
    n = h.size
    return 2.0 * fftconvolve(gLf[1:-1], h[::-1], mode='valid')[:n]


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _adaptive_resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    hmax = h.max()
    if hmax <= 0:
        return np.ones(N)
    w = h * h + 1e-6 * (hmax * hmax)
    c = np.concatenate(([0.0], np.cumsum(w)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    t = np.linspace(0.0, total, N + 1)
    x = np.interp(t, c, np.arange(M + 1, dtype=float))
    cm = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.arange(M + 1, dtype=float)
    vals = np.interp(x, xs, cm)
    dx = np.diff(x)
    dx = np.where(dx <= 1e-15, 1e-15, dx)
    out = np.diff(vals) / dx
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        return np.ones(N)
    return out


def _lbfgs_log(h, maxiter, deadline):
    n = h.size
    x0 = np.log(np.maximum(h, 1e-12))
    mask = h > 1e-13 * h.max()
    if mask.sum() < 2:
        mask = np.ones(n, dtype=bool)

    def fun(x):
        hh = np.zeros(n)
        hh[mask] = np.exp(np.clip(x, -50, 50))
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        L = _knots(hh)
        num, dq = _num_and_dq(L)
        m = L.max()
        if m <= 0 or num <= 0:
            return 1e30, np.zeros_like(x)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(m)
        gL = -dq / num
        k = np.argmax(L)
        gL[k] += 1.0 / m
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[mask] * hh[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = np.zeros(n)
        out[mask] = np.exp(np.clip(res.x, -50, 50))
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _lbfgs_sm(h, beta, maxiter, deadline):
    n = h.size
    x0 = np.log(np.maximum(h, 1e-12))
    mask = h > 1e-13 * h.max()
    if mask.sum() < 2:
        mask = np.ones(n, dtype=bool)

    def fun(x):
        hh = np.zeros(n)
        hh[mask] = np.exp(np.clip(x, -50, 50))
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        L = _knots(hh)
        num, dq = _num_and_dq(L)
        if num <= 0:
            return 1e30, np.zeros_like(x)
        M = L.max()
        e = np.exp(beta * (L - M))
        Z = e.sum()
        lse = M + np.log(Z) / beta
        val = -np.log(num) + 2.0 * np.log(s) + lse
        w = e / Z
        gL = -dq / num + w
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[mask] * hh[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = np.zeros(n)
        out[mask] = np.exp(np.clip(res.x, -50, 50))
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _window_polish_peak(h, frac, extra, maxiter, deadline, beta=None):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    L = _knots(h)
    k = int(np.argmax(L))
    half = max(2, int(frac * n))
    lo = max(0, (k - half) // 2 - extra)
    hi = min(n, (k + half) // 2 + extra + 1)
    if hi - lo < 2:
        return h
    sub = h[lo:hi].copy()
    m = sub.size
    x0 = np.log(np.maximum(sub, 1e-12))
    mask = sub > 1e-13 * sub.max()
    if mask.sum() < 2:
        mask = np.ones(m, dtype=bool)

    def fun(x):
        hh = h.copy()
        s2 = np.zeros(m)
        s2[mask] = np.exp(np.clip(x, -50, 50))
        hh[lo:hi] = s2
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        Lp = _knots(hh)
        num, dq = _num_and_dq(Lp)
        mm = Lp.max()
        if mm <= 0 or num <= 0:
            return 1e30, np.zeros_like(x)
        if beta is None:
            val = -np.log(num) + 2.0 * np.log(s) + np.log(mm)
            gL = -dq / num
            kk = np.argmax(Lp)
            gL[kk] += 1.0 / mm
        else:
            e = np.exp(beta * (Lp - mm))
            Z = e.sum()
            lse = mm + np.log(Z) / beta
            val = -np.log(num) + 2.0 * np.log(s) + lse
            w = e / Z
            gL = -dq / num + w
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[lo:hi][mask] * s2[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = h.copy()
        s2 = np.zeros(m)
        s2[mask] = np.exp(np.clip(res.x, -50, 50))
        out[lo:hi] = s2
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _zero_smallest(h, q):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    k = int(q * n)
    if k <= 0 or k >= n:
        return h
    idx = np.argpartition(h, k - 1)[:k]
    h[idx] = 0.0
    s = h.sum()
    if s <= 0:
        return h
    return h


def _revive_zeros(h, factor=1e-3):
    h = np.asarray(h, dtype=float).copy()
    pos = h > 0
    if not np.any(pos):
        return h
    posmean = h[pos].mean()
    zeros = ~pos
    if np.any(zeros):
        h[zeros] = factor * posmean
    return h


def _polish_pipeline(h, deadline, time_left, it_log=1200, it_sm=250, it_pol=300):
    best = h
    bestR = _R_of(h)
    if time_left():
        c = _lbfgs_log(best, it_log, deadline)
        if _R_of(c) > bestR:
            best = c; bestR = _R_of(c)
    for beta in (100, 500, 2000):
        if not time_left():
            break
        c = _lbfgs_sm(best, beta, it_sm, deadline)
        rc = _R_of(c)
        if rc > bestR:
            best = c; bestR = rc
    for f in (0.05, 0.10, 0.20):
        if not time_left():
            break
        c = _window_polish_peak(best, f, 8, it_pol, deadline)
        rc = _R_of(c)
        if rc > bestR:
            best = c; bestR = rc
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.975

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = _R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = _R_of(best)

    base = best.copy()
    baseR = bestR

    def try_accept(cand):
        nonlocal best, bestR
        rc = _R_of(cand)
        if rc > bestR:
            bestR = rc
            best = cand.copy()
            return True
        return False

    # --- EXPERIMENT: adaptive resample p0186 (N=8001) to N=64000, then fine polish ---
    experiment_best = None
    experiment_bestR = -1.0

    N = 64000
    if time_left():
        h = _adaptive_resample(base, N)
        if h.sum() > 0 and np.all(np.isfinite(h)):
            # exact log-LBFGS 1500
            if time_left():
                c = _lbfgs_log(h, 1500, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            # softmax betas 200/1000/5000/20000, 300 iters each
            for beta in (200, 1000, 5000, 20000):
                if not time_left():
                    break
                c = _lbfgs_sm(h, beta, 300, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            # exact log-LBFGS 1000
            if time_left():
                c = _lbfgs_log(h, 1000, deadline)
                if _R_of(c) > _R_of(h):
