    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    width = max(3, N // 300)

    # ---- Step 1: fine-grained local polish on the best (start) solution.
    # Many short, cheap full-mesh polish passes with small perturbation
    # resets, alternating with peak-window polishing, to squeeze out the
    # tiny gains the previous program was leaving on the table.
    cur = best
    curR = bestR

