    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _interp_shift(h_small, N_big, shift):
    """Prolongate to N_big with a fractional index shift (resampling)."""
    n = h_small.size
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1) + shift / N_big
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _dither_restart(h, rng, scale=0.02):
    """Small multiplicative perturbation for escaping local optima."""
    n = h.size
    noise = np.exp(rng.normal(0.0, scale, n))
    return h * noise


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0

    def _try(h, tag, record_alt=False):
        nonlocal best, bestR, alt, altR
        if h is None:
            return -1.0
        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
            print("%s R=%.7f" % (tag, r))
        elif record_alt and r > altR:
            alt, altR = h.copy(), r
        return r

    N0 = start_best.size
    N1 = min(1000000, 2 * N0)

    cur = _prolongate(start_best, N1)
    cur = _rescale(cur)
    r = R_of(cur)
    print("prolongate N=%d R=%.7f" % (N1, r))
    if r > bestR + 1e-12:
        best, bestR = cur.copy(), r
        cur = best.copy()
    else:
        cur = start_best.copy()

    # Stage 1: log-space L-BFGS on current size
    if time.process_time() < deadline - 20.0:
        h = _lbfgs_log(cur, 1500, deadline)
        _try(h, "log1500")
        if R_of(h) > R_of(cur):
            cur = h

    # Stage 2: beta-softmax continuation (smooth -> sharp)
    for beta in (20.0, 50.0, 120.0, 300.0):
        if time.process_time() >= deadline - 15.0:
            break
        h = _lbfgs_log(cur, 400, deadline, beta=beta)
        _try(h, "beta%.0f" % beta)
        if h is not None and R_of(h) > R_of(cur) - 0.002:
            cur = h

    # Stage 3: narrow peak-window fine polish at multiple scales
    for frac, extra in ((0.005, 16), (0.01, 24), (0.02, 32),
                        (0.04, 48), (0.08, 64), (0.15, 96)):
        if time.process_time() >= deadline - 12.0:
            break
        h = _window_polish_peak(cur, deadline, frac, extra, maxiter=250)
        _try(h, "win%.3f" % frac)
        if h is not None and R_of(h) > R_of(cur) - 0.001:
            cur = h

    # Stage 4: exact log polish
    if time.process_time() < deadline - 8.0:
        h = _lbfgs_log(cur, 800, deadline)
        _try(h, "log800")
        if h is not None and R_of(h) > R_of(cur) - 0.001:
            cur = h

    # Stage 5: NEW - sub-pixel shift resampling at higher resolution.
    # Try shifting the current construction by fractional steps when
    # prolongating, to break the alignment of the peak with the grid.
    if time.process_time() < deadline - 5.0 and N1 < 1000000:
        N2 = min(1000000, int(N1 * 1.5))
        for shift in (0.25, 0.5, 0.75):
            if time.process_time() >= deadline - 4.0:
                break
            h2 = _interp_shift(best, N2, shift)
            h2 = _rescale(h2)
            # short re-optimisation
            h2 = _lbfgs_log(h2, 600, deadline)
            _try(h2, "shift%.2f" % shift, record_alt=True)

    # Stage 6: dithered restarts from best, short log-L-BFGS
    rng = np.random.default_rng(12345)
    tries = 0
    while time.process_time() < deadline - 1.5 and tries < 8:
        tries += 1
        h0 = _dither_restart(best, rng, scale=0.015)
        h0 = _rescale(h0)
        h = _lbfgs_log(h0, 400, deadline)
        _try(h, "dither%d" % tries, record_alt=True)

    # Final continuous polish of best until deadline
    while time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 400, deadline)
        if h is None:
            break
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final-polish R=%.7f" % bestR)
        else:
            # try a small window polish as a last resort
            h2 = _window_polish_peak(best, deadline, 0.03, 32, maxiter=200)
            if h2 is not None:
                r2 = R_of(h2)
                if r2 > bestR + 1e-13:
                    best, bestR = h2, r2
                    print("final-win R=%.7f" % bestR)
                    continue
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if alt is not None and altR > start_bestR - 1e-6:
        return {"best": start_best, "alternative": alt}
    return {"best": start_best, "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _revive_far_tails(h, frac=0.12, level=1e-3, win=256):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    if n < 4:
        return h
    pos = h > 0
    if not pos.any():
        return h
    k = max(1, min(win, n))
    kernel = np.ones(k) / k
    posf = pos.astype(float)
    num = np.convolve(h, kernel, mode='same')
    den = np.convolve(posf, kernel, mode='same')
    local_mean = np.where(den > 1e-12, num / np.maximum(den, 1e-12), 0.0)
    gmean = h[pos].mean()
    local_mean = np.where(local_mean > 0, local_mean, gmean)
    fill = level * local_mean
    lo_end = int(frac * n)
    hi_start = int((1.0 - frac) * n)
    mask = np.zeros(n, dtype=bool)
    mask[:lo_end] = True
    mask[hi_start:] = True
    revive = mask & (~pos)
    h[revive] = fill[revive]
    return h


def _downsample(h, N2):
    n = h.size
    if n == N2:
        return h.copy()
    idx = (np.arange(N2 + 1) * (n / N2)).astype(int)
    idx = np.clip(idx, 0, n)
    out = np.empty(N2)
    for i in range(N2):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            out[i] = h[min(a, n - 1)]
        else:
            out[i] = h[a:b].mean()
    return out


def _upsample(h, N2):
    """Piecewise-constant upsample preserving the step function."""
    n = h.size
    if n == N2:
        return h.copy()
    idx = (np.arange(N2) * (n / N2)).astype(int)
    idx = np.clip(idx, 0, n - 1)
    return h[idx]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = _revive_far_tails(best, frac=0.12, level=1e-3, win=256)
    cur = _rescale(cur)
    r = R_of(cur)
    if r > bestR + 1e-12:
        best, bestR = cur.copy(), r

    if time.process_time() < deadline - 8.0:
        h = _lbfgs_log(cur, 600, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur

    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 32,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
            cur = hp if rp > bestR - 0.003 else cur

    # NEW: multi-resolution polish. Downsample, polish coarse, upsample back,
    # then polish fine. Coarse problems are less ill-conditioned and can
    # escape the fine-scale local minimum the current best is stuck in.
    n0 = best.size
    if n0 >= 4096 and time.process_time() < deadline - 6.0:
        for factor in (2, 4):
            if time.process_time() >= deadline - 4.0:
                break
            Nc = max(1024, n0 // factor)
            hc = _downsample(best, Nc)
            hc = _rescale(hc)
            rc = R_of(hc)
            hc2 = _lbfgs_log(hc, 400, deadline)
            rc2 = R_of(hc2)
            if rc2 > rc + 1e-10:
                hf = _upsample(hc2, n0)
                hf = _rescale(hf)
                # smooth the upsampled blocky result slightly
                k = max(1, factor)
                kern = np.ones(k) / k
                hsm = np.convolve(hf, kern, mode='same')
                hsm = _rescale(hsm)
                # fine polish
                hf2 = _lbfgs_log(hsm, 300, deadline)
                rf = R_of(hf2)
                print("  multires f=%d R=%.7f" % (factor, rf))
                if rf > bestR + 1e-12:
                    best, bestR = hf2, rf

    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.02, 0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

