    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 4000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 4000:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, m):
    """Mass-preserving cumulative-mass prolongation to m steps."""
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _adaptive_betas(h):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return (200.0, 2000.0)
    d = M - Lf
    d = d[d >= 0]
    if d.size == 0:
        return (200.0, 2000.0)
    d1 = np.quantile(d, 0.01)
    d5 = np.quantile(d, 0.05)
    d20 = np.quantile(d, 0.20)
    betas = []
    for dd in (d1, d5, d20):
        if dd > 1e-15:
            betas.append(min(1e6, 2.0 / dd))
    betas.extend([200.0, 2000.0])
    # dedupe, sort ascending
    betas = sorted(set(round(b, 6) for b in betas))
    return tuple(betas)


def _near_max_share(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _polish_cycle(h, rcur, deadline, fracs, maxiter_log=400,
                  maxiter_sm=200, maxiter_blk=400):
    # (a) exact log-space
    if time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(h, maxiter=maxiter_log, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    # (b) adaptive softmax
    betas = _adaptive_betas(h)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_sm(h, beta, maxiter=maxiter_sm, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    # (c) peak-window block polish
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter_blk, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is None:
        # fall back to a smooth bump ladder (should not happen in this line)
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        h = _rescale(h)
        cur_r = R_of(h)
        betas = (8, 32, 128, 512, 2048)
        N = N0
        while N <= 65536:
            if time.process_time() >= deadline - 6.0:
                break
            cand = _lbfgs_log(h, maxiter=400, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                h, cur_r = cand, r
            for beta in betas:
                if time.process_time() >= deadline - 1.0:
                    break
                cand = _lbfgs_sm(h, beta, maxiter=200, deadline=deadline)
                r = R_of(cand)
                if r > cur_r:
                    h, cur_r = cand, r
            if N >= 65536:
                break
            N = min(N * 2, 65536)
            h = _rescale(_prolong(h, N))
            cur_r = R_of(h)
        return h

    # Main path: prolongate the start and polish at increasing N.
    best = start_arr.copy()
    best_r = start_r
    print("start R=%.6f N=%d" % (best_r, best.size))

    # Build the ladder of target sizes from the start size.
    n0 = start_arr.size
    targets = []
    N = n0
    while N < 262144:
        N = N * 2
        targets.append(N)

    cur = start_arr.copy()
    cur_r = start_r
    for N in targets:
        if time.process_time() >= deadline - 3.0:
            break
        cur = _rescale(_prolong(cur, N))
        cur_r = R_of(cur)
        print("  prolong N=%d R=%.6f" % (N, cur_r))
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        # polish cycles at this level
        first_gain = None
        cyc = 0
        while time.process_time() < deadline - 1.5:
            prev_r = cur_r
            cur, cur_r = _polish_cycle(
                cur, cur_r, deadline,
                fracs=(0.10, 0.05, 0.02, 0.01),
                maxiter_log=400, maxiter_sm=200, maxiter_blk=400)
            cyc += 1
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
            gain = cur_r - prev_r
            if first_gain is None:
                first_gain = cur_r - R_of(_rescale(_prolong(start_arr, N))) \
                    if N > start_arr.size else 0.0
            print("    N=%d cyc=%d R=%.6f gain=%.2e share0.1%%=%.3f share1%%=%.3f"
                  % (N, cyc, cur_r, gain,
                     _near_max_share(cur, 0.001),
                     _near_max_share(cur, 0.01)))
            if gain < 1e-9:
                break
        # if the first 131072 cycle gave < +0.0005, the grid isn't binding;
        # still continue to larger N since it may help anyway.
        if N >= 131072 and first_gain is not None and first_gain < 5e-4:
            print("    (small first gain %.2e at N=%d)" % (first_gain, N))

    print("best R=%.6f (start %.6f) N=%d" % (best_r, start_r, best.size))

    if start_arr is not None and start_r >= best_r:
        return {"best": _rescale(start_arr), "alternative": _rescale(best)}
    if start_arr is not None:
        return {"best": _rescale(best), "alternative": _rescale(start_arr)}
    return _rescale(best)

