def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _fresh(deadline):
    N0 = 64
    x = np.linspace(0, 1, N0)
    h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
    h = _rescale(h)
    cur_r = R_of(h)
    betas = (8, 32, 128, 512, 2048)
    N = N0
    while N <= 65536:
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs_log(h, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            h, cur_r = cand, r
        cand, r = _homotopy(h, betas, 200, deadline)
        if r > cur_r:
            h, cur_r = cand, r
        if N >= 65536:
            break
        N = min(N * 2, 65536)
        h = _rescale(_prolong(h, N))
        cur_r = R_of(h)
    return h, cur_r


def _coarsen(h, k):
    n = h.size
    if n % k != 0:
        return None
    return h.reshape(n // k, k).sum(axis=1)


def _sharpen(h, deadline, rcur):
    cand = _lbfgs_log(h, maxiter=600, deadline=deadline)
    r = R_of(cand)
    if r > rcur:
        return cand, r
    return h, rcur


def _perturb_restart(h, rcur, deadline, rng, scales=(0.03, 0.08, 0.15)):
    n = h.size
    best_h, best_r = h, rcur
    for sc in scales:
        if time.process_time() >= deadline - 1.0:
            break
        active = np.flatnonzero(h > 1e-12 * h.max())
        if active.size == 0:
            break
        noise = np.exp(rng.normal(0.0, sc, size=active.size))
        hh = h.copy()
        hh[active] = hh[active] * noise
        hh = _rescale(hh)
        cand = _lbfgs_log(hh, maxiter=250, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best_h, best_r = cand, r
    return best_h, best_r


def _peak_rescale(h):
    """Normalize so the peak knot equals 1 (cheap, doesn't change R)."""
    mx = _knots(h).max()
    if mx > 0:
        return h / np.sqrt(mx)
    return h


def _multi_start_coarsen(best, best_r, deadline, rng):
    """Coarsen to multiple levels and refine each, taking the best.

    Key idea: the coarse (block-summed) grid smooths the objective and often
    converges to a different, better basin than the fine grid. We try several
    coarsening factors and re-detail the winner.
    """
    n = best.size
    best_h, best_r_out = best, best_r
    for k in (2, 4, 8):
        if time.process_time() >= deadline - 3.0:
            break
        if n % k != 0:
            continue
        hc = _coarsen(best, k)
        if hc is None:
            continue
        rc = R_of(hc)
        sub_deadline = min(deadline, time.process_time() +
                           0.20 * (deadline - time.process_time()))
        # coarsened objective often has different local optima: perturb slightly
        for attempt in range(2):
            if time.process_time() >= sub_deadline - 2.0:
                break
            hstart = hc.copy()
            if attempt == 1:
                active = np.flatnonzero(hstart > 1e-12 * hstart.max())
                if active.size:
                    hstart[active] *= np.exp(rng.normal(0, 0.02, active.size))
                hstart = _rescale(hstart)
            cc = _lbfgs_log(hstart, maxiter=500, deadline=sub_deadline)
            cc, cr = _homotopy(cc, (256, 1024, 4096, 16000), 200, sub_deadline)
            cc, cr = _polish(cc, sub_deadline, cr,
                             fracs=(0.30, 0.12, 0.05), maxiter=350)
            # re-detail
            fine = np.repeat(cc, k) / float(k)
            rc_fine = R_of(fine)
            # exact polish on the fine grid, but only briefly
            fine2 = _lbfgs_log(fine, maxiter=300, deadline=sub_deadline)
            rf2 = R_of(fine2)
            if rf2 > best_r_out:
                best_h, best_r_out = fine2, rf2
            elif rc_fine > best_r_out:
                best_h, best_r_out = fine, rc_fine
    return best_h, best_r_out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(12345)

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        best, best_r = _fresh(deadline)
        start_r = best_r

    if best.size < 65536:
        best = _rescale(_prolong(best, 65536))
        best_r = R_of(best)
        print("prolonged start to 65536: R=%.6f" % best_r)

    # ---- Step 1: multi-level coarsening search (new) ----
    cand, r = _multi_start_coarsen(best, best_r, deadline, rng)
    if r > best_r:
        best, best_r = cand, r
    print("after multi-coarsen R=%.6f" % best_r)

    # ---- Step 2: exact polish + very high-beta homotopy on fine grid ----
    cand = _lbfgs_log(best, maxiter=600, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r
    print("after log polish R=%.6f" % best_r)

    hi_betas = (2000, 6000, 20000, 60000, 150000)
    cand, r = _homotopy(best, hi_betas, 300, deadline)
    if r > best_r:
        best, best_r = cand, r
    print("after hi-beta homotopy R=%.6f" % best_r)

    # ---- Step 3: alternating polish / homotopy / perturb until deadline ----
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
