    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs(cur, maxiter=maxiter, deadline=deadline, mode='sm', beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _polish(h, deadline, rcur, fracs, maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac) + 1)
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs(h, maxiter=maxiter, deadline=deadline, mode='block', free=free)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _fresh(deadline, Ntarget):
    N0 = 64
    x = np.linspace(0, 1, N0)
    h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
    h = _rescale(h)
    cur_r = R_of(h)
    betas = (8, 32, 128, 512, 2048)
    N = N0
    while N <= Ntarget:
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs(h, maxiter=400, deadline=deadline, mode='log')
        r = R_of(cand)
        if r > cur_r:
            h, cur_r = cand, r
        cand, r = _homotopy(h, betas, 200, deadline)
        if r > cur_r:
            h, cur_r = cand, r
        if N >= Ntarget:
            break
        N = min(N * 2, Ntarget)
        h = _rescale(_prolong(h, N))
        cur_r = R_of(h)
    return h, cur_r


def _coarsen(h, k):
    n = h.size
    if n % k != 0:
        return None
    return h.reshape(n // k, k).sum(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        best, best_r = _fresh(deadline, 65536)
        start_r = best_r

    Ntarget = 65536
    if best.size < Ntarget:
        best = _rescale(_prolong(best, Ntarget))
        best_r = R_of(best)
        print("prolonged start to %d: R=%.6f" % (Ntarget, best_r))

    alt_best = None
    alt_r = -1.0

    # ---- coarsen by 4 and optimise heavily ----
    if best.size % 4 == 0:
        hc = _coarsen(best, 4)
        if hc is not None:
            rc = R_of(hc)
            if abs(rc - best_r) < 1e-7:
                cd = min(deadline, time.process_time() + 0.45 * (deadline - time.process_time()))
                cc, cr = _lbfgs(hc, maxiter=800, deadline=cd, mode='log')
                cc, cr = _homotopy(cc, (64, 256, 1024, 4096), 300, cd)
                cc, cr = _polish(cc, cd, cr,
                                 fracs=(0.30, 0.15, 0.07, 0.03, 0.015, 0.007), maxiter=500)
                # re-detail
                fine = np.repeat(cc, 4) / 4.0
                fine_r = R_of(fine)
                print("coarse R=%.9f -> fine R=%.9f" % (cr, fine_r))
                if fine_r > best_r:
                    best, best_r = fine, fine_r
                else:
                    alt_best, alt_r = fine, fine_r

    # ---- main loop: alternate homotopy/log/block polish ----
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        cand, r = _homotopy(best, (400, 1024, 2048, 4096, 8000, 16000), 300, deadline)
        if r > best_r:
            best, best_r = cand, r
        cand = _lbfgs(best, maxiter=400, deadline=deadline, mode='log')
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
        cand, r = _polish(best, deadline, best_r,
                          fracs=(0.30, 0.15, 0.07, 0.03, 0.015, 0.007), maxiter=500)
        if r > best_r:
            best, best_r = cand, r
        print("  alt#%d R=%.9f" % (it, best_r))

    print("best R=%.9f (start %.9f)" % (best_r, start_r))
    best = _rescale(best)

    if start_arr is not None and start_r >= best_r:
        if alt_best is not None and alt_r > best_r:
            return {"best": start_arr, "alternative": alt_best}
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 4000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 4000:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _fun_grad_plateau(h):
    """J = log(num) - 2 log(s) - log(0.5*max(L) + 0.5*mean(top-K L))."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    K = max(8, int(0.01 * n))
    K = min(K, n)
    # top-K indices
    idx = np.argpartition(Lf, n - K)[n - K:]
    m = int(np.argmax(Lf))
    top_mean = Lf[idx].mean()
    Lm = Lf[m]
    blend = 0.5 * Lm + 0.5 * top_mean
    if blend <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    # d/d blend of -log(blend) = -1/blend
    coef = -1.0 / blend
    gLf[m] += coef * 0.5
    gLf[idx] += coef * 0.5 / K
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(blend)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_plateau(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_plateau(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _plateau_cycle(h, r, deadline, tag):
    """One cycle: plateau surrogate LBFGS, then true-R LBFGS, then polish."""
    cand = _lbfgs_plateau(h, maxiter=800, deadline=deadline)
    r2 = R_of(cand)
    if r2 > r:
        h, r = cand, r2
    cand = _lbfgs_log(h, maxiter=400, deadline=deadline)
    r2 = R_of(cand)
    if r2 > r:
        h, r = cand, r2
    cand, r2 = _polish(h, deadline, r, fracs=(0.02, 0.05, 0.10, 0.20), maxiter=400)
    if r2 > r:
        h, r = cand, r2
    print("  %s R=%.6f" % (tag, r))
    return h, r


def _refine_line(h, r, deadline, tag):
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r,
                           fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if r2 > r:
            h, r = cand, r2
        cand = _lbfgs_sm(h, 4096, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        print("  %s R=%.6f" % (tag, r))
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    half = t0 + 0.5 * (budget_seconds - 2.0)

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0
    alt = None
    alt_r = -1.0

    if start_arr is not None:
        cur = start_arr
        if cur.size < 65536:
            cur = _rescale(_prolong(cur, 65536))
        cur_r = R_of(cur)
        print("start base R=%.6f N=%d" % (cur_r, cur.size))

        # First half: plateau cycles at N=65536
        while time.process_time() < half - 1.0:
            cur, cur_r = _plateau_cycle(cur, cur_r, deadline, "plateau")
        best, best_r = cur, cur_r

        # Second half: try 2x split to N=131072, then plateau cycles there
        if time.process_time() < deadline - 6.0:
            hi = _rescale(_prolong(cur, 131072))
            hi_r = R_of(hi)
            print("  split N=%d R=%.6f" % (hi.size, hi_r))
            while time.process_time() < deadline - 1.5:
                hi, hi_r = _plateau_cycle(hi, hi_r, deadline, "split")
            if hi_r > best_r:
                alt, alt_r = hi, hi_r
            else:
                alt, alt_r = hi, hi_r

        # If time remains, continue refining best
        if time.process_time() < deadline - 1.5:
            best, best_r = _refine_line(best, best_r, deadline, "final")

    if best is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None and start_r >= best_r:
        if alt is not None and alt_r > 0 and not np.array_equal(alt, start_arr):
            return {"best": _rescale(start_arr), "alternative": _rescale(alt)}
        return _rescale(start_arr)

    if start_arr is not None:
        return {"best": _rescale(best), "alternative": _rescale(start_arr)}
    return _rescale(best)

