def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _refine_line(h, r, deadline, tag, rounds=1000):
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r,
                           fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if r2 > r:
            h, r = cand, r2
        cand = _lbfgs_sm(h, 4096, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        print("  %s R=%.6f" % (tag, r))
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0
    alt = None
    alt_r = -1.0

    if start_arr is not None:
        # NEW CORE IDEA: the earlier ladder wasted time refining each rung.
        # Here we instead exploit the *local* structure of the optimum: the
        # autoconvolution peak is sharp, and the only meaningful degrees of
        # freedom are (a) the global log-refine, (b) a fine local polish of
        # the peak region, and (c) a short smoothing pass.  We run that tight
        # triple loop on the given start at its own resolution, then do a
        # *single* well-chosen prolongation (to ~2x and ~4x) and repeat.
        base = start_arr.copy()
        base_r = start_r
        print("start base R=%.6f N=%d" % (base_r, base.size))

        # Tight local loop at current resolution
        for it in range(40):
            if time.process_time() >= deadline - 3.0:
                break
            prev = base_r
            c = _lbfgs_log(base, maxiter=400, deadline=deadline)
            rc = R_of(c)
            if rc > base_r:
                base, base_r = c, rc
            base, base_r = _polish(base, deadline, base_r,
                                   fracs=(0.30, 0.15, 0.07, 0.03, 0.015),
                                   maxiter=500)
            c = _lbfgs_sm(base, 4096, maxiter=300, deadline=deadline)
            rc = R_of(c)
            if rc > base_r:
                base, base_r = c, rc
            if base_r <= prev + 1e-12:
                break
            print("  local R=%.6f" % base_r)

        if base_r > best_r:
            best, best_r = base.copy(), base_r

        # Prolongation ladder of a couple of rungs, each with a short local loop
        n0 = base.size
        for mult in (2, 4):
            if time.process_time() >= deadline - 3.0:
                break
            m = min(n0 * mult, 1000000)
            if m <= base.size:
                continue
            base = _rescale(_prolong(base, m))
            base_r = R_of(base)
            for it in range(20):
                if time.process_time() >= deadline - 2.5:
                    break
                prev = base_r
                c = _lbfgs_log(base, maxiter=300, deadline=deadline)
                rc = R_of(c)
                if rc > base_r:
                    base, base_r = c, rc
                base, base_r = _polish(base, deadline, base_r,
                                       fracs=(0.20, 0.10, 0.05, 0.02),
                                       maxiter=400)
                if base_r <= prev + 1e-12:
                    break
            print("  ladder N=%d R=%.6f" % (base.size, base_r))
            if base_r > best_r:
                best, best_r = base.copy(), base_r

        # Final squeeze
        base, base_r = _refine_line(base, base_r, deadline, "final")
        if base_r > best_r:
            best, best_r = base, base_r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

    if best is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    best = _rescale(best)
    if start_arr is not None:
        if start_r >= best_r:
            alt = best if not np.array_equal(best, start_arr) else None
            if alt is not None:
                return {"best": _rescale(start_arr), "alternative": alt}
            return _rescale(start_arr)
        return {"best": best, "alternative": _rescale(start_arr)}
    return best

