        print("  %s R=%.6f" % (tag, r))
    return h, r


def _make_seed(rng, N, nblocks, zero_frac):
    h = np.zeros(N)
    widths = np.exp(rng.uniform(np.log(1.0), np.log(N / 8.0), size=nblocks))
    widths = np.maximum(widths, 1.0)
    total = widths.sum()
    widths = widths * (N / total)
    widths = np.maximum(np.round(widths).astype(int), 1)
    # adjust to fit
    while widths.sum() > N:
        i = int(np.argmax(widths))
        if widths[i] > 1:
            widths[i] -= 1
        else:
            break
    starts = rng.integers(0, max(1, N - widths.sum() + 1), size=nblocks)
    heights = np.exp(rng.normal(0.0, 1.5, size=nblocks))
    pos = 0
    # place blocks sequentially with random gaps
    idx = 0
    for b in range(nblocks):
        w = widths[b]
        if idx + w > N:
            w = N - idx
        if w <= 0:
            break
        h[idx:idx + w] = heights[b]
        idx += w
        gap = int(rng.integers(0, max(1, (N - idx) // max(1, nblocks - b))))
        idx += gap
        if idx >= N:
            break
    # zero lowest fraction of nonzero heights
    nz = np.flatnonzero(h > 0)
    if nz.size > 0:
        k = int(zero_frac * nz.size)
        order = nz[np.argsort(h[nz])]
        h[order[:k]] = 0.0
    mx = h.max()
    if mx > 0:
        h[h > 0] = np.maximum(h[h > 0], 1e-3 * mx)
    s = h.sum()
    if s > 0:
        h = h / s
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    # ---- Fresh zero-rich multiscale search ----
    N = 4096
    nseeds = 30
    seed_results = []
    if time.process_time() < deadline - 20.0:
        for si in range(nseeds):
            if time.process_time() >= deadline - 18.0:
                break
            rng = np.random.default_rng(12345 + si)
            nblocks = int(rng.integers(16, 33))
            zero_frac = 0.45 if si % 2 == 0 else 0.60
            h = _make_seed(rng, N, nblocks, zero_frac)
            h = _rescale(h)
            r = R_of(h)
            # exact non-log L-BFGS-B
            c = _lbfgs_exact(h, maxiter=200, deadline=deadline - 15.0)
            rc = R_of(c)
            if rc > r:
                h, r = c, rc
            # 2 rounds peak polish
            for _ in range(2):
                if time.process_time() >= deadline - 15.0:
                    break
                c, rc = _polish(h, deadline - 15.0, r,
                                fracs=(0.30, 0.15, 0.07), maxiter=300)
                if rc > r:
                    h, r = c, rc
            seed_results.append((r, h.copy()))
            nz = np.count_nonzero(h)
            mm = h.max() / (h.mean() + 1e-30)
            print("  seed %d R=%.6f zeros=%.1f%% max/mean=%.1f"
                  % (si, r, 100.0 * (1 - nz / h.size), mm))

    if seed_results:
        seed_results.sort(key=lambda t: -t[0])
        top = seed_results[:4]
        rungs = [16384, 65536, 262144]
        for ti, (sr, sh) in enumerate(top):
            if time.process_time() >= deadline - 4.0:
                break
            cur = sh
            cur_r = sr
            best_local = (cur_r, cur.copy())
            for m in rungs:
                if time.process_time() >= deadline - 4.0:
                    break
                cur = _rescale(_prolong(cur, m))
                cur_r = R_of(cur)
                c = _lbfgs_log(cur, maxiter=300, deadline=deadline - 3.0)
                rc = R_of(c)
                if rc > cur_r:
                    cur, cur_r = c, rc
                c, rc = _polish(cur, deadline - 3.0, cur_r,
                                fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400)
                if rc > cur_r:
                    cur, cur_r = c, rc
                if cur_r > best_local[0]:
                    best_local = (cur_r, cur.copy())
                print("  top%d rung N=%d R=%.6f" % (ti, m, cur_r))
            if best_local[0] > best_r:
                best, best_r = best_local[1], best_local[0]

    # ---- p0266 fallback (start refinement) ----
    if start_arr is not None:
        base = start_arr
        base_r = start_r
        print("start base R=%.6f N=%d" % (base_r, base.size))

        n0 = base.size
        schedule = []
        m = n0
        while m <= 1000000:
            schedule.append(m)
            if m == 1000000:
                break
            m = min(m * 2, 1000000)
        if len(schedule) < 3:
            schedule = sorted(set([n0, min(2 * n0, 1000000),
                                   min(4 * n0, 1000000)]))

        all_candidates = [(base_r, base.copy())]
        for m in schedule:
            if time.process_time() >= deadline - 3.0:
                break
            if m != base.size:
                base = _rescale(_prolong(base, m))
            base_r = R_of(base)
            for _ in range(2):
                if time.process_time() >= deadline - 2.5:
                    break
                c = _lbfgs_log(base, maxiter=300, deadline=deadline)
                rc = R_of(c)
                if rc > base_r:
                    base, base_r = c, rc
                base, base_r = _polish(base, deadline, base_r,
                                       fracs=(0.30, 0.15, 0.07, 0.03, 0.015),
                                       maxiter=400)
            all_candidates.append((base_r, base.copy()))
            print("  ladder N=%d R=%.6f" % (m, base_r))

        for r, c in all_candidates:
            if r > best_r:
                best, best_r = c, r
        base, base_r = best if best is not None else base, best_r if best_r > 0 else base_r

        base, base_r = _refine_line(base, base_r, deadline, "start-refine")
        if base_r > best_r:
            best, best_r = base, base_r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

    if best is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    best = _rescale(best)
    if start_arr is not None:
        if start_r >= best_r:
            alt = best if not np.array_equal(best, start_arr) else None
            if alt is not None:
                return {"best": _rescale(start_arr), "alternative": alt}
            return _rescale(start_arr)
        return {"best": best, "alternative": _rescale(start_arr)}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 4000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 4000:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _fun_grad_plateau(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    K = max(8, int(0.01 * n))
    K = min(K, n)
    idx = np.argpartition(Lf, n - K)[n - K:]
    m = int(np.argmax(Lf))
    top_mean = Lf[idx].mean()
    Lm = Lf[m]
    blend = 0.5 * Lm + 0.5 * top_mean
    if blend <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    coef = -1.0 / blend
    gLf[m] += coef * 0.5
    gLf[idx] += coef * 0.5 / K
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(blend)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_plateau(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_plateau(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _restrict(h, m):
    """Coarsen to m steps by binning (mass-preserving)."""
    n = h.size
    if m >= n:
        return _prolong(h, m)
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _plateau_cycle(h, r, deadline, tag):
    cand = _lbfgs_plateau(h, maxiter=800, deadline=deadline)
    r2 = R_of(cand)
    if r2 > r:
        h, r = cand, r2
    cand = _lbfgs_log(h, maxiter=400, deadline=deadline)
    r2 = R_of(cand)
    if r2 > r:
        h, r = cand, r2
    cand, r2 = _polish(h, deadline, r, fracs=(0.02, 0.05, 0.10, 0.20), maxiter=400)
    if r2 > r:
        h, r = cand, r2
    print("  %s R=%.6f N=%d" % (tag, r, h.size))
    return h, r


def _refine_line(h, r, deadline, tag):
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r,
                           fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if r2 > r:
            h, r = cand, r2
        cand = _lbfgs_sm(h, 4096, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        print("  %s R=%.6f N=%d" % (tag, r, h.size))
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    half = t0 + 0.5 * (budget_seconds - 2.0)

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0
    alt = None
    alt_r = -1.0

    if start_arr is not None:
        cur = start_arr
        cur_r = R_of(cur)
        print("start base R=%.6f N=%d" % (cur_r, cur.size))

        # Phase 1: plateau cycles at current N (build a good base).
        while time.process_time() < half - 1.0:
            cur, cur_r = _plateau_cycle(cur, cur_r, deadline, "base")
        best, best_r = cur, cur_r

        # Phase 2: try a *doubled* resolution branch, keeping whichever wins.
        if time.process_time() < deadline - 6.0:
            hi = _rescale(_prolong(cur, 2 * cur.size))
            hi_r = R_of(hi)
            print("  split N=%d R=%.6f" % (hi.size, hi_r))
            # A few plateau cycles at high N to see if it beats base.
            while time.process_time() < deadline - 1.5:
                hi, hi_r = _plateau_cycle(hi, hi_r, deadline, "split")
            alt, alt_r = hi, hi_r

            # Also try coarsening back: sometimes a coarser representation
            # escapes a local optimum and re-refines better.
            if time.process_time() < deadline - 1.5 and best.size > 1024:
                lo = _rescale(_restrict(best, best.size // 2))
                lo_r = R_of(lo)
                print("  coarsen N=%d R=%.6f" % (lo.size, lo_r))
                while time.process_time() < deadline - 1.5:
                    lo, lo_r = _plateau_cycle(lo, lo_r, deadline, "coarse")
                if lo_r > alt_r:
                    alt, alt_r = lo, lo_r

        # Phase 3: final refinement on the winner.
        if time.process_time() < deadline - 1.5:
            if alt_r > best_r:
                best, best_r = alt, alt_r
            best, best_r = _refine_line(best, best_r, deadline, "final")
            if alt_r > best_r:
                best, best_r = alt, alt_r

    if best is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None and start_r >= best_r:
        if alt is not None and alt_r > 0 and not np.array_equal(alt, start_arr):
            return {"best": _rescale(start_arr), "alternative": _rescale(alt)}
        return _rescale(start_arr)

    if start_arr is not None:
        return {"best": _rescale(best), "alternative": _rescale(start_arr)}
    return _rescale(best)

import numpy as np
import time
