    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0
    alt = None
    alt_r = -1.0

    # ---- Phase 1: refine the start directly (main attack) ----
    if start_arr is not None:
        h = start_arr.copy()
        if h.size < 65536:
            h = _rescale(_prolong(h, 65536))
        r = R_of(h)
        print("start base R=%.6f N=%d" % (r, h.size))
        # Use nearly all budget on the start line -- this is where gains are.
        h, r = _refine_line(h, r, deadline - 3.0, "start-refine")
        if r > best_r:
            best, best_r = h, r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

    # ---- Phase 2: if time and start exists, try asymmetric perturbations ----
    if best is not None and time.process_time() < deadline - 6.0:
        base_h, base_r = best, best_r
        best_pert_h, best_pert_r = base_h, base_r
        for slope in (0.08, -0.08, 0.20, -0.20, 0.35, -0.35):
            if time.process_time() >= deadline - 4.0:
                break
            cand = _smooth_tilt(base_h, slope)
            cand, r2 = _refine_local(cand, R_of(cand), deadline - 1.0,
                                     "asym%.2f" % slope)
            if r2 > best_pert_r:
                best_pert_h, best_pert_r = cand, r2
        if best_pert_r > best_r:
            # Full refine of the winning perturbation.
            h, r = _refine_line(best_pert_h, best_pert_r, deadline - 1.5,
                                "asym-refine")
            if r > best_r:
                best, best_r = h, r
            print("asym improved R=%.6f" % best_r)
        else:
            # Small perturbation didn't help; if base is different from start,
            # still offer it as alternative.
            pass

    if best is None:
        # No start: build a fresh construction from scratch.
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        cur_r = R_of(h)
        betas = (8, 32, 128, 512, 2048)
        N = N0
        while N <= 65536 and time.process_time() < deadline - 3.0:
            cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
            rr = R_of(cand)
            if rr > cur_r:
                h, cur_r = cand, rr
            for beta in betas:
                if time.process_time() >= deadline - 2.0:
                    break
                cand = _lbfgs_sm(h, beta, maxiter=150, deadline=deadline)
                rr = R_of(cand)
                if rr > cur_r:
                    h, cur_r = cand, rr
            if N >= 65536:
                break
            N = min(N * 2, 65536)
            h = _rescale(_prolong(h, N))
            cur_r = R_of(h)
        h, cur_r = _refine_line(h, cur_r, deadline - 1.0, "fresh")
        best, best_r = h, cur_r
        print("fresh R=%.6f" % best_r)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    # Decide what to return.
    if start_arr is not None:
        if best_r > start_r + 1e-12:
            # Our improvement wins; start goes in as alternative.
            return {"best": _rescale(best), "alternative": _rescale(start_arr)}
        # Couldn't beat start; return start as best, keep our attempt as alt.
        if best is not None and not np.array_equal(best, start_arr) and best_r > 0:
            return {"best": _rescale(start_arr), "alternative": _rescale(best)}
        return _rescale(start_arr)

    return _rescale(best)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 3000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 3000:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _cb_factory(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, active_mask=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if active_mask is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.flatnonzero(active_mask)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _cb_factory(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _cb_factory(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _cb_factory(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _upsample(h, factor):
    """Linear interpolation upsample by factor; keeps shape."""
    n = h.size
    m = (n - 1) * factor + 1
    x_old = np.linspace(0, 1, n)
    x_new = np.linspace(0, 1, m)
    return np.interp(x_new, x_old, h)


def _best_so_far(h, best_h, best_r):
    r = R_of(h)
    if r > best_r:
        return h, r
    return best_h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    best_h = None
    best_r = -1.0

    if start is not None:
        s = np.clip(np.asarray(start, dtype=float), 0, None)
        if s.sum() > 0:
            best_h = s.copy()
            best_r = R_of(s)

    if best_h is None:
        best_h = np.ones(50)
        best_r = R_of(best_h)

    # Initial seed: a smooth bump shape known to be decent
    if best_r < 0.7:
        x = np.linspace(-1, 1, 200)
        cand = np.exp(-4.0 * x * x)
        r = R_of(cand)
        if r > best_r:
            best_h, best_r = cand, r

    print(f"start R={best_r:.6f} N={best_h.size}")

    # Main loop: refine at current resolution, then upsample and refine again.
    h = best_h.copy()
    res_plan = []
    n = h.size
    while n < 60000 and time.process_time() < deadline - 2.0:
        res_plan.append(n)
        n = int(n * 2)
    if not res_plan:
        res_plan = [h.size]

    # Run smoothing continuation at each resolution.
    for target_n in res_plan:
        if time.process_time() >= deadline - 1.0:
            break
        if h.size != target_n:
            h = _upsample(h, max(1, target_n // h.size))
        # smoothing continuation
        for beta in [2.0, 8.0, 32.0, 128.0, 512.0]:
            if time.process_time() >= deadline - 1.0:
                break
            h = _lbfgs_sm(h, beta, 200, deadline)
            h, best_r = _best_so_far(h, best_h, best_r)
        # hard max polish
        for _ in range(3):
            if time.process_time() >= deadline - 1.0:
                break
            h = _lbfgs_log(h, 300, deadline)
            h, best_r = _best_so_far(h, best_h, best_r)
        print(f"N={h.size} R={best_r:.6f} t={time.process_time()-t0:.1f}")

    # Final polish on the best found, with a bit more upsampling if budget allows.
    h = best_h.copy()
    while time.process_time() < deadline - 2.0 and h.size < 200000:
        h = _upsample(h, 2)
        h = _lbfgs_sm(h, 64.0, 150, deadline)
        h = _lbfgs_log(h, 200, deadline)
        h, best_r = _best_so_far(h, best_h, best_r)
        print(f"final N={h.size} R={best_r:.6f} t={time.process_time()-t0:.1f}")

    # Verify and ensure at least start is returned as best
    if best_h is None or R_of(best_h) <= 0:
        best_h = np.ones(50)
    best_r = R_of(best_h)

    # If start was better, keep it as best, and offer our new as alternative.
    alt = best_h
    alt_r = R_of(alt)
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float), 0, None)
        if s.sum() > 0:
            sr = R_of(s)
            if sr > alt_r:
                # our construction is worse than start: return start as best,
                # our different construction as alternative
                if s.shape == alt.shape and np.allclose(s, alt):
                    return s
                return {"best": s, "alternative": alt}
    print(f"final R={alt_r:.6f}, N={alt.size}")
    return alt
SUMMARY: Added smoothing-continuation multi-resolution refinement (upsample + L-BFGS-B on soft-max and hard-max objectives) so the search escapes local optima and refines until near the deadline; returns start as best with new construction as alternative if worse.

