        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
        else:
            alt, alt_r = cand, r
        print("upsampled to %d R=%.6f" % (best.size, best_r))

    # Main loop: softmax homotopy restarts + peak polish.
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        seed = best.copy()
        # Small random perturbation to escape the current basin.
        rng = np.random.default_rng(it * 7919)
        noise = 1.0 + 0.05 * rng.standard_normal(seed.size)
