        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _support_cycle(h, deadline, drop_frac=0.01, admit_frac=0.01):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    val, g = _fun_grad(h)
    n = h.size
    pos = np.flatnonzero(h > 0)
    zer = np.flatnonzero(h <= 0)
    h2 = h.copy()
    if pos.size > 0:
        kdrop = max(1, int(pos.size * drop_frac))
        order = pos[np.argsort(h[pos])]
        h2[order[:kdrop]] = 0.0
    if zer.size > 0:
        kadmit = max(1, int(zer.size * admit_frac))
        kadmit = min(kadmit, zer.size)
        gz = g[zer]
        order = zer[np.argsort(gz)]
        fill = 1e-3 * h.mean()
        h2[order[:kadmit]] = fill
    h2 = _rescale(h2)
    return _lbfgs_log(h2, 400, deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _refine_at_N(cur, curR, deadline, betas, extra_windows=True):
    """At fixed N: alternating full + peak-window polish with a schedule of
    smoothing betas to escape flat max-plateau geometry. Returns (h, R)."""
    best, bestR = cur, curR
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        h = _lbfgs_log(best, 600, deadline, beta=beta)
        h = _lbfgs_log(h, 600, deadline, beta=0.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if extra_windows and time.process_time() < deadline - 1.5:
            for frac, extra in ((0.15, 8), (0.30, 16), (0.50, 32)):
                if time.process_time() >= deadline - 1.0:
                    break
                hw = _window_polish_peak(best, deadline, frac, extra,
                                         maxiter=400, beta=beta)
                hw = _lbfgs_log(hw, 400, deadline, beta=0.0)
                rw = R_of(hw)
                if rw > bestR + 1e-15:
                    best, bestR = hw, rw
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: the max-plateau of f*f is broad, so the plain argmax gradient is
    # non-smooth and L-BFGS stalls. Use a *smooth* log-sum-exp surrogate of the
    # max (beta schedule) to escape stalls, then descend on the true objective.
    # Also: multiscale N cycling — coarsen & prolongate to change the sampling
    # of the peak plateau, which regularises the geometry.

    betas_full = [30.0, 80.0, 200.0, 500.0, 1200.0]

    # Phase 1: support working-set loop (keeps ability to change zeros).
    cycle = 0
    while time.process_time() < deadline - 6.0:
        cycle += 1
        h = _support_cycle(best, deadline)
        r = R_of(h)
        nz = int(np.sum(h <= 0))
        if r > bestR + 1e-15:
            best, bestR = h, r
        print("support: %d zeros, R=%.7f" % (nz, bestR))
        if cycle % 2 == 0:
            h = _lbfgs_log(best, 800, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
        if time.process_time() >= deadline - 6.0:
            break

    # Phase 2: beta-smoothed refinement at current N.
    if time.process_time() < deadline - 4.0:
        h, r = _refine_at_N(best, bestR, deadline, betas_full)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("beta-refine R=%.7f" % bestR)

    # Phase 3: multiscale N cycling — coarsen, refine, prolongate back.
    n_full = best.size
    while time.process_time() < deadline - 3.0:
        for Nc in (n_full // 2, n_full // 4, n_full // 2):
            if time.process_time() >= deadline - 3.0:
                break
            Nc = max(512, min(n_full, Nc))
            hc = _coarse(best, Nc)
            hc = _rescale(hc)
            rc = R_of(hc)
            hc, rc = _refine_at_N(hc, rc, min(deadline, time.process_time() + 3.0),
                                  [50.0, 200.0, 0.0], extra_windows=True)
            if time.process_time() >= deadline - 3.0:
                break
            hp = _prolongate(hc, n_full)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 600, deadline)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("multiscale N=%d R=%.7f" % (Nc, bestR))
        if time.process_time() >= deadline - 3.0:
            break

    # Phase 4: final alternating full/window polish with beta kicks.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 3.0:
                h, r = _refine_at_N(best, bestR, deadline, [100.0, 300.0])
                if r > bestR + 1e-15:
                    best, bestR = h, r
                    stall = 0
            elif stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_lav(h, k):
    """Surrogate: replace Lmax by max of k-point moving average of knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    # window centred on m, clipped to valid range of Lf
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stochastic_blocks(h, rng, nblocks=64, sigma=0.02):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    if n < nblocks:
        return h
    edges = np.linspace(0, n, nblocks + 1).astype(int)
    mult = rng.lognormal(0.0, sigma, size=nblocks)
    for b in range(nblocks):
        lo, hi = edges[b], edges[b + 1]
        if hi > lo:
            h[lo:hi] *= mult[b]
    return _rescale(h)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    cur = best.copy()
    curR = bestR
    improved_any = False

    # Main loop: moving-average surrogate ladder, then exact sharp polish.
    stage = 0
    while time.process_time() < deadline - 3.0:
        stage += 1
        for (k, iters) in [(9, 80), (5, 120), (3, 150)]:
            if time.process_time() >= deadline - 4.0:
                break
            fg = (lambda hh, kk=k: _fun_grad_lav(hh, kk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            hs = _lbfgs_log(hb, 8, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            mx, m, near = _stats(cand)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                print("  stage %d k=%d R=%.7f Lmax=%.6e argmax=%d near=%d" %
                      (stage, k, curR, mx, m, near))
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                    improved_any = True
            else:
                print("  stage %d k=%d R=%.7f (no gain) Lmax=%.6e argmax=%d near=%d" %
                      (stage, k, rc, mx, m, near))

        # Occasional beta continuation to keep the base's good behaviour.
        if time.process_time() < deadline - 3.0:
            for beta in (1e7, 1e8):
                if time.process_time() >= deadline - 4.0:
                    break
                hb = _lbfgs_log(cur, 120, deadline, beta=beta)
                hs = _lbfgs_log(hb, 5, deadline)
                rs = R_of(hs)
                if rs > curR + 3e-13:
                    cur, curR = hs, rs
                    if curR > bestR + 1e-13:
                        best, bestR = cur.copy(), curR
                        improved_any = True
                    print("  stage %d beta=%.0e R=%.7f" % (stage, beta, curR))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf
            improved_any = True

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

