        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _band_stats(h, delta):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, 0.0, 0.0
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return 0, 0.0, mx
    Lb = Lf[B]
    ratio = float(Lb.min() / mx)
    return nB, ratio, mx


def _report(tag, h, delta):
    Lf = _knots(h)
    mx = Lf.max()
    s = h.sum()
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    bmean = float(Lf[B].mean() / mx) if nB else 0.0
    r = R_of(h)
    print("  %s R=%.7f mx=%.6f num=%.6f |B|=%d mean/max=%.5f" %
          (tag, r, mx, num, nB, bmean))
    return r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    cur = best.copy()
    curR = bestR

    schedule = [(0.05, 1.0), (0.05, 5.0), (0.10, 2.0), (0.02, 2.0)]
    pass_no = 0
    while time.process_time() < deadline - 3.0:
        pass_no += 1
        for (delta, lam) in schedule:
            if time.process_time() >= deadline - 3.0:
                break
            hd = _lbfgs_log_band_down(cur, 120, deadline, delta, lam)
            _report("pass %d down d=%.2f l=%.1f" % (pass_no, delta, lam),
                    hd, delta)
            # exact sharp polish
            if time.process_time() < deadline - 2.5:
                hs = _lbfgs_log(hd, 10, deadline)
                _report("pass %d sharp" % pass_no, hs, delta)
            else:
                hs = hd
            # peak window polish
            if time.process_time() < deadline - 2.0:
                hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
                _report("pass %d window" % pass_no, hp, delta)
            else:
                hp = hs
            rp = R_of(hp)
            if rp > curR + 3e-13:
                cur, curR = hp, rp
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                    print("  pass %d NEW BEST R=%.7f" % (pass_no, bestR))
        print("  pass %d R=%.7f" % (pass_no, curR))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        _report("final", hf, 0.05)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, delta):
    """Surrogate: geometric-mean over the band [ (1-delta)*max, max ] of L."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    mask = Lf >= (1.0 - delta) * mx
    cnt = int(mask.sum())
    if cnt <= 0:
        return _fun_grad(h)
    # geometric mean of L over band = exp(mean(log L)); use log-sum surrogate
    Lb = Lf[mask]
    Lb = np.clip(Lb, 1e-300, None)
    logsum = np.log(Lb).sum()
    # d/dh of log(geomean) = (1/cnt) * sum_{band} (1/L) dL
    w = np.zeros_like(Lf)
    w[mask] = 1.0 / (cnt * Lb)
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logsum / cnt
    return val, grad


def _make_cb(deadline):
