def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _coarsen(h, k):
    n = h.size
    n2 = (n + k - 1) // k
    pad = n2 * k - n
    if pad > 0:
        hp = np.concatenate([h, np.zeros(pad)])
    else:
        hp = h
    return hp.reshape(n2, k).sum(axis=1)


def _prolong(H, k, n_target):
    out = np.repeat(H, k)
    if out.size > n_target:
        out = out[:n_target]
    elif out.size < n_target:
        out = np.concatenate([out, np.zeros(n_target - out.size)])
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    N = best.size
    cur = best.copy()
    curR = bestR

    # ---- Multi-resolution coarse polish (F190 revival) ----
    for k in (8, 16):
        if time.process_time() >= deadline - 8.0:
            break
        H = _coarsen(cur, k)
        H = _rescale(H)
        Rc0 = R_of(_prolong(H, k, N))
        print("  coarse level k=%d: R before=%.7f (n=%d, zeros %.1f%%)" %
              (k, Rc0, H.size, 100.0 * np.mean(H <= 0)))
        Hc = H.copy()
        for rnd in range(3):
            if time.process_time() >= deadline - 8.0:
                break
            # moving-average surrogate k=5
            fg5 = (lambda hh: _fun_grad_lav(hh, 5))
            Hc = _lbfgs_log(Hc, 800, deadline, fg=fg5)
            # exact-log L-BFGS
            Hc = _lbfgs_log(Hc, 400, deadline)
            # beta ladder
            for beta in (1e4, 1e6, 1e8):
                if time.process_time() >= deadline - 8.0:
                    break
                Hc = _lbfgs_log(Hc, 300, deadline, beta=beta)
            Rc = R_of(_prolong(Hc, k, N))
            if Rc > Rc0 + 3e-13:
                Rc0 = Rc
                print("    k=%d round %d R=%.7f (n=%d, zeros %.1f%%)" %
                      (k, rnd, Rc0, Hc.size, 100.0 * np.mean(Hc <= 0)))
            else:
                print("    k=%d round %d R=%.7f (no gain)" % (k, rnd, Rc))
        # prolongate best coarse result
        hp = _prolong(Hc, k, N)
        hp = _rescale(hp)
        rp = R_of(hp)
        print("  coarse level k=%d: R after prolongation=%.7f (zeros %.1f%%)" %
              (k, rp, 100.0 * np.mean(hp <= 0)))
        if rp > curR + 3e-13:
            cur, curR = hp, rp
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR

    # ---- Standard L7 pipeline at full N with remaining time ----
    stage = 0
    while time.process_time() < deadline - 3.0:
        stage += 1
        for (kk, iters) in [(9, 80), (5, 120), (3, 150)]:
            if time.process_time() >= deadline - 4.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            hs = _lbfgs_log(hb, 8, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            mx, m, near = _stats(cand)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                print("  stage %d k=%d R=%.7f Lmax=%.6e argmax=%d near=%d" %
                      (stage, kk, curR, mx, m, near))
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
            else:
                print("  stage %d k=%d R=%.7f (no gain) Lmax=%.6e argmax=%d near=%d" %
                      (stage, kk, rc, mx, m, near))

        if time.process_time() < deadline - 3.0:
            for beta in (1e4, 1e6, 1e8):
                if time.process_time() >= deadline - 4.0:
                    break
                hb = _lbfgs_log(cur, 120, deadline, beta=beta)
                hs = _lbfgs_log(hb, 5, deadline)
                rs = R_of(hs)
                if rs > curR + 3e-13:
                    cur, curR = hs, rs
                    if curR > bestR + 1e-13:
                        best, bestR = cur.copy(), curR
                    print("  stage %d beta=%.0e R=%.7f" % (stage, beta, curR))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _perturb_full(h, rng, sigma=0.20):
    h = h.copy()
    n = h.size
    if n < 8:
        return h
    nblocks = int(rng.integers(3, 6))
    cuts = np.sort(rng.choice(np.arange(1, n), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [n]))
    for b in range(edges.size - 1):
        a = edges[b]
        c = edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    pos = h[h > 0]
    if pos.size > 0:
        mean = pos.mean()
        z = h <= 0
        if np.any(z):
            h[z] = 1e-3 * mean
    return _rescale(h)


def _peak_window_indices(h, frac=0.15):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    step = min(max(m, 0), n - 1)
    half = max(2, int(frac * n))
    lo = max(0, step - half)
    hi = min(n - 1, step + half)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    start_r = R_of(start_arr)
    best = start_arr.copy()
    best_r = start_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # Try a couple of resolutions; the higher one generalizes but costs more per
    # L-BFGS iteration, so we prefer the resolution of `start` and only attempt
    # a modestly larger one if time permits.
    Ns = [start_arr.size]
    if start_arr.size < 64000:
        Ns.append(min(64000, 2 * start_arr.size))
    elif start_arr.size < 100000:
        Ns.append(min(100000, int(start_arr.size * 1.5)))

    for N_big in Ns:
        if time.process_time() >= hard_end - 1.0:
            break
        h_big = _prolongate(start_arr if N_big >= start_arr.size else best,
                            N_big) if N_big != start_arr.size else start_arr.copy()
        big_r = R_of(h_big)
        _consider(h_big, big_r)

        n_seeds = 4
        for seed in range(n_seeds):
            if time.process_time() >= hard_end - 1.0:
                break
            rng_s = np.random.default_rng(3000 + seed)
            h = _perturb_full(h_big, rng_s, sigma=0.20)

            free = _peak_window_indices(h, frac=0.15)
            for beta in (400.0, 1000.0, 2500.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_block(h, free, maxiter=250, deadline=hard_end, beta=beta)
                if R_of(c) >= R_of(h):
                    h = c

            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
                if R_of(c) >= R_of(h):
                    h = c

            for frac in (0.10, 0.25):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, 8, maxiter=300, beta=0.0)
                if R_of(c) >= R_of(h):
                    h = c

            _consider(h, R_of(h))

        print("N=%d R=%.6f" % (N_big, best_r))

    # Final refinement loop on `best` until budget is exhausted.
    try:
        while time.process_time() < hard_end - 1.0:
            h = best.copy()
            for beta in (2500.0, 1000.0, 400.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_log(h, maxiter=200, deadline=hard_end, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.25, 16), (0.10, 8), (0.05, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=300, beta=0.0)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("refine R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < start_r:
        best = start_arr.copy()
        best_r = start_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

