def _smooth_dilate(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _refine_at_res(h, deadline, rcur, rounds=3):
