def _box_surrogate(h, eta, lam):
    """Two-level box surrogate: soft-max over box-averaged knots.
    eta controls box width, lam mixes exact max vs box max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
