    gsk = w
    gLf = -dq / num
    # backprop gsk through box conv (correlate with kernel)
    gLf += np.convolve(gsk, ker, mode='same') / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
