    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _coarsen(h, k):
    n = h.size
    n2 = (n + k - 1) // k
    pad = n2 * k - n
    if pad > 0:
        hp = np.concatenate([h, np.zeros(pad)])
    else:
        hp = h
    return hp.reshape(n2, k).sum(axis=1)


def _prolong_ramp(H, k, n_target):
    """Mass-preserving linear ramp prolongation."""
    n = H.size
    # build fine array of length n*k by linear interpolation between H_i and H_{i+1}
    Hp = np.concatenate([H, [H[-1]]])
    j = np.arange(k, dtype=float)
    w = (j + 1.0) / (k + 1.0)  # in (0,1)
    # fine[ki + j] = H_i + w * (H_{i+1} - H_i)
    out = (H[:, None] * (1.0 - w[None, :]) + Hp[1:, None] * w[None, :]).ravel()
    out = np.clip(out, 0, None)
    if out.size > n_target:
        out = out[:n_target]
    elif out.size < n_target:
        out = np.concatenate([out, np.zeros(n_target - out.size)])
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    N = best.size
    cur = best.copy()
    curR = bestR

    # ---- Experiment: mild coarsening (k=2,4) with box surrogate ----
    for k in (2, 4):
        if time.process_time() >= deadline - 20.0:
            break
        H = _coarsen(cur, k)
        H = _rescale(H)
        # coarse R equals fine R (identical f)
        Rc0 = R_of(_prolong_ramp(H, k, N))
        print("  coarse k=%d: R before=%.7f (n=%d, zeros %.1f%%)" %
              (k, Rc0, H.size, 100.0 * np.mean(H <= 0)))
        Hc = H.copy()
        bestHc = H.copy()
        bestHcR = Rc0
        for rnd in range(3):
            if time.process_time() >= deadline - 20.0:
                break
            # box surrogate with two (eta,lam) settings
            for (eta, lam) in ((60.0, 0.1), (120.0, 0.05)):
                if time.process_time() >= deadline - 20.0:
                    break
                fg = (lambda hh, e=eta, l=lam: _box_surrogate(hh, e, l))
                Hc = _lbfgs_log(Hc, 400, deadline, fg=fg)
            # exact sharp
            Hc = _lbfgs_log(Hc, 100, deadline)
            Rc = R_of(_prolong_ramp(Hc, k, N))
            print("    k=%d round %d coarse R=%.7f (n=%d, zeros %.1f%%)" %
                  (k, rnd, Rc, Hc.size, 100.0 * np.mean(Hc <= 0)))
            if Rc > bestHcR + 1e-13:
                bestHcR = Rc
                bestHc = Hc.copy()
        # prolongate best coarse via linear ramp
        hp = _prolong_ramp(bestHc, k, N)
        hp = _rescale(hp)
        rp = R_of(hp)
        print("  coarse k=%d: R after ramp prolongation=%.7f (zeros %.1f%%)" %
              (k, rp, 100.0 * np.mean(hp <= 0)))
        # one exact sharp L-BFGS + window polish
        if time.process_time() < deadline - 6.0:
            hf = _lbfgs_log(hp, 100, deadline)
            rf = R_of(hf)
            print("  coarse k=%d: R after exact sharp=%.7f" % (k, rf))
            if time.process_time() < deadline - 4.0:
                hw = _window_polish_peak(hf, deadline, 0.10, 64, maxiter=200)
                rw = R_of(hw)
                print("  coarse k=%d: R after window polish=%.7f" % (k, rw))
                if rw > rf:
                    hf, rf = hw, rw
            if rf > curR + 3e-13:
                cur, curR = hf, rf
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  coarse k=%d: ACCEPTED R=%.7f" % (k, curR))
            else:
                print("  coarse k=%d: rejected (%.7f <= %.7f)" % (k, rf, curR))

    # ---- Standard L7 pipeline at full N with remaining time ----
    stage = 0
    while time.process_time() < deadline - 3.0:
        stage += 1
        for (kk, iters) in [(9, 80), (5, 120), (3, 150)]:
            if time.process_time() >= deadline - 4.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            hs = _lbfgs_log(hb, 8, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            mx, m, near = _stats(cand)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                print("  stage %d k=%d R=%.7f Lmax=%.6e argmax=%d near=%d" %
                      (stage, kk, curR, mx, m, near))
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
            else:
                print("  stage %d k=%d R=%.7f (no gain) Lmax=%.6e argmax=%d near=%d" %
                      (stage, kk, rc, mx, m, near))

        if time.process_time() < deadline - 3.0:
            for beta in (1e4, 1e6, 1e8):
                if time.process_time() >= deadline - 4.0:
                    break
                hb = _lbfgs_log(cur, 120, deadline, beta=beta)
                hs = _lbfgs_log(hb, 5, deadline)
                rs = R_of(hs)
                if rs > curR + 3e-13:
                    cur, curR = hs, rs
                    if curR > bestR + 1e-13:
                        best, bestR = cur.copy(), curR
                    print("  stage %d beta=%.0e R=%.7f" % (stage, beta, curR))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, delta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return _fun_grad(h)
    Lb = Lf[B]
    Lb_safe = np.clip(Lb, 1e-300, None)
    val = -np.log(num) + 2.0 * np.log(s) + np.mean(np.log(Lb_safe))
    gLf = -dq / num
    gLf[B] += (1.0 / nB) / Lb_safe
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log_band(h0, maxiter, deadline, delta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_band(hh, delta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _band_stats(h, delta):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, 0.0, 0.0
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return 0, 0.0, mx
    Lb = Lf[B]
    ratio = float(Lb.min() / mx)
    return nB, ratio, mx


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    cur = best.copy()
    curR = bestR

    # alternating phases: log-domain band smoothing + exact window polish
    pass_no = 0
    while time.process_time() < deadline - 3.0:
        pass_no += 1

        # Broad band smoothing in log domain (whole support, all active)
        if time.process_time() < deadline - 5.0:
            hb = _lbfgs_log_band(cur, 250, deadline, 0.05)
            rb = R_of(hb)
            nB, ratio, mx = _band_stats(hb, 0.05)
            print("  pass %d band0.05 R=%.7f |B|=%d min/max=%.5f" %
                  (pass_no, rb, nB, ratio))
            if rb > curR + 1e-13:
                cur, curR = hb, rb

        if time.process_time() < deadline - 4.0:
            hb = _lbfgs_log_band(cur, 150, deadline, 0.02)
            rb = R_of(hb)
            nB, ratio, mx = _band_stats(hb, 0.02)
            print("  pass %d band0.02 R=%.7f |B|=%d min/max=%.5f" %
                  (pass_no, rb, nB, ratio))
            if rb > curR + 1e-13:
                cur, curR = hb, rb

        if pass_no % 3 == 0 and time.process_time() < deadline - 4.0:
            hs = _lbfgs_log(cur, 150, deadline, beta=1e7)
            rs = R_of(hs)
            if rs > curR + 1e-13:
                cur, curR = hs, rs
                print("  pass %d softmax R=%.7f" % (pass_no, curR))

        # Exact polish on all active in log domain
        if time.process_time() < deadline - 3.5:
            hs = _lbfgs_log(cur, 30, deadline)
            rs = R_of(hs)
            if rs > curR + 1e-13:
                cur, curR = hs, rs

        # Window polish around peak region
        if time.process_time() < deadline - 3.0:
            hp = _window_polish_peak(cur, deadline, 0.10, 32, maxiter=200)
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp

        print("  pass %d R=%.7f" % (pass_no, curR))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 250, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

