        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        for frac, extra in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _moving_average(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    return np.convolve(h, ker, mode='same')


def _revive_tails(h, frac=0.12, level=1e-3, win=256):
    """Revive exact zeros in both far tails to level*local mean (mass-preserving)."""
    h = h.copy()
    n = h.size
    lo_end = int(frac * n)
    hi_start = int((1.0 - frac) * n)
    # local mean via moving average over win
    ker = np.ones(win) / win
    local = np.convolve(h, ker, mode='same')
    # fallback where local mean is tiny
    gm = h.mean()
    local = np.where(local > 1e-12 * max(gm, 1e-30), local, gm)
    for a, b in ((0, lo_end), (hi_start, n)):
        if b <= a:
            continue
        seg = h[a:b]
        z = seg <= 0
        if not np.any(z):
            continue
        add = np.zeros_like(seg)
        add[z] = level * local[a:b][z]
        # mass-preserving: subtract added mass proportionally from positive entries
        total_add = add.sum()
        pos = seg > 0
        if pos.any() and total_add > 0:
            pos_mass = seg[pos].sum()
            if pos_mass > total_add:
                seg[pos] -= total_add * seg[pos] / pos_mass
            else:
                seg[pos] *= 0.5
        seg += add
        h[a:b] = seg
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # Revive exact zeros in both far tails.
    cur = _revive_tails(best, frac=0.12, level=1e-3, win=256)
    r = R_of(cur)
    print("revived R=%.7f (zeros %.1f%%)" %
          (r, 100.0 * np.mean(cur <= 0)))
    if r > bestR + 1e-12:
        best, bestR = cur, r
    else:
        # keep revived as working state even if slightly worse
        cur = cur

    # Sharp full L-BFGS.
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, 800, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f (zeros %.1f%%)" %
              (r, 100.0 * np.mean(h <= 0)))
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur

    # Moving-average surrogate smoothing with exact rechecks.
    for k in (9, 5, 3):
        if time.process_time() >= deadline - 4.0:
            break
        hs = _moving_average(cur, k)
        hs = _rescale(hs)
        rs = R_of(hs)
        if rs > bestR + 1e-12:
            best, bestR = hs, rs
            cur = hs
            print("  mavg k=%d R=%.7f" % (k, rs))
        else:
            # polish the smoothed candidate anyway
            hp = _lbfgs_log(hs, 200, deadline)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                cur = hp
                print("  mavg+polish k=%d R=%.7f" % (k, rp))

    # Beta ladder with exact sharp polish after each.
    for beta in (1e4, 1e5, 1e6, 1e7, 1e8, 1e10):
        if time.process_time() >= deadline - 3.0:
            break
        hb = _lbfgs_log(cur, 300, deadline, beta=beta)
        rb = R_of(hb)
        # exact sharp polish
        hp = _lbfgs_log(hb, 300, deadline)
        rp = R_of(hp)
        print("beta=%.0e R=%.7f -> polish R=%.7f (zeros %.1f%%)" %
              (beta, rb, rp, 100.0 * np.mean(hp <= 0)))
        if rp > bestR + 1e-12:
            best, bestR = hp, rp
        if rp > bestR - 0.003:
            cur = hp
        elif rb > bestR - 0.003:
            cur = hb

    # Peak polish.
    if time.process_time() < deadline - 2.0:
        hp = _window_polish_peak(best, deadline, 0.10, 64, maxiter=300)
        rp = R_of(hp)
        if rp > bestR + 1e-12:
            best, bestR = hp, rp
            cur = hp
            print("peak polish R=%.7f" % rp)

    # Repeat: alternate sharp + peak polish + beta until deadline.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(cur, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt sharp #%d R=%.7f" % (it, bestR))
        cur = h if r > bestR - 0.003 else cur
        if time.process_time() >= deadline - 2.0:
            break
        hp = _window_polish_peak(cur, deadline, 0.10, 64, maxiter=300)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
            print("  alt peak #%d R=%.7f" % (it, rp))
        cur = hp if rp > bestR - 0.003 else cur
        if time.process_time() >= deadline - 2.0:
            break
        # occasional high-beta push
        if it % 2 == 0:
            hb = _lbfgs_log(cur, 200, deadline, beta=1e6)
            rb = R_of(hb)
            if rb > bestR + 1e-13:
                best, bestR = hb, rb
                print("  alt beta #%d R=%.7f" % (it, rb))
            cur = hb if rb > bestR - 0.003 else cur

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

