    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy_lav(seed, ks, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for k in ks:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline,
                          fg=lambda hh, k=k: _fun_grad_lav(hh, k))
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _homotopy_beta(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline,
                          fg=lambda hh, b=beta: _fun_grad_beta(hh, b))
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _maximize_peak(h, deadline, rcur):
    for frac in (0.5, 0.25, 0.12, 0.06, 0.03, 0.015, 0.008, 0.004):
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h, tol=0.98)
        center = (lo + hi) // 2
        span = max(hi - lo, 4)
        half = max(4, int(span * frac))
        lo = max(0, center - half)
        hi = min(h.size - 1, center + half)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _fresh(deadline):
    N0 = 64
    x = np.linspace(0, 1, N0)
    h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
    h = _rescale(h)
    cur_r = R_of(h)
    betas = (8, 32, 128, 512, 2048)
    N = N0
    while N <= 65536:
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs_log(h, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            h, cur_r = cand, r
        cand, r = _homotopy_beta(h, betas, 200, deadline)
        if r > cur_r:
            h, cur_r = cand, r
        if N >= 65536:
            break
        N = min(N * 2, 65536)
        h = _rescale(_prolong(h, N))
        cur_r = R_of(h)
    return h, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        best, best_r = _fresh(deadline)
        start_r = best_r

    if best.size < 65536:
        best = _rescale(_prolong(best, 65536))
        best_r = R_of(best)
        print("prolonged start to 65536: R=%.6f" % best_r)

    # Full log-space polish.
    cand = _lbfgs_log(best, maxiter=600, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r
    print("after log polish R=%.6f" % best_r)

    # New idea: averaging (lav) homotopy — smooths the max via box filter,
    # anneals k from large to 1. Approaches max from flat direction, often
    # reaching better local optima than softmax on this problem.
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        # Lav homotopy: large window -> 1
        cand, r = _homotopy_lav(best, (64, 32, 16, 8, 4, 2, 1), 250, deadline)
        if r > best_r:
            best, best_r = cand, r
        # Softmax homotopy
        cand, r = _homotopy_beta(best, (64, 256, 1024, 4096), 250, deadline)
        if r > best_r:
            best, best_r = cand, r
        cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
        cand, r = _maximize_peak(best, deadline, best_r)
        if r > best_r:
            best, best_r = cand, r
        cand, r = _polish(best, deadline, best_r,
                          fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400)
        if r > best_r:
            best, best_r = cand, r
        print("  alt#%d R=%.6f" % (it, best_r))

    if start_arr is None:
        fresh, fresh_r = _fresh(deadline)
        if fresh_r > best_r:
            best, best_r = fresh, fresh_r

    print("best R=%.6f (start %.6f)" % (best_r, start_r))
    best = _rescale(best)

    if start_arr is not None and start_r >= best_r:
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _rl_step(h, T, niter, deadline=None):
    """Richardson-Lucy deconvolution toward target autoconvolution T.
    h *= conv(T/L, h) / h.sum(), with L = conv(h,h). Rescale so L.max preserved.
    Returns best h found (by exact R)."""
    h = np.clip(np.asarray(h, dtype=float), 1e-300, None)
    if h.sum() <= 0:
        return h
    L = _conv(h)
    mx0 = L.max()
    if mx0 <= 0:
        return h
    best = h.copy()
    bestR = R_of(h)
    n = h.size
    for it in range(niter):
        if deadline is not None and time.process_time() > deadline - 0.5:
            break
        L = _conv(h)
        Ls = np.clip(L, 1e-300, None)
        ratio = T[:Ls.size] / Ls if T.size >= Ls.size else np.concatenate(
            [T, np.zeros(Ls.size - T.size)]) / Ls
        # conv with reversed h: conv(ratio, h[::-1]) valid -> length Ls.size - n + 1
        if n > 1500:
            corr = fftconvolve(ratio, h[::-1], mode='valid')[:n]
        else:
            corr = np.correlate(ratio, h, mode='valid')[:n]
        corr = np.clip(corr, 1e-300, None)
        s = h.sum()
        h = h * corr / s
        h = np.clip(h, 1e-300, None)
        # rescale so L.max preserved
        L = _conv(h)
        mxn = L.max()
        if mxn > 0:
            h = h * np.sqrt(mx0 / mxn)
        if (it + 1) % 5 == 0:
            r = R_of(h)
            if r > bestR:
                bestR = r
                best = h.copy()
    r = R_of(h)
    if r > bestR:
        bestR = r
        best = h.copy()
    return best


def _make_target(h, alpha, taper_frac):
    """Build target T: 1 on [lo,hi] where L>=alpha*M, cosine taper outside,
    zero elsewhere. Normalize T.sum() = (h.sum())^2."""
    L = _knots(h)
    M = L.max()
    if M <= 0:
        return None
    idx = np.flatnonzero(L >= alpha * M)
    if idx.size == 0:
        return None
    lo = int(idx.min())
    hi = int(idx.max())
    n = L.size
    T = np.zeros(n)
    T[lo:hi + 1] = 1.0
    span = max(1, hi - lo)
    tw = max(1, int(taper_frac * span))
    # cosine taper outside on both sides
    for i in range(1, tw + 1):
        w = 0.5 * (1.0 + np.cos(np.pi * i / (tw + 1)))
        if lo - i >= 0:
            T[lo - i] = w
        if hi + i < n:
            T[hi + i] = w
    s = h.sum()
    tot = T.sum()
    if tot <= 0:
        return None
    T = T * (s * s) / tot
    return T


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    cur = best.copy()
    curR = bestR

    # ---- Experiment: Richardson-Lucy toward flat target autoconvolution ----
    alphas = (0.5, 0.8, 0.95)
    tapers = (0.05, 0.10, 0.20)
    rl_round = 0
    while time.process_time() < deadline - 8.0:
        rl_round += 1
        improved_this_round = False
        for alpha in alphas:
            if time.process_time() >= deadline - 8.0:
                break
            for taper in tapers:
                if time.process_time() >= deadline - 8.0:
                    break
                T = _make_target(cur, alpha, taper)
                if T is None:
                    continue
                h_rl = _rl_step(cur, T, 50, deadline=deadline)
                r_rl = R_of(h_rl)
                # exact L-BFGS
                if time.process_time() < deadline - 5.0:
                    h_lb = _lbfgs_log(h_rl, 200, deadline)
                    r_lb = R_of(h_lb)
                else:
                    h_lb, r_lb = h_rl, r_rl
                cand, rc = (h_lb, r_lb) if r_lb > r_rl else (h_rl, r_rl)
                if time.process_time() < deadline - 4.0:
                    h_w = _window_polish_peak(cand, deadline, 0.10, 64, maxiter=200)
                    r_w = R_of(h_w)
                    if r_w > rc:
                        cand, rc = h_w, r_w
                print("  RL round %d alpha=%.2f taper=%.2f R=%.7f (rl=%.7f)" %
                      (rl_round, alpha, taper, rc, r_rl))
                if rc > curR + 3e-13:
                    cur, curR = cand, rc
                    improved_this_round = True
                    if curR > bestR + 1e-13:
                        best, bestR = cur.copy(), curR
                    print("    ACCEPTED R=%.7f" % curR)
        if not improved_this_round:
            break

    # ---- Standard L7 pipeline at full N with remaining time ----
    stage = 0
    while time.process_time() < deadline - 3.0:
        stage += 1
        for (kk, iters) in [(9, 80), (5, 120), (3, 150)]:
            if time.process_time() >= deadline - 4.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            hs = _lbfgs_log(hb, 8, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            mx, m, near = _stats(cand)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                print("  stage %d k=%d R=%.7f Lmax=%.6e argmax=%d near=%d" %
                      (stage, kk, curR, mx, m, near))
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
            else:
                print("  stage %d k=%d R=%.7f (no gain) Lmax=%.6e argmax=%d near=%d" %
                      (stage, kk, rc, mx, m, near))

        if time.process_time() < deadline - 3.0:
            for beta in (1e4, 1e6, 1e8):
                if time.process_time() >= deadline - 4.0:
                    break
                hb = _lbfgs_log(cur, 120, deadline, beta=beta)
                hs = _lbfgs_log(hb, 5, deadline)
                rs = R_of(hs)
                if rs > curR + 3e-13:
                    cur, curR = hs, rs
                    if curR > bestR + 1e-13:
                        best, bestR = cur.copy(), curR
                    print("  stage %d beta=%.0e R=%.7f" % (stage, beta, curR))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _refine(h, deadline, rounds=6):
    """Refinement ladder: multi-scale L-BFGS + peak polish; keep best R."""
    best = h.copy()
    bestR = R_of(best)
    cur = best.copy()
    for r in range(rounds):
        if time.process_time() >= deadline - 2.0:
            break
        for kk, iters in [(9, 60), (5, 90), (3, 120), (1, 150)]:
            if time.process_time() >= deadline - 2.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            rs = R_of(hb)
            if rs > bestR + 1e-14:
                best, bestR = hb.copy(), rs
            cur = hb
        hp = _window_polish_peak(cur, deadline, 0.10, 48, maxiter=150)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp.copy(), rp
        if rp > R_of(cur) - 1e-15:
            cur = hp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    # ---- Main idea: split the peak plateau by masking one lobe and re-optimizing.
    # The autoconvolution maximum plateau is narrow; a near-degenerate structure
    # means many active constraints. Perturb + polish across scales.
    cur = best.copy()
    curR = bestR

    rng = np.random.RandomState(12345)
    round_id = 0
    while time.process_time() < deadline - 6.0:
        round_id += 1
        improved = False
        # Perturbation moves: tiny multiplicative noise on the active support,
        # then refine. Each refine is a full ladder so it converges locally.
        for scale in (1e-3, 3e-4, 1e-4, 3e-5):
            if time.process_time() >= deadline - 6.0:
                break
            h = cur.copy()
            mask = h > 1e-12 * h.max()
            idx = np.flatnonzero(mask)
            if idx.size == 0:
                continue
            h[idx] *= np.exp(scale * rng.randn(idx.size))
            h = _rescale(h)
            h2, r2 = _refine(h, deadline, rounds=3)
            if r2 > curR + 1e-13:
                cur, curR = h2, r2
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  round %d scale=%.1e R=%.7f" % (round_id, scale, curR))
        # Structured move: soften/tighten one side of the peak to escape plateau.
        if time.process_time() < deadline - 6.0:
            Lf = _knots(cur)
            mx = Lf.max()
            idx = np.flatnonzero(Lf >= 0.999 * mx)
            if idx.size:
                lo = int(idx.min()); hi = int(idx.max())
                n = cur.size
                # widen the peak's shoulders
                for side in (-1, 1):
                    if time.process_time() >= deadline - 6.0:
                        break
                    h = cur.copy()
                    if side < 0:
                        a = max(0, lo - 40); b = lo + 1
                    else:
                        a = hi; b = min(n, hi + 41)
                    if b > a:
                        g = np.linspace(0.7, 1.0, b - a)
                        h[a:b] *= g if side < 0 else g[::-1]
                    h = _rescale(h)
                    h2, r2 = _refine(h, deadline, rounds=2)
                    if r2 > curR + 1e-13:
                        cur, curR = h2, r2
                        improved = True
                        if curR > bestR + 1e-13:
                            best, bestR = cur.copy(), curR
                        print("  round %d side=%d R=%.7f" % (round_id, side, curR))
        if not improved:
            break

    # ---- Final polishing with remaining time ----
    if time.process_time() < deadline - 1.0:
        hf, rf = _refine(best, deadline, rounds=8)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f N=%d Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _perturb_global(h, rng, amp=0.12):
    h = h.copy()
    n = h.size
    nk = int(rng.integers(3, 7))
    ks = rng.uniform(0.5, 4.0, size=nk)
    amps = rng.normal(0.0, amp, size=nk)
    x = np.linspace(0.0, 1.0, n)
    field = np.zeros(n)
    for k, a in zip(ks, amps):
        field += a * np.sin(np.pi * k * x + rng.uniform(0, 2 * np.pi))
    h *= np.exp(field)
    return _rescale(h)


def _perturb_peak(h, rng):
    h = h.copy()
    n = h.size
    lo, hi = _peak_region(h, tol=0.9)
    pad = max(8, (hi - lo))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    W = hi - lo
    if W < 4:
        return h
    nblocks = int(rng.integers(3, 7))
    cuts = np.sort(rng.choice(np.arange(1, W), size=min(nblocks - 1, W - 1), replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, 0.20))
        h[a:c] *= fac
    return _rescale(h)


def _harden(h, deadline):
    cur = h
    for beta in (2000.0, 5000.0, 20000.0):
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_sm(cur, beta, maxiter=250, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(cur, maxiter=600, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    return cur


def _tight_polish(h, deadline):
    """Soft->hard schedule plus peak-window polish, returns improved copy."""
    cur = h
    for beta in (300.0, 120.0, 60.0, 30.0):
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2)):
        if time.process_time() >= deadline - 0.5:
            break
        c = _window_polish_peak(cur, deadline, frac, extra, maxiter=400)
        if R_of(c) >= R_of(cur):
            cur = c
    return cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    best = start_arr.copy()
    best_r = R_of(best)
    alternative = None
    alt_r = -1.0

    # Phase A: harden & tight-polish the start itself.
    h = _harden(best.copy(), hard_end)
    h = _tight_polish(h, hard_end)
    r = R_of(h)
    if r > best_r:
        best, best_r = h.copy(), r

    # Phase B: prolongate to higher resolution and refine.
    for N_big in (64000, 128000, 256000):
        if time.process_time() >= hard_end - 3.0:
            break
        if N_big <= best.size:
            continue
        h_big = _prolongate(best, N_big)
        h_big = _harden(h_big, hard_end)
        h_big = _tight_polish(h_big, hard_end)
        r = R_of(h_big)
        if r > best_r:
            best, best_r = h_big.copy(), r
        elif r > alt_r:
            alternative, alt_r = h_big.copy(), r

    print("phaseB R=%.6f N=%d" % (best_r, best.size))

    # Phase C: perturb + re-polish loop, keeps improving until deadline.
    rnd = 0
    while time.process_time() < hard_end - 2.0:
        rng = np.random.default_rng(9001 + rnd)
        rnd += 1
        base = best.copy()
        # alternate perturbation families
        if rnd % 2 == 0:
            h = _perturb_peak(base, rng)
        else:
            h = _perturb_global(base, rng, amp=0.08)
        h = _tight_polish(h, hard_end)
        r = R_of(h)
        if r > best_r:
            best, best_r = h.copy(), r
        elif r > alt_r:
            alternative, alt_r = h.copy(), r

    print("final R=%.6f N=%d" % (best_r, best.size))

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r > R_of(start_arr):
        return {"best": best, "alternative": alternative}
    if best_r > R_of(start_arr):
        return best
    return start_arr

