def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.3

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=2000, deadline=hard_end)
        return cur

    cur = best.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    n = cur.size

    # Stage 1: direct gradient polishing of start via L-BFGS with exact max
    # plus extended beta-continuation. This is the reliable baseline.
    h = cur.copy()
    for beta in (2000.0, 1000.0, 400.0, 150.0, 60.0, 20.0, 0.0):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_log(h, maxiter=400, deadline=hard_end, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    _consider(h, R_of(h))
    print("beta-cont R=%.6f N=%d" % (best_r, best.size))

    # Stage 2: peak-window modulation experiments, then re-polish
    n_seeds = 12
    for seed in range(n_seeds):
        if time.process_time() >= hard_end - 1.0:
            break
        rng_s = np.random.default_rng(5000 + seed)
        h = _perturb_peak(cur, rng_s, scale=0.05)
        for beta in (600.0, 200.0, 60.0, 0.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_log(h, maxiter=300, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        _consider(h, R_of(h))
    print("peak-exp R=%.6f N=%d" % (best_r, best.size))

    # Stage 3: fine local polishing of best (block over full vector)
    try:
        while time.process_time() < hard_end - 1.0:
            h = best.copy()
            for beta in (120.0, 40.0, 10.0, 0.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_log(h, maxiter=500, deadline=hard_end, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("polish R=%.6f" % best_r)
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

