def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _refine_at(full_h, lo, hi, iters, deadline, use_beta=0.0):
    """Optimize only block [lo,hi] of full_h via log coordinates."""
    if time.process_time() >= deadline - 0.3:
        return full_h
    n = full_h.size
    sub = np.clip(full_h[lo:hi], 0, None)
    if sub.size == 0 or sub.sum() <= 0:
        return full_h
    thresh = 1e-13 * max(sub.max(), 1e-30)
    active = np.flatnonzero(sub > thresh)
    if active.size == 0:
        return full_h
    u0 = np.log(np.clip(sub[active], 1e-300, None))
    if use_beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, use_beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = full_h.copy()
        hh[lo:hi] = 0.0
        hh[lo + active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[lo + active] * hh[lo + active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return full_h
    if res is None:
        return full_h
    h2 = full_h.copy()
    h2[lo:hi] = 0.0
    h2[lo + active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_window(full_h, deadline):
    """Polish the block of h that determines the peak of f*f."""
    h = np.asarray(full_h, dtype=float)
    n = h.size
    Lf = _knots(h)
    kstar = int(np.argmax(Lf))
    lo = max(0, kstar - n + 1)
    hi = min(n - 1, kstar)
    w = max(8, (hi - lo) // 3)
    lo = max(0, lo - w)
    hi = min(n, hi + w + 1)
    return _refine_at(h, lo, hi, 300, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5

    start_h = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()

    best = None
    best_R = -1.0
    if start_h is not None:
        best = start_h.copy()
        best_R = _R(best)

    alt_best = None
    alt_R = -1.0

    # Build a base at N ~ 4096 to escape from local minima, then ladder up
    if start_h is not None:
        base = _prolong(start_h, 4096)
    else:
        base = np.ones(4096)

    # First: coarse global optimization at low N with beta softmax, several betas
    cur = base.copy()
    cur = _rescale(cur)
    for beta in [0.0, 40.0, 200.0]:
        if time.process_time() > deadline:
            break
        cur = _lbfgs_log(cur, 400, deadline, beta=beta)
        cur = _peak_window(cur, deadline)
        r = _R(cur)
        print(f"coarse beta={beta}: R={r:.6f}")

    # Ladder up in resolution, polishing at each step
    ladder = [4096, 8192, 16384, 32768, 65536, 131072, 262144]
    for N in ladder:
        if time.process_time() > deadline:
            break
        if cur.size != N:
            cur = _prolong(cur, N)
        cur = _rescale(cur)
        cur = _lbfgs_log(cur, 300, deadline, beta=0.0)
        if time.process_time() > deadline:
            break
        cur = _lbfgs_log(cur, 300, deadline, beta=50.0)
        cur = _peak_window(cur, deadline)
        r = _R(cur)
        print(f"ladder N={N}: R={r:.6f}")
        if r > alt_R:
            alt_R = r
            alt_best = cur.copy()

    # Final: alternate peak polish and short global polish at best N
    if alt_best is not None:
        cur = alt_best.copy()
        cur_R = alt_R
        while time.process_time() < deadline - 1.0:
            prev = cur_R
            cur = _peak_window(cur, deadline)
            if time.process_time() > deadline:
                break
            cur = _lbfgs_log(cur, 150, deadline, beta=0.0)
            cur = _refine_at(cur,
                             max(0, np.argmax(_knots(cur)) - cur.size),
                             cur.size, 150, deadline)
            cur_R = _R(cur)
            if cur_R > alt_R:
                alt_R = cur_R
                alt_best = cur.copy()
            if cur_R <= prev + 1e-10:
                break

    result_best = best if best is not None else np.ones(50)
    result_R = best_R
    alternative = None

    if alt_best is not None:
        if alt_R > best_R:
            result_best = alt_best
            result_R = alt_R
        else:
            alternative = alt_best

    if result_best is None:
        result_best = np.ones(50)
    result_best = np.maximum(result_best, 0.0)
    if result_best.sum() <= 0:
        result_best = np.ones(50)

    print(f"final R={_R(result_best):.6f} N={len(result_best)}")
    if alternative is not None:
        print(f"alternative R={_R(alternative):.6f} N={len(alternative)}")
        return {"best": result_best, "alternative": alternative}
    return result_best

