    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window_jitter(h, rng, sigma, width):
    """Multiply a random window centred near the peak by a smooth bump."""
    n = h.size
    lo_pk, hi_pk = _peak_region(h)
    c = (lo_pk + hi_pk) // 2
    w = min(width, n)
    lo = int(np.clip(c - w // 2 + rng.integers(-w, w + 1), 0, n - w))
    t = np.arange(w, dtype=float)
    center = w / 2.0 + rng.normal(0, w / 8.0)
    g = np.exp(-0.5 * ((t - center) / (w / 6.0)) ** 2)
    k = 9
    ker = np.ones(k) / k
    g = np.convolve(g, ker, mode='same')
    g = g / max(g.max(), 1e-300)
    bump = np.exp(sigma * (g - 1.0))
    hp = h.copy()
    hp[lo:lo + w] *= bump
    return np.clip(hp, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("start R=%.7f (N=%d)" % (start_bestR, start_best.size))

    # ---- 2x grid ----
    H = _rescale(np.repeat(start_best, 2))
    R2x = R_of(H)
    print("2x baseline R=%.7f (N=%d)" % (R2x, H.size))

    best = start_best.copy()
    bestR = start_bestR

    # Baseline polish on the 2x grid
    Hp = _lbfgs_log(H, 150, deadline)
    Hp = _window_polish_peak(Hp, deadline, 0.10, 200, maxiter=150)
    if time.process_time() < deadline - 2.0:
        Hb = _lbfgs_log(Hp, 120, deadline, beta=1e7)
        rb = R_of(Hb)
        if rb > R_of(Hp):
            Hp = Hb
    R2x_pol = R_of(Hp)
    print("2x polished R=%.7f" % R2x_pol)
    if R2x_pol > bestR + 1e-13:
        best, bestR = Hp.copy(), R2x_pol

    # ---- end-spike scan on H (the 2x baseline, not polished) ----
    n = H.size
    cands = []  # (R, side, k, mult, mode, array)
    for side in ("left", "right"):
        for k in (1, 2, 4, 8, 16):
            if k > n:
                continue
            if side == "left":
                seg = H[0:k]
                adj = H[k:k + 64]
            else:
                seg = H[-k:]
                adj = H[-k - 64:-k]
            adj_mean = float(adj.mean()) if adj.size > 0 else float(H.mean())
            for mult in (1.5, 2.0, 3.0, 5.0, 8.0):
                for mode in ("scale", "set"):
                    Hc = H.copy()
                    if mode == "scale":
                        if side == "left":
                            Hc[0:k] = seg * mult
                        else:
                            Hc[-k:] = seg * mult
                    else:
                        if side == "left":
                            Hc[0:k] = mult * adj_mean
                        else:
                            Hc[-k:] = mult * adj_mean
                    Hc = _rescale(Hc)
                    r = R_of(Hc)
                    cands.append((r, side, k, mult, mode, Hc))
                    print("  scan %s k=%d mult=%.1f %s R=%.7f" %
                          (side, k, mult, mode, r))
                    if time.process_time() > deadline - 12.0:
                        break
                if time.process_time() > deadline - 12.0:
                    break
            if time.process_time() > deadline - 12.0:
                break
        if time.process_time() > deadline - 12.0:
            break

    cands.sort(key=lambda t: -t[0])
    top = cands[:3]
    print("top candidates: " + ", ".join(
        "%s k=%d mult=%.1f %s R=%.7f" % (c[1], c[2], c[3], c[4], c[0]) for c in top))

    def full_polish(hc, deadline, iters=200):
        h = _lbfgs_log(hc, iters, deadline)
        h = _window_polish_peak(h, deadline, 0.10, 128, maxiter=150)
        r = R_of(h)
        for beta in (1e5, 1e7, 1e9):
            if time.process_time() >= deadline - 3.0:
                break
            hb = _lbfgs_log(h, 120, deadline, beta=beta)
            rb = R_of(hb)
            if rb > r:
                h, r = hb, rb
        return h, r

    for (r0, side, k, mult, mode, Hc) in top:
        if time.process_time() >= deadline - 6.0:
            break
        h, r = full_polish(Hc, deadline)
        # one stochastic peak-window perturbation
        if time.process_time() < deadline - 4.0:
            hp = _peak_window_jitter(h, rng, 0.01, 128)
            hp = _rescale(hp)
            h2 = _lbfgs_log(hp, 120, deadline)
            h2 = _window_polish_peak(h2, deadline, 0.10, 128, maxiter=120)
            r2 = R_of(h2)
            if r2 > r:
                h, r = h2, r2
        print("  polished %s k=%d mult=%.1f %s -> R=%.7f" %
              (side, k, mult, mode, r))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("  NEW BEST R=%.7f" % bestR)

    # ---- alternating stochastic + sharp polish loop ----
    cur = best.copy()
    curR = bestR
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        width = int(rng.choice([64, 128, 256]))
        sigma = float(rng.choice([0.005, 0.01, 0.02]))
        hp = _peak_window_jitter(cur, rng, sigma, width)
        hp = _rescale(hp)
        h1 = _lbfgs_log(hp, 120, deadline)
        h2 = _window_polish_peak(h1, deadline, 0.10, 128, maxiter=120)
        r2 = R_of(h2)
        if r2 > curR + 3e-13:
            cur, curR = h2, r2
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  loop %d accept R=%.7f (w=%d s=%.3f)" %
                      (it, bestR, width, sigma))

    # final sharp polish
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _polish(h, deadline, tag=""):
    """Multi-scale polish: full log-space + softmax-beta + peak windows."""
    best = h
    bestR = R_of(h)
    # softmax-beta smoothing to escape max-knot degeneracy
    for beta in (30.0, 100.0, 300.0):
        if time.process_time() >= deadline - 1.0:
            break
        h2 = _lbfgs_log(best, 300, deadline, beta=beta)
        r = R_of(h2)
        if r > bestR + 1e-15:
            best, bestR = h2, r
    # peak-window polishing at increasing scales
    for frac, extra in ((0.15, 8), (0.30, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 1.5:
            break
        h2 = _window_polish_peak(best, deadline, frac, extra)
        h2 = _lbfgs_log(h2, 400, deadline)
        r = R_of(h2)
        if r > bestR + 1e-15:
            best, bestR = h2, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    # Establish baseline from start (or default).
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    print("base R=%.7f (N=%d)" % (baseR, base.size))

    # MAIN: continue optimising start.  Use softmax-beta polish which tends to
    # escape the flat-maximum basin that pure L_inf gradient gets stuck in.
    best = base.copy()
    bestR = baseR

    # Phase 1: softmax-beta relaxations from start.
    for beta in (50.0, 150.0, 400.0):
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_log(best, 500, deadline, beta=beta)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("beta=%.0f R=%.7f" % (beta, bestR))

    # Phase 2: multi-scale polish.
    best, bestR = _polish(best, deadline)
    print("after polish R=%.7f" % bestR)

    # Phase 3: alternate full + peak until deadline.
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.45, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if bestR <= prev + 1e-15:
            # try a softmax kick
            h = _lbfgs_log(best, 300, deadline, beta=100.0)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
            else:
                break

    print("final main R=%.7f (N=%d)" % (bestR, best.size))

    # ALTERNATIVE: mirror-completion to try a genuinely different basin.
    alt = None
    altR = 0.0
    if time.process_time() < deadline - 5.0:
        h0 = base + base[::-1]
        h0 = _rescale(h0)
        hm, rm = _polish(h0, deadline)
        # alternate
        while time.process_time() < deadline - 1.0:
            prev = rm
            h = _lbfgs_log(hm, 600, deadline)
            r = R_of(h)
            if r > rm + 1e-15:
                hm, rm = h, r
            if time.process_time() >= deadline - 1.5:
                break
            h = _window_polish_peak(hm, deadline, 0.45, 24)
            r = R_of(h)
            if r > rm + 1e-15:
                hm, rm = h, r
            if rm <= prev + 1e-15:
                break
        alt = hm
        altR = rm
        print("mirror R=%.7f" % altR)

    if alt is not None and altR > bestR + 1e-15:
        # mirror wins: return it as best, original best as alternative
        return {"best": alt, "alternative": best}
    if alt is not None and bestR > baseR + 1e-15:
        return {"best": best, "alternative": alt}
    if bestR > baseR + 1e-15:
        return {"best": best, "alternative": alt if alt is not None else base}
    # nothing beat start: keep start as best, offer alternative (best effort)
    return {"best": base, "alternative": best if bestR > baseR + 1e-15 else (alt if alt is not None else best)}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def _refine_beta(h, deadline, maxiter=600):
    """Polish using the smooth-max (logsumexp) surrogate with a small beta,
    then a sharp beta, to push the flat top upward more aggressively.
    This gives a different gradient direction than the exact-max polish,
    which can escape the plateau that the exact polish is stuck on."""
    h1 = _lbfgs_log(h, maxiter=maxiter, deadline=deadline, beta=200.0)
    r1 = R_of(h1)
    h2 = _lbfgs_log(h1, maxiter=maxiter, deadline=deadline, beta=2000.0)
    r2 = R_of(h2)
    if r2 >= r1:
        return h2, r2
    return h1, r1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(256)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Alternative: finer-resolution prolongation + polish, then coarsen back.
    alt = None
    alt_r = -1.0
    N_up = min(cur.size * 2, 500000)
    if time.process_time() < deadline - 20.0:
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=300, deadline=deadline)
        up_r = R_of(up)
        if up_r > best_r:
            alt = _rescale(_coarsen(up, cur.size))
            alt_r = R_of(alt)
            if alt_r > best_r:
                best, best_r = alt.copy(), alt_r
        print("alt refine R = %.6f (N_up=%d)" % (up_r, N_up))

    # Coarsen-and-reprolong path
    if cur.size >= 16384 and time.process_time() < deadline - 15.0:
        c = _rescale(_coarsen(cur, 16384))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        c = _rescale(_prolongate(c, cur.size))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        rc = R_of(c)
        if rc > best_r:
            best, best_r = c.copy(), rc
        print("coarsen-reprolong R = %.6f" % rc)

    cur = best.copy(); cur_r = best_r

    # Main loop: alternate full polish, peak-window polish, beta-surrogate polish.
    last_r = cur_r
    stall = 0
    while time.process_time() < deadline - 1.0:
        # window polish first (cheap, local) with the exact max
        for frac, extra in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

        # full polish (exact max)
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

        # NEW: beta-surrogate polish to widen the flat top of f*f.
        # The logsumexp surrogate spreads gradient over the whole plateau,
        # which tends to raise the peak relative to L2 mass (the binding term).
        if time.process_time() < deadline - 5.0:
            cand, r = _refine_beta(cur, deadline, maxiter=500)
            if r > cur_r:
                cur, cur_r = cand, r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 3.0:
                # perturb + beta polish (different basin than exact polish)
                scale = min(0.01 * stall, 0.1)
                perturbed = _perturb(best, rng, scale)
                cp = _rescale(perturbed)
                cp = _lbfgs_log(cp, maxiter=600, deadline=deadline)
                rp = R_of(cp)
                if rp > cur_r:
                    cur, cur_r = cp, rp
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    stall = 0
                else:
                    cur = best.copy(); cur_r = best_r
        else:
            stall = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        if best_r > R_of(start_arr) + 1e-12:
            return {"best": best, "alternative": start_arr}
        return {"best": start_arr, "alternative": best}
    return best

