def _zero_runs(h):
    """Return list of (start, length) for maximal runs of exact zeros."""
    z = (h <= 0)
    n = h.size
    runs = []
    i = 0
    while i < n:
        if z[i]:
            j = i
            while j < n and z[j]:
                j += 1
            runs.append((i, j - i))
            i = j
        else:
            i += 1
    return runs


def _delete_run(h, start, length):
    return np.concatenate((h[:start], h[start + length:]))


def _polish(h, deadline, sharp_iters=200, peak_frac=0.10, peak_extra=64,
            peak_iters=150):
    if time.process_time() >= deadline - 1.0:
        return h
    h = _lbfgs_log(h, sharp_iters, deadline)
    if time.process_time() < deadline - 0.8:
        hp = _window_polish_peak(h, deadline, peak_frac, peak_extra,
                                 maxiter=peak_iters)
        if R_of(hp) > R_of(h):
            h = hp
    for beta in (1e7, 1e9):
        if time.process_time() >= deadline - 0.6:
            break
        hb = _lbfgs_log(h, 120, deadline, beta=beta)
        if R_of(hb) > R_of(h):
            h = hb
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # EXPERIMENT: interior zero-run deletion (support compaction).
    n = best.size
    runs = _zero_runs(best)
    # interior runs: not touching boundaries, length >= 64
    cands = [(s, L) for (s, L) in runs
             if s > 0 and s + L < n and L >= 64]
    cands.sort(key=lambda t: -t[1])
    cands = cands[:5]
    print("interior zero runs found: %d, testing %d" %
          (len([1 for (s, L) in runs if s > 0 and s + L < n and L >= 64]),
           len(cands)))

    best_after = best.copy()
    best_afterR = bestR

    for (s, L) in cands:
        if time.process_time() >= deadline - 5.0:
            break
        h_del = _delete_run(best, s, L)
        h_del = _rescale(h_del)
        r0 = R_of(h_del)
        h_pol = _polish(h_del, deadline)
        rp = R_of(h_pol)
        print("  del run@%d len=%d: raw R=%.7f -> polished R=%.7f (N=%d)" %
              (s, L, r0, rp, h_pol.size))
        if rp > best_afterR + 1e-12:
            best_after = h_pol
            best_afterR = rp
            print("    new best R=%.7f" % best_afterR)

    # Also polish the original p0204 briefly to be fair.
    if time.process_time() < deadline - 8.0:
        h_orig = _polish(best, deadline, sharp_iters=150)
        r_orig = R_of(h_orig)
        print("orig polish R=%.7f" % r_orig)
        if r_orig > best_afterR + 1e-12:
            best_after = h_orig
            best_afterR = r_orig

    # Spend leftover time: 3 rounds of peak perturbation + sharp polish.
    rng = np.random.default_rng(12345)
    for rnd in range(3):
        if time.process_time() >= deadline - 3.0:
            break
        h = best_after.copy()
        # perturb: multiply peak-region entries by small random factors
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(32, int(span * 0.15))
        a = max(0, lo - pad); b = min(h.size - 1, hi + pad)
        noise = 1.0 + 0.02 * rng.standard_normal(b - a + 1)
        h[a:b + 1] = np.clip(h[a:b + 1] * noise, 0, None)
        h = _rescale(h)
        h = _lbfgs_log(h, 250, deadline)
        if time.process_time() < deadline - 2.0:
            hp = _window_polish_peak(h, deadline, 0.10, 64, maxiter=200)
            if R_of(hp) > R_of(h):
                h = hp
        r = R_of(h)
        print("  round %d R=%.7f" % (rnd, r))
        if r > best_afterR + 1e-12:
            best_after = h
            best_afterR = r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (best_afterR, best_after.size,
           100.0 * np.mean(best_after <= 0)))

    if best_afterR > start_bestR + 1e-12:
        return best_after
    return {"best": start_best,
