import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    n = h.size
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fun(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    return _lbfgs(h0, _fun_grad, maxiter, deadline)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    return _lbfgs(h0, lambda h: _fun_grad_sm(h, beta), maxiter, deadline)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_sm(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _refine_full(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        for beta in (500.0, 200.0, 80.0, 30.0):
            if time.process_time() >= t_end - 0.5:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=1200, deadline=t_end)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=2000, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.2, 8, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _smooth_perturb(h, rng, scale):
    """Small smooth multiplicative perturbation of a whole interval (keeps support)."""
    n = h.size
    k = max(2, n // 200)
    # random smooth kernel via cumsum of gaussian noise, blurred
    g = rng.normal(0.0, 1.0, size=n)
    ker = np.exp(-np.linspace(-3, 3, max(3, k)) ** 2)
    ker /= ker.sum()
    g = np.convolve(g, ker, mode='same')
    g -= g.mean()
    g /= (g.std() + 1e-12)
    return np.clip(h * np.exp(scale * g), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(13579)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)
        start_arr = None

    cur = best.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    # Focus on the smooth-max + exact polish loop, which is what drove improvements.
    while time.process_time() < deadline - 0.8:
        slice_t = min(10.0, deadline - time.process_time() - 0.8)
        if slice_t <= 0.5:
            break
        cand, cand_r = _refine_full(cur, deadline, time_slice=slice_t)
        if cand_r > cur_r + 1e-12:
            cur, cur_r = cand, cand_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif cand_r > alt_r:
            alternative, alt_r = cand.copy(), cand_r

        if time.process_time() >= deadline - 0.8:
            break

        # Smooth whole-support perturbation to escape local optima.
        trial = _smooth_perturb(cur, rng, scale=rng.uniform(0.05, 0.25))
        trial = _rescale(trial)
        tr = R_of(trial)
        if tr > 0.5 * cur_r:
            trial, tr = _refine_full(trial, deadline,
                                     time_slice=min(6.0, deadline - time.process_time() - 0.8))
        if tr > cur_r:
            cur, cur_r = trial, tr
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif tr > alt_r:
            alternative, alt_r = trial.copy(), tr

        if time.process_time() >= deadline - 0.8:
            break

        # Beta continuation: from soft to sharp, on a peak window.
        trial = _window_polish_peak(cur, deadline, 0.3, 10, maxiter=400, beta=50.0)
        trial = _window_polish_peak(trial, deadline, 0.3, 10, maxiter=400, beta=0.0)
        tr = R_of(trial)
        if tr > cur_r:
            cur, cur_r = trial, tr
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif tr > alt_r:
            alternative, alt_r = trial.copy(), tr

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

