    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _downsample(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _perturb(h, rng, sigma=0.15):
    h = h.copy()
    n = h.size
    if n < 8:
        return h
    nblocks = int(rng.integers(3, 6))
    cuts = np.sort(rng.choice(np.arange(1, n), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [n]))
    for b in range(edges.size - 1):
        a = edges[b]; c = edges[b + 1]
        if c <= a:
            continue
        h[a:c] *= np.exp(rng.normal(0.0, sigma))
    pos = h[h > 0]
    if pos.size > 0:
        z = h <= 0
        if np.any(z):
            h[z] = 1e-3 * pos.mean()
    return _rescale(h)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    start_r = R_of(start_arr)
    best = start_arr.copy()
    best_r = start_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    N_big = 96000
    h_big = _prolongate(start_arr, N_big)
    big_r = R_of(h_big)
    _consider(h_big, big_r)

    # Multi-start seeds with smoothed + block polish, escalated beta schedule
    n_seeds = 8
    for seed in range(n_seeds):
        if time.process_time() >= hard_end - 1.0:
            break
        rng_s = np.random.default_rng(7000 + seed)
        h = _perturb(h_big, rng_s, sigma=0.15)

        # smoothed global with escalating beta
        for beta in (150.0, 400.0, 1000.0, 2500.0, 6000.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_log(h, maxiter=250, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c

        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c

        # peak-window polish
        lo, hi = _peak_region(h)
        span = hi - lo
        for frac in (0.05, 0.12, 0.25):
            if time.process_time() >= hard_end - 0.5:
                break
            pad = max(8, int(span * frac))
            a = max(0, lo - pad); b = min(h.size - 1, hi + pad)
            c = _lbfgs_block(h, np.arange(a, b + 1), maxiter=300,
                             deadline=hard_end, beta=0.0)
            if R_of(c) >= R_of(h):
                h = c

        r = R_of(h)
        _consider(h, r)
        print("seed %d R=%.6f best=%.6f" % (seed, r, best_r))

    # Refine best at N_big
    try:
        while time.process_time() < hard_end - 1.0 and best.size == N_big:
            h = best.copy()
            for beta in (6000.0, 2500.0, 1000.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_log(h, maxiter=250, deadline=hard_end, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            lo, hi = _peak_region(h)
            span = hi - lo
            for frac in (0.20, 0.08):
                if time.process_time() >= hard_end - 0.5:
                    break
                pad = max(8, int(span * frac))
                a = max(0, lo - pad); b = min(h.size - 1, hi + pad)
                c = _lbfgs_block(h, np.arange(a, b + 1), maxiter=300,
                                 deadline=hard_end, beta=0.0)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
    except Exception:
        pass

    print("final best=%.6f N=%d" % (best_r, best.size))

    if best_r < start_r:
        best = start_arr.copy()
        best_r = start_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


# ---------- core evaluation ----------

def _conv(h):
    if h.size > 1200:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


# ---------- objective ----------

def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    if beta <= 0:
        m = int(np.argmax(Lf))
        gLf = -dq / num
        gLf[m] += 1.0 / Lf[m]
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lf[m])
        return val, grad
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.15:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-12 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active] * hh[active]

    def cb(xk):
        if time.process_time() > deadline - 0.1:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.15:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.1:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _sharpen(h, deadline, iters=80):
    cur = h
    for beta in (2.0, 8.0, 32.0, 128.0, 512.0, 0.0):
        if time.process_time() > deadline - 0.3:
            break
        cur = _lbfgs_log(cur, iters, deadline, beta=beta)
    return cur


# ---------- structural helpers ----------

def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.ones(n_new)
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _prune(h, frac):
    h = np.asarray(h, dtype=float).copy()
    n = len(h)
    k = int(frac * n)
    if k <= 0:
        return h
    if k >= n:
        k = n - 1
    idx = np.argpartition(h, k - 1)[:k]
    h[idx] = 0.0
    mx = h.max()
    if mx > 0:
        floor = 1e-6 * mx
        pos = h > 0
        h[pos] = np.maximum(h[pos], floor)
    return h


def _prune_blockmean(h, frac):
    """Zero the frac of entries with smallest block-mean (forced pruning)."""
    h = np.asarray(h, dtype=float).copy()
    n = len(h)
    k = int(frac * n)
    if k <= 0:
        return h
    if k >= n:
        k = n - 1
    # block-mean over small blocks to preserve structure
    bs = max(1, n // 512)
    nb = n // bs
    if nb < 2:
        return _prune(h, frac)
    bm = h[:nb * bs].reshape(nb, bs).mean(axis=1)
    order = np.argsort(bm)
    nblocks = max(1, int(round(frac * nb)))
    kill = order[:nblocks]
    mask = np.ones(n, dtype=bool)
    for b in kill:
        mask[b * bs:(b + 1) * bs] = False
    h[~mask] = 0.0
    mx = h.max()
    if mx > 0:
        floor = 1e-6 * mx
        pos = h > 0
        h[pos] = np.maximum(h[pos], floor)
    return h


def _sup_window(h):
    """Return (argmax index in knot space, half-width where g > 0.5*max)."""
    L = _knots(h)
    m = int(np.argmax(L))
    mx = L[m]
    if mx <= 0:
        return m, 1
    half = 0.5 * mx
    above = np.flatnonzero(L > half)
    if above.size == 0:
        return m, 1
    lo = above[0]; hi = above[-1]
    hw = max(1, (hi - lo) // 2)
    return m, hw


def _frac_within(h, fracs=(0.001, 0.01, 0.05)):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return [0.0] * len(fracs)
    return [float(np.mean(L > (1.0 - f) * mx)) for f in fracs]


# ---------- seeds ----------

def _seed_cosine(n):
    x = np.linspace(0, 1, n)
    return np.cos(np.pi * (x - 0.5))**2 + 1e-3


def _seed_asym(n):
    x = np.linspace(0, 1, n)
    return np.exp(-((x - 0.35) / 0.2)**2) + 1e-3


# ---------- rung refinement ----------

def _rung_refine(H, deadline, rounds=5, tag=""):
    """Widened-window block polish + forced pruning + softmax polish."""
    cur = _rescale(H)
    curR = R_of(cur)
    n = len(cur)
    for rnd in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        sub_deadline = min(deadline - 0.3,
                           time.process_time() + (deadline - time.process_time()) / (rounds - rnd + 1))
        # (a) widened window block polish
        m, hw = _sup_window(cur)
        w = max(512, 4 * hw)
        lo = max(0, m - w)
        hi = min(n, m + w)
        free = np.arange(lo, hi)
        trial = _lbfgs_block(cur, free, 200, sub_deadline, beta=0.0)
        r = R_of(trial)
        if r > curR + 1e-10:
            cur = trial; curR = r
        # (b) forced pruning on block-mean + full sharpen
        for frac in (0.25,):
            if time.process_time() > sub_deadline - 0.2:
                break
            hp = _prune_blockmean(cur, frac)
            hp = _sharpen(hp, sub_deadline, iters=80)
            r = R_of(hp)
            if r > curR + 1e-10:
                cur = hp; curR = r
        # (c) one beta=1e6 softmax window polish
        if time.process_time() < sub_deadline - 0.2:
            trial = _lbfgs_block(cur, free, 120, sub_deadline, beta=1e6)
            r = R_of(trial)
            if r > curR + 1e-10:
                cur = trial; curR = r
        fr = _frac_within(cur)
        print(f"  {tag} rnd{rnd} N={n} R={curR:.6f} zeros={np.mean(cur<=0):.3f} "
              f"within .1/1/5%={fr[0]:.4f}/{fr[1]:.4f}/{fr[2]:.4f}")
    return cur, curR


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.0
    best = None
    best_R = -1.0
    start_h = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()
            best = s.copy()
            best_R = R_of(best)

    if start_h is None:
        seed_cap = t0 + min(12.0, budget_seconds * 0.25)
        best_seed = None
        best_seed_R = -1.0
        for seed_fn in (_seed_cosine, _seed_asym):
            h = seed_fn(256)
            h = _sharpen(h, seed_cap, iters=60)
            for nn in (512, 1024, 2048):
                if time.process_time() > seed_cap:
                    break
                h = _prolong(h, nn)
                h = _sharpen(h, seed_cap, iters=60)
            r = R_of(h)
            if r > best_seed_R:
                best_seed_R = r
                best_seed = h
        if best_seed is not None and best_seed_R > best_R:
            best = best_seed
            best_R = best_seed_R

    # sharpen start at its own resolution
    if best is not None:
        cur = _sharpen(best, deadline, iters=120)
        r = R_of(cur)
        if r > best_R:
            best = cur.copy(); best_R = r

    # ---- ladder: 2x, 4x, 8x with widened-window refinement ----
    if best is not None:
        cur_best = best.copy()
        cur_best_R = best_R
        for rung, factor in enumerate((2, 4, 8), start=1):
            if time.process_time() > deadline - 2.0:
                break
            n_new = len(cur_best) * factor
            if n_new > 1000000:
                break
            H = _rescale(np.repeat(cur_best, factor))
            print(f"rung {rung} ({factor}x) N={n_new} startR={R_of(H):.6f}")
            cand, candR = _rung_refine(H, deadline, rounds=5, tag=f"r{rung}")
            if candR > cur_best_R + 1e-10:
                cur_best = cand
                cur_best_R = candR
                if candR > best_R:
                    best = cand.copy(); best_R = candR
            else:
                # even if not better, keep the shape for next rung if it's close
                if candR > cur_best_R - 0.005:
                    cur_best = cand
                    cur_best_R = candR

    # ---- final polish at own resolution ----
    if best is not None and time.process_time() < deadline - 0.5:
        cur = _sharpen(best, deadline, iters=150)
        r = R_of(cur)
        if r > best_R + 1e-10:
            best = cur.copy(); best_R = r
        # small block polish around sup
        if time.process_time() < deadline - 0.3:
            m, hw = _sup_window(best)
            w = max(256, 4 * hw)
            lo = max(0, m - w); hi = min(len(best), m + w)
            trial = _lbfgs_block(best, np.arange(lo, hi), 200, deadline, beta=0.0)
            r = R_of(trial)
            if r > best_R + 1e-10:
                best = trial; best_R = r

    if best is None:
        best = np.ones(50)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)

    fr = _frac_within(best)
    print(f"final R={R_of(best):.6f} N={len(best)} zeros={np.mean(best<=0):.3f} "
          f"within .1/1/5%={fr[0]:.4f}/{fr[1]:.4f}/{fr[2]:.4f}")
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    startR = bestR
    alt = None
    altR = 0.0

    # Phase 1: smooth (beta>0) polish at current resolution to escape the
    # kinked max objective, then exact polish.
    if time.process_time() < deadline - 20.0:
        for beta in (200.0, 1000.0, 4000.0):
            if time.process_time() >= deadline - 15.0:
                break
            hb = _lbfgs_log(best, 200, deadline, beta=beta)
            r = R_of(hb)
            print("beta=%.0f R=%.7f" % (beta, r))
            if r > bestR + 1e-15:
                best, bestR = hb, r
                print("beta improved R=%.7f" % bestR)
        # exact polish after smoothing
        he = _lbfgs_log(best, 400, deadline)
        r = R_of(he)
        if r > bestR + 1e-15:
            best, bestR = he, r
            print("post-smooth exact R=%.7f" % bestR)
        elif alt is None or r > altR:
            alt, altR = he, r

    # Phase 2: prolongate to higher resolution (up to 1e6) and polish.
    for factor in (2, 2):
        if time.process_time() >= deadline - 8.0:
            break
        N1 = min(best.size * factor, 1000000)
        if N1 <= best.size:
            break
        hf = _rescale(_prolongate(best, N1))
        print("prolongated to N=%d, R=%.7f" % (hf.size, R_of(hf)))
        hf = _lbfgs_log(hf, 300, deadline)
        r = R_of(hf)
        print("prolongated polish R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = hf, r
            print("prolongated improved R=%.7f" % bestR)
        elif alt is None or r > altR:
            alt, altR = hf, r

    # Phase 3: peak-window polish at multiple scales + full polish, alternating.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        for frac in (0.05, 0.10, 0.20, 0.40):
            if time.process_time() >= deadline - 1.5:
                break
            h = _window_polish_peak(best, deadline, frac, 16, maxiter=400)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                print("win(%.2f) R=%.7f" % (frac, bestR))
                break
        if time.process_time() >= deadline - 1.5:
            break
        h = _lbfgs_log(best, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt is not None and altR > 0 and bestR <= startR + 1e-12:
        return {"best": best, "alternative": alt}
    return best

