def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_topk(h, kfrac):
    """Smooth max surrogate: mean of the top-k knots.  Directly encourages a
    wide flat plateau near the maximum instead of a single sharp peak."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(kfrac * n))
    if k >= n:
        k = n
    idx = np.argpartition(Lf, -k)[-k:]
    sm = Lf[idx].mean()
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += (1.0 / sm) / k
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _perturb_peak(h, rng):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    wlen = int(rng.randint(128, 513))
    sigma = rng.uniform(0.02, 0.06)
    lo = max(0, m - wlen)
    hi = min(n, m + wlen)
    if hi - lo < 4:
        return h
    x = np.arange(lo, hi, dtype=float)
    center = rng.uniform(lo, hi)
    width = max(2.0, (hi - lo) * sigma)
    bump = np.exp(-0.5 * ((x - center) / width) ** 2)
    ker = np.ones(9) / 9.0
    bump = np.convolve(bump, ker, mode='same')
    amp = rng.uniform(0.03, 0.10)
    h2 = h.copy()
    h2[lo:hi] *= np.exp(amp * bump)
    return _rescale(h2)


def _perturb_global(h, rng):
    """Structured low-frequency multiplicative perturbation over the whole
    support: lets the global shape move, escaping shape-level local optima."""
    n = h.size
    m = rng.randint(3, 16)
    x = np.linspace(0.0, 1.0, n)
    field = np.zeros(n)
    for j in range(1, m + 1):
        a = rng.randn()
        b = rng.uniform(0.0, 2.0 * np.pi)
        field += a * np.sin(2.0 * np.pi * j * x + b)
    fm = np.abs(field).max()
    if fm > 0:
        field /= fm
    amp = rng.uniform(0.01, 0.10)
    return _rescale(h * np.exp(amp * field))


def _same_shape(a, b):
    if a.size != b.size:
        return False
    aa = a / (a.max() + 1e-300)
    bb = b / (b.max() + 1e-300)
    return np.allclose(aa, bb, rtol=1e-3, atol=1e-5)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    # ---- load start ----
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_h = _rescale(base)
            start_R = R_of(start_h)
        else:
            start_h, start_R = None, 0.0
    else:
        start_h, start_R = None, 0.0

    if start_h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_h = _rescale(h)
        start_R = R_of(start_h)

    best = start_h.copy()
    bestR = start_R
    print("base R=%.7f N=%d" % (bestR, best.size))

    rng = np.random.RandomState(1234567)

    # ---- work at 2x the start resolution (shape is the bottleneck) ----
    if best.size * 2 <= 1000000:
        cur = _rescale(np.repeat(best, 2))
    else:
        cur = best.copy()
    curR = R_of(cur)
    if curR > bestR + 1e-13:
        best, bestR = cur.copy(), curR
    print("2x R=%.7f N=%d" % (curR, cur.size))

    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        sub = min(deadline - 1.0, time.process_time() + 7.0)

        # (1) sharp polish
        h = _lbfgs_log(cur, 180, sub)
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h, r

        # (2) top-k plateau polishes (the key new objective)
        for kfrac in (0.02, 0.005):
            if time.process_time() >= sub - 0.5:
                break
            fg = (lambda hh, kf=kfrac: _fun_grad_topk(hh, kf))
            h = _lbfgs_log(cur, 120, sub, fg=fg)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r

        # (3) one moderate beta polish
        if time.process_time() < sub - 0.5:
            h = _lbfgs_log(cur, 80, sub, beta=1e7)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r

        # (4) global perturbation + polish
        if time.process_time() < sub - 0.5:
            hp = _perturb_global(cur, rng)
            h = _lbfgs_log(hp, 100, sub)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r

        # (5) peak perturbation + polish
        if time.process_time() < sub - 0.5:
            hp = _perturb_peak(cur, rng)
            h = _lbfgs_log(hp, 90, sub)
