        print("it%d R=%.7f best=%.7f" % (it, curR, bestR))

        # (6) occasionally try a higher resolution (only if it actually helps)
        if it % 4 == 0 and cur.size * 2 <= 1000000 and time.process_time() < deadline - 12.0:
            up = _rescale(np.repeat(cur, 2))
