def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    # NEW: try prolongation to a finer grid to escape discretization ceiling.
    # Idea: upsampling the shape at higher N and re-optimising can find a
    # strictly better continuous-shape R than the fixed N=32000 allows.
    if cur.size * 2 <= 1000000:
        n_big = min(1000000, max(cur.size * 2, 64000))
        try:
            big = _prolongate(cur, n_big)
            big = _lbfgs_log(big, maxiter=600, deadline=deadline)
            big_r = R_of(big)
            if big_r > cur_r + 1e-5:
                # careful: R on finer discretization is directly comparable
                cur, cur_r = big, big_r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
        except Exception:
            pass

    while time.process_time() < deadline - 0.8:
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_log(cur, maxiter=300, deadline=deadline - 0.5, beta=beta)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        cand = _window_polish_peak(cur, deadline - 0.5, 0.4, 20, maxiter=500, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine_best(trial, deadline - 0.5,
                                          time_slice=min(6.0, deadline - time.process_time() - 0.5))
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _reparametrize(h, deadline, rng):
    """Try a different step-count representation: coarsen to half, refine back.
    This changes the discretisation grid, giving a genuinely different basin."""
    n = h.size
    if n < 64:
        return h
    c = _rescale(_coarsen(h, n // 2))
    c = _lbfgs_log(c, maxiter=300, deadline=deadline)
    c = _rescale(_prolongate(c, n))
    c = _lbfgs_log(c, maxiter=300, deadline=deadline)
    return c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(64)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Short smoothing continuation to soften any sharp features
    for beta in (8, 32, 128):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_log(cur, maxiter=120, deadline=deadline, beta=beta)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # Track an alternative solution obtained through reparametrisation
    alt = None
    alt_r = -1.0
    if time.process_time() < deadline - 25.0:
        a = _reparametrize(cur, deadline, rng)
        alt_r = R_of(a)
        alt = a
        print("  reparam R = %.6f" % alt_r)

    # Main loop
    last_r = cur_r
    no_improve = 0
    tries = 0
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1500, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, extra in ((0.04, 4), (0.12, 8), (0.3, 16)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=600)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 4.0:
                # Try reparametrisation of current best first
                seed = _reparametrize(best, deadline, rng)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    # Combined smoothing + perturbation
                    k = 3 if tries % 2 == 0 else 5
                    seed2 = _rescale(_smooth(best, k))
                    seed2 = _perturb(seed2, rng, min(0.02 * (1 + tries), 0.15))
                    seed2 = _rescale(seed2)
                    cand_p = _lbfgs_log(seed2, maxiter=1000, deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    if alt is not None and alt_r > best_r:
        best, best_r = alt.copy(), alt_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None and alt is not None and alt_r > 0:
        return {"best": best, "alternative": alt}
    return best

