                        eps=eps, beta=beta)


def _warp(h, phi):
    """Mass-preserving monotone coordinate warp. phi: array of length N+1 in [0,1]."""
    n = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return h.copy()
    xq = np.clip(phi, 0.0, 1.0) * n
    xp = np.arange(n + 1, dtype=float)
    cw = np.interp(xq, xp, c)
    hw = np.diff(cw)
    hw = np.clip(hw, 0.0, None)
    s = hw.sum()
    if s <= 0:
        return h.copy()
    hw *= total / s
    return _rescale(hw)


def _peak_perturb(h, rng, scale=0.02):
    """Stochastic multiplicative perturbation near the peak region."""
    h = h.copy()
    n = h.size
    lo, hi = _peak_region(h)
    span = max(1, hi - lo)
    pad = max(16, int(0.1 * span))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    idx = np.arange(lo, hi + 1)
    noise = 1.0 + scale * rng.standard_normal(idx.size)
    h[idx] = np.clip(h[idx] * noise, 0.0, None)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (baseR, base.size, 100.0 * np.mean(base <= 0)))

    n = base.size
    u = np.arange(n + 1, dtype=float) / n

    phis = [
        ("u^0.75", u ** 0.75),
        ("u^0.85", u ** 0.85),
        ("u^1.15", u ** 1.15),
        ("u^1.30", u ** 1.30),
        ("1-(1-u)^1.3", 1.0 - (1.0 - u) ** 1.3),
        ("1-(1-u)^0.8", 1.0 - (1.0 - u) ** 0.8),
    ]

    best = base.copy()
    bestR = baseR
    best_warp = None

    # Phase 1: warp sweep
    for name, phi in phis:
        if time.process_time() >= deadline - 8.0:
            break
        hw = _warp(base, phi)
        rw = R_of(hw)
        # short polish
        if time.process_time() < deadline - 6.0:
            hw2 = _lbfgs_log(hw, 200, min(deadline, time.process_time() + 10.0))
            rw2 = R_of(hw2)
            if rw2 > rw:
                hw, rw = hw2, rw2
        if time.process_time() < deadline - 4.0:
            hw3 = _window_polish_peak(hw, min(deadline, time.process_time() + 6.0),
                                      0.15, 64, maxiter=200)
            rw3 = R_of(hw3)
            if rw3 > rw:
                hw, rw = hw3, rw3
        if time.process_time() < deadline - 3.0:
            hw4 = _lbfgs_log(hw, 100, min(deadline, time.process_time() + 4.0),
                             beta=1e7)
            rw4 = R_of(hw4)
            if rw4 > rw:
                hw, rw = hw4, rw4
        print("phi=%s warp R=%.7f -> polish R=%.7f (zeros %.1f%%)" %
              (name, R_of(_warp(base, phi)), rw, 100.0 * np.mean(hw <= 0)))
        if rw > bestR + 1e-12:
            best, bestR = hw, rw
            best_warp = hw
        elif best_warp is None and rw > baseR - 1e-4:
            best_warp = hw

    # Phase 2: alternate sharp polish + peak polish + stochastic perturbation
    rng = np.random.default_rng(12345)
    cur = best.copy()
    curR = bestR
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        if time.process_time() < deadline - 1.5:
            h1 = _lbfgs_log(cur, 150, min(deadline, time.process_time() + 8.0))
            r1 = R_of(h1)
            if r1 > curR:
                cur, curR = h1, r1
        if time.process_time() < deadline - 1.5:
            h2 = _window_polish_peak(cur, min(deadline, time.process_time() + 5.0),
                                     0.10, 32, maxiter=150)
            r2 = R_of(h2)
            if r2 > curR:
                cur, curR = h2, r2
        if time.process_time() < deadline - 1.5:
            hp = _peak_perturb(cur, rng, scale=0.02)
            h3 = _lbfgs_log(hp, 100, min(deadline, time.process_time() + 4.0))
            r3 = R_of(h3)
            if r3 > curR:
                cur, curR = h3, r3
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
        print("iter %d R=%.7f (best %.7f)" % (it, curR, bestR))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _support_trim(h, eps=1e-9):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    thr = eps * h.max()
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    return h[idx[0]:idx[-1] + 1].copy()


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    # ---- Prolongate to N=65536 ----
    N_big = 65536
    h = _prolongate(start_arr, N_big)
    h = _rescale(h)
    cur_r = R_of(h)
    print("prolong R=%.6f N=%d" % (cur_r, h.size))

    # ---- Descending-beta smooth-max continuation ----
    for beta in (1500.0, 800.0, 400.0, 200.0):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("beta=%.0f R=%.6f" % (beta, cur_r))

    # ---- Exact-objective log L-BFGS ----
    if time.process_time() < hard_end - 0.5:
        c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("exact R=%.6f" % cur_r)

    # ---- Peak-window exact polish ----
    for frac, extra in ((0.05, 8), (0.10, 12), (0.20, 20)):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _window_polish_peak(h, hard_end, frac, extra, maxiter=400, beta=None)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("win frac=%.2f R=%.6f" % (frac, cur_r))

    # ---- NEW: support-trimmed re-prolongation cycle ----
    if time.process_time() < hard_end - 2.0:
        ht = _support_trim(h, eps=1e-6)
        if ht.size < h.size and ht.size > 100:
            N_trim = min(65536, max(ht.size, int(ht.size * 1.2)))
            h2 = _prolongate(ht, N_trim)
            h2 = _rescale(h2)
            r2 = R_of(h2)
            if r2 >= cur_r - 0.001:
                c = _lbfgs_sm(h2, 400.0, maxiter=200, deadline=hard_end)
                rc = R_of(c)
                if rc > cur_r:
                    h, cur_r = c, rc
                    print("reprolong R=%.6f N=%d" % (cur_r, h.size))

    # ---- Alternate full exact polish and peak-window polish ----
    try:
        while time.process_time() < hard_end - 1.0:
            c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
            rc = R_of(c)
            if rc >= cur_r:
                h, cur_r = c, rc
            if time.process_time() >= hard_end - 0.5:
                break
            for frac, extra in ((0.20, 20), (0.10, 12), (0.05, 8)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=300, beta=None)
                rc = R_of(c)
                if rc >= cur_r:
                    h, cur_r = c, rc
            if time.process_time() >= hard_end - 1.0:
                break
    except Exception:
        pass

    print("final R=%.6f N=%d" % (cur_r, h.size))

    if cur_r > best_r:
        return {"best": h, "alternative": best}
    return {"best": best, "alternative": h}

