    hi = min(h.size - 1, idx.max())
    return lo, hi


def _perturb_peak(h, rng, scale=0.05):
    h = h.copy()
    n = h.size
    lo, hi = _peak_region(h, tol=0.98)
    pad = max(4, int(0.12 * n))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    W = hi - lo + 1
    if W < 4:
        return h
    nmodes = int(rng.integers(1, 4))
    x = np.linspace(0.0, 1.0, W)
    mod = np.ones(W)
    for _ in range(nmodes):
        k = int(rng.integers(1, 5))
        amp = rng.normal(0.0, scale)
        phase = rng.uniform(0, 2 * np.pi)
        mod *= (1.0 + amp * np.sin(2 * np.pi * k * x + phase))
    mod = np.clip(mod, 0.5, 1.5)
    h[lo:hi + 1] *= mod
    return _rescale(h)


def _upsample(h, factor=2):
    """Refine resolution: linear interpolation between steps."""
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    nn = n * factor
    x_new = np.linspace(0.0, 1.0, nn)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds - 1.2

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    best = start_arr.copy()
    best_r = R_of(best)
    cur = best.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # Stage 0: try upsampling to break resolution limits, then polish.
    if start_arr.size <= 250000:
        for factor in (2, 3):
            if time.process_time() >= hard_end - 1.0:
                break
            up = _upsample(start_arr, factor)
            h = up
            for beta in (300.0, 100.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_log(h, maxiter=200, deadline=hard_end, beta=beta)
                if R_of(c) >= R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=500, deadline=hard_end)
                if R_of(c) >= R_of(h):
                    h = c
            _consider(h, R_of(h))
            if best_r > cur_r or best is not start_arr:
                pass
        print("upsample R=%.6f N=%d" % (best_r, best.size))

    # Stage 1: baseline smoothing polish on best
    h = best.copy()
    for beta in (400.0, 150.0, 60.0, 25.0):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_log(h, maxiter=300, deadline=hard_end, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    if time.process_time() < hard_end - 0.5:
        c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
        if R_of(c) >= R_of(h):
            h = c
    _consider(h, R_of(h))
    print("baseline R=%.6f N=%d" % (best_r, best.size))

    # Stage 2: peak-window perturbations
    seed = 0
    while time.process_time() < hard_end - 0.8 and seed < 8:
        rng_s = np.random.default_rng(9000 + seed)
        seed += 1
        h = _perturb_peak(cur, rng_s, scale=0.06)
        for beta in (500.0, 150.0, 50.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_log(h, maxiter=200, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        _consider(h, R_of(h))
    print("peak-exp R=%.6f N=%d" % (best_r, best.size))

    # Stage 3: repeated fine polishing of best
    while time.process_time() < hard_end - 0.9:
        h = best.copy()
        changed = False
        n = h.size
        lo, hi = _peak_region(h)
        for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2), (0.015, 1)):
            if time.process_time() >= hard_end - 0.4:
                break
            span = hi - lo
            pad = max(extra, int(span * frac))
            l2 = max(0, lo - pad); h2 = min(n - 1, hi + pad)
            c = _lbfgs_block(h, np.arange(l2, h2 + 1), 350, hard_end)
            if R_of(c) > R_of(h):
                h = c
                changed = True
        if time.process_time() < hard_end - 0.4:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end)
            if R_of(c) > R_of(h):
                h = c
                changed = True
        r = R_of(h)
        if r > best_r:
            _consider(h, r)
        if not changed:
            break
    print("polish R=%.6f" % best_r)

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r > -1 and alt_r < best_r:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _revive_zeros(h, lo, hi, level, win=512):
    """Revive exact zeros in [lo,hi) to level * local mean of positive heights."""
    h = h.copy()
    n = h.size
    lo = max(0, int(lo)); hi = min(n, int(hi))
    if hi <= lo:
        return h
    pos = h > 0
    idx = np.flatnonzero(~pos[lo:hi]) + lo
    if idx.size == 0:
        return h
    # local mean via cumulative sums of positives
    csum = np.concatenate(([0.0], np.cumsum(h)))
    ccnt = np.concatenate(([0.0], np.cumsum(pos.astype(float))))
    for j in idx:
        a = max(0, j - win); b = min(n, j + win)
        s = csum[b] - csum[a]
        c = ccnt[b] - ccnt[a]
        if c > 0:
            h[j] = level * (s / c)
        else:
            h[j] = level * (h.sum() / max(1, pos.sum()))
    return _rescale(h)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    near = np.mean(Lf >= 0.99 * mx)
    argm = int(np.argmax(Lf)) / max(1, Lf.size - 1)
    return (100.0 * np.mean(h <= 0), h.max() / max(1e-30, h.mean()),
            near, argm)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (baseR, base.size, 100.0 * np.mean(base <= 0)))

    # Doubling: exact staircase lift
    h = np.repeat(base, 2)
    h = _rescale(h)
    R = R_of(h)
    print("doubled R=%.7f (N=%d)" % (R, h.size))
    z, mm, nm, am = _stats(h)
    print("  zeros %.1f%% max/mean %.2f near-max %.4f argmax %.3f" %
          (z, mm, nm, am))

    best = h.copy()
    bestR = R

    n = h.size

    def stage(hcur, Rcur, label):
        nonlocal best, bestR
        if Rcur > bestR + 1e-13:
            best = hcur.copy(); bestR = Rcur
        z, mm, nm, am = _stats(hcur)
        print("%s R=%.7f zeros %.1f%% max/mean %.2f near %.4f argmax %.3f" %
              (label, Rcur, z, mm, nm, am))

    # Round 1: revive zeros in peak-feeding right window [0.60N, N)
    if time.process_time() < deadline - 5.0:
        h1 = _revive_zeros(h, 0.60 * n, n, 1e-3)
        R1 = R_of(h1)
        if R1 > R:
            h, R = h1, R1
        stage(h, R, "revive1")

    # Sharp log-space L-BFGS
    if time.process_time() < deadline - 5.0:
        h2 = _lbfgs_log(h, 300, min(deadline, time.process_time() + 12.0))
        R2 = R_of(h2)
        if R2 > R:
            h, R = h2, R2
        stage(h, R, "sharp")

    # Beta-softmax polishes with peak-window polishes in between
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 4.0:
            break
        hb = _lbfgs_log(h, 150, min(deadline, time.process_time() + 6.0), beta=beta)
        Rb = R_of(hb)
        if Rb > R:
            h, R = hb, Rb
        stage(h, R, "beta%.0e" % beta)
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hw = _window_polish_peak(h, min(deadline, time.process_time() + 4.0),
                                     frac, 32, maxiter=150)
            Rw = R_of(hw)
            if Rw > R:
                h, R = hw, Rw
            stage(h, R, "win%.2f" % frac)

    # Round 2: interior zeros in [0.25N, 0.60N) at 5e-3 local mean
    if time.process_time() < deadline - 4.0:
        h3 = _revive_zeros(h, 0.25 * n, 0.60 * n, 5e-3)
        R3 = R_of(h3)
        if R3 > R:
            h, R = h3, R3
        stage(h, R, "revive2")
        if time.process_time() < deadline - 3.0:
            h4 = _lbfgs_log(h, 200, min(deadline, time.process_time() + 8.0))
            R4 = R_of(h4)
            if R4 > R:
                h, R = h4, R4
            stage(h, R, "sharp2")

    # Alternate sharp + beta + window until budget
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        if time.process_time() < deadline - 2.0:
            hh = _lbfgs_log(h, 150, min(deadline, time.process_time() + 6.0))
            Rh = R_of(hh)
            if Rh > R:
                h, R = hh, Rh
        if time.process_time() < deadline - 2.0:
            hh = _lbfgs_log(h, 100, min(deadline, time.process_time() + 4.0),
                            beta=1e4)
            Rh = R_of(hh)
            if Rh > R:
                h, R = hh, Rh
        if time.process_time() < deadline - 2.0:
            hh = _window_polish_peak(h, min(deadline, time.process_time() + 3.0),
                                     0.10, 32, maxiter=120)
            Rh = R_of(hh)
            if Rh > R:
                h, R = hh, Rh
        stage(h, R, "alt%d" % it)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

