    # NEW IDEA: two-pronged exploration.
    # (1) Multiplicative-noise basin hopping at the CURRENT resolution:
    #     perturb the incumbent with smooth multiplicative noise, run a short
    #     full-resolution log-space L-BFGS, then a peak-window polish.
    #     This produces different basins than pure blur.
    # (2) "Re-coarse" trick: downsample to a smaller N, optimise there with
    #     beta-smoothed max (to avoid the sharp max), prolongate back up, and
    #     polish. This lets the peak structure shift more freely.
    n = best.size
    trial = 0
    while time.process_time() < deadline - 6.0:
        trial += 1
        if trial % 2 == 1:
            # multiplicative noise
            amp = float(rng.choice([0.05, 0.1, 0.2, 0.4, 0.8]))
            hp = _perturb_noise(best, rng, amp)
            hp = _rescale(hp)
            if hp.sum() <= 0:
                continue
            hp = _lbfgs_log(hp, 300, deadline)
            if time.process_time() >= deadline - 4.0:
                break
            hp = _window_polish_peak(hp, deadline, 0.30, 16)
            r = R_of(hp)
            print("noise amp=%.2f trial=%d R=%.7f" % (amp, trial, r))
        else:
            # re-coarse with beta-smoothed max
            Nc = int(max(512, n // int(rng.choice([2, 3, 4, 6, 8]))))
            hc = _resample(best, Nc)
            hc = _rescale(hc)
            beta = float(rng.choice([2.0, 5.0, 10.0, 20.0]))
            hc = _lbfgs_log(hc, 300, deadline, beta=beta)
            hc = _window_polish_peak(hc, deadline, 0.35, 12, beta=beta)
            hp = _resample(hc, n)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 300, deadline)
            if time.process_time() >= deadline - 4.0:
                break
            hp = _window_polish_peak(hp, deadline, 0.30, 16)
            r = R_of(hp)
            print("recoarse Nc=%d beta=%.1f R=%.7f" % (Nc, beta, r))

        if r > bestR + 1e-12:
            best, bestR = hp, r
            print("  accept R=%.7f" % bestR)

    # Final full polish and peak-window alternation.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _fine_polish(h, deadline):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    for frac in (0.02, 0.04, 0.08):
        if time.process_time() >= deadline - 0.4:
            break
        for beta in (None, 8000.0, 20000.0):
            if time.process_time() >= deadline - 0.4:
                break
            _try(_window_polish_peak(cur, deadline, frac, 4,
                                     maxiter=300, beta=beta))
    if time.process_time() < deadline - 0.4:
        _try(_lbfgs_log(cur, maxiter=600, deadline=deadline))
    return cur, cur_r


def _prolong_mass(h, N2):
    n = h.size
    if N2 <= n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, float(n), N2 + 1)
    newc = np.interp(edges, np.arange(n + 1, dtype=float), c)
    h2 = np.diff(newc)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return np.ones(N2)
    return h2


# ---------------- Block-correction stage ----------------

def _block_edges(n, B):
    edges = np.linspace(0, n, B + 1).astype(int)
    edges[-1] = n
    return edges


def _block_correction(h_base, B, maxiter, deadline):
    """Optimize additive per-block corrections d_b >= -min(h_base in block)."""
    if time.process_time() >= deadline - 0.3:
        return h_base
    n = h_base.size
    edges = _block_edges(n, B)
    lens = np.diff(edges)
    mins = np.array([h_base[edges[b]:edges[b + 1]].min() for b in range(B)])
    lb = -mins  # d_b >= -min

    # Build a repeat-index for summing fine gradients into blocks
    idx = np.repeat(np.arange(B), lens)

    def expand(d):
        return h_base + d[idx]

    def f(d):
        h = expand(d)
        val, g = _fun_grad(h)
        gd = np.zeros(B)
        np.add.at(gd, idx, g)
        return val, gd

    d0 = np.zeros(B)
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lb[b], None) for b in range(B)],
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h_base
    if res is None:
        return h_base
    d = res.x
    h2 = np.clip(expand(d), 0.0, None)
    if h2.sum() <= 0:
        return h_base
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r + 1e-12:
            best, best_r = cand.copy(), r
        elif r > alt_r + 1e-12:
            alternative, alt_r = cand.copy(), r

    n = base.size

    # Prolong to 256000 if base is smaller
    N2 = 256000
    if n < N2:
        hf = _prolong_mass(base, N2)
        hf = _rescale(hf)
    else:
        hf = base.copy()
    r0 = R_of(hf)
    print("prolonged R=%.7f (base %.7f) N=%d" % (r0, base_r, hf.size))
    cur = hf
    cur_r = r0
    _consider(cur, cur_r)

    # ---- Block-correction stage ----
    for B in (128, 256, 512, 1024):
        if time.process_time() >= hard_end - 4.0:
            break
        hb = _block_correction(cur, B, maxiter=250, deadline=hard_end)
        rb = R_of(hb)
        print("block B=%d R=%.7f (cur %.7f)" % (B, rb, cur_r))
        if rb > cur_r + 1e-12:
            cur, cur_r = hb, rb
            _consider(cur, cur_r)
        # fine log-space polish
        if time.process_time() < hard_end - 2.0:
            hp = _lbfgs_log(cur, maxiter=100, deadline=hard_end)
            rp = R_of(hp)
            print("  log polish R=%.7f" % rp)
            if rp > cur_r + 1e-12:
                cur, cur_r = hp, rp
                _consider(cur, cur_r)
        # beta polish
        for beta in (400.0, 1500.0, 4000.0):
            if time.process_time() >= hard_end - 1.5:
                break
            hp = _lbfgs_sm(cur, beta, maxiter=120, deadline=hard_end)
            rp = R_of(hp)
            if rp > cur_r + 1e-12:
                cur, cur_r = hp, rp
                _consider(cur, cur_r)
        print("  beta polish R=%.7f" % cur_r)
        # peak-window polish
        if time.process_time() < hard_end - 1.0:
            hp = _window_polish_peak(cur, hard_end, 0.05, 8,
                                     maxiter=300, beta=None)
            rp = R_of(hp)
            if rp > cur_r + 1e-12:
                cur, cur_r = hp, rp
                _consider(cur, cur_r)
            print("  peak polish R=%.7f" % cur_r)

    # ---- Final sharp polish ----
    if time.process_time() < hard_end - 0.5:
        hfin, rfin = _fine_polish(cur, hard_end)
        _consider(hfin, rfin)
        print("final fine polish R=%.7f" % rfin)

    print("final R=%.7f N=%d | base R=%.7f N=%d"
          % (best_r, best.size, base_r, base.size))

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _peak_polish(h, deadline, rcur, fracs=(0.03, 0.07, 0.15), maxiter=300):
    for frac in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _resample(h, n_new):
    n = h.size
    if n == n_new:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    x_new = np.linspace(0.0, 1.0, n_new, endpoint=False)
    return np.interp(x_new, x_old, h)


def _revive_zeros(h, factor, win=256):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    pos = h > 0
    if not pos.any():
        return h
    gmean = h[pos].mean()
    hp = np.where(pos, h, 0.0)
    cnt = pos.astype(float)
    cs = np.concatenate(([0.0], np.cumsum(hp)))
    cc = np.concatenate(([0.0], np.cumsum(cnt)))
    half = win // 2
    idx = np.arange(n)
    lo = np.clip(idx - half, 0, n)
    hi = np.clip(idx + half + 1, 0, n)
    ssum = cs[hi] - cs[lo]
    scnt = cc[hi] - cc[lo]
    local = np.where(scnt > 0, ssum / np.maximum(scnt, 1e-300), gmean)
    zeros = ~pos
    h[zeros] = factor * local[zeros]
    return _rescale(h)


def _perturb(h, rng, scale=0.05):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    p = rng.standard_normal(n) * scale
    if n > 8:
        k = max(3, n // 64)
        kern = np.ones(k) / k
        p = np.convolve(p, kern, mode='same')
    h = h * np.exp(p)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = _rescale(s.copy())
            best_r = R_of(best)

    if best is None:
        x = np.linspace(0, 1, 256)
        best = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best_r = R_of(best)

    print("start R = %.6f, N = %d" % (best_r, best.size))
    base_r = best_r
    rng = np.random.default_rng(12345)

    # Phase A: refine on the SAME grid first (cheap, high leverage).
    # The start is already tuned; a quick sharp + smooth ladder on it
    # often beats any resampling.
    h = best.copy()
    cur = best_r
    for _ in range(2):
        if time.process_time() >= deadline - 2.0:
            break
        c = _lbfgs_log(h, maxiter=400, deadline=deadline)
        r = R_of(c)
        if r > cur:
            h, cur = c, r
        for beta in (1e5, 1e6):
            if time.process_time() >= deadline - 2.0:
                break
            c2 = _lbfgs_log(h, maxiter=250, deadline=deadline, beta=beta)
            r2 = R_of(c2)
            if r2 > cur:
                h, cur = c2, r2
        h, cur = _peak_polish(h, deadline, cur, fracs=(0.03, 0.10), maxiter=300)
    if cur > best_r:
        best, best_r = h.copy(), cur
        print("same-grid refine -> %.6f" % best_r)

    # Phase B: try alternative grids (upsample by 2x) and reoptimize on them.
    # This is the main "new idea": the original program only upsampled once
    # at the very start; here we do it after the same-grid polish, so the
    # finer grid inherits a better starting point.
    alt = []
    for factor in (2, 4):
        if time.process_time() >= deadline - 8.0:
            break
        n_new = min(1000000, best.size * factor)
        if n_new <= best.size:
            continue
        hf = _rescale(_resample(best, n_new))
        hf = _lbfgs_log(hf, maxiter=350, deadline=deadline)
        rf = R_of(hf)
        if rf > best_r:
            hf, rf = _peak_polish(hf, deadline, rf,
                                  fracs=(0.03, 0.07, 0.15), maxiter=300)
        alt.append((rf, hf))
        print("  up %dx R=%.6f N=%d" % (factor, rf, hf.size))

    if alt:
        alt.sort(key=lambda t: -t[0])
        rf, hf = alt[0]
        if rf > best_r:
            best, best_r = hf.copy(), rf
            print("upsample improved to %.6f (N=%d)" % (best_r, best.size))

    # Phase C: zero revival on the best
    if time.process_time() < deadline - 6.0:
        for factor in (1e-3, 1e-2):
            if time.process_time() >= deadline - 4.0:
                break
            hr = _revive_zeros(best, factor)
            hr = _lbfgs_log(hr, maxiter=500, deadline=deadline)
            rr = R_of(hr)
            for beta in (1e3, 1e4, 1e5):
                if time.process_time() >= deadline - 3.0:
                    break
                cand = _lbfgs_log(hr, maxiter=250, deadline=deadline, beta=beta)
                r = R_of(cand)
                if r > rr:
                    hr, rr = cand, r
                hr, rr = _peak_polish(hr, deadline, rr,
                                      fracs=(0.03, 0.10), maxiter=250)
            if rr > best_r:
                best, best_r = hr.copy(), rr
                print("  revive f=%.0e R=%.6f" % (factor, rr))

    # Phase D: alternating full sharp + smooth + peak polish + perturbations
    h, cur = best.copy(), best_r
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        c = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r = R_of(c)
        if r > cur:
            h, cur = c, r
        if it % 3 == 0:
            for beta in (1e5, 1e6, 1e7):
                if time.process_time() >= deadline - 1.0:
                    break
                c2 = _lbfgs_log(h, maxiter=200, deadline=deadline, beta=beta)
                r2 = R_of(c2)
                if r2 > cur:
                    h, cur = c2, r2
        h, cur = _peak_polish(h, deadline, cur,
                              fracs=(0.03, 0.07, 0.15), maxiter=300)
        if it % 4 == 0 and time.process_time() < deadline - 3.0:
            hp = _perturb(h, rng, scale=0.03)
            hp = _lbfgs_log(hp, maxiter=200, deadline=deadline)
            rp = R_of(hp)
            if rp > cur:
                h, cur = hp, rp
        if cur > best_r:
            best, best_r = h.copy(), cur
        print("  alt %d R=%.6f (best %.6f) N=%d" % (it, cur, best_r, best.size))

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        if best_r > base_r + 1e-12:
            return {"best": best, "alternative": start_arr}
        return {"best": start_arr, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_topk(h, kfrac):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(kfrac * n))
    if k >= n:
        k = n
    idx = np.argpartition(Lf, -k)[-k:]
    sm = Lf[idx].mean()
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += (1.0 / sm) / k
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _perturb_peak(h, rng):
    n = h.size
    m = int(np.argmax(_knots(h)))
    wlen = int(rng.randint(128, 513))
    sigma = rng.uniform(0.02, 0.06)
    lo = max(0, m - wlen)
    hi = min(n, m + wlen)
    if hi - lo < 4:
        return h
    x = np.arange(lo, hi, dtype=float)
    center = rng.uniform(lo, hi)
    width = max(2.0, (hi - lo) * sigma)
    bump = np.exp(-0.5 * ((x - center) / width) ** 2)
    ker = np.ones(9) / 9.0
    bump = np.convolve(bump, ker, mode='same')
    amp = rng.uniform(0.03, 0.10)
    h2 = h.copy()
    h2[lo:hi] *= np.exp(amp * bump)
    return _rescale(h2)


def _perturb_global(h, rng):
    n = h.size
    m = rng.randint(3, 16)
    x = np.linspace(0.0, 1.0, n)
    field = np.zeros(n)
    for j in range(1, m + 1):
        a = rng.randn()
        b = rng.uniform(0.0, 2.0 * np.pi)
        field += a * np.sin(2.0 * np.pi * j * x + b)
    fm = np.abs(field).max()
    if fm > 0:
        field /= fm
    amp = rng.uniform(0.01, 0.10)
    return _rescale(h * np.exp(amp * field))


def _same_shape(a, b):
    if a.size != b.size:
        return False
    aa = a / (a.max() + 1e-300)
    bb = b / (b.max() + 1e-300)
    return np.allclose(aa, bb, rtol=1e-3, atol=1e-5)


def _peak_polish(h, deadline, iters=3):
    """Local block refinement around the plateau: fine-tunes the shape near
    the maximum where the L2/Linf trade-off is decided."""
    for _ in range(iters):
        if time.process_time() >= deadline - 0.5:
            break
        lo, hi = _peak_region(h)
        pad = max(64, int((hi - lo) * 0.2))
        lo2 = max(0, lo - pad); hi2 = min(h.size - 1, hi + pad)
        if hi2 <= lo2:
            break
        free = np.arange(lo2, hi2 + 1)
        h2 = _lbfgs_block(h, free, 120, deadline)
        if R_of(h2) >= R_of(h) - 1e-13:
            h = h2
        else:
            break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_h = _rescale(base)
            start_R = R_of(start_h)
        else:
            start_h, start_R = None, 0.0
    else:
        start_h, start_R = None, 0.0

    if start_h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_h = _rescale(h)
        start_R = R_of(start_h)

    best = start_h.copy()
    bestR = start_R
    print("base R=%.7f N=%d" % (bestR, best.size))

    rng = np.random.RandomState(987654321)

    # Start from the given construction at its own resolution (no premature
    # upsampling: that wastes budget and rarely helps on a converged shape).
    cur = best.copy()
    curR = bestR

    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        sub = min(deadline - 1.0, time.process_time() + 8.0)

        # (1) sharp direct polish
        h = _lbfgs_log(cur, 200, sub)
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h, r

        # (2) top-k plateau polishes
        for kfrac in (0.02, 0.005, 0.001):
            if time.process_time() >= sub - 0.5:
                break
            fg = (lambda hh, kf=kfrac: _fun_grad_topk(hh, kf))
            h = _lbfgs_log(cur, 120, sub, fg=fg)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r

        # (3) peak-block refinement
        if time.process_time() < sub - 0.5:
            h = _peak_polish(cur, sub, iters=2)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r

        # (4) structured perturbation + polish
        if time.process_time() < sub - 0.5:
            if rng.rand() < 0.5:
                hp = _perturb_global(cur, rng)
            else:
                hp = _perturb_peak(cur, rng)
            h = _lbfgs_log(hp, 120, sub)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r

        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
        print("it%d R=%.7f best=%.7f" % (it, curR, bestR))

        # (5) occasionally try 2x resolution
        if it % 5 == 0 and cur.size * 2 <= 1000000 and time.process_time() < deadline - 12.0:
            up = _rescale(np.repeat(cur, 2))
            upR = R_of(up)
            sub2 = min(deadline - 1.0, time.process_time() + 9.0)
            h = _lbfgs_log(up, 150, sub2)
            r = R_of(h)
            if r > upR + 1e-13:
                up, upR = h, r
            fg = (lambda hh: _fun_grad_topk(hh, 0.01))
            if time.process_time() < sub2 - 0.5:
                h = _lbfgs_log(up, 100, sub2, fg=fg)
                r = R_of(h)
                if r > upR + 1e-13:
                    up, upR = h, r
            if upR > curR + 1e-13:
                cur, curR = up, upR
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  up R=%.7f N=%d" % (curR, cur.size))

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_R + 1e-12:
        return best
    if not _same_shape(best, start_h):
        return {"best": start_h, "alternative": best}
    return start_h

