    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _fine_polish(h, deadline):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    for frac in (0.02, 0.04, 0.08):
        if time.process_time() >= deadline - 0.4:
            break
        for beta in (None, 8000.0, 20000.0):
            if time.process_time() >= deadline - 0.4:
                break
            _try(_window_polish_peak(cur, deadline, frac, 4,
                                     maxiter=300, beta=beta))
    if time.process_time() < deadline - 0.4:
        _try(_lbfgs_log(cur, maxiter=600, deadline=deadline))
    return cur, cur_r


def _prolong_mass(h, N2):
    n = h.size
    if N2 <= n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, float(n), N2 + 1)
    newc = np.interp(edges, np.arange(n + 1, dtype=float), c)
    h2 = np.diff(newc)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return np.ones(N2)
    return h2


def _block_edges(n, B):
    edges = np.linspace(0, n, B + 1).astype(int)
    edges[-1] = n
    return edges


def _block_correction(h_base, B, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h_base
    n = h_base.size
    edges = _block_edges(n, B)
    lens = np.diff(edges)
    mins = np.array([h_base[edges[b]:edges[b + 1]].min() for b in range(B)])
    lb = -mins
    idx = np.repeat(np.arange(B), lens)

    def expand(d):
        return h_base + d[idx]

    def f(d):
        h = expand(d)
        val, g = _fun_grad(h)
        gd = np.zeros(B)
        np.add.at(gd, idx, g)
        return val, gd

    d0 = np.zeros(B)
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lb[b], None) for b in range(B)],
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h_base
    if res is None:
        return h_base
    d = res.x
    h2 = np.clip(expand(d), 0.0, None)
    if h2.sum() <= 0:
        return h_base
    return _rescale(h2)


# ---------------- Experiment helpers ----------------

def _avg_pool(h, k):
    n = h.size
    m = n // k
    if m < 1:
        return h.copy()
    hh = h[:m * k].reshape(m, k)
    return hh.mean(axis=1)


def _upsample_repeat(h, N2):
    n = h.size
    if N2 <= n:
        return h.copy()
    k = int(round(N2 / n))
    if k < 1:
        k = 1
    h2 = np.repeat(h, k)
    if h2.size < N2:
        h2 = np.concatenate((h2, np.full(N2 - h2.size, h2[-1])))
    elif h2.size > N2:
        h2 = h2[:N2]
    return _rescale(h2)


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / (Lf.size - 1)


def _tilt_trim(h64, t, tau):
    n = h64.size
    x = (np.arange(n) + 0.5) / n
    h = h64 * np.exp(t * (x - 0.5))
    lo = int(round(tau * n))
    hi = n - lo
    if hi <= lo:
        return h64.copy()
    out = np.zeros(n)
    seg = h[lo:hi]
    # decide orientation: keep side with smaller mean height
    if seg.size > 1:
        half = seg.size // 2
        left_mean = seg[:half].mean() if half > 0 else 0.0
        right_mean = seg[seg.size - half:].mean() if half > 0 else 0.0
        if left_mean > right_mean:
            seg = seg[::-1]
    out[lo:hi] = seg
    if out.sum() <= 0:
        return h64.copy()
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r + 1e-12:
            best, best_r = cand.copy(), r
        elif r > alt_r + 1e-12:
            alternative, alt_r = cand.copy(), r

    n = base.size

    # Prolong to 256000 if base is smaller
    N2 = 256000
    if n < N2:
        hf = _prolong_mass(base, N2)
        hf = _rescale(hf)
    else:
        hf = base.copy()
    r0 = R_of(hf)
    print("prolonged R=%.7f (base %.7f) N=%d" % (r0, base_r, hf.size))
    cur = hf
    cur_r = r0
    _consider(cur, cur_r)

    # ---- Pool to 64k ----
    h64 = _avg_pool(hf, 4)
    h64 = _rescale(h64)
    r64 = R_of(h64)
    print("pooled 64k R=%.7f N=%d" % (r64, h64.size))

    # Baseline sharpen + peak polish at 64k
    if time.process_time() < hard_end - 20.0:
        hb = _lbfgs_log(h64, maxiter=120, deadline=hard_end - 18.0)
        rb = R_of(hb)
        if rb > r64:
            h64, r64 = hb, rb
        hp = _window_polish_peak(h64, hard_end - 16.0, 0.05, 4,
                                 maxiter=120, beta=None)
        rp = R_of(hp)
        if rp > r64:
            h64, r64 = hp, rp
    print("baseline 64k R=%.7f argmax=%.3f" % (r64, _argmax_frac(h64)))

    best64 = h64.copy()
    best64_r = r64

    # ---- Tilt + trim sweep ----
    ts = (-0.6, -0.45, -0.3, -0.15, 0.15, 0.3, 0.45, 0.6)
    taus = (0.0, 0.05, 0.10)
    for t in ts:
        for tau in taus:
            if time.process_time() >= hard_end - 12.0:
                break
            cand = _tilt_trim(h64, t, tau)
            rc = R_of(cand)
            # short beta-smoothed polish
            for beta in (32.0, 64.0):
                if time.process_time() >= hard_end - 11.0:
                    break
                hc = _lbfgs_sm(cand, beta, maxiter=80, deadline=hard_end - 10.0)
                rcc = R_of(hc)
                if rcc > rc:
                    cand, rc = hc, rcc
            if time.process_time() < hard_end - 9.0:
                hc = _lbfgs_log(cand, maxiter=100, deadline=hard_end - 8.0)
                rcc = R_of(hc)
                if rcc > rc:
                    cand, rc = hc, rcc
            if time.process_time() < hard_end - 7.0:
                hc = _window_polish_peak(cand, hard_end - 6.0, 0.05, 4,
                                         maxiter=100, beta=None)
                rcc = R_of(hc)
                if rcc > rc:
                    cand, rc = hc, rcc
            print("tilt t=%+.2f tau=%.2f R=%.7f argmax=%.3f"
                  % (t, tau, rc, _argmax_frac(cand)))
            if rc > best64_r + 1e-12:
                best64, best64_r = cand.copy(), rc
        if time.process_time() >= hard_end - 12.0:
            break

    # ---- 2 rounds of extra sharp polish on best-so-far ----
    cur64 = best64.copy()
    cur64_r = best64_r
    for rnd in range(2):
        if time.process_time() >= hard_end - 6.0:
            break
        hc = _lbfgs_log(cur64, maxiter=150, deadline=hard_end - 5.0)
        rc = R_of(hc)
        if rc > cur64_r:
            cur64, cur64_r = hc, rc
        hc = _window_polish_peak(cur64, hard_end - 4.0, 0.06, 6,
                                 maxiter=150, beta=None)
        rc = R_of(hc)
        if rc > cur64_r:
            cur64, cur64_r = hc, rc
        print("round %d 64k R=%.7f argmax=%.3f"
              % (rnd, cur64_r, _argmax_frac(cur64)))

    # ---- Upsample to 256k and polish to deadline ----
    hf2 = _upsample_repeat(cur64, N2)
    rf2 = R_of(hf2)
    print("upsampled 256k R=%.7f" % rf2)
    if rf2 > cur64_r:
        cur64, cur64_r = hf2, rf2
    _consider(cur64, cur64_r)

    if time.process_time() < hard_end - 1.0:
        hc = _lbfgs_log(cur64, maxiter=200, deadline=hard_end - 0.8)
        rc = R_of(hc)
        if rc > cur64_r:
            cur64, cur64_r = hc, rc
            _consider(cur64, cur64_r)
        print("final log R=%.7f" % cur64_r)
    if time.process_time() < hard_end - 0.5:
        hc = _window_polish_peak(cur64, hard_end - 0.3, 0.05, 8,
                                 maxiter=200, beta=None)
        rc = R_of(hc)
        if rc > cur64_r:
            cur64, cur64_r = hc, rc
            _consider(cur64, cur64_r)
        print("final peak R=%.7f" % cur64_r)

    print("final R=%.7f N=%d | base R=%.7f N=%d"
          % (best_r, best.size, base_r, base.size))

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _refine_grid(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    if m > 1000000:
        return None
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(m, dtype=float) / factor
    h_new = np.interp(x_new, x_old, h)
    return _rescale(h_new)


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return _rescale(hs)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = best.copy()

    # Stage A: sharp log-space full L-BFGS.
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, 800, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur

    # Stage B: beta sweep + peak polishes.
    for beta in (1e3, 1e4, 5e4, 2e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 32,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  peak frac=%.2f R=%.7f" % (frac, rp))
            cur = hp if rp > bestR - 0.003 else cur

    # Stage B2: refine grid, re-optimize peak region on finer grid.
    if time.process_time() < deadline - 8.0:
        hr = _refine_grid(best, 2)
        if hr is not None:
            hp = _window_polish_peak(hr, deadline, 0.10, 64, maxiter=300)
            rp = R_of(hp)
            print("refine x2 R=%.7f" % rp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                cur = hp

    # Stage B3: light smoothing perturbation + re-optimize.
    if time.process_time() < deadline - 8.0:
        for k in (3, 5, 9):
            if time.process_time() >= deadline - 6.0:
                break
            hs = _smooth(best, k)
            hs = _window_polish_peak(hs, deadline, 0.15, 64, maxiter=200)
            rs = R_of(hs)
            print("smooth k=%d R=%.7f" % (k, rs))
            if rs > bestR + 1e-12:
                best, bestR = hs, rs
                cur = hs

    # NEW Stage B4: multi-scale grid refinement. Repeatedly refine x2 and
    # polish the peak region; this recovers sub-step resolution that caps R
    # at the current grid. Each doubling roughly quadruples the effective
    # resolution of the critical peak region.
    while time.process_time() < deadline - 10.0 and best.size < 500000:
        hr = _refine_grid(best, 2)
        if hr is None:
            break
        # Polish the whole thing briefly, then the peak region harder.
        hp = _lbfgs_log(hr, 120, deadline)
        rp = R_of(hp)
        hp = _window_polish_peak(hp, deadline, 0.10, 128, maxiter=250)
        rp2 = R_of(hp)
        if rp2 > rp:
            rp = rp2
        print("multirefine R=%.7f (N=%d)" % (rp, hp.size))
        if rp > bestR + 1e-12:
            best, bestR = hp, rp
            cur = hp
        else:
            # even if not improving, keep the finer representation if close
            if rp > bestR - 5e-4:
                cur = hp
            break

    # Stage C: final sharp.
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(best, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)

    # Stage D: alternate full sharp + peak polish, with occasional smoothing.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))
        # Occasional smoothed restart seeded from best to escape flat ridges.
        if it % 3 == 0 and time.process_time() < deadline - 4.0:
            hs = _smooth(best, 5)
            hs = _window_polish_peak(hs, deadline, 0.15, 64, maxiter=200)
            rs = R_of(hs)
            if rs > bestR + 1e-13:
                best, bestR = hs, rs
                print("  alt smooth #%d R=%.7f" % (it, rs))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400, beta=0.0):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _smooth_bump(N):
    x = np.linspace(0, 1, N)
    h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
    return _rescale(h)


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _split_and_refine(h, deadline, rcur, newN):
    """Prolong to newN, then do full log-space L-BFGS + peak polish."""
    h2 = _rescale(_prolong(_rescale(h), newN))
    r2 = R_of(h2)
    # Full log-space polish
    cand = _lbfgs_log(h2, maxiter=500, deadline=deadline)
    r = R_of(cand)
    if r > r2:
        h2, r2 = cand, r
    # Peak polish at multiple scales
    h2, r2 = _polish(h2, deadline, r2, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400)
    return h2, r2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            start_r = R_of(_rescale(s.copy()))

    best = None
    best_r = -1.0
    if start_arr is not None:
        best = _rescale(start_arr.copy())
        best_r = start_r

    # Main lever: prolong start to higher resolution (65536 -> 131072 -> 262144),
    # then full log-space L-BFGS + peak polish. Higher resolution grids let the
    # optimizer find sharper, more concentrated autoconvolutions, which is what
    # pushes R up.
    if best is not None:
        for newN in (131072, 262144):
            if time.process_time() >= deadline - 12.0:
                break
            if newN <= best.size:
                continue
            cand, r = _split_and_refine(best, deadline, best_r, newN)
            print("prolong N=%d R=%.7f" % (newN, r))
            if r > best_r:
                best, best_r = cand, r

    # Then do smoothing homotopy (beta continuation) on best at its resolution.
    if best is not None:
        while time.process_time() < deadline - 6.0:
            prev = best_r
            # beta homotopy: start very smooth, decrease to sharp
            cur = best.copy()
            cur_r = best_r
            for beta in (64.0, 16.0, 4.0, 1.0):
                if time.process_time() >= deadline - 5.0:
                    break
                cand = _lbfgs_log(cur, maxiter=300, deadline=deadline, beta=beta)
                r = R_of(cand)
                if r > cur_r:
                    cur, cur_r = cand, r
            # Then sharpen with exact (non-smoothed) objective
            cand = _lbfgs_log(cur, maxiter=500, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            cur, cur_r = _polish(cur, deadline, cur_r,
                                 fracs=(0.20, 0.10, 0.05, 0.02), maxiter=400)
            if cur_r > best_r:
                best, best_r = cur, cur_r
            print("homotopy R=%.7f" % best_r)
            if best_r - prev < 1e-9:
                break

    # Final polish loop with remaining time.
    if best is not None:
        while time.process_time() < deadline - 1.5:
            prev = best_r
            cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
            best, best_r = _polish(best, deadline, best_r,
                                   fracs=(0.15, 0.08, 0.04, 0.02), maxiter=400)
            if best_r - prev < 1e-10:
                break
        print("best R=%.7f" % best_r)

    if best is None:
        return _rescale(_smooth_bump(64))

    out = {"best": _rescale(best)}
    # Alternative: a fresh smooth-bump start refined briefly, in case it helps future gens.
    if start_arr is not None and best_r <= start_r + 1e-12:
        # We didn't improve; return start as best and best as alternative
        out = {"best": _rescale(start_arr), "alternative": _rescale(best)}
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num + w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if beta is None:
            val, g = fg(hh)
        else:
            val, g = fg(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = fg(hh)
        else:
            val, g = fg(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None, fg=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta, fg=fg)


def _smooth_ramp(h, deadline, betas, per=400):
    cur = h
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cur = _lbfgs_log(cur, per, deadline, beta=beta)
    return cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best, bestR = None, 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt, altR = None, 0.0

    def consider(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))
        elif alt is None or r > altR:
            alt, altR = h, r

    # Phase 1: smooth-max ramp from current best to try to flatten the top
    if time.process_time() < deadline - 4.0:
        h = _smooth_ramp(best.copy(), deadline, (40.0, 120.0, 350.0, 900.0, 2200.0))
        h = _lbfgs_log(h, 1200, deadline)
        consider(h, "sm")

    # Phase 2: use p-norm smoothing (different from exp), tends to produce
    # flatter plateaus; p decreasing from large to moderate.
    if time.process_time() < deadline - 4.0:
        h = best.copy()
        for p in (30.0, 20.0, 12.0, 8.0):
            if time.process_time() >= deadline - 2.0:
                break
            h = _lbfgs_log(h, 500, deadline, fg=_fun_grad_pnorm)  # placeholder
        # Actually run pnorm with p as fixed arg via wrapper
        def fg_p(hh, p):
            return _fun_grad_pnorm(hh, p)
        h = best.copy()
        for p in (30.0, 18.0, 10.0, 6.0, 4.0):
            if time.process_time() >= deadline - 2.0:
                break
            h = _lbfgs_log(h, 500, deadline, beta=p, fg=fg_p)
        h = _lbfgs_log(h, 1000, deadline)
        consider(h, "pnorm")

    # Phase 3: peak-window polishing with smooth-max
    for frac, beta in ((0.15, 400.0), (0.30, 800.0), (0.50, None)):
        if time.process_time() >= deadline - 3.0:
            break
        h = _window_polish_peak(best, deadline, frac, 24, maxiter=600, beta=beta)
        h = _lbfgs_log(h, 800, deadline)
        consider(h, "win(%.2f)" % frac)

    # Phase 4: alternating full + window polish until deadline.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 1000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.45, 32, maxiter=500)
        h = _lbfgs_log(h, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None:
        startR = R_of(np.asarray(start, dtype=float))
        if bestR <= startR + 1e-12 and alt is not None and altR > 0:
            return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    # soft-max via p-norm of knots: sm = (sum Lf^p)^(1/p)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None) ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    w = (np.clip(Lf, 0, None) ** (p - 1)) / S  # d sm / d Lf
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, p=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_pnorm(hh, p)) if p > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, p=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_pnorm(hh, p)) if p > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _revive_zeros(h, frac=0.15, scale=1e-3, win=512):
    n = h.size
    out = h.copy()
    zones = [(0, int(frac * n)), (int((1.0 - frac) * n), n)]
    for lo, hi in zones:
        if hi <= lo:
            continue
        seg = out[lo:hi]
        zeros = np.flatnonzero(seg == 0.0)
        if zeros.size == 0:
            continue
        # local mean via cumulative sum over window
        cs = np.concatenate(([0.0], np.cumsum(out)))
        for z in zeros:
            a = max(0, lo + z - win // 2)
            b = min(n, lo + z + win // 2)
            m = (cs[b] - cs[a]) / max(1, b - a)
            if m > 0:
                out[lo + z] = scale * m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0

    def _try(h, tag):
        nonlocal best, bestR, alt, altR
        h = _rescale(h)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("%s R=%.7f" % (tag, r))
        elif r > altR:
            alt, altR = h.copy(), r
        return r

    cur = start_best.copy()
    curR = start_bestR
    rnd = 0
    while time.process_time() < deadline - 2.0:
        rnd += 1
        # (a) sharp log polish
        h = _lbfgs_log(cur, 200, deadline)
        if R_of(h) > curR + 1e-13:
            cur, curR = h, R_of(h)
            _try(cur, "r%d log" % rnd)

        # (b) p-norm ladder
        for p in (4, 8, 16, 32, 64):
            if time.process_time() >= deadline - 2.0:
                break
            h = _lbfgs_log(cur, 150, deadline, p=p)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r
                _try(cur, "r%d p%d" % (rnd, p))

        # (c) F183 revival
        if time.process_time() < deadline - 2.0:
            h = _revive_zeros(cur)
            h = _lbfgs_log(h, 80, deadline)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r
                _try(cur, "r%d revive" % rnd)

        # (d) full height-space block
        if time.process_time() < deadline - 2.0:
            free = np.arange(cur.size)
            h = _lbfgs_block(cur, free, 100, deadline)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r
                _try(cur, "r%d block" % rnd)

        # (e) exact 2x staircase prolongation once per round
        if time.process_time() < deadline - 2.0 and cur.size < 1000000:
            N1 = min(1000000, 2 * cur.size)
            hb = _rescale(_prolongate(cur, N1))
            hb = _lbfgs_log(hb, 150, deadline)
            rb = R_of(hb)
            if rb > curR + 1e-13:
                cur, curR = hb, rb
                _try(cur, "r%d up2x" % rnd)

        zf = float(np.mean(cur == 0.0))
        mm = float(cur.max() / max(cur.mean(), 1e-300))
        print("r%d R=%.7f zero=%.3f max/mean=%.2f N=%d"
              % (rnd, curR, zf, mm, cur.size))

        if curR < 0.9407 and rnd >= 3 and time.process_time() > deadline - 15.0:
            # stagnating; keep pushing but note it
            pass

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    # p-norm surrogate for max: ||L||_p
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None)
    mx = Lp.max()
    if mx <= 0:
        return _fun_grad(h)
    # scaled to avoid overflow
    sc = Lp / mx
    sp = sc ** p
    S = sp.sum()
    if S <= 0:
        return _fun_grad(h)
    # max approx = mx * S^(1/p)
    logm = np.log(mx) + np.log(S) / p
    # d log(max_approx)/dLf = (1/p) * (p * sc^(p-1) / mx) / S + (1/mx)*d mx/d... 
    # simpler: treat mx as constant wrt Lf locally (mx = max, gradient of max is delta at argmax)
    # Use full gradient: d/dLi [ log(mx) + log(S)/p ] where mx=max(Lf)
    # = delta_i,argmax / mx + (1/p)*(1/S)* p*sc^(p-1)*(1/mx) for the S term
    #   = delta/mx + sc^(p-1)/(S*mx)
    w = sp / S  # weights sum to 1
    gLf = -dq / num
    # gradient of log(max_approx)
    m = int(np.argmax(Lf))
    gLf[m] += 1.0 / mx
    # S term: d/dLi log(S)/p = (1/p)*(1/S)*p*sc^(p-1)*(1/mx) = sc^(p-1)/(S*mx)
    gLf += (sc ** (p - 1)) / (S * mx)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, pnorm=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if pnorm > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, pnorm))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _refine_grid(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    if m > 1000000:
        return None
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(m, dtype=float) / factor
    h_new = np.interp(x_new, x_old, h)
    return _rescale(h_new)


def _staircase_double(h):
    # exact 2x staircase doubling: repeat each cell twice, scale to keep R
    h2 = np.repeat(h, 2)
    return _rescale(h2)


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return _rescale(hs)


def _argmax_pos(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, h.size)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d) argmax=%.3f" %
          (bestR, best.size, _argmax_pos(best)))

    # ---- Experiment: exact 2x staircase doubling of start ----
    h0 = _staircase_double(best)
    r0 = R_of(h0)
