          (r0, h0.size, _argmax_pos(h0)))

    cur = h0
    curR = r0
    if r0 > bestR + 1e-13:
        best, bestR = h0, r0

    pnorm_ladder = (4, 8, 16, 32, 64, 128)
    round_idx = 0

    while time.process_time() < deadline - 3.0:
        round_idx += 1
        improved = False

        # (a) sharp
        h = _lbfgs_log(cur, 200, deadline)
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h, r
            improved = True
        if r > bestR + 1e-13:
            best, bestR = h, r

        # (b) p-norm ladder
        for p in pnorm_ladder:
            if time.process_time() >= deadline - 3.0:
                break
            hp = _lbfgs_log(cur, 120, deadline, pnorm=p)
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp
                improved = True
            if rp > bestR + 1e-13:
                best, bestR = hp, rp

        # (c) peak-window polish
        if time.process_time() < deadline - 3.0:
            hp = _window_polish_peak(cur, deadline, 0.15, 32, maxiter=150)
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp
                improved = True
            if rp > bestR + 1e-13:
                best, bestR = hp, rp

        print("round %d R=%.7f (N=%d) argmax=%.3f zeros=%.1f%%" %
              (round_idx, bestR, best.size, _argmax_pos(best),
               100.0 * np.mean(best <= 0)))

        # (d) every third round, try further 2x doubling
        if round_idx % 3 == 0 and best.size < 500000 \
                and time.process_time() < deadline - 8.0:
            hd = _staircase_double(best)
            if hd is not None and hd.size <= 1000000:
                rd = R_of(hd)
                # sharpen/p-norm-polish the doubled candidate
                hd2 = _lbfgs_log(hd, 150, deadline)
