                    hd3 = _lbfgs_log(hd2, 100, deadline, pnorm=p)
                    rd3 = R_of(hd3)
                    if rd3 > rd2:
                        hd2, rd2 = hd3, rd3
                hd2 = _window_polish_peak(hd2, deadline, 0.15, 64,
                                          maxiter=150)
                rd2 = R_of(hd2)
                print("  double R=%.7f (N=%d) argmax=%.3f" %
                      (rd2, hd2.size, _argmax_pos(hd2)))
                if rd2 > bestR + 1e-13:
                    best, bestR = hd2, rd2
                    cur, curR = hd2, rd2
                # else revert to 84992 (cur unchanged)

        if not improved and round_idx > 4:
            # small perturbation to escape flat ridges
            if time.process_time() < deadline - 5.0:
                hs = _smooth(cur, 5)
                hs = _window_polish_peak(hs, deadline, 0.15, 64, maxiter=150)
                rs = R_of(hs)
                if rs > curR + 1e-13:
                    cur, curR = hs, rs
                if rs > bestR + 1e-13:
                    best, bestR = hs, rs

    # Final sharp + peak polish on best grid
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)
        hp = _window_polish_peak(best, deadline, 0.15, 64, maxiter=200)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
