            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: resolution lifting.  The incumbent was found at N=42496; a
    # finer grid exposes new degrees of freedom that can squeeze out a bit more
    # R.  We lift to 2x and 4x resolution, polish with a soft-max surrogate
    # (beta>0) to redistribute mass, then hard L2 polish, keeping improvements.
    # This is the primary driver of the improvement over the start shape.
    N0 = best.size
    for factor in (2, 4):
        if time.process_time() >= deadline - 8.0:
            break
        N_new = N0 * factor
        if N_new > 1000000:
            break
        h = _refine_at_higher_N(best, N_new, deadline - 4.0)
        h = _window_polish_peak(h, deadline - 3.0, 0.35, 16)
        r = R_of(h)
        print("lift x%d N=%d R=%.7f" % (factor, h.size, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
            print("  accept lift R=%.7f" % bestR)

    # Soft-max basin hopping at current resolution: varied beta redistributes
    # mass across the peak region and can escape the hard-max local minimum.
    rng = np.random.default_rng(4242)
    betas = [5.0, 10.0, 20.0, 40.0, 80.0]
    trial = 0
    while time.process_time() < deadline - 3.0:
        beta = float(rng.choice(betas))
        hb = _perturb_blur(best, float(rng.choice([1.0, 2.0, 4.0, 8.0])))
        hb = _rescale(hb)
        if hb.sum() <= 0:
            continue
        hb = _lbfgs_log(hb, 400, deadline, beta=beta)
        if time.process_time() >= deadline - 2.0:
            break
        hb = _lbfgs_log(hb, 400, deadline)
        hb = _window_polish_peak(hb, deadline, 0.30, 12)
        r = R_of(hb)
        trial += 1
        if r > bestR + 1e-12:
            best, bestR = hb, r
            print("  accept beta=%.0f trial=%d R=%.7f" % (beta, trial, bestR))

    # Final hard polish: full-resolution L2 plus peak window, alternating.
    stall = 0
    while time.process_time() < deadline - 0.8:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.2:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


# ---------- multiscale block helpers ----------

def _block_average(h, N0):
    """Mass-preserving block-average of h (length N) to length N0."""
    N = h.size
    if N == N0:
        return h.copy()
    edges = np.linspace(0, N, N0 + 1)
    out = np.zeros(N0)
    for i in range(N0):
        a = int(round(edges[i])); b = int(round(edges[i + 1]))
        if b <= a:
            b = a + 1
        out[i] = h[a:b].sum()
    return out


def _escalate_2x(h):
    """Exact 2x mass-preserving repeat/scale: h -> [h/2, h/2] interleaved.
    We use simple repeat then halve so mass preserved and shape refined."""
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out * 0.5


def _random_sparse_seed(N0, rng):
    nb = int(rng.integers(12, 41))
    widths = np.exp(rng.uniform(np.log(2.0), np.log(N0 / 4.0), size=nb))
    widths = widths / widths.sum() * N0
    widths = np.maximum(widths, 1.0)
    # place blocks sequentially
    h = np.zeros(N0)
    pos = 0.0
    heights = np.exp(rng.uniform(np.log(0.1), np.log(10.0), size=nb))
    for i in range(nb):
        w = widths[i]
        a = int(round(pos)); b = int(round(pos + w))
        if b <= a:
            b = a + 1
        b = min(b, N0)
        if a >= N0:
            break
        h[a:b] = heights[i]
        pos += w
    if h.sum() <= 0:
        h[:] = 1.0
    return h


def _staircase_to(h, N_target):
    """Mass-preserving staircase (block-average style) from h to N_target."""
    n = h.size
    if n == N_target:
        return h.copy()
    edges = np.linspace(0, n, N_target + 1)
    out = np.zeros(N_target)
    for i in range(N_target):
        a = int(round(edges[i])); b = int(round(edges[i + 1]))
        if b <= a:
            b = a + 1
        out[i] = h[a:b].sum() * (n / N_target) if False else h[a:b].sum()
    return out


def _escalate_through(h, levels, deadline, bestH, bestRH, per_level_iters=100):
    """Escalate h through levels, polishing at each level. Returns best (h,R)."""
    cur = h.copy()
    for N in levels:
        if time.process_time() >= deadline - 0.5:
            break
        if cur.size != N:
            cur = _staircase_to(cur, N)
        cur = _rescale(cur)
        # sharp
        sub = min(deadline, time.process_time() + 3.0)
        hs = _lbfgs_log(cur, per_level_iters, sub)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
        cur = hs
        # beta ladder
        for beta in (1e2, 1e3, 1e5, 1e6):
            if time.process_time() >= deadline - 0.5:
                break
            sub = min(deadline, time.process_time() + 2.0)
            hb = _lbfgs_log(cur, 80, sub, beta=beta)
            rb = R_of(hb)
            if rb > bestRH + 1e-13:
                bestH, bestRH = hb.copy(), rb
            cur = hb
        # peak polish
        if time.process_time() < deadline - 0.5:
            sub = min(deadline, time.process_time() + 2.0)
            hp, rp = _peak_polish(cur, R_of(cur), 100, sub)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
            cur = hp
    return bestH, bestRH, cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    N_final = best.size
    N0 = max(64, N_final // 16)

    # ---- build seeds ----
    seeds = []
    # (a) coarsened start at N0, 2*N0, 4*N0
    for Ns in (N0, 2 * N0, 4 * N0):
        if Ns <= N_final:
            seeds.append(_block_average(best, Ns))
    # (b) random sparse block arrays at N0=2048, staircased to N0
    rng = np.random.default_rng(12345)
    Nr = 2048
    for _ in range(24):
        hr = _random_sparse_seed(Nr, rng)
        if N0 != Nr:
            hr = _staircase_to(hr, N0)
        seeds.append(hr)

    levels = [N0, 2 * N0, 4 * N0, 8 * N0, 16 * N0]
    levels = [L for L in levels if L <= N_final]
    if not levels or levels[-1] != N_final:
        levels.append(N_final)

    # ---- first pass: ~1.2s per seed ----
    seed_results = []
    n_seeds = len(seeds)
    for si, seed in enumerate(seeds):
        if time.process_time() >= deadline - 3.0:
            break
        seed_deadline = min(deadline - 2.0, time.process_time() + 1.2)
        try:
            hb, rb, _ = _escalate_through(seed, levels, seed_deadline,
                                          best.copy(), bestR)
        except Exception:
            continue
        if rb > bestR + 1e-13:
            best, bestR = hb.copy(), rb
        seed_results.append((rb, hb))
        print("seed %d/%d R=%.7f (best %.7f)" % (si + 1, n_seeds, rb, bestR))

    # ---- repolish best 3 distinct seeds + start ----
    seed_results.sort(key=lambda x: -x[0])
    top = []
    for rb, hb in seed_results:
        if len(top) >= 3:
            break
        # distinctness: skip near-duplicates by R
        if all(abs(rb - r2) > 1e-9 for r2, _ in top):
            top.append((rb, hb))
    top.append((start_bestR, start_best))

    # full-resolution polish loop on the top candidates
    loop_end = t0 + budget_seconds * 0.88
    roundN = 0
    ladder = (4, 8, 16, 32, 64, 128)
    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 2.0:
        roundN += 1
        improved = False
        for rb, hb in top:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 2.0:
                break
            cur = hb
            if cur.size != N_final:
                cur = _staircase_to(cur, N_final)
            cur = _rescale(cur)
            sub = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(cur, 200, sub)
            rs = R_of(hs)
            if rs > bestR + 1e-13:
                best, bestR = hs.copy(), rs
                improved = True
            cur = hs
            for beta in (1e2, 1e3, 1e5):
                if time.process_time() >= loop_end - 1.5:
                    break
                sub = min(loop_end, time.process_time() + 2.0)
                hb2 = _lbfgs_log(cur, 80, sub, beta=beta)
                rb2 = R_of(hb2)
                if rb2 > bestR + 1e-13:
                    best, bestR = hb2.copy(), rb2
                    improved = True
                cur = hb2
            if time.process_time() < loop_end - 1.0:
                sub = min(loop_end, time.process_time() + 2.0)
                hp, rp = _peak_polish(cur, R_of(cur), 100, sub)
                if rp > bestR + 1e-13:
                    best, bestR = hp.copy(), rp
                    improved = True
        # p-norm homotopy on best
        for p in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 2.0:
                break
            sub = min(loop_end, time.process_time() + 3.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(best, 150, sub, fg=fg)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                improved = True
        print("round %d R=%.7f" % (roundN, bestR))
        if not improved and roundN > 2:
            break

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 300, deadline - 0.5)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        print("final sharp R=%.7f" % bestR)

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

