    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _refine(h, r, deadline, tag):
    """Refine with smoothing continuation (beta ramp) then exact polish."""
    for beta in (64.0, 256.0, 1024.0, 4096.0):
        if time.process_time() >= deadline - 1.5:
            break
        c = _lbfgs_log(h, maxiter=200, deadline=deadline, beta=beta)
        rc = R_of(c)
        if rc > r:
            h, r = c, rc
    if time.process_time() < deadline - 1.5:
        c = _lbfgs_log(h, maxiter=300, deadline=deadline)
        rc = R_of(c)
        if rc > r:
            h, r = c, rc
    if time.process_time() < deadline - 1.5:
        c, rc = _polish(h, deadline, r,
                        fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if rc > r:
            h, r = c, rc
    print("  %s R=%.6f" % (tag, r))
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    # Phase 1: work on the start construction directly (it is already strong).
    if start_arr is not None:
        cur = start_arr.copy()
        cur_r = start_r
        print("start base R=%.6f N=%d" % (cur_r, cur.size))

        # Smoothing continuation + polish on start.
        cur, cur_r = _refine(cur, cur_r, deadline, "start-refine")
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

        # Try slight prolongation + refine to escape local structure.
        n0 = cur.size
        for factor in (2,):
            if time.process_time() >= deadline - 3.0:
                break
            m = min(n0 * factor, 1000000)
            if m == n0:
                continue
            cand = _rescale(_prolong(cur, m))
            rc = R_of(cand)
            if rc > cur_r:
                cur, cur_r = cand, rc
            cur, cur_r = _refine(cur, cur_r, deadline, "prolonged N=%d" % m)
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        # Repeated polish rounds until budget.
        while time.process_time() < deadline - 2.0:
            c, rc = _polish(cur, deadline, cur_r,
                            fracs=(0.20, 0.10, 0.05, 0.02, 0.01), maxiter=400)
            if rc <= cur_r + 1e-12:
                break
            cur, cur_r = c, rc
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
            print("  polish R=%.6f" % cur_r)

    if best is None:
        # No start: build a reasonable seed.
        N0 = 256
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)
        best, best_r = _refine(best, best_r, deadline, "seed")

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    best = _rescale(best)
    if start_arr is not None:
        if start_r >= best_r:
            # Return start as best; provide refined-alt if genuinely different.
            if not np.array_equal(best, start_arr) and best_r > start_r - 1e-9:
                return {"best": _rescale(start_arr), "alternative": best}
            return _rescale(start_arr)
        return {"best": best, "alternative": _rescale(start_arr)}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat(h, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    if lam > 0:
        g = Lf[1:-1]
        mu = g.mean()
        d = g - mu
        var = np.mean(d * d)
        val = val + lam * np.log(var + 1e-300)
        if var > 0:
            gLf[1:-1] += lam * (2.0 * d / (g.size * var))
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _variance(h):
    Lf = _knots(h)
    g = Lf[1:-1]
    mu = g.mean()
    return float(np.mean((g - mu) ** 2))


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d var=%.3e" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0, _variance(best)))

    bestH = best.copy()
    bestRH = bestR

    # ---- global variance (flatness) penalty ladder with sharp/peak interleaving ----
    ladder = (8.0, 4.0, 2.0, 1.0, 0.5, 0.25, 0.0)
    loop_end = t0 + budget_seconds * 0.86

    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 4.0:
        for lam in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 4.0:
                break
            sub_deadline = min(loop_end, time.process_time() + 8.0)
            fg = (lambda hh, _l=lam: _fun_grad_flat(hh, _l))
            h = _lbfgs_log(bestH, 150, sub_deadline, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            mx, m, near = _stats(bestH)
            print("  lam=%.2f R=%.7f var=%.3e Lmax=%.6e near0.1%%=%d" %
                  (lam, bestRH, _variance(bestH), mx, near))

            if time.process_time() >= loop_end - 1.0:
                break
            sub2 = min(loop_end, time.process_time() + 6.0)
            hs = _lbfgs_log(bestH, 150, sub2)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
            print("  lam=%.2f sharp R=%.7f" % (lam, bestRH))
            bestH, bestRH = _peak_polish(bestH, bestRH, 150, sub2)
            print("  lam=%.2f peak R=%.7f" % (lam, bestRH))

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 300, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d var=%.3e" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near, _variance(best)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

