        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _perturb_peak(h, rng, scale=0.05):
    h = h.copy()
    n = h.size
    lo, hi = _peak_region(h, tol=0.98)
    pad = max(4, int(0.12 * n))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    W = hi - lo + 1
    if W < 4:
        return h
    nmodes = int(rng.integers(1, 4))
    x = np.linspace(0.0, 1.0, W)
    mod = np.ones(W)
    for _ in range(nmodes):
        k = int(rng.integers(1, 5))
        amp = rng.normal(0.0, scale)
        phase = rng.uniform(0, 2 * np.pi)
        mod *= (1.0 + amp * np.sin(2 * np.pi * k * x + phase))
    mod = np.clip(mod, 0.5, 1.5)
    h[lo:hi + 1] *= mod
    return _rescale(h)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _pnorm_continuation(h, deadline, plist):
    for p in plist:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_log(h, maxiter=300, deadline=deadline, pnorm=p)
        if R_of(c) >= R_of(h):
            h = c
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=2000, deadline=hard_end)
        return cur

    cur = best.copy()
    cur_r = best_r
    best = cur.copy()
    best_r = cur_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand.copy(), r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # Stage 1: p-norm continuation (better than log-sum-exp for sharp maxima),
    # then exact polish. This is a genuinely different smoothing path.
    h = cur.copy()
    plist = [64.0, 32.0, 16.0, 8.0, 4.0, 2.0]
    h = _pnorm_continuation(h, hard_end, plist)
    if time.process_time() < hard_end - 0.5:
        c = _lbfgs_log(h, maxiter=500, deadline=hard_end, pnorm=0.0)
        if R_of(c) >= R_of(h):
            h = c
    _consider(h, R_of(h))
    print("pnorm R=%.6f N=%d" % (best_r, best.size))

    # Stage 2: block polishing of peak region (finer control than whole-vector log param)
    try:
        while time.process_time() < hard_end - 1.0:
            lo, hi = _peak_region(best, tol=0.99)
            pad = max(8, int(0.05 * best.size))
            lo = max(0, lo - pad)
            hi = min(best.size - 1, hi + pad)
            free = np.arange(lo, hi + 1)
            h = _lbfgs_block(best, free, maxiter=300, deadline=hard_end, pnorm=0.0)
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("block R=%.6f" % best_r)
    except Exception:
        pass

    # Stage 3: peak-window modulation experiments with p-norm polish
    seed = 0
    while time.process_time() < hard_end - 1.0:
        rng_s = np.random.default_rng(7000 + seed)
        h = _perturb_peak(cur, rng_s, scale=0.04)
        h = _pnorm_continuation(h, hard_end, [16.0, 4.0, 1.0])
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=300, deadline=hard_end, pnorm=0.0)
            if R_of(c) >= R_of(h):
                h = c
        _consider(h, R_of(h))
        seed += 1
    print("peak R=%.6f" % best_r)

    if start_arr is not None and R_of(start_arr) > best_r:
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.1:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.05)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.1:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.05)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 0.2:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


# ---------- multiscale block helpers ----------

def _block_average(h, N0):
    """Mass-preserving block-average of h (length N) to length N0."""
    N = h.size
    if N == N0:
        return h.copy()
    edges = np.linspace(0, N, N0 + 1)
    out = np.zeros(N0)
    for i in range(N0):
        a = int(round(edges[i])); b = int(round(edges[i + 1]))
        if b <= a:
            b = a + 1
        out[i] = h[a:b].sum()
    return out


def _escalate_2x(h):
    """Exact 2x mass-preserving repeat/scale: h -> [h/2, h/2] interleaved."""
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out * 0.5


def _random_sparse_seed(N0, rng):
    nb = int(rng.integers(8, 31))
    widths = np.exp(rng.uniform(np.log(2.0), np.log(N0 / 4.0), size=nb))
    widths = widths / widths.sum() * N0
    widths = np.maximum(widths, 1.0)
    h = np.zeros(N0)
    pos = 0.0
    heights = np.exp(rng.uniform(np.log(0.1), np.log(10.0), size=nb))
    for i in range(nb):
        w = widths[i]
        a = int(round(pos)); b = int(round(pos + w))
        if b <= a:
            b = a + 1
        b = min(b, N0)
        if a >= N0:
            break
        h[a:b] = heights[i]
        pos += w
    if h.sum() <= 0:
        h[:] = 1.0
    # zero out 30-70% of cells
    frac = rng.uniform(0.3, 0.7)
    nz = int(N0 * frac)
    if nz > 0:
        idx = rng.choice(N0, size=nz, replace=False)
        h[idx] = 0.0
    if h.sum() <= 0:
        h[:] = 1.0
    return h


def _gauss_smooth_seed(N0, sigma, rng):
    x = rng.uniform(0.0, 1.0, size=N0)
    # random walk
    w = np.cumsum(rng.normal(0, 1, size=N0))
    w = w - w.min()
    w = w / (w.max() + 1e-12)
    # gaussian smooth
    if sigma > 0:
        k = int(max(1, round(4 * sigma)))
        xs = np.arange(-k, k + 1)
        ker = np.exp(-0.5 * (xs / sigma) ** 2)
        ker /= ker.sum()
        w = np.convolve(w, ker, mode='same')
    w = np.clip(w, 0, None)
    if w.sum() <= 0:
        w[:] = 1.0
    return w


def _perturb_seed(base, rng, scale=0.3):
    h = base.copy()
    noise = np.exp(rng.normal(0, scale, size=h.size))
    h = h * noise
    return _rescale(h)


def _staircase_to(h, N_target):
    n = h.size
    if n == N_target:
        return h.copy()
    edges = np.linspace(0, n, N_target + 1)
    out = np.zeros(N_target)
    for i in range(N_target):
        a = int(round(edges[i])); b = int(round(edges[i + 1]))
        if b <= a:
            b = a + 1
        out[i] = h[a:b].sum()
    return out


def _escalate_through(h, levels, deadline, bestH, bestRH, per_level_iters=80):
    cur = h.copy()
    for N in levels:
        if time.process_time() >= deadline - 0.3:
            break
        if cur.size != N:
            cur = _staircase_to(cur, N)
        cur = _rescale(cur)
        sub = min(deadline, time.process_time() + 2.0)
        hs = _lbfgs_log(cur, per_level_iters, sub)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
        cur = hs
        if time.process_time() < deadline - 0.3:
            sub = min(deadline, time.process_time() + 1.0)
            hp, rp = _peak_polish(cur, R_of(cur), 60, sub)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
            cur = hp
    return bestH, bestRH, cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    N_final = best.size
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    # ---- (1) Baseline coarsened images ----
    N0 = 1024
    coarse_start = _block_average(best, N0)
    coarse_start = _rescale(coarse_start)
    coarse_startR = R_of(coarse_start)
    print("coarse baseline N0=%d R=%.7f" % (N0, coarse_startR))
    if N0 * 2 <= N_final:
        cs2 = _rescale(_block_average(best, 2 * N0))
        print("coarse baseline N0=%d R=%.7f" % (2 * N0, R_of(cs2)))

    # ---- (2) Coarse restarts at N0=1024 ----
    rng = np.random.default_rng(20240123)
    coarse_candidates = []  # (R, h)

    def _try_coarse(h_seed, cap=0.12, iters=60):
        if time.process_time() >= deadline - 5.0:
            return
        h_seed = _rescale(np.clip(h_seed, 0, None))
        sub = min(deadline - 4.0, time.process_time() + cap)
        h = _lbfgs_log(h_seed, iters, sub)
        r = R_of(h)
        coarse_candidates.append((r, h))

    # 60 random sparse
    for _ in range(60):
        if time.process_time() >= deadline - 5.0:
            break
        _try_coarse(_random_sparse_seed(N0, rng))
    # 30 gaussian-smoothed
    for sigma in (2.0, 8.0, 32.0):
        for _ in range(10):
            if time.process_time() >= deadline - 5.0:
                break
            _try_coarse(_gauss_smooth_seed(N0, sigma, rng))
    # 30 perturbations of coarsened start
    for _ in range(30):
        if time.process_time() >= deadline - 5.0:
            break
        _try_coarse(_perturb_seed(coarse_start, rng, scale=0.3))

    # include the coarse baseline itself
    coarse_candidates.append((coarse_startR, coarse_start.copy()))

    coarse_candidates.sort(key=lambda x: -x[0])

    # dedupe on R and zero pattern
    def _zeropattern(h):
        return tuple(np.flatnonzero(h <= 1e-12).tolist()[:50])

    top_coarse = []
    seen_R = []
    seen_zp = []
    for r, h in coarse_candidates:
        if len(top_coarse) >= 6:
            break
        zp = _zeropattern(h)
        if any(abs(r - r2) < 1e-10 for r2 in seen_R):
            continue
        if zp in seen_zp:
            continue
        top_coarse.append((r, h))
        seen_R.append(r)
        seen_zp.append(zp)

    print("top coarse R values: %s" % ", ".join("%.7f" % r for r, _ in top_coarse))
    n_beat = sum(1 for r, _ in top_coarse if r > coarse_startR + 1e-10)
    print("seeds beating coarse baseline: %d/%d" % (n_beat, len(top_coarse)))

    # ---- (3) Escalate top 6 through levels ----
    levels = [2 * N0, 4 * N0, 8 * N0, 16 * N0, 32 * N0]
    levels = [L for L in levels if L <= N_final]
    if not levels or levels[-1] != N_final:
        levels.append(N_final)

    escalated = []
    per_seed_budget = 5.0
    for r0, h0 in top_coarse:
        if time.process_time() >= deadline - 8.0:
            break
        seed_deadline = min(deadline - 6.0, time.process_time() + per_seed_budget)
        try:
            hb, rb, _ = _escalate_through(h0, levels, seed_deadline,
                                          best.copy(), bestR)
        except Exception:
            continue
        escalated.append((rb, hb))
        if rb > bestR + 1e-13:
            best, bestR = hb.copy(), rb
        print("escalated seed R=%.7f (best %.7f)" % (rb, bestR))

    # ---- (4) Repolish best 2 seeds + start ----
    all_cands = escalated + [(start_bestR, start_best)]
    all_cands.sort(key=lambda x: -x[0])
    top2 = []
    for r, h in all_cands:
        if len(top2) >= 2:
            break
        if all(abs(r - r2) > 1e-9 for r2, _ in top2):
            top2.append((r, h))
    if not top2:
        top2 = [(start_bestR, start_best)]

    loop_end = t0 + budget_seconds * 0.88
    ladder_p = (4, 8, 16, 32, 64)
    ladder_beta = (1e2, 1e3, 1e5, 1e6)
    roundN = 0
    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 2.0:
        roundN += 1
        improved = False
        for rb, hb in top2:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 2.0:
                break
            cur = hb
            if cur.size != N_final:
                cur = _staircase_to(cur, N_final)
            cur = _rescale(cur)
            sub = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(cur, 200, sub)
            rs = R_of(hs)
            if rs > bestR + 1e-13:
