        fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
        hp = _lbfgs_log(h, 120, min(deadline, time.process_time() + 4.0), fg=fg)
        Rp = R_of(hp)
        if Rp > R:
            h, R = hp, Rp
        stage(h, R, "p%d" % p)

    # Beta-softmax polishes + peak windows
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 4.0:
            break
        fg = (lambda hh, _b=beta: _fun_grad_beta(hh, _b))
        hb = _lbfgs_log(h, 120, min(deadline, time.process_time() + 4.0), fg=fg)
        Rb = R_of(hb)
        if Rb > R:
            h, R = hb, Rb
        stage(h, R, "beta%.0e" % beta)
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hw = _window_polish_peak(h, min(deadline, time.process_time() + 3.0),
                                     frac, 32, maxiter=120)
            Rw = R_of(hw)
            if Rw > R:
                h, R = hw, Rw
            stage(h, R, "win%.2f" % frac)

    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        if time.process_time() < deadline - 2.0:
            hh = _lbfgs_log(h, 150, min(deadline, time.process_time() + 5.0))
            Rh = R_of(hh)
            if Rh > R:
                h, R = hh, Rh
        if time.process_time() < deadline - 2.0:
            fg = (lambda hh: _fun_grad_pnorm(hh, 256))
            hh = _lbfgs_log(h, 100, min(deadline, time.process_time() + 3.0), fg=fg)
            Rh = R_of(hh)
            if Rh > R:
                h, R = hh, Rh
        if time.process_time() < deadline - 2.0:
            hh = _window_polish_peak(h, min(deadline, time.process_time() + 3.0),
                                     0.10, 32, maxiter=120)
            Rh = R_of(hh)
            if Rh > R:
                h, R = hh, Rh
        stage(h, R, "alt%d" % it)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline, frac=0.15):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * frac))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def _refine(h, deadline, rounds=6, maxiter=200):
    """Iteratively polish the peak region and full-support log-LBFGS."""
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        prev = bestR
        if time.process_time() < deadline - 1.0:
            h = _lbfgs_log(h, maxiter, min(deadline - 0.5, time.process_time() + 5.0))
            r = R_of(h)
            if r > bestR:
                bestR = r
        if time.process_time() < deadline - 1.0:
            h, r = _peak_polish(h, bestR, maxiter, min(deadline - 0.5, time.process_time() + 5.0))
            if r > bestR:
                bestR = r
        if bestR - prev < 1e-12:
            break
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # Phase 1: long full-support log-LBFGS refinement on start.
    # The key improvement: the previous program only did short 4-5s bursts.
    # We give the start a long careful polish first, then alternate.
    if time.process_time() < deadline - 2.0:
        sub = min(deadline - 1.0, time.process_time() + (deadline - time.process_time()) * 0.45)
        h = _lbfgs_log(bestH, 400, sub)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  long-polish R=%.7f" % bestRH)

    # Phase 2: peak-region polish with wider window, more iters.
    if time.process_time() < deadline - 2.0:
        h, r = _peak_polish(bestH, bestRH, 400,
                            min(deadline - 1.0, time.process_time() + 8.0), frac=0.10)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  peak-wide R=%.7f" % bestRH)

    # Phase 3: alternate p-norm smoothing and sharpening to escape local min of the max.
    ladder = (2, 4, 8, 16, 32, 64, 128)
    round_p = 0
    while time.process_time() < deadline - 3.0:
        improved = False
        p = ladder[round_p % len(ladder)]
        round_p += 1
        if time.process_time() < deadline - 2.5:
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            sub = min(deadline - 1.5, time.process_time() + 6.0)
            h = _lbfgs_log(bestH, 150, sub, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
                improved = True
            print("  p=%d R=%.7f" % (p, bestRH))

        # After p-norm, do a full objective polish (this is what locks in gains).
        if time.process_time() < deadline - 2.0:
            sub = min(deadline - 1.0, time.process_time() + 4.0)
            h = _lbfgs_log(bestH, 150, sub)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
                improved = True

        if time.process_time() < deadline - 2.0:
            bestH, bestRH = _peak_polish(bestH, bestRH, 150,
                                         min(deadline - 1.0, time.process_time() + 4.0))
            print("  peak R=%.7f" % bestRH)

        if not improved and time.process_time() > deadline - 6.0:
            break

    # Phase 4: final intensive refine on remaining time.
    if time.process_time() < deadline - 1.0:
        bestH, bestRH = _refine(bestH, deadline, rounds=10, maxiter=200)
        print("  final-refine R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

