        # accept only if exact R improved (or keep as warm start)
        r = R_of(h)
        if r > curR + 1e-15:
            cur, curR = h, r
            print("pnorm p=%.0f R=%.7f" % (p, curR))
        else:
            # still use as warm start for next stage
            cur = h
        h = _window_polish_peak(cur, deadline, 0.30, 16, maxiter=300, fg=fg)
        r = R_of(h)
        if r > curR + 1e-15:
            cur, curR = h, r
            print("pnorm-win p=%.0f R=%.7f" % (p, curR))

    if curR > bestR + 1e-15:
        best, bestR = cur.copy(), curR

    # Stage 2: exact-objective polish at current resolution.
    for frac, extra in ((0.15, 8), (0.30, 16), (0.50, 32), (0.80, 64)):
        if time.process_time() >= deadline - 3.0:
            break
        h = _lbfgs_log(cur, 600, deadline)
        r = R_of(h)
        if r > curR + 1e-15:
            cur, curR = h, r
        h = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
        r = R_of(h)
        if r > curR + 1e-15:
            cur, curR = h, r
            print("polish(%.2f) R=%.7f" % (frac, curR))

    if curR > bestR + 1e-15:
        best, bestR = cur.copy(), curR

    # Stage 3: go finer.
    factors = [2, 3, 4, 6]
    for fac in factors:
        if time.process_time() >= deadline - 6.0:
            break
        Nf = min(Nmax, best.size * fac)
        if Nf <= best.size:
            continue
        hf = _prolongate(best, Nf)
        hf = _rescale(hf)
        # smooth-max polish at finer resolution
        fg = lambda hh: _fun_grad_pnorm(hh, 16.0)
        hf = _lbfgs_log(hf, 300, deadline, fg=fg)
        hf = _lbfgs_log(hf, 300, deadline)
        hf = _window_polish_peak(hf, deadline, 0.30, 16, maxiter=300)
        r = R_of(hf)
        print("fine x%d (N=%d) R=%.7f" % (fac, Nf, r))
        if r > bestR + 1e-12:
            best, bestR = hf, r

    # Stage 4: final alternating loop.
    stall = 0
    fac_idx = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _lbfgs_log(best, 900, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24, maxiter=500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 8.0:
                fac = factors[fac_idx % len(factors)]
                fac_idx += 1
                Nf = min(Nmax, best.size * fac)
                if Nf > best.size:
                    hf = _prolongate(best, Nf)
                    hf = _rescale(hf)
                    hf = _lbfgs_log(hf, 300, deadline)
                    r = R_of(hf)
                    if r > bestR + 1e-12:
                        best, bestR = hf, r
                        improved = True
                        print("stall-fine x%d R=%.7f" % (fac, bestR))
            if stall >= 4:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline, frac=0.15):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * frac))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def _landweber_target(h, T, iters, eta_scale=0.4):
    """Projected Landweber on h to fit h*h to target T (length n+1)."""
    h = np.clip(h, 0, None).copy()
    n = h.size
    if T.size != n + 1:
        return h
    mx = h.max()
    eta = eta_scale / (4.0 * mx + 1e-12)
    for _ in range(iters):
        L = _knots(h)
        # residual on interior knots (length n-1)
        res = L[1:-1] - T[1:-1]
        # gradient of 0.5||h*h - T||^2 wrt h: 2*corr(h, res)
        if n > 1500:
            g = 2.0 * fftconvolve(res, h[::-1], mode='full')[:n]
        else:
            g = 2.0 * np.correlate(res, h, mode='full')[:n]
        h = np.clip(h - eta * g, 0.0, None)
        if h.sum() <= 0:
            return h
    return h


def _make_flat_target(L, factor):
    n1 = L.size
    mean = L.mean()
    c = factor * mean
    T = np.full(n1, c)
    # preserve total mass of L
    sL = L.sum()
    sT = T.sum()
    if sT > 0:
        T *= sL / sT
    return T


def _make_clip_target(L, q, lam):
    mx = L.max()
    if mx <= 0:
        return L.copy()
    excess = np.maximum(L - q * mx, 0.0)
    Lc = L - lam * excess
    sL = L.sum()
    sLc = Lc.sum()
    if sLc > 0:
        Lc = Lc * (sL / sLc)
    return Lc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Target-refit family ----
    L0 = _knots(bestH)
    targets = []
    for c in (1.0, 1.15, 1.3, 1.5):
        targets.append(("flat%.2f" % c, _make_flat_target(L0, c)))
    for q in (0.90, 0.95, 0.98):
        for lam in (0.5, 1.0):
            targets.append(("clip%.2f_%.1f" % (q, lam),
                            _make_clip_target(L0, q, lam)))

    refit_budget = t0 + budget_seconds * 0.45
    results = []
    for name, T in targets:
        if time.process_time() >= refit_budget - 1.0:
            break
        sub = min(refit_budget, time.process_time() + 6.0)
        h = _landweber_target(bestH, T, 40, eta_scale=0.4)
        if h.sum() <= 0:
            continue
        h = _rescale(h)
        r0 = R_of(h)
        h2 = _lbfgs_log(h, 120, sub)
        r1 = R_of(h2)
        h3, r2 = _peak_polish(h2, r1, 120, sub, frac=0.10)
        cand, rc = (h3, r2) if r2 >= r1 else (h2, r1)
        results.append((name, r0, rc))
        print("  refit %-14s R0=%.7f -> R=%.7f" % (name, r0, rc))
        if rc > bestRH + 1e-13:
            bestH, bestRH = cand.copy(), rc
            mx, m, near = _stats(bestH)
            print("    new best R=%.7f Lmax=%.6e near0.1%%=%d" %
                  (bestRH, mx, near))

    # ---- Cycle best two parameters with sharp + p-norm polish ----
    results.sort(key=lambda x: -x[2])
    top = results[:2] if len(results) >= 2 else results
    loop_end = t0 + budget_seconds * 0.86
    ladder = (8, 32, 128)
    roundN = 0
    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 4.0:
        roundN += 1
        for name, T in [(n, t) for (n, _, _) in top for t in [_target_lookup(n, L0)]]:
            pass
        # rebuild targets for top names
        for (name, _, _) in top:
            if time.process_time() >= loop_end - 1.5:
                break
            T = _target_by_name(name, L0)
            sub = min(loop_end, time.process_time() + 5.0)
            h = _landweber_target(bestH, T, 30, eta_scale=0.4)
            h = _rescale(h)
            h2 = _lbfgs_log(h, 80, sub)
            r2 = R_of(h2)
            if r2 > bestRH + 1e-13:
                bestH, bestRH = h2.copy(), r2
            for p in ladder:
                if time.process_time() >= loop_end - 1.5:
                    break
                sub2 = min(loop_end, time.process_time() + 4.0)
                fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
                hp = _lbfgs_log(bestH, 100, sub2, fg=fg)
                rp = R_of(hp)
                if rp > bestRH + 1e-13:
                    bestH, bestRH = hp.copy(), rp
            bestH, bestRH = _peak_polish(bestH, bestRH, 120, loop_end, frac=0.10)
            print("  R%d %-14s R=%.7f" % (roundN, name, bestRH))

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 300, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}


def _target_by_name(name, L0):
    if name.startswith("flat"):
        c = float(name[4:])
        return _make_flat_target(L0, c)
    # clip
    body = name[4:]
    qs, lams = body.split("_")
    return _make_clip_target(L0, float(qs), float(lams))


def _target_lookup(name, L0):
    return _target_by_name(name, L0)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    startR = bestR
    alt = None
    altR = 0.0

    # Phase 1: smooth (beta>0) polish at current resolution.
    if time.process_time() < deadline - 20.0:
        for beta in (200.0, 1000.0, 4000.0):
            if time.process_time() >= deadline - 15.0:
                break
            hb = _lbfgs_log(best, 200, deadline, beta=beta)
            r = R_of(hb)
            print("beta=%.0f R=%.7f" % (beta, r))
            if r > bestR + 1e-15:
                best, bestR = hb, r
        he = _lbfgs_log(best, 400, deadline)
        r = R_of(he)
        if r > bestR + 1e-15:
            best, bestR = he, r
        elif alt is None or r > altR:
            alt, altR = he, r

    # Phase 2: prolongate to higher resolution (up to 1e6) and polish.
    for factor in (2, 2):
        if time.process_time() >= deadline - 8.0:
            break
        N1 = min(best.size * factor, 1000000)
        if N1 <= best.size:
            break
        hf = _rescale(_prolongate(best, N1))
        print("prolongated to N=%d, R=%.7f" % (hf.size, R_of(hf)))
        hf = _lbfgs_log(hf, 300, deadline)
        r = R_of(hf)
        print("prolongated polish R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = hf, r
        elif alt is None or r > altR:
            alt, altR = hf, r

    # NEW Phase 2b: smooth-beta polish at the *higher* resolution, which
    # the original program never did (it only did exact polish after
    # prolongation). This can break out of the kinked-max local minimum.
    if time.process_time() < deadline - 6.0:
        for beta in (500.0, 2000.0, 8000.0):
            if time.process_time() >= deadline - 4.0:
                break
            hb = _lbfgs_log(best, 250, deadline, beta=beta)
            r = R_of(hb)
            print("hi-beta=%.0f R=%.7f" % (beta, r))
            if r > bestR + 1e-15:
                best, bestR = hb, r
                print("hi-beta improved R=%.7f" % bestR)
            elif alt is None or r > altR:
                alt, altR = hb, r
        he = _lbfgs_log(best, 400, deadline)
        r = R_of(he)
        if r > bestR + 1e-15:
            best, bestR = he, r
            print("post-hi-beta exact R=%.7f" % bestR)

    # Phase 3: peak-window polish at multiple scales + full polish.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        for frac in (0.05, 0.10, 0.20, 0.40):
            if time.process_time() >= deadline - 1.5:
                break
            h = _window_polish_peak(best, deadline, frac, 16, maxiter=400)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                print("win(%.2f) R=%.7f" % (frac, bestR))
                break
        if time.process_time() >= deadline - 1.5:
            break
        h = _lbfgs_log(best, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt is not None and altR > 0 and bestR <= startR + 1e-12:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


# ---- coordinate warp machinery ----
def _warp(h, theta, x):
    N = h.size
    d = np.zeros(N)
    for m in range(7):
        d += theta[2 * m] * np.sin(2 * np.pi * m * x)
        d += theta[2 * m + 1] * np.cos(2 * np.pi * m * x)
    y = np.clip(x + d, 0.0, 1.0)
    hw = np.interp(y, x, h)
    return _rescale(hw)


def _powell_warp(h, deadline, maxfev=3000):
    N = h.size
    x = (np.arange(N) + 0.5) / N
    bound = 1.5e-4
    bnds = [(-bound, bound)] * 14

    def obj(theta):
        if time.process_time() > deadline:
            raise TimeoutError
        hw = _warp(h, theta, x)
        return -R_of(hw)

    best_theta = np.zeros(14)
    best_val = -R_of(h)
    starts = [np.zeros(14)]
    rng = np.random.RandomState(12345)
    for _ in range(4):
        starts.append(rng.uniform(-bound * 0.5, bound * 0.5, 14))
    for th0 in starts:
        if time.process_time() > deadline - 0.5:
            break
        try:
            res = minimize(obj, th0, method='Powell', bounds=bnds,
                           options={'maxfev': maxfev, 'xtol': 1e-10, 'ftol': 1e-14})
        except (TimeoutError, Exception):
            break
        if res is not None and res.fun < best_val:
            best_val = res.fun
            best_theta = res.x.copy()
    return best_theta, -best_val


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Phase 1: coordinate warp via Powell ----
    warp_deadline = min(deadline - 2.0, time.process_time() + budget_seconds * 0.35)
    theta, rw = _powell_warp(bestH, warp_deadline)
    N = bestH.size
    x = (np.arange(N) + 0.5) / N
    hw = _warp(bestH, theta, x)
    rw = R_of(hw)
    print("warp R=%.7f (cells: %s)" %
          (rw, np.array2string(theta * N, precision=2, max_line_width=200)))
    if rw > bestRH + 1e-13:
        bestH, bestRH = hw.copy(), rw

    # ---- Phase 2: p-norm ladder + sharp polish ----
    ladder = (4, 8, 16, 32, 64, 128)
    loop_end = t0 + budget_seconds * 0.86
    stage_count = 0
    roundN = 0

    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 3.0:
        roundN += 1
        for p in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 3.0:
                break
            sub_deadline = min(loop_end, time.process_time() + 8.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 80, sub_deadline, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  R%d p=%d R=%.7f" % (roundN, p, bestRH))
            stage_count += 1

            if stage_count % 2 == 0:
                if time.process_time() >= loop_end - 1.0:
                    break
                sub2 = min(loop_end, time.process_time() + 6.0)
                hs = _lbfgs_log(bestH, 200, sub2)
                rs = R_of(hs)
                if rs > bestRH + 1e-13:
                    bestH, bestRH = hs.copy(), rs
                print("  R%d sharp R=%.7f" % (roundN, bestRH))

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 300, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _restrict(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _perturb(h, rng, sigma=0.20):
    h = h.copy()
    n = h.size
    if n < 8:
        return h
    nblocks = int(rng.integers(3, 6))
    cuts = np.sort(rng.choice(np.arange(1, n), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [n]))
    for b in range(edges.size - 1):
        a = edges[b]; c = edges[b + 1]
        if c <= a:
            continue
        h[a:c] *= np.exp(rng.normal(0.0, sigma))
    pos = h[h > 0]
    if pos.size > 0:
        z = h <= 0
        if np.any(z):
            h[z] = 1e-3 * pos.mean()
    return _rescale(h)


def _polish(h, deadline, betas, fracs):
    """Multi-scale polish: beta-homotopy then window refinement."""
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_log(h, maxiter=250, deadline=deadline, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(h, maxiter=400, deadline=deadline)
        if R_of(c) >= R_of(h):
            h = c
    for frac, extra in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        n = h.size
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(extra, int(span * frac))
        lo = max(0, lo - pad); hi = min(n - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        c = _lbfgs_block(h, free, maxiter=300, deadline=deadline, beta=0.0)
        if R_of(c) >= R_of(h):
            h = c
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds - 2.0

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = _lbfgs_log(np.ones(512), maxiter=800, deadline=hard_end)
        return cur

    start_r = R_of(start_arr)
    best = start_arr.copy()
    best_r = start_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    betas = (3000.0, 1200.0, 500.0, 0.0)
    fracs = ((0.30, 24), (0.15, 12), (0.06, 6))

    # Phase 1: refine on the start's resolution.
    h = _polish(best.copy(), hard_end, betas, fracs)
    _consider(h, R_of(h))
    print("phase1 R=%.6f N=%d" % (best_r, best.size))

    # Phase 2: upsample to a larger grid (finer discretization often lets the
    # optimizer find slightly better shapes), then polish.
    for factor, cap in ((2.0, 128000), (1.5, 192000)):
        if time.process_time() >= hard_end - 1.0:
            break
        N_big = int(min(cap, best.size * factor))
        if N_big <= best.size:
            continue
        h_big = _prolongate(best, N_big)
        h_big = _polish(h_big, hard_end, betas, fracs)
        _consider(h_big, R_of(h_big))
        # Restrict back to a compact representation to keep later steps cheap.
        if best.size < 64000 and time.process_time() < hard_end - 1.0:
            h_small = _restrict(h_big, best.size)
            h_small = _polish(h_small, hard_end, betas, fracs)
            _consider(h_small, R_of(h_small))
        print("upsample N=%d R=%.6f" % (N_big, best_r))

    # Phase 3: perturb-and-polish restarts around the best found, until budget.
    seed = 0
    while time.process_time() < hard_end - 1.0:
        rng = np.random.default_rng(9000 + seed)
        seed += 1
        sigma = float(rng.choice([0.08, 0.15, 0.25]))
        h = _perturb(best, rng, sigma=sigma)
        h = _polish(h, hard_end, betas, fracs)
        _consider(h, R_of(h))

    print("final R=%.6f N=%d" % (best_r, best.size))

    if best_r < start_r:
        best = start_arr.copy()
        best_r = start_r
    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


# ---- Warp machinery ----
def _warp(h, d, K=32, amp=0.25):
    N = h.size
    xk = np.arange(K + 1, dtype=float) / K
    u = xk.copy()
    u[1:K] = xk[1:K] + amp * np.tanh(d)
    u[0] = 0.0
    u[K] = 1.0
    u = np.maximum.accumulate(u + 1e-6 * np.arange(K + 1))
    u = np.clip(u, 0.0, 1.0)
    u[0] = 0.0
    u[K] = 1.0
    xj = np.arange(N, dtype=float) / N
    v = np.interp(xj, xk, u)
    C = np.concatenate(([0.0], np.cumsum(h) / h.sum()))
    xi = np.arange(N + 1, dtype=float) / N
    Cnew = np.interp(v, xi, C)
    hnew = N * np.diff(np.concatenate(([0.0], Cnew)))
    return _rescale(np.clip(hnew, 0, None))


def _warp_opt(h, deadline, d0=None, K=32):
    if time.process_time() >= deadline - 0.5:
        return h, R_of(h), np.zeros(K - 1)
    if d0 is None:
        d0 = np.zeros(K - 1)
    best = [None, -1.0, d0.copy()]

    def obj(d):
        if time.process_time() > deadline - 0.3:
            raise TimeoutError
        hw = _warp(h, d, K)
        r = R_of(hw)
        if r > best[1]:
            best[0] = hw
            best[1] = r
            best[2] = d.copy()
        return -r

    try:
        minimize(obj, d0, method='Powell',
                 options={'maxfev': 3000, 'xtol': 1e-4, 'ftol': 1e-10})
    except (TimeoutError, Exception):
        pass
    if best[0] is None:
        return h, R_of(h), d0
    return best[0], best[1], best[2]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Warp experiment: 3 restarts of Powell over 31 breakpoints ----
    rng = np.random.default_rng(12345)
    warp_end = t0 + budget_seconds * 0.55
    d_cur = np.zeros(31)
    for restart in range(3):
        if time.process_time() >= warp_end - 1.0:
            break
        if restart > 0:
            d_cur = d_cur + rng.normal(0.0, 0.5, size=31)
        sub_deadline = min(warp_end, time.process_time() + 5.0)
        hw, rw, d_cur = _warp_opt(bestH, sub_deadline, d0=d_cur, K=32)
        print("  warp restart %d R=%.7f (|d|max=%.4f)" %
              (restart, rw, np.max(np.abs(d_cur))))
        if rw > bestRH + 1e-13:
            bestH, bestRH = hw.copy(), rw

    # ---- Polish: sharp, p=8, p=32, peak ----
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(bestH, 200, min(deadline - 1.5, time.process_time() + 6.0))
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  sharp R=%.7f" % bestRH)

    for p in (8, 32):
        if time.process_time() >= deadline - 2.0:
            break
        fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
        h = _lbfgs_log(bestH, 100, min(deadline - 1.5, time.process_time() + 5.0), fg=fg)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  p=%d R=%.7f" % (p, bestRH))

    while time.process_time() < deadline - 1.5:
        prev = bestRH
        bestH, bestRH = _peak_polish(bestH, bestRH, 150, deadline - 1.0)
        if time.process_time() < deadline - 1.5:
            h = _lbfgs_log(bestH, 150, min(deadline - 1.0, time.process_time() + 4.0))
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
        print("  peak R=%.7f" % bestRH)
        if bestRH <= prev + 1e-14:
            break

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

