    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _smooth_polish(h, deadline, betas):
    """Continuation on beta to sharpen the max, then exact polish."""
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_log(h, maxiter=300, deadline=deadline, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(h, maxiter=600, deadline=deadline, beta=0.0)
        if R_of(c) >= R_of(h):
            h = c
    return h


def _perturb_window(h, rng, lo_frac, hi_frac, sigma, nblk_lo=4, nblk_hi=9,
                    zero_fill=False):
    h = h.copy()
    n = h.size
    lo = int(lo_frac * n)
    hi = int(hi_frac * n)
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(nblk_lo, nblk_hi))
    cuts = np.sort(rng.choice(np.arange(1, W), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    if zero_fill:
        win = h[lo:hi]
        pos = win[win > 0]
        if pos.size > 0:
            local_mean = pos.mean()
            z = win <= 0
            if np.any(z):
                win[z] = 1e-3 * local_mean
                h[lo:hi] = win
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(512)
        best = _smooth_polish(best, deadline, [30.0, 60.0, 120.0, 300.0])
        return best

    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    cur = start_arr.copy()
    cur_r = best_r

    hard_end = deadline - 0.5

    # Start with a quick sharpening of the given start via beta continuation.
    if time.process_time() < hard_end - 1.0:
        c = _smooth_polish(cur, hard_end, [30.0, 15.0, 7.0])
        if R_of(c) > cur_r:
            cur, cur_r = c, R_of(c)
            _consider(cur, cur_r)

    # Main loop: perturb a window, sharpen with beta continuation, polish peak.
    rng = np.random.default_rng(int(t0 * 1e6) % (2**31))
    it = 0
    while time.process_time() < hard_end - 1.0:
        it += 1
        # alternate windows: left, right, both, narrow right
        choice = it % 4
        if choice == 0:
            h = _perturb_window(cur, rng, 0.0, 0.50, 0.30, zero_fill=True)
        elif choice == 1:
            h = _perturb_window(cur, rng, 0.55, 1.0, 0.25, zero_fill=True)
        elif choice == 2:
            h = _perturb_window(cur, rng, 0.0, 1.0, 0.15)
        else:
            h = _perturb_window(cur, rng, 0.75, 1.0, 0.20, nblk_lo=3, nblk_hi=6,
                                zero_fill=True)

        # choose beta schedule based on current sharpness
        Lf = _knots(h)
        mx = Lf.max()
        if mx > 0:
            frac_near = np.mean(Lf >= 0.999 * mx)
        else:
            frac_near = 1.0
        if frac_near > 0.05:
            betas = [30.0, 80.0, 200.0]
        else:
            betas = [100.0, 300.0, 700.0]

        for beta in betas:
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_log(h, maxiter=250, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end, beta=0.0)
            if R_of(c) >= R_of(h):
                h = c
        for frac, extra in ((0.30, 16), (0.15, 8)):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _window_polish_peak(h, hard_end, frac, extra, maxiter=350)
            if R_of(c) >= R_of(h):
                h = c
        r = R_of(h)
        _consider(h, r)
        # If we improved, restart perturbing from the improved point.
        if r > cur_r:
            cur, cur_r = best.copy(), best_r

    print("main R=%.6f N=%d iters=%d" % (best_r, best.size, it))

    # Final polishing of best with progressively tighter beta.
    if time.process_time() < hard_end:
        c = _smooth_polish(best, hard_end + 0.5, [10.0, 3.0, 1.0, 0.3])
        if R_of(c) > best_r:
            best, best_r = c, R_of(c)

    if start_arr is not None and R_of(start_arr) > best_r:
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r < best_r and alt_r > R_of(start_arr):
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    """Smoothed objective: replace ||.||_inf by a p-norm of the knot values.
    This spreads the maximum out (flat top), which tends to help escape
    the sharp-peak local optimum and lets a subsequent true-inf step do better."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _full_block(h0, maxiter, deadline, fg=None):
    n = h0.size
    free = np.arange(n)
    return _lbfgs_block(h0, free, maxiter=maxiter, deadline=deadline, fg=fg)


def _window_polish_peak(h, deadline, frac, extra, maxiter=1500):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    base = best.copy()
    base_r = best_r

    def try_improve(cand):
        nonlocal best, best_r
        if cand is None:
            return False
        r = R_of(cand)
        if r > best_r + 1e-12:
            best, best_r = cand.copy(), r
            return True
        return False

    # Phase 1: log-param global refine
    if time.process_time() < deadline - 1.0:
        sub = time.process_time() + (deadline - time.process_time()) * 0.3
        try_improve(_lbfgs_log(best, maxiter=8000, deadline=sub))

    # Phase 2: smoothed (p-norm) polish — flattens the peak, then true-inf step.
    # This is the key new ingredient: it lets the optimizer reshape the peak
    # region rather than chase a single sharp maximum.
    for p in (16.0, 8.0, 4.0):
        if time.process_time() >= deadline - 1.0:
            break
        sub = time.process_time() + (deadline - time.process_time()) * 0.3
        fg = (lambda h, _p=p: _fun_grad_pnorm(h, _p))
        cand = _full_block(best, maxiter=4000, deadline=sub, fg=fg)
        try_improve(cand)

    # Phase 3: true-inf full-block polish
    if time.process_time() < deadline - 1.0:
        sub = time.process_time() + (deadline - time.process_time()) * 0.4
        try_improve(_full_block(best, maxiter=6000, deadline=sub))

    # Phase 4: peak-window polish, decreasing pad
    for frac, extra in [(0.5, 4), (0.25, 4), (0.15, 3), (0.08, 2)]:
        if time.process_time() >= deadline - 0.8:
            break
        sub = min(deadline - 0.5,
                  time.process_time() + (deadline - time.process_time()) * 0.45)
        try_improve(_window_polish_peak(best, sub, frac, extra, maxiter=1500))

    # Phase 5: prolongation to finer grid, then re-optimize (smoothed + true)
    if time.process_time() < deadline - 3.0 and best.size < 20000:
        N_big = min(20000, best.size * 2)
        h_big = _prolongate(best, N_big)
        sub = min(deadline - 0.5,
                  time.process_time() + (deadline - time.process_time()) * 0.35)
        fg = (lambda h: _fun_grad_pnorm(h, 8.0))
        cand = _lbfgs_log(h_big, maxiter=4000, deadline=sub, fg=fg)
        cand = _full_block(cand, maxiter=3000, deadline=sub)
        if R_of(cand) > best_r + 1e-12:
            best, best_r = cand, R_of(cand)

    # Phase 6: final true-inf full-block polish
    if time.process_time() < deadline - 0.5:
        try_improve(_full_block(best, maxiter=6000, deadline=deadline))

    if base_r >= best_r:
        return {"best": base, "alternative": best}
    return {"best": best, "alternative": base}

