import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _lbfgs_masked(h0, mask, maxiter, deadline, beta=0.0):
    """Optimize only entries where mask is True, using log parameterization."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.flatnonzero(mask & (h > 1e-13 * h.max()))
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(64)
        best_r = R_of(best)

    cur = best.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand.copy(), r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    rng = np.random.default_rng(1234567)
    n_full = cur.size

    # ---------------- Phase A: masked local polish at current N ----------
    # Only refine entries in the "support" of f*f peak region and its mirror.
    # We use a mask that includes peak region + neighborhood of f support.
    phaseA_end = t0 + 0.30 * (deadline - t0)
    try:
        h = cur.copy()
        # soft smooth with beta to escape
        for beta in (400.0, 150.0, 60.0):
            if time.process_time() >= phaseA_end - 0.5:
                break
            c = _lbfgs_log(h, maxiter=350, deadline=phaseA_end, beta=beta)
            if R_of(c) > R_of(h):
                h = c
        if time.process_time() < phaseA_end - 0.5:
            c = _lbfgs_log(h, maxiter=600, deadline=phaseA_end)
            if R_of(c) > R_of(h):
                h = c
        if time.process_time() < phaseA_end - 0.5:
            c = _window_polish_peak(h, phaseA_end, 0.20, 12, maxiter=400, beta=0.0)
            if R_of(c) > R_of(h):
                h = c
        _consider(h, R_of(h))
        print("phaseA R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Phase B: coarse-escape via downsample ----------------
    phaseB_end = t0 + 0.62 * (deadline - t0)

    def _coarse_escape(h, N_small, t_end):
        if time.process_time() >= t_end - 1.0:
            return h
        hs = _prolongate(h, N_small)
        slice_end = min(t_end - 0.5, time.process_time() + 2.5)
        for beta in (250.0, 80.0):
            if time.process_time() >= slice_end - 0.5:
                break
            c = _lbfgs_log(hs, maxiter=200, deadline=slice_end, beta=beta)
            if R_of(c) > R_of(hs):
                hs = c
        if time.process_time() < slice_end - 0.5:
            c = _lbfgs_log(hs, maxiter=350, deadline=slice_end)
            if R_of(c) > R_of(hs):
                hs = c
        hb = _prolongate(hs, h.size)
        if time.process_time() < t_end - 0.5:
            c = _lbfgs_log(hb, maxiter=500, deadline=t_end)
            if R_of(c) > R_of(hb):
                hb = c
        if time.process_time() < t_end - 0.5:
            c = _window_polish_peak(hb, t_end, 0.25, 12, maxiter=350, beta=0.0)
            if R_of(c) > R_of(hb):
                hb = c
        return hb

    try:
        for N_small in (n_full // 2, n_full // 4):
            if N_small < 1000:
                continue
            if time.process_time() >= phaseB_end - 1.0:
                break
            hb = _coarse_escape(cur, N_small, phaseB_end)
            _consider(hb, R_of(hb))
        print("phaseB R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Phase C: descending-beta + peak polish loop ---------
    try:
        while time.process_time() < deadline - 1.0:
            h = cur.copy()
            for beta in (100.0, 40.0, 15.0):
                if time.process_time() >= deadline - 1.0:
                    break
                c = _lbfgs_log(h, maxiter=250, deadline=deadline - 0.5, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < deadline - 1.0:
                c = _lbfgs_log(h, maxiter=500, deadline=deadline - 0.5)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.25, 12), (0.12, 6), (0.05, 3)):
                if time.process_time() >= deadline - 1.0:
                    break
                c = _window_polish_peak(h, deadline - 0.5, frac, extra,
                                        maxiter=350, beta=0.0)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= deadline - 1.0:
                break
        print("phaseC R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if start_arr is not None:
        sr = R_of(start_arr)
        if best_r < sr:
            best = start_arr.copy()
            best_r = sr

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

