        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt is not None and altR > 0 and bestR <= startR + 1e-12:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _polish(h, deadline, tag=""):
    best = h
    bestR = R_of(h)
    for beta in (30.0, 100.0, 300.0):
        if time.process_time() >= deadline - 1.0:
            break
        h2 = _lbfgs_log(best, 300, deadline, beta=beta)
        r = R_of(h2)
        if r > bestR + 1e-15:
            best, bestR = h2, r
    for frac, extra in ((0.15, 8), (0.30, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 1.5:
            break
        h2 = _window_polish_peak(best, deadline, frac, extra)
        h2 = _lbfgs_log(h2, 400, deadline)
        r = R_of(h2)
        if r > bestR + 1e-15:
            best, bestR = h2, r
    return best, bestR


def _perturb(h, rng, amp):
    """Multiplicative random perturbation to escape a local basin."""
    n = h.size
    noise = rng.standard_normal(n) * amp
    h2 = h * np.exp(noise)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    print("base R=%.7f (N=%d)" % (baseR, base.size))

    best = base.copy()
    bestR = baseR

    # Phase 1: softmax-beta relaxations.
    for beta in (50.0, 150.0, 400.0):
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_log(best, 500, deadline, beta=beta)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("beta=%.0f R=%.7f" % (beta, bestR))

    # Phase 2: multi-scale polish.
    best, bestR = _polish(best, deadline)
    print("after polish R=%.7f" % bestR)

    # Phase 3: alternate full + peak.
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.45, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if bestR <= prev + 1e-15:
            h = _lbfgs_log(best, 300, deadline, beta=100.0)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
            else:
                break

    print("final main R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 4: perturb-and-reoptimise search from the best, plus mirror.
    alt = None
    altR = 0.0

    # Try mirror-completion once as a genuinely different construction.
    if time.process_time() < deadline - 6.0:
        h0 = _rescale(base + base[::-1])
        hm, rm = _polish(h0, deadline)
        if rm > altR:
            alt, altR = hm, rm
            print("mirror R=%.7f" % altR)

    # Random-perturbation multi-start search around the best found.
    seeds = [best, base]
    while time.process_time() < deadline - 1.5:
        if alt is not None and altR > bestR:
            src, srcR = alt, altR
        else:
            src, srcR = best, bestR
        # Randomly pick a source to perturb.
        if rng.random() < 0.5:
            src, srcR = best, bestR
        amp = 10.0 ** rng.uniform(-2.5, -0.5)
        h0 = _perturb(src, rng, amp)
        h, r = _polish(h0, deadline)
        # refine with peak windows
        h2 = _window_polish_peak(h, deadline, 0.45, 24)
        r2 = R_of(h2)
        if r2 > r:
            h, r = h2, r2
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("perturb amp=%.3f R=%.7f" % (amp, bestR))
        elif r > altR + 1e-15:
            alt, altR = h, r

    print("final best R=%.7f alt R=%.7f" % (bestR, altR))

    if alt is not None and altR > bestR + 1e-15:
        return {"best": alt, "alternative": best}
    if bestR > baseR + 1e-15:
        return {"best": best, "alternative": alt if alt is not None else base}
    return {"best": base, "alternative": best if bestR > baseR + 1e-15 else (alt if alt is not None else best)}

