    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: resolution upsampling homotopy.
    # Progressively refine the grid (prolongate + re-optimise), which escapes
    # the local optimum the current grid is stuck in. Each level re-polishes
    # globally and around the peak, then continues to the next finer grid.
    n0 = best.size
    targets = []
    n = n0
    while n < 200000:
        n = int(n * 1.5) + 64
        targets.append(n)
    # Always try at least one refinement even if already large.
    if not targets:
        targets = [min(1000000, n0 * 2)]

    for Nt in targets:
        if time.process_time() >= deadline - 3.0:
            break
        cand = _prolongate(best, Nt)
        cand = _rescale(cand)
        r = R_of(cand)
        # re-optimise at new resolution
        for _ in range(2):
            if time.process_time() >= deadline - 3.0:
                break
            hh = _lbfgs_log(cand, 600, deadline)
            rr = R_of(hh)
            if rr > r + 1e-15:
                cand, r = hh, rr
            hh = _window_polish_peak(cand, deadline, 0.40, 32)
            rr = R_of(hh)
            if rr > r + 1e-15:
                cand, r = hh, rr
        print("upsample N=%d R=%.7f" % (Nt, r))
        if r > bestR + 1e-15:
            best, bestR = cand, r

    # Continue normal polishing loop on the (possibly upsampled) shape.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

