            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("prolong wins R=%.7f" % bestR)

    # Perturbation exploration with beta polish
    specs = [(N / 300.0, 0.05, 11), (N / 300.0, 0.10, 12),
             (N / 80.0, 0.06, 13), (N / 150.0, 0.08, 14)]
    for sigma, amp, seed in specs:
