        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Final loop: alternate sharp and beta-ladder polish.
    while time.process_time() < deadline - 1.5:
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if time.process_time() >= deadline - 3.0:
            break
        h, r = _polish_beta(best, min(deadline, time.process_time() + 0.15 * budget_seconds))
        if r > bestR + 1e-15:
            best, bestR = h, r
        else:
