        sup_lo, sup_hi = int(nz[0]), int(nz[-1])
    else:
        sup_lo, sup_hi = 0, best.size - 1
    print("base R=%.7f N=%d support=[%d,%d] zero-runs=%d" %
          (bestR, best.size, sup_lo, sup_hi, len(runs)))
    if runs:
        big = sorted(runs, key=lambda t: -t[1])[:6]
        print("  top zero-runs (start,len):", big)

    bestH = best.copy()
    bestRH = bestR

    # (1) extension sweep
    exts = [16, 64, 256, 1024, 4096]
    modes = ['left', 'right', 'both']
    qs = [0.5, 1.0, 2.0]
    rs = [0.01, 0.05, 0.2, 1.0]

    def build_ext(h, mode, ext, q, r):
        n = h.size
        aL = _end_amp(h, 'left') * r
        aR = _end_amp(h, 'right') * r
        if mode == 'left':
            toe = _make_toe(ext, q, aL)
            return np.concatenate((toe, h))
        elif mode == 'right':
            toe = _make_toe(ext, q, aR)
            return np.concatenate((h, toe))
        else:
            tl = _make_toe(ext, q, aL)
            tr = _make_toe(ext, q, aR)
            return np.concatenate((tl, h, tr))

    cands = []
    for mode in modes:
        for ext in exts:
            for q in qs:
                for r in rs:
                    he = build_ext(bestH, mode, ext, q, r)
                    he = _rescale(he)
                    re = R_of(he)
                    cands.append((re, mode, ext, q, r, he))
                    if time.process_time() > deadline - 8.0:
                        break
                if time.process_time() > deadline - 8.0:
                    break
            if time.process_time() > deadline - 8.0:
                break
        if time.process_time() > deadline - 8.0:
            break

    cands.sort(key=lambda t: -t[0])
    print("ext sweep: %d cands, top unpolished R=%.7f" %
          (len(cands), cands[0][0] if cands else 0.0))

