    polished = []
    for (re, mode, ext, q, r, he) in cands[:6]:
        if time.process_time() > deadline - 4.0:
            break
        n = he.size
        if mode == 'left':
            free = np.arange(0, ext + 2 * ext)
        elif mode == 'right':
            free = np.arange(n - ext - 2 * ext, n)
        else:
            free = np.concatenate((np.arange(0, ext + 2 * ext),
                                   np.arange(n - ext - 2 * ext, n)))
        free = np.clip(free, 0, n - 1)
        sub_dl = min(deadline - 2.0, time.process_time() + 3.0)
        hp = _lbfgs_block(he, free, 100, sub_dl)
        rp = R_of(hp)
        if time.process_time() < deadline - 2.0:
            sub_dl = min(deadline - 1.0, time.process_time() + 3.0)
            hg = _lbfgs_log(hp, 200, sub_dl)
            rg = R_of(hg)
            if rg > rp:
                hp, rp = hg, rg
        polished.append((rp, mode, ext, q, r, hp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("  polish ACCEPT mode=%s ext=%d q=%.2f r=%.3f R=%.7f" %
                  (mode, ext, q, r, bestRH))

    # (3) interior zero-run fill
    if time.process_time() < deadline - 6.0:
        runs_now = _zero_runs(bestH)
        for (s0, ln) in runs_now:
            if ln < 4:
                continue
            if time.process_time() > deadline - 5.0:
                break
            for q in (0.5, 1.0, 2.0):
                for r in (0.05, 0.2):
                    hc = bestH.copy()
                    aL = _end_amp(bestH, 'left') * r
                    aR = _end_amp(bestH, 'right') * r
                    j = np.arange(ln, dtype=float)
                    prof = aL * np.power(np.clip(1.0 - (j + 0.5) / ln, 0, None), q) + \
                           aR * np.power(np.clip((j + 0.5) / ln, 0, None), q)
                    hc[s0:s0 + ln] = prof
                    hc = _rescale(hc)
                    rc = R_of(hc)
                    if rc > bestRH + 1e-13:
                        sub_dl = min(deadline - 3.0, time.process_time() + 2.0)
                        hp = _lbfgs_block(hc, np.arange(max(0, s0 - 32), min(hc.size, s0 + ln + 32)),
                                          80, sub_dl)
                        rp = R_of(hp)
                        if rp > bestRH + 1e-13:
                            bestH, bestRH = hp.copy(), rp
                            print("  fill ACCEPT run=(%d,%d) q=%.2f r=%.2f R=%.7f" %
                                  (s0, ln, q, r, bestRH))

