    best_exts = [c[2] for c in cands[:2]] if cands else [256, 1024]
    best_modes = [c[1] for c in cands[:2]] if cands else ['right', 'both']
    r_scale = 1.0
    round_i = 0
    while time.process_time() < deadline - 4.0:
        round_i += 1
        r_scale *= 0.5
        improved = False
        for mode in best_modes:
            for ext in best_exts:
                if time.process_time() > deadline - 4.0:
                    break
                for q in qs:
                    for r in rs:
                        rr = r * r_scale
                        he = build_ext(bestH, mode, ext, q, rr)
                        he = _rescale(he)
                        re = R_of(he)
                        if re > bestRH - 1e-5:
                            n = he.size
                            if mode == 'left':
                                free = np.arange(0, ext + 2 * ext)
                            elif mode == 'right':
                                free = np.arange(n - ext - 2 * ext, n)
                            else:
                                free = np.concatenate((np.arange(0, ext + 2 * ext),
                                                       np.arange(n - ext - 2 * ext, n)))
                            free = np.clip(free, 0, n - 1)
                            sub_dl = min(deadline - 3.0, time.process_time() + 2.0)
                            hp = _lbfgs_block(he, free, 80, sub_dl)
                            rp = R_of(hp)
                            if rp > bestRH + 1e-13:
                                bestH, bestRH = hp.copy(), rp
                                improved = True
                                print("  anneal ACCEPT round=%d mode=%s ext=%d q=%.2f r=%.4f R=%.7f" %
                                      (round_i, mode, ext, q, rr, bestRH))
        if not improved and r_scale < 1e-3:
            break

    # final global polish
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


