import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1200:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolong(h, n_new):
    """Cumulative-mass (piecewise-linear CDF) prolongation."""
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.ones(n_new)
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _seed_cosine(n):
    x = np.linspace(0, 1, n)
    return np.cos(np.pi * (x - 0.5)) ** 2 + 1e-3


def _seed_asym(n):
    x = np.linspace(0, 1, n)
    return np.exp(-((x - 0.35) / 0.2) ** 2) + 1e-3


def _seed_triangular(n):
    x = np.linspace(0, 1, n)
    return np.minimum(x, 1 - x) + 1e-3


def construct(budget_seconds, start):
    t0 = time.process_time()
    # leave a healthy margin
    deadline = t0 + budget_seconds - 2.0

    best = None
    bestR = -1.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            best = _rescale(s)
            bestR = R_of(best)

    # ---- Phase A: seed optimisation at small N ----
    N0 = 256
    seeds = [("cosine", _seed_cosine(N0)),
             ("asym", _seed_asym(N0)),
             ("triangular", _seed_triangular(N0))]
    survivors = []
    if time.process_time() < deadline - 15.0:
        for name, s in seeds:
            if time.process_time() > deadline - 15.0:
                break
            try:
                h = _lbfgs_log(s, 300, deadline - 15.0, beta=0.0)
                h = _lbfgs_log(h, 300, deadline - 15.0, beta=8.0)
                r = R_of(h)
                survivors.append((r, name, h))
            except Exception:
                pass
    survivors.sort(key=lambda t: -t[0])

    # ---- Phase B: ladder prolongation + polishing ----
    ladder_best = None
    ladder_R = -1.0
    ladder_list = [survivors[0]] if survivors else []
    for r0, name, h in ladder_list:
        cur = h
        for n_new in [512, 1024, 2048, 4096, 8192, 16384, 32768]:
            if time.process_time() > deadline - 5.0:
                break
            cur = _prolong(cur, n_new)
            cur = _lbfgs_log(cur, 250, deadline - 5.0, beta=0.0)
            cur = _lbfgs_log(cur, 150, deadline - 5.0, beta=10.0)
        r = R_of(cur)
        print(f"ladder {name}: R={r:.6f} N={len(cur)}")
        if r > ladder_R:
            ladder_R = r
            ladder_best = cur

    if ladder_best is not None and ladder_R > bestR:
        best = ladder_best
        bestR = ladder_R

    # ---- Phase C: improve from start itself (prolong then re-optimise) ----
    if start is not None and time.process_time() < deadline - 5.0:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            for n_new in [len(s), 2 * len(s), 4 * len(s)]:
                if n_new > 200000:
                    break
                if time.process_time() > deadline - 5.0:
                    break
                cur = _prolong(s, n_new)
                cur = _lbfgs_log(cur, 250, deadline - 5.0, beta=0.0)
                r = R_of(cur)
                if r > bestR:
                    best, bestR = cur, r
                    print(f"start-ladder: R={r:.6f} N={len(cur)}")

    # ---- Phase D: from current best, try higher-resolution refinement ----
    if best is not None:
        cur = best
        for n_new in [len(cur), 2 * len(cur), 4 * len(cur)]:
            if n_new > 200000:
                break
            if time.process_time() > deadline - 3.0:
                break
            cur = _prolong(cur, n_new)
            cur = _lbfgs_log(cur, 300, deadline - 3.0, beta=0.0)
            r = R_of(cur)
            if r > bestR:
                best, bestR = cur, r
                print(f"refine: R={r:.6f} N={len(cur)}")

    # ---- Phase E: alternate zero-sparsification and re-optimisation ----
    if best is not None:
        while time.process_time() < deadline - 2.0:
            cur = best.copy()
            nz = cur[cur > 0]
            if nz.size == 0:
                break
            thr = np.quantile(nz, 0.15)
            cur[cur < thr] = 0.0
            cur2 = _lbfgs_log(cur, 200, deadline - 2.0, beta=0.0)
            r = R_of(cur2)
            if r > bestR + 1e-9:
                best, bestR = cur2, r
                print(f"sparsify: R={r:.6f}")
            else:
                break

    if best is None:
        best = np.ones(50)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)

    alt = None
    if ladder_best is not None and abs(ladder_R - bestR) > 1e-9:
        alt = ladder_best

    print(f"final R={R_of(best):.6f} N={len(best)}")
    if alt is not None:
        return {"best": best, "alternative": alt}
    return best

