        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _sym_polish(h, deadline, maxiter=250):
    """Symmetric-constrained polish: h = [u, u[::-1]] (mirror about centre)."""
    n = h.size
    half = n // 2
    if half < 2:
        return h
    # Symmetrise current h to get the initial u
    hh = h[:2 * half]
    u0 = 0.5 * (hh[:half] + hh[::-1][:half])
    u0 = np.clip(u0, 1e-12, None)

    def rebuild(u):
        uu = np.clip(u, 0.0, None)
        return np.concatenate((uu, uu[::-1]))

    def f(u):
        hfull = rebuild(u)
        val, g = _fun_grad(hfull)
        ghalf = g[:half] + g[::-1][:half]
        # chain rule through log parameterisation
        uu = np.clip(u, 1e-30, None)
        return val, ghalf * uu

    ulog0 = np.log(u0)
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, ulog0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * half,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    u = np.exp(np.clip(res.x, -30.0, 30.0))
    hfull = rebuild(u)
    return _rescale(hfull)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    h0 = best.copy()
    n = h0.size

    # (1) Symmetrisation table
    cands = []
    for d in (-3, -1, 0, 1, 3):
        for w in (0.25, 0.5, 0.75, 1.0):
            mirror = np.roll(h0[::-1], d)
            cand = (1.0 - w) * h0 + w * mirror
            cand = np.clip(cand, 0, None)
            cand = _rescale(cand)
            r = R_of(cand)
            cands.append((r, d, w, cand))
            print("  sym d=%+d w=%.2f R=%.7f" % (d, w, r))

    cands.sort(key=lambda t: -t[0])
    top = cands[:4]

    # (2) Polish top 4
    best_sym = None
    best_symR = -1.0
    for r0, d, w, cand in top:
        if time.process_time() >= deadline - 20.0:
            break
        h = _lbfgs_log(cand, 300, deadline)
        for beta in (1e3, 1e4):
            if time.process_time() >= deadline - 18.0:
                break
            hb = _lbfgs_log(h, 150, deadline, beta=beta)
            if R_of(hb) > R_of(h):
                h = hb
        r = R_of(h)
        print("  polish d=%+d w=%.2f R=%.7f" % (d, w, r))
        if r > best_symR:
            best_symR = r
            best_sym = h

    if best_sym is None:
        best_sym = h0
        best_symR = bestR

    # (3) Symmetric-constrained polish
    if time.process_time() < deadline - 12.0:
        hs = _sym_polish(best_sym, deadline, maxiter=250)
        rs = R_of(hs)
        print("  sym-constrained R=%.7f (was %.7f)" % (rs, best_symR))
        if rs > best_symR:
            best_sym, best_symR = hs, rs

    # Track the symmetric-basin best separately
    sym_best = best_sym.copy()
    sym_bestR = best_symR

    if best_symR > bestR:
        best, bestR = best_sym.copy(), best_symR
        print("symmetric basin improved base to R=%.7f" % bestR)

    # (4) Release constraint: free sharp + peak polish to deadline
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  free full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  free peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    # Return the symmetric-basin construction as alternative if genuinely different
    if sym_bestR > start_bestR - 1e-6 and sym_bestR > 0:
        return {"best": start_best, "alternative": sym_best}
    return {"best": start_best, "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


# --- Soft-max homotopy: smooth approximation to max_j L_j ---
def _make_fg_soft(beta):
    def fg(h):
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(h.size)
        num, dq, Lf = _num_and_dq(h)
        # logsumexp over knots
        z = beta * Lf
        zmax = z.max()
        ez = np.exp(z - zmax)
        S = ez.sum()
        lse = zmax + np.log(S)
        m_soft = lse / beta
        w = ez / S  # softmax weights
        # grad of log(m_soft) w.r.t. Lf
        gLf = -dq / num + w / m_soft
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(m_soft)
        return val, grad
    return fg


def _mass_resample(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew) / Nnew
    x = np.linspace(0.0, 1.0, Nnew + 1)
    src_x = np.linspace(0.0, 1.0, N + 1)
    target_c = np.interp(x, src_x, c)
    out = np.diff(target_c)
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return np.ones(Nnew) / Nnew
    return out * (total / out.sum())


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    # Key new idea: soft-max homotopy polish at the current N. This directly
    # targets the max-knot constraint (the binding part of R), pushing more
    # knots up against Lmax, which the hard-max L-BFGS cannot do smoothly.
    def try_soft_polish(h, dl, betas=(50.0, 200.0, 800.0, 3000.0)):
        cur = h.copy()
        curR = R_of(cur)
        for beta in betas:
            if time.process_time() > dl:
                break
            fg = _make_fg_soft(beta)
            hp = _lbfgs_log(cur, 150, min(dl, time.process_time() + 6.0), fg=fg)
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp
            else:
                # still take it as warm start for next beta if close
                if rp > curR - 1e-9:
                    cur = hp
        # final hard polish
        if time.process_time() < dl:
            hp = _lbfgs_log(cur, 200, dl)
            rp = R_of(hp)
            if rp > curR:
                cur, curR = hp, rp
        return cur, curR

    # (1) soft-max polish at native resolution
    h1, r1 = try_soft_polish(bestH, deadline - budget_seconds * 0.55)
    if r1 > bestRH + 1e-13:
        bestH, bestRH = h1.copy(), r1
        print("soft polish ACCEPT R=%.7f" % bestRH)

    # (2) mass-preserving upsampling + soft polish (refine on finer grid)
    if time.process_time() < deadline - budget_seconds * 0.30:
        N = bestH.size
        for mult in (2, 3):
            if time.process_time() > deadline - budget_seconds * 0.30:
                break
            Nnew = min(1000000, N * mult)
            hu = _mass_resample(bestH, Nnew)
            hu = _rescale(hu)
            dl = min(deadline, time.process_time() + budget_seconds * 0.18)
            hu2, ru2 = try_soft_polish(hu, dl)
            if ru2 > bestRH + 1e-13:
                bestH, bestRH = hu2.copy(), ru2
                print("upsample x%d ACCEPT R=%.7f N=%d" % (mult, bestRH, bestH.size))
                break

    # (3) final hard polish to squeeze any remaining improvement
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

