            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            else:
                cur = cand
        hh, hom_r = cur, cur_r
        print("desc-homotopy R=%.6f (base %.6f)" % (hom_r, base_r))
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(hh, maxiter=400, deadline=hard_end)
