        # peak-window polish
        for frac in (0.05, 0.15):
            if not time_left():
                break
            lo, hi = _peak_region(hw, tol=0.999)
            span = max(1, hi - lo)
            pad = max(16, int(span * frac))
            lo2 = max(0, lo - pad)
            hi2 = min(hw.size - 1, hi + pad)
            free = np.arange(lo2, hi2 + 1)
            c = _lbfgs_block(hw, free, 200, deadline, beta=1e5)
            if R_of(c) > R_of(hw):
                hw = c
            try_accept(hw)
            consider_alt(hw)
        if time_left():
            c = _lbfgs_log(hw, 200, deadline, beta=1e7)
            if R_of(c) > R_of(hw):
