        hw_best = hw
        r_best = r0
        for cand in cands:
            rc = R_of(cand)
            if rc > r_best:
                r_best = rc
                hw_best = cand
        hw = hw_best
        print(f"  after revival R={r_best:.6f}")
        hw = optimise(hw, f"N={N}")
        rc = R_of(hw)
        if rc > currentR:
            current = hw
            currentR = rc
        else:
            # keep going from best anyway
            if rc > R_of(current):
                current = hw
                currentR = rc
        print(f"level x{mult} sigma={sigma}: R={currentR:.6f}")

    # Final polish at current resolution until time runs out.
    while time_left():
        c = _lbfgs_log(current, 200, deadline)
        if R_of(c) > R_of(current):
            current = c
        try_accept(current)
        consider_alt(current)
        if not time_left():
            break
        lo, hi = _peak_region(current, tol=0.999)
        span = max(1, hi - lo)
        pad = max(16, int(span * 0.15))
        lo2 = max(0, lo - pad)
        hi2 = min(current.size - 1, hi + pad)
        free = np.arange(lo2, hi2 + 1)
        c = _lbfgs_block(current, free, 200, deadline)
        if R_of(c) > R_of(current):
            current = c
        try_accept(current)

    print(f"final best R={bestR:.6f} N={best.size}")
    if alt is not None and altR > bestR:
        return {"best": alt, "alternative": best}
    if alt is not None and altR > 0 and alt.size != best.size:
