def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _gauss_kernel(sigma):
    r = max(1, int(np.ceil(3.0 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return k


def _smooth_log_window(h, free, sigma, alpha):
    """Log-space Gaussian smoothing on the window `free`, then exponentiate."""
    h = np.clip(h, 0, None)
    n = h.size
    lo = int(free[0]); hi = int(free[-1]) + 1
    if hi <= lo:
        return h
    floor = 1e-12 * max(h.max(), 1e-300)
    seg = np.clip(h[lo:hi], floor, None)
    u = np.log(seg)
    k = _gauss_kernel(sigma)
    r = (k.size - 1) // 2
    up = np.pad(u, r, mode='reflect')
    us = np.convolve(up, k, mode='valid')
    un = (1.0 - alpha) * u + alpha * us
    h2 = h.copy()
    h2[lo:hi] = np.exp(np.clip(un, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
