                break
            free = _peak_window(bestH, frac=frac)
            for sigma in (2, 4, 8, 16, 32, 64):
                if time.process_time() >= sweep_end:
                    break
                for alpha in (0.35, 0.6):
                    if time.process_time() >= sweep_end:
                        break
                    h2 = _smooth_log_window(bestH, free, sigma, alpha)
                    r_raw = R_of(h2)
                    cap = min(deadline - 1.0, time.process_time() + 6.0)
                    hp = _lbfgs_log(h2, 250, cap, beta=0.0)
                    rp = R_of(hp)
                    if time.process_time() < deadline - 1.0:
                        cap = min(deadline - 1.0, time.process_time() + 4.0)
                        hb = _lbfgs_log(hp, 120, cap, beta=1e4)
                        rb = R_of(hb)
                        if rb > rp:
                            hp, rp = hb, rb
                    print("  smooth frac=%.2f sigma=%2d alpha=%.2f raw=%.7f pol=%.7f" %
                          (frac, sigma, alpha, r_raw, rp))
                    if rp > bestRH + 1e-13:
                        bestH, bestRH = hp.copy(), rp
                        print("    NEW BEST R=%.7f" % bestRH)

    # ---- Remaining time: alternating sharp + peak polish on best ----
    rng = np.random.default_rng(987654321)
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            improved = True
            print("  iter=%d sharp R=%.7f" % (it, bestRH))
        if time.process_time() < loop_end:
            frac = 0.05 + 0.10 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
                print("  iter=%d peak R=%.7f" % (it, bestRH))
        if not improved and time.process_time() < loop_end - 2.0:
            beta = 1e5
            cap = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(bestH, 100, cap, beta=beta)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
                print("  iter=%d beta=%.1e R=%.7f" % (it, beta, bestRH))

    print("final R=%.7f (best of experiment)" % bestRH)

    if bestRH > start_bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH
    else:
        best, bestR = start_best, start_bestR

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    if bestH.size == start_best.size and bestRH > start_bestR - 1e-6:
        return {"best": start_best, "alternative": bestH}
    return {"best": start_best, "alternative": None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _end_amp(h, side, frac=0.05):
    n = h.size
    k = max(1, int(n * frac))
    seg = h[:k] if side == 'left' else h[-k:]
    seg = seg[seg > 0]
    if seg.size == 0:
        return h.max() * 0.01
    return float(np.mean(seg))


def _make_toe(ext, q, a):
    j = np.arange(ext, dtype=float)
    return a * np.power(np.clip(1.0 - (j + 0.5) / ext, 0.0, None), q)


def _peak_window(h, frac=0.15):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(32, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    # (1) Beta-smoothed polish of the peak region: works around
    # non-smoothness of the max term, which is the main blocker to
    # further L-BFGS progress at this fine resolution.
    if time.process_time() < deadline - 20.0:
        win = _peak_window(bestH, frac=0.20)
        for beta in (20.0, 80.0, 300.0, 1200.0):
            if time.process_time() > deadline - 18.0:
                break
            sub_dl = min(deadline - 15.0, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, win, 150, sub_dl, beta=beta)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  beta=%.0f peak R=%.7f" % (beta, bestRH))

    # (2) Full beta-smoothed polish on whole support
    if time.process_time() < deadline - 12.0:
        for beta in (50.0, 200.0, 800.0):
            if time.process_time() > deadline - 11.0:
                break
            sub_dl = min(deadline - 9.0, time.process_time() + 4.0)
            hp = _lbfgs_log(bestH, 200, sub_dl, beta=beta)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  beta=%.0f full R=%.7f" % (beta, bestRH))

    # (3) Small extension sweeps: append tiny toes on left/right, then polish.
    if time.process_time() < deadline - 6.0:
        for side in ('left', 'right', 'both'):
            if time.process_time() > deadline - 5.0:
                break
            for ext in (8, 32, 128):
                for q in (0.5, 1.0, 2.0):
                    for r in (0.02, 0.1, 0.5):
                        if time.process_time() > deadline - 4.5:
                            break
                        aL = _end_amp(bestH, 'left') * r
                        aR = _end_amp(bestH, 'right') * r
                        if side == 'left':
                            he = np.concatenate((_make_toe(ext, q, aL), bestH))
                        elif side == 'right':
                            he = np.concatenate((bestH, _make_toe(ext, q, aR)))
                        else:
                            he = np.concatenate((_make_toe(ext, q, aL), bestH,
                                                 _make_toe(ext, q, aR)))
                        he = _rescale(he)
                        re = R_of(he)
                        if re > bestRH - 2e-4:
                            n = he.size
                            if side == 'left':
                                free = np.arange(0, ext + 2 * ext)
                            elif side == 'right':
                                free = np.arange(n - ext - 2 * ext, n)
                            else:
                                free = np.concatenate((
                                    np.arange(0, ext + 2 * ext),
                                    np.arange(n - ext - 2 * ext, n)))
                            free = np.clip(free, 0, n - 1)
                            sub_dl = min(deadline - 3.0,
                                         time.process_time() + 2.0)
                            hp = _lbfgs_block(he, free, 100, sub_dl)
                            rp = R_of(hp)
                            if rp > bestRH + 1e-13:
                                bestH, bestRH = hp.copy(), rp
                                print("  ext side=%s ext=%d q=%.1f r=%.2f R=%.7f" %
                                      (side, ext, q, r, bestRH))

    # (4) Final sharp full polish
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 500, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d zeros %.1f%%) argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

