    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _mass_downsample(h, N0):
    """Mass-preserving downsample to N0 bins via cumulative sums."""
    n = h.size
    if n <= N0:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0, n, N0 + 1)
    idx = np.clip(np.round(edges).astype(int), 0, n)
    out = np.diff(c[idx])
    return np.clip(out, 0, None)


def _upsample_linear(h, N1):
    """Upsample to N1 bins, then rescale to original mass."""
    n = h.size
    if n == N1:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N1) + 0.5) / N1
    out = np.interp(x_new, x_old, h, left=h[0], right=h[-1])
    s_old = h.sum()
    s_new = out.sum()
    if s_new > 0:
        out *= s_old / s_new
    return np.clip(out, 0, None)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 5e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
