        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    record_R = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    # ---- KEY IDEA: re-grid the existing solution (downsample then re-upsample) ----
    # Then polish on the fresh grid.  Changing grid often escapes the local basin
    # that plain L-BFGS is stuck in, and typically finds a better optimum.
    variants = []
    n0 = best.size
    # (a) downsample to a coarser grid then re-upsample; state is smoother, easier to move
    for factor in (2, 3, 4):
        Nc = max(512, n0 // factor)
        if Nc >= n0:
            continue
        hc = _mass_downsample(best, Nc)
        hc = _rescale(hc)
        # polish on the coarse grid briefly, then upsample
        if time.process_time() < deadline - 3.0:
            hc2, rc = _polish(hc, min(deadline - 2.0, time.process_time() + 4.0), 0.0)
            if rc > R_of(hc):
                hc = hc2
        hu = _upsample_linear(hc, n0)
        hu = _rescale(hu)
        ru = R_of(hu)
        variants.append(("coarse x%d" % factor, hu, ru))
        print("  regrid coarse x%d: pre R=%.7f (d=%.2e)" % (factor, ru, ru - record_R))

    # (b) pure upsample to a finer grid then re-downsample to original size
    for factor in (2,):
        Nf = n0 * factor
        if Nf > 900000:
            continue
        hf = _upsample_linear(best, Nf)
        hf = _rescale(hf)
        hf2, rf = _polish(hf, min(deadline - 2.0, time.process_time() + 6.0), 0.0)
        if rf > R_of(hf):
            hf = hf2
        hd = _mass_downsample(hf, n0)
        hd = _rescale(hd)
        rd = R_of(hd)
        variants.append(("updown x%d" % factor, hd, rd))
        print("  regrid updown x%d: pre R=%.7f (d=%.2e)" % (factor, rd, rd - record_R))

    # (c) mirror of current
    hm = _rescale(best[::-1].copy())
    rm = R_of(hm)
    variants.append(("mirror", hm, rm))
    print("  mirror: pre R=%.7f (d=%.2e)" % (rm, rm - record_R))

    keep = [v for v in variants if v[2] >= record_R - 5e-3]
    keep.sort(key=lambda v: -v[2])
    top = keep[:3]

    bestH = best.copy()
    bestRH = record_R

    for name, hv, rv in top:
        if time.process_time() >= deadline - 2.0:
            break
        cap = min(deadline - 1.0, time.process_time() + 12.0)
        hp, rp = _polish(hv, cap, record_R)
        print("  polish %-14s -> R=%.7f" % (name, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.7f" % bestRH)

    # remaining time: alternate sharp + peak polish on best
    rng = np.random.default_rng(987654321)
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 250, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            improved = True
        if time.process_time() < loop_end:
            frac = 0.04 + 0.12 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
        if improved:
            print("  iter=%d R=%.7f" % (it, bestRH))
        else:
            if time.process_time() < loop_end - 2.0:
                beta = 10.0 ** rng.uniform(1.0, 4.0)
                cap = min(loop_end, time.process_time() + 3.0)
                hs = _lbfgs_log(bestH, 120, cap, beta=beta)
                rs = R_of(hs)
                if rs > bestRH + 1e-13:
                    bestH, bestRH = hs.copy(), rs
                    print("  soft beta=%.1e R=%.7f" % (beta, bestRH))

    print("final R=%.7f" % bestRH)

    if bestRH > start_bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH
    else:
        best, bestR = start_best, start_bestR

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    if bestH.size != start_best.size or bestRH > start_bestR - 1e-6:
        return {"best": start_best, "alternative": bestH}
    return {"best": start_best, "alternative": None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_window_at(h, lo, hi, rng, sigma=0.30):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _smooth_shift(h, shift):
    """Shift heights by a fractional amount via linear interpolation, keeping length."""
    n = h.size
    x = np.arange(n, dtype=float)
    xi = x - shift
    return np.interp(xi, x, h, left=0.0, right=0.0)


def _try_resample(h, n_new):
    """Resample h onto n_new steps by piecewise-linear interpolation of the cumulative shape."""
    n = h.size
    if n_new == n:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(n_new) + 0.5) / n_new
    return np.interp(x_new, x_old, h, left=0.0, right=0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    hard_end = deadline - 0.5
    n = cur.size

    # ---- NEW IDEA: fractional-shift search.  The optimal f likely has a
    # continuum structure; snapping to step boundaries loses R.  Try small
    # sub-step shifts of the whole profile and re-optimise.
    for shift in (0.5, -0.5, 0.25, -0.25, 0.75, -0.75):
        if time.process_time() >= hard_end - 2.0:
            break
        hs = _smooth_shift(cur, shift)
        hs = _rescale(hs)
        if hs.sum() <= 0:
            continue
        r0 = R_of(hs)
        if r0 < cur_r - 5e-3:
            continue
        # quick local polish
        c = _lbfgs_log(hs, maxiter=400, deadline=hard_end)
        if R_of(c) > r0:
            hs = c
        for beta in (400.0, 1000.0):
            if time.process_time() >= hard_end - 1.0:
                break
            c = _lbfgs_sm(hs, beta, maxiter=300, deadline=hard_end)
            if R_of(c) > R_of(hs):
                hs = c
        c = _window_polish_peak(hs, hard_end, 0.20, 8, maxiter=400)
        if R_of(c) > R_of(hs):
            hs = c
        _consider(hs, R_of(hs))

    print("shift R=%.6f N=%d" % (best_r, best.size))

    # ---- Resample search: try a slightly different N (finer near optimum) ----
    for factor in (1.5, 2.0, 0.5):
        if time.process_time() >= hard_end - 2.0:
            break
        n_new = int(min(1000000, max(64, int(n * factor))))
        if n_new == n:
            continue
        hr = _try_resample(cur, n_new)
        hr = _rescale(hr)
        if hr.sum() <= 0:
            continue
        for beta in (500.0, 1200.0):
            if time.process_time() >= hard_end - 1.0:
                break
            c = _lbfgs_sm(hr, beta, maxiter=250, deadline=hard_end)
            if R_of(c) > R_of(hr):
                hr = c
        c = _lbfgs_log(hr, maxiter=400, deadline=hard_end)
        if R_of(c) > R_of(hr):
            hr = c
        r = R_of(hr)
        # If resampled shape is better, adopt its length for further work.
        if r > best_r:
            _consider(hr, r)
            if r > best_r - 1e-9 or r > cur_r:
                # adopt new size only if it is at least as good
                pass
    print("resample R=%.6f N=%d" % (best_r, best.size))

    # ---- Seeded sliding-window perturbations (as before, fewer seeds) ----
    n_seeds = 10
    for seed in range(n_seeds):
        if time.process_time() >= hard_end - 1.0:
            break
        rng_s = np.random.default_rng(7000 + seed)
        lo = int(rng_s.uniform(0.0, 0.35) * cur.size)
        hi = min(cur.size, lo + cur.size // 2)
        h = _perturb_window_at(cur, lo, hi, rng_s, sigma=0.30)
        for beta in (300.0, 800.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        for frac in (0.15, 0.30):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _window_polish_peak(h, hard_end, frac, 8, maxiter=300)
            if R_of(c) >= R_of(h):
                h = c
        _consider(h, R_of(h))

    print("perturb R=%.6f N=%d" % (best_r, best.size))

    # ---- Fallback refinement ----
    try:
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=300, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
