    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_sm(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_sm(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _peak_window(h, frac, pad):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    half = max(4, int(frac * n)) + pad
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(512)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    alt_returned = None

    # ---- Primary idea: refine on a finer grid; accept if mapped-back improves. ----
    if cur.size < 300000 and time.process_time() < deadline - 25.0:
        N_up = min(cur.size * 2, 400000)
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=500, deadline=deadline - 20.0)
        # peak-window polish at fine grid
        for frac, pad in ((0.05, 4), (0.15, 10)):
            if time.process_time() >= deadline - 18.0:
                break
            win = _peak_window(up, frac, pad)
            cand = _lbfgs_block(up, win, maxiter=400, deadline=deadline - 18.0)
            if R_of(cand) > R_of(up):
                up = cand
        up_r = R_of(up)
        print("fine refine R = %.6f (N=%d)" % (up_r, N_up))
        back = _rescale(_coarsen(up, cur.size))
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        elif up_r > best_r:
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r
        else:
            alt_returned = up.copy()

    # ---- Region-restricted polish of the current best on its own grid. ----
    if time.process_time() < deadline - 8.0:
        for frac, pad in ((0.02, 2), (0.05, 4), (0.12, 8)):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=600, deadline=deadline - 8.0)
            rc = R_of(cand)
            if rc > cur_r:
                cur, cur_r = cand, rc
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r

    # ---- Smoothing continuation ----
    for beta in (4, 16, 64):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_log(cur, maxiter=200, deadline=deadline, beta=beta)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # ---- Main loop: alternate full and windowed polish, restart on stall. ----
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, pad in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=500, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lm = Lf.max()
    w = np.exp(beta * (Lf - Lm))
    Z = w.sum()
    gLf = -dq / num
    gLf += beta * (w / Z)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (np.log(Z) / beta + Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _left_toe_len(h):
    n = h.size
    thresh = 1e-14 * max(h.max(), 1e-300)
    i = 0
    while i < n and h[i] <= thresh:
        i += 1
    if i >= n:
        return 0
    j = i
    while j < n and h[j] > thresh:
        j += 1
    return j - i


def _polish(h, deadline, budget_slice):
    """Block on new cells + first 2K cells, then global sharp, then beta."""
    hp = h.copy()
    rp = R_of(hp)
    return hp, rp


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR

    toe_len = _left_toe_len(best)
    print("base R=%.7f N=%d left_toe_len=%d" % (bestR, best.size, toe_len))

    bestH = best.copy()
    bestRH = bestR

    # Extract toe (first nonzero run)
    thresh = 1e-14 * max(best.max(), 1e-300)
    i0 = 0
    while i0 < best.size and best[i0] <= thresh:
        i0 += 1
    toe_full = best[i0:i0 + toe_len].copy() if toe_len > 0 else best[:16].copy()

    # ---- Left-toe prepend sweep ----
    Ks = [4, 8, 16, 32, 64]
    ss = [0.25, 0.5, 1.0, 2.0]
    gaps = [0, 1, 2, 4, 8]
    candidates = []

    def build_ext(K, s, gap):
        seg = toe_full[:min(K, toe_full.size)]
        if seg.size == 0:
            return None
        tail = s * seg[::-1]
        if gap > 0:
            pad = np.zeros(gap)
            h_ext = np.concatenate((tail, pad, best))
        else:
            h_ext = np.concatenate((tail, best))
        return h_ext

    for K in Ks:
        for s in ss:
            for gap in gaps:
                if time.process_time() > deadline - 12.0:
                    break
                h_ext = build_ext(K, s, gap)
                if h_ext is None:
                    continue
                r_ext = R_of(h_ext)
                candidates.append((r_ext, K, s, gap, h_ext))

    # Also test scaling existing toe
    for mult in (0.5, 1.5, 2.0):
        if time.process_time() > deadline - 12.0:
            break
        h_m = best.copy()
        if toe_len > 0:
            h_m[i0:i0 + toe_len] *= mult
        r_m = R_of(h_m)
        candidates.append((r_m, -1, mult, 0, h_m))

    candidates.sort(key=lambda x: -x[0])
    print("top candidates (R, K, s, gap):")
    for c in candidates[:8]:
        print("  R=%.7f K=%d s=%.2f gap=%d" % (c[0], c[1], c[2], c[3]))

    # Polish top candidates
    for idx, (r_ext, K, s, gap, h_ext) in enumerate(candidates[:8]):
        if time.process_time() > deadline - 6.0:
            break
        n = h_ext.size
        if K > 0:
            free = np.arange(0, min(n, K + 2 * K + gap))
        else:
            free = np.arange(0, min(n, 3 * toe_len + 2))
        sub_dl = min(deadline - 4.0, time.process_time() + 4.0)
        hp = _lbfgs_block(h_ext, free, 150, sub_dl)
        rp = R_of(hp)
        if time.process_time() < deadline - 3.0:
            sub_dl = min(deadline - 2.5, time.process_time() + 3.0)
            hg = _lbfgs_log(hp, 200, sub_dl)
            rg = R_of(hg)
            if rg > rp:
                hp, rp = hg, rg
        if time.process_time() < deadline - 2.0:
            sub_dl = min(deadline - 1.5, time.process_time() + 2.0)
            hb = _lbfgs_log(hp, 100, sub_dl,
                            fg=lambda hh, b=1e4: _fun_grad_beta(hh, b))
            rb = R_of(hb)
            if rb > rp + 1e-13:
                hp, rp = hb, rb
        print("  polish K=%d s=%.2f gap=%d Rbefore=%.7f Rafter=%.7f" %
              (K, s, gap, r_ext, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    ACCEPT R=%.7f" % bestRH)

    # ---- Remaining time: repeat with halved K around best ----
    K_cur = 64
    while time.process_time() < deadline - 3.0 and K_cur >= 2:
        if bestRH <= start_bestR + 1e-13:
            break
        # rebuild toe from bestH
        th2 = 1e-14 * max(bestH.max(), 1e-300)
        j0 = 0
        while j0 < bestH.size and bestH[j0] <= th2:
            j0 += 1
        j1 = j0
        while j1 < bestH.size and bestH[j1] > th2:
            j1 += 1
        toe2 = bestH[j0:j1].copy()
        if toe2.size == 0:
            break
        improved = False
        for s in (0.5, 1.0, 1.5):
            if time.process_time() > deadline - 4.0:
                break
            seg = toe2[:min(K_cur, toe2.size)]
            tail = s * seg[::-1]
            h_ext = np.concatenate((tail, bestH))
            r_ext = R_of(h_ext)
            n = h_ext.size
            free = np.arange(0, min(n, K_cur + 2 * K_cur))
            sub_dl = min(deadline - 2.0, time.process_time() + 4.0)
            hp = _lbfgs_block(h_ext, free, 150, sub_dl)
            rp = R_of(hp)
            if time.process_time() < deadline - 2.0:
                sub_dl = min(deadline - 1.0, time.process_time() + 3.0)
                hg = _lbfgs_log(hp, 200, sub_dl)
                rg = R_of(hg)
                if rg > rp:
                    hp, rp = hg, rg
            print("  refine K=%d s=%.2f Rbefore=%.7f Rafter=%.7f" %
                  (K_cur, s, r_ext, rp))
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
                print("    ACCEPT R=%.7f" % bestRH)
        K_cur //= 2
        if not improved and K_cur < 4:
            break

    # Final global polish
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m_, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m_, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def _rasterize(params, N):
    aL, aR, pL, pR, cap, base, epsL, epsR = params
    aL = np.exp(aL); aR = np.exp(aR); cap = np.exp(cap)
    epsL = np.exp(epsL); epsR = np.exp(epsR)
    pL = np.clip(pL, 0.05, 4.0); pR = np.clip(pR, 0.05, 4.0)
    base = max(base, 0.0)
    sub = 8
    M = N * sub
    x = (np.arange(M) + 0.5) / M
    val = aL * np.power(x + epsL, -pL) + aR * np.power(1.0 - x + epsR, -pR) + base
    val = np.minimum(val, cap)
    return val.reshape(N, sub).mean(axis=1)


def _lbfgs(h, iters, deadline, beta=0.0):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        return h
    n = len(h)
    # work in log space
    def obj(z):
        if time.process_time() > deadline:
            raise TimeoutError
        hh = np.exp(np.clip(z, -30, 30))
        s = hh.sum()
        L = np.convolve(hh, hh)
        L = np.concatenate(([0.0], L, [0.0]))
        sq = np.sum(L[:-1]*L[:-1] + L[:-1]*L[1:] + L[1:]*L[1:]) / 3.0
        inf = L.max()
        r = sq / (s*s*inf)
        # penalty for smoothness (beta) to encourage flat plateau
        pen = 0.0
        if beta > 0:
            d = np.diff(hh)
            pen = beta * np.sum(d*d) / (s*s)
        return -(r - pen * 1e-3)
    z0 = np.log(np.maximum(h, 1e-12))
    try:
        res = minimize(obj, z0, method='L-BFGS-B', options={'maxiter': iters, 'maxfun': iters*3})
        out = np.exp(np.clip(res.x, -30, 30))
        if _R(out) > _R(h):
            return out
    except TimeoutError:
        pass
    except Exception:
        pass
    return h


def _prolongate(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    out = np.interp(x_new, x_old, h)
    # mass preserving
    s_old = h.sum() / n
    s_new = out.sum() / N
    if s_new > 0:
        out *= s_old / s_new
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 5.0
    best = None
    best_R = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best = s.copy()
            best_R = _R(best)

    rng = np.random.default_rng(12345)
    N0 = 2048

    # random search
    candidates = []
    n_draws = 2000
    for i in range(n_draws):
        if time.process_time() > deadline - 20:
            break
        params = np.array([
            rng.uniform(-3, 3),      # log aL
            rng.uniform(-3, 3),      # log aR
            rng.uniform(0.1, 3.0),   # pL
            rng.uniform(0.1, 3.0),   # pR
            rng.uniform(0, 9.2),     # log cap
            rng.uniform(0, 0.2),     # base
            rng.uniform(np.log(1e-4), np.log(0.05)),  # log epsL
            rng.uniform(np.log(1e-4), np.log(0.05)),  # log epsR
        ])
        h = _rasterize(params, N0)
        r = _R(h)
        candidates.append((r, params, h))
    candidates.sort(key=lambda t: -t[0])
    top = candidates[:8]

    # Nelder-Mead on params
    refined = []
    for r0, params, h0 in top:
        if time.process_time() > deadline - 15:
            refined.append((r0, params, h0))
            continue
        def obj(p):
            if time.process_time() > deadline - 15:
                raise TimeoutError
            try:
                hh = _rasterize(p, N0)
                return -_R(hh)
            except Exception:
                return 1.0
        try:
            res = minimize(obj, params, method='Nelder-Mead',
                           options={'maxiter': 400, 'xatol': 1e-4, 'fatol': 1e-7})
            hh = _rasterize(res.x, N0)
            refined.append((_R(hh), res.x, hh))
        except TimeoutError:
            refined.append((r0, params, h0))
        except Exception:
            refined.append((r0, params, h0))
    refined.sort(key=lambda t: -t[0])

    # L-BFGS on top few
    for r0, params, h0 in refined[:3]:
        if time.process_time() > deadline - 10:
            break
        hh = _lbfgs(h0, 200, deadline - 8)
        if _R(hh) > best_R:
            best_R = _R(hh); best = hh

    if refined:
        r0, params, h0 = refined[0]
        if _R(h0) > best_R:
            best_R = _R(h0); best = h0
        # beta pass
        if time.process_time() < deadline - 8:
            hb = _lbfgs(h0, 200, deadline - 6, beta=1e4)
            if _R(hb) > best_R:
                best_R = _R(hb); best = hb

    if best is None:
        best = np.ones(50)
        best_R = _R(best)

    # resolution ladder
    for N in (4096, 8192):
        if time.process_time() > deadline - 3:
            break
        h = _prolongate(best, N)
        h = _lbfgs(h, 200, deadline - 2)
        if _R(h) > best_R:
            best_R = _R(h); best = h
        if time.process_time() < deadline - 2:
            hb = _lbfgs(h, 200, deadline - 1, beta=1e4)
            if _R(hb) > best_R:
                best_R = _R(hb); best = hb

    if refined:
        r0, params, h0 = refined[0]
        aL, aR, pL, pR, cap, base, epsL, epsR = params
        print("params: aL=%.3g aR=%.3g pL=%.3g pR=%.3g cap=%.3g base=%.3g epsL=%.3g epsR=%.3g"
              % (np.exp(aL), np.exp(aR), pL, pR, np.exp(cap), base, np.exp(epsL), np.exp(epsR)))
    print("best R = %.6f, N = %d" % (best_R, len(best)))

    result = {"best": best}
    if start is not None:
        s = np.asarray(start, dtype=float)
        if _R(s) >= best_R:
            result["best"] = s
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _coarsen(h, k):
    n = h.size
    if n % k != 0:
        return None
    return h.reshape(n // k, k).sum(axis=1)


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        # Fallback: simple seed if no start given
        N = 4096
        h = np.ones(N)
        best = _rescale(h)
        best_r = R_of(best)

    # Work at a coarse grid: try several coarsening factors and pick best.
    # This is the key new idea: multi-scale coarsening search with homotopy on coarse
    # grid, then re-detailing, which explores a wider basin than the single factor-4
    # coarsening of the original.
    n = best.size

    # First refine slightly at fine scale
    cand = _lbfgs_log(best, maxiter=200, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r

    # Try multiple coarsening factors
    best_coarse = None
    best_coarse_r = -1.0
    best_factor = 1
    for k in (2, 4, 8):
        if n % k != 0:
            continue
        hc = _coarsen(best, k)
        if hc is None:
            continue
        rc = R_of(hc)
        if rc > best_coarse_r:
            best_coarse, best_coarse_r = hc, rc
            best_factor = k

    # Spend ~35% of budget optimizing the best coarse representation
    if best_coarse is not None and best_factor > 1:
        coarse_deadline = min(deadline, time.process_time() + 0.35 * (deadline - time.process_time()))
        cc = best_coarse.copy()
        cr = best_coarse_r
        cand = _lbfgs_log(cc, maxiter=600, deadline=coarse_deadline)
        r = R_of(cand)
        if r > cr:
            cc, cr = cand, r
        cc, cr = _homotopy(cc, (64, 256, 1024, 4096, 12000), 250, coarse_deadline)
        cc, cr = _polish(cc, coarse_deadline, cr,
                         fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400)
        cand = _lbfgs_log(cc, maxiter=300, deadline=coarse_deadline)
        r = R_of(cand)
        if r > cr:
            cc, cr = cand, r
        print("coarse (k=%d) optimised: R=%.6f" % (best_factor, cr))

        # Re-detail
        fine = np.repeat(cc, best_factor) / float(best_factor)
        fine_r = R_of(fine)
        print("re-detailed: R=%.6f (was %.6f)" % (fine_r, best_r))
        if fine_r > best_r:
            best, best_r = fine, fine_r

    # Now polish the fine grid with homotopy + local polish
    cand = _lbfgs_log(best, maxiter=600, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r
    print("after log polish R=%.6f" % best_r)

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        cand, r = _homotopy(best, (400, 1024, 2048, 4096, 8000, 16000), 250, deadline)
        if r > best_r:
            best, best_r = cand, r
        cand = _lbfgs_log(best, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
        cand, r = _polish(best, deadline, best_r,
                          fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400)
        if r > best_r:
            best, best_r = cand, r
        print("  iter#%d R=%.6f" % (it, best_r))

    print("best R=%.6f (start %.6f)" % (best_r, start_r))
    best = _rescale(best)

    if start_arr is not None and start_r >= best_r:
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

