    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _gauss_smooth(h, sigma):
    if sigma <= 0.5:
        return h.copy()
    r = int(3 * sigma) + 1
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _smooth_perturb(h, sigma, amp, seed):
    n = h.size
    rng = np.random.RandomState(seed)
    m = max(16, n // 64)
    noise = rng.randn(m)
    xp = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, n)
    p = np.interp(xi, xp, noise)
    return np.clip(h * np.exp(amp * p), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    alt = None
    altR = 0.0

    # NEW primary idea: soft-max (beta-smoothed L_inf) polish.
    # The hard max makes the gradient sparse (only peak knots). A smooth
    # soft-max spreads gradient across near-peak knots, letting L-BFGS
    # reshape the whole top plateau simultaneously -- escaping the
    # single-knot local optimum that the hard-max polish gets stuck in.
    # We anneal beta from small (broad) to large (sharp) to converge to
    # the true R optimum.
    betas = [8.0, 20.0, 50.0, 120.0, 300.0, 800.0, 0.0]
    h_cur = best.copy()
    for beta in betas:
        if time.process_time() >= deadline - 6.0:
            break
        h_cur = _lbfgs_log(h_cur, 300, deadline, beta=beta)
        h_cur = _window_polish_peak(h_cur, deadline, 0.40, 24, beta=beta)
        r = R_of(h_cur)
        print("softmax beta=%.1f R=%.7f" % (beta, r))
        if r > altR:
            alt, altR = h_cur.copy(), r
        if r > bestR + 1e-15:
            best, bestR = h_cur.copy(), r

    # Second primary pass: restart annealing from best with perturbed copy
    # to explore a different basin near the peak.
    if time.process_time() < deadline - 20.0:
        for sigma, amp, seed in ((max(2.0, N / 400.0), 0.04, 11),
                                 (max(3.0, N / 250.0), 0.06, 12)):
            if time.process_time() >= deadline - 15.0:
                break
            hp = _smooth_perturb(best, sigma, amp, seed)
            hp = _rescale(hp)
            for beta in [15.0, 60.0, 200.0, 0.0]:
                if time.process_time() >= deadline - 8.0:
                    break
                hp = _lbfgs_log(hp, 250, deadline, beta=beta)
                hp = _window_polish_peak(hp, deadline, 0.40, 24, beta=beta)
            r = R_of(hp)
            print("perturb-anneal s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
            if r > altR:
                alt, altR = hp.copy(), r
            if r > bestR + 1e-15:
                best, bestR = hp.copy(), r

    # Coarse-grain + re-optimise (secondary), with soft-max polish.
    if time.process_time() < deadline - 12.0:
        for factor in (4, 2):
            if time.process_time() >= deadline - 10.0:
                break
            Nc = max(256, N // factor)
            hc = _coarse(best, Nc)
            hc = _rescale(hc)
            hc = _gauss_smooth(hc, sigma=max(1.0, Nc / 400.0))
            hc = _rescale(hc)
            hc = _lbfgs_log(hc, 500, deadline)
            hc = _window_polish_peak(hc, deadline, 0.5, 8)
            r = R_of(hc)
            hp = _prolongate(hc, N)
            hp = _rescale(hp)
            for beta in [20.0, 80.0, 0.0]:
                if time.process_time() >= deadline - 6.0:
                    break
                hp = _lbfgs_log(hp, 300, deadline, beta=beta)
                hp = _window_polish_peak(hp, deadline, 0.40, 24, beta=beta)
            rp = R_of(hp)
            print("prolong %d->%d R=%.7f" % (Nc, N, rp))
            if rp > altR:
                alt, altR = hp.copy(), rp
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp

    # Phase exploration with soft-max polish.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 4.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = _lbfgs_log(hp, 500, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp.copy(), r

    # Final loop: alternate hard polish and one more softmax anneal on best.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_log(best, 400, deadline, beta=50.0)
        h = _window_polish_peak(h, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = fftconvolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def _rasterize(params, N):
    c, aL, pL, wL, aR, pR, wR, epsL, epsR = params
    c = np.clip(c, 0.01, 10.0)
    aL = np.exp(np.clip(aL, np.log(1e-4), np.log(1e3)))
    aR = np.exp(np.clip(aR, np.log(1e-4), np.log(1e3)))
    pL = np.clip(pL, 0.1, 0.5)
    pR = np.clip(pR, 0.1, 0.5)
    wL = np.clip(wL, 1e-4, 0.1)
    wR = np.clip(wR, 1e-4, 0.1)
    epsL = np.exp(np.clip(epsL, np.log(1e-6), np.log(1e-3)))
    epsR = np.exp(np.clip(epsR, np.log(1e-6), np.log(1e-3)))
    sub = 8
    M = N * sub
    x = (np.arange(M) + 0.5) / M
    val = np.full(M, c)
    mL = x < wL
    mR = x > 1.0 - wR
    val[mL] += aL * np.power(x[mL] + epsL, -pL)
    val[mR] += aR * np.power(1.0 - x[mR] + epsR, -pR)
    return val.reshape(N, sub).mean(axis=1)


def _lbfgs_log(h, iters, deadline, beta=0.0):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 1e-12)
    if h.sum() <= 0:
        return h

    def obj(z):
        if time.process_time() > deadline:
            raise TimeoutError
        hh = np.exp(np.clip(z, -30, 30))
        s = hh.sum()
        L = fftconvolve(hh, hh)
        L = np.concatenate(([0.0], L, [0.0]))
        sq = np.sum(L[:-1]*L[:-1] + L[:-1]*L[1:] + L[1:]*L[1:]) / 3.0
        inf = L.max()
        r = sq / (s*s*inf)
        pen = 0.0
        if beta > 0:
            d = np.diff(hh)
            pen = beta * np.sum(d*d) / (s*s)
        return -(r - pen * 1e-3)

    z0 = np.log(h)
    try:
        res = minimize(obj, z0, method='L-BFGS-B',
                       options={'maxiter': iters, 'maxfun': iters*3})
        out = np.exp(np.clip(res.x, -30, 30))
        if _R(out) > _R(h):
            return out
    except TimeoutError:
        pass
    except Exception:
        pass
    return h


def _prolongate(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    out = np.interp(x_new, x_old, h)
    s_old = h.sum() / n
    s_new = out.sum() / N
    if s_new > 0:
        out *= s_old / s_new
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 5.0
    best = None
    best_R = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best = s.copy()
            best_R = _R(best)

    rng = np.random.default_rng(987654)
    N0 = 1024

    # random search over new family
    candidates = []
    n_draws = 4000
    for i in range(n_draws):
        if time.process_time() > deadline - 25:
            break
        params = np.array([
            np.exp(rng.uniform(np.log(0.01), np.log(10.0))),  # c
            rng.uniform(np.log(1e-4), np.log(1e3)),           # log aL
            rng.uniform(0.1, 0.5),                            # pL
            np.exp(rng.uniform(np.log(1e-4), np.log(0.1))),   # wL
            rng.uniform(np.log(1e-4), np.log(1e3)),           # log aR
            rng.uniform(0.1, 0.5),                            # pR
            np.exp(rng.uniform(np.log(1e-4), np.log(0.1))),   # wR
            rng.uniform(np.log(1e-6), np.log(1e-3)),          # log epsL
            rng.uniform(np.log(1e-6), np.log(1e-3)),          # log epsR
        ])
        h = _rasterize(params, N0)
        r = _R(h)
        candidates.append((r, params, h))
    candidates.sort(key=lambda t: -t[0])
    top = candidates[:12]

    # Nelder-Mead on params
    refined = []
    for r0, params, h0 in top:
        if time.process_time() > deadline - 18:
            refined.append((r0, params, h0))
            continue

        def obj(p):
            if time.process_time() > deadline - 18:
                raise TimeoutError
            try:
                hh = _rasterize(p, N0)
                return -_R(hh)
            except Exception:
                return 1.0
        try:
            res = minimize(obj, params, method='Nelder-Mead',
                           options={'maxiter': 200, 'xatol': 1e-5, 'fatol': 1e-8})
            hh = _rasterize(res.x, N0)
            refined.append((_R(hh), res.x, hh))
        except TimeoutError:
            refined.append((r0, params, h0))
        except Exception:
            refined.append((r0, params, h0))
    refined.sort(key=lambda t: -t[0])

    # L-BFGS on top 3 at N0
    for r0, params, h0 in refined[:3]:
        if time.process_time() > deadline - 15:
            break
        hh = _lbfgs_log(h0, 200, deadline - 14)
        if _R(hh) > best_R:
            best_R = _R(hh); best = hh

    if refined:
        r0, params, h0 = refined[0]
        if _R(h0) > best_R:
            best_R = _R(h0); best = h0

    if best is None:
        best = np.ones(50)
        best_R = _R(best)

    # resolution ladder
    for N in (4096, 16384, 32768):
        if time.process_time() > deadline - 6:
            break
        h = _prolongate(best, N)
        h = _lbfgs_log(h, 200, deadline - 4)
        r = _R(h)
        print("N=%d R=%.6f" % (N, r))
        if r > best_R:
            best_R = r; best = h
        if time.process_time() < deadline - 4:
            hb = _lbfgs_log(h, 200, deadline - 3, beta=1e4)
            rb = _R(hb)
            if rb > best_R:
                best_R = rb; best = hb
                print("N=%d beta R=%.6f" % (N, rb))

    # final param re-optimization at best N
    if refined and time.process_time() < deadline - 1:
        Nbest = len(best)
        params0 = refined[0][1]
        tcap = time.process_time() + 1.5

        def obj2(p):
            if time.process_time() > tcap:
                raise TimeoutError
            try:
                hh = _rasterize(p, Nbest)
                return -_R(hh)
            except Exception:
                return 1.0
        try:
            res = minimize(obj2, params0, method='Nelder-Mead',
                           options={'maxiter': 300, 'xatol': 1e-5, 'fatol': 1e-8})
            hh = _rasterize(res.x, Nbest)
            if _R(hh) > best_R:
                best_R = _R(hh); best = hh
                print("final param R=%.6f" % best_R)
        except TimeoutError:
            pass
        except Exception:
            pass

    print("best R = %.6f, N = %d" % (best_R, len(best)))

    result = {"best": best}
    if start is not None:
        s = np.asarray(start, dtype=float)
        if _R(s) >= best_R:
            result["best"] = s
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _restrict(h, m):
    n = h.size
    if m <= 1:
        return h.copy()
    nr = (n + m - 1) // m
    pad = nr * m - n
    if pad > 0:
        hh = np.concatenate((h, np.zeros(pad)))
    else:
        hh = h
    return hh.reshape(nr, m).sum(axis=1)


def _prolong(hc, n):
    nr = hc.size
    m = (n + nr - 1) // nr
    out = np.repeat(hc / m, m)
    if out.size > n:
        out = out[:n]
    elif out.size < n:
        out = np.concatenate((out, np.zeros(n - out.size)))
    return out


def _lbfgs_coarse(h0, maxiter, deadline, beta=0.0):
    """Like _lbfgs_log but scores by exact R of prolongation is handled by caller;
    here we just optimize the coarse-level R directly (cheaper)."""
    return _lbfgs_log(h0, maxiter, deadline, beta=beta)


def _vcycle(h_best, deadline, m=4):
    n = h_best.size
    hc = _rescale(_restrict(h_best, m))
    best_hc = hc.copy()
    best_cR = R_of(_prolong(best_hc, n))
    coarse_deadline = min(deadline, time.process_time() + 3.0)
    for beta in (2.0, 5.0, 10.0, 25.0, 50.0, 100.0):
        if time.process_time() >= coarse_deadline - 0.3:
            break
        cap = min(coarse_deadline, time.process_time() + 1.0)
        hc2 = _lbfgs_coarse(best_hc, 120, cap, beta=beta)
        cR = R_of(_prolong(hc2, n))
        if cR > best_cR + 1e-13:
            best_hc, best_cR = hc2, cR
    coarseR = best_cR
    fine_res = h_best - _prolong(_restrict(h_best, m), n)
    cand = _prolong(best_hc, n) + fine_res
    cand = _rescale(np.clip(cand, 0, None))
    candR = R_of(cand)
    return cand, coarseR, candR


def _smooth_perturb(h, rng, scale=0.02):
    """Random smooth multiplicative perturbation to escape local optima."""
    n = h.size
    k = max(4, n // 200)
    x = np.linspace(0, 1, n)
    noise = np.zeros(n)
    for _ in range(3):
        freq = rng.uniform(1.0, 8.0)
        phase = rng.uniform(0, 2 * np.pi)
        noise += rng.uniform(0.3, 1.0) * np.sin(2 * np.pi * freq * x + phase)
    fac = 1.0 + scale * noise
    out = h * np.clip(fac, 0.5, 1.5)
    return _rescale(np.clip(out, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR
    rng = np.random.default_rng(1234567)

    # ---- main loop: alternate V-cycles with perturbed restarts ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False

        # 1) V-cycle from current best
        if time.process_time() < loop_end - 6.0:
            vc_deadline = min(loop_end, time.process_time() + 8.0)
            cand, coarseR, candR = _vcycle(bestH, vc_deadline, m=int(rng.choice([2, 3, 4, 5])))
            polished = cand
            polR = candR
            if time.process_time() < vc_deadline - 0.5:
                cap = min(vc_deadline, time.process_time() + 3.0)
                hs = _lbfgs_log(cand, 300, cap, beta=0.0)
                rs = R_of(hs)
                if rs > polR + 1e-13:
                    polished, polR = hs, rs
            if polR > bestRH + 1e-13:
                bestH, bestRH = polished.copy(), polR
                improved = True
                print("  it=%d V-cycle NEW BEST R=%.7f" % (it, bestRH))

        # 2) smooth perturbed restart to escape local optima
        if time.process_time() < loop_end - 4.0:
            sc = float(rng.choice([0.005, 0.01, 0.02, 0.04]))
            hp = _smooth_perturb(bestH, rng, scale=sc)
            cap = min(loop_end, time.process_time() + 4.0)
            hs = _lbfgs_log(hp, 400, cap, beta=0.0)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
                improved = True
                print("  it=%d perturb(%.3f) NEW BEST R=%.7f" % (it, sc, bestRH))

        # 3) peak-window polish
        if time.process_time() < loop_end - 2.0:
            frac = float(rng.choice([0.02, 0.05, 0.10]))
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
                print("  it=%d peak(%.2f) NEW BEST R=%.7f" % (it, frac, bestRH))

        if not improved and time.process_time() < loop_end - 2.0:
            # plain sharpen
            cap = min(loop_end, time.process_time() + 2.0)
            hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs

    print("final R=%.7f (best of experiment)" % bestRH)

    if bestRH > start_bestR + 1e-12:
        best, bestR = bestH.copy(), bestRH
    else:
        best, bestR = start_best, start_bestR

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    if bestH.size == start_best.size and bestRH > start_bestR - 1e-4:
        return {"best": start_best, "alternative": bestH}
    return {"best": start_best, "alternative": None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_window_at(h, lo, hi, rng, sigma=0.30):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _refine(h, hard_end):
    """Full refinement pipeline on a single candidate."""
    for beta in (300.0, 120.0, 60.0, 30.0):
        if time.process_time() >= hard_end - 0.4:
            break
        c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
        if R_of(c) >= R_of(h):
            h = c
    if time.process_time() < hard_end - 0.4:
        c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
        if R_of(c) >= R_of(h):
            h = c
    for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
        if time.process_time() >= hard_end - 0.4:
            break
        c = _window_polish_peak(h, hard_end, frac, extra, maxiter=300)
        if R_of(c) >= R_of(h):
            h = c
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    hard_end = deadline - 0.3

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    best = start_arr.copy()
    best_r = R_of(best)
    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand.copy(), r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r
        return r

    n = cur.size

    # Phase 1: strong local refinement of start alone (quick gain).
    if time.process_time() < hard_end - 2.0:
        c = _refine(cur, min(hard_end, time.process_time() + 8.0))
        _consider(c)

    # Phase 2: many seeded perturbations over diverse windows.
    n_seeds = 24
    for seed in range(n_seeds):
        if time.process_time() >= hard_end - 1.5:
            break
        rng_s = np.random.default_rng(7000 + seed)
        mode = seed % 4
        if mode == 0:
            lo = int(rng_s.uniform(0.0, 0.5) * n)
            hi = min(n, lo + n // 2)
        elif mode == 1:
            # concentrate near the peak of f*f
            Lf = _knots(cur)
            m = int(np.argmax(Lf))
            lo = max(0, m - n // 4)
            hi = min(n, m + n // 4)
        elif mode == 2:
            lo = int(rng_s.uniform(0.0, 0.6) * n)
            hi = min(n, lo + int(rng_s.uniform(0.2, 0.5) * n))
        else:
            lo = int(rng_s.uniform(0.0, 0.2) * n)
            hi = min(n, lo + int(rng_s.uniform(0.4, 0.8) * n))
        sigma = float(rng_s.uniform(0.15, 0.45))
        h = _perturb_window_at(cur, lo, hi, rng_s, sigma=sigma)
        # short smoothing to escape perturbation
        for beta in (800.0, 300.0):
            if time.process_time() >= hard_end - 1.0:
                break
            c = _lbfgs_sm(h, beta, maxiter=150, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 1.0:
            c = _refine(h, hard_end)
            _consider(c)

    print("phase2 R=%.6f N=%d" % (best_r, best.size))

    # Phase 3: keep polishing best until nearly out of time.
    try:
        while time.process_time() < hard_end - 1.0:
            before = best_r
            c = _refine(best, hard_end)
            _consider(c)
            if best_r <= before + 1e-9:
                # try a small perturbation to break plateau
                rng_s = np.random.default_rng(int(time.process_time() * 1000) & 0xffff)
                Lf = _knots(best)
                m = int(np.argmax(Lf))
                lo = max(0, m - n // 3)
                hi = min(n, m + n // 3)
                h = _perturb_window_at(best, lo, hi, rng_s, sigma=0.10)
                c = _refine(h, hard_end)
                _consider(c)
                if best_r <= before + 1e-9:
                    break
        print("phase3 R=%.6f" % best_r)
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

