    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _shift_raster(h, delta):
    """Exact cell-averaging of the shifted step function."""
    n = h.size
    k = int(np.floor(delta))
    u = delta - k
    idx = np.arange(n)
    i0 = np.clip(idx + k, 0, n - 1)
    i1 = np.clip(idx + k + 1, 0, n - 1)
    hd = (1.0 - u) * h[i0] + u * h[i1]
    hd = np.clip(hd, 0.0, None)
    return _rescale(hd)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    # ---- Phase-shift rasterisation experiment ----
    bestH = best.copy()
    bestRH = bestR
    deltas = (-0.5, -0.25, 0.25, 0.5)
    for delta in deltas:
        if time.process_time() >= deadline - 2.0:
            break
        hd = _shift_raster(best, delta)
        r_raw = R_of(hd)
        print("  delta=%+.2f raw R=%.9f (vs %.9f)" % (delta, r_raw, bestRH))
        # polish this shifted candidate
        cand = hd
        candR = r_raw
        if time.process_time() < deadline - 1.5:
            cap = min(deadline - 1.0, time.process_time() + 3.0)
            hs = _lbfgs_log(cand, 200, cap, beta=0.0)
            rs = R_of(hs)
            if rs > candR:
                cand, candR = hs, rs
        if time.process_time() < deadline - 1.0:
            free = _peak_window(cand, frac=0.10)
            cap = min(deadline - 1.0, time.process_time() + 2.0)
            hs = _lbfgs_block(cand, free, 150, cap, beta=0.0)
            rs = R_of(hs)
            if rs > candR:
                cand, candR = hs, rs
        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 1.0, time.process_time() + 2.0)
            hs = _lbfgs_log(cand, 150, cap, beta=1e4)
            rs = R_of(hs)
            if rs > candR:
                cand, candR = hs, rs
        print("  delta=%+.2f polished R=%.9f" % (delta, candR))
        if candR > bestRH + 1e-13:
            bestH, bestRH = cand.copy(), candR
            print("    NEW BEST R=%.9f (delta=%+.2f)" % (bestRH, delta))

    # ---- Final full polish of the best array ----
    if time.process_time() < deadline - 1.0:
        cap = deadline - 0.5
        hp, rp = _polish(bestH, cap, bestRH)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp, rp
            print("  final polish R=%.9f" % bestRH)

    # If time remains, keep polishing
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            free = _peak_window(bestH, frac=0.10)
            cap = min(loop_end, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _restrict(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _perturb(h, rng, sigma=0.20):
    h = h.copy()
    n = h.size
    if n < 8:
        return h
    nblocks = int(rng.integers(3, 6))
    cuts = np.sort(rng.choice(np.arange(1, n), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [n]))
    for b in range(edges.size - 1):
        a = edges[b]; c = edges[b + 1]
        if c <= a:
            continue
        h[a:c] *= np.exp(rng.normal(0.0, sigma))
    pos = h[h > 0]
    if pos.size > 0:
        z = h <= 0
        if np.any(z):
            h[z] = 1e-3 * pos.mean()
    return _rescale(h)


def _polish(h, deadline, betas, fracs):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_log(h, maxiter=250, deadline=deadline, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(h, maxiter=400, deadline=deadline)
        if R_of(c) >= R_of(h):
            h = c
    for frac, extra in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        n = h.size
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(extra, int(span * frac))
        lo = max(0, lo - pad); hi = min(n - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        c = _lbfgs_block(h, free, maxiter=300, deadline=deadline, beta=0.0)
        if R_of(c) >= R_of(h):
            h = c
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds - 2.0

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = _lbfgs_log(np.ones(512), maxiter=800, deadline=hard_end)
        return cur

    start_r = R_of(start_arr)
    best = start_arr.copy()
    best_r = start_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    betas = (3000.0, 1200.0, 500.0, 0.0)
    fracs = ((0.30, 24), (0.15, 12), (0.06, 6))

    # Phase 1: refine on the start's resolution.
    h = _polish(best.copy(), hard_end, betas, fracs)
    _consider(h, R_of(h))
    print("phase1 R=%.6f N=%d" % (best_r, best.size))

    # Phase 2: upsample then polish (finer grid).
    for factor, cap in ((2.0, 128000), (1.5, 192000)):
        if time.process_time() >= hard_end - 1.0:
            break
        N_big = int(min(cap, best.size * factor))
        if N_big <= best.size:
            continue
        h_big = _prolongate(best, N_big)
        h_big = _polish(h_big, hard_end, betas, fracs)
        _consider(h_big, R_of(h_big))
        if best.size < 64000 and time.process_time() < hard_end - 1.0:
            h_small = _restrict(h_big, best.size)
            h_small = _polish(h_small, hard_end, betas, fracs)
            _consider(h_small, R_of(h_small))
        print("upsample N=%d R=%.6f" % (N_big, best_r))

    # Phase 3: perturb-and-polish restarts around the best found.
    seed = 0
    while time.process_time() < hard_end - 1.0:
        rng = np.random.default_rng(9000 + seed)
        seed += 1
        sigma = float(rng.choice([0.08, 0.15, 0.25]))
        h = _perturb(best, rng, sigma=sigma)
        h = _polish(h, hard_end, betas, fracs)
        _consider(h, R_of(h))

    print("final R=%.6f N=%d" % (best_r, best.size))

    if best_r < start_r:
        best = start_arr.copy()
        best_r = start_r
    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

