        return _fun_grad(h)
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return _fun_grad(h)
    Lb = Lf[B]
    Lb_safe = np.clip(Lb, 1e-300, None)
    val = -np.log(num) + 2.0 * np.log(s) + np.mean(np.log(Lb_safe))
    gLf = -dq / num
    gLf[B] += (1.0 / nB) / Lb_safe
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log_band(h0, maxiter, deadline, delta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_band(hh, delta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() > deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _smooth_dilate(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _refine_at_res(h, deadline, rcur, rounds=3):
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        n = h.size
        if n >= 1_000_000:
            break
        m = min(1_000_000, n * 2)
        h2 = _rescale(_prolong(h, m))
        cand = _lbfgs_log(h2, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
        else:
            break
    return h, rcur


def _resample(h, m):
    """Resample h to m steps keeping the total mass; do not upscale peaks badly."""
    return _rescale(_prolong(np.clip(h, 0, None), m))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
        orig_n = start_arr.size
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r
        orig_n = best.size

    # NEW IDEA: multi-resolution ensemble. Instead of only refining at one resolution,
    # run short optimizations at several resolutions (down and up) and keep the best.
    # Lower resolution moves are cheaper per step and escape local minima better;
    # the higher resolution versions then fine-tune.

    # First: a quick direct polish of what we have.
    cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r
    print("initial polish R=%.6f" % best_r)

    alt = None
    alt_r = -1.0

    # Resolutions to try, relative to start size. Include downsampling (cheap, useful).
    base_n = max(256, min(orig_n, 65536))
    resolutions = sorted(set([
        max(256, base_n // 4),
        max(256, base_n // 2),
        base_n,
        min(1_000_000, base_n * 2),
    ]))

    # Round-robin over resolutions until budget is nearly spent.
    round_id = 0
    while time.process_time() < deadline - 2.0:
        round_id += 1
        improved_this_round = False
        for m in resolutions:
            if time.process_time() >= deadline - 2.0:
                break
            # Resample current best to this resolution.
            if best.size != m:
                seed = _resample(best, m)
            else:
                seed = best.copy()
            seed = _rescale(seed)

            # Short homotopy at this resolution.
            cand, r = _homotopy(seed, (128, 512, 2048),
                                maxiter=180, deadline=deadline)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True
            elif alt is None or r > alt_r:
                alt, alt_r = cand, r

            # Local band polish at this resolution.
            if time.process_time() < deadline - 2.0:
                for delta in (0.01, 0.002):
                    if time.process_time() >= deadline - 2.0:
                        break
                    c2 = _lbfgs_log_band(best, maxiter=250,
                                         deadline=deadline, delta=delta)
                    r2 = R_of(c2)
                    if r2 > best_r + 1e-9:
                        best, best_r = c2, r2
                        improved_this_round = True

        # After a full sweep, do a peak polish at the best resolution.
        if time.process_time() < deadline - 2.0:
            cand, r = _polish(best, deadline, best_r,
                              fracs=(0.25, 0.12, 0.05, 0.02),
                              maxiter=250)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True

        # And one final full log polish.
        if time.process_time() < deadline - 2.0:
            cand = _lbfgs_log(best, maxiter=250, deadline=deadline)
            r = R_of(cand)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True

        print("  round %d R=%.6f N=%d alt=%.6f (start %.6f)" %
              (round_id, best_r, best.size,
               alt_r if alt is not None else -1, start_r))

        if not improved_this_round and round_id >= 2:
            # Try a smoothing perturbation to escape a local minimum.
            if time.process_time() < deadline - 2.0:
                for k in (5, 11):
                    if time.process_time() >= deadline - 2.0:
                        break
                    seed = _smooth_dilate(best, k)
                    seed = _rescale(seed)
                    cand, r = _homotopy(seed, (64, 256, 1024),
                                        maxiter=180, deadline=deadline)
                    if r > best_r + 1e-9:
                        best, best_r = cand, r
                        improved_this_round = True
                        break
                    elif alt is None or r > alt_r:
                        alt, alt_r = cand, r
                if not improved_this_round:
                    break

    best = _rescale(best)
    best_r = R_of(best)
    print("FINAL best R=%.6f (start %.6f) N=%d" % (best_r, start_r, best.size))

    # Return logic: always report the best found vs start.
    if start_arr is not None and start_r >= best_r:
        if alt is not None and alt_r > start_r:
            return {"best": start_arr, "alternative": alt}
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        if alt is not None and alt_r > 0 and R_of(alt) < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


# ---------- NEW: local refinement by shrinking around the peak (grid refine) ----------
def _resample(h, factor):
    """Linearly interpolate a step function to a finer grid (factor x)."""
    n = h.size
    m = n * factor
    x = (np.arange(m) + 0.5) * (n / m) - 0.5
    xi = np.clip(x, 0.0, n - 1)
    i0 = np.floor(xi).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    w = xi - i0
    return (1.0 - w) * h[i0] + w * h[i1]


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h
    return h[:m * factor].reshape(m, factor).mean(axis=1)


# ---------- NEW: symmetry-breaking split: try inserting a small dip/step ----------
def _split_attempt(bestH, bestRH, deadline, rng):
    """Try refining by resampling to 2x, running local L-BFGS, then evaluating."""
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH, None
    n = bestH.size
    if n * 2 > 500000:
        return bestH, bestRH, None
    try:
        h2 = _resample(bestH, 2)
    except Exception:
        return bestH, bestRH, None
    # quick local polish on fine grid
    sub = min(deadline - 0.5, time.process_time() + 8.0)
    h2p = _lbfgs_log(h2, 120, sub)
    r2 = R_of(h2p)
    if r2 > bestRH + 1e-13:
        return h2p, r2, (n, n * 2)
    return bestH, bestRH, None


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    rng = np.random.default_rng(12345)

    # ---- main loop: alternate p-norm homotopy, sharp, peak, and 2x refinement ----
    ladder = (4, 8, 16, 32, 64, 128)
    loop_end = t0 + budget_seconds * 0.86
    roundN = 0
    refine_tried = 0
    max_refines = 4

    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 4.0:
        roundN += 1
        for p in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 4.0:
                break
            sub_deadline = min(loop_end, time.process_time() + 6.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 150, sub_deadline, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  R%d p=%d R=%.7f" % (roundN, p, bestRH))

        # sharp + peak polish
        if time.process_time() < loop_end - 1.0:
            sub2 = min(loop_end, time.process_time() + 5.0)
            hs = _lbfgs_log(bestH, 120, sub2)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
            bestH, bestRH = _peak_polish(bestH, bestRH, 120, sub2)
            print("  R%d sharp+peak R=%.7f" % (roundN, bestRH))

        # NEW: try 2x refinement periodically
        if refine_tried < max_refines and time.process_time() < loop_end - 3.0:
            refine_tried += 1
            hn, rn, info = _split_attempt(bestH, bestRH, loop_end, rng)
            if info is not None:
                bestH, bestRH = hn, rn
                print("  refine2x #%d -> N=%d R=%.7f" % (refine_tried, bestH.size, bestRH))

    # ---- final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 300, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 5.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.3, time.process_time() + 3.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(int)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts)
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts)
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


def _refine_toes(h, K, sub=4):
    n = h.size
    K = min(K, n // 2)
    if K <= 0:
        return h.copy(), np.array([], dtype=int)
    left = np.repeat(h[:K], sub) / sub
    right = np.repeat(h[n - K:], sub) / sub
    mid = h[K:n - K]
    h2 = np.concatenate([left, mid, right])
    free = np.concatenate([np.arange(0, K * sub),
                           np.arange(h2.size - K * sub, h2.size)])
    return h2, free


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    mx0, m0, near0 = _stats(start_best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (start_bestR, start_best.size, 100.0 * np.mean(start_best <= 0),
           mx0, m0, near0))

    bestH = start_best.copy()
    bestRH = start_bestR
    alt = start_best.copy()
    altR = start_bestR

    # --- Experiment: toe refinement with multiple K, then polish ---
    K_order = [512, 128, 2048, 32]
    for K in K_order:
        if time.process_time() >= deadline - 8.0:
            break
        cap = min(deadline - 6.0, time.process_time() + 10.0)
        h2, free = _refine_toes(bestH, K, sub=4)
        r0 = R_of(h2)
        # Stage 1: toe-only LBFGS
        hs = _lbfgs_block(h2, free, 200, cap, beta=0.0)
        r1 = R_of(hs)
        # Stage 2: toe-only with beta
        if time.process_time() < cap - 1.0:
            hb = _lbfgs_block(hs, free, 80, min(cap, time.process_time() + 3.0), beta=1e3)
            rb = R_of(hb)
            if rb > r1:
                hs, r1 = hb, rb
        print("  K=%-5d r0=%.9f r1=%.9f (dR=%+.2e)" % (K, r0, r1, r1 - bestRH))
        if r1 > altR + 1e-13:
            alt = hs.copy()
            altR = r1
        if r1 > bestRH + 1e-13:
            # Polish
            cap2 = min(deadline - 2.0, time.process_time() + 6.0)
            hp, rp = _polish(hs, cap2)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp, rp
                print("    NEW BEST R=%.9f" % bestRH)

    # --- Block-additive passes ---
    for B in (128, 256, 512, 1024):
        if time.process_time() >= deadline - 3.0:
            break
        cap = min(deadline - 1.5, time.process_time() + 5.0)
        hb = _block_additive(bestH, B, cap, maxiter=150)
        rb = R_of(hb)
        if rb > bestRH + 1e-13:
            cap2 = min(deadline - 0.5, time.process_time() + 4.0)
            hp, rp = _polish(hb, cap2)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp, rp
                print("  B=%-4d R=%.9f (new best)" % (B, bestRH))
            elif rb > bestRH + 1e-13:
                bestH, bestRH = hb, rb
                print("  B=%-4d R=%.9f (new best, unpolished)" % (B, bestRH))

    # --- Final polish loop ---
    rng = np.random.default_rng(1234567)
    loop_end = deadline - 0.4
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.04 + 0.16 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 2.5)
            hp = _lbfgs_block(bestH, free, 120, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp

    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": alt}

