    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolong(h, N):
    n = h.size
    if N == n:
        return h.copy()
    h = np.clip(h, 0, None)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    if total <= 0:
        return np.zeros(N)
    edges = np.linspace(0.0, n, N + 1)
    mass = np.interp(edges, np.arange(n + 1), cum)
    out = np.diff(mass)
    out *= (N / n)
    out = np.clip(out, 0, None)
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Prolong to 2x grid (less aggressive to keep conditioning)
    cur = best.copy()
    for mult in (2,):
        N2 = best.size * mult
        cand = _rescale(_prolong(best, N2))
        r = R_of(cand)
        print("prolonged N=%d R=%.7f" % (cand.size, r))
        if r > bestR + 1e-12:
            best, bestR = cand.copy(), r
        cur = cand

    # Stage A: sharp log full polish
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, 800, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
        if r > bestR - 0.003:
            cur = h

    # Stage B: beta ladder with peak polishes (annealed max)
    for beta in (1e2, 1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 300, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
        if r > bestR - 0.003:
            cur = h
        for frac in (0.005, 0.01, 0.02, 0.05):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 48,
                                     maxiter=250, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp.copy(), rp
                print("  peak frac=%.3f R=%.7f" % (frac, rp))
            if rp > bestR - 0.003:
                cur = hp

    # Stage C: alternating full + multi-scale peak polishes
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("  alt full #%d R=%.7f" % (it, bestR))
        if time.process_time() >= deadline - 1.5:
            break
        # alternate small/large windows around peak
        frac = 0.01 if it % 2 else 0.03
        hp = _window_polish_peak(best, deadline, frac, 64, maxiter=250)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp.copy(), rp
            print("  alt peak #%d R=%.7f" % (it, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_near_peak(h, deadline, rcur, iters=6, maxiter=300):
    """Directly optimize h in a window around the peak of f*f in x-space
    with beta-homotopy to sharpen the peak (a genuinely different move)."""
    for k in range(iters):
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h, tol=0.995)
        # map peak back to h-window: peak of f*f at knot m ~ center of support window
        Lf = _knots(h)
        m = int(np.argmax(Lf))
        n = h.size
        # h-window centered at m/2 (since f*f peak lies near 2*center of mass)
        c = m // 2
        half = max(16, int(0.25 * n))
        lo_h = max(0, c - half)
        hi_h = min(n - 1, c + half)
        free = np.arange(lo_h, hi_h + 1)
        beta = 64.0 * (2 ** k)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r

    alt = None
    alt_r = -1.0

    # First: sharpen the existing construction with beta-homotopy on the whole
    # support, then a peak-localized homotopy. This is the biggest gain when
    # start is already well-converged: the peak needs to be much sharper.
    if time.process_time() < deadline - 8:
        h_sharp, r_sharp = _homotopy(
            best, (64, 256, 1024, 4096, 16384), 200, deadline)
        if r_sharp > best_r:
            best, best_r = h_sharp, r_sharp
        print("sharpen R=%.6f" % best_r)

    if time.process_time() < deadline - 6:
        h_sharp2, r_sharp2 = _refine_near_peak(best, deadline, best_r, iters=5, maxiter=250)
        if r_sharp2 > best_r:
            best, best_r = h_sharp2, r_sharp2
        print("peak-refine R=%.6f" % best_r)

    # Try a higher-resolution version of the start as an alternative line.
    n0 = best.size
    if n0 < 262144 and time.process_time() < deadline - 12:
        target = min(262144, n0 * 4)
        hp = _rescale(_prolong(best, target))
        cand = _lbfgs_log(hp, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
        elif alt is None or r > alt_r:
            alt, alt_r = cand, r
        print("upsampled to %d R=%.6f" % (best.size, best_r))

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        seed = best.copy()
        rng = np.random.default_rng(it * 7919)
        noise = 1.0 + 0.05 * rng.standard_normal(seed.size)
        seed = _rescale(np.clip(seed * noise, 0.0, None))

        cand, r = _homotopy(seed, (32, 128, 512, 2048, 8192), 150, deadline)
        if r > best_r:
            best, best_r = cand, r
        elif alt is None or r > alt_r:
            alt, alt_r = cand, r

        cand, r = _polish(best, deadline, best_r)
        if r > best_r:
            best, best_r = cand, r

        if it % 2 == 0:
            cand, r = _refine_near_peak(best, deadline, best_r, iters=3, maxiter=200)
            if r > best_r:
                best, best_r = cand, r

        if it % 3 == 0:
            cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
            print("  it#%d R=%.6f (start %.6f)" % (it, best_r, start_r))

    best = _rescale(best)
    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if start_r >= best_r:
            if alt is not None and alt_r > start_r:
                return {"best": start_arr, "alternative": alt}
            return {"best": start_arr, "alternative": best}
        if alt is not None and alt_r > 0 and alt_r < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

