        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    experiment_best = best.copy()
    experiment_bestR = bestR

    qs = (0.05, 0.10, 0.15, 0.25)
    modes = (0, 1, 2)

    for q in qs:
        for mode in modes:
            if time.process_time() >= deadline - 6.0:
                break
            hq = _prune_pedestal(best, q, mode)
            r_pre = R_of(hq)
            print("  q=%.2f mode=%d pre-polish R=%.9f (dR=%+.2e)" %
                  (q, mode, r_pre, r_pre - bestR))
            if r_pre > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hq.copy(), r_pre
            # 5s slice: lbfgs_log then peak window block
            slice_end = min(deadline - 3.0, time.process_time() + 5.0)
            hs = _lbfgs_log(hq, 200, slice_end, beta=0.0)
            rs = R_of(hs)
            if time.process_time() < slice_end - 0.3:
                free = _peak_window(hs, frac=0.10)
                hs2 = _lbfgs_block(hs, free, 100,
                                   min(slice_end, time.process_time() + 2.0),
