        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _peak_window(h, frac):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    # knot index m corresponds to f*f at position m; f*f support [0, 2n]
    # map to h index roughly m/2
    c = m / 2.0
    w = max(2.0, frac * n)
    lo = int(max(0, c - w))
    hi = int(min(n, c + w))
    mask = np.zeros(n, dtype=bool)
    mask[lo:hi] = True
    return mask


def _short_polish(h, deadline, iters=150):
    return _lbfgs_log(h, iters, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt, altR = None, 0.0

    def consider(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
        return r

    # Stage A: sharp polish
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(best, 250, min(deadline, time.process_time() + 0.15 * budget_seconds))
        consider(h, "A sharp")

    # Stage B: beta-ladder
    betas = (50, 200, 1e3, 1e4, 1e5, 1e6, 1e7, 1e6, 1e3)
    for beta in betas:
        if time.process_time() >= deadline - 6.0:
            break
        cap = min(deadline, time.process_time() + 4.0)
        fg = (lambda hh, bb=beta: _fun_grad_beta(hh, bb))
        h = _lbfgs_log(best, 70, cap, fg=fg)
        consider(h, "B beta=%.0e" % beta)

    # Stage C: p-norm ladder
    for p in (30, 16, 8, 5, 4):
        if time.process_time() >= deadline - 5.0:
            break
        cap = min(deadline, time.process_time() + 3.0)
        fg = (lambda hh, pp=p: _fun_grad_pnorm(hh, pp))
        h = _lbfgs_log(best, 60, cap, fg=fg)
        consider(h, "C pnorm p=%d" % p)

    # Stage D: block polish over peak window, interleaved with short sharp polish
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 4.0:
            break
        mask = _peak_window(best, frac)
        # block polish: only update masked entries via a custom fg that zeroes
        # gradient outside mask and freezes them (approximate by running full
        # lbfgs but with a masked gradient: entries outside get zero grad so
        # they stay put in u-space)
        def fg_block(hh, mk=mask):
            val, g = _fun_grad(hh)
            g = g.copy()
            g[~mk] = 0.0
            return val, g
        cap = min(deadline, time.process_time() + 3.0)
        h = _lbfgs_log(best, 100, cap, fg=fg_block)
        consider(h, "D block frac=%.2f" % frac)
        if time.process_time() < deadline - 3.0:
            h = _short_polish(best, min(deadline, time.process_time() + 2.0), iters=100)
            consider(h, "D polish")

    # Stage E: mass-preserving 2x prolongation
    if time.process_time() < deadline - 8.0:
        Nf = min(1000000, N * 2)
        hf = _prolongate(best, Nf)
        hf = _rescale(hf)
        rf = R_of(hf)
        print("E prolong %d->%d R=%.7f" % (N, Nf, rf))
        for beta in (0, 1e3, 1e4):
            if time.process_time() >= deadline - 5.0:
                break
            cap = min(deadline, time.process_time() + 2.0)
            if beta == 0:
                hf2 = _lbfgs_log(hf, 120, cap)
            else:
                fg = (lambda hh, bb=beta: _fun_grad_beta(hh, bb))
                hf2 = _lbfgs_log(hf, 120, cap, fg=fg)
            r2 = R_of(hf2)
            print("E fine beta=%.0e R=%.7f" % (beta, r2))
            if r2 > rf:
                hf, rf = hf2, r2
        if rf > bestR + 1e-15:
            best, bestR = hf, rf
            print("E wins R=%.7f (N=%d)" % (bestR, best.size))
        if rf > altR:
            alt, altR = hf, rf

    # Final loop: alternate sharp and beta passes
    toggle = 0
    while time.process_time() < deadline - 1.5:
        if toggle % 2 == 0:
            h = _lbfgs_log(best, 300, deadline)
            tag = "F sharp"
        else:
            beta = 1e3 if (toggle // 2) % 2 == 0 else 1e4
            fg = (lambda hh, bb=beta: _fun_grad_beta(hh, bb))
            h = _lbfgs_log(best, 200, deadline, fg=fg)
            tag = "F beta=%.0e" % beta
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s R=%.7f" % (tag, r))
        else:
            print("%s no gain (%.7f)" % (tag, r))
            if toggle % 2 == 1:
                break
        toggle += 1

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and altR > startR + 1e-15 and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_blur(h, w):
    """Gaussian-blurred objective: replace Lf by Gb = Lf * gaussian(sigma=w)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    if w <= 0:
        return _fun_grad(h)
    rad = int(np.ceil(3.0 * w)) + 1
    xs = np.arange(-rad, rad + 1, dtype=float)
    k = np.exp(-0.5 * (xs / w) ** 2)
    k /= k.sum()
    # zero-extend then convolve same-length
    Gb = np.convolve(Lf, k, mode='same')
    a = Gb[:-1]; b = Gb[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    if num <= 0:
        return _fun_grad(h)
    # dq for blurred knots
    dq = np.zeros_like(Gb)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    # trapezoid mass of Gb
    S = np.sum(0.5 * (Gb[:-1] + Gb[1:]))
    if S <= 0:
        return _fun_grad(h)
    M = Gb.max()
    m = int(np.argmax(Gb))
    if M <= 0:
        return _fun_grad(h)
    # gradient wrt Gb
    gGb = -dq / num
    # d/dGb of log(S): trapezoid weights 0.5 at ends, 1 interior
    wS = np.ones_like(Gb)
    wS[0] = 0.5; wS[-1] = 0.5
    gGb += wS / S
    gGb[m] += 1.0 / M
    # self-adjoint blur back
    gG = np.convolve(gGb, k, mode='same')
    grad = _backprop(gG, h) + 2.0 / s
    val = -np.log(num) + np.log(S) + np.log(M)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log_blur(h0, w, maxiter, deadline):
    return _lbfgs_log(h0, maxiter, deadline, beta=0.0,
                      fg=(lambda hh: _fun_grad_blur(hh, w)))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    rng = np.random.default_rng(20240517)

    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Blurred homotopy experiment ----
    h_cur = best.copy()
    r_cur = bestR
    print("--- Gaussian blur homotopy ---")
    for w in (64, 32, 16, 8, 4, 2):
        if time.process_time() >= deadline - 8.0:
            print("  w=%-3d skipped (time)" % w)
            break
        cap = min(deadline - 6.0, time.process_time() + 3.0)
        try:
            hw = _lbfgs_log_blur(h_cur, w, 120, cap)
        except Exception as e:
            print("  w=%-3d blur failed: %s" % (w, e))
            hw = h_cur
        hw = _rescale(hw)
        rw = R_of(hw)
        print("  w=%-3d blurred-opt R=%.12f (dR=%+.2e)" % (w, rw, rw - bestRH))
        if rw > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hw.copy(), rw
        # sharp pass at w=0
        if time.process_time() < deadline - 5.0:
            cap = min(deadline - 4.0, time.process_time() + 2.0)
            hs = _lbfgs_log(hw, 60, cap, beta=0.0)
            rs = R_of(hs)
            print("  w=%-3d sharp-pass R=%.12f (dR=%+.2e)" % (w, rs, rs - bestRH))
            if rs > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hs.copy(), rs
            h_cur = hs if rs >= rw else hw
            r_cur = max(rs, rw)
        else:
            h_cur, r_cur = hw, rw

    print("experiment best R=%.12f (base %.12f, dR=%+.2e)" %
          (experiment_bestR, bestR, experiment_bestR - bestR))

    # beta=1e3 pass
    if time.process_time() < deadline - 5.0:
        cap = min(deadline - 4.0, time.process_time() + 3.0)
        hs = _lbfgs_log(experiment_best, 80, cap, beta=1e3)
        rs = R_of(hs)
        print("  beta=1e3 R=%.12f (dR=%+.2e)" % (rs, rs - experiment_bestR))
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs

    # peak-window block pass
    if time.process_time() < deadline - 4.0:
        free = _peak_window(experiment_best, frac=0.08)
        cap = min(deadline - 3.0, time.process_time() + 3.0)
        hs = _lbfgs_block(experiment_best, free, 120, cap, beta=0.0)
        rs = R_of(hs)
        print("  peak-block R=%.12f (dR=%+.2e)" % (rs, rs - experiment_bestR))
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs

    # Adopt if improved
    if experiment_bestR > bestRH + 1e-13:
        bestH, bestRH = experiment_best.copy(), experiment_bestR
        print("  adopting experiment result R=%.12f" % bestRH)

    # ---- Spend remaining time alternating polish ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        if it % 2 == 1:
            cap = min(loop_end, time.process_time() + 5.0)
            hp, rp = _polish(bestH, cap, bestRH)
        else:
            cap = min(loop_end, time.process_time() + 3.0)
            hp, rp = _short_polish(bestH, cap, bestRH)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("  polish iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h, N_small):
    n = h.size
    if n == N_small:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(N_small)
    return hc


def _smooth(h, sigma):
    if sigma <= 0:
        return h
    n = h.size
    r = max(1, int(np.ceil(3 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    if n > 4000:
        return np.clip(fftconvolve(h, k, mode='same'), 0, None)
    return np.clip(np.convolve(h, k, mode='same'), 0, None)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _refine_at_scale(h, deadline, betas=(0.0, 200.0, 1000.0, 5000.0)):
    """Polish h at its own resolution: full + peak-window passes, with
    smoothed-max (beta) objectives to flatten the needle peak and let the
    shoulders grow. This is the main lever for improving R."""
    if time.process_time() >= deadline - 1.0:
        return h
    best = h.copy()
    bestR = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        # full-objective polish
        cand = _lbfgs_log(best, 800, deadline, beta=beta)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand, r
        # peak-window polish at several widths
        for frac in (0.08, 0.20, 0.40, 0.70):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(best, frac)
            cand = _lbfgs_block(best, free, 500, deadline, beta=beta)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt, altR = None, 0.0

    def consider(h, r, tag):
        nonlocal best, bestR, alt, altR
        print("%s R=%.7f" % (tag, r))
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))
            return True
        elif alt is None or r > altR:
            alt, altR = h, r
        return False

    # Stage 1: polish the start directly with smoothed-max escalation.
    if time.process_time() < deadline - 8.0:
        h = _refine_at_scale(best, min(t0 + budget_seconds * 0.40, deadline - 8.0))
        consider(h, R_of(h), "polish")

    # Stage 2: coarsen-refine-prolongate cycle. Working at a smaller N lets
    # full L-BFGS converge deeper per unit time; prolongation then rebuilds
    # fine structure. Repeat across several scales.
    for Nc in (2048, 4096, 8192, 16384, 32768):
        if time.process_time() >= deadline - 6.0:
            break
        if Nc >= N:
            continue
        hc = _coarsen(best, Nc)
        sub_deadline = min(time.process_time() + 6.0, deadline - 6.0)
        hc = _refine_at_scale(hc, sub_deadline, betas=(0.0, 500.0, 2000.0))
        rc = R_of(hc)
        # prolongate back up and polish
        hp = _rescale(_prolongate(hc, N))
        hp = _refine_at_scale(hp, min(time.process_time() + 5.0, deadline - 4.0),
                              betas=(0.0, 1000.0))
        consider(hp, R_of(hp), "scale%d" % Nc)

    # Stage 3: smoothing escape attempts from the current best.
    for sigma in (3.0, 10.0, 30.0, 80.0):
        if time.process_time() >= deadline - 4.0:
            break
        hs = _rescale(_smooth(best, sigma))
        if hs.sum() <= 0:
            continue
        hs = _refine_at_scale(hs, min(time.process_time() + 4.0, deadline - 3.0),
                              betas=(0.0, 300.0))
        consider(hs, R_of(hs), "smooth%.0f" % sigma)

    # Stage 4: phase-shift escapes.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 3.0:
            break
        hp = _rescale(_phase_shift(best, delta))
        if hp.sum() <= 0:
            continue
        hp = _refine_at_scale(hp, min(time.process_time() + 3.0, deadline - 2.0),
                              betas=(0.0,))
        consider(hp, R_of(hp), "phase%+.2f" % delta)

    # Stage 5: final polish loop until budget exhausted.
    stall = 0
    while time.process_time() < deadline - 1.0:
        h = _refine_at_scale(best, deadline, betas=(0.0, 2000.0))
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            stall = 0
            print("final R=%.7f" % bestR)
        else:
            stall += 1
            if stall >= 2:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if start is not None and alt is not None and altR > 0:
        startR = R_of(np.asarray(start, dtype=float))
        if bestR <= startR + 1e-12 and altR > 0:
            return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
