    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


# ---- coordinate warp machinery ----
def _warp(h, theta, x):
    N = h.size
    d = np.zeros(N)
    for m in range(7):
        d += theta[2 * m] * np.sin(2 * np.pi * m * x)
        d += theta[2 * m + 1] * np.cos(2 * np.pi * m * x)
    y = np.clip(x + d, 0.0, 1.0)
    hw = np.interp(y, x, h)
    return _rescale(hw)


def _powell_warp(h, deadline, maxfev=3000):
    N = h.size
    x = (np.arange(N) + 0.5) / N
    bound = 1.5e-4
    bnds = [(-bound, bound)] * 14

    def obj(theta):
        if time.process_time() > deadline:
            raise TimeoutError
        hw = _warp(h, theta, x)
        return -R_of(hw)

    best_theta = np.zeros(14)
    best_val = -R_of(h)
    starts = [np.zeros(14)]
    rng = np.random.RandomState(12345)
    for _ in range(4):
        starts.append(rng.uniform(-bound * 0.5, bound * 0.5, 14))
    for th0 in starts:
        if time.process_time() > deadline - 0.5:
            break
        try:
            res = minimize(obj, th0, method='Powell', bounds=bnds,
                           options={'maxfev': maxfev, 'xtol': 1e-10, 'ftol': 1e-14})
        except (TimeoutError, Exception):
            break
        if res is not None and res.fun < best_val:
            best_val = res.fun
            best_theta = res.x.copy()
    return best_theta, -best_val


def _upsample(h, N2):
    """Resample h onto N2 cells preserving shape via cumulative integral."""
    N = h.size
    if N2 == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, c[-1], N2 + 1)
    y = np.interp(xs, np.linspace(0.0, c[-1], N + 1), c)
    return np.diff(y)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Phase 1: coordinate warp via Powell ----
    warp_deadline = min(deadline - 2.0, time.process_time() + budget_seconds * 0.30)
    theta, rw = _powell_warp(bestH, warp_deadline)
    N = bestH.size
    x = (np.arange(N) + 0.5) / N
    hw = _warp(bestH, theta, x)
    rw = R_of(hw)
    print("warp R=%.7f" % rw)
    if rw > bestRH + 1e-13:
        bestH, bestRH = hw.copy(), rw

    # ---- Phase 2: p-norm ladder + sharp polish ----
    ladder = (4, 8, 16, 32, 64, 128)
    loop_end = t0 + budget_seconds * 0.86
    stage_count = 0
    roundN = 0

    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 3.0:
        roundN += 1
        for p in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 3.0:
                break
            sub_deadline = min(loop_end, time.process_time() + 8.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 80, sub_deadline, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  R%d p=%d R=%.7f" % (roundN, p, bestRH))
            stage_count += 1

            if stage_count % 2 == 0:
                if time.process_time() >= loop_end - 1.0:
                    break
                sub2 = min(loop_end, time.process_time() + 6.0)
                hs = _lbfgs_log(bestH, 200, sub2)
                rs = R_of(hs)
                if rs > bestRH + 1e-13:
                    bestH, bestRH = hs.copy(), rs
                print("  R%d sharp R=%.7f" % (roundN, bestRH))

    # ---- Phase 3: upsample refine (NEW) ----
    # Increase N and re-polish to explore finer structure the coarse grid missed.
    if time.process_time() < deadline - 5.0:
        Ncur = bestH.size
        Nnew = min(1000000, int(Ncur * 2))
        if Nnew > Ncur:
            try:
                hu = _rescale(_upsample(bestH, Nnew))
                ru = R_of(hu)
                if ru > bestRH - 1e-6:
                    sub = min(deadline - 2.0, time.process_time() + 10.0)
                    h2 = _lbfgs_log(hu, 150, sub)
                    r2 = R_of(h2)
                    if r2 > bestRH + 1e-13:
                        bestH, bestRH = h2.copy(), r2
                        print("upsample N=%d R=%.7f" % (Nnew, bestRH))
            except Exception:
                pass

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

