    return _rescale(h2)


def _prolongate(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    out = np.interp(x_new, x_old, h)
    s_old = h.sum() / n
    s_new = out.sum() / N
    if s_new > 0:
        out *= s_old / s_new
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 4.0

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best = s.copy()
            best_R = R_of(best)

    if best is None:
        best = np.ones(256)
        best_R = R_of(best)

    # Warm up: polish start at its own resolution first.
    if time.process_time() < deadline - 20:
        h = _lbfgs_log(best, 400, deadline - 15)
        r = R_of(h)
        if r > best_R:
            best_R = r; best = h
        print("polish N=%d R=%.7f" % (len(best), best_R))

    # Resolution ladder, extending upward until budget runs out.
    Ncur = len(best)
    targets = [Ncur]
    for N in (4096, 8192, 16384, 32768, 65536):
        if N > Ncur:
            targets.append(N)

    for N in targets:
        if time.process_time() > deadline - 5:
            break
        if N > len(best):
            h = _prolongate(best, N)
        else:
            h = best.copy()
        r0 = R_of(h)
        h = _lbfgs_log(h, 400, deadline - 3)
        r = R_of(h)
        print("N=%d R=%.7f (was %.7f)" % (N, r, r0))
        if r > best_R:
            best_R = r; best = h

    # Final polish at best resolution, using any remaining budget.
    if time.process_time() < deadline - 1:
        h = _lbfgs_log(best, 400, deadline - 0.5)
        r = R_of(h)
        if r > best_R:
            best_R = r; best = h

    print("best R = %.7f, N = %d" % (best_R, len(best)))

    result = {"best": best}
    if start is not None:
        s = np.asarray(start, dtype=float)
        if R_of(s) >= best_R:
            result["best"] = s
            result["alternative"] = best
    return result

