        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


# ---- Warp machinery ----
def _warp(h, d, K=32, amp=0.25):
    N = h.size
    xk = np.arange(K + 1, dtype=float) / K
    u = xk.copy()
    u[1:K] = xk[1:K] + amp * np.tanh(d)
    u[0] = 0.0
    u[K] = 1.0
    u = np.maximum.accumulate(u + 1e-6 * np.arange(K + 1))
    u = np.clip(u, 0.0, 1.0)
    u[0] = 0.0
    u[K] = 1.0
    xj = np.arange(N, dtype=float) / N
    v = np.interp(xj, xk, u)
    C = np.concatenate(([0.0], np.cumsum(h) / h.sum()))
    xi = np.arange(N + 1, dtype=float) / N
    Cnew = np.interp(v, xi, C)
    hnew = N * np.diff(np.concatenate(([0.0], Cnew)))
    return _rescale(np.clip(hnew, 0, None))


def _warp_opt(h, deadline, d0=None, K=32):
    if time.process_time() >= deadline - 0.5:
        return h, R_of(h), np.zeros(K - 1)
    if d0 is None:
        d0 = np.zeros(K - 1)
    best = [None, -1.0, d0.copy()]

    def obj(d):
        if time.process_time() > deadline - 0.3:
            raise TimeoutError
        hw = _warp(h, d, K)
        r = R_of(hw)
        if r > best[1]:
            best[0] = hw
            best[1] = r
            best[2] = d.copy()
        return -r

    try:
        minimize(obj, d0, method='Powell',
                 options={'maxfev': 3000, 'xtol': 1e-4, 'ftol': 1e-10})
    except (TimeoutError, Exception):
        pass
    if best[0] is None:
        return h, R_of(h), d0
    return best[0], best[1], best[2]


# ---- New: multiscale refinement of the flat-top peak region ----
def _multiscale_polish(bestH, bestRH, deadline):
    """Repeatedly refine a shrinking window around the peak using
    block L-BFGS on the peak neighbourhood. Focuses effort where the
    plateau is being shaped."""
    if time.process_time() >= deadline - 2.0:
        return bestH, bestRH
    h = bestH.copy()
    r = bestRH
    for tol in (0.9999, 0.999, 0.995, 0.99):
        if time.process_time() >= deadline - 1.5:
            break
        lo, hi = _peak_region(h, tol=tol)
        span = hi - lo
        if span <= 0:
            continue
        pad = max(32, int(span * 0.5))
        lo2 = max(0, lo - pad); hi2 = min(h.size - 1, hi + pad)
        free = np.arange(lo2, hi2 + 1)
        sub_end = min(deadline - 1.0, time.process_time() + 3.0)
        hp = _lbfgs_block(h, free, 200, sub_end)
        rp = R_of(hp)
        if rp > r + 1e-13:
            h, r = hp.copy(), rp
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- New: multiscale polish of the peak region first (cheap, focused) ----
    if time.process_time() < deadline - 3.0:
        sub_end = min(deadline - 2.0, time.process_time() + 10.0)
        h, r = _multiscale_polish(bestH, bestRH, sub_end)
        if r > bestRH + 1e-13:
            bestH, bestRH = h, r
        print("  multiscale R=%.7f" % bestRH)

    # ---- Existing polish: sharp, p=8, p=32 ----
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(bestH, 200, min(deadline - 1.5, time.process_time() + 6.0))
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  sharp R=%.7f" % bestRH)

    for p in (8, 32):
        if time.process_time() >= deadline - 2.0:
            break
        fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
        h = _lbfgs_log(bestH, 100, min(deadline - 1.5, time.process_time() + 5.0), fg=fg)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  p=%d R=%.7f" % (p, bestRH))

    # ---- New: alternate multiscale peak polish with sharp/pnorm until time ----
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        prev = bestRH
        sub_end = min(deadline - 1.5, time.process_time() + 4.0)
        h, r = _multiscale_polish(bestH, bestRH, sub_end)
        if r > bestRH + 1e-13:
            bestH, bestRH = h, r
        if time.process_time() < deadline - 2.0:
            h = _lbfgs_log(bestH, 120, min(deadline - 1.0, time.process_time() + 4.0))
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
        print("  alt%d R=%.7f" % (it, bestRH))
        if bestRH <= prev + 1e-14:
            break

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None) ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    w = (np.clip(Lf, 0, None) ** (p - 1)) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0, None)
    mx = Lc.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lc - mx))
    S = e.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = mx + np.log(S) / beta
    w = e / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, p=0, beta=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif p > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, p))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, p=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_pnorm(hh, p)) if p > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.08):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    w = max(64, int(frac * n))
    lo = max(0, m - w)
    hi = min(n, m + w)
    return np.arange(lo, hi)


def _revive_zeros(h, frac=0.15, scale=1e-3, win=512):
    n = h.size
    out = h.copy()
    zones = [(0, int(frac * n)), (int((1.0 - frac) * n), n)]
    cs = np.concatenate(([0.0], np.cumsum(out)))
    for lo, hi in zones:
        if hi <= lo:
            continue
        seg = out[lo:hi]
        zeros = np.flatnonzero(seg == 0.0)
        if zeros.size == 0:
            continue
        for z in zeros:
            a = max(0, lo + z - win // 2)
            b = min(n, lo + z + win // 2)
            m = (cs[b] - cs[a]) / max(1, b - a)
            if m > 0:
                out[lo + z] = scale * m
    return out


def _prune(h, q):
    n = h.size
    k = int(round(q * n))
    if k <= 0:
        return h.copy()
    if k >= n:
        k = n - 1
    idx = np.argsort(h)
    out = h.copy()
    out[idx[:k]] = 0.0
    return out


def _sharp_polish(h, deadline, iters=120):
    h = _rescale(h)
    h = _lbfgs_log(h, iters, deadline)
    if time.process_time() < deadline - 0.3:
        free = _peak_window(h, 0.08)
        h = _lbfgs_block(h, free, 100, deadline)
    return _rescale(h)


def _coarsen(h, k):
    n = h.size
    m = n // k
    if m < 1:
        return h.copy()
    hh = h[:m * k].reshape(m, k)
    return hh.mean(axis=1)


def _prolongate(h, k, N):
    hb = np.repeat(h, k)
    if hb.size < N:
        pad = N - hb.size
        hb = np.concatenate((hb, np.zeros(pad)))
    else:
        hb = hb[:N]
    return _rescale(hb / np.sqrt(k))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0

    def _record(h, tag):
        nonlocal best, bestR, alt, altR
        h = _rescale(h)
        r = R_of(h)
        zf = float(np.mean(h == 0.0))
        mm = float(h.max() / max(h.mean(), 1e-300))
        Lf = _knots(h)
        near = float(np.mean(Lf >= 0.999 * Lf.max()))
        print("%s R=%.9f N=%d zero=%.3f max/mean=%.2f near=%.4f"
              % (tag, r, h.size, zf, mm, near))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        elif r > altR:
            alt, altR = h.copy(), r
        return r

    N0 = start_best.size

    # ---- Stage A: coarse copies, halve-and-refine ----
    coarse_deadline = t0 + budget_seconds * 0.42
    coarse_cands = []  # (k, h_coarse, R)
    for k in (2, 4):
        if time.process_time() >= coarse_deadline - 0.5:
            break
        hc = _coarsen(start_best, k)
        hc = _rescale(hc)
        r_coarse = R_of(hc)
        drop = start_bestR - r_coarse
        print("halve k=%d R=%.9f drop=%.2e N=%d" % (k, r_coarse, drop, hc.size))

        # polish coarse
        slice_dl = min(coarse_deadline,
                       time.process_time() + max(3.0, (coarse_deadline - time.process_time()) / 2))
        hc = _lbfgs_log(hc, 150, min(slice_dl, time.process_time() + 3.0))
        if time.process_time() < slice_dl - 0.3:
            free = _peak_window(hc, 0.08)
            hc = _lbfgs_block(hc, free, 80, min(slice_dl, time.process_time() + 2.0))
        hc = _rescale(hc)
        r_pol = R_of(hc)
        print("coarse k=%d polish R=%.9f recov=%.2e" % (k, r_pol, r_pol - r_coarse))

        # one rank-prune cycle q=0.10
        if time.process_time() < slice_dl - 0.3:
            hp = _prune(hc, 0.10)
            hp = _revive_zeros(hp, frac=0.20, scale=1e-3)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 80, slice_dl)
            hp = _rescale(hp)
            r_pr = R_of(hp)
            if r_pr > r_pol:
                hc, r_pol = hp, r_pr
        print("coarse k=%d R=%.9f zero=%.3f" % (k, r_pol, float(np.mean(hc == 0.0))))
        coarse_cands.append((k, hc, r_pol))

    # pick best coarse
    if coarse_cands:
        coarse_cands.sort(key=lambda t: -t[2])
        k_best, hc_best, r_c_best = coarse_cands[0]
        print("best coarse k=%d R=%.9f" % (k_best, r_c_best))
    else:
        k_best, hc_best, r_c_best = 2, _coarsen(start_best, 2), -1.0

    # ---- Stage B: prolongate back and refine ----
    h_pro = _prolongate(hc_best, k_best, N0)
    r_pro = R_of(h_pro)
    print("prolongate k=%d R=%.9f" % (k_best, r_pro))
    _record(h_pro, "prol-k%d" % k_best)

    cand = best.copy()
    candR = bestR

    ladders = [("p4", 4, 0), ("p8", 8, 0), ("p16", 16, 0), ("p32", 32, 0),
               ("b1e2", 0, 1e2), ("b1e3", 0, 1e3), ("b1e5", 0, 1e5)]
    peak_fracs = [0.05, 0.15]

    while time.process_time() < deadline - 1.5:
        improved = False
        for tag, p, beta in ladders:
            if time.process_time() >= deadline - 1.5:
                break
            it = 80 if p > 0 else 60
            hc = _lbfgs_log(cand, it, deadline, p=p, beta=beta)
            hc = _rescale(hc)
            for pf in peak_fracs:
                if time.process_time() >= deadline - 1.0:
                    break
                free = _peak_window(hc, pf)
                hc = _lbfgs_block(hc, free, 60, deadline)
            hc = _rescale(hc)
            r = R_of(hc)
            if r > candR + 1e-13:
                cand, candR = hc, r
                improved = True
                _record(hc, "lad-%s" % tag)
        if not improved:
            break

    _record(cand, "final")

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    return out

import numpy as np
import time
from scipy.optimize import minimize


def _R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def _rasterize(g, a, K, N):
    # gaps from g (length K-1), heights from a (length K-1, a0=0)
    eg = np.exp(g - g.max())
    gaps = eg / eg.sum()
    b = np.concatenate(([0.0], np.cumsum(gaps)))
    heights = np.exp(np.concatenate(([0.0], a)))
    edges = np.arange(N + 1) / N
    h = np.zeros(N)
    for k in range(K):
        lo = np.maximum(edges[:-1], b[k])
        hi = np.minimum(edges[1:], b[k + 1])
        ov = np.maximum(hi - lo, 0.0)
        h += heights[k] * ov
    return h, b, heights


def _lbfgs_log(h, beta, iters, N):
    # work in log-space with smoothness penalty
    x0 = np.log(np.maximum(h, 1e-12))
    def f(x):
        hh = np.exp(x)
        r = _R_of(hh)
        pen = beta * np.sum(np.diff(x)**2)
        return -r + pen
    res = minimize(f, x0, method='L-BFGS-B',
                   options={'maxiter': iters, 'maxfun': iters * 4})
    return np.exp(res.x)


def _lbfgs_block(h, iters, N):
    x0 = np.log(np.maximum(h, 1e-12))
    def f(x):
        return -_R_of(np.exp(x))
    res = minimize(f, x0, method='L-BFGS-B',
                   options={'maxiter': iters, 'maxfun': iters * 4})
    return np.exp(res.x)


def _peak_window(h, frac):
    L = np.convolve(h, h)
    j = int(np.argmax(L))
    n = len(h)
    w = max(4, int(frac * n))
    lo = max(0, j - w)
    hi = min(n, j + w)
    mask = np.zeros(n, dtype=bool)
    mask[lo:hi] = True
    return mask


def _polish(h, mask, iters):
    x0 = np.log(np.maximum(h, 1e-12))
    def f(x):
        hh = np.exp(x)
        return -_R_of(hh)
    # only free the masked entries
    free = np.where(mask)[0]
    if len(free) == 0:
        return h
    def f_sub(z):
        x = x0.copy()
        x[free] = z
        return f(x)
    res = minimize(f_sub, x0[free], method='L-BFGS-B',
                   options={'maxiter': iters, 'maxfun': iters * 4})
    x = x0.copy()
    x[free] = res.x
    return np.exp(x)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.7

    def time_left():
        return deadline - time.process_time()

    best = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
    best_R = _R_of(best) if best is not None else -1.0

    N = 4096
    K = 6
    npar = (K - 1) + (K - 1)  # gaps + heights

    rng = np.random.default_rng(12345)

    def objective(params):
        g = params[:K - 1]
        a = params[K - 1:]
        try:
            h, b, heights = _rasterize(g, a, K, N)
            return -_R_of(h)
        except Exception:
            return 1e9

    # Stage 1: random restarts
    candidates = []
    n_starts = 30
    per_start = 0.6
    for it in range(n_starts):
        if time_left() < per_start + 2.0:
            break
        g0 = rng.uniform(np.log(1e-2), np.log(1.0), size=K - 1)
        a0 = rng.uniform(np.log(1e-2), np.log(1e2), size=K - 1)
        x0 = np.concatenate((g0, a0))
        t_start = time.process_time()
        try:
            res = minimize(objective, x0, method='Nelder-Mead',
                           options={'maxiter': 400, 'xatol': 1e-4, 'fatol': 1e-6})
            val = res.fun
            if np.isfinite(val):
                candidates.append((val, res.x))
        except Exception:
            pass
        # time guard: don't blow past per_start too badly
        if time.process_time() - t_start > per_start * 3:
            pass

    candidates.sort(key=lambda z: z[0])
    top = candidates[:3]

    # re-run NM on top 3
    refined = []
    for val, x0 in top:
        if time_left() < 2.0:
            break
        try:
            res = minimize(objective, x0, method='Nelder-Mead',
                           options={'maxiter': 800, 'xatol': 1e-5, 'fatol': 1e-8})
            if np.isfinite(res.fun):
                refined.append((res.fun, res.x))
        except Exception:
            pass
    refined.sort(key=lambda z: z[0])

    block_best = None
    block_best_R = -1.0
    if refined:
        val, x = refined[0]
        try:
            g = x[:K - 1]
            a = x[K - 1:]
            h, b, heights = _rasterize(g, a, K, N)
            r = _R_of(h)
            if r > block_best_R:
                block_best = h
                block_best_R = r
            print("block boundaries:", np.round(b, 4))
            print("block heights:", np.round(heights, 4))
        except Exception:
            pass

    # choose working array: best of start / block
    if block_best is not None and block_best_R > best_R:
        work = block_best
        work_R = block_best_R
    elif best is not None:
        # resample start to N if needed
        if best.size != N:
            work = np.interp(np.linspace(0, 1, N),
                             np.linspace(0, 1, best.size), best)
        else:
            work = best.copy()
        work_R = _R_of(work)
    else:
        work = np.ones(N)
        work_R = _R_of(work)

    # Stage 2: free continuation on raster
    try:
        for beta in [0.0, 1e2, 1e3]:
            if time_left() < 1.0:
                break
            cand = _lbfgs_log(work, beta, 100, N)
            r = _R_of(cand)
            if r > work_R:
                work, work_R = cand, r
        if time_left() > 1.0:
            mask = _peak_window(work, 0.10)
            cand = _polish(work, mask, 100)
            r = _R_of(cand)
            if r > work_R:
                work, work_R = cand, r
    except Exception:
        pass

    # Stage 3: staircase prolongation
    cur = work
    cur_R = work_R
    cur_N = N
    for target_N in [8192, 16384]:
        if time_left() < 1.5:
            break
        try:
            up = np.repeat(cur, 2) / np.sqrt(2.0)
            r = _R_of(up)
            if r >= cur_R - 1e-9:
                cur = up
                cur_R = r
                cur_N = target_N
            # beta ladder
            for beta in [0.0, 1e2, 1e3]:
                if time_left() < 1.0:
                    break
                cand = _lbfgs_log(cur, beta, 100, cur_N)
                r = _R_of(cand)
                if r > cur_R:
                    cur, cur_R = cand, r
            if time_left() > 1.0:
                mask = _peak_window(cur, 0.10)
                cand = _polish(cur, mask, 100)
                r = _R_of(cand)
                if r > cur_R:
                    cur, cur_R = cand, r
        except Exception:
            pass

    # final selection
    result = cur
    if best is not None and best_R >= cur_R:
        result = best

    result = np.asarray(result, dtype=float)
    result = np.where(np.isfinite(result) & (result >= 0), result, 0.0)
    if result.sum() <= 0:
        result = np.ones(50)
    if result.size > 1000000:
        result = result[:1000000]

    # diagnostics
    try:
        L = np.convolve(result, result)
        j = int(np.argmax(L))
        loc = j / max(1, len(L) - 1)
        near = np.mean(L > 0.99 * L.max())
        print("final R:", _R_of(result), "N:", result.size,
              "argmax(f*f) at", round(loc, 3),
              "frac near max:", round(float(near), 3))
    except Exception:
        pass

    if best is not None and _R_of(result) < best_R:
        return {"best": best, "alternative": result}
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    m = L.max()
    if m <= 0:
        return -1.0
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    return num / (s * s * m)


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Always keep the best-of-start available
    start_h = None
    start_R = -1.0
    if start is not None:
        start_h = np.asarray(start, dtype=float).copy()
        start_R = R_of(start_h)

    # Ladder: refine up to a moderately large N, but don't waste time going
    # to 64000 (diminishing returns, and 512 already scored best).
    ladder = [128, 256, 512, 1024, 2048]

    for N in ladder:
        if time.process_time() > deadline - 8.0:
            break
        if h.size != N:
            h = _prolongate(h, N)
        h = _rescale(h)
        # direct
        h = _lbfgs_log(h, 600, deadline)
        R = R_of(h)
        if R > best_R:
            best_R = R
            best_h = h.copy()
        # homotopy on softmax
        for beta in (4, 8, 16, 32, 64, 128):
            if time.process_time() > deadline - 4.0:
                break
            h = _lbfgs_log(h, 300, deadline, beta=beta)
            R = R_of(h)
            if R > best_R:
                best_R = R
                best_h = h.copy()
        print("level N=%d R=%.6f best=%.6f" % (N, R, best_R))

    # Final phase: keep polishing the best at its N, alternating full and block
    h = best_h.copy()
    N = h.size
    while time.process_time() < deadline - 1.0:
        h2 = _lbfgs_log(h, 2000, deadline)
        R2 = R_of(h2)
        if R2 > best_R:
            best_R = R2
            h = h2
            best_h = h2.copy()
        else:
            h = h2
        # block polish around the peak
        Lf = _knots(h)
        m = int(np.argmax(Lf))
        half = max(16, int(0.15 * N))
        lo = max(0, m - half)
        hi = min(N, m + half)
        if hi > lo:
            h2 = _lbfgs_block(h, np.arange(lo, hi), 400, deadline)
            R2 = R_of(h2)
            if R2 > best_R:
                best_R = R2
                h = h2
                best_h = h2.copy()
            else:
                h = h2
        if time.process_time() > deadline - 1.0:
            break

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start_h is not None and start_R >= best_R:
        return {"best": start_h, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_softmax_p(h, p):
    """L_p norm of knot profile instead of L_inf, for p large (smooth max)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0.0, None)
    # soft Lp: (sum L^p)^(1/p)
    m = Lp.max()
    if m <= 0:
        return _fun_grad(h)
    z = Lp / m
    zp = z ** p
    S = zp.sum()
    sm = m * S ** (1.0 / p)
    # d sm / d L_j = (z_j^(p-1)) * m^(1-p) * sm^(1-p) ... compute directly
    # sm = (sum L^p)^(1/p). d sm/dL_j = L_j^(p-1) * sm^(1-p)
    dsm = (Lp ** (p - 1.0)) * (sm ** (1.0 - p))
    gLf = -dq / num + dsm / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _refine(h, deadline):
    """Refine on a finer grid: linear-interpolate h onto 2x grid."""
    n = h.size
    if n >= 400000:
        return h
    n2 = min(2 * n, 1000000)
    xi = np.linspace(0, n - 1, n2)
    h2 = np.interp(xi, np.arange(n), h)
    h2 = np.clip(h2, 0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Experiment A: soft-Lp (p large) smoothing of the max ----
    for p in (4.0, 8.0, 16.0, 32.0):
        if time.process_time() >= deadline - 6.0:
            break
        cap = min(deadline - 4.0, time.process_time() + 2.0)
        fg = (lambda hh, pp=p: _fun_grad_softmax_p(hh, pp))
        hs = _lbfgs_log(best, 80, cap, fg=fg)
        rs = R_of(hs)
        # polish with exact R
        if time.process_time() < deadline - 2.5:
            cap2 = min(deadline - 1.5, time.process_time() + 2.0)
            hp = _lbfgs_log(hs, 120, cap2, beta=0.0)
            rp = R_of(hp)
            if rp > rs:
                hs, rs = hp, rp
        print("  A p=%.1f R=%.12f dR=%+.2e" % (p, rs, rs - experiment_bestR))
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs

    # ---- Experiment B: grid refinement (2x) then polish ----
    if time.process_time() < deadline - 8.0 and best.size < 400000:
        hr = _refine(experiment_best, deadline)
        rr = R_of(hr)
        cap = min(deadline - 3.0, time.process_time() + 4.0)
        hp = _lbfgs_log(hr, 150, cap, beta=0.0)
        rp = R_of(hp)
        if rp > rr:
            hr, rr = hp, rp
        print("  B refine N=%d R=%.12f dR=%+.2e" % (hr.size, rr, rr - experiment_bestR))
        if rr > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hr.copy(), rr

    # ---- Experiment C: exact-R polish + peak-window block passes ----
    loop_end = deadline - 0.8
    bestH = experiment_best.copy()
    bestRH = experiment_bestR
    it = 0
    rng = np.random.default_rng(20240517)
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            continue
        improved = False
        for beta in (1e3, 1e4):
            if time.process_time() >= loop_end - 1.0:
                break
            cap = min(loop_end, time.process_time() + 3.0)
            hb = _lbfgs_log(bestH, 120, cap, beta=beta)
            rb = R_of(hb)
            if rb > bestRH + 1e-13:
                bestH, bestRH = hb.copy(), rb
                improved = True
                break
        if improved:
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.06 + 0.06 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp

    print("final R=%.9f" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_R = -1.0
    alt = None
    alt_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            r = R_of(s)
            if r > 0:
                best = s.copy()
                best_R = r

    if best is None:
        n = 256
        x = np.linspace(0, 1, n)
        best = np.cos(np.pi * (x - 0.5))**2 + 1e-3
        best = _lbfgs_log(best, 250, deadline)
        best_R = R_of(best)

    print(f"seed R={best_R:.6f} N={len(best)}")

    cur = best.copy()
    cur_R = best_R

    def try_polish(h, R, label):
        nonlocal cur, cur_R
        h2 = _lbfgs_log(h, 400, deadline, beta=0.0)
        r2 = R_of(h2)
        if r2 > R + 1e-11:
            h, R = h2, r2
            print(f"  {label} logopt R={R:.6f} N={len(h)}")
        for beta in [32.0, 128.0, 512.0, 2048.0, 8192.0]:
            if time.process_time() > deadline - 1.0:
                break
            h3 = _lbfgs_log(h, 200, deadline, beta=beta)
            r3 = R_of(h3)
            if r3 > R + 1e-11:
                h, R = h3, r3
                print(f"  {label} beta={beta} R={R:.6f}")
        return h, R

    # Ladder: prolong + polish at increasing N
    for N in [8192, 16384, 32768, 65536]:
        if time.process_time() > deadline - 4.0:
            break
        cur = _prolong(cur, N)
        cur_R = R_of(cur)
        cur, cur_R = try_polish(cur, cur_R, f"N={N}")
        if cur_R > best_R:
            best = cur.copy()
            best_R = cur_R

    # Alternation: full logopt, peak-window polishes, prolongation
    while time.process_time() < deadline - 1.0:
        improved = False

        h2, r2 = try_polish(best, best_R, "full")
        if r2 > best_R + 1e-11:
            best, best_R = h2, r2
            improved = True

        for frac in [0.30, 0.15, 0.07]:
            if time.process_time() > deadline - 1.0:
                break
            win = _peak_window(best, frac=frac)
            if win.size < 4:
                continue
            h = best.copy()
            active = win
            x0 = h[active].copy()
            def f(x, h=h, active=active):
                hh = h.copy()
                hh[active] = np.clip(x, 0, None)
                val, g = _fun_grad(hh)
                return val, g[active]
            cb = _make_cb(deadline - 0.3)
            try:
                res = minimize(f, x0, jac=True, method='L-BFGS-B',
                               bounds=[(0.0, None)] * active.size,
                               callback=cb,
                               options={'maxiter': 300, 'maxfun': 600,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                h2 = h.copy()
                h2[active] = np.clip(res.x, 0, None)
                h2 = _rescale(h2)
                r3 = R_of(h2)
                if r3 > best_R + 1e-11:
                    best, best_R = h2, r3
                    improved = True
                    print(f"window frac={frac} R={best_R:.6f}")
            except (TimeoutError, Exception):
                pass

        if not improved:
            N = min(2 * len(best), 131072)
            if N <= len(best):
                break
            best = _prolong(best, N)
            best = _lbfgs_log(best, 200, deadline)
            best_R = R_of(best)
            print(f"prolong N={N} R={best_R:.6f}")

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={R_of(best):.6f} N={len(best)}")
    return best

