    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


# ---------- Edge-singular model family ----------

def _edge_profile(M, p, cap, mass):
    """Rasterized x^-p profile: model_i = min(cap, A*((i+1)^(1-p)-i^(1-p))/(1-p)),
    A chosen so sum(model)=mass."""
    i = np.arange(M, dtype=float)
    if abs(p - 1.0) < 1e-9:
        base = 1.0 / (i + 1.0)
    else:
        base = ((i + 1.0) ** (1.0 - p) - i ** (1.0 - p)) / (1.0 - p)
    # base is the analytic cell-average of x^-p on [i, i+1]
    # We want A*base clipped at cap, with sum = mass.
    # Solve for A by bisection (sum is monotone increasing in A).
    lo, hi = 0.0, 1.0
    # find hi such that sum >= mass
    for _ in range(80):
        s = np.sum(np.minimum(cap, hi * base))
        if s >= mass:
            break
        hi *= 2.0
        if hi > 1e30:
            break
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        s = np.sum(np.minimum(cap, mid * base))
        if s < mass:
            lo = mid
        else:
            hi = mid
    A = 0.5 * (lo + hi)
    model = np.minimum(cap, A * base)
    return model


def _build_candidate(h0, M, p, cap, blend=16):
    """Replace h0[:M] with a mass-matched edge profile, blended at the seam."""
    M = min(M, h0.size)
    if M <= 0:
        return h0.copy()
    mass = h0[:M].sum()
    if mass <= 0:
        return h0.copy()
    model = _edge_profile(M, p, cap, mass)
    h = h0.copy()
    h[:M] = model
    # Blend last `blend` cells of the model region toward h0 to avoid seam.
    b = min(blend, M)
    if b > 0:
        w = np.linspace(0.0, 1.0, b)
        h[M - b:M] = (1.0 - w) * model[M - b:M] + w * h0[M - b:M]
    return _rescale(h)


def _diag(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    frac1 = float(np.mean(Lf >= 0.99 * mx))
    frac01 = float(np.mean(Lf >= 0.999 * mx))
    return mx, m, frac1, frac01


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    # Detect spike side: end with largest single cell height.
    n = best.size
    left_max = best[:max(1, n // 20)].max()
    right_max = best[n - max(1, n // 20):].max()
    reversed_ = right_max > left_max
    if reversed_:
        work = best[::-1].copy()
        print("  spike on right; operating on reversed array")
    else:
        work = best.copy()
        print("  spike on left")

    edge_max = work[:max(1, n // 20)].max()
    workR = R_of(work)

    bestH = work.copy()
    bestRH = workR
    experiment_best = work.copy()
    experiment_bestR = workR

    # ---- Sweep 1: M x p x cap ----
    M_list = [128, 256, 512]
    p_list = [0.3, 0.4, 0.5, 0.6, 0.7]
    cap_list = [0.5, 1.0, 2.0]

    def evaluate(M, p, cap):
        nonlocal experiment_best, experiment_bestR
        if time.process_time() >= deadline - 8.0:
            return
        cand = _build_candidate(work, M, p, cap * edge_max)
        r = R_of(cand)
        mx, m, f1, f01 = _diag(cand)
        sr = cand[:M].sum() / max(work[:M].sum(), 1e-300)
        gain = r - workR
        if r > experiment_bestR + 1e-13:
            experiment_best = cand.copy()
            experiment_bestR = r
            tag = "NEW"
        else:
            tag = "   "
        print("  %s M=%-4d p=%.2f cap=%.1f R=%.9f dR=%+.2e sumratio=%.4f argmax=%d f1%%=%.4f f0.1%%=%.4f" %
              (tag, M, p, cap, r, gain, sr, m, f1, f01))

    for M in M_list:
        for p in p_list:
            for cap in cap_list:
                if time.process_time() >= deadline - 8.0:
                    break
                evaluate(M, p, cap)

    print("sweep1 best R=%.9f (base %.9f, dR=%+.2e)" %
          (experiment_bestR, workR, experiment_bestR - workR))

    # ---- Polish the best candidate ----
    if experiment_bestR > workR + 1e-13:
        if time.process_time() < deadline - 6.0:
            cap_t = min(deadline - 4.0, time.process_time() + 6.0)
            hp, rp = _short_polish(experiment_best, cap_t, experiment_bestR)
            if rp > experiment_bestR:
                experiment_best, experiment_bestR = hp, rp
                print("  after short_polish R=%.9f" % experiment_bestR)
        if time.process_time() < deadline - 4.0:
            free = _peak_window(experiment_best, frac=0.08)
            cap_t = min(deadline - 2.0, time.process_time() + 6.0)
            hp = _lbfgs_block(experiment_best, free, 200, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > experiment_bestR:
                experiment_best, experiment_bestR = hp, rp
                print("  after lbfgs_block R=%.9f" % experiment_bestR)

    # ---- Sweep 2: refine around best p and M ----
    if time.process_time() < deadline - 8.0:
        # find best (M,p,cap) so far by re-evaluating a small grid
        best_cfg = None
        best_cfgR = experiment_bestR
        # We don't track cfg; just do a focused grid around likely winners.
        p_fine = [0.35, 0.45, 0.55, 0.65]
        M_fine = [192, 384, 768]
        cap_fine = [0.75, 1.5]
        for M in M_fine:
            for p in p_fine:
                for cap in cap_fine:
                    if time.process_time() >= deadline - 6.0:
                        break
                    evaluate(M, p, cap)
        print("sweep2 best R=%.9f" % experiment_bestR)

    # ---- Adopt and polish ----
    if experiment_bestR > bestRH + 1e-13:
        bestH, bestRH = experiment_best.copy(), experiment_bestR
        print("  adopting experiment, polishing...")
        if time.process_time() < deadline - 1.0:
            hp, rp = _polish(bestH, deadline - 0.5, bestRH)
            if rp > bestRH:
                bestH, bestRH = hp, rp
                print("  full polish R=%.9f" % bestRH)

    # ---- Remaining time: block-additive passes ----
    for B in (256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # final polish loop
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    # Reverse back if needed
    if reversed_:
        bestH = bestH[::-1].copy()
        experiment_best = experiment_best[::-1].copy()

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None) ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    w = (np.clip(Lf, 0, None) ** (p - 1)) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0, None)
    mx = Lc.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lc - mx))
    S = e.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = mx + np.log(S) / beta
    w = e / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, p=0, beta=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif p > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, p))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, p=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_pnorm(hh, p)) if p > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.08):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    w = max(64, int(frac * n))
    lo = max(0, m - w)
    hi = min(n, m + w)
    return np.arange(lo, hi)


def _revive_zeros(h, frac=0.15, scale=1e-3, win=512):
    n = h.size
    out = h.copy()
    zones = [(0, int(frac * n)), (int((1.0 - frac) * n), n)]
    cs = np.concatenate(([0.0], np.cumsum(out)))
    for lo, hi in zones:
        if hi <= lo:
            continue
        seg = out[lo:hi]
        zeros = np.flatnonzero(seg == 0.0)
        if zeros.size == 0:
            continue
        for z in zeros:
            a = max(0, lo + z - win // 2)
            b = min(n, lo + z + win // 2)
            m = (cs[b] - cs[a]) / max(1, b - a)
            if m > 0:
                out[lo + z] = scale * m
    return out


def _prune(h, q):
    n = h.size
    k = int(round(q * n))
    if k <= 0:
        return h.copy()
    if k >= n:
        k = n - 1
    idx = np.argsort(h)
    out = h.copy()
    out[idx[:k]] = 0.0
    return out


def _coarsen(h, k):
    n = h.size
    m = n // k
    if m < 1:
        return h.copy()
    hh = h[:m * k].reshape(m, k)
    return hh.mean(axis=1)


def _prolongate(h, k, N):
    hb = np.repeat(h, k)
    if hb.size < N:
        pad = N - hb.size
        hb = np.concatenate((hb, np.zeros(pad)))
    else:
        hb = hb[:N]
    return _rescale(hb / np.sqrt(k))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0

    def _record(h, tag):
        nonlocal best, bestR, alt, altR
        h = _rescale(h)
        r = R_of(h)
        zf = float(np.mean(h == 0.0))
        mm = float(h.max() / max(h.mean(), 1e-300))
        Lf = _knots(h)
        near = float(np.mean(Lf >= 0.999 * Lf.max()))
        print("%s R=%.9f N=%d zero=%.3f max/mean=%.2f near=%.4f"
              % (tag, r, h.size, zf, mm, near))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        elif r > altR:
            alt, altR = h.copy(), r
        return r

    N0 = start_best.size

    # ---- Stage A: coarsest level k=8 ----
    h8 = _rescale(_coarsen(start_best, 8))
    print("coarsen k=8 R=%.9f N=%d" % (R_of(h8), h8.size))
    h8 = _lbfgs_log(h8, 300, deadline)
    # rank-prune q=0.15 then revive then polish
    if time.process_time() < deadline - 1.0:
        hp = _prune(h8, 0.15)
        hp = _revive_zeros(hp, frac=0.20, scale=1e-3)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 100, deadline)
        hp = _rescale(hp)
        if R_of(hp) > R_of(h8):
            h8 = hp
    # beta ladder
    for beta in (1e2, 1e4):
        if time.process_time() >= deadline - 1.0:
            break
        hc = _lbfgs_log(h8, 80, deadline, beta=beta)
        if R_of(hc) > R_of(h8):
            h8 = hc
    if time.process_time() < deadline - 1.0:
        free = _peak_window(h8, 0.10)
        hc = _lbfgs_block(h8, free, 100, deadline)
        if R_of(hc) > R_of(h8):
            h8 = hc
    h8 = _rescale(h8)
    r8 = R_of(h8)
    print("L8 R=%.9f zero=%.3f" % (r8, float(np.mean(h8 == 0.0))))
    _record(h8, "L8")

    # ---- Stage B: prolongate to N=42496 ----
    N4 = 4 * h8.size
    h4 = _prolongate(h8, 2, N4)
    print("prol->L4 R=%.9f N=%d" % (R_of(h4), h4.size))
    _record(h4, "prol-L4")
    h4 = _lbfgs_log(h4, 200, deadline)
    if time.process_time() < deadline - 1.0:
        hc = _lbfgs_log(h4, 80, deadline, beta=1e4)
        if R_of(hc) > R_of(h4):
            h4 = hc
    if time.process_time() < deadline - 1.0:
        free = _peak_window(h4, 0.08)
        hc = _lbfgs_block(h4, free, 80, deadline)
        if R_of(hc) > R_of(h4):
            h4 = hc
    if time.process_time() < deadline - 1.0:
        hp = _prune(h4, 0.10)
        hp = _revive_zeros(hp, frac=0.20, scale=1e-3)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 80, deadline)
        hp = _rescale(hp)
        if R_of(hp) > R_of(h4):
            h4 = hp
    h4 = _rescale(h4)
    print("L4 R=%.9f zero=%.3f" % (R_of(h4), float(np.mean(h4 == 0.0))))
    _record(h4, "L4")

    # ---- Stage C: prolongate to N=84992 ----
    N2 = 2 * h4.size
    h2 = _prolongate(h4, 2, N2)
    print("prol->L2 R=%.9f N=%d" % (R_of(h2), h2.size))
    _record(h2, "prol-L2")
    h2 = _lbfgs_log(h2, 200, deadline)
    if time.process_time() < deadline - 1.0:
        hc = _lbfgs_log(h2, 80, deadline, beta=1e4)
        if R_of(hc) > R_of(h2):
            h2 = hc
    if time.process_time() < deadline - 1.0:
        free = _peak_window(h2, 0.08)
        hc = _lbfgs_block(h2, free, 80, deadline)
        if R_of(hc) > R_of(h2):
            h2 = hc
    if time.process_time() < deadline - 1.0:
        hp = _prune(h2, 0.10)
        hp = _revive_zeros(hp, frac=0.20, scale=1e-3)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 80, deadline)
        hp = _rescale(hp)
        if R_of(hp) > R_of(h2):
            h2 = hp
    h2 = _rescale(h2)
    print("L2 R=%.9f zero=%.3f" % (R_of(h2), float(np.mean(h2 == 0.0))))
    _record(h2, "L2")

    # ---- Stage D: prolongate to N=169984 and alternate ----
    h1 = _prolongate(h2, 2, N0)
    print("prol->L1 R=%.9f N=%d" % (R_of(h1), h1.size))
    _record(h1, "prol-L1")

    cand = h1.copy()
    candR = R_of(cand)
    if candR < bestR:
        cand, candR = best.copy(), bestR

    while time.process_time() < deadline - 0.7:
        improved = False
        # beta=0 log
        if time.process_time() < deadline - 0.7:
            hc = _lbfgs_log(cand, 150, deadline)
            r = R_of(hc)
            if r > candR + 1e-13:
                cand, candR = hc, r
                improved = True
                _record(hc, "d-b0")
        # beta=1e5 log
        if time.process_time() < deadline - 0.7:
            hc = _lbfgs_log(cand, 100, deadline, beta=1e5)
            r = R_of(hc)
            if r > candR + 1e-13:
                cand, candR = hc, r
                improved = True
                _record(hc, "d-b1e5")
        # peak blocks
        for pf in (0.05, 0.15):
            if time.process_time() >= deadline - 0.7:
                break
            free = _peak_window(cand, pf)
            hc = _lbfgs_block(cand, free, 80, deadline)
            r = R_of(hc)
            if r > candR + 1e-13:
                cand, candR = hc, r
                improved = True
                _record(hc, "d-pk%.2f" % pf)
        if not improved:
            break

    _record(cand, "final")

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


# ---------- Edge-singular model family ----------

def _edge_profile(M, p, cap, mass):
    i = np.arange(M, dtype=float)
    if abs(p - 1.0) < 1e-9:
        base = 1.0 / (i + 1.0)
    else:
        base = ((i + 1.0) ** (1.0 - p) - i ** (1.0 - p)) / (1.0 - p)
    lo, hi = 0.0, 1.0
    for _ in range(80):
        s = np.sum(np.minimum(cap, hi * base))
        if s >= mass:
            break
        hi *= 2.0
        if hi > 1e30:
            break
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        s = np.sum(np.minimum(cap, mid * base))
        if s < mass:
            lo = mid
        else:
            hi = mid
    A = 0.5 * (lo + hi)
    model = np.minimum(cap, A * base)
    return model


def _build_candidate(h0, M, p, cap, blend=16):
    M = min(M, h0.size)
    if M <= 0:
        return h0.copy()
    mass = h0[:M].sum()
    if mass <= 0:
        return h0.copy()
    model = _edge_profile(M, p, cap, mass)
    h = h0.copy()
    h[:M] = model
    b = min(blend, M)
    if b > 0:
        w = np.linspace(0.0, 1.0, b)
        h[M - b:M] = (1.0 - w) * model[M - b:M] + w * h0[M - b:M]
    return _rescale(h)


def _diag(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    frac1 = float(np.mean(Lf >= 0.99 * mx))
    frac01 = float(np.mean(Lf >= 0.999 * mx))
    return mx, m, frac1, frac01


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n = best.size
    left_max = best[:max(1, n // 20)].max()
    right_max = best[n - max(1, n // 20):].max()
    reversed_ = right_max > left_max
    if reversed_:
        work = best[::-1].copy()
        print("  spike on right; operating on reversed array")
    else:
        work = best.copy()
        print("  spike on left")

    edge_max = work[:max(1, n // 20)].max()
    workR = R_of(work)

    bestH = work.copy()
    bestRH = workR
    experiment_best = work.copy()
    experiment_bestR = workR

    M_list = [128, 256, 512]
    p_list = [0.3, 0.4, 0.5, 0.6, 0.7]
    cap_list = [0.5, 1.0, 2.0]

    def evaluate(M, p, cap):
        nonlocal experiment_best, experiment_bestR
        if time.process_time() >= deadline - 8.0:
            return
        cand = _build_candidate(work, M, p, cap * edge_max)
        r = R_of(cand)
        mx, m, f1, f01 = _diag(cand)
        sr = cand[:M].sum() / max(work[:M].sum(), 1e-300)
        gain = r - workR
        if r > experiment_bestR + 1e-13:
            experiment_best = cand.copy()
            experiment_bestR = r
            tag = "NEW"
        else:
            tag = "   "
        print("  %s M=%-4d p=%.2f cap=%.1f R=%.9f dR=%+.2e sumratio=%.4f argmax=%d f1%%=%.4f f0.1%%=%.4f" %
              (tag, M, p, cap, r, gain, sr, m, f1, f01))

    for M in M_list:
        for p in p_list:
            for cap in cap_list:
                if time.process_time() >= deadline - 8.0:
                    break
                evaluate(M, p, cap)

    print("sweep1 best R=%.9f (base %.9f, dR=%+.2e)" %
          (experiment_bestR, workR, experiment_bestR - workR))

    if experiment_bestR > workR + 1e-13:
        if time.process_time() < deadline - 6.0:
            cap_t = min(deadline - 4.0, time.process_time() + 6.0)
            hp, rp = _short_polish(experiment_best, cap_t, experiment_bestR)
            if rp > experiment_bestR:
                experiment_best, experiment_bestR = hp, rp
                print("  after short_polish R=%.9f" % experiment_bestR)
        if time.process_time() < deadline - 4.0:
            free = _peak_window(experiment_best, frac=0.08)
            cap_t = min(deadline - 2.0, time.process_time() + 6.0)
            hp = _lbfgs_block(experiment_best, free, 200, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > experiment_bestR:
                experiment_best, experiment_bestR = hp, rp
                print("  after lbfgs_block R=%.9f" % experiment_bestR)

    if time.process_time() < deadline - 8.0:
        p_fine = [0.35, 0.45, 0.55, 0.65]
        M_fine = [192, 384, 768]
        cap_fine = [0.75, 1.5]
        for M in M_fine:
            for p in p_fine:
                for cap in cap_fine:
                    if time.process_time() >= deadline - 6.0:
                        break
                    evaluate(M, p, cap)
        print("sweep2 best R=%.9f" % experiment_bestR)

    if experiment_bestR > bestRH + 1e-13:
        bestH, bestRH = experiment_best.copy(), experiment_bestR
        print("  adopting experiment, polishing...")
        if time.process_time() < deadline - 1.0:
            hp, rp = _polish(bestH, deadline - 0.5, bestRH)
            if rp > bestRH:
                bestH, bestRH = hp, rp
                print("  full polish R=%.9f" % bestRH)

    for B in (256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    if reversed_:
        bestH = bestH[::-1].copy()
        experiment_best = experiment_best[::-1].copy()

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    Lp = np.clip(Lf / mx, 0.0, None)
    sp = np.sum(Lp ** p)
    if sp <= 0:
        return _fun_grad(h)
    sm = mx * sp ** (1.0 / p)
    # d sm / d Lf = mx * (1/p) * sp^(1/p - 1) * p * Lp^(p-1) / mx
    #             = sp^(1/p - 1) * Lp^(p-1)
    dsm = sp ** (1.0 / p - 1.0) * Lp ** (p - 1.0)
    gLf = -dq / num + dsm / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, pnorm=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if pnorm > 0:
            fg = (lambda hh: _fun_grad_pnorm(hh, pnorm))
        elif beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _gauss_smooth(h, sigma=1.5):
    r = 3
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    hp = np.concatenate((np.full(r, h[0]), h, np.full(r, h[-1])))
    return np.convolve(hp, k, mode='valid')


def _rank_prune(h, q, deadline):
    """Zero the q smallest positive cells, restore mass into longest zero run."""
    h = np.clip(h, 0, None).copy()
    pos = np.flatnonzero(h > 0)
    if pos.size < 10:
        return h
    k = max(1, int(q * pos.size))
    order = pos[np.argsort(h[pos])]
    kill = order[:k]
    mass = h[kill].sum()
    h[kill] = 0.0
    # find longest zero run
    zero = (h <= 0).astype(int)
    best_len = 0
    best_start = 0
    cur = 0
    for i in range(h.size):
        if zero[i]:
            cur += 1
            if cur > best_len:
                best_len = cur
                best_start = i - cur + 1
        else:
            cur = 0
    if best_len <= 0:
        return _rescale(h)
    a = best_start
    b = best_start + best_len
    local = h[max(0, a - 5):b + 5]
    lm = local[local > 0].mean() if np.any(local > 0) else 1.0
    fill = 1e-3 * lm
    h[a:b] += fill
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    deadline_c = t0 + budget_seconds * 0.55

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    # ---- Step 0: staircase diagnostic ----
    n = best.size
    if n % 2 == 0:
        h_c = 0.5 * (best[0::2] + best[1::2])
        h_c = _rescale(h_c)
        recon = np.repeat(h_c, 2)
        err = np.max(np.abs(best - recon)) / max(best.max(), 1e-300)
        Rcoarse = R_of(h_c)
        Rfine = R_of(best)
        print("staircase err=%.2e Rcoarse=%.12f Rfine=%.12f" % (err, Rcoarse, Rfine))
    else:
        h_c = best.copy()
        Rcoarse = R_of(h_c)
        print("odd N; skipping staircase diagnostic")

    # ---- Step 1: coarse search ----
    hc_best = h_c.copy()
    hc_bestR = R_of(hc_best)
    print("coarse start R=%.9f" % hc_bestR)

    def coarse_try(name, cand):
        nonlocal hc_best, hc_bestR
        r = R_of(cand)
        dR = r - hc_bestR
        if r > hc_bestR + 1e-13:
            hc_best = cand.copy()
            hc_bestR = r
            tag = "NEW"
        else:
            tag = "   "
        print("coarse %s %s R=%.9f dR=%+.2e" % (tag, name, r, dR))

    def coarse_budget():
        return min(deadline_c, time.process_time() + 6.0)

    if time.process_time() < deadline_c - 1.0:
        coarse_try("lbfgs0", _lbfgs_log(hc_best, 400, coarse_budget(), beta=0.0))
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline_c - 1.0:
            break
        coarse_try("beta%.0e" % beta,
                   _lbfgs_log(hc_best, 150, coarse_budget(), beta=beta))
    for p in (4, 8, 16):
        if time.process_time() >= deadline_c - 1.0:
            break
        coarse_try("pnorm%d" % p,
                   _lbfgs_log(hc_best, 100, coarse_budget(), pnorm=p))
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline_c - 1.0:
            break
        free = _peak_window(hc_best, frac=frac)
        coarse_try("peak%.2f" % frac,
                   _lbfgs_block(hc_best, free, 150, coarse_budget(), beta=0.0))
    if time.process_time() < deadline_c - 1.0:
        hp = _rank_prune(hc_best, 0.10, deadline_c)
        hp = _lbfgs_log(hp, 100, coarse_budget(), beta=0.0)
        coarse_try("rankprune", hp)

    print("coarse best R=%.9f (dR from start %+.2e)" % (hc_bestR, hc_bestR - start_bestR))

    # ---- Step 2: prolongate ----
    A = _rescale(np.repeat(hc_best, 2))
    B = _rescale(np.repeat(_gauss_smooth(hc_best, sigma=1.5), 2))
    RA = R_of(A)
    RB = R_of(B)
    print("prolongate R(A)=%.9f R(B)=%.9f" % (RA, RB))

    # incumbent fine
    if RA >= RB:
        fine_best, fine_bestR = A.copy(), RA
        other = B.copy()
    else:
        fine_best, fine_bestR = B.copy(), RB
        other = A.copy()

    # also consider the original start
    if start_bestR > fine_bestR:
        fine_best, fine_bestR = start_best.copy(), start_bestR

    # ---- Step 3: alternate fine polish ----
    loop_end = deadline - 0.7
    used_other = False
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap_t = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(fine_best, 300, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > fine_bestR + 1e-13:
            fine_best, fine_bestR = hs.copy(), rs
            improved = True
            print("  fine it=%d beta0 R=%.9f" % (it, fine_bestR))
        if time.process_time() < loop_end - 1.0:
            cap_t = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(fine_best, 120, cap_t, beta=1e5)
            rs = R_of(hs)
            if rs > fine_bestR + 1e-13:
                fine_best, fine_bestR = hs.copy(), rs
                improved = True
                print("  fine it=%d beta1e5 R=%.9f" % (it, fine_bestR))
        if time.process_time() < loop_end - 1.0:
            free = _peak_window(fine_best, frac=0.05)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(fine_best, free, 100, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > fine_bestR + 1e-13:
                fine_best, fine_bestR = hp.copy(), rp
                improved = True
                print("  fine it=%d peak R=%.9f" % (it, fine_bestR))
        if not improved and not used_other:
            used_other = True
            ro = R_of(other)
            if ro > fine_bestR + 1e-13:
                fine_best, fine_bestR = other.copy(), ro
                print("  restart from other prolongation R=%.9f" % fine_bestR)

    print("final R=%.9f (fine)" % fine_bestR)
    mx, m, near = _stats(fine_best)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (fine_bestR, fine_best.size, 100.0 * np.mean(fine_best <= 0), mx, m, near))

    # Return best vs start
    if fine_bestR > start_bestR + 1e-12:
        alt = A if RA > start_bestR + 1e-12 else start_best
        return {"best": fine_best, "alternative": alt}
    else:
        return {"best": start_best, "alternative": fine_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    if beta <= 0:
        m = int(np.argmax(Lf))
        gLf = -dq / num
        gLf[m] += 1.0 / Lf[m]
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lf[m])
        return val, grad
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _peak_window(h, frac, pad):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    extra = max(pad, int(span * frac))
    lo = max(0, lo - extra)
    hi = min(h.size - 1, hi + extra)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
            startR = bestR
        else:
            best, bestR, startR = None, 0.0, 0.0
    else:
        best, bestR, startR = None, 0.0, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
        startR = bestR

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    alt = None
    altR = 0.0

    def _try(h, tag):
        nonlocal best, bestR, alt, altR
        if h is None or h.sum() <= 0:
            return False
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if r > bestR + 1e-14:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))
            return True
        elif alt is None or r > altR:
            alt, altR = h, r
        return False

    # --- Phase 1: full-array polish with soft-max annealing (beta ramp) ---
    # Anneal beta from small (smooth, robust) to large (approaches true max).
    for beta in (200.0, 400.0, 800.0, 1600.0):
        if time.process_time() >= deadline - 20.0:
            break
        h = _lbfgs_block(best, np.arange(N), 300, deadline, beta=beta)
        _try(h, "anneal_b%d" % int(beta))
    # exact full polish
    if time.process_time() < deadline - 15.0:
        h = _lbfgs_block(best, np.arange(N), 500, deadline, beta=0.0)
        _try(h, "full")

    # --- Phase 2: peak-window polishing at multiple scales ---
    for frac, pad in ((0.05, 8), (0.10, 16), (0.20, 32), (0.35, 64)):
        if time.process_time() >= deadline - 6.0:
            break
        free = _peak_window(best, frac, pad)
        h = _lbfgs_block(best, free, 400, deadline, beta=0.0)
        _try(h, "win%.2f" % frac)
        # small beta on window for robustness
        if time.process_time() < deadline - 4.0:
            h = _lbfgs_block(best, free, 200, deadline, beta=600.0)
            h = _lbfgs_block(h, free, 200, deadline, beta=0.0)
            _try(h, "winb%.2f" % frac)

    # --- Phase 3: toe/edge region polish (zeros & tails) ---
    if time.process_time() < deadline - 4.0:
        # free the left and right tails (first/last 15%)
        m = max(1, int(0.15 * N))
        free = np.concatenate((np.arange(0, m), np.arange(N - m, N)))
        h = _lbfgs_block(best, free, 300, deadline, beta=0.0)
        _try(h, "tails")

    # --- Phase 4: alternate full and window until deadline ---
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_block(best, np.arange(N), 400, deadline, beta=0.0)
        if _try(h, "full2"):
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        free = _peak_window(best, 0.25, 40)
        h = _lbfgs_block(best, free, 300, deadline, beta=0.0)
        if _try(h, "win2"):
            improved = True
        if not improved:
            # try a soft anneal to escape
            if time.process_time() < deadline - 3.0:
                h = _lbfgs_block(best, np.arange(N), 200, deadline, beta=400.0)
                h = _lbfgs_block(h, np.arange(N), 300, deadline, beta=0.0)
                if _try(h, "escape"):
                    improved = True
            if not improved:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt is not None and altR > 0 and bestR <= startR + 1e-12:
        return {"best": best, "alternative": alt}
    return best

