def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad

def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lm = Lf.max()
    w = np.exp(beta * (Lf - Lm))
    Z = w.sum()
    if Z <= 0:
        return _fun_grad(h)
    sm = Lm + np.log(Z) / beta
    gLf = -dq / num + (w / Z) / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad

def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb

def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad
    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)

def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad
    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)

def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near

def _left_toe_len(h):
    n = h.size
    thresh = 1e-14 * max(h.max(), 1e-300)
    i = 0
    while i < n and h[i] <= thresh:
        i += 1
    if i >= n:
        return 0
    j = i
    while j < n and h[j] > thresh:
        j += 1
    return j - i

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    toe_len = _left_toe_len(best)
    print("base R=%.7f N=%d left_toe_len=%d" % (bestR, best.size, toe_len))

    bestH = best.copy()
    bestRH = bestR

    def try_global(h_in, tag, budget):
        nonlocal bestH, bestRH
        if time.process_time() > deadline - budget - 0.5:
            return
        hp = h_in.copy()
        rp = R_of(hp)
        sub_dl = min(deadline - budget / 2, time.process_time() + budget / 2)
        hg = _lbfgs_log(hp, 300, sub_dl)
        rg = R_of(hg)
        if rg > rp:
            hp, rp = hg, rg
        for beta in (1e3, 1e4, 1e5):
            if time.process_time() > deadline - 0.5:
                break
            sub_dl = min(deadline - 0.3, time.process_time() + budget / 3)
            hb = _lbfgs_log(hp, 200, sub_dl,
                            fg=lambda hh, b=beta: _fun_grad_beta(hh, b))
            rb = R_of(hb)
            if rb > rp + 1e-13:
                hp, rp = hb, rb
        print("  global[%s] R=%.7f" % (tag, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    ACCEPT R=%.7f" % bestRH)

    rng = np.random.RandomState(12345)

    def perturb(h, scale, mode):
        n = h.size
        if mode == 'mult_noise':
            noise = 1.0 + scale * rng.randn(n)
            return np.clip(h * noise, 0, None)
        if mode == 'coord_warp':
            x = np.arange(n, dtype=float)
            amp = scale * 0.02 * n
            xw = x + amp * np.sin(2 * np.pi * x / n * rng.uniform(0.5, 3.0))
            xw = np.clip(xw, 0, n - 1)
            return np.interp(xw, x, h)
        if mode == 'smooth':
            from scipy.ndimage import gaussian_filter1d
            sig = max(1.0, scale * n * 0.005)
            return gaussian_filter1d(h, sig, mode='constant')
        return h

    try_global(bestH, "base", 8.0)

    hops = 0
    while time.process_time() < deadline - 4.0:
        hops += 1
        mode = ['mult_noise', 'coord_warp', 'smooth'][hops % 3]
        scale = [0.05, 0.1, 0.2, 0.3][hops % 4]
        h_pert = perturb(bestH, scale, mode)
        h_pert = _rescale(h_pert)
        sub_dl = min(deadline - 3.0, time.process_time() + 3.0)
        h_pol = _lbfgs_log(h_pert, 200, sub_dl)
        r_pol = R_of(h_pol)
        tag = "%s_%.2f" % (mode, scale)
        if r_pol > bestRH + 1e-13:
            bestH, bestRH = h_pol.copy(), r_pol
            print("  HOP ACCEPT %s R=%.7f" % (tag, bestRH))
        else:
            print("  hop %s R=%.7f (best %.7f)" % (tag, r_pol, bestRH))
        if hops % 3 == 0 and time.process_time() < deadline - 6.0:
            try_global(bestH, "re", 4.0)

    if time.process_time() < deadline - 2.0:
        thresh = 1e-14 * max(bestH.max(), 1e-300)
        i0 = 0
        while i0 < bestH.size and bestH[i0] <= thresh:
            i0 += 1
        j0 = i0
        while j0 < bestH.size and bestH[j0] > thresh:
            j0 += 1
        toe2 = bestH[i0:j0].copy() if j0 > i0 else bestH[:16].copy()
        if toe2.size > 0:
            for K in (8, 16, 32):
                if time.process_time() > deadline - 2.0:
                    break
                for s in (0.5, 1.0):
                    seg = toe2[:min(K, toe2.size)]
                    tail = s * seg[::-1]
                    h_ext = np.concatenate((tail, bestH))
                    n = h_ext.size
                    free = np.arange(0, min(n, K + 2 * K))
                    sub_dl = min(deadline - 1.5, time.process_time() + 2.0)
                    hp = _lbfgs_block(h_ext, free, 150, sub_dl)
                    rp = R_of(hp)
                    if rp > bestRH + 1e-13:
                        bestH, bestRH = hp.copy(), rp
                        print("  toe ACCEPT K=%d s=%.2f R=%.7f" % (K, s, bestRH))

    if time.process_time() < deadline - 0.5:
        h = _lbfgs_log(bestH, 300, deadline - 0.3)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m_, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m_, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolongate(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    out = np.interp(x_new, x_old, h)
    s_old = h.sum() / n
    s_new = out.sum() / N
    if s_new > 0:
        out *= s_old / s_new
    return np.maximum(out, 0.0)


def _edge_profile_analytic(N, p):
    """Exact cell averages of x^-p on [0,1], no cap."""
    i = np.arange(N, dtype=float)
    if abs(p - 0.5) < 1e-12:
        base = 2.0 * (np.sqrt(i + 1.0) - np.sqrt(i))
    else:
        base = ((i + 1.0) ** (1.0 - p) - i ** (1.0 - p)) / (1.0 - p)
    return base


def _make_two_sided(N, p, ratio):
    """h_i = A*base_L[i] + B*base_R[i], mass-normalized, rescaled."""
    base = _edge_profile_analytic(N, p)
    baseL = base
    baseR = base[::-1].copy()
    h = baseL + ratio * baseR
    s = h.sum()
    if s <= 0:
        return np.ones(N)
    h = h / s
    return _rescale(h)


def _rasterize_by_mass(h, N):
    """Rasterize profile h (length n) to N steps by cumulative-mass interpolation."""
    n = len(h)
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    c /= total
    x_new = (np.arange(N) + 0.5) / N
    # invert cumulative mass to get positions, then sample density
    pos = np.interp(x_new, c, np.arange(n + 1) / n)
    # density at pos: h evaluated
    out = np.interp(pos, (np.arange(n) + 0.5) / n, h, left=h[0], right=h[-1])
    s = out.sum()
    if s > 0:
        out = out / s * (h.sum() / n) * N
    return _rescale(np.maximum(out, 0.0))


def _lbfgs_block(h, deadline, frac=0.10, iters=120):
    """Polish a window around the peak of f*f, others fixed."""
    if time.process_time() >= deadline - 1.0:
        return h
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    # window in h-index space roughly around peak location
    half = max(4, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    if hi <= lo:
        return h
    idx = np.arange(lo, hi)
    h_fixed = h.copy()

    def fg(u):
        hh = h_fixed.copy()
        hh[idx] = np.exp(np.clip(u, -30.0, 30.0))
        val, g = _fun_grad(hh)
        return val, g[idx] * hh[idx]

    u0 = np.log(np.clip(h[idx], 1e-300, None))
    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(fg, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * idx.size, callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h
    if res is None:
        return h
    h2 = h_fixed.copy()
    h2[idx] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.90 * budget_seconds

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best = s.copy()
            best_R = R_of(best)
    if best is None:
        best = np.ones(256)
        best_R = R_of(best)

    print("start R = %.7f, N = %d" % (best_R, len(best)))

    # Step A: evaluate raw analytic profiles at N=16384
    N0 = 16384
    ps = [0.45, 0.5, 0.55, 0.6]
    ratios = [1.0, 1.5, 2.5]
    bestA = None
    bestA_R = -1.0
    bestA_params = None
    for p in ps:
        for ratio in ratios:
            h = _make_two_sided(N0, p, ratio)
            r = R_of(h)
            print("A p=%.2f ratio=%.2f R=%.7f" % (p, ratio, r))
            if r > bestA_R:
                bestA_R = r
                bestA = h
                bestA_params = (p, ratio)
    print("best raw A: p=%.2f ratio=%.2f R=%.7f" % (bestA_params[0], bestA_params[1], bestA_R))

    # Step B: resolution ladder from best analytic
    p_best, ratio_best = bestA_params
    cur = bestA.copy()
    cur_R = bestA_R
    ladder = [16384, 65536, 262144]
    for N in ladder:
        if time.process_time() > deadline - 8:
            break
        if N != len(cur):
            cur = _rasterize_by_mass(cur, N)
        r0 = R_of(cur)
        slice_deadline = min(deadline - 5, time.process_time() + 5.0)
        h = _lbfgs_log(cur, 150, slice_deadline)
        r = R_of(h)
        print("B N=%d R=%.7f (was %.7f)" % (N, r, r0))
        if r > cur_R:
            cur_R = r
            cur = h
        else:
            cur = h  # keep going from polished even if not better
    if cur_R > best_R:
        best_R = cur_R
        best = cur
    else:
        # keep analytic track as alternative even if worse
        pass

    # Step C: at finest level, block polish
    if time.process_time() < deadline - 3:
        h = _lbfgs_block(cur, deadline - 2, frac=0.10, iters=120)
        r = R_of(h)
        print("C block R=%.7f" % r)
        if r > cur_R:
            cur_R = r
            cur = h
        if r > best_R:
            best_R = r
            best = h

    # Step D: alternate log and block polish
    while time.process_time() < deadline - 2:
        h = _lbfgs_log(cur, 200, deadline - 1)
        r = R_of(h)
        if r > cur_R:
            cur_R = r
            cur = h
        if r > best_R:
            best_R = r
            best = h
        if time.process_time() > deadline - 2:
            break
        h = _lbfgs_block(cur, deadline - 1, frac=0.10, iters=120)
        r = R_of(h)
        if r > cur_R:
            cur_R = r
            cur = h
        if r > best_R:
            best_R = r
            best = h
        print("D R=%.7f" % best_R)

    print("best R = %.7f, N = %d" % (best_R, len(best)))

    result = {"best": best}
    if start is not None:
        s = np.asarray(start, dtype=float)
        if R_of(s) >= best_R:
            result["best"] = s
            result["alternative"] = best
    return result

