    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(32, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half + 1)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best, bestR = None, 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt, altR = None, 0.0

    def consider(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))
        elif alt is None or r > altR:
            alt, altR = h, r

    # Phase 1: smooth-max ramp to flatten the top of f*f
    if time.process_time() < deadline - 4.0:
        h = best.copy()
        for beta in (40.0, 120.0, 350.0, 900.0, 2200.0):
            if time.process_time() >= deadline - 3.0:
                break
            h = _lbfgs_log(h, 400, deadline,
                           fg=(lambda hh, b=beta: _fun_grad_beta(hh, b)))
        h = _lbfgs_log(h, 1200, deadline)
        consider(h, "sm")

    # Phase 2: p-norm smoothing (different shape of plateau)
    if time.process_time() < deadline - 4.0:
        h = best.copy()
        for p in (30.0, 18.0, 10.0, 6.0, 4.0):
            if time.process_time() >= deadline - 2.0:
                break
            h = _lbfgs_log(h, 500, deadline,
                           fg=(lambda hh, pp=p: _fun_grad_pnorm(hh, pp)))
        h = _lbfgs_log(h, 1000, deadline)
        consider(h, "pnorm")

    # Phase 3: windowed polishing around the peak of f*f
    for frac in (0.10, 0.20, 0.35):
        if time.process_time() >= deadline - 3.0:
            break
        free = _peak_window(best, frac)
        h = _lbfgs_block(best, free, 600, deadline,
                         fg=(lambda hh: _fun_grad_beta(hh, 600.0)))
        h = _lbfgs_log(h, 800, deadline)
        consider(h, "win(%.2f)" % frac)

    # Phase 4: alternate full + window polish until deadline
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 1000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        free = _peak_window(best, 0.45)
        h = _lbfgs_block(best, free, 500, deadline,
                         fg=(lambda hh: _fun_grad_beta(hh, 900.0)))
        h = _lbfgs_log(h, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None:
        startR = R_of(np.asarray(start, dtype=float))
        if bestR <= startR + 1e-12 and alt is not None and altR > 0:
            return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
import math
from scipy.optimize import differential_evolution, minimize
from scipy.signal import fftconvolve

# ---------- exact R evaluation ----------
def _conv(h):
    h = np.asarray(h, dtype=float)
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)

def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _conv(h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    a = Lp[:-1]; b = Lp[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * np.max(Lp)
    if den <= 0:
        return -1.0
    return num / den

# ---------- rasterize family ----------
def rasterize(params, N, sub=8):
    a, b, c, A, p, w, d = params
    if a > b:
        a, b = b, a
    i = np.arange(N)
    offs = (np.arange(sub) + 0.5) / sub
    x = (i[:, None] + offs[None, :]) / N
    plat = ((x >= a) & (x <= b)).astype(float)
    g = A * np.exp(-0.5 * ((x - p) / w) ** 2)
    f = d + c * plat + g
    return f.mean(axis=1)

def family_R(params, N=2048):
    h = rasterize(params, N)
    return -R_of(h)

# ---------- prolongation ----------
def prolongate(h, Nnew):
    h = np.asarray(h, dtype=float)
    N = h.size
    c = np.concatenate([[0.0], np.cumsum(h)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    edges = np.linspace(0.0, N, Nnew + 1)
    m = np.interp(edges, np.arange(N + 1), c)
    newh = np.diff(m)
    return np.maximum(newh, 0.0)

# ---------- fast polish machinery (from p0616) ----------
def _knots(h):
    L = _conv(h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    return Lp

def _num_and_dq(Lp):
    a = Lp[:-1]; b = Lp[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lp)
    dq[:-1] += (2*a + b) / 3.0
    dq[1:] += (a + 2*b) / 3.0
    return num, dq

def _backprop(gL, h):
    N = h.size
    return 2.0 * np.correlate(gL, h, mode='full')[N-1:2*N-1]

def _fun_grad(logh):
    h = np.exp(logh)
    s = h.sum()
    Lp = _knots(h)
    num, dq = _num_and_dq(Lp)
    mx = np.max(Lp)
    den = s * s * mx
    R = num / den
    gL = dq[1:-1]
    grad_num = _backprop(gL, h)
    am = np.argmax(Lp)
    grad_den = 2.0 * s * mx * np.ones(h.size)
    if 1 <= am <= h.size:
        j = am - 1
        k = np.arange(h.size)
        jj = j - k
        m = (jj >= 0) & (jj < h.size)
        grad_den[m] += s * s * 2.0 * h[jj[m]]
    gradR = (grad_num * den - num * grad_den) / (den * den)
    return -R, -(gradR * h)

def _lbfgs_log(h, maxiter=300, beta=0.0):
    h = np.maximum(np.asarray(h, dtype=float), 1e-12)
    if beta > 0:
        h = h + beta * h.mean()
    x0 = np.log(h)
    try:
        res = minimize(_fun_grad, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter*2,
                                'ftol': 1e-15, 'gtol': 1e-12})
        return np.maximum(np.exp(res.x), 0.0)
    except Exception:
        return h

def _peak_window(h):
    Lp = _knots(h)
    am = int(np.argmax(Lp))
    N = h.size
    # window in h-index space around the peak of f*f
    half = max(8, N // 40)
    lo = max(0, am - half)
    hi = min(N, am + half)
    if hi - lo < 4:
        return h
    seg = h[lo:hi].copy()
    seg = np.maximum(seg, 1e-12)
    x0 = np.log(seg)
    def fg(x):
        hh = h.copy()
        hh[lo:hi] = np.exp(x)
        return _fun_grad(np.log(np.maximum(hh, 1e-12)))
    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': 200, 'ftol': 1e-15, 'gtol': 1e-12})
        out = h.copy()
        out[lo:hi] = np.maximum(np.exp(res.x), 0.0)
        return out
    except Exception:
        return h

def _rescale(h):
    s = h.sum()
    if s > 0:
        return h / s * h.size
    return h

def _polish(h, deadline, levels=(0.0, 1e3, 1e4)):
    best = np.asarray(h, dtype=float)
    bestR = R_of(best)
    for beta in levels:
        if time.process_time() > deadline:
            break
        cand = _lbfgs_log(best, maxiter=300, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
        if time.process_time() > deadline:
            break
        cand = _peak_window(best)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR

# ---------- main ----------
def main_construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_h = s.copy()
            best_R = R_of(s)

    # ---- Stage 1: family optimisation at N=2048 ----
    N1 = 2048
    bounds = [(0.0, 1.0), (0.0, 1.0), (0.0, 10.0),
              (1e-2, 1e3), (0.0, 1.0), (0.002, 0.15), (0.0, 1.0)]

    def obj(x):
        return family_R(x, N1)

    candidates = []
    # structured guesses
    guesses = [
        [0.02, 0.98, 1.0, 100.0, 0.01, 0.008, 0.01],
        [0.02, 0.98, 1.0, 100.0, 0.99, 0.008, 0.01],
        [0.05, 0.95, 1.0, 50.0, 0.02, 0.02, 0.02],
        [0.05, 0.95, 1.0, 50.0, 0.98, 0.02, 0.02],
        [0.1, 0.9, 1.0, 20.0, 0.05, 0.05, 0.05],
        [0.1, 0.9, 1.0, 20.0, 0.95, 0.05, 0.05],
        [0.0, 1.0, 1.0, 10.0, 0.0, 0.05, 0.0],
        [0.0, 1.0, 1.0, 10.0, 1.0, 0.05, 0.0],
    ]
    for g in guesses:
        candidates.append(np.array(g))

    # differential evolution
    try:
        de_budget = min(14.0, (deadline - time.process_time()) * 0.4)
        if de_budget > 1.0:
            res = differential_evolution(obj, bounds, maxiter=300, popsize=24,
                                         tol=1e-8, seed=12345, polish=False,
                                         init='latinhypercube',
                                         updating='immediate', workers=1)
            candidates.append(res.x)
    except Exception:
        pass

    # local refinement of guesses
    rng = np.random.default_rng(7)
    n_local = 0
    while time.process_time() < deadline * 0.45 and n_local < 30:
        n_local += 1
        x0 = np.array([
            rng.uniform(0.0, 0.3),
            rng.uniform(0.7, 1.0),
            rng.uniform(0.1, 5.0),
            rng.uniform(1.0, 200.0),
            rng.choice([rng.uniform(0.0, 0.15), rng.uniform(0.85, 1.0)]),
            rng.uniform(0.002, 0.10),
            rng.uniform(0.0, 0.2),
        ])
        try:
            r = minimize(obj, x0, method='Nelder-Mead',
                         options={'maxiter': 300, 'xatol': 1e-6, 'fatol': 1e-10})
            candidates.append(r.x)
        except Exception:
            pass

    scored = []
    for x in candidates:
        try:
            v = -obj(x)
            if np.isfinite(v):
                scored.append((v, x))
        except Exception:
            pass
    scored.sort(key=lambda t: -t[0])
    top = scored[:5]

    if top:
        print("best raw family R at N=%d: %.6f" % (N1, top[0][0]))

    # build best family at N1
    if top:
        h = rasterize(top[0][1], N1)
        r = R_of(h)
        if r > best_R:
            best_h = h
            best_R = r

    if best_h is None:
        best_h = np.ones(50)
        best_R = R_of(best_h)

    # ---- Stage 2: escalate resolutions ----
    for Ntarget in [8192, 32768, 84992]:
        if time.process_time() > deadline:
            break
        h = prolongate(best_h, Ntarget)
        h, r = _polish(h, deadline)
        if r > best_R:
            best_R = r
            best_h = h

    # also polish start as fallback
    if start is not None and time.process_time() < deadline:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            hs, rs = _polish(s, deadline)
            if rs > best_R:
                best_R = rs
                best_h = hs

    if best_h is None:
        best_h = np.ones(50)

    print("final polished R: %.6f, N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            rs = R_of(s)
            if rs >= best_R:
                return s
            else:
                return {"best": best_h, "alternative": s}
    return best_h

def construct(budget_seconds, start):
    try:
        return main_construct(budget_seconds, start)
    except Exception:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_topq(h, q):
    """Robust max = mean of top-q fraction of knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    K = max(1, int(round(q * n)))
    if K >= n:
        K = n
    if K <= 1:
        return _fun_grad(h)
    idx = np.argpartition(Lf, n - K)[n - K:]
    Mq = Lf[idx].mean()
    if Mq <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / Mq
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Mq)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _top1_stats(h):
    Lf = _knots(h)
    n = Lf.size
    K = max(1, int(round(0.01 * n)))
    idx = np.argpartition(Lf, n - K)[n - K:]
    top = Lf[idx]
    return float(top.mean()), float(top.max() / max(top.min(), 1e-300))


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


def _topq_sweep(h, deadline, q_list, per_stage=5.0):
    """Run log-space L-BFGS with top-q robust max for each q; return best by exact R."""
    best = h.copy()
    bestR = R_of(best)
    for q in q_list:
        if time.process_time() >= deadline - 0.5:
            break
        if q <= 0.0:
            fg = _fun_grad
        else:
            fg = (lambda hh, _q=q: _fun_grad_topq(hh, _q))
        cap_t = min(deadline - 0.3, time.process_time() + per_stage)
        hs = _lbfgs_log(best, 200, cap_t, beta=0.0, fg=fg)
        rs = R_of(hs)
        mean1, spread1 = _top1_stats(hs)
        tag = "NEW" if rs > bestR + 1e-13 else "   "
        print("  %s q=%.4f R=%.9f top1%% mean=%.6f spread=%.4f" %
              (tag, q, rs, mean1, spread1))
        if rs > bestR + 1e-13:
            best, bestR = hs.copy(), rs
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))
    mean1, spread1 = _top1_stats(best)
    print("  base top1%% mean=%.6f spread=%.4f" % (mean1, spread1))

    # Detect spike side
    n = best.size
    left_max = best[:max(1, n // 20)].max()
    right_max = best[n - max(1, n // 20):].max()
    reversed_ = right_max > left_max
    if reversed_:
        work = best[::-1].copy()
        print("  spike on right; operating on reversed array")
    else:
        work = best.copy()
        print("  spike on left")

    bestH = work.copy()
    bestRH = R_of(work)
    experiment_best = work.copy()
    experiment_bestR = bestRH

    q_list = [0.01, 0.005, 0.002, 0.0]

    # ---- Main loop: q-sweep + polish until deadline ----
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        print("--- iteration %d (R=%.9f) ---" % (it, bestRH))
        # q-sweep on current best
        hs, rs = _topq_sweep(bestH, deadline - 1.0, q_list, per_stage=5.0)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  after q-sweep R=%.9f" % bestRH)
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs

        if time.process_time() >= deadline - 1.5:
            break

        # polish
        cap_t = min(deadline - 0.5, time.process_time() + 8.0)
        hp, rp = _polish(bestH, cap_t, bestRH)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("  after polish R=%.9f" % bestRH)
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp

        mean1, spread1 = _top1_stats(bestH)
        print("  top1%% mean=%.6f spread=%.4f" % (mean1, spread1))

    # ---- Remaining time: block-additive passes ----
    for B in (256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp

    # final polish loop
    loop_end = deadline - 0.5
    it2 = 0
    while time.process_time() < loop_end:
        it2 += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it2, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it2, bestRH))

    if reversed_:
        bestH = bestH[::-1].copy()
        experiment_best = experiment_best[::-1].copy()

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))
    mean1, spread1 = _top1_stats(bestH)
    print("final top1%% mean=%.6f spread=%.4f" % (mean1, spread1))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


# ---------- Coarsening / prolongation ----------

def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    """Cumulative-mass interpolation of coarse hc back to n_target cells."""
    mc = hc.size
    # coarse cumulative mass at coarse cell edges (mc+1 edges)
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    # coarse edges in normalized coordinate [0,1]
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n_fine = best.size
    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Downward ladder ----
    def run_ladder(seed, seedR, tag):
        nonlocal bestH, bestRH, experiment_best, experiment_bestR
        # Build coarse chain
        chain = [seed.copy()]
        for _ in range(3):
            chain.append(_coarsen(chain[-1]))
        # Optimize each level (coarse to fine order for prolongation, but we
        # optimize all levels independently from the coarsened seed)
        coarse_sols = []
        for lvl in range(len(chain)):
            hc = chain[lvl]
            rc0 = R_of(hc)
            print("  [%s] level %d N=%d start R=%.9f" % (tag, lvl, hc.size, rc0))
            cur = hc.copy()
            curR = rc0
            for beta in (0.0, 1e3, 1e4):
                if time.process_time() >= deadline - 6.0:
                    break
                cap_t = min(deadline - 5.0, time.process_time() + 3.0)
                hs = _lbfgs_log(cur, 250, cap_t, beta=beta)
                rs = R_of(hs)
                if rs > curR:
                    cur, curR = hs, rs
            print("  [%s] level %d N=%d optimized R=%.9f (dR=%+.2e)" %
                  (tag, lvl, cur.size, curR, curR - rc0))
            coarse_sols.append((cur.copy(), curR))
        # Prolongate each coarse solution back to n_fine and evaluate exact R
        best_pro = None
        best_proR = -1.0
        for lvl, (hc, rc) in enumerate(coarse_sols):
            hp = _prolongate(hc, n_fine)
            rp = R_of(hp)
            print("  [%s] prolongated level %d -> R=%.9f" % (tag, lvl, rp))
            if rp > best_proR:
                best_pro, best_proR = hp, rp
        return best_pro, best_proR

    # First ladder from current best
    if time.process_time() < deadline - 8.0:
        pro, proR = run_ladder(bestH, bestRH, "L1")
        if pro is not None and proR > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = pro.copy(), proR
            print("  ladder1 prolonged R=%.9f (base %.9f)" % (proR, bestRH))
            # Polish the prolonged solution
            if time.process_time() < deadline - 3.0:
                cap_t = min(deadline - 2.0, time.process_time() + 8.0)
                hp, rp = _short_polish(experiment_best, cap_t, experiment_bestR)
                if rp > experiment_bestR:
                    experiment_best, experiment_bestR = hp, rp
                    print("  after short_polish R=%.9f" % experiment_bestR)
                if time.process_time() < deadline - 2.0:
                    cap_t = min(deadline - 1.0, time.process_time() + 6.0)
                    hp, rp = _polish(experiment_best, cap_t, experiment_bestR)
                    if rp > experiment_bestR:
                        experiment_best, experiment_bestR = hp, rp
                        print("  after full polish R=%.9f" % experiment_bestR)

    # Adopt if better
    if experiment_bestR > bestRH + 1e-13:
        bestH, bestRH = experiment_best.copy(), experiment_bestR
        print("  adopting ladder result R=%.9f" % bestRH)

    # Second ladder from current best if time remains
    if time.process_time() < deadline - 8.0:
        pro, proR = run_ladder(bestH, bestRH, "L2")
        if pro is not None and proR > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = pro.copy(), proR
            print("  ladder2 prolonged R=%.9f" % proR)
            if time.process_time() < deadline - 3.0:
                cap_t = min(deadline - 2.0, time.process_time() + 8.0)
                hp, rp = _short_polish(experiment_best, cap_t, experiment_bestR)
                if rp > experiment_bestR:
                    experiment_best, experiment_bestR = hp, rp
                    print("  after short_polish R=%.9f" % experiment_bestR)
                if time.process_time() < deadline - 2.0:
                    cap_t = min(deadline - 1.0, time.process_time() + 6.0)
                    hp, rp = _polish(experiment_best, cap_t, experiment_bestR)
                    if rp > experiment_bestR:
                        experiment_best, experiment_bestR = hp, rp
                        print("  after full polish R=%.9f" % experiment_bestR)
        if experiment_bestR > bestRH + 1e-13:
            bestH, bestRH = experiment_best.copy(), experiment_bestR
            print("  adopting ladder2 result R=%.9f" % bestRH)

    # ---- Remaining time: block-additive passes on best ----
    for B in (256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # final polish loop
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, fg=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, fg=fg)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    near = np.mean(Lf >= 0.99 * mx)
    argm = int(np.argmax(Lf)) / max(1, Lf.size - 1)
    return (100.0 * np.mean(h <= 0), h.max() / max(1e-30, h.mean()),
            near, argm)


def _interp_to(h, N):
    """Resample a step function h (N0 steps) onto N steps by area-preserving
    piecewise-constant integration, preserving total mass."""
    n0 = h.size
    if n0 == N:
        return h.copy()
    # cumulative mass of h at positions i/n0
    c = np.concatenate(([0.0], np.cumsum(h)))
    # target boundaries at j/N in [0,1] -> position in source index space
    xs = np.linspace(0.0, n0, N + 1)
    # linear interpolation of cumulative mass
    cm = np.interp(xs, np.arange(n0 + 1), c)
    out = np.diff(cm) * (N / n0)
    return _rescale(np.clip(out, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.7f (N=%d)" % (baseR, base.size))

    best = base.copy()
    bestR = baseR

    def stage(hcur, Rcur, label):
        nonlocal best, bestR
        if Rcur > bestR + 1e-13:
            best = hcur.copy(); bestR = Rcur
        z, mm, nm, am = _stats(hcur)
        print("%s R=%.8f N=%d zeros %.1f%% max/mean %.2f near %.4f argmax %.3f" %
              (label, Rcur, hcur.size, z, mm, nm, am))

    # Stage 1: exact log-L-BFGS on the (possibly resampled) start
    h = base.copy()
    R = baseR
    if time.process_time() < deadline - 8.0:
        h2 = _lbfgs_log(h, 300, min(deadline, time.process_time() + 5.0))
        R2 = R_of(h2)
        if R2 > R:
            h, R = h2, R2
        stage(h, R, "lbfgs")

    # Stage 2: softmax (beta) smoothing passes to escape argmax pinning
    for beta in (1e3, 1e4, 3e4):
        if time.process_time() >= deadline - 5.0:
            break
        fg = (lambda hh, _b=beta: _fun_grad_beta(hh, _b))
        hb = _lbfgs_log(h, 80, min(deadline, time.process_time() + 2.5), fg=fg)
        Rb = R_of(hb)
        if Rb > R:
            h, R = hb, Rb
        stage(h, R, "beta%.0e" % beta)

    # Stage 3: peak-region window polish
    for frac in (0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 3.0:
            break
        hw = _window_polish_peak(h, min(deadline, time.process_time() + 2.5),
                                 frac, 32, maxiter=150)
        Rw = R_of(hw)
        if Rw > R:
            h, R = hw, Rw
        stage(h, R, "win%.2f" % frac)

    # Stage 4: REFINEMENT VIA RESAMPLING - the substantial new idea.
    # Take the current best and resample it to a larger N (area-preserving)
    # then re-optimise. This lets the optimiser discover finer structure
    # than the start grid allows.
    n_cur = h.size
    for factor in (2, 2):  # double twice if budget allows
        if time.process_time() >= deadline - 6.0:
            break
        N_new = min(1000000, n_cur * factor)
        if N_new == n_cur:
            break
        hr = _interp_to(h, N_new)
        # short polish on the refined grid
        hr2 = _lbfgs_log(hr, 200, min(deadline, time.process_time() + 4.0))
        Rr = R_of(hr2)
        if Rr > R:
            h, R = hr2, Rr
            n_cur = N_new
        stage(h, R, "refine%d->%d" % (factor, N_new))

    # Stage 5: alternate exact polish + window polish until deadline
    it = 0
    while time.process_time() < deadline - 2.5:
        it += 1
        hp = _lbfgs_log(h, 200, min(deadline, time.process_time() + 2.5))
        Rp = R_of(hp)
        if Rp > R:
            h, R = hp, Rp
        stage(h, R, "pol%d" % it)
        for frac in (0.08, 0.15):
            if time.process_time() >= deadline - 1.5:
                break
            hw = _window_polish_peak(h, min(deadline, time.process_time() + 1.5),
                                     frac, 32, maxiter=100)
            Rw = R_of(hw)
            if Rw > R:
                h, R = hw, Rw
            stage(h, R, "%d-win%.2f" % (it, frac))

    print("final R=%.8f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    if bestR > start_bestR - 1e-6 and best.size != start_best.size:
        return {"best": start_best, "alternative": best}
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

