    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


# ---------- Coarsening / prolongation ----------

def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def _aggregate(h, k, o):
    """Aggregate k consecutive cells starting at offset o, value = mean.
    Ragged tail handled by cumulative-mass interpolation."""
    n = h.size
    # Build a padded array so that (n - o) is divisible by k
    if o >= n:
        o = 0
    body = h[o:]
    m = body.size
    full = m // k
    used = full * k
    if full == 0:
        return _rescale(np.array([h.mean()]))
    core = body[:used].reshape(full, k).mean(axis=1)
    tail = body[used:]
    if tail.size > 0:
        # distribute tail mass proportionally into one extra coarse cell
        extra = tail.sum() / k
        core = np.concatenate((core, [extra]))
    # Prepend head cells (before offset) as a single coarse cell
    if o > 0:
        head = h[:o].sum() / k
        core = np.concatenate(([head], core))
    return _rescale(np.clip(core, 0.0, None))


def _prolongate_replicate(hc, n_target, k, o):
    """Exact k-fold step replication of coarse cells, with mass-interp tail."""
    mc = hc.size
    # We know the coarse array was built with an optional head cell (if o>0)
    # and possibly an extra tail cell. Reconstruct approximate fine array.
    # Simpler: replicate each coarse cell k times, then mass-interpolate to n_target.
    rep = np.repeat(hc, k)
    if rep.size == n_target:
        return _rescale(rep)
    # If head existed, account for offset by mass interpolation
    return _prolongate(hc, n_target)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n_fine = best.size
    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Phase/block-size sweep ----
    # (k, o) pairs: k=2 offsets 0,1; k=3 offsets 0,1,2
    pairs = [(2, 0), (2, 1), (3, 0), (3, 1), (3, 2)]

    def sweep(seed, seedR, tag):
        nonlocal bestH, bestRH, experiment_best, experiment_bestR
        for (k, o) in pairs:
            if time.process_time() >= deadline - 6.0:
                return
            hc = _aggregate(seed, k, o)
            rc0 = R_of(hc)
            cur = hc.copy()
            curR = rc0
            for beta in (0.0, 1e3, 1e4):
                if time.process_time() >= deadline - 5.0:
                    break
                cap_t = min(deadline - 4.0, time.process_time() + 2.0)
                hs = _lbfgs_log(cur, 150, cap_t, beta=beta)
                rs = R_of(hs)
                if rs > curR:
                    cur, curR = hs, rs
                print("  [%s] k=%d o=%d beta=%.0e coarse R=%.9f (start %.9f)" %
                      (tag, k, o, beta, curR, rc0))
            # Prolongate back to fine resolution two ways
            cands = []
            hp1 = _prolongate(cur, n_fine)
            cands.append(("mass", hp1))
            hp2 = _prolongate_replicate(cur, n_fine, k, o)
            cands.append(("rep", hp2))
            for name, hp in cands:
                if time.process_time() >= deadline - 3.0:
                    break
                rp0 = R_of(hp)
                cap_t = min(deadline - 2.0, time.process_time() + 4.0)
                hpp, rpp = _short_polish(hp, cap_t, rp0)
                print("  [%s] k=%d o=%d %s prolong R=%.9f polished R=%.9f" %
                      (tag, k, o, name, rp0, rpp))
                if rpp > experiment_bestR + 1e-13:
                    experiment_best, experiment_bestR = hpp.copy(), rpp
                    print("    NEW EXPERIMENT BEST R=%.9f" % experiment_bestR)
                if rpp > bestRH + 1e-13:
                    bestH, bestRH = hpp.copy(), rpp
                    print("    NEW BEST R=%.9f" % bestRH)

    # First sweep from current best
    if time.process_time() < deadline - 8.0:
        sweep(bestH, bestRH, "S1")

    # If we found something better, full polish it
    if experiment_bestR > start_bestR + 1e-13 and time.process_time() < deadline - 4.0:
        cap_t = min(deadline - 2.0, time.process_time() + 6.0)
        hp, rp = _polish(experiment_best, cap_t, experiment_bestR)
        if rp > experiment_bestR:
            experiment_best, experiment_bestR = hp, rp
            print("  after full polish R=%.9f" % experiment_bestR)
        if experiment_bestR > bestRH + 1e-13:
            bestH, bestRH = experiment_best.copy(), experiment_bestR
            print("  adopting polished R=%.9f" % bestRH)

    # Second sweep from best-so-far if time remains
    if time.process_time() < deadline - 8.0:
        sweep(bestH, bestRH, "S2")
        if experiment_bestR > start_bestR + 1e-13 and time.process_time() < deadline - 4.0:
            cap_t = min(deadline - 2.0, time.process_time() + 6.0)
            hp, rp = _polish(experiment_best, cap_t, experiment_bestR)
            if rp > experiment_bestR:
                experiment_best, experiment_bestR = hp, rp
                print("  after full polish R=%.9f" % experiment_bestR)
            if experiment_bestR > bestRH + 1e-13:
                bestH, bestRH = experiment_best.copy(), experiment_bestR
                print("  adopting polished R=%.9f" % bestRH)

    # ---- Remaining time: block-additive passes on best ----
    for B in (256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # final polish loop
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_beta_tail(h, beta, tail):
    """Softmax over knots near the max only, to give a much sharper target that
    pushes the profile toward a flat plateau while ignoring far-away knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    thr = mx - tail
    mask = Lf >= thr
    Lm_sel = Lf[mask]
    e = np.exp(beta * (Lm_sel - Lm_sel.max()))
    Z = e.sum()
    w_sel = e / Z
    sm = Lm_sel.max() + np.log(Z) / beta
    w = np.zeros_like(Lf)
    w[mask] = w_sel
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _gauss_smooth(h, sigma):
    if sigma <= 0.5:
        return h.copy()
    r = int(3 * sigma) + 1
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _smooth_perturb(h, sigma, amp, seed):
    n = h.size
    rng = np.random.RandomState(seed)
    m = max(16, n // 64)
    noise = rng.randn(m)
    xp = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, n)
    p = np.interp(xi, xp, noise)
    return np.clip(h * np.exp(amp * p), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt = None
    altR = 0.0

    # NEW primary idea: refine on a FINER grid. The reported construction has a
    # wide plateau of near-max knots and many zero steps, so the true limiting
    # profile is smoother than the current grid can resolve. We prolongate to a
    # finer grid (2x steps), re-optimise there, and only fall back to the coarse
    # grid at the end if it did not help. Finer resolution lets the optimiser
    # shape the plateau / tails more freely and typically gains a little R.
    def anneal_polish(h0, dl, betas, iters):
        h = h0
        for beta in betas:
            if time.process_time() >= dl - 1.0:
                break
            h = _lbfgs_log(h, iters, dl, beta=beta)
            h = _window_polish_peak(h, dl, 0.35, 16, maxiter=iters, beta=beta)
        return h

    betas = [2.0, 8.0, 32.0, 128.0, 512.0, 2048.0]

    # Pass 0: quick exact-objective polish of the start on its own grid.
    if time.process_time() < deadline - 30.0:
        h = _lbfgs_log(best, 600, deadline - 25.0)
        h = _window_polish_peak(h, deadline - 20.0, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("polish wins R=%.7f" % bestR)
        elif r > altR:
            alt, altR = h, r

    # Pass 1: prolongate to a finer grid and re-optimise there.
    fine_best = None
    fineR = 0.0
    if time.process_time() < deadline - 15.0 and N < 500000:
        Nf = min(500000, 2 * N)
        hf = _rescale(_prolongate(best, Nf))
        # light smoothing to remove prolongation kinks
        hf = _rescale(_gauss_smooth(hf, 1.0))
        hf = anneal_polish(hf, deadline - 12.0, betas[:4], 250)
        hf = _lbfgs_log(hf, 500, deadline - 8.0)
        hf = _window_polish_peak(hf, deadline - 6.0, 0.40, 24)
        rf = R_of(hf)
        print("fine N=%d R=%.7f" % (Nf, rf))
        fine_best, fineR = hf, rf
        if rf > altR:
            alt, altR = hf, rf
        if rf > bestR + 1e-15:
            best, bestR = hf, rf
            print("fine wins R=%.7f" % bestR)

    # Pass 2: on the fine grid (or best grid) run softmax-tail annealing,
    # focusing on flattening the maximum plateau.
    def tail_anneal(h0, dl):
        h = h0
        for tail, beta in [(0.05, 50.0), (0.02, 100.0), (0.01, 200.0),
                           (0.005, 400.0), (0.002, 800.0)]:
            if time.process_time() >= dl - 1.0:
                break
            fg = (lambda hh, b=beta, t=tail: _fun_grad_beta_tail(hh, b, t))
            h = _lbfgs_log(h, 300, dl, fg=fg)
        return h

    if time.process_time() < deadline - 8.0:
        src = fine_best if (fine_best is not None and fineR >= bestR * 0.999) else best
        ht = tail_anneal(src, deadline - 6.0)
        ht = _lbfgs_log(ht, 500, deadline - 4.0)
        ht = _window_polish_peak(ht, deadline - 3.0, 0.40, 24)
        rt = R_of(ht)
        print("tail R=%.7f" % rt)
        if rt > altR:
            alt, altR = ht, rt
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
            print("tail wins R=%.7f" % bestR)

    # Pass 3: perturb + anneal on the working grid.
    perturb_specs = [
        (max(2.0, best.size / 300.0), 0.05, 11),
        (max(4.0, best.size / 150.0), 0.06, 12),
    ]
    for sigma, amp, seed in perturb_specs:
        if time.process_time() >= deadline - 5.0:
            break
        hp = _rescale(_smooth_perturb(best, sigma, amp, seed))
        hp = anneal_polish(hp, deadline - 3.0, betas[:4], 200)
        hp = _lbfgs_log(hp, 400, deadline - 2.0)
        hp = _window_polish_peak(hp, deadline - 1.5, 0.35, 16)
        r = R_of(hp)
        print("perturb s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("perturb wins R=%.7f" % bestR)

    # Final: alternate full/peak polish until budget exhausted.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _gauss_smooth(h, sigma=1.5):
    r = 3
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    hp = np.concatenate((np.full(r, h[0]), h, np.full(r, h[-1])))
    return np.convolve(hp, k, mode='valid')


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample_lin(h, factor):
    """Linear (smooth) upsampling by integer factor."""
    n = h.size
    m = n * factor
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = R_of(base)
        best = base.copy()
    else:
        # analytic sqrt-profile seed
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d" % (bestR, best.size))

    # ---- Phase 1: fine search from the start (the main lever) ----
    def try_fine(name, cand):
        nonlocal best, bestR
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f" % (name, bestR))
            return True
        return False

    loop_end = deadline - 1.0
    it = 0
    stall = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 6.0)
        hs = _lbfgs_log(best, 400, cap)
        if try_fine("full it=%d" % it, hs):
            improved = True
        else:
            stall += 1

        if time.process_time() < loop_end - 1.0 and stall >= 1:
            # peak-window polish to break out of plateaus
            free = _peak_window(best, frac=0.04)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 150, cap)
            if try_fine("peak it=%d" % it, hp):
                improved = True
                stall = 0

        if time.process_time() < loop_end - 1.0 and stall >= 2:
            # Try a smoothed prolongation as an escape; only keep if it beats.
            A = _rescale(np.repeat(best, 2))
            B = _rescale(np.repeat(_gauss_smooth(best, 1.5), 2))
            RA, RB = R_of(A), R_of(B)
            cand = A if RA >= RB else B
            cap = min(loop_end, time.process_time() + 4.0)
            hc = _lbfgs_log(cand, 200, cap)
            if try_fine("prolong it=%d" % it, hc):
                improved = True
                stall = 0
            else:
                stall = 0  # reset stall; prolongation was attempted

    # Final safety: ensure we return at least the start.
    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d" % (bestR, best.size))
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(int)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts)
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    hh = h + np.repeat(res.x, counts)
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


def _smooth_and_refine(h, deadline, baseR, rng):
    """New idea: apply mild Gaussian smoothing (shape perturbation) to escape
    local optimum, then re-optimise. Try several sigma scales + random jitter."""
    best = h.copy()
    bestR = baseR
    n = h.size
    # Try smoothing with a few sigmas (in step units)
    for sigma in (0.7, 1.5, 3.0, 6.0):
        if time.process_time() >= deadline - 2.0:
            break
        rad = max(1, int(4 * sigma))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / sigma) ** 2)
        k /= k.sum()
        hs = np.convolve(h, k, mode='same')
        hs = _rescale(hs)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs, rs
        # polish
        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            hp = _lbfgs_log(hs, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
    # random multiplicative jitter on peak window
    for _ in range(2):
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(best, frac=0.10)
        hh = best.copy()
        hh[free] *= (1.0 + 0.02 * rng.standard_normal(free.size))
        hh = _rescale(np.clip(hh, 0, None))
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hp = _lbfgs_block(hh, free, 150, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20250601)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Block additive passes (as before but better interleaved) ----
    for B in (128, 256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # ---- New: smoothing + jitter escape ----
    if time.process_time() < deadline - 5.0:
        hs, rs = _smooth_and_refine(bestH, min(deadline - 2.0, time.process_time() + 12.0),
                                    bestRH, rng)
        print("  smooth+jitter R=%.12f (base %.12f, dR=%+.2e)" %
              (rs, bestRH, rs - bestRH))
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs

    # ---- final polish loop ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


# ---------- Coarsening / prolongation ----------

def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def _aggregate(h, k, o):
    n = h.size
    if o >= n:
        o = 0
    body = h[o:]
    m = body.size
    full = m // k
    used = full * k
    if full == 0:
        return _rescale(np.array([h.mean()]))
    core = body[:used].reshape(full, k).mean(axis=1)
    tail = body[used:]
    if tail.size > 0:
        extra = tail.sum() / k
        core = np.concatenate((core, [extra]))
    if o > 0:
        head = h[:o].sum() / k
        core = np.concatenate(([head], core))
    return _rescale(np.clip(core, 0.0, None))


def _prolongate_replicate(hc, n_target, k, o):
    rep = np.repeat(hc, k)
    if rep.size == n_target:
        return _rescale(rep)
    return _prolongate(hc, n_target)


# ---------- Gauss-Newton on the near-max knot set ----------

def _gn_step(h, kappa, lam, n_cg=40):
    """Solve (J^T J + lam I) d = J^T r on near-max knot set A.
    J d restricted to A equals 2*conv(d,h) at those knots."""
    n = h.size
    L = _knots(h)
    M = L.max()
    A = np.flatnonzero(L >= (1.0 - kappa) * M)
    if A.size == 0:
        return None, 0.0, 0.0
    r = M - L[A]
    rms = float(np.sqrt(np.mean(r * r)))
    Llen = L.size

    def Jd(d):
        c = 2.0 * fftconvolve(d, h)[:Llen]
        return c[A]

    def JT(v):
        vf = np.zeros(Llen)
        vf[A] = v
        full = 2.0 * np.correlate(vf, h, mode='full')
        # correlate(vf,h)[k] = sum vf[j] h[j - k + (n-1)]; we want conv(vf,h)[N-1:2N-1]
        # conv(vf,h)[k] = sum vf[j] h[k-j]; use fftconvolve for consistency
        return full[n - 1:2 * n - 1]

    # Precompute JT r
    b = JT(r)
    x = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs_old = float(np.dot(res, res))
    if rs_old <= 0:
        return None, rms, 0.0
    for _ in range(n_cg):
        Jp = Jd(p)
        denom = float(np.dot(Jp, Jp)) + lam * float(np.dot(p, p))
        if denom <= 0:
            break
        alpha = rs_old / denom
        x += alpha * p
        res -= alpha * (JT(Jp) + lam * p)
        rs_new = float(np.dot(res, res))
        if rs_new < 1e-30 * rs_old:
            break
        p = res + (rs_new / rs_old) * p
        rs_old = rs_new
    return x, rms, float(np.sqrt(rs_old))


def _gn_improve(h, deadline, kappas=(0.05, 0.02, 0.01), outer=8):
    best = h.copy()
    bestR = R_of(best)
    for kappa in kappas:
        for it in range(outer):
            if time.process_time() >= deadline - 1.0:
                return best, bestR
            L = _knots(best)
            M = L.max()
            A = np.flatnonzero(L >= (1.0 - kappa) * M)
            if A.size == 0:
                break
            r = M - L[A]
            # lam from mean |J^T r| (approx via gradient magnitude on active)
            # cheap proxy: use RMS of r scaled by h magnitude
            scale = max(1e-12, float(np.mean(np.abs(r))))
            lam = 1e-2 * scale * scale * max(1.0, float(best.size))
            # simpler: lam relative to signal
            lam = 1e-2 * float(np.mean(best)) * float(np.mean(best)) * best.size
            improved = False
            for _ in range(4):
                d, rms, cgres = _gn_step(best, kappa, lam)
                if d is None:
                    break
                for alpha in (1.0, 0.5, 0.25, 0.125, 2.0):
                    hc = best + alpha * d
                    if np.any(hc < 0):
                        continue
                    hc = _rescale(hc)
                    rc = R_of(hc)
                    if rc > bestR + 1e-14:
                        best, bestR = hc, rc
                        improved = True
                        break
                if improved:
                    break
                lam *= 10.0
            L2 = _knots(best)
            M2 = L2.max()
            A2 = np.flatnonzero(L2 >= (1.0 - kappa) * M2)
            rms2 = float(np.sqrt(np.mean((M2 - L2[A2]) ** 2))) if A2.size else 0.0
            print("  [GN k=%.2f it=%d] R=%.9f rms=%.3e -> %.3e |A|=%d" %
                  (kappa, it, bestR, rms, rms2, A.size))
            if not improved:
                break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n_fine = best.size
    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Phase 1: Gauss-Newton on near-max knot set ----
    if time.process_time() < deadline - 20.0:
        cap_t = min(deadline - 15.0, time.process_time() + 18.0)
        hg, rg = _gn_improve(bestH, cap_t)
        print("  GN result R=%.9f (start %.9f)" % (rg, bestRH))
        if rg > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hg.copy(), rg
        if rg > bestRH + 1e-13:
            bestH, bestRH = hg.copy(), rg
            print("    NEW BEST after GN R=%.9f" % bestRH)

    # ---- Phase 2: p0646's coarsening sweep ----
    pairs = [(2, 0), (2, 1), (3, 0), (3, 1), (3, 2)]

    def sweep(seed, seedR, tag):
        nonlocal bestH, bestRH, experiment_best, experiment_bestR
        for (k, o) in pairs:
            if time.process_time() >= deadline - 6.0:
                return
            hc = _aggregate(seed, k, o)
            rc0 = R_of(hc)
            cur = hc.copy()
            curR = rc0
            for beta in (0.0, 1e3, 1e4):
                if time.process_time() >= deadline - 5.0:
                    break
                cap_t = min(deadline - 4.0, time.process_time() + 2.0)
                hs = _lbfgs_log(cur, 150, cap_t, beta=beta)
                rs = R_of(hs)
                if rs > curR:
                    cur, curR = hs, rs
            cands = []
            hp1 = _prolongate(cur, n_fine)
            cands.append(("mass", hp1))
            hp2 = _prolongate_replicate(cur, n_fine, k, o)
            cands.append(("rep", hp2))
            for name, hp in cands:
                if time.process_time() >= deadline - 3.0:
                    break
                rp0 = R_of(hp)
                cap_t = min(deadline - 2.0, time.process_time() + 4.0)
                hpp, rpp = _short_polish(hp, cap_t, rp0)
                print("  [%s] k=%d o=%d %s prolong R=%.9f polished R=%.9f" %
                      (tag, k, o, name, rp0, rpp))
                if rpp > experiment_bestR + 1e-13:
                    experiment_best, experiment_bestR = hpp.copy(), rpp
                if rpp > bestRH + 1e-13:
                    bestH, bestRH = hpp.copy(), rpp
                    print("    NEW BEST R=%.9f" % bestRH)

    if time.process_time() < deadline - 8.0:
        sweep(bestH, bestRH, "S1")

    if experiment_bestR > start_bestR + 1e-13 and time.process_time() < deadline - 4.0:
        cap_t = min(deadline - 2.0, time.process_time() + 6.0)
        hp, rp = _polish(experiment_best, cap_t, experiment_bestR)
        if rp > experiment_bestR:
            experiment_best, experiment_bestR = hp, rp
        if experiment_bestR > bestRH + 1e-13:
            bestH, bestRH = experiment_best.copy(), experiment_bestR

    if time.process_time() < deadline - 8.0:
        sweep(bestH, bestRH, "S2")
        if experiment_bestR > start_bestR + 1e-13 and time.process_time() < deadline - 4.0:
            cap_t = min(deadline - 2.0, time.process_time() + 6.0)
            hp, rp = _polish(experiment_best, cap_t, experiment_bestR)
            if rp > experiment_bestR:
                experiment_best, experiment_bestR = hp, rp
            if experiment_bestR > bestRH + 1e-13:
                bestH, bestRH = experiment_best.copy(), experiment_bestR

    # ---- Phase 3: block-additive passes ----
    for B in (256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # ---- Phase 4: final polish loop ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    """Smooth-max version of ||f*f||_inf for stabilising the gradient."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample_lin(h, factor):
    n = h.size
    m = n * factor
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = R_of(base)
        best = base.copy()
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d" % (bestR, best.size))

    def try_fine(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f" % (name, bestR))
            return True
        return False

    loop_end = deadline - 1.0
    it = 0
    # ---------------------------------------------------------------
    # Phase 0: an aggressive global pass with smoothed-max target.
    # ---------------------------------------------------------------
    for beta in (200.0, 500.0, 1000.0):
        if time.process_time() >= loop_end - 2.0:
            break
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(best, 200, cap, fg=(lambda hh, b=beta: _fun_grad_beta(hh, b)))
        try_fine("beta=%g" % beta, hs)

    # ---------------------------------------------------------------
    # Phase 1: alternating full + peak-window polish, with a second
    # finer upsample attempt when stalling.
    # ---------------------------------------------------------------
    stall = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(best, 400, cap)
        if try_fine("full it=%d" % it, hs):
            improved = True
        else:
            stall += 1

        if time.process_time() < loop_end - 1.0:
            free = _peak_window(best, frac=0.04)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 150, cap)
            if try_fine("peak it=%d" % it, hp):
                improved = True
                stall = 0

        if time.process_time() < loop_end - 1.0 and stall >= 2:
            # Try upsample-by-2 with a finer local polish; also try
            # an upsample-by-3 for a finer grid.
            for fac in (2, 3):
                if time.process_time() >= loop_end - 1.0:
                    break
                A = _rescale(_upsample_lin(best, fac))
                cap = min(loop_end, time.process_time() + 3.0)
                # refine only the peak window on the finer grid to save time
                free = _peak_window(A, frac=0.08)
                hc = _lbfgs_block(A, free, 200, cap)
                if try_fine("up%d it=%d" % (fac, it), hc):
                    improved = True
                    stall = 0
                    break

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d" % (bestR, best.size))
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

