    h2 = np.repeat(baseH, 2)
    h2 = _rescale(h2)
    r2 = R_of(h2)
    print("fine init N=%d R=%.9f (base %.9f, diff %.2e)" %
          (h2.size, r2, baseR, r2 - baseR))

    bestH = h2.copy()
    bestR = r2
    experiment_best = h2.copy()
    experiment_bestR = r2

    # Initial global log passes with beta schedule
    for beta in (0.0, 1e3, 1e4):
