    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _mass_downsample(h, N0):
    n = h.size
    if n <= N0:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0, n, N0 + 1)
    out = np.empty(N0)
    for k in range(N0):
        lo = edges[k]; hi = edges[k + 1]
        ilo = int(np.floor(lo)); ihi = int(np.floor(hi))
        if ihi <= ilo:
            out[k] = 0.0
            continue
        val = c[ihi] - c[ilo]
        val -= (lo - ilo) * h[ilo]
        if ihi < n:
            val -= (ihi - hi) * h[ihi]
        out[k] = max(val, 0.0)
    return out


def _prolong2(h):
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h * 0.5
    out[1::2] = h * 0.5
    return out


def _restrict(h, m):
    n = h.size
    if m <= 1:
        return h.copy()
    nr = (n + m - 1) // m
    pad = nr * m - n
    hh = np.concatenate((h, np.zeros(pad))) if pad > 0 else h
    return hh.reshape(nr, m).sum(axis=1)


def _prolong(hc, n):
    nr = hc.size
    m = (n + nr - 1) // nr
    out = np.repeat(hc / m, m)
    if out.size > n:
        out = out[:n]
    elif out.size < n:
        out = np.concatenate((out, np.zeros(n - out.size)))
    return out


def _vcycle(h_best, deadline):
    n = h_best.size
    m = 4
    hc = _rescale(_restrict(h_best, m))
    best_hc = hc.copy()
    best_cR = R_of(_prolong(best_hc, n))
    coarse_deadline = min(deadline, time.process_time() + 3.0)
    for beta in (2.0, 5.0, 10.0, 25.0, 50.0, 100.0):
        if time.process_time() >= coarse_deadline - 0.3:
            break
        cap = min(coarse_deadline, time.process_time() + 1.0)
        hc2 = _lbfgs_log(best_hc, 120, cap, beta=beta)
        cR = R_of(_prolong(hc2, n))
        if cR > best_cR + 1e-13:
            best_hc, best_cR = hc2, cR
    fine_res = h_best - _prolong(_restrict(h_best, m), n)
    cand = _rescale(np.clip(_prolong(best_hc, n) + fine_res, 0, None))
    return cand, best_cR, R_of(cand)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Primary workhorse: sharp full-vector polish + peak blocks ----
    # The start is already near-optimal; the biggest wins come from long,
    # careful sharp-max L-BFGS runs rather than coarse V-cycles.
    rng = np.random.default_rng(2024)
    loop_end = deadline - 0.5

    # First: a long sharp polish directly on start (most valuable use of time).
    if time.process_time() < loop_end - 2.0:
        cap = min(loop_end, time.process_time() + 8.0)
        hs = _lbfgs_log(bestH, 400, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  sharp polish R=%.7f" % bestRH)

    # Then: one V-cycle for a structural shake-up.
    if time.process_time() < loop_end - 8.0:
        vc_deadline = min(loop_end, time.process_time() + 10.0)
        cand, coarseR, candR = _vcycle(bestH, vc_deadline)
        polished, polR = cand, candR
        if time.process_time() < vc_deadline - 0.5:
            cap = min(vc_deadline, time.process_time() + 3.0)
            hs = _lbfgs_log(cand, 300, cap, beta=0.0)
            rs = R_of(hs)
            if rs > polR + 1e-13:
                polished, polR = hs, rs
        print("V-cycle coarseR=%.7f candR=%.7f polishR=%.7f" %
              (coarseR, candR, polR))
        if polR > bestRH + 1e-13:
            bestH, bestRH = polished.copy(), polR
            print("  NEW BEST R=%.7f" % bestRH)

    # ---- Leftover: alternate sharp full polish and peak-block polish ----
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        if time.process_time() < loop_end - 1.0:
            cap = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(bestH, 250, cap, beta=0.0)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
                improved = True
        if time.process_time() < loop_end - 1.0:
            frac = float(rng.choice([0.02, 0.05, 0.10]))
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
        if improved:
            print("  iter=%d R=%.7f" % (it, bestRH))

    print("final R=%.7f (best of experiment)" % bestRH)

    if bestRH > start_bestR + 1e-12:
        best, bestR = bestH.copy(), bestRH
    else:
        best, bestR = start_best, start_bestR

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _resample(h, delta, factor=2):
    n = h.size
    m = n * factor
    i = np.arange(m, dtype=float)
    t = (i + delta) / factor
    return np.interp(t, np.arange(n, dtype=float), h, left=0.0, right=0.0)


def _schedule(h, deadline, full_iters=800):
    h = _rescale(h)
    r = R_of(h)
    best, bestR = h.copy(), r

    hh = _lbfgs_log(h, full_iters, deadline)
    rr = R_of(hh)
    if rr > bestR:
        best, bestR = hh.copy(), rr

    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 6.0:
            break
        hb = _lbfgs_log(best, 250, deadline, beta=beta)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb.copy(), rb
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 5.0:
                break
            hp = _window_polish_peak(best, deadline, frac, 32,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR:
                best, bestR = hp.copy(), rp

    for _ in range(2):
        if time.process_time() >= deadline - 3.0:
            break
        hf = _lbfgs_log(best, 400, deadline)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf.copy(), rf

    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (baseR, base.size, 100.0 * np.mean(base <= 0)))

    # Multi-resolution: try upsampled variants at several factors/offsets,
    # plus direct polish of base.  Each is a fresh line of the search.
    candidates = [("base", base)]

    # Upsampled versions (finer grid can locally improve the maximum region).
    for factor in (2, 3):
        for delta in (0.0, 0.5):
            if time.process_time() >= deadline - 12.0:
                break
            cand = _resample(base, delta, factor=factor)
            cand = _rescale(cand)
            candidates.append(("up%d_%.2f" % (factor, delta), cand))

    # Downsampled version (coarser grid: fewer params, easier to escape).
    if base.size > 2000:
        dn = base[::2].copy()
        if dn.sum() > 0:
            candidates.append(("down2", _rescale(dn)))

    best = base.copy()
    bestR = baseR
    best_tag = None
    alt_best = None
    alt_bestR = -1.0

    for tag, cand in candidates:
        if time.process_time() >= deadline - 8.0:
            break
        r0 = R_of(cand)
        h, r = _schedule(cand, deadline)
        print("%s R0=%.7f -> R=%.7f (n=%d)" % (tag, r0, r, h.size))
        if r > bestR + 1e-13:
            # If size differs from start, we have a genuinely new construction.
            if h.size != base.size:
                if r > alt_bestR:
                    alt_best, alt_bestR = h.copy(), r
            best, bestR, best_tag = h.copy(), r, tag
        else:
            if h.size != base.size and r > alt_bestR:
                alt_best, alt_bestR = h.copy(), r

    # Iterate polishes on the best until deadline: full + peak windows.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  loop full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  loop peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%, tag=%s)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), best_tag))

    if bestR > start_bestR + 1e-12:
        return best
    if alt_best is not None and alt_bestR > start_bestR - 1e-6:
        return {"best": start_best, "alternative": alt_best}
    return start_best

