    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---- Mass transfer using cheap linearized change of R ---------------------
def _mass_transfer_batch(h, bestR, rng, n_trials, eta_list):
    n = h.size
    L = _knots(h)
    m = int(np.argmax(L))
    k = m - 1
    if k < 0 or k > 2 * n - 2:
        return h, bestR, False
    lo = max(0, k - n + 1)
    hi = min(n - 1, k)
    if hi <= lo:
        return h, bestR, False
    idx = np.arange(lo, hi + 1)
    c = h[idx] * h[k - idx]
    top_c = np.argsort(-c)[:min(80, c.size)]
    src_pool = idx[top_c]
    src_pool = src_pool[h[src_pool] > 0]
    if src_pool.size == 0:
        return h, bestR, False

    hj = h[k - idx]
    low = np.argsort(hj)[:min(80, hj.size)]
    dst_pool = idx[low]
    dst_pool = dst_pool[h[dst_pool] >= 0]
    if dst_pool.size == 0:
        return h, bestR, False

    best_gain = 1e-13
    best_move = None
    best_newR = bestR
    for _ in range(n_trials):
        i = int(src_pool[rng.integers(src_pool.size)])
        j = int(dst_pool[rng.integers(dst_pool.size)])
        if i == j:
            continue
        eta = eta_list[rng.integers(len(eta_list))]
        delta = eta * h[i]
        if delta <= 0:
            continue
        h_new = h.copy()
        h_new[i] = max(0.0, h_new[i] - delta)
        h_new[j] += delta
        r_new = R_of(h_new)
        if r_new > bestR + best_gain:
            best_gain = r_new - bestR
            best_move = (i, j, delta)
            best_newR = r_new
    if best_move is None:
        return h, bestR, False
    i, j, delta = best_move
    h2 = h.copy()
    h2[i] = max(0.0, h2[i] - delta)
    h2[j] += delta
    return h2, best_newR, True


# ---- Upsampling: refine the shape onto a finer grid -----------------------
def _upsample(h, factor):
    n = h.size
    m = n * factor
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(m) + 0.5) / m
    return np.interp(x_new, x_old, h)


def _smooth(h, w):
    if w <= 1:
        return h
    ker = np.ones(w) / w
    return np.convolve(h, ker, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    start_best = None
    start_bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)

    rng = np.random.default_rng(int(t0 * 1e6) & 0xFFFFFFFF)

    # Candidate A: refine the current start on a finer grid, then optimize.
    bestH = start_best.copy() if start_best is not None else None
    bestRH = start_bestR

    if start_best is not None:
        print("base R=%.9f (N=%d)" % (start_bestR, start_best.size))

    # Try a few upsampling factors and smoothings; keep whichever improves.
    if start_best is not None and time.process_time() < deadline - 20.0:
        for factor in (2, 3):
            if time.process_time() > deadline - 18.0:
                break
            up = _upsample(start_best, factor)
            up = _rescale(up)
            r_up = R_of(up)
            if r_up > bestRH + 1e-9:
                # brief polish
                hs = _lbfgs_log(up, 200, min(deadline - 15.0,
                                             time.process_time() + 4.0), beta=0.0)
                rs = R_of(hs)
                if rs > bestRH + 1e-9:
                    bestH, bestRH = hs, rs
                    print("  upsample x%d R=%.9f" % (factor, bestRH))

    if bestH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        bestH = _rescale(h)
        bestRH = R_of(bestH)

    # Mass-transfer search loop
    eta_list = np.array([0.3, 0.15, 0.07, 0.03, 0.015, 0.007])
    search_end = deadline - 5.0
    if search_end <= time.process_time():
        search_end = deadline - 0.5

    last_polish = time.process_time()
    it = 0
    n_trials = 20
    while time.process_time() < search_end:
        it += 1
        h2, r2, improved = _mass_transfer_batch(bestH, bestRH, rng, n_trials, eta_list)
        if improved:
            bestH, bestRH = h2, r2
            if it % 25 == 0:
                print("  MT iter=%d R=%.9f" % (it, bestRH))
            if time.process_time() - last_polish > 5.0:
                hs = _lbfgs_log(bestH, 150, min(search_end, time.process_time() + 2.5), beta=0.0)
                rs = R_of(hs)
                if rs > bestRH + 1e-13:
                    bestH, bestRH = hs, rs
                    print("  MT polish R=%.9f" % bestRH)
                last_polish = time.process_time()
        else:
            if n_trials > 4:
                n_trials = max(4, n_trials - 2)
            hs = _lbfgs_log(bestH, 120, min(search_end, time.process_time() + 2.0), beta=0.0)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs, rs
                print("  MT stall polish R=%.9f" % bestRH)
                n_trials = 20
            last_polish = time.process_time()
    print("mass-transfer done: it=%d R=%.9f" % (it, bestRH))

    # Final polish: log-LBFGS + beta smoothing + peak window
    loop_end = deadline - 0.4
    if time.process_time() < loop_end - 2.0:
        hs = _lbfgs_log(bestH, 400, min(loop_end, time.process_time() + 5.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs, rs
            print("  final log R=%.9f" % bestRH)
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= loop_end - 1.5:
            break
        hs = _lbfgs_log(bestH, 150, min(loop_end, time.process_time() + 3.0), beta=beta)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs, rs
            print("  final beta=%.0e R=%.9f" % (beta, bestRH))
    for frac in (0.04, 0.08, 0.15, 0.25):
        if time.process_time() >= loop_end - 1.0:
            break
        free = _peak_window(bestH, frac=frac)
        hp = _lbfgs_block(bestH, free, 200, min(loop_end, time.process_time() + 3.0), beta=0.0)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp, rp
            print("  final peak frac=%.2f R=%.9f" % (frac, bestRH))

    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if start_best is None:
        return bestH
    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _build_basis(n, p=64):
    """Gaussian-smoothed block indicators, each normalized to max|v|=1."""
    block = max(1, n // p)
    idx = np.arange(n, dtype=float)
    V = np.zeros((p, n))
    sigma = 1.5 * block
    for i in range(p):
        c = (i + 0.5) * block
        v = np.exp(-0.5 * ((idx - c) / sigma) ** 2)
        m = np.max(np.abs(v))
        if m > 0:
            v /= m
        V[i] = v
    return V


def _grad_R(h):
    """Gradient of R (not log) w.r.t. h, using analytic formula scaled."""
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if num <= 0 or Lm <= 0:
        return np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    # grad is d(-log R)/dh; dR/dh = -R * grad
    R = num / (s * s * Lm)
    return -R * grad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR

    # ---- Reduced Hessian in smooth block-scaling subspace ----
    h0 = baseH.copy()
    n = h0.size
    p = 64
    V = _build_basis(n, p)

    # Project out scaling direction: subtract component along h0
    hnorm2 = np.dot(h0, h0)
    if hnorm2 > 0:
        for i in range(p):
            V[i] = V[i] - (np.dot(V[i], h0) / hnorm2) * h0
    # renormalize each to max|v|=1
    for i in range(p):
        m = np.max(np.abs(V[i]))
        if m > 0:
            V[i] /= m

    eps = 1e-5 * np.max(h0)
    if eps <= 0:
        eps = 1e-8

    def proj_grad(hh):
        g = _grad_R(hh)
        # project out scaling direction
        if hnorm2 > 0:
            g = g - (np.dot(g, h0) / hnorm2) * h0
        return V @ g

    G0 = proj_grad(h0)
    H = np.zeros((p, p))
    try:
        for j in range(p):
            if time.process_time() > deadline - 20.0:
                break
            hp = h0 + eps * V[j]
            hm = h0 - eps * V[j]
            hp = np.clip(hp, 0, None)
            hm = np.clip(hm, 0, None)
            Gp = proj_grad(hp)
            Gm = proj_grad(hm)
            H[:, j] = (Gp - Gm) / (2.0 * eps)
    except Exception:
        pass
    H = 0.5 * (H + H.T)
    try:
        evals, evecs = np.linalg.eigh(H)
    except Exception:
        evals = np.zeros(p)
        evecs = np.eye(p)
    print("reduced Hessian smallest eigenvalues: %s" %
          np.array2string(evals[:5], precision=4))

    # ordering: most negative first, then smallest |lambda|
    order = list(np.argsort(evals))  # ascending: most negative first
    # add smallest |lambda| directions
    abs_order = list(np.argsort(np.abs(evals)))
    seen = set(order[:4])
    extra = [i for i in abs_order if i not in seen][:2]
    dirs = order[:4] + extra

    ladder = [1e-3, 1e-2, 3e-2, 1e-1, 3e-1, 1.0]
    signed = []
    for t in ladder:
        signed.append(t)
        signed.append(-t)

    def try_direction(d_vec, label):
        nonlocal bestH, bestR
        w = V.T @ d_vec
        mw = np.max(np.abs(w))
        if mw <= 0:
            return
        w = w / mw
        results = []
        for t in signed:
            if time.process_time() > deadline - 8.0:
                break
            hc = np.clip(h0 * np.exp(t * w), 0, None)
            if hc.sum() <= 0:
                continue
            hc = _rescale(hc)
            rc = R_of(hc)
            results.append((rc, t, hc))
        if not results:
            return
        results.sort(key=lambda x: -x[0])
        print("  dir %s best t=%.3e R=%.9f" % (label, results[0][1], results[0][0]))
        # polish top 4
        for rc, t, hc in results[:4]:
            if time.process_time() > deadline - 5.0:
                break
            cap = min(deadline - 3.0, time.process_time() + 3.0)
            hp = _lbfgs_log(hc, 60, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("    polished dir %s -> R=%.9f" % (label, bestR))

    for k, di in enumerate(dirs):
        if time.process_time() > deadline - 10.0:
            break
        try_direction(evecs[:, di], "eig%d" % k)

    # ---- Random combinations of the 4 eigen-directions ----
    rng = np.random.RandomState(12345)
    top4 = order[:4]
    for rnd in range(6):
        if time.process_time() > deadline - 6.0:
            break
        coeffs = rng.randn(len(top4))
        d = np.zeros(p)
        for c, di in zip(coeffs, top4):
            d[di] += c
        w = V.T @ d
        mw = np.max(np.abs(w))
        if mw <= 0:
            continue
        w = w / mw
        t = signed[rng.randint(len(signed))]
        hc = np.clip(h0 * np.exp(t * w), 0, None)
        if hc.sum() <= 0:
            continue
        hc = _rescale(hc)
        cap = min(deadline - 4.0, time.process_time() + 3.0)
        hp = _lbfgs_log(hc, 60, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            print("  rand rnd=%d t=%.3e -> R=%.9f" % (rnd, t, bestR))

    # ---- Finish: sharp global polish + peak-window polish ----
    if time.process_time() < deadline - 3.0:
        cap = min(deadline - 1.5, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 150, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  final global -> R=%.9f" % bestR)

    if time.process_time() < deadline - 2.0:
        free = _peak_window(bestH, frac=0.05)
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            print("  final peak -> R=%.9f" % bestR)

    mx, m, near = _stats(bestH)
    print("final N=%d zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))
    print("final exact R=%.9f (base %.9f)" % (bestR, baseR))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _upsample(h, factor):
    """Upsample by linear interpolation to `factor` times the length."""
    n = h.size
    m = n * factor
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(m) + 0.5) / m
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and np.all(np.isfinite(s)):
            best_h = s.copy()
            best_R = R_of(s)

    rng = np.random.default_rng(2024)

    # If start exists, try to directly improve it at its own resolution with
    # beta-smoothed objective to push down competing peaks, then sharpen.
    if best_h is not None:
        h = best_h.copy()
        # beta continuation: large beta -> sharp max, small beta -> soft
        for beta in (200.0, 80.0, 30.0, 10.0, 3.0, 1.0, 0.0):
            if time.process_time() > deadline - 2.0:
                break
            sub_deadline = min(deadline, time.process_time() + max(
                1.0, (deadline - time.process_time()) * 0.12))
            h2 = _lbfgs_log(h, 400, sub_deadline, beta=beta)
            r2 = R_of(h2)
            if r2 > R_of(h):
                h = h2
        if R_of(h) > best_R:
            best_R = R_of(h)
            best_h = h.copy()

    # Resolution ladder: refine at increasing N. Each rung: upsample, then
    # optimize with local windows near peak, then global L-BFGS polish.
    schedule = [1024, 2048, 4096, 8192, 16384, 32768, 65536, 131072]
    for target_n in schedule:
        if time.process_time() > deadline - 3.0:
            break
        cur_n = best_h.size if best_h is not None else 0
        if cur_n == 0:
            # no start: seed with a broad bump
            x = np.linspace(0, 1, target_n)
            h = np.exp(-((x - 0.5) ** 2) / 0.05) + 0.1
        elif cur_n < target_n:
            factor = target_n // cur_n
            if factor < 2:
                factor = 2
            h = _upsample(best_h, factor)
            target_n = h.size
        else:
            h = best_h.copy()
        # local budget for this rung
        remain = deadline - time.process_time()
        rung_end = time.process_time() + max(2.0, remain * 0.35)
        # 1) windowed optimization around peak
        win = _peak_window(h, frac=0.15)
        h = _lbfgs_block(h, win, 300, rung_end)
        # 2) a couple of alternate windows (flanks) to deepen shoulder
        Lf = _knots(h)
        m = int(np.argmax(Lf))
        n = h.size
        for shift in (-0.25, 0.25):
            if time.process_time() > rung_end:
                break
            c = int(m + shift * n)
            half = max(16, int(0.12 * n))
            lo = max(0, c - half); hi = min(n, c + half)
            h = _lbfgs_block(h, np.arange(lo, hi), 200, rung_end)
        # 3) global polish with soft-max beta continuation
        for beta in (30.0, 10.0, 3.0, 0.0):
            if time.process_time() > rung_end:
                break
            h2 = _lbfgs_log(h, 200, rung_end, beta=beta)
            if R_of(h2) >= R_of(h):
                h = h2
        r = R_of(h)
        if r > best_R:
            best_R = r
            best_h = h.copy()

    # Final: if time remains, try a couple of random restarts at moderate N
    while time.process_time() < deadline - 1.0:
        n = best_h.size if best_h is not None else 2048
        n = min(n, 16384)
        h = best_h.copy() if best_h is not None else np.ones(n)
        if h.size != n:
            h = _upsample(h, max(1, n // h.size)) if h.size < n else _coarsen(h)
        # random multiplicative perturbation in ~64 blocks
        nb = 64
        cell = max(1, h.size // nb)
        for c in range(0, h.size, cell):
            h[c:c + cell] *= np.exp(rng.normal(0, 0.15))
        h = np.maximum(h, 1e-9)
        h2 = _lbfgs_log(h, 200, deadline - 0.5)
        r = R_of(h2)
        if r > best_R:
            best_R = r
            best_h = h2.copy()
        else:
            break

    if best_h is None:
        best_h = np.ones(50)

    best_R = R_of(best_h)
    print(f"R={best_R:.6f} N={best_h.size} max/mean={best_h.max()/best_h.mean():.2f} "
          f"zero_frac={np.mean(best_h < 1e-12):.3f}")
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _gauss_smooth(h, sigma=1.5):
    r = 3
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    hp = np.concatenate((np.full(r, h[0]), h, np.full(r, h[-1])))
    return np.convolve(hp, k, mode='valid')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # NEW IDEA: full-grid L-BFGS polish in the *height* space, followed by
    # a peak-window polish, repeatedly. The original p0404 spent most of its
    # time in beta-homotopy; here we get real gains from direct hard-max
    # optimization at full resolution, then targeted peak-window refinement.
    # Alternate between these until no improvement.

    def full_polish(h, maxiter=800):
        return _lbfgs_log(h, maxiter, deadline)

    def peak_polish(h, frac=0.25, extra=32, maxiter=400):
        return _window_polish_peak(h, deadline, frac, extra, maxiter=maxiter)

    # Initial full optimization
    h = full_polish(best, 1500)
    r = R_of(h)
    if r > bestR + 1e-15:
        best, bestR = h, r
    print("full0 R=%.9f" % bestR)

    # Alternate full + peak polish
    stall = 0
    it = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        it += 1
        improved = False

        # peak window polish (small targeted block)
        if time.process_time() < deadline - 3.0:
            h = peak_polish(best, frac=0.20, extra=24, maxiter=300)
            r = R_of(h)
            if r > bestR + 1e-14:
                best, bestR = h, r
                improved = True

        # full polish
        if time.process_time() < deadline - 2.0:
            h = full_polish(best, 800)
            r = R_of(h)
            if r > bestR + 1e-14:
                best, bestR = h, r
                improved = True

        if improved:
            stall = 0
            print("iter%d R=%.9f" % (it, bestR))
        else:
            stall += 1

    # Upsample-and-anneal: on 2x grid, run full + peak polish, compress back.
    N0 = best.size
    if time.process_time() < deadline - 8.0 and N0 * 2 <= 1000000:
        hp = _prolongate(best, N0 * 2)
        hp = _rescale(hp)
        # Smooth a little to avoid aliasing
        hp = _gauss_smooth(hp, sigma=1.0)
        hp = _rescale(hp)
        hp = full_polish(hp, 500)
        hp = peak_polish(hp, frac=0.15, extra=32, maxiter=300)
        r = R_of(hp)
        print("up2x R=%.9f" % r)
        if r > bestR + 1e-15:
            best, bestR = hp, r
        # compress back
        if time.process_time() < deadline - 4.0:
            hc = _coarse(best, N0)
            hc = _rescale(hc)
            hc = full_polish(hc, 400)
            hc = peak_polish(hc, frac=0.20, extra=24, maxiter=300)
            r = R_of(hc)
            print("compress R=%.9f" % r)
            if r > bestR + 1e-15:
                best, bestR = hc, r

    # Phase exploration
    for delta in (-0.5, 0.5):
        if time.process_time() >= deadline - 4.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = full_polish(hp, 400)
        r = R_of(hp)
        print("phase %+.2f R=%.9f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Final alternating polish until deadline
    stall = 0
    while time.process_time() < deadline - 1.0 and stall < 2:
        improved = False
        h = full_polish(best, 800)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("final full R=%.9f" % bestR)
        if time.process_time() >= deadline - 3.0:
            break
        h = peak_polish(best, frac=0.15, extra=32, maxiter=300)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("final peak R=%.9f" % bestR)
        if not improved:
            stall += 1

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 4000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 4000:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, active_mask=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if active_mask is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.flatnonzero(active_mask)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_sm(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400,
            beta=0.0):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_line(h, r, deadline, tag, do_print=True):
    """Aggressively polish a single construction with all tools until deadline."""
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r,
                           fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if r2 > r:
            h, r = cand, r2
        cand = _lbfgs_sm(h, 4096, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        if do_print:
            print("  %s R=%.6f" % (tag, r))
    return h, r


def _shift_perturb(h, shift_fracs, deadline, rcur):
    """Roll the array by a fraction of its length and reoptimize.

    Breaking the exact symmetry of the peak region is the key escape move:
    a symmetric autocorrelation peak is a stationary trap, a slightly
    shifted support is not.
    """
    n = h.size
    best_h, best_r = h, rcur
    for frac in shift_fracs:
        if time.process_time() >= deadline - 1.5:
            break
        sh = int(round(frac * n))
        if sh == 0:
            continue
        cand = np.roll(h, sh)
        cand = _rescale(cand)
        cand2 = _lbfgs_log(cand, maxiter=200, deadline=deadline)
        r2 = R_of(cand2)
        if r2 > best_r:
            best_h, best_r = cand2, r2
    return best_h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best, best_r = None, -1.0
    fresh, fresh_r = None, -1.0

    if start_arr is not None:
        s_hi = start_arr
        if s_hi.size < 65536:
            s_hi = _rescale(_prolong(s_hi, 65536))
        s_r = R_of(s_hi)
        print("start base R=%.6f N=%d" % (s_r, s_hi.size))
        split = t0 + 0.55 * (deadline - t0)
        s_hi, s_r = _refine_line(s_hi, s_r, split, "start-refine")
        best, best_r = s_hi, s_r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

        # NEW: symmetry-breaking via fractional shifts of the support,
        # then re-optimize from each shifted copy.
        if time.process_time() < deadline - 8.0:
            sh_deadline = deadline - 0.45 * (deadline - time.process_time())
            cand, r2 = _shift_perturb(
                best,
                (0.002, -0.002, 0.005, -0.005, 0.012, -0.012),
                sh_deadline, best_r)
            if r2 > best_r:
                cand, r2 = _refine_line(cand, r2, sh_deadline, "shift-refine")
                if r2 > best_r:
                    best, best_r = cand, r2
                    print("shift improved R=%.6f" % best_r)

    if time.process_time() < deadline - 6.0:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        h = _rescale(h)
        cur_r = R_of(h)
        betas = (8, 32, 128, 512, 2048)
        N = N0
        while N <= 65536 and time.process_time() < deadline - 4.0:
            cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                h, cur_r = cand, r
            cand, r = _homotopy(h, betas, 150, deadline)
            if r > cur_r:
                h, cur_r = cand, r
            if N >= 65536:
                break
            N = min(N * 2, 65536)
            h = _rescale(_prolong(h, N))
            cur_r = R_of(h)
        fresh, fresh_r = h, cur_r
        print("fresh R=%.6f" % fresh_r)

    # Spend remaining time refining whichever is best.
    if time.process_time() < deadline - 1.5:
        if fresh is not None and fresh_r > best_r:
            fresh, fresh_r = _refine_line(fresh, fresh_r, deadline, "fresh")
        elif best is not None:
            best, best_r = _refine_line(best, best_r, deadline, "final")

    if fresh is not None and fresh_r > best_r:
        best, best_r = fresh, fresh_r
    if best is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None and start_r >= best_r:
        alt = fresh if (fresh is not None and fresh_r > 0) else None
        if alt is not None and not np.array_equal(alt, start_arr):
            return {"best": _rescale(start_arr), "alternative": _rescale(alt)}
        return _rescale(start_arr)

    if start_arr is not None:
        return {"best": _rescale(best), "alternative": _rescale(start_arr)}
    return _rescale(best)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _cycle(cur, cur_R, best, best_R, deadline, betas, peak_fracs):
    for beta in betas:
        if time.process_time() >= deadline:
            break
        cand = _lbfgs_log(cur, 200, deadline, beta=beta)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand
            cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy()
                best_R = r
    for frac in peak_fracs:
        if time.process_time() >= deadline:
            break
        free = _peak_window(cur, frac=frac)
        cand = _lbfgs_block(cur, free, 200, deadline)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand
            cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy()
                best_R = r
    return cur, cur_R, best, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            best_R = R_of(best)

    if best is None:
        best = np.ones(1024)
        best_R = R_of(best)

    cur = best.copy()
    cur_R = best_R

    # Ensure we are at N=32768 to start.
    if len(cur) < 32768:
        cand = _prolong(cur, 32768)
        cand = _lbfgs_log(cand, 200, deadline)
        r = R_of(cand)
        if r > cur_R:
            cur = cand
            cur_R = r
            if r > best_R:
                best = cand.copy()
                best_R = r

    betas = [1e3, 1e4, 1e5, 1e6, 1e7]
    peak_fracs = [0.02, 0.05, 0.1, 0.2]

    cycle = 0
    no_improve = 0
    prolonged = False
    prev_R = cur_R

    while time.process_time() < deadline - 0.5:
        cycle += 1
        cur, cur_R, best, best_R = _cycle(cur, cur_R, best, best_R,
                                          deadline, betas, peak_fracs)
        gain = cur_R - prev_R
        prev_R = cur_R
        print(f"cycle {cycle} N={len(cur)} cur={cur_R:.6f} best={best_R:.6f} gain={gain:.2e}")

        if gain > 1e-6:
            no_improve = 0
        else:
            no_improve += 1

        # Prolongate once if two consecutive cycles fail to improve.
        if (not prolonged) and no_improve >= 2 and len(cur) < 65536:
            if time.process_time() < deadline - 3.0:
                cand = _prolong(cur, 65536)
                cand = _rescale(cand)
                r = R_of(cand)
                if r > cur_R - 1e-9:
                    cur = cand
                    cur_R = r
                    if r > best_R:
                        best = cand.copy()
                        best_R = r
                prolonged = True
                prev_R = cur_R
                no_improve = 0
                print(f"prolongated to N={len(cur)} R={cur_R:.6f}")

        # Sharp global polish at start of each cycle after prolongation.
        if prolonged and time.process_time() < deadline - 1.0:
            cand = _lbfgs_log(cur, 200, deadline, beta=0.0)
            r = R_of(cand)
            if r > cur_R + 1e-12:
                cur = cand
                cur_R = r
                if r > best_R + 1e-12:
                    best = cand.copy()
                    best_R = r

        if time.process_time() - t0 > budget_seconds * 0.9:
            break

    # Spend remaining time on a sharp full polish at largest N reached.
    if time.process_time() < deadline:
        cand = _lbfgs_log(best, 600, deadline, beta=0.0)
        r = R_of(cand)
        if r > best_R:
            best = cand
            best_R = r

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={best_R:.6f} N={len(best)}")

    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_R = R_of(s)

    if best_R >= start_R:
        return best
    return {"best": np.asarray(start, dtype=float), "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolong(h):
    return np.repeat(h, 2)


def _perturb(h, sigma, rng):
    h = h.copy()
    mean = h.mean()
    mask = h > mean
    if mask.any():
        noise = np.exp(rng.normal(0.0, sigma, size=mask.sum()))
        h[mask] *= noise
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.RandomState(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    experiment_best = baseH.copy()
    experiment_bestR = baseR

    # ---- Stage 1: coarsen by 2x repeatedly, 7 times -> N/128
    hc = bestH.copy()
    levels = []
    for _ in range(7):
        if hc.size < 2:
            break
        hc = _coarsen(hc)
        levels.append(hc.size)
    coarseR = R_of(hc)
    print("coarsened to N=%d R=%.9f (should equal %.9f)" % (hc.size, coarseR, bestR))

    # ---- Stage 2: multi-start at coarse level
    coarse_best = hc.copy()
    coarse_bestR = coarseR
    candidates = [(coarseR, hc.copy())]
    n_restarts = 12
    for k in range(1, n_restarts):
        if time.process_time() >= deadline - 20.0:
            break
        sigma = 0.1 + 0.4 * rng.random()
        hstart = _perturb(hc, sigma, rng)
        # beta ladder
        cur = hstart
        for beta in (0.0, 1e2, 1e3):
            cap = min(deadline - 18.0, time.process_time() + 1.5)
            if time.process_time() >= cap - 0.3:
                break
            cur = _lbfgs_log(cur, 100, cap, beta=beta)
        r = R_of(cur)
        candidates.append((r, cur.copy()))
        if r > coarse_bestR + 1e-14:
            coarse_best, coarse_bestR = cur.copy(), r
            print("  coarse restart %d sigma=%.2f R=%.9f" % (k, sigma, r))

    candidates.sort(key=lambda x: -x[0])
    top = []
    for r, h in candidates[:6]:
        # distinctness check
        dup = False
        for r2, h2 in top:
            if h.size == h2.size and np.max(np.abs(h - h2)) < 1e-6 * (h.max() + 1e-30):
                dup = True
                break
        if not dup:
            top.append((r, h))
        if len(top) >= 3:
            break
    print("coarse-best R=%.9f (record coarse %.9f) top=%d" %
          (coarse_bestR, bestR, len(top)))

    # ---- Stage 3: prolongate each top candidate up to fine level
    targetN = bestH.size
    level_results = []
    for ci, (r0, h0) in enumerate(top):
        if time.process_time() >= deadline - 12.0:
            break
        h = h0.copy()
        while h.size < targetN:
            h = _prolong(h)
            if h.size > targetN:
                # trim to target
                h = h[:targetN]
            # sharp polish
            cap = min(deadline - 10.0, time.process_time() + 1.5)
            if time.process_time() < cap - 0.3:
                h = _lbfgs_log(h, 50, cap, beta=0.0)
            # peak-window polish
            if time.process_time() < deadline - 10.0:
                frac = 0.05 + 0.15 * rng.random()
                free = _peak_window(h, frac=frac)
                cap = min(deadline - 10.0, time.process_time() + 1.0)
                h = _lbfgs_block(h, free, 60, cap, beta=0.0)
            # small levels: perturbed restarts
            if h.size <= 10624 and time.process_time() < deadline - 10.0:
                best_local = h.copy()
                best_localR = R_of(h)
                for _ in range(6):
                    if time.process_time() >= deadline - 10.0:
                        break
                    sigma = 0.05 + 0.15 * rng.random()
                    hp = _perturb(h, sigma, rng)
                    cap = min(deadline - 10.0, time.process_time() + 0.8)
                    hp = _lbfgs_log(hp, 60, cap, beta=0.0)
                    rp = R_of(hp)
                    if rp > best_localR + 1e-14:
                        best_local, best_localR = hp.copy(), rp
                h = best_local
        r = R_of(h)
        level_results.append((r, h.copy()))
        print("  cand %d prolongated N=%d R=%.9f" % (ci, h.size, r))
        if r > bestR + 1e-14:
            bestH, bestR = h.copy(), r
            if bestR > experiment_bestR + 1e-14:
                experiment_best, experiment_bestR = bestH.copy(), bestR

    # ---- Stage 4: use remaining time on alternating polishes at fine level
    it = 0
    loop_end = deadline - 2.0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  iter=%d global R=%.9f" % (it, bestR))
            if bestR > experiment_bestR + 1e-14:
                experiment_best, experiment_bestR = bestH.copy(), bestR
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.07 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("  iter=%d peak frac=%.2f R=%.9f" % (it, frac, bestR))
                if bestR > experiment_bestR + 1e-14:
                    experiment_best, experiment_bestR = bestH.copy(), bestR

    mx, m, near = _stats(bestH)
    print("final N=%d zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d R=%.9f" %
          (bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near, bestR))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": experiment_best}
    else:
        return {"best": baseH, "alternative": experiment_best}

