    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cap(h, delta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    c = (1.0 - delta) * mx
    ramp = 0.1 * delta * c
    if ramp <= 0:
        w = (Lf < c).astype(float)
    else:
        w = np.clip((c - Lf) / ramp + 0.5, 0.0, 1.0)
    sw = np.sum(w * Lf)
    if sw <= 0:
        return _fun_grad(h)
    dLf = -w / sw
    grad = _backprop(dLf, h) + 2.0 / s
    val = -np.log(sw) + 2.0 * np.log(s)
    return val, grad


