            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    # Experiment: coarsen base by pairwise mean twice (exact 4x staircase)
    coarse = baseH
    ok = True
    for _ in range(2):
        if coarse.size % 2 == 1:
            ok = False
            break
        coarse = _coarsen(coarse)
    if ok:
        coarse = _rescale(coarse)
        rc = R_of(coarse)
        print("coarse N=%d R=%.12f (base %.12f, diff %.2e)" %
              (coarse.size, rc, baseR, rc - baseR))
        if abs(rc - baseR) > 1e-9:
