        h = h_start.copy()
        r = R_of(h)
        for delta in deltas:
            if time.process_time() >= time_cap - 0.3:
                break
            fg = (lambda hh, d=delta: _fun_grad_cap(hh, d))
            cap = min(time_cap, time.process_time() + 3.0)
            hs = _lbfgs_log(h, 120, cap, fg=fg)
            rs = R_of(hs)
            print("  delta=%.4f -> R=%.9f" % (delta, rs))
            if rs > r + 1e-14:
                h, r = hs.copy(), rs
        return h, r

    # Main schedule from coarse
    coarse_best, coarse_bestR = coarse.copy(), rc
    if time.process_time() < deadline - 5.0:
        cap = min(deadline - 4.0, time.process_time() + 8.0)
        h1, r1 = run_schedule(coarse, cap)
        if r1 > coarse_bestR + 1e-14:
