        noise = np.exp(sigma * rng.randn(n))
        hpert[mask] = hpert[mask] * noise[mask]
        hpert = _rescale(hpert)
        cap = min(deadline - 3.0, time.process_time() + 4.0)
        h2, r2 = run_schedule(hpert, cap)
        if r2 > coarse_bestR + 1e-14:
            coarse_best, coarse_bestR = h2.copy(), r2
            print("  perturb trial %d improved: R=%.9f" % (trial, coarse_bestR))

    # Upsample coarse best back to fine
    fine = _duplicate(coarse_best, 2)
    fine = _rescale(fine)
    fineR = R_of(fine)
    print("upsampled 2x N=%d R=%.9f" % (fine.size, fineR))

    bestH = fine.copy()
    bestR = fineR
    experiment_best = fine.copy()
    experiment_bestR = fineR

    if baseR > bestR:
        bestH, bestR = baseH.copy(), baseR

    # Beta ladder on fine
    for beta in (1e3, 1e4, 1e5, 1e6, 1e7):
        if time.process_time() >= deadline - 3.0:
            break
        cap = min(deadline - 2.0, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 150, cap, beta=beta)
        rs = R_of(hs)
        print("  beta=%.0e -> R=%.9f" % (beta, rs))
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            if bestR > experiment_bestR + 1e-14:
                experiment_best, experiment_bestR = bestH.copy(), bestR
        if time.process_time() < deadline - 2.0:
            free = _peak_window(bestH, frac=0.05)
            cap = min(deadline - 1.5, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 100, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                if bestR > experiment_bestR + 1e-14:
                    experiment_best, experiment_bestR = bestH.copy(), bestR

    # Final polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
