    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    n = h.size
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fun(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    return _lbfgs(h0, _fun_grad, maxiter, deadline)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    return _lbfgs(h0, lambda h: _fun_grad_sm(h, beta), maxiter, deadline)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _refine_full(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        for beta in (500.0, 200.0, 80.0, 30.0):
            if time.process_time() >= t_end - 0.5:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=1200, deadline=t_end)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=2000, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.2, 8, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _refine_block(h, deadline, time_slice, lo, hi, maxiter=800):
    """Refine only a block; used for fine local work."""
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    free = np.arange(lo, hi + 1)
    while time.process_time() < t_end - 0.3:
        cand = _lbfgs_block(cur, free, maxiter=maxiter, deadline=t_end)
        r = R_of(cand)
        if r > cur_r + 1e-14:
            cur, cur_r = cand, r
        else:
            break
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(987654321)

    if start_arr is None:
        # cold start: modest generic search
        N0 = 2048
        h = np.ones(N0)
        h = _lbfgs_log(h, maxiter=800, deadline=deadline)
        h = _window_polish_peak(h, deadline, 0.3, 16, maxiter=400)
        best, best_r = h, R_of(h)
        while time.process_time() < deadline - 0.5:
            cand, cand_r = _refine_full(best, deadline,
                                        time_slice=min(10.0, deadline - time.process_time() - 0.5))
            if cand_r > best_r:
                best, best_r = cand, cand_r
        return best

    cur = start_arr.copy()
    cur_r = best_r
    n = cur.size
    alternative = None
    alt_r = -1.0

    # Phase 1: full-vector refinement with smooth-max + exact + window.
    while time.process_time() < deadline - 1.0:
        slice_t = min(10.0, deadline - time.process_time() - 1.0)
        if slice_t <= 0.5:
            break
        cand, cand_r = _refine_full(cur, deadline, time_slice=slice_t)
        if cand_r > cur_r + 1e-12:
            cur, cur_r = cand, cand_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif cand_r > alt_r:
            alternative, alt_r = cand.copy(), cand_r
        if time.process_time() >= deadline - 1.0:
            break
        # small local block polish around peak region for fine gains
        lo, hi = _peak_region(cur)
        pad = max(8, (hi - lo))
        lo = max(0, lo - pad); hi = min(n - 1, hi + pad)
        cand, cand_r = _refine_block(cur, deadline, min(4.0, deadline - time.process_time() - 1.0),
                                     lo, hi, maxiter=800)
        if cand_r > cur_r + 1e-13:
            cur, cur_r = cand, cand_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif cand_r > alt_r:
            alternative, alt_r = cand.copy(), cand_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _prolongate(h, n_new):
    """Mass-conserving prolongation, rescaled. Fall back to repeat if R drifts."""
    r0 = R_of(h)
    cand = _prolong(h, n_new)
    cand = cand * (h.sum() / max(cand.sum(), 1e-300))
    cand = _rescale(cand)
    r1 = R_of(cand)
    if abs(r1 - r0) > 1e-6 * max(1.0, abs(r0)):
        # fall back to exact duplication
        rep = int(round(n_new / len(h)))
        if rep >= 1 and rep * len(h) == n_new:
            cand = np.repeat(h, rep)
        else:
            cand = _prolong(h, n_new)
        cand = _rescale(cand)
    return cand


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _cycle(cur, cur_R, best, best_R, deadline, betas, peak_fracs, sharp=True):
    for beta in betas:
        if time.process_time() >= deadline:
            break
        cand = _lbfgs_log(cur, 200, deadline, beta=beta)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand
            cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy()
                best_R = r
    for frac in peak_fracs:
        if time.process_time() >= deadline:
            break
        free = _peak_window(cur, frac=frac)
        cand = _lbfgs_block(cur, free, 200, deadline)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand
            cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy()
                best_R = r
    if sharp and time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(cur, 200, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand
            cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy()
                best_R = r
    return cur, cur_R, best, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            best_R = R_of(best)

    if best is None:
        best = np.ones(1024)
        best_R = R_of(best)

    cur = best.copy()
    cur_R = best_R

    # Ensure we are at N=32768 to start.
    if len(cur) < 32768:
        cand = _prolong(cur, 32768)
        cand = _lbfgs_log(cand, 200, deadline)
        r = R_of(cand)
        if r > cur_R:
            cur = cand
            cur_R = r
            if r > best_R:
                best = cand.copy()
                best_R = r
    elif len(cur) > 32768:
        # downsample-ish: just keep, but we prefer 32768; leave as is
        pass

    # (1) Two cycles at N=32768 with base ladder.
    betas32 = [1e3, 1e4, 1e5, 1e6, 1e7]
    fracs32 = [0.02, 0.05, 0.1, 0.2]
    for cyc in range(2):
        if time.process_time() >= deadline - 1.0:
            break
        cur, cur_R, best, best_R = _cycle(cur, cur_R, best, best_R,
                                          deadline, betas32, fracs32, sharp=False)
        print(f"cycle {cyc+1} N={len(cur)} cur={cur_R:.6f} best={best_R:.6f}")

    # (2) Unconditional prolongation to 65536 + sharp polish.
    if len(cur) < 65536 and time.process_time() < deadline - 3.0:
        cand = _prolongate(cur, 65536)
        cand = _lbfgs_log(cand, 200, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R - 1e-9:
            cur = cand
            cur_R = r
            if r > best_R:
                best = cand.copy()
                best_R = r
        print(f"prolongated to N={len(cur)} R={cur_R:.6f}")

    # (3) Cycles at 65536 with widened ladder.
    betas64 = [1e4, 1e5, 1e6, 1e7, 1e8]
    fracs64 = [0.01, 0.02, 0.05, 0.1]
    for cyc in range(5):
        if time.process_time() >= deadline - 1.0:
            break
        cur, cur_R, best, best_R = _cycle(cur, cur_R, best, best_R,
                                          deadline, betas64, fracs64, sharp=True)
        print(f"cycle64 {cyc+1} N={len(cur)} cur={cur_R:.6f} best={best_R:.6f}")

    # (4) If >12s remain after 3 cycles at 65536, prolongate to 131072.
    remaining = deadline - time.process_time()
    if remaining > 12.0 and len(cur) < 131072:
        cand = _prolongate(cur, 131072)
        cand = _lbfgs_log(cand, 200, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R - 1e-9:
            cur = cand
            cur_R = r
            if r > best_R:
                best = cand.copy()
                best_R = r
        print(f"prolongated to N={len(cur)} R={cur_R:.6f}")
        betas128 = [1e5, 1e6, 1e7, 1e8, 1e9]
        fracs128 = [0.01, 0.02, 0.05, 0.1]
        for cyc in range(2):
            if time.process_time() >= deadline - 1.0:
                break
            cur, cur_R, best, best_R = _cycle(cur, cur_R, best, best_R,
                                              deadline, betas128, fracs128, sharp=True)
            print(f"cycle128 {cyc+1} N={len(cur)} cur={cur_R:.6f} best={best_R:.6f}")

    # (5) Final sharp polish at largest N.
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(best, 600, deadline, beta=0.0)
        r = R_of(cand)
        if r > best_R:
            best = cand
            best_R = r

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={best_R:.6f} N={len(best)}")

    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_R = R_of(s)

    if best_R >= start_R:
        return best
    return {"best": np.asarray(start, dtype=float), "alternative": best}

