    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _edge_add(h, M, A, p, left, right):
    """Add A*(i+1)^(-p) on left prefix [0,M), A*(N-i)^(-p) on right suffix [N-M,N)."""
    n = h.size
    hh = h.copy()
    M = int(min(M, n))
    if M <= 0:
        return hh
    idx = np.arange(1, M + 1, dtype=float)
    if left:
        hh[:M] += A * idx ** (-p)
    if right:
        hh[n - M:] += A * (idx ** (-p))[::-1]
    return hh


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n = best.size
    nz = best[best > 0]
    m_mean = nz.mean() if nz.size > 0 else 1.0

    # Baseline edge knot diagnostics
    L0 = _knots(best)
    mxL = L0.max()
    print("  base edge knots rel: L[1:6]=%s L[-6:-1]=%s" % (
        np.round(L0[1:6] / mxL, 6), np.round(L0[-6:-1] / mxL, 6)))

    # Grid of edge candidates
    ps = [0.25, 0.5, 0.75]
    Ms = [int(round(f * n)) for f in (0.005, 0.01, 0.02, 0.05)]
    As = [0.2 * m_mean, 0.5 * m_mean, 1.0 * m_mean, 2.0 * m_mean]
    sides = [(True, False), (False, True), (True, True)]

    candidates = []  # (rawR, h)
    for p in ps:
        for M in Ms:
            for A in As:
                for (lft, rgt) in sides:
                    hh = _edge_add(best, M, A, p, lft, rgt)
                    hh = _rescale(hh)
                    r = R_of(hh)
                    candidates.append((r, hh, p, M, A, lft, rgt))
    candidates.sort(key=lambda t: -t[0])
    print("  grid built %d candidates; top raw R=%.9f" % (len(candidates), candidates[0][0]))
    for c in candidates[:6]:
        print("    raw R=%.9f p=%.2f M=%d A=%.3g L=%d R=%d" %
              (c[0], c[2], c[3], c[4], c[5], c[6]))

    experiment_best = best.copy()
    experiment_bestR = bestR

    # Polish top candidates
    top = candidates[:6]
    for i, (r, hh, p, M, A, lft, rgt) in enumerate(top):
        if time.process_time() >= deadline - 4.0:
            break
        cap_t = min(deadline - 2.0, time.process_time() + 6.0)
        hp, rp = _short_polish(hh, cap_t, r)
        print("  cand %d p=%.2f M=%d A=%.3g raw=%.9f polished=%.9f" %
              (i, p, M, A, r, rp))
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp
            print("    NEW EXPERIMENT BEST R=%.9f" % experiment_bestR)

    # Full polish of experiment best
    if experiment_bestR > start_bestR + 1e-13 and time.process_time() < deadline - 4.0:
        cap_t = min(deadline - 1.0, time.process_time() + 10.0)
        hp, rp = _polish(experiment_best, cap_t, experiment_bestR)
        if rp > experiment_bestR:
            experiment_best, experiment_bestR = hp, rp
            print("  after full polish R=%.9f" % experiment_bestR)

    # If nothing beat start, still try more aggressive edge additions with polish,
    # and also try adding edges then polishing the base itself.
    if experiment_bestR <= start_bestR + 1e-13:
        print("  no raw gain; trying polish-from-base with edge seeds")
        extra_idx = 6
        while time.process_time() < deadline - 4.0 and extra_idx < len(candidates):
            r, hh, p, M, A, lft, rgt = candidates[extra_idx]
            extra_idx += 1
            cap_t = min(deadline - 2.0, time.process_time() + 5.0)
            hp, rp = _short_polish(hh, cap_t, r)
            if rp > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hp.copy(), rp
                print("    extra cand R=%.9f (p=%.2f M=%d A=%.3g)" %
                      (experiment_bestR, p, M, A))

    # Final polish loop on experiment best
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(experiment_best, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, experiment_bestR))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(experiment_best, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(experiment_best, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, experiment_bestR))

    # Diagnostics on experiment best
    Lb = _knots(experiment_best)
    mxb = Lb.max()
    print("  exp edge knots rel: L[1:6]=%s L[-6:-1]=%s" % (
        np.round(Lb[1:6] / mxb, 6), np.round(Lb[-6:-1] / mxb, 6)))
    print("final R=%.9f (best of experiment)" % experiment_bestR)
    mx, m, near = _stats(experiment_best)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (experiment_bestR, experiment_best.size,
           100.0 * np.mean(experiment_best <= 0), mx, m, near))

    if experiment_bestR > start_bestR + 1e-12:
        return {"best": experiment_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


# ---- Fractional-shift resampling ----

def _shift_resample(h, delta):
    """Re-rasterise the same mass on nodes shifted by delta cells.
    Cumulative mass c on grid x_k = k/N; new cell j spans
    [(j+delta)/N, (j+1+delta)/N] in source coordinates."""
    n = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(n)
    c = c / total
    xs = np.arange(n + 1, dtype=float)  # source node coords 0..n
    # new node positions in source coords: k + delta for k=0..n
    newx = np.arange(n + 1, dtype=float) + delta
    newx = np.clip(newx, 0.0, float(n))
    cv = np.interp(newx, xs, c)
    out = np.diff(cv)
    out = np.clip(out, 0.0, None)
    return out


def _polish(h, deadline, budget):
    """Short beta ladder + peak-window polish. Returns (h, R)."""
    best = h.copy()
    bestR = R_of(best)
    for beta in (0.0, 1e3, 1e4):
        if time.process_time() >= deadline - 0.5:
            break
        cap = min(deadline - 0.3, time.process_time() + budget / 3.0)
        hs = _lbfgs_log(best, 150, cap, beta=beta)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            best, bestR = hs.copy(), rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.05)
        cap = min(deadline - 0.3, time.process_time() + budget / 3.0)
        hp = _lbfgs_block(best, free, 120, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp.copy(), rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    experiment_best = baseH.copy()
    experiment_bestR = baseR

    # ---- Fractional-shift scan ----
    deltas = [d * 0.1 for d in range(1, 10)]
    deltas = deltas + [-d for d in deltas]

    def scan_shifts(hcur, rcur, tag):
        raw = []
        for delta in deltas:
            hs = _shift_resample(hcur, delta)
            hs = _rescale(hs)
            rs = R_of(hs)
            raw.append((rs, delta, hs))
            print("  [%s] delta=%+.1f raw R=%.9f (delta %.2e)" %
                  (tag, delta, rs, rs - rcur))
        raw.sort(key=lambda t: -t[0])
        return raw

    # First scan from base
    raw = scan_shifts(bestH, bestR, "scan1")
    top = raw[:3]

    # Polish top-3 candidates
    for rs, delta, hs in top:
        if time.process_time() >= deadline - 3.0:
            break
        cap = min(deadline - 2.0, time.process_time() + 6.0)
        hp, rp = _polish(hs, cap, 6.0)
        print("  [polish1] delta=%+.1f raw=%.9f polished=%.9f" %
              (delta, rs, rp))
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            print("  shift improved: R=%.9f (delta %.2e)" %
                  (bestR, bestR - baseR))
        if rp > experiment_bestR + 1e-14:
            experiment_best, experiment_bestR = hp.copy(), rp

    # Repeat scan from new best while time remains
    round_i = 1
    while time.process_time() < deadline - 8.0:
        round_i += 1
        raw = scan_shifts(bestH, bestR, "scan%d" % round_i)
        top = raw[:3]
        improved = False
        for rs, delta, hs in top:
            if time.process_time() >= deadline - 3.0:
                break
            cap = min(deadline - 2.0, time.process_time() + 6.0)
            hp, rp = _polish(hs, cap, 6.0)
            print("  [polish%d] delta=%+.1f raw=%.9f polished=%.9f" %
                  (round_i, delta, rs, rp))
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                improved = True
                print("  shift improved: R=%.9f" % bestR)
            if rp > experiment_bestR + 1e-14:
