import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _resample(h, m):
    n = h.size
    if n == m:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, m + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hr = np.clip(np.diff(Sb), 0.0, None)
    if hr.sum() <= 0:
        return np.ones(m)
    return hr


def _perturb_noise(h, rng, amp):
    if amp <= 0:
        return h.copy()
    n = h.size
    w = rng.standard_normal(n)
    k = max(1, int(amp * 4))
    if k > 1:
        kern = np.ones(k) / k
        w = np.convolve(w, kern, mode='same')
    scale = amp / (np.std(w) + 1e-12)
    fac = np.exp(scale * w)
    return np.clip(h * fac, 0, None)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
    return 0.5 * (h[0::2] + h[1::2])


def _prolong(h):
    return np.repeat(h, 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(20240607)
    n = best.size

    # NEW IDEA: multiscale V-cycle polishing.
    # The 0.9408 solution is stuck because local optima at full resolution
    # don't allow the peak structure to shift.  We do a proper
    # restriction -> coarse optimise (with beta-smoothed max to allow the
    # peak to move) -> prolongation -> full-res polish loop, going multiple
    # levels deep, and we also do direct coarsening of the current best
    # (not just resampling mass) so the peak shape is preserved.
    trial = 0
    while time.process_time() < deadline - 8.0:
        trial += 1
        choice = trial % 4
        if choice == 0:
            # deep V-cycle: coarsen twice, optimise, prolong twice
            hc = _coarsen(_coarsen(best))
            hc = _rescale(hc)
            beta = float(rng.choice([1.0, 2.0, 5.0]))
            hc = _lbfgs_log(hc, 400, deadline, beta=beta)
            hc = _window_polish_peak(hc, deadline, 0.5, 6, beta=beta)
            hc = _prolong(_prolong(hc))
            if hc.size != n:
                hc = _resample(hc, n)
            hp = _rescale(hc)
            hp = _lbfgs_log(hp, 400, deadline)
            if time.process_time() >= deadline - 6.0:
                break
            hp = _window_polish_peak(hp, deadline, 0.30, 16)
            r = R_of(hp)
            print("deepV beta=%.1f trial=%d R=%.7f" % (beta, trial, r))
        elif choice == 1:
            # single coarsen + beta
            hc = _coarsen(best)
            hc = _rescale(hc)
            beta = float(rng.choice([2.0, 5.0, 10.0]))
            hc = _lbfgs_log(hc, 400, deadline, beta=beta)
            hp = _prolong(hc)
            if hp.size != n:
                hp = _resample(hp, n)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 400, deadline)
            if time.process_time() >= deadline - 6.0:
                break
            hp = _window_polish_peak(hp, deadline, 0.30, 16)
            r = R_of(hp)
            print("Vcycle beta=%.1f trial=%d R=%.7f" % (beta, trial, r))
        elif choice == 2:
            amp = float(rng.choice([0.05, 0.1, 0.2, 0.4]))
            hp = _perturb_noise(best, rng, amp)
            hp = _rescale(hp)
            if hp.sum() <= 0:
                continue
            hp = _lbfgs_log(hp, 300, deadline)
            if time.process_time() >= deadline - 6.0:
                break
            hp = _window_polish_peak(hp, deadline, 0.30, 16)
            r = R_of(hp)
            print("noise amp=%.2f trial=%d R=%.7f" % (amp, trial, r))
        else:
            # wider peak-window polish at full res, with different fracs
            frac = float(rng.choice([0.15, 0.25, 0.5, 0.75]))
            hp = _window_polish_peak(best, deadline, frac, 24, maxiter=600)
            hp = _lbfgs_log(hp, 400, deadline)
            r = R_of(hp)
            print("widewin frac=%.2f trial=%d R=%.7f" % (frac, trial, r))

        if r > bestR + 1e-12:
            best, bestR = hp, r
            print("  accept R=%.7f" % bestR)

    # Final alternating polish
    while time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

