    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


# ---------- Coarsening / prolongation ----------

def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def _aggregate(h, k, o):
    n = h.size
    if o >= n:
        o = 0
    body = h[o:]
    m = body.size
    full = m // k
    used = full * k
    if full == 0:
        return _rescale(np.array([h.mean()]))
    core = body[:used].reshape(full, k).mean(axis=1)
    tail = body[used:]
    if tail.size > 0:
        extra = tail.sum() / k
        core = np.concatenate((core, [extra]))
    if o > 0:
        head = h[:o].sum() / k
        core = np.concatenate(([head], core))
    return _rescale(np.clip(core, 0.0, None))


def _prolongate_replicate(hc, n_target, k, o):
    rep = np.repeat(hc, k)
    if rep.size == n_target:
        return _rescale(rep)
    return _prolongate(hc, n_target)


# ---------- Gauss-Newton on near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=40):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return h
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return h
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return h
    lam = lam_scale * bn

    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-20 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(20):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-14:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def _block_multiplicative(h, s, a, rng):
    """Multiply each block of size s by exp(e), e~U(-a,a)."""
    n = h.size
    nb = (n + s - 1) // s
    e = rng.uniform(-a, a, size=nb)
    mult = np.repeat(np.exp(e), s)[:n]
    hn = h * mult
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    rng = np.random.default_rng(12345)
    block_sizes = [128, 512, 2048, 8192]
    amps = [0.02, 0.01, 0.005]

    # ---- Block-structured multiplicative perturbation loop ----
    loop_end = min(deadline - 4.0, t0 + budget_seconds * 0.55)
    round_i = 0
    while time.process_time() < loop_end:
        round_i += 1
        s = int(rng.choice(block_sizes))
        a = float(rng.choice(amps))
        hpert = _block_multiplicative(bestH, s, a, rng)
        r_pre = R_of(hpert)

        # pipeline: lbfgs_log beta=0, then beta continuation, then polish
        cap = min(loop_end, time.process_time() + 1.5)
        hp = _lbfgs_log(hpert, 200, cap, beta=0.0)
        for beta in (1e3, 1e4, 1e6):
            if time.process_time() >= loop_end:
                break
            cap = min(loop_end, time.process_time() + 1.2)
            hp = _lbfgs_log(hp, 100, cap, beta=beta)
        r_mid = R_of(hp)
        if time.process_time() < loop_end:
            cap = min(loop_end, time.process_time() + 2.0)
            hp, r_post = _polish(hp, cap, bestRH)
        else:
            r_post = R_of(hp)

        accepted = r_post > bestRH + 1e-13
        print("  round=%d s=%d a=%.3f pre=%.9f mid=%.9f post=%.9f %s" %
              (round_i, s, a, r_pre, r_mid, r_post, "ACCEPT" if accepted else ""))
        if accepted:
            bestH, bestRH = hp.copy(), r_post
            mx, m, near = _stats(bestH)
            print("    NEW BEST R=%.9f argmax=%d near0.1%%=%d" % (bestRH, m, near))
            if bestRH > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = bestH.copy(), bestRH

    # ---- Remaining time: block-additive passes on best ----
    for B in (256, 512, 1024):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)
            if bestRH > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = bestH.copy(), bestRH

    # final polish loop
    loop_end2 = deadline - 0.5
    it = 0
    while time.process_time() < loop_end2:
        it += 1
        cap_t = min(loop_end2, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            if bestRH > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = bestH.copy(), bestRH
            continue
        if time.process_time() < loop_end2 - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end2, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))
                if bestRH > experiment_bestR + 1e-13:
                    experiment_best, experiment_bestR = bestH.copy(), bestRH

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.12, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _refine(h, deadline, frac=0.12, iters=200, beta=0.0):
    """Local block polish on the peak window; keep if R improves."""
    r0 = R_of(h)
    win = _peak_window(h, frac=frac)
    sub = min(deadline, time.process_time() + 3.0)
    h1 = _lbfgs_block(h, win, iters, sub, beta=beta)
    r1 = R_of(h1)
    if r1 > r0 + 1e-13:
        return h1, r1
    return h, r0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    # ---- Main loop: multi-scale peak-window refinement at growing density ----
    # We alternate refining the peak window (where mass concentrates) and
    # occasionally upsampling the whole array to add resolution near the peak.
    h = best.copy()
    r = bestR
    it = 0
    while time.process_time() < deadline - 3.0:
        it += 1
        # Refine on peak window with sharp objective
        h2, r2 = _refine(h, deadline - 2.0, frac=0.12, iters=250, beta=0.0)
        if r2 > r:
            h, r = h2, r2
        # Refine on peak window with beta-smoothed objective to escape
        if time.process_time() < deadline - 2.5:
            h2, r2 = _refine(h, deadline - 1.5, frac=0.18, iters=180,
                             beta=2e3)
            if r2 > r:
                h, r = h2, r2
        # Occasionally widen window to let new mass appear
        if it % 3 == 0 and time.process_time() < deadline - 2.0:
            h2, r2 = _refine(h, deadline - 1.5, frac=0.30, iters=120)
            if r2 > r:
                h, r = h2, r2
        # Try global sharp polish
        if time.process_time() < deadline - 2.0 and it % 2 == 0:
            sub = min(deadline - 1.0, time.process_time() + 2.0)
            hg = _lbfgs_log(h, 200, sub)
            rg = R_of(hg)
            if rg > r + 1e-13:
                h, r = hg, rg
        if r > bestR + 1e-13:
            bestR, best = r, h.copy()
            print("  it=%d R=%.7f N=%d" % (it, bestR, best.size))
        # Increase resolution: upsample by 2, refine
        if it % 2 == 1 and time.process_time() < deadline - 4.0 and best.size < 400000:
            # Upsample using linear interpolation (preserve shape)
            n = best.size
            xo = np.arange(n)
            xn = np.linspace(0, n - 1, 2 * n)
            hu = np.interp(xn, xo, best)
            ru = R_of(hu)
            if ru > r - 1e-4:  # accept near-equal upsample as new seed
                hh, rr = _refine(hu, deadline - 3.0, frac=0.10, iters=200)
                if rr > r + 1e-13:
                    h, r = hh, rr
                    if r > bestR + 1e-13:
                        bestR, best = r, h.copy()
                        print("  upsample R=%.7f N=%d" % (bestR, best.size))

    # Final full polish
    if time.process_time() < deadline - 0.5:
        sub = min(deadline - 0.2, time.process_time() + 2.0)
        hg = _lbfgs_log(best, 300, sub)
        rg = R_of(hg)
        if rg > bestR + 1e-13:
            best, bestR = hg, rg
        print("final sharp R=%.7f" % bestR)

    mx, m_, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m_, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

