        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best, bestR = None, 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)

    if best is None:
        N = 2048
        best = _rescale(np.ones(N))
        bestR = R_of(best)

    # Save the incoming start to report as alternative if we do better.
    start_scaled = best.copy()
    start_R = bestR

    # Phase 1: direct sharp-log polishing on start at its scale.
    h = _lbfgs_log(best, 800, deadline, beta=0.0)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Phase 2: multi-scale. Coarsen, polish, prolongate back.
    # This is a new idea: work at reduced resolution so L-BFGS sees global
    # structure, then refine. Helps escape fine-grained local minima at large N.
    for _ in range(3):
        if time.process_time() > deadline - 3.0:
            break
        hc = _coarsen(best)
        hc = _rescale(hc)
        rc = R_of(hc)
        # Polish coarsened version.
        hc2 = _lbfgs_log(hc, 400, deadline, beta=0.0)
        rc2 = R_of(hc2)
        if rc2 < rc:
            hc2 = hc
        # Prolongate back up and polish.
        hp = _rescale(_prolongate(hc2, best.size))
        hp = _lbfgs_log(hp, 600, deadline, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
        else:
            break

    # Phase 3: alternate smooth (beta) and sharp polishing, plus peak window,
    # and occasional N growth.
    betas = [0.0, 40.0, 150.0, 0.0, 80.0, 300.0, 0.0]
    bi = 0
    stall = 0
    while time.process_time() < deadline - 1.0:
        beta = betas[bi % len(betas)]
        bi += 1
        h1 = _lbfgs_log(best, 600, deadline, beta=beta)
        r1 = R_of(h1)
        if time.process_time() < deadline - 1.5:
            h2 = _window_polish_peak(h1, deadline, 0.35, 24)
            r2 = R_of(h2)
            if r2 > r1:
                h1, r1 = h2, r2
        if r1 > bestR + 1e-14:
            best, bestR = h1, r1
            stall = 0
        else:
            stall += 1
        if stall >= 3 and best.size < 200000 and time.process_time() < deadline - 5.0:
            Nb = min(best.size * 2, 200000)
            hp = _rescale(_prolongate(best, Nb))
            hp = _lbfgs_log(hp, 500, deadline)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
            stall = 0
        if time.process_time() >= deadline - 1.5:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None and start_R > 0:
        if bestR > start_R + 1e-12:
            return {"best": best, "alternative": start_scaled}
        return {"best": start_scaled, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A, n):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=40):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A, n)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-20 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(24):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-14:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def _gn_plateau(h, deadline, label=""):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005]
    lams = [1e-6, 1e-4, 1e-2]
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-14:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Full-N Gauss-Newton on the plateau first ----
    if time.process_time() < deadline - 6.0:
        gn_deadline2 = min(deadline - 3.0, time.process_time() + 12.0)
        gn_hf, gn_Rf = _gn_plateau(bestH, gn_deadline2, label="fullN")
        if gn_Rf > bestRH + 1e-13:
            bestH, bestRH = gn_hf, gn_Rf
            print("  fullN GN R=%.9f" % bestRH)
        if gn_Rf > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = gn_hf.copy(), gn_Rf

    # ---- Alternating L-BFGS + GN passes ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  lbfgs iter=%d R=%.9f" % (it, bestRH))
        if time.process_time() < loop_end - 1.5:
            gn_cap = min(loop_end, time.process_time() + 3.0)
            gh, gr = _gn_plateau(bestH, gn_cap, label="loop")
            if gr > bestRH + 1e-13:
                bestH, bestRH = gh, gr
                print("  loop GN iter=%d R=%.9f" % (it, bestRH))
                continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  peak iter=%d R=%.9f" % (it, bestRH))

    # ---- Final LSQR-based Newton-CG refinement on a few free blocks ----
    if time.process_time() < loop_end - 0.5:
        for frac in (0.10, 0.20, 0.30):
            if time.process_time() >= loop_end:
                break
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 100, cap_t)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  wide iter R=%.9f" % bestRH)

    print("final R=%.9f (best of experiment)" % bestRH)
    print("final R=%.9f (N=%d)" % (bestRH, bestH.size))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _flat(h, thresh=0.0):
    """Flatness deficit G = sum_j (L_j/M - 1)^2 over knots (or those > thresh*M).
    Returns (G, grad_h)."""
    L = _knots(h)
    M = L.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    m = int(np.argmax(L))
    r = L / M - 1.0
    if thresh > 0.0:
        mask = L > thresh * M
    else:
        mask = np.ones_like(L, dtype=bool)
    rm = np.where(mask, r, 0.0)
    G = float(np.sum(rm * rm))
    # dG/dL[k] = 2*r[k]/M for masked, minus correction from M dependence
    S2 = float(np.sum(rm * (L / M)))  # sum (L/M - 1)*(L/M) over masked
    gL = np.where(mask, 2.0 * r / M, 0.0)
    gL[m] -= 2.0 * S2 / M
    grad = _backprop(np.concatenate(([0.0], gL, [0.0])), h)
    return G, grad


def _flat_blend(h, w=0.02):
    G, g = _flat(h)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    gradR = _backprop(gLf, h) + 2.0 / s
    valR = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    val = G - w * (-valR)  # G - w*log R  (valR = -log R)
    grad = g - w * gradR
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _perturb(h, frac=0.10, amp=0.05, rng=None):
    if rng is None:
        rng = np.random
    n = h.size
    w = max(1, int(frac * n))
    lo = rng.randint(0, max(1, n - w))
    hh = h.copy()
    hh[lo:lo + w] *= np.exp(rng.uniform(-amp, amp, size=w))
    return _rescale(hh)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    G0, _ = _flat(best)
    print("base R=%.9f G=%.6e (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, G0, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    experiment_best = best.copy()
    experiment_bestR = bestR
    rng = np.random.RandomState(12345)

    # Variants: (name, fg_factory, threshold, blend_w)
    variants = [
        ("all", lambda: (lambda hh: _flat(hh, 0.0)), 0.0, 0.0),
        ("hi0.5", lambda: (lambda hh: _flat(hh, 0.5)), 0.5, 0.0),
        ("blend", lambda: (lambda hh: _flat_blend(hh, 0.02)), 0.0, 0.02),
    ]

    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        for (name, fgf, thr, w) in variants:
            if time.process_time() >= loop_end - 1.0:
                break
            # Base seed: current experiment best; sometimes a perturbed restart
            if it == 1:
                seed = experiment_best.copy()
            else:
                if rng.rand() < 0.5:
                    seed = experiment_best.copy()
                else:
                    seed = _perturb(experiment_best, frac=0.10, amp=0.05, rng=rng)
            Gs, _ = _flat(seed)
            cap_t = min(loop_end, time.process_time() + 5.0)
            hs = _lbfgs_log(seed, 400, cap_t, fg=fgf())
            Ge, _ = _flat(hs)
            rs = R_of(hs)
            print("  iter=%d var=%s G_start=%.6e G_end=%.6e R=%.9f" %
                  (it, name, Gs, Ge, rs))
            if rs > experiment_bestR + 1e-9:
                # R improved: polish
                cap_t = min(loop_end, time.process_time() + 6.0)
                hp, rp = _polish(hs, cap_t, rs)
                if rp > experiment_bestR + 1e-13:
                    experiment_best, experiment_bestR = hp.copy(), rp
                    print("    NEW EXPERIMENT BEST R=%.9f (var=%s)" %
                          (experiment_bestR, name))
                else:
                    # keep the flat-improved one as alternative candidate
                    if rs > experiment_bestR + 1e-13:
                        experiment_best, experiment_bestR = hs.copy(), rs
            else:
                # track flatness improvement even if R didn't move
                if Ge < Gs * 0.95 and rs > start_bestR - 1e-6:
                    # store as alternative if it's at least as good R-wise
                    if rs > experiment_bestR + 1e-13:
                        experiment_best, experiment_bestR = hs.copy(), rs

    # Final short polish on experiment best
    if time.process_time() < deadline - 1.0:
        cap_t = min(deadline - 0.5, time.process_time() + 4.0)
        hp, rp = _short_polish(experiment_best, cap_t, experiment_bestR)
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp, rp

    Gf, _ = _flat(experiment_best)
    print("final G=%.6e (start G=%.6e) R=%.9f" % (Gf, G0, experiment_bestR))
    mx, m, near = _stats(experiment_best)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (experiment_bestR, experiment_best.size,
           100.0 * np.mean(experiment_best <= 0), mx, m, near))

    if experiment_bestR > start_bestR + 1e-12:
        return {"best": experiment_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample_lin(h, factor):
    n = h.size
    m = n * factor
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = R_of(base)
        best = base.copy()
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d" % (bestR, best.size))

    def try_fine(name, cand):
        nonlocal best, bestR
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f" % (name, bestR))
            return True
        return False

    loop_end = deadline - 1.0
    it = 0
    # Phase 1: smooth-max (beta) descent to nudge peak down toward a tied plateau.
    # This is the new idea: use a soft-max surrogate with moderate beta to
    # slightly lower the peak while keeping L2 high, then a hard-max polish.
    while time.process_time() < loop_end:
        it += 1
        improved = False

        # soft-max refinement at a few betas, each followed by hard-max polish
        for beta_scale in (200.0, 800.0, 3000.0):
            if time.process_time() >= loop_end - 1.0:
                break
            n = best.size
            beta = beta_scale / max(1.0, float(n))
            cap = min(loop_end, time.process_time() + 4.0)
            hs = _lbfgs_log(best, 200, cap, beta=beta)
            # hard-max polish
            cap = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(hs, 150, cap)
            if try_fine("beta%.0f it=%d" % (beta_scale, it), hs):
                improved = True

        if time.process_time() < loop_end - 1.0:
            free = _peak_window(best, frac=0.05)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 200, cap)
            if try_fine("peak it=%d" % it, hp):
                improved = True

        if not improved:
            # escape via prolongation (upsample then descend)
            A = _rescale(_upsample_lin(best, 2))
            cap = min(loop_end, time.process_time() + 4.0)
            hc = _lbfgs_log(A, 200, cap)
            if try_fine("prolong it=%d" % it, hc):
                pass

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d" % (bestR, best.size))
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

