    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=60):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(28):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def _gn_plateau(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002]
    lams = [1e-6, 1e-4, 1e-2, 1e-1]
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-15:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            break
        if time.process_time() < deadline - 0.5:
            cap = min(deadline, time.process_time() + 1.5)
            hp = _lbfgs_log(best, 100, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
    return best, bestR


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # The key change: instead of SA ladder (which failed to beat start),
    # directly attack the full-resolution start with GN-Newton on the
    # near-max plateau, interleaved with L-BFGS, using the full budget.

    # quick full L-BFGS polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 6.0)
        hp = _lbfgs_log(best, 400, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            print("  lbfgs R=%.9f" % bestR)

    # main loop: GN on plateau + local lbfgs, keep going
    it = 0
    while time.process_time() < deadline - 0.5:
        it += 1
        # GN plateau attack
        gn_cap = min(deadline - 0.3, time.process_time() + 5.0)
        gh, gr = _gn_plateau(best, gn_cap)
        if gr > bestR + 1e-15:
            best, bestR = gh, gr
            print("  GN iter=%d R=%.9f" % (it, bestR))
        # then a local lbfgs to settle
        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            hp = _lbfgs_log(best, 200, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("  lbfgs iter=%d R=%.9f" % (it, bestR))
        # occasionally a peak-window block refine
        if it % 3 == 0 and time.process_time() < deadline - 1.0:
            free = _peak_window(best, frac=0.05)
            cap = min(deadline - 0.3, time.process_time() + 2.0)
            hb = _lbfgs_block(best, free, 150, cap)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
                print("  block iter=%d R=%.9f" % (it, bestR))

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _perturb_left(h, rng):
    h = h.copy()
    n = h.size
    lo = 0
    hi = int(0.50 * n)
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, 0.30))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _perturb_global(h, rng):
    h = h.copy()
    n = h.size
    nk = int(rng.integers(3, 7))
    ks = rng.uniform(0.5, 4.0, size=nk)
    amps = rng.normal(0.0, 0.12, size=nk)
    x = np.linspace(0.0, 1.0, n)
    field = np.zeros(n)
    for k, a in zip(ks, amps):
        field += a * np.sin(np.pi * k * x + rng.uniform(0, 2 * np.pi))
    h *= np.exp(field)
    return _rescale(h)


def _perturb_peak(h, rng):
    h = h.copy()
    n = h.size
    lo, hi = _peak_region(h, tol=0.9)
    pad = max(8, (hi - lo))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    W = hi - lo
    if W < 4:
        return h
    nblocks = int(rng.integers(3, 7))
    cuts = np.sort(rng.choice(np.arange(1, W), size=min(nblocks - 1, W - 1), replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, 0.20))
        h[a:c] *= fac
    return _rescale(h)


def _harden(h, deadline, iters=8):
    cur = h
    for beta in (2000.0, 5000.0, 20000.0):
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_sm(cur, beta, maxiter=250, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(cur, maxiter=600, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    return cur


def _smooth_reconvolve(h):
    """Reconstruct a smoother profile from f*f: take sqrt of the convolution
    envelope via a deconvolution-ish Gaussian smoothing. Keeps support."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    k = max(3, h.size // 400)
    kern = np.exp(-0.5 * (np.arange(-k, k + 1) / (k / 2.0 + 1e-9)) ** 2)
    kern /= kern.sum()
    pad = k
    hpad = np.concatenate((np.zeros(pad), h, np.zeros(pad)))
    hs = np.convolve(hpad, kern, mode='same')[pad:pad + h.size]
    return _rescale(np.clip(hs, 0, None))


def _bump_peak(h, rng, deadline):
    """Add a small triangular bump near the peak region of f*f, then reharden."""
    n = h.size
    lo, hi = _peak_region(h, tol=0.98)
    center = (lo + hi) // 2
    width = max(4, (hi - lo) // 2 + int(0.02 * n))
    amp = 0.05 + 0.15 * rng.random()
    h2 = h.copy()
    a = max(0, center - width)
    b = min(n, center + width + 1)
    tri = np.linspace(0, 1, b - a)
    tri = np.minimum(tri, tri[::-1])
    h2[a:b] *= (1.0 + amp * tri)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)
        cur = _lbfgs_log(np.ones(512), maxiter=800, deadline=deadline)
        return cur

    alternative = None
    alt_r = -1.0

    rng = np.random.default_rng(98765)
    cur = start_arr.copy()
    cur_r = best_r

    # ---------------- Phase A: smooth reconstruction restart ----------------
    # A genuinely different start: smooth `start` and reharden. Often lands
    # in a slightly different basin.
    if time.process_time() < hard_end - 4.0:
        try:
            hs = _smooth_reconvolve(cur)
            hs = _harden(hs, hard_end)
            for frac, extra in ((0.25, 12), (0.12, 6)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(hs, hard_end, frac, extra, maxiter=350)
                if R_of(c) >= R_of(hs):
                    hs = c
            r = R_of(hs)
            if r > best_r:
                best, best_r = hs.copy(), r
            elif r > alt_r:
                alternative, alt_r = hs.copy(), r
            if r > cur_r:
                cur, cur_r = hs.copy(), r
        except Exception:
            pass
        print("phaseA R=%.6f N=%d" % (best_r, best.size))

    # ---------------- Phase B: multi-scale basin escapes ----------------
    perturb_fns = [_perturb_left, _perturb_global, _perturb_peak, _bump_peak]
    n_rounds = 10
    for rnd in range(n_rounds):
        if time.process_time() >= hard_end - 1.0:
            break
        pf = perturb_fns[rnd % len(perturb_fns)]
        rng_r = np.random.default_rng(3000 + rnd)
        try:
            if pf is _bump_peak:
                h = pf(cur, rng_r, hard_end)
            else:
                h = pf(cur, rng_r)
        except Exception:
            continue
        for beta in (300.0, 800.0, 2000.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        for frac in (0.20, 0.10):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _window_polish_peak(h, hard_end, frac, 8, maxiter=350, beta=None)
            if R_of(c) >= R_of(h):
                h = c
        r = R_of(h)
        if r > cur_r:
            cur, cur_r = h, r
        if r > best_r:
            best, best_r = h.copy(), r
        elif r > alt_r:
            alternative, alt_r = h.copy(), r

    print("phaseB R=%.6f N=%d" % (best_r, best.size))

    # ---------------- Phase C: increase resolution ----------------
    try:
        for N_big in (64000, 128000):
            if time.process_time() >= hard_end - 2.0:
                break
            if N_big <= best.size:
                continue
            h_big = _prolongate(best, N_big)
            h_big = _harden(h_big, hard_end)
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h_big, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) >= R_of(h_big):
                    h_big = c
            r = R_of(h_big)
            if r > best_r:
                best, best_r = h_big.copy(), r
            elif r > alt_r:
