    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _jitter_seed(h, rng, n_blocks, sigma=0.20):
    N = h.size
    out = h.copy()
    fracs = rng.uniform(0.015, 0.08, size=n_blocks)
    positions = []
    for k in range(n_blocks):
        w = max(2, int(fracs[k] * N))
        lo = int(rng.integers(0, max(1, N - w)))
        positions.append((lo, lo + w))
    positions.sort()
    last_hi = -1
    for lo, hi in positions:
        if lo < last_hi:
            continue
        last_hi = hi
        fac = np.exp(rng.normal(0.0, sigma, size=hi - lo))
        out[lo:hi] = out[lo:hi] * fac
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return h.copy()
    return _rescale(out)


def _solve_seed(h_seed, deadline_seed):
    h = h_seed
    for beta in (30.0, 120.0, 400.0):
        if time.process_time() >= deadline_seed - 0.3:
            break
        h = _lbfgs_sm(h, beta, maxiter=250, deadline=deadline_seed)
    if time.process_time() < deadline_seed - 0.3:
        h = _lbfgs_log(h, maxiter=400, deadline=deadline_seed)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        # cold start: build from scratch
        cur = np.ones(256)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        for beta in (60.0, 200.0, 600.0):
            if time.process_time() >= deadline - 1.0:
                break
            cur = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline - 0.5)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        cur = _window_polish_peak(cur, deadline - 0.5, 0.3, 16, maxiter=400, beta=600.0)
        cur = _lbfgs_log(cur, maxiter=600, deadline=deadline - 0.5)
        return _rescale(cur)

    cur = start_arr.copy()
    cur_r = best_r
    n_full = cur.size
    rng = np.random.default_rng(int(t0 * 1e6) & 0xffffffff)

    # ---- Phase 1: try to break out at full resolution with jittered restarts ----
    # Each restart: perturb a random block, smooth-optimize, then polish.
    alt = None
    alt_r = -1.0

    # First do a strong polish of the incumbent at full resolution
    if time.process_time() < deadline - 3.0:
        cand = _window_polish_peak(cur, deadline - 1.0, 0.35, 24,
                                   maxiter=600, beta=800.0)
        cand = _lbfgs_log(cand, maxiter=600, deadline=deadline - 0.8)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    # Jittered restarts at full resolution
    n_restarts = 0
    while time.process_time() < deadline - 2.5:
        n_restarts += 1
        n = cur.size
        n_blocks = int(rng.integers(4, 14))
        seed = _jitter_seed(cur, rng, n_blocks, sigma=0.25)
        if R_of(seed) < 0.85 * cur_r:
            continue
        slice_end = min(deadline - 1.5, time.process_time() + 3.5)
        # gentle smoothing schedule then log
        for beta in (60.0, 200.0, 800.0):
            if time.process_time() >= slice_end - 0.4:
                break
            seed = _lbfgs_sm(seed, beta, maxiter=200, deadline=slice_end)
        if time.process_time() < slice_end - 0.4:
            seed = _lbfgs_log(seed, maxiter=400, deadline=slice_end)
        if time.process_time() < slice_end - 0.4:
            seed = _window_polish_peak(seed, slice_end, 0.25, 16, maxiter=300, beta=600.0)
        r = R_of(seed)
        print("restart %d R=%.6f (cur %.6f)" % (n_restarts, r, cur_r))
        if r > cur_r:
            cur, cur_r = seed, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif r > alt_r:
            alt, alt_r = seed.copy(), r

    # Final polish of best
    if time.process_time() < deadline - 0.8:
        cand = _window_polish_peak(best, deadline - 0.5, 0.4, 32,
                                   maxiter=600, beta=1000.0)
        cand = _lbfgs_log(cand, maxiter=800, deadline=deadline - 0.4)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r

    print("final R=%.6f (start %.6f)" % (best_r, R_of(start_arr)))
    if alt is not None and alt_r > 0:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve, next_fast_len


def _conv(h):
    if h.size > 1500:
        n = next_fast_len(2 * h.size - 1)
        return fftconvolve(h, h, mode='full')[:2 * h.size - 1]
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=40):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-20 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(24):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-14:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def _gn_plateau(h, deadline, label=""):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005]
    lams = [1e-6, 1e-4, 1e-2]
    rnd = 0
    while time.process_time() < deadline:
        rnd += 1
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-14:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            break
        if time.process_time() < deadline - 1.0:
            cap = min(deadline, time.process_time() + 2.0)
            hp, rp = _short_polish(best, cap, bestR)
            if rp > bestR:
                best, bestR = hp, rp
                print("  %s GN polish -> R=%.9f" % (label, bestR))
    return best, bestR


# ---------- experiment helpers ----------

def _upsample_mass(h, n_target):
    """Mass-conserving cumulative interpolation to n_target cells."""
    n = h.size
    cum = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, n_target + 1)
    cum_new = np.interp(x_new, x_old, cum)
    hn = np.diff(cum_new)
    return np.clip(hn, 0.0, None)


def _power_toe(K, p, mass):
    """Cell averages of x^-p on [0,K] normalized to given mass."""
    j = np.arange(K, dtype=float)
    if abs(p - 1.0) < 1e-9:
        w = np.log((j + 1.0) / np.maximum(j, 1e-12))
    else:
        w = ((j + 1.0) ** (1.0 - p) - j ** (1.0 - p)) / (1.0 - p)
    w = np.clip(w, 0.0, None)
    s = w.sum()
    if s <= 0:
        return np.full(K, mass / K)
    return w * (mass / s)


def _apply_toe(h, K, p, cap_mult=None, side='left'):
    """Overwrite first/last K cells with power-law toe conserving mass."""
    h = h.copy()
    n = h.size
    if side == 'left':
        sl = slice(0, K)
    else:
        sl = slice(n - K, n)
    old = h[sl]
    mass = old.sum()
    if mass <= 0:
        return h
    w = _power_toe(K, p, mass)
    if cap_mult is not None:
        old_max = old.max()
        if old_max > 0:
            cap = cap_mult * old_max
            w = np.minimum(w, cap)
            s = w.sum()
            if s > 0:
                w = w * (mass / s)
            else:
                w = np.full(K, mass / K)
    h[sl] = w
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n0 = best.size
    # choose k
    k_choices = [11, 8, 6, 4]
    k_sel = 4
    for k in k_choices:
        if k * n0 <= 1000000:
            k_sel = k
            break
    n_fine = k_sel * n0
    print("upsample k=%d -> N=%d" % (k_sel, n_fine))

    h_up = _upsample_mass(best, n_fine)
    h_up = _rescale(h_up)
    r_up = R_of(h_up)
    print("upsampled raw R=%.9f (start %.9f, diff %.2e)" % (r_up, bestR, r_up - bestR))

    # K cells for toe overwrite
    K = 4096
    if K > n_fine // 4:
        K = max(64, n_fine // 8)

    ps = [0.30, 0.40, 0.50, 0.60]
    caps = [None, 2.0, 5.0]

    candidates = []
    # control
    candidates.append(("control", h_up.copy(), r_up))

    for p in ps:
        for cap in caps:
            for side in ('left', 'right', 'both'):
                if side == 'both':
                    hc = _apply_toe(h_up, K, p, cap, 'left')
                    hc = _apply_toe(hc, K, p, cap, 'right')
                else:
                    hc = _apply_toe(h_up, K, p, cap, side)
                hc = _rescale(hc)
                rc = R_of(hc)
                candidates.append(("p=%.2f cap=%s side=%s" % (p, cap, side), hc, rc))
                print("  raw %s -> R=%.9f (diff %.2e)" % (candidates[-1][0], rc, rc - bestR))

    # pick best raw candidate
    best_cand = max(candidates, key=lambda c: c[2])
    print("best raw candidate: %s R=%.9f" % (best_cand[0], best_cand[2]))

    experiment_best = best_cand[1].copy()
    experiment_bestR = best_cand[2]

    # block L-BFGS on first K and last K cells
    def _block_toe(h, K, deadline, maxiter=300):
        n = h.size
        free = np.concatenate((np.arange(0, min(K, n)),
                               np.arange(max(0, n - K), n)))
        free = np.unique(free)
        return _lbfgs_block(h, free, maxiter, deadline, beta=0.0)

    # optimize best raw candidate
    if time.process_time() < deadline - 2.0:
        cap_t = min(deadline - 1.0, time.process_time() + 10.0)
        hb = _block_toe(experiment_best, K, cap_t)
        rb = R_of(hb)
        print("  block L-BFGS K=%d -> R=%.9f" % (K, rb))
        if rb > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hb.copy(), rb

    # also optimize control
    if time.process_time() < deadline - 2.0:
        cap_t = min(deadline - 1.0, time.process_time() + 10.0)
        hb = _block_toe(h_up, K, cap_t)
        rb = R_of(hb)
        print("  block L-BFGS control K=%d -> R=%.9f" % (K, rb))
        if rb > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hb.copy(), rb

    # doubled K
    K2 = min(2 * K, n_fine // 4)
    if time.process_time() < deadline - 2.0 and K2 > K:
        cap_t = min(deadline - 1.0, time.process_time() + 10.0)
        hb = _block_toe(experiment_best, K2, cap_t)
        rb = R_of(hb)
        print("  block L-BFGS K=%d -> R=%.9f" % (K2, rb))
        if rb > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hb.copy(), rb

    # full-array polish
    if time.process_time() < deadline - 1.0:
        cap_t = min(deadline - 0.5, time.process_time() + 6.0)
        hp = _lbfgs_log(experiment_best, 200, cap_t, beta=0.0)
        rp = R_of(hp)
        print("  full polish -> R=%.9f" % rp)
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp

    # peak window polish
    if time.process_time() < deadline - 1.0:
        free = _peak_window(experiment_best, frac=0.08)
        cap_t = min(deadline - 0.5, time.process_time() + 6.0)
        hp = _lbfgs_block(experiment_best, free, 200, cap_t, beta=0.0)
        rp = R_of(hp)
        print("  peak polish -> R=%.9f" % rp)
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp

    # remaining time: alternate polish
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 3.0)
        hs = _lbfgs_log(experiment_best, 150, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs
            print("  loop iter=%d R=%.9f" % (it, experiment_bestR))
        if time.process_time() < loop_end - 1.0:
            frac = 0.05 + 0.10 * np.random.random()
            free = _peak_window(experiment_best, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(experiment_best, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hp.copy(), rp
                print("  loop peak iter=%d R=%.9f" % (it, experiment_bestR))

    print("final R=%.9f (experiment)" % experiment_bestR)
    mx, m, near = _stats(experiment_best)
    print("final N=%d zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (experiment_best.size, 100.0 * np.mean(experiment_best <= 0), mx, m, near))

    if experiment_bestR > start_bestR + 1e-12:
        return {"best": experiment_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _restrict(h_big, N_small):
    """Area-averaging restriction to a coarser grid."""
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _multigrid_search(h, deadline, rng):
    """Coarse-grid search: restrict to a smaller N, perturb, optimise, prolongate back.
    Small N makes each L-BFGS step cheap, allowing many diverse restarts that
    explore the landscape far more broadly than polishing at N=32000 alone."""
    n = h.size
    best = h.copy()
    best_r = R_of(h)
    # Coarse sizes to try
    sizes = []
    for f in (2, 3, 4, 6):
        m = n // f
        if 200 <= m <= 8000 and m not in sizes:
            sizes.append(m)
    if not sizes:
        return best, best_r

    while time.process_time() < deadline - 1.0:
        m = int(rng.choice(sizes))
        hc = _restrict(best, m)
        # Random perturbation on coarse grid
        kind = rng.integers(0, 3)
        if kind == 0:
            noise = np.exp(rng.normal(0.0, 0.25, size=m))
            hc = np.clip(hc * noise, 0, None)
        elif kind == 1:
            # Smooth bump
            k = max(2, m // 40)
            lo = int(rng.integers(0, max(1, m - k)))
            hc[lo:lo + k] *= np.exp(rng.normal(0.0, 0.5, size=k))
            hc = np.clip(hc, 0, None)
        else:
            # Global multiplicative jitter
            hc = np.clip(hc * np.exp(rng.normal(0.0, 0.4, size=m)), 0, None)
        hc = _rescale(hc)
        # Optimise on coarse grid (cheap)
        t_slice = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _lbfgs_log(hc, maxiter=400, deadline=t_slice)
        hc = _lbfgs_log(hc, maxiter=200, deadline=t_slice, beta=300.0)
        rc = R_of(hc)
        # Prolongate back to full resolution and polish briefly
        if rc > 0.5 * best_r:
            hf = _prolongate(hc, n)
            hf = _rescale(hf)
            tf = min(deadline - 0.5, time.process_time() + 4.0)
            hf = _lbfgs_log(hf, maxiter=400, deadline=tf)
            rf = R_of(hf)
            if rf > best_r:
                best, best_r = hf, rf
    return best, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    # Try prolongation to finer grid once
    if cur.size * 2 <= 1000000:
        n_big = min(1000000, max(cur.size * 2, 64000))
        try:
            big = _prolongate(cur, n_big)
            big = _lbfgs_log(big, maxiter=400, deadline=deadline)
            big_r = R_of(big)
            if big_r > cur_r + 1e-5:
                cur, cur_r = big, big_r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
        except Exception:
            pass

    # Multigrid coarse exploration phase: budget ~40% of remaining time
    mg_budget = min(deadline - 0.8, time.process_time() + 0.4 * (deadline - time.process_time()))
    try:
        mg_best, mg_r = _multigrid_search(cur, mg_budget, rng)
        if mg_r > cur_r:
            cur, cur_r = mg_best, mg_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif mg_best is not cur and mg_r > alt_r:
            alternative, alt_r = mg_best.copy(), mg_r
    except Exception:
        pass

    # Polishing phase
    while time.process_time() < deadline - 0.8:
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_log(cur, maxiter=300, deadline=deadline - 0.5, beta=beta)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        cand = _window_polish_peak(cur, deadline - 0.5, 0.4, 20, maxiter=500, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # Occasionally restart from a perturbed version
        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine_best(trial, deadline - 0.5,
                                          time_slice=min(6.0, deadline - time.process_time() - 0.5))
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _restrict(h_big, N_small):
    """Area-averaging restriction to a coarser grid."""
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _multigrid_search(h, deadline, rng):
    """Coarse-grid search: restrict to a smaller N, perturb, optimise, prolongate back.
    Small N makes each L-BFGS step cheap, allowing many diverse restarts that
    explore the landscape far more broadly than polishing at N=32000 alone."""
    n = h.size
    best = h.copy()
    best_r = R_of(h)
    # Coarse sizes to try
    sizes = []
    for f in (2, 3, 4, 6):
        m = n // f
        if 200 <= m <= 8000 and m not in sizes:
            sizes.append(m)
    if not sizes:
        return best, best_r

    while time.process_time() < deadline - 1.0:
        m = int(rng.choice(sizes))
        hc = _restrict(best, m)
        # Random perturbation on coarse grid
        kind = rng.integers(0, 3)
        if kind == 0:
            noise = np.exp(rng.normal(0.0, 0.25, size=m))
            hc = np.clip(hc * noise, 0, None)
        elif kind == 1:
            # Smooth bump
            k = max(2, m // 40)
            lo = int(rng.integers(0, max(1, m - k)))
            hc[lo:lo + k] *= np.exp(rng.normal(0.0, 0.5, size=k))
            hc = np.clip(hc, 0, None)
        else:
            # Global multiplicative jitter
            hc = np.clip(hc * np.exp(rng.normal(0.0, 0.4, size=m)), 0, None)
        hc = _rescale(hc)
        # Optimise on coarse grid (cheap)
        t_slice = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _lbfgs_log(hc, maxiter=400, deadline=t_slice)
        hc = _lbfgs_log(hc, maxiter=200, deadline=t_slice, beta=300.0)
        rc = R_of(hc)
        # Prolongate back to full resolution and polish briefly
        if rc > 0.5 * best_r:
            hf = _prolongate(hc, n)
            hf = _rescale(hf)
            tf = min(deadline - 0.5, time.process_time() + 4.0)
            hf = _lbfgs_log(hf, maxiter=400, deadline=tf)
            rf = R_of(hf)
            if rf > best_r:
                best, best_r = hf, rf
    return best, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    # Try prolongation to finer grid once
    if cur.size * 2 <= 1000000:
        n_big = min(1000000, max(cur.size * 2, 64000))
        try:
            big = _prolongate(cur, n_big)
            big = _lbfgs_log(big, maxiter=400, deadline=deadline)
            big_r = R_of(big)
            if big_r > cur_r + 1e-5:
                cur, cur_r = big, big_r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
        except Exception:
            pass

    # Multigrid coarse exploration phase: budget ~40% of remaining time
    mg_budget = min(deadline - 0.8, time.process_time() + 0.4 * (deadline - time.process_time()))
    try:
        mg_best, mg_r = _multigrid_search(cur, mg_budget, rng)
        if mg_r > cur_r:
            cur, cur_r = mg_best, mg_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif mg_best is not cur and mg_r > alt_r:
            alternative, alt_r = mg_best.copy(), mg_r
    except Exception:
        pass

    # Polishing phase
    while time.process_time() < deadline - 0.8:
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_log(cur, maxiter=300, deadline=deadline - 0.5, beta=beta)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        cand = _window_polish_peak(cur, deadline - 0.5, 0.4, 20, maxiter=500, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # Occasionally restart from a perturbed version
        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine_best(trial, deadline - 0.5,
                                          time_slice=min(6.0, deadline - time.process_time() - 0.5))
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
    return 0.5 * (h[0::2] + h[1::2])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f (N=%d)" % (baseR, baseH.size))

    # Work at exactly start's resolution (no duplication); polish, then
    # attempt a doubling refinement which is the main new idea.
    bestH = baseH.copy()
    bestR = baseR
    altH = None
    altR = 0.0

    # Phase 1: polish at native resolution
    cap = min(deadline - 4.0, time.process_time() + 0.25 * budget_seconds)
    hs = _lbfgs_log(bestH, 400, cap)
    rs = R_of(hs)
    if rs > bestR + 1e-14:
        bestH, bestR = hs.copy(), rs
    print("polish native R=%.9f" % bestR)

    # Phase 2: refine by splitting each cell into two equal halves
    # (exact for step functions: convolution identical, but doubles DOF)
    while time.process_time() < deadline - 3.0 and bestH.size < 1000000 // 2:
        h2 = np.repeat(bestH, 2) * 0.5  # keep mass, half height per half-cell
        h2 = _rescale(h2)
        r2 = R_of(h2)
        # polish refined
        cap = min(deadline - 2.5, time.process_time() + 0.15 * budget_seconds)
        hp = _lbfgs_log(h2, 300, cap)
        rp = R_of(hp)
        if rp > r2:
            h2, r2 = hp, rp
        # peak-window polish
        if time.process_time() < deadline - 2.0:
            free = _peak_window(h2, frac=0.05)
            cap = min(deadline - 1.5, time.process_time() + 0.08 * budget_seconds)
            hpp = _lbfgs_block(h2, free, 200, cap)
            rpp = R_of(hpp)
            if rpp > r2:
                h2, r2 = hpp, rpp
        print("refined N=%d R=%.9f (delta %.2e)" % (h2.size, r2, r2 - bestR))
        if r2 > bestR + 1e-13:
            bestH, bestR = h2.copy(), r2
        else:
            # no gain from refinement; keep as alternative if different
            if altH is None:
                altH, altR = h2.copy(), r2
            break

    # Phase 3: alternate global and peak-window polish until near deadline
    loop_end = deadline - 1.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 0.12 * budget_seconds)
        hs = _lbfgs_log(bestH, 300, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  iter=%d global R=%.9f" % (it, bestR))
            continue
        if time.process_time() < loop_end - 0.5:
            frac = 0.02 + 0.08 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 0.08 * budget_seconds)
            hp = _lbfgs_block(bestH, free, 200, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("  iter=%d peak R=%.9f" % (it, bestR))

    # Final quick polish
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hs = _lbfgs_log(bestH, 200, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    print("final N=%d R=%.9f (base %.9f)" % (bestH.size, bestR, baseR))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": (altH if altH is not None else baseH)}
    else:
        return {"best": baseH, "alternative": (bestH if bestR > 0 else None)}

