        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=60):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(28):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def _gn_plateau(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002]
    lams = [1e-6, 1e-4, 1e-2, 1e-1]
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-15:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            break
        if time.process_time() < deadline - 0.5:
            cap = min(deadline, time.process_time() + 1.5)
            hp = _lbfgs_log(best, 100, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
    return best, bestR


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # Main strategy: smooth-max (soft-inf) L-BFGS with beta ladder.
    # This is the key change: the hard-max gradient is sparse and
    # highly non-smooth near the plateau; a softmax with increasing
    # beta gives a smooth landscape that actually moves the plateau.
    betas = [1.0, 5.0, 20.0, 80.0, 300.0, 1000.0]
    it = 0
    while time.process_time() < deadline - 0.5:
        it += 1
        improved = False
        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            cap = min(deadline - 0.3, time.process_time() + 4.0)
            hp = _lbfgs_log(best, 200, cap, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved = True
                print("  beta=%.0f iter=%d R=%.9f" % (beta, it, bestR))
        # GN plateau attack
        if time.process_time() < deadline - 0.5:
            gn_cap = min(deadline - 0.3, time.process_time() + 4.0)
            gh, gr = _gn_plateau(best, gn_cap)
            if gr > bestR + 1e-15:
                best, bestR = gh, gr
                improved = True
                print("  GN iter=%d R=%.9f" % (it, bestR))
        # hard-max L-BFGS to settle
        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            hp = _lbfgs_log(best, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved = True
                print("  hard iter=%d R=%.9f" % (it, bestR))
        # peak-window block refine
        if it % 2 == 0 and time.process_time() < deadline - 1.0:
            free = _peak_window(best, frac=0.05)
            cap = min(deadline - 0.3, time.process_time() + 2.0)
            hb = _lbfgs_block(best, free, 150, cap)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
                improved = True
                print("  block iter=%d R=%.9f" % (it, bestR))
        if not improved and beta == betas[-1]:
            # try a fresh restart from a small perturbation
            rng = np.random.default_rng(it)
            pert = best * (1.0 + 0.001 * rng.standard_normal(best.size))
            pert = _rescale(np.clip(pert, 0, None))
            rp = R_of(pert)
            if rp > bestR:
                best, bestR = pert, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def _duplicate(h, k):
    return np.repeat(h, k)


def _toe_window(h, W, side):
    """Return index array of W cells at the given side ('left' or 'right')."""
    n = h.size
    W = min(W, n)
    if side == 'left':
        return np.arange(0, W)
    else:
        return np.arange(n - W, n)


def _apply_power_law(h, W, p_left, p_right, capped=False, cap_factor=4.0):
    """Replace toe windows with power-law profiles conserving window mass."""
    h = h.copy()
    n = h.size
    for side, p in (('left', p_left), ('right', p_right)):
        idx = _toe_window(h, W, side)
        Ww = idx.size
        if Ww == 0:
            continue
        mass = h[idx].sum()
        if mass <= 0:
            continue
        # position from the support end: for left, i=0 is the end; for right, i=0 is the end
        if side == 'left':
            pos = (np.arange(Ww) + 0.5) / Ww
        else:
            pos = (np.arange(Ww)[::-1] + 0.5) / Ww
        prof = pos ** p
        if capped:
            cap = cap_factor * prof.max()
            prof = np.minimum(prof, cap)
        s = prof.sum()
        if s <= 0:
            continue
        newv = prof * (mass / s)
        h[idx] = newv
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88
    hard_deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best0 = _rescale(base)
            best0R = R_of(best0)
        else:
            best0, best0R = None, 0.0
    else:
        best0, best0R = None, 0.0

    if best0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best0 = _rescale(h)
        best0R = R_of(best0)

    start_best = best0.copy()
    start_bestR = best0R
    mx0, m0, near0 = _stats(best0)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (best0R, best0.size, 100.0 * np.mean(best0 <= 0), mx0, m0, near0))

    # ---- 4x duplication ----
    k = 4
    h4 = _duplicate(best0, k)
    h4 = _rescale(h4)
    r4 = R_of(h4)
    print("4x dup N=%d R=%.9f (start %.9f, diff %.2e)" % (h4.size, r4, best0R, r4 - best0R))

    experiment_best = best0.copy()
    experiment_bestR = best0R

    # ---- Toe surgery table ----
    Ws = [256, 1024, 4096]
    ps = [0.5, 1.0, 1.5, 2.0, 3.0]
    best_raw = h4.copy()
    best_rawR = r4
    best_desc = ("identity", 0, 0.0, 0.0)
    print("toe surgery table (raw, pre-optimisation):")
    for W in Ws:
        for pl in ps:
            for pr in ps:
                if time.process_time() > deadline - 8.0:
                    break
                hv = _apply_power_law(h4, W, pl, pr)
                rv = R_of(hv)
                if rv > best_rawR + 1e-13:
                    best_raw, best_rawR = hv.copy(), rv
                    best_desc = ("power", W, pl, pr)
                if rv > best0R + 1e-5:
                    print("  WIN W=%d pl=%.1f pr=%.1f R=%.9f" % (W, pl, pr, rv))
            if time.process_time() > deadline - 8.0:
                break
        if time.process_time() > deadline - 8.0:
            break
    print("best raw variant: %s R=%.9f (start %.9f)" % (str(best_desc), best_rawR, best0R))

    # capped variants
    for W in Ws:
        for pl in ps:
            for pr in ps:
                if time.process_time() > deadline - 6.0:
                    break
                hv = _apply_power_law(h4, W, pl, pr, capped=True, cap_factor=3.0)
                rv = R_of(hv)
                if rv > best_rawR + 1e-13:
                    best_raw, best_rawR = hv.copy(), rv
                    best_desc = ("capped", W, pl, pr)
            if time.process_time() > deadline - 6.0:
                break
        if time.process_time() > deadline - 6.0:
            break
    print("best raw (incl capped): %s R=%.9f" % (str(best_desc), best_rawR))

    # ---- Optimise the best raw variant ----
    work = best_raw.copy()
    workR = best_rawR
    if workR > best0R + 1e-7:
        # bounded log-height L-BFGS restricted to toe windows
        if time.process_time() < deadline - 4.0:
            W = best_desc[1] if best_desc[0] != "identity" else 1024
            idxL = _toe_window(work, W, 'left')
            idxR = _toe_window(work, W, 'right')
            free = np.concatenate([idxL, idxR])
            cap = min(deadline - 2.0, time.process_time() + 8.0)
            ht = _lbfgs_block(work, free, 200, cap, beta=0.0)
            rt = R_of(ht)
            print("toe L-BFGS -> R=%.9f" % rt)
            if rt > workR:
                work, workR = ht, rt
        # full-array log L-BFGS
        if time.process_time() < deadline - 3.0:
            cap = min(deadline - 1.5, time.process_time() + 8.0)
            hf = _lbfgs_log(work, 150, cap, beta=0.0)
            rf = R_of(hf)
            print("full log L-BFGS -> R=%.9f" % rf)
            if rf > workR:
                work, workR = hf, rf
        # beta ladder
        for beta in (1e2, 1e3, 1e4, 1e5):
            if time.process_time() >= deadline - 1.5:
                break
            cap = min(deadline - 1.0, time.process_time() + 3.0)
            hb = _lbfgs_log(work, 100, cap, beta=beta)
            rb = R_of(hb)
            if rb > workR:
                work, workR = hb, rb
                print("beta=%.0e -> R=%.9f" % (beta, workR))
        # peak-window polish
        for frac in (0.05, 0.10):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(work, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            hp = _lbfgs_block(work, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > workR:
                work, workR = hp, rp
                print("peak frac=%.2f -> R=%.9f" % (frac, workR))
        if workR > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = work.copy(), workR
            print("NEW EXPERIMENT BEST R=%.9f" % experiment_bestR)

    # ---- Loop surgery + polish with new p values ----
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        # try a fresh surgery on current best (at 4x of current best if size allows)
        cur = experiment_best
        curR = experiment_bestR
        # Try random p on current
        W = int(np.random.choice([256, 512, 1024, 2048, 4096]))
        pl = float(np.random.choice([0.3, 0.5, 0.75, 1.0, 1.25, 1.5, 2.0, 2.5, 3.0]))
        pr = float(np.random.choice([0.3, 0.5, 0.75, 1.0, 1.25, 1.5, 2.0, 2.5, 3.0]))
        hv = _apply_power_law(cur, W, pl, pr)
        rv = R_of(hv)
        if rv > curR + 1e-13:
            cur, curR = hv, rv
        # short polish
        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.5, time.process_time() + 2.5)
            hs = _lbfgs_log(cur, 80, cap, beta=0.0)
            rs = R_of(hs)
            if rs > curR:
                cur, curR = hs, rs
        if curR > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = cur.copy(), curR
            print("loop iter=%d W=%d pl=%.2f pr=%.2f R=%.9f" %
                  (it, W, pl, pr, experiment_bestR))

    # Final polish on experiment best
    if time.process_time() < hard_deadline - 1.0:
        cap = min(hard_deadline - 0.5, time.process_time() + 2.0)
        hp, rp = _short_polish(experiment_best, cap, experiment_bestR)
        if rp > experiment_bestR:
            experiment_best, experiment_bestR = hp, rp

    print("final R=%.9f (N=%d)" % (experiment_bestR, experiment_best.size))
    mx, m, near = _stats(experiment_best)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (experiment_bestR, experiment_best.size, 100.0 * np.mean(experiment_best <= 0),
           mx, m, near))

    if experiment_bestR > start_bestR + 1e-12:
        return {"best": experiment_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    """log-sum-exp soft max - rewards flat peak plateaus."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return 0, h.size - 1
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _refine(h, deadline, rounds=6):
    best = h.copy()
    bestR = R_of(best)
    cur = best.copy()
    for r in range(rounds):
        if time.process_time() >= deadline - 2.0:
            break
        for kk, iters in [(9, 60), (5, 90), (3, 120), (1, 150)]:
            if time.process_time() >= deadline - 2.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            rs = R_of(hb)
            if rs > bestR + 1e-14:
                best, bestR = hb.copy(), rs
            cur = hb
        hp = _window_polish_peak(cur, deadline, 0.10, 48, maxiter=150)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp.copy(), rp
        if rp > R_of(cur) - 1e-15:
            cur = hp
    return best, bestR


def _multiscale_refine(h, deadline, bestR):
    """Coarsen -> optimize at coarse scale -> prolongate -> refine.
    This escapes the local basin because the coarse landscape is different."""
    best = h.copy()
    n = h.size
    cur = h.copy()
    # Try several coarsening depths
    for depth in (1, 2, 3):
        if time.process_time() >= deadline - 3.0:
            break
        hc = cur.copy()
        for _ in range(depth):
            if hc.size < 64:
                break
            hc = _coarsen(hc)
        if hc.size < 32:
            continue
        # optimize at coarse scale with smooth softmax to flatten peak
        for beta in (50.0, 200.0, 800.0):
            if time.process_time() >= deadline - 3.0:
                break
            hc2 = _lbfgs_log(hc, 200, deadline, beta=beta)
            if R_of(hc2) > R_of(hc):
                hc = hc2
        # prolongate back up
        hp = _prolongate(hc, n)
        rp = R_of(hp)
        if rp > R_of(cur) - 1e-9:
            # refine the prolonged solution
            hp2, rp2 = _refine(hp, deadline, rounds=3)
            if rp2 > R_of(cur) + 1e-13:
                cur = hp2
                if rp2 > bestR + 1e-13:
                    best, bestR = hp2.copy(), rp2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    cur = best.copy()
    curR = bestR

    # ---- Move 1: soft-max (log-sum-exp) flattening at multiple betas ----
    # This rewards a flatter peak plateau, which is where R gains hide.
    for beta in (30.0, 80.0, 200.0, 500.0, 1200.0):
        if time.process_time() >= deadline - 8.0:
            break
        hb = _lbfgs_log(cur, 250, deadline, beta=beta)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
            print("  beta=%.0f R=%.7f" % (beta, curR))
        # polish with exact max on top
        hb2 = _lbfgs_log(hb, 150, deadline)
        rb2 = R_of(hb2)
        if rb2 > curR + 1e-13:
            cur, curR = hb2, rb2
            print("  beta=%.0f +polish R=%.7f" % (beta, curR))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    # ---- Move 2: multi-scale coarsen/prolongate escape ----
    rng = np.random.RandomState(999)
    round_id = 0
    while time.process_time() < deadline - 6.0:
        round_id += 1
        improved = False

        # multiscale refine on current
        hm, rm = _multiscale_refine(cur, deadline, curR)
        if rm > curR + 1e-13:
            cur, curR = hm, rm
            improved = True
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
            print("  mscale R=%.7f" % curR)

        # perturbation moves (larger than original, to escape)
        for scale in (3e-3, 1e-3, 3e-4):
            if time.process_time() >= deadline - 6.0:
                break
            h = cur.copy()
            mask = h > 1e-12 * h.max()
            idx = np.flatnonzero(mask)
            if idx.size == 0:
                continue
            h[idx] *= np.exp(scale * rng.randn(idx.size))
            h = _rescale(h)
            h2, r2 = _refine(h, deadline, rounds=2)
            if r2 > curR + 1e-13:
                cur, curR = h2, r2
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  round %d scale=%.1e R=%.7f" % (round_id, scale, curR))

        if not improved:
            # force a bigger jump: coarsen deeply and back
            if time.process_time() < deadline - 6.0 and cur.size >= 128:
                hc = cur.copy()
                for _ in range(3):
                    if hc.size < 64:
                        break
                    hc = _coarsen(hc)
                hc = _lbfgs_log(hc, 250, deadline, beta=300.0)
                hp = _prolongate(hc, cur.size)
                hp, rp = _refine(hp, deadline, rounds=2)
                if rp > curR + 1e-13:
                    cur, curR = hp, rp
                    if curR > bestR + 1e-13:
                        best, bestR = cur.copy(), curR
                    print("  deep-coarsen R=%.7f" % curR)
                else:
                    break
            else:
                break

    # ---- Final polishing ----
    if time.process_time() < deadline - 1.0:
        hf, rf = _refine(best, deadline, rounds=8)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f N=%d Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, delta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return _fun_grad(h)
    Lb = Lf[B]
    Lb_safe = np.clip(Lb, 1e-300, None)
    val = -np.log(num) + 2.0 * np.log(s) + np.mean(np.log(Lb_safe))
    gLf = -dq / num
    gLf[B] += (1.0 / nB) / Lb_safe
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log_band(h0, maxiter, deadline, delta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_band(hh, delta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() > deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _smooth_dilate(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _resample(h, m):
    return _rescale(_prolong(np.clip(h, 0, None), m))


# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')[:n]
    else:
        c = np.correlate(yp, h, mode='valid')[:n]
    return 2.0 * c


def _gauss_newton_plateau(h, deadline, iters=8, band=0.05):
    """Gauss-Newton step to flatten the near-max plateau of f*f.

    Targets the knots within `band` of the maximum: we solve a least-squares
    problem that tries to push all of them up to the current maximum.  This is
    a genuinely different move from the log-barrier L-BFGS: it linearises the
    plateau constraint and solves the resulting normal equations in the
    free (positive) variables.  Useful to break through local minima of the
    max-based objective.
    """
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    for _ in range(iters):
        if time.process_time() >= deadline - 0.5:
            break
        Lf = _knots(h)
        mx = Lf.max()
        if mx <= 0:
            break
        A = np.flatnonzero((Lf >= (1.0 - band) * mx) & (Lf > 0))
        if A.size < 4:
            break
        # residual: we want Lf[A] to grow toward mx (slightly above)
        target = mx * 1.0000001
        r = target - Lf[A]
        # Jacobian rows: J[i,:] = 2 * conv(delta_{A[i]-1}, h) restricted to free vars
        thresh = 1e-12 * h.max()
        free = np.flatnonzero(h > thresh)
        if free.size == 0:
            break
        # Build normal equations J^T J x = J^T r via matvec.
        # For efficiency use JVP/VJP products rather than forming J.
        m = A.size
        # We approximate J^T J by a diagonal + low-rank using a few probe vectors.
        # Simpler: use J^T r as gradient and a diagonal scaling.
        g = _JT(h, r, A, n)
        # Diagonal of J^T J: sum over rows of (2*conv(delta_k, h)[A-1])^2.
        # Approximate it via the second moment of h.
        h2 = h * h
        diagJtJ = 4.0 * np.sum(h2) * np.ones(n)  # crude but scale-correct
        step = np.zeros(n)
        step[free] = g[free] / np.maximum(diagJtJ[free], 1e-30)
        # Damped update
        alpha = 0.5
        h_new = h + alpha * step
        h_new = np.clip(h_new, 0.0, None)
        if h_new.sum() <= 0:
            break
        # Accept only if it does not reduce R too much (allow small decrease
        # because we are targeting a smoother plateau that may later pay off).
        r_old = R_of(h)
        r_new = R_of(h_new)
        if r_new >= r_old - 1e-4:
            h = _rescale(h_new)
        else:
            alpha *= 0.5
            h_new = np.clip(h + alpha * step, 0, None)
            if h_new.sum() > 0 and R_of(h_new) > r_old - 1e-4:
                h = _rescale(h_new)
            else:
                break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
        orig_n = start_arr.size
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r
        orig_n = best.size

    # Initial polish
    cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r
    print("initial polish R=%.6f" % best_r)

    alt = None
    alt_r = -1.0

    base_n = max(256, min(orig_n, 65536))
    resolutions = sorted(set([
        max(256, base_n // 4),
        max(256, base_n // 2),
        base_n,
        min(1_000_000, base_n * 2),
    ]))

    round_id = 0
    while time.process_time() < deadline - 2.0:
        round_id += 1
        improved_this_round = False

        # NEW MOVE: Gauss-Newton plateau flattening, before the L-BFGS sweep.
        if time.process_time() < deadline - 2.0:
            gn = _gauss_newton_plateau(best, deadline, iters=6, band=0.02)
            rgn = R_of(gn)
            if rgn > best_r + 1e-9:
                best, best_r = gn, rgn
                improved_this_round = True
            # Then polish with L-BFGS to consolidate.
            if time.process_time() < deadline - 2.0:
                c2 = _lbfgs_log(best, maxiter=200, deadline=deadline)
                r2 = R_of(c2)
                if r2 > best_r + 1e-9:
                    best, best_r = c2, r2
                    improved_this_round = True

        for m in resolutions:
            if time.process_time() >= deadline - 2.0:
                break
            if best.size != m:
                seed = _resample(best, m)
            else:
                seed = best.copy()
            seed = _rescale(seed)

            cand, r = _homotopy(seed, (128, 512, 2048),
                                maxiter=180, deadline=deadline)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True
            elif alt is None or r > alt_r:
                alt, alt_r = cand, r

            if time.process_time() < deadline - 2.0:
                for delta in (0.01, 0.002):
                    if time.process_time() >= deadline - 2.0:
                        break
                    c2 = _lbfgs_log_band(best, maxiter=250,
                                         deadline=deadline, delta=delta)
                    r2 = R_of(c2)
                    if r2 > best_r + 1e-9:
                        best, best_r = c2, r2
                        improved_this_round = True

        if time.process_time() < deadline - 2.0:
            cand, r = _polish(best, deadline, best_r,
                              fracs=(0.25, 0.12, 0.05, 0.02),
                              maxiter=250)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True

        if time.process_time() < deadline - 2.0:
            cand = _lbfgs_log(best, maxiter=250, deadline=deadline)
            r = R_of(cand)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True

        print("  round %d R=%.6f N=%d alt=%.6f (start %.6f)" %
              (round_id, best_r, best.size,
               alt_r if alt is not None else -1, start_r))

        if not improved_this_round and round_id >= 2:
            if time.process_time() < deadline - 2.0:
                for k in (5, 11):
                    if time.process_time() >= deadline - 2.0:
                        break
                    seed = _smooth_dilate(best, k)
                    seed = _rescale(seed)
                    cand, r = _homotopy(seed, (64, 256, 1024),
                                        maxiter=180, deadline=deadline)
                    if r > best_r + 1e-9:
                        best, best_r = cand, r
                        improved_this_round = True
                        break
                    elif alt is None or r > alt_r:
                        alt, alt_r = cand, r
                if not improved_this_round:
                    break

    best = _rescale(best)
    best_r = R_of(best)
    print("FINAL best R=%.6f (start %.6f) N=%d" % (best_r, start_r, best.size))

    if start_arr is not None and start_r >= best_r:
        if alt is not None and alt_r > start_r:
            return {"best": start_arr, "alternative": alt}
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        if alt is not None and alt_r > 0 and R_of(alt) < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, delta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return _fun_grad(h)
    Lb = Lf[B]
    Lb_safe = np.clip(Lb, 1e-300, None)
    val = -np.log(num) + 2.0 * np.log(s) + np.mean(np.log(Lb_safe))
    gLf = -dq / num
    gLf[B] += (1.0 / nB) / Lb_safe
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
