# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')[:n]
    else:
        c = np.correlate(yp, h, mode='valid')[:n]
    return 2.0 * c


def _gauss_newton_plateau(h, deadline, iters=8, band=0.05):
    """Gauss-Newton step to flatten the near-max plateau of f*f.

    Targets the knots within `band` of the maximum: we solve a least-squares
    problem that tries to push all of them up to the current maximum.  This is
    a genuinely different move from the log-barrier L-BFGS: it linearises the
    plateau constraint and solves the resulting normal equations in the
    free (positive) variables.  Useful to break through local minima of the
    max-based objective.
    """
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    for _ in range(iters):
        if time.process_time() >= deadline - 0.5:
            break
        Lf = _knots(h)
        mx = Lf.max()
        if mx <= 0:
            break
        A = np.flatnonzero((Lf >= (1.0 - band) * mx) & (Lf > 0))
        if A.size < 4:
            break
        # residual: we want Lf[A] to grow toward mx (slightly above)
        target = mx * 1.0000001
        r = target - Lf[A]
        # Jacobian rows: J[i,:] = 2 * conv(delta_{A[i]-1}, h) restricted to free vars
        thresh = 1e-12 * h.max()
        free = np.flatnonzero(h > thresh)
        if free.size == 0:
            break
        # Build normal equations J^T J x = J^T r via matvec.
        # For efficiency use JVP/VJP products rather than forming J.
        m = A.size
        # We approximate J^T J by a diagonal + low-rank using a few probe vectors.
        # Simpler: use J^T r as gradient and a diagonal scaling.
        g = _JT(h, r, A, n)
        # Diagonal of J^T J: sum over rows of (2*conv(delta_k, h)[A-1])^2.
        # Approximate it via the second moment of h.
        h2 = h * h
        diagJtJ = 4.0 * np.sum(h2) * np.ones(n)  # crude but scale-correct
        step = np.zeros(n)
        step[free] = g[free] / np.maximum(diagJtJ[free], 1e-30)
        # Damped update
        alpha = 0.5
        h_new = h + alpha * step
        h_new = np.clip(h_new, 0.0, None)
        if h_new.sum() <= 0:
            break
        # Accept only if it does not reduce R too much (allow small decrease
        # because we are targeting a smoother plateau that may later pay off).
        r_old = R_of(h)
        r_new = R_of(h_new)
        if r_new >= r_old - 1e-4:
            h = _rescale(h_new)
        else:
            alpha *= 0.5
            h_new = np.clip(h + alpha * step, 0, None)
            if h_new.sum() > 0 and R_of(h_new) > r_old - 1e-4:
                h = _rescale(h_new)
            else:
                break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
        orig_n = start_arr.size
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r
        orig_n = best.size

    # Initial polish
    cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r
    print("initial polish R=%.6f" % best_r)

    alt = None
    alt_r = -1.0

    base_n = max(256, min(orig_n, 65536))
    resolutions = sorted(set([
        max(256, base_n // 4),
        max(256, base_n // 2),
        base_n,
        min(1_000_000, base_n * 2),
    ]))

    round_id = 0
    while time.process_time() < deadline - 2.0:
        round_id += 1
        improved_this_round = False

        # NEW MOVE: Gauss-Newton plateau flattening, before the L-BFGS sweep.
        if time.process_time() < deadline - 2.0:
            gn = _gauss_newton_plateau(best, deadline, iters=6, band=0.02)
            rgn = R_of(gn)
            if rgn > best_r + 1e-9:
                best, best_r = gn, rgn
                improved_this_round = True
            # Then polish with L-BFGS to consolidate.
            if time.process_time() < deadline - 2.0:
                c2 = _lbfgs_log(best, maxiter=200, deadline=deadline)
                r2 = R_of(c2)
                if r2 > best_r + 1e-9:
                    best, best_r = c2, r2
                    improved_this_round = True

        for m in resolutions:
            if time.process_time() >= deadline - 2.0:
                break
            if best.size != m:
                seed = _resample(best, m)
            else:
                seed = best.copy()
            seed = _rescale(seed)

            cand, r = _homotopy(seed, (128, 512, 2048),
                                maxiter=180, deadline=deadline)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True
            elif alt is None or r > alt_r:
                alt, alt_r = cand, r

            if time.process_time() < deadline - 2.0:
                for delta in (0.01, 0.002):
                    if time.process_time() >= deadline - 2.0:
                        break
                    c2 = _lbfgs_log_band(best, maxiter=250,
                                         deadline=deadline, delta=delta)
                    r2 = R_of(c2)
                    if r2 > best_r + 1e-9:
                        best, best_r = c2, r2
                        improved_this_round = True

        if time.process_time() < deadline - 2.0:
            cand, r = _polish(best, deadline, best_r,
                              fracs=(0.25, 0.12, 0.05, 0.02),
                              maxiter=250)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True

        if time.process_time() < deadline - 2.0:
            cand = _lbfgs_log(best, maxiter=250, deadline=deadline)
            r = R_of(cand)
            if r > best_r + 1e-9:
                best, best_r = cand, r
                improved_this_round = True

        print("  round %d R=%.6f N=%d alt=%.6f (start %.6f)" %
              (round_id, best_r, best.size,
               alt_r if alt is not None else -1, start_r))

        if not improved_this_round and round_id >= 2:
            if time.process_time() < deadline - 2.0:
                for k in (5, 11):
                    if time.process_time() >= deadline - 2.0:
                        break
                    seed = _smooth_dilate(best, k)
                    seed = _rescale(seed)
                    cand, r = _homotopy(seed, (64, 256, 1024),
                                        maxiter=180, deadline=deadline)
                    if r > best_r + 1e-9:
                        best, best_r = cand, r
                        improved_this_round = True
                        break
                    elif alt is None or r > alt_r:
                        alt, alt_r = cand, r
                if not improved_this_round:
                    break

    best = _rescale(best)
    best_r = R_of(best)
    print("FINAL best R=%.6f (start %.6f) N=%d" % (best_r, start_r, best.size))

    if start_arr is not None and start_r >= best_r:
        if alt is not None and alt_r > start_r:
            return {"best": start_arr, "alternative": alt}
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        if alt is not None and alt_r > 0 and R_of(alt) < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _split4(h, alpha, rng):
    """Mass-preserving 4-way random split of each group of 4 cells."""
    n = h.size
    if n % 4 != 0:
        pad = 4 - (n % 4)
        h = np.concatenate((h, np.zeros(pad)))
        n = h.size
    g = h.reshape(-1, 4)
    mass = g.sum(axis=1, keepdims=True)
    w = rng.dirichlet([alpha] * 4, size=g.shape[0])
    out = w * mass
    return out.reshape(-1)


def _free_mask(h, frac=0.05, edge=4096):
    """Cells whose group's f*f knots are within frac of max, or near edges."""
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    # f*f knot index k corresponds roughly to support position k/(2n);
    # cell i covers support [i/n,(i+1)/n] -> knot region around 2i..2i+2
    mask = np.zeros(n, dtype=bool)
    # edge cells
    e = min(edge, n)
    mask[:e] = True
    mask[n - e:] = True
    # peak region: knots within frac of max -> map back to cells
    peak_knots = np.flatnonzero(Lf >= (1.0 - frac) * mx)
    if peak_knots.size > 0:
        lo_k = peak_knots.min()
        hi_k = peak_knots.max()
        lo_c = max(0, lo_k // 2 - 8)
        hi_c = min(n, hi_k // 2 + 8)
        mask[lo_c:hi_c] = True
    return np.flatnonzero(mask)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    rng = np.random.default_rng(12345)

    # ---- Stage A: raw 4-way random splits, no polish ----
    bestH = baseH.copy()
    bestR = baseR
    raw_candidates = []
    n_split = 0
    n_beat = 0
    best_raw_R = -1.0
    best_raw_h = None
    for alpha in (1.0, 4.0, 20.0):
        for seed in range(40):
            if time.process_time() >= deadline - 20.0:
                break
            r = np.random.default_rng(seed * 1000 + int(alpha * 10))
            hs = _split4(baseH, alpha, r)
            hs = _rescale(hs)
            rs = R_of(hs)
            n_split += 1
            if rs > best_raw_R:
                best_raw_R = rs
                best_raw_h = hs.copy()
            if rs > baseR - 1e-6:
                n_beat += 1
            raw_candidates.append((rs, hs.copy(), alpha, seed))
    print("StageA: %d splits, best raw R=%.9f (base %.9f, delta %.2e), %d within 1e-6" %
          (n_split, best_raw_R, baseR, best_raw_R - baseR, n_beat))

    raw_candidates.sort(key=lambda t: -t[0])
    top = raw_candidates[:5]

    # ---- Stage B: polish top 5 with free mask + beta homotopy ----
    stageB_best = baseH.copy()
    stageB_bestR = baseR
    for (rs, hs, alpha, seed) in top:
        if time.process_time() >= deadline - 8.0:
            break
        free = _free_mask(hs, frac=0.05, edge=4096)
        cap = min(deadline - 6.0, time.process_time() + 4.0)
        hp = _lbfgs_block(hs, free, 150, cap, beta=0.0)
        rp = R_of(hp)
        for beta in (1e4, 1e5, 1e6):
            if time.process_time() >= deadline - 6.0:
                break
            cap = min(deadline - 5.0, time.process_time() + 1.5)
            hb = _lbfgs_block(hp, free, 60, cap, beta=beta)
            rb = R_of(hb)
            if rb > rp:
                hp, rp = hb, rb
        print("  StageB alpha=%.1f seed=%d raw=%.9f -> polished=%.9f (delta vs base %.2e)" %
              (alpha, seed, rs, rp, rp - baseR))
        if rp > stageB_bestR + 1e-14:
            stageB_best, stageB_bestR = hp.copy(), rp

    if stageB_bestR > bestR + 1e-14:
        bestH, bestR = stageB_best.copy(), stageB_bestR
        mx, m, near = _stats(bestH)
        print("StageB improved: R=%.9f max/mean=%.2f near0.1%%=%d" %
              (bestR, mx / bestH.mean(), near))

    # ---- Stage C: full-array exact-R L-BFGS on best ----
    if time.process_time() < deadline - 2.0:
        cap = min(deadline - 1.0, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 150, cap, beta=0.0)
        rs = R_of(hs)
        print("StageC full L-BFGS -> R=%.9f (delta %.2e)" % (rs, rs - bestR))
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    # Final short polish if time
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hs = _lbfgs_log(bestH, 100, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    mx, m, near = _stats(bestH)
    print("final R=%.9f N=%d zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        alt = stageB_best if stageB_bestR > baseR else baseH
        return {"best": baseH, "alternative": alt}

