                cap_t = min(deadline - 0.8, time.process_time() + 1.5)
                hn = _lbfgs_block(cur, free, 120, cap_t, beta=0.0)
                rn = R_of(hn)
                if rn > curR + 1e-14:
                    cur, curR = hn, rn
                    improved_cycle = True

            print("cyc=%d delta=%.3f R=%.12f near0.1%%=%.4f" %
                  (cycle, delta, curR, _frac_near(cur, 0.001)))

            if curR > bestR + 1e-14:
                bestH, bestR = cur.copy(), curR

        # peak-window block polish at multiple fracs
        for frac in fracs:
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(cur, frac=frac)
            cap_t = min(deadline - 0.8, time.process_time() + 2.0)
            hn = _lbfgs_block(cur, free, 150, cap_t, beta=0.0)
            rn = R_of(hn)
            if rn > curR + 1e-14:
                cur, curR = hn, rn
                improved_cycle = True
                if curR > bestR + 1e-14:
                    bestH, bestR = cur.copy(), curR
            print("cyc=%d frac=%.2f R=%.12f near0.1%%=%.4f" %
                  (cycle, frac, curR, _frac_near(cur, 0.001)))

        if not improved_cycle and cycle > 2:
            # try a broader window to escape
            free = _peak_window(cur, frac=0.30)
            cap_t = min(deadline - 0.8, time.process_time() + 2.0)
            hn = _lbfgs_block(cur, free, 150, cap_t, beta=0.0)
            rn = R_of(hn)
            if rn > curR + 1e-14:
                cur, curR = hn, rn
                if curR > bestR + 1e-14:
                    bestH, bestR = cur.copy(), curR

    altH, altR = cur.copy(), curR

    if bestR > baseR + 1e-12:
        print("final R=%.12f (N=%d) gain=%+.2e" % (bestR, bestH.size, bestR - baseR))
        return {"best": bestH, "alternative": altH}
    else:
        print("capped surrogate: no gain over base (R=%.12f)" % baseR)
