import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=60):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(28):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def _gn_plateau(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002]
    lams = [1e-6, 1e-4, 1e-2, 1e-1]
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-15:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            break
        if time.process_time() < deadline - 0.5:
            cap = min(deadline, time.process_time() + 1.5)
            hp = _lbfgs_log(best, 100, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
    return best, bestR


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # Extended smooth-max homotopy ladder: very low beta to very high beta.
    betas = [1e-3, 3e-3, 1e-2, 3e-2, 0.1, 0.3, 1.0, 3.0, 10.0, 30.0,
             100.0, 300.0, 1e3, 3e3, 1e4, 3e4, 1e5, 1e6, 1e7]
    fracs = [0.02, 0.05, 0.10, 0.20]

    cycle = 0
    while time.process_time() < deadline - 0.5:
        cycle += 1
        improved_cycle = False
        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            cap = min(deadline - 0.3, time.process_time() + 2.0)
            hp = _lbfgs_log(best, 150, cap, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved_cycle = True
            print("  cyc=%d beta=%.0e R=%.9f" % (cycle, beta, bestR))

            # peak-window block polish at this beta
            if time.process_time() >= deadline - 0.5:
                break
            for frac in fracs:
                if time.process_time() >= deadline - 0.5:
                    break
                free = _peak_window(best, frac=frac)
                cap = min(deadline - 0.3, time.process_time() + 1.0)
                hb = _lbfgs_block(best, free, 100, cap, beta=beta)
                rb = R_of(hb)
                if rb > bestR + 1e-15:
                    best, bestR = hb, rb
                    improved_cycle = True
                    print("    block frac=%.2f R=%.9f" % (frac, bestR))

        # exact-R GN plateau attack between cycles
        if time.process_time() < deadline - 0.5:
            gn_cap = min(deadline - 0.3, time.process_time() + 3.0)
            gh, gr = _gn_plateau(best, gn_cap)
            if gr > bestR + 1e-15:
                best, bestR = gh, gr
                improved_cycle = True
                print("  GN cyc=%d R=%.9f" % (cycle, bestR))

        if not improved_cycle and cycle > 1:
            break

    # final hard-max exact-R polish
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        hp = _lbfgs_log(best, 300, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            print("  final hard R=%.9f" % bestR)

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

