    def fg(h):
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(h.size)
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        e = np.exp(beta * (Lf - mx))
        Z = e.sum()
        w = e / Z
        Lsoft = mx + np.log(Z) / beta
        gLf = -dq / num + w / Lsoft
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lsoft)
        return val, grad
    return fg


