        if time.process_time() > deadline - 1.0:
            break
        fg = _make_fg_soft(b)
        sub_dl = min(deadline - 0.5, time.process_time() + 4.0)
        h2 = _lbfgs_log(h, maxiter, sub_dl, fg=fg)
        if R_of(h2) >= R_of(h) - 1e-9:
            h = h2
    return h


