# ---- Gauss-Newton on the near-max plateau of f*f ----
def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')[:n]
    else:
        c = np.correlate(yp, h, mode='valid')[:n]
    return 2.0 * c


def _gauss_newton_plateau(h0, deadline, n_iter=6, frac=0.06, reg=1e-6):
    """Reduce ||f*f||_inf by pushing near-max knots down via Gauss-Newton on
    the squared residuals (L_j - Lmax*(1-eps)) for knots in the plateau."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    for it in range(n_iter):
        if time.process_time() > deadline - 0.5:
            break
        Lf = _knots(h)
        mx = Lf.max()
        # target the knots within 1% of max: push them down slightly
        thr = 0.99 * mx
        A = np.flatnonzero(Lf >= thr)
        if A.size < 4:
            break
        target = mx * (1.0 - 1e-3)
        r = Lf[A] - target  # positive: too high
        # We want to reduce max: solve J d = -r for d (d = change in h)
        # J is (|A| x n), J_j = 2*(h*d_j)[A_j-1]
        JtJ = np.zeros((n, n))
        Jtr = np.zeros(n)
        # Build via matvecs (n up to ~1e5 => too big for dense; use CG)
        def Jv(v):
            return _Jd(h, v, A)
        def JTv(y):
            return _JT(h, y, A, n)
        # CG on (J^T J + reg I) d = -J^T r
        rhs = -JTv(r)
        d = np.zeros(n)
        resid = rhs.copy()
        p = resid.copy()
        rsold = np.dot(resid, resid)
        if rsold <= 0:
            break
        for _ in range(15):
            if time.process_time() > deadline - 0.5:
                break
            Jp = Jv(p)
            Ap = JTv(Jp) + reg * p
            alpha = rsold / (np.dot(p, Ap) + 1e-300)
            d += alpha * p
            resid -= alpha * Ap
            rsnew = np.dot(resid, resid)
            if rsnew < 1e-16 * (rsold + 1e-300):
                break
            p = resid + (rsnew / rsold) * p
            rsold = rsnew
        # line search on step size
        best_h, best_r = h, R_of(h)
        for step in (1.0, 0.5, 0.25, 0.1):
            htry = np.clip(h + step * d, 0, None)
            if htry.sum() <= 0:
                continue
            htry = _rescale(htry)
            rt = R_of(htry)
            if rt > best_r:
                best_h, best_r = htry, rt
        if best_h is h:
            break
        h = best_h
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    # ---- (A) Fine-grid lift ----
    if time.process_time() < deadline - 20.0:
        for factor in (2, 4):
            if time.process_time() > deadline - 15.0:
                break
            Nnew = min(1000000, bestH.size * factor)
            if Nnew == bestH.size:
                continue
            h_lift = _mass_resample(bestH, Nnew)
            h_lift = _rescale(h_lift)
            r_lift = R_of(h_lift)
            sub_dl = min(deadline - 10.0, time.process_time() + 8.0)
            h_pol = _lbfgs_log(h_lift, 300, sub_dl)
            r_pol = R_of(h_pol)
            print("  lift x%d N=%d R0=%.7f Rpol=%.7f" % (factor, Nnew, r_lift, r_pol))
            if r_pol > bestRH + 1e-13:
                bestH, bestRH = h_pol.copy(), r_pol

    # ---- (B) Soft-max homotopy polish ----
    if time.process_time() < deadline - 12.0:
        h_soft = _soft_polish(bestH, min(deadline - 10.0, time.process_time() + 18.0))
        r_soft = R_of(h_soft)
        print("  soft-homotopy R=%.7f (was %.7f)" % (r_soft, bestRH))
        if r_soft > bestRH + 1e-13:
            bestH, bestRH = h_soft.copy(), r_soft

    # ---- (C) NEW: Gauss-Newton plateau-flattening polish ----
    # The key new idea: directly minimize the max knot by Gauss-Newton on
    # the near-max plateau, which the L-BFGS smooth objectives approximate
    # only indirectly. Interleave with hard L-BFGS polish.
    if time.process_time() < deadline - 8.0:
        sub_dl = min(deadline - 6.0, time.process_time() + 10.0)
        h_gn = _gauss_newton_plateau(bestH, sub_dl, n_iter=8, frac=0.06)
        h_gn = _lbfgs_log(h_gn, 200, min(deadline - 4.0, time.process_time() + 4.0))
        r_gn = R_of(h_gn)
        print("  gauss-newton plateau R=%.7f (was %.7f)" % (r_gn, bestRH))
        if r_gn > bestRH + 1e-13:
            bestH, bestRH = h_gn.copy(), r_gn

    # ---- (D) Iterated soft-homotopy + hard + GN loop ----
    round_i = 0
    while time.process_time() < deadline - 3.0:
        round_i += 1
        prev = bestRH
        if time.process_time() < deadline - 2.5:
            h_soft = _soft_polish(bestH, min(deadline - 2.0, time.process_time() + 5.0),
                                  betas=(50.0, 150.0, 500.0, 1500.0), maxiter=60)
            r_soft = R_of(h_soft)
            if r_soft > bestRH + 1e-13:
                bestH, bestRH = h_soft.copy(), r_soft
        if time.process_time() < deadline - 1.5:
            sub_dl = min(deadline - 1.0, time.process_time() + 4.0)
            h_hard = _lbfgs_log(bestH, 200, sub_dl)
            r_hard = R_of(h_hard)
            if r_hard > bestRH + 1e-13:
                bestH, bestRH = h_hard.copy(), r_hard
        if time.process_time() < deadline - 1.5:
            sub_dl = min(deadline - 1.0, time.process_time() + 4.0)
            h_gn = _gauss_newton_plateau(bestH, sub_dl, n_iter=4, frac=0.06)
            r_gn = R_of(h_gn)
            if r_gn > bestRH + 1e-13:
                bestH, bestRH = h_gn.copy(), r_gn
        print("  round %d R=%.7f (dR=%.2e)" % (round_i, bestRH, bestRH - prev))
        if bestRH - prev < 1e-10:
            if time.process_time() < deadline - 3.0:
                rng = np.random.default_rng(round_i)
                h_j = bestH * (1.0 + 0.005 * rng.standard_normal(bestH.size))
                h_j = _rescale(h_j)
                if R_of(h_j) > bestRH - 1e-6:
                    bestH = h_j
            else:
                break

    # ---- (E) Final hard sharpening ----
    if time.process_time() < deadline - 0.8:
        h = _lbfgs_log(bestH, 500, deadline - 0.4)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH
    else:
        best = start_best
        bestR = start_bestR

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": bestH if bestRH > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


# ---------- Gauss-Newton on near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=50):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(28):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn
        alpha *= 0.4
    return h, bestR


def _gn_plateau(h, deadline, label=""):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002]
    lams = [1e-8, 1e-6, 1e-4, 1e-2]
    stall = 0
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-15:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
            if time.process_time() < deadline - 1.0:
                cap = min(deadline, time.process_time() + 2.0)
                hp, rp = _short_polish(best, cap, bestR)
                if rp > bestR:
                    best, bestR = hp, rp
                    print("  %s GN polish -> R=%.9f" % (label, bestR))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n_fine = best.size
    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # Coarsen and run GN on multiple scales simultaneously
    scales = []
    hs = bestH
    for _ in range(4):
        hs = _coarsen(hs)
        if hs.size < 64:
            break
        scales.append(hs.copy())

    # GN on coarsest scales first (fast, gets global structure right)
    for level, hc in enumerate(reversed(scales)):
        if time.process_time() >= deadline - 3.0:
            break
        gn_cap = min(deadline - 2.0, time.process_time() + budget_seconds * 0.15)
        gh, gr = _gn_plateau(hc, gn_cap, label="scale%d" % (hc.size))
        print("GN scale N=%d end: R=%.9f" % (hc.size, gr))
        if gr > R_of(hc) + 1e-14:
            hf = _prolongate(gh, n_fine)
            rf = R_of(hf)
            if time.process_time() < deadline - 3.0:
                cap = min(deadline - 2.0, time.process_time() + 5.0)
                hp, rp = _polish(hf, cap, rf)
                print("  prolong scale%d -> polished R=%.9f" % (hc.size, rp))
                if rp > experiment_bestR + 1e-14:
                    experiment_best, experiment_bestR = hp.copy(), rp
                if rp > bestRH + 1e-14:
                    bestH, bestRH = hp.copy(), rp
                    print("  NEW BEST R=%.9f (scale %d)" % (bestRH, hc.size))

    # Full-N GN on the plateau
    if time.process_time() < deadline - 6.0:
        gn_deadline2 = min(deadline - 3.0, time.process_time() + 8.0)
        gn_hf, gn_Rf = _gn_plateau(bestH, gn_deadline2, label="fullN")
        if gn_Rf > bestRH + 1e-14:
            bestH, bestRH = gn_hf, gn_Rf
            print("  NEW BEST (fullN GN) R=%.9f" % bestRH)
        if gn_Rf > experiment_bestR + 1e-14:
            experiment_best, experiment_bestR = gn_hf.copy(), gn_Rf

    # Alternating L-BFGS + GN passes
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 3.5)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-14:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
        if time.process_time() < loop_end - 1.5:
            gn_cap = min(loop_end, time.process_time() + 3.0)
            gh, gr = _gn_plateau(bestH, gn_cap, label="loop")
            if gr > bestRH + 1e-14:
                bestH, bestRH = gh, gr
                print("  loop GN iter=%d R=%.9f" % (it, bestRH))
                continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.12 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-14:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))
        if time.process_time() < loop_end - 2.0 and it % 3 == 0:
            # soft-max polish to push the plateau flatter
            beta = 10.0 ** np.random.uniform(2, 5)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(bestH, 150, cap_t, beta=beta)
            rs = R_of(hs)
            if rs > bestRH + 1e-14:
                bestH, bestRH = hs.copy(), rs
                print("  final beta=%.0e iter=%d R=%.9f" % (beta, it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- two-window mass transfer ----------

def _apply_transfer(h, a1, b1, a2, b2, alpha):
    hn = h.copy()
    m1 = h[a1:b1].sum()
    m2 = h[a2:b2].sum()
    if m1 <= 0 or m2 <= 0:
        return None
    hn[a1:b1] = h[a1:b1] * (1.0 + alpha)
    hn[a2:b2] = h[a2:b2] * (1.0 - alpha * m1 / m2)
    if np.any(hn < 0):
        return None
    return hn


def _best_alpha(h, a1, b1, a2, b2, lo=-0.45, hi=0.45, iters=24):
    # golden-section maximisation of R over alpha
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    hc = _apply_transfer(h, a1, b1, a2, b2, c)
    hd = _apply_transfer(h, a1, b1, a2, b2, d)
    fc = R_of(hc) if hc is not None else -1.0
    fd = R_of(hd) if hd is not None else -1.0
    for _ in range(iters):
        if fc > fd:
            hi = d; d = c; fd = fc
            c = hi - gr * (hi - lo)
            hc = _apply_transfer(h, a1, b1, a2, b2, c)
            fc = R_of(hc) if hc is not None else -1.0
        else:
            lo = c; c = d; fc = fd
            d = lo + gr * (hi - lo)
            hd = _apply_transfer(h, a1, b1, a2, b2, d)
            fd = R_of(hd) if hd is not None else -1.0
    alpha = 0.5 * (lo + hi)
    ha = _apply_transfer(h, a1, b1, a2, b2, alpha)
    if ha is None:
        return 0.0, h
    return alpha, ha


def _best_flatten(h, a, b, lo=-0.45, hi=0.45, iters=20):
    win = h[a:b]
    if win.size == 0:
        return 0.0, h
    mean = h.mean()
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    def ev(alpha):
        hn = h.copy()
        hn[a:b] = (1.0 - alpha) * win + alpha * mean
        if np.any(hn < 0):
            return -1.0, None
        return R_of(hn), hn
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    fc, hc = ev(c)
    fd, hd = ev(d)
    for _ in range(iters):
        if fc > fd:
            hi = d; d = c; fd = fc; hd = hc
            c = hi - gr * (hi - lo)
            fc, hc = ev(c)
        else:
            lo = c; c = d; fc = fd; hc = hd
            d = lo + gr * (hi - lo)
            fd, hd = ev(d)
    alpha = 0.5 * (lo + hi)
    fa, ha = ev(alpha)
    if ha is None:
        return 0.0, h
    return alpha, ha


def _build_pairs(n, Lf):
    widths = [256, 1024, 4096, 16384]
    stride = 1024
    m = int(np.argmax(Lf))
    starts = list(range(0, max(1, n - 1), stride))
    pairs = []
    seen = set()
    def add(a1, b1, a2, b2):
        if a1 < 0 or b1 > n or a2 < 0 or b2 > n:
            return
        if b1 <= a1 or b2 <= a2:
            return
        if not (b1 <= a2 or b2 <= a1):
            return
        key = (a1, b1, a2, b2)
        if key in seen:
            return
        seen.add(key)
        pairs.append(key)
    # pairs straddling the argmax (one on each side)
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = m - w // 2; b2 = a2 + w
            if a2 < 0:
                a2 = 0; b2 = w
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
    # pairs with one window on near-max plateau, one in a tail
    plateau_lo = max(0, m - 4096)
    plateau_hi = min(n, m + 4096)
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = plateau_lo; b2 = min(n, plateau_lo + w)
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
            a2 = max(0, plateau_hi - w); b2 = plateau_hi
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
    # opposite-side pairs
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = n - s - w; b2 = n - s
            add(a1, b1, a2, b2)
    # cap
    if len(pairs) > 400:
        idx = np.linspace(0, len(pairs) - 1, 400).astype(int)
        pairs = [pairs[i] for i in idx]
    return pairs


def _scan(h, bestR, deadline, verbose=True):
    n = h.size
    Lf = _knots(h)
    pairs = _build_pairs(n, Lf)
    deltas = []
    best_delta = -np.inf
    best_move = None
    best_h = None
    for (a1, b1, a2, b2) in pairs:
        if time.process_time() >= deadline:
            break
        alpha, hn = _best_alpha(h, a1, b1, a2, b2)
        if hn is None:
            continue
        rn = R_of(hn)
        d = rn - bestR
        deltas.append(d)
        if d > best_delta:
            best_delta = d
            best_move = (a1, b1, a2, b2, alpha)
            best_h = hn
    # flattening moves
    for w in [256, 1024, 4096, 16384]:
        for s in range(0, max(1, n - 1), 1024):
            if time.process_time() >= deadline:
                break
            a = s; b = min(n, s + w)
            alpha, hn = _best_flatten(h, a, b)
            if hn is None:
                continue
            rn = R_of(hn)
            d = rn - bestR
            deltas.append(d)
            if d > best_delta:
                best_delta = d
                best_move = ('flat', a, b, alpha)
                best_h = hn
    if verbose and deltas:
        arr = np.array(deltas)
        pos = arr[arr > 0]
        nonpos = arr[arr <= 0]
        print("  scan: n=%d best=%.3e pos=%d" %
              (len(arr), best_delta, pos.size))
        if nonpos.size:
            print("    nonpos min=%.3e med=%.3e max=%.3e near0=%d" %
                  (nonpos.min(), np.median(nonpos), nonpos.max(),
                   int(np.sum(np.abs(arr) < 1e-7))))
    return best_delta, best_move, best_h


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        cap = min(deadline - 0.5, time.process_time() + 8.0)
        bd, bm, bh = _scan(best, bestR, cap, verbose=True)
        if bd > 1e-13 and bh is not None:
            best = bh
            bestR = R_of(best)
            print("  cyc=%d applied move delta=%.3e R=%.9f" %
                  (cycle, bd, bestR))
        else:
            print("  cyc=%d no improving move (best=%.3e)" % (cycle, bd))
            # try polish anyway
        # polish: peak-window L-BFGS at several fracs
        for frac in [0.02, 0.05, 0.10]:
            if time.process_time() >= deadline - 0.5:
                break
            free = _peak_window(best, frac=frac)
            cap = min(deadline - 0.3, time.process_time() + 1.5)
            hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
                print("    polish frac=%.2f R=%.9f" % (frac, bestR))
        # one full exact-R log-height L-BFGS
        if time.process_time() < deadline - 0.5:
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            hp = _lbfgs_log(best, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("    full R=%.9f" % bestR)
        if bd <= 1e-13 and cycle > 2:
            break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = np.log(np.clip(h, 1e-12, None))

    def f(x):
        hh = np.exp(np.clip(x, -30.0, 30.0))
        if beta > 0:
            val, g = _fun_grad_beta(hh, beta)
        else:
            val, g = _fun_grad(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(np.clip(res.x, -30.0, 30.0)))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta > 0:
            val, g = _fun_grad_beta(hh, beta)
        else:
            val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _frac_near(h, tol=0.001):
    Lf = _knots(h)
    mx = Lf.max()
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _is_staircase(h, factor=4, tol=1e-9):
    n = h.size
    if n % factor != 0:
        return False
    m = n // factor
    blocks = h.reshape(m, factor)
    return bool(np.all(np.abs(blocks - blocks.mean(axis=1, keepdims=True)) <= tol * (1.0 + np.abs(blocks).max())))


def _coarsen(h, factor=4):
    n = h.size
    m = n // factor
    return h.reshape(m, factor).mean(axis=1)


def _lift(h, factor=4):
    return np.repeat(h, factor)


def _golden_max(f, lo, hi, steps=18):
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    a, b = lo, hi
    c = b - gr * (b - a)
    d = a + gr * (b - a)
    fc = f(c); fd = f(d)
    for _ in range(steps):
        if fc > fd:
            b, d, fd = d, c, fc
            c = b - gr * (b - a)
            fc = f(c)
        else:
            a, c, fc = c, d, fd
            d = a + gr * (b - a)
            fd = f(d)
    if fc > fd:
        return c, fc
    return d, fd


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    print("base R=%.12f (N=%d)" % (baseR, base.size))

    # Try to coarsen by 4 if exact staircase.
    work = base
    workR = baseR
    factor = 1
    if _is_staircase(base, 4):
        cand = _coarsen(base, 4)
        candR = R_of(cand)
        print("staircase detected: coarsen x4 M=%d R=%.12f (base %.12f)" %
              (cand.size, candR, baseR))
        if abs(candR - baseR) < 1e-7:
            work = _rescale(cand)
            workR = R_of(work)
            factor = 4
        else:
            print("coarsen R mismatch, staying at full resolution")
    else:
        print("not an exact staircase; staying at full resolution")

    M = work.size
    cur = work.copy()
    curR = workR
    bestH = base.copy()
    bestR = baseR

    B = 1024
    if M < 4 * B:
        B = max(64, M // 8)
    nblocks = (M + B - 1) // B
    rng = np.random.RandomState(12345)

    sweep = 0
    while time.process_time() < deadline - 2.0:
        sweep += 1
        # (1) gradient once
        _, g = _fun_grad(cur)
        glog = g * cur  # d/d log h
        # normalize direction scale
        gn = np.linalg.norm(glog)
        if gn > 0:
            glog = glog / gn

        perm = rng.permutation(nblocks)
        max_block_gain = 0.0
        accepted = 0

        for bi in perm:
            if time.process_time() >= deadline - 2.0:
                break
            lo = bi * B
            hi = min(M, lo + B)
            if hi <= lo:
                continue
            idx = np.arange(lo, hi)
            d = glog[idx]
            if np.linalg.norm(d) <= 0:
                continue
            hb0 = cur[idx].copy()
            base_block_R = curR

            def f_alpha(alpha, idx=idx, d=d, hb0=hb0):
                hh = cur.copy()
                hh[idx] = hb0 * np.exp(alpha * d)
                return R_of(hh)

            # exact 1-D max in [0, 0.5]
            try:
                a_best, r_best = _golden_max(f_alpha, 0.0, 0.5, steps=18)
            except Exception:
                continue
            if r_best > curR + 1e-14:
                cur[idx] = hb0 * np.exp(a_best * d)
                cur = _rescale(cur)
                curR = R_of(cur)
                gain = curR - base_block_R
                if gain > max_block_gain:
                    max_block_gain = gain
                accepted += 1

            # (2) two non-gradient moves
            if time.process_time() >= deadline - 2.0:
                break
            hb0 = cur[idx].copy()
            base_block_R = curR
            mb = hb0.mean()
            mt = cur.mean()

            def f_shrink(alpha, idx=idx, hb0=hb0, mb=mb):
                hh = cur.copy()
                hh[idx] = (1.0 - alpha) * hb0 + alpha * mb
                return R_of(hh)

            try:
                a_best, r_best = _golden_max(f_shrink, 0.0, 1.0, steps=14)
            except Exception:
                a_best, r_best = 0.0, curR
            if r_best > curR + 1e-14:
                cur[idx] = (1.0 - a_best) * hb0 + a_best * mb
                cur = _rescale(cur)
                curR = R_of(cur)
                gain = curR - base_block_R
                if gain > max_block_gain:
                    max_block_gain = gain
                accepted += 1

            if time.process_time() >= deadline - 2.0:
                break
            hb0 = cur[idx].copy()
            base_block_R = curR

            def f_global(alpha, idx=idx, hb0=hb0, mt=mt):
                hh = cur.copy()
                hh[idx] = (1.0 - alpha) * hb0 + alpha * mt
                return R_of(hh)

            try:
                a_best, r_best = _golden_max(f_global, 0.0, 1.0, steps=14)
            except Exception:
                a_best, r_best = 0.0, curR
            if r_best > curR + 1e-14:
                cur[idx] = (1.0 - a_best) * hb0 + a_best * mt
                cur = _rescale(cur)
                curR = R_of(cur)
                gain = curR - base_block_R
                if gain > max_block_gain:
                    max_block_gain = gain
                accepted += 1

        # (3) peak-window L-BFGS frac 0.05
        if time.process_time() < deadline - 2.0:
            free = _peak_window(cur, frac=0.05)
            cap_t = min(deadline - 1.0, time.process_time() + 2.0)
            hn = _lbfgs_block(cur, free, 120, cap_t, beta=0.0)
            rn = R_of(hn)
            if rn > curR + 1e-14:
                cur, curR = hn, rn

        # every 3rd sweep: full log L-BFGS
        if sweep % 3 == 0 and time.process_time() < deadline - 2.0:
            cap_t = min(deadline - 1.0, time.process_time() + 4.0)
            hn = _lbfgs_log(cur, 200, cap_t, beta=0.0)
            rn = R_of(hn)
            if rn > curR + 1e-14:
                cur, curR = hn, rn

        print("sweep=%d R=%.12f maxblockgain=%.3e accepted=%d near0.1%%=%.4f" %
              (sweep, curR, max_block_gain, accepted, _frac_near(cur, 0.001)))

        if curR > bestR + 1e-14:
            if factor > 1:
                bestH = _lift(cur, factor)
            else:
                bestH = cur.copy()
            bestR = R_of(bestH)

    # Final lift + polish if we improved on the coarse grid.
    altH = bestH.copy()
    altR = bestR

    if factor > 1 and curR > workR + 1e-9:
        lifted = _lift(cur, factor)
        lifted = _rescale(lifted)
        lR = R_of(lifted)
        print("lifting: coarse R=%.12f lifted R=%.12f" % (curR, lR))
        # softmax beta ladder
        cur2 = lifted.copy()
        cur2R = lR
        for beta in [1.0, 10.0, 100.0, 1000.0]:
            if time.process_time() >= deadline - 0.5:
                break
            cap_t = min(deadline - 0.4, time.process_time() + 2.0)
            hn = _lbfgs_log(cur2, 100, cap_t, beta=beta)
            rn = R_of(hn)
            if rn > cur2R + 1e-14:
                cur2, cur2R = hn, rn
            print("  beta=%.1f R=%.12f" % (beta, cur2R))
        # hard exact-R polish
        if time.process_time() < deadline - 0.5:
            cap_t = min(deadline - 0.4, time.process_time() + 3.0)
            hn = _lbfgs_log(cur2, 200, cap_t, beta=0.0)
            rn = R_of(hn)
            if rn > cur2R + 1e-14:
                cur2, cur2R = hn, rn
        if cur2R > bestR + 1e-14:
            bestH, bestR = cur2.copy(), cur2R
        altH, altR = cur2.copy(), cur2R
    elif factor == 1 and curR > workR + 1e-12:
        altH, altR = cur.copy(), curR
        if curR > bestR + 1e-14:
            bestH, bestR = cur.copy(), curR

    print("final best R=%.12f (N=%d) base R=%.12f gain=%+.3e" %
          (bestR, bestH.size, baseR, bestR - baseR))
    return {"best": bestH, "alternative": altH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    return max(0, idx.min() - 1), min(h.size - 1, idx.max())


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400, beta=0.0):
    for frac in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    if start_arr is not None:
        base = start_arr
        base_r = start_r
        print("start base R=%.6f N=%d" % (base_r, base.size))

        # Multi-pass polish with increasing softmax sharpness on start itself
        cur = base
        cur_r = base_r
        for beta in (0.0, 0.0, 512.0, 2048.0, 0.0):
            if time.process_time() >= deadline - 1.0:
                break
            c = _lbfgs_log(cur, maxiter=200, deadline=deadline, beta=beta)
            rc = R_of(c)
            if rc > cur_r:
                cur, cur_r = c, rc
            c, rc = _polish(cur, deadline, cur_r,
                            fracs=(0.30, 0.15, 0.07, 0.03), maxiter=300, beta=beta)
            if rc > cur_r:
                cur, cur_r = c, rc
            print("  pass beta=%.0f R=%.6f" % (beta, cur_r))

        if cur_r > best_r:
            best, best_r = cur, cur_r

        # Try a signed excursion from the peak on a moderate resolution
        # (downsample start to ~8k, then re-refine) to escape local optimum
        if time.process_time() < deadline - 5.0:
            n8 = 8192
            hs = _prolong(base, n8)
            hs = _rescale(hs)
            rs = R_of(hs)
            for beta in (0.0, 1024.0):
                c = _lbfgs_log(hs, maxiter=400, deadline=deadline, beta=beta)
                rc = R_of(c)
                if rc > rs:
                    hs, rs = c, rc
            # prolong back up
            m = base.size
            hu = _rescale(_prolong(hs, m))
            ru = R_of(hu)
            c = _lbfgs_log(hu, maxiter=200, deadline=deadline)
            rc = R_of(c)
            if rc > ru:
                hu, ru = c, rc
            c, rc = _polish(hu, deadline, ru, fracs=(0.20, 0.08, 0.03), maxiter=300)
            if rc > ru:
                hu, ru = c, rc
            print("  resample R=%.6f" % ru)
            if ru > best_r:
                best, best_r = hu, ru

    if best is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    best = _rescale(best)
    if start_arr is not None:
        if start_r >= best_r:
            alt = best if not np.array_equal(best, start_arr) else None
            if alt is not None:
                return {"best": _rescale(start_arr), "alternative": alt}
            return _rescale(start_arr)
        return {"best": best, "alternative": _rescale(start_arr)}
    return best

import numpy as np
import time
from scipy.optimize import minimize
