def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pen(h, rho):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    viol = Lf - 1.0
    pos = np.maximum(viol, 0.0)
    pen = rho * np.sum(pos * pos)
    gLf = -dq / num + 2.0 * rho * pos
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _halve(h):
    n = h.size
    if n < 2:
        return h
    m = n // 2
    a = h[:2 * m].reshape(m, 2)
    return a.sum(axis=1)


def _double(h):
    return np.repeat(h, 2)


def _exact_polish(h, bestR, deadline, tag=""):
    best = h
    # peak-window block L-BFGS
    for frac in [0.02, 0.05, 0.10]:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    # full exact-R log L-BFGS
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        hp = _lbfgs_log(best, 200, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
    return best, bestR


def _pen_stage(h, rho, deadline):
    # rescale so max(Lf) == 1 exactly
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    hs = h / np.sqrt(mx)
    cap = min(deadline - 0.3, time.process_time() + 4.0)
    if time.process_time() >= cap - 0.3:
        return h
    fg = (lambda hh: _fun_grad_pen(hh, rho))
    hp = _lbfgs_log(hs, 250, cap, fg=fg)
    return hp


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rhos = [1e0, 1e1, 1e2, 1e3, 1e4, 1e6, 1e8]
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        # alternate between full N and halved M
        if cycle % 2 == 1:
            work = best.copy()
            tag = "N"
        else:
            work = _halve(best)
            tag = "M"
        for rho in rhos:
            if time.process_time() >= deadline - 1.5:
                break
            hp = _pen_stage(work, rho, deadline)
            Lf = _knots(hp)
            num, _, _ = _num_and_dq(hp)
            s = hp.sum()
            ratio = num / (s * s) if s > 0 else 0.0
            mx = Lf.max()
            nviol = int(np.sum(Lf > 1.0))
            nnear = int(np.sum(Lf > 0.99 * mx))
            print("  cyc=%d %s rho=%.0e num/s2=%.9f maxLf=%.6f >1:%d near:%.0f%%=%d" %
                  (cycle, tag, rho, ratio, mx, nviol, 99.0, nnear))
            # exact-R polish
            hp2, rp = _exact_polish(hp, R_of(hp), deadline, tag=tag)
            if tag == "M":
                hp2d = _double(hp2)
                rpd = R_of(hp2d)
                if rpd > rp:
                    hp2, rp = hp2d, rpd
            if rp > bestR + 1e-15:
                best, bestR = hp2, rp
                print("    -> best R=%.9f" % bestR)
            work = hp
        # also polish the current best directly
        if time.process_time() < deadline - 1.0:
            bp, rbp = _exact_polish(best, bestR, deadline)
            if rbp > bestR + 1e-15:
                best, bestR = bp, rbp
                print("  cyc=%d best polish R=%.9f" % (cycle, bestR))

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.15):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(32, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample(h, k):
    """Linear refinement: split each step into k sub-steps via averaging."""
    if k <= 1:
        return h
    n = h.size
    out = np.repeat(h, k) / k
    # small smoothing to avoid exact duplicates
    return out


def _downsample(h, k):
    n = h.size
    m = n // k
    if m < 1:
        return h
    return h[:m * k].reshape(m, k).sum(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    # (1) Multi-resolution strategy: downsample, polish at coarse
    # resolution (cheap, escapes local minima of the fine problem),
    # then upsample and polish at fine resolution. This is the main
    # new idea: the coarse problem has fewer flat directions and can
    # move the global shape, while the fine polish sharpens the peak.
    n0 = bestH.size
    # choose factors that are divisors-ish
    factors = [8, 4, 2, 1]
    for k in factors:
        if time.process_time() > deadline - 6.0:
            break
        if n0 < 8 * k:
            continue
        hc = _downsample(bestH, k) if k > 1 else bestH.copy()
        hc = _rescale(np.clip(hc, 0, None))
        rc = R_of(hc)
        # coarse polish (beta-smoothed then sharp)
        for beta in (30.0, 200.0, 0.0):
            if time.process_time() > deadline - 5.0:
                break
            sub_dl = min(deadline - 4.0, time.process_time() + 3.0)
            hp = _lbfgs_log(hc, 300, sub_dl, beta=beta)
            rp = R_of(hp)
            if rp > rc + 1e-12:
                hc, rc = hp, rp
        # upsample back and check
        if k > 1:
            hu = _upsample(hc, k)
            hu = hu[:n0]
            if hu.size < n0:
                hu = np.concatenate((hu, np.zeros(n0 - hu.size)))
            hu = _rescale(hu)
            ru = R_of(hu)
        else:
            hu, ru = hc, rc
        if ru > bestRH + 1e-13:
            bestH, bestRH = hu.copy(), ru
            print("  multires k=%d R=%.7f" % (k, bestRH))

    # (2) Beta-smoothed polish of the peak region
    if time.process_time() < deadline - 4.0:
        win = _peak_window(bestH, frac=0.20)
        for beta in (20.0, 80.0, 300.0, 1200.0):
            if time.process_time() > deadline - 3.5:
                break
            sub_dl = min(deadline - 3.0, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, win, 150, sub_dl, beta=beta)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  beta=%.0f peak R=%.7f" % (beta, bestRH))

    # (3) Final sharp full polish
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_log(bestH, 500, deadline - 0.3)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d zeros %.1f%%) argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

