# ---- Flat-target objective: push many knots of f*f toward the maximum ----

def _flat_fg(h):
    """F(h) = log( sum_j w_j (g_j - c)^2 / sum_j w_j ), w_j = g_j^2.
    Minimising drives the convolution's mass toward its peak."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    c = Lf.max()
    w = Lf * Lf + 1e-12
    diff = Lf - c
    num = np.sum(w * diff * diff)
    den = np.sum(w)
    if den <= 0:
        return 1e18, np.zeros(h.size)
    val = np.log(num / den + 1e-300)
    gLf = 2.0 * w * diff / num
    grad = _backprop(gLf, h)
    return val, grad


def _flat_descent(h0, seconds, deadline):
    cap = min(deadline - 0.3, time.process_time() + seconds)
    return _lbfgs_log(h0, 200, cap, fg=_flat_fg)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    # Establish base
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    alternative = baseH.copy()
    alternativeR = baseR

    # ---- Strategy A: flat-target descent from base ----
    if time.process_time() < deadline - 5.0:
        cap_s = min(12.0, (deadline - time.process_time()) * 0.35)
        hf = _flat_descent(bestH, cap_s, deadline)
        rf = R_of(hf)
        print("  flat descent -> R=%.9f (delta %.2e)" % (rf, rf - bestR))
        if rf > bestR + 1e-14:
            bestH, bestR = hf.copy(), rf
        # Polish with true objective
        if time.process_time() < deadline - 4.0:
            cap = min(deadline - 3.0, time.process_time() + 4.0)
            hp = _lbfgs_log(bestH, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("  flat polish -> R=%.9f" % bestR)

    # ---- Strategy B: warp experiment to test alternate shapes ----
    Lf = _knots(bestH)
    m = int(np.argmax(Lf))
    n = bestH.size
    xp = min(max(m / (2.0 * n), 0.02), 0.98)

    def _cumint(h):
        return np.concatenate(([0.0], np.cumsum(h)))

    def _sample_cum(C, x):
        n_ = C.size - 1
        x = np.clip(x, 0.0, float(n_))
        i = np.floor(x).astype(int)
        i = np.clip(i, 0, n_ - 1)
        t = x - i
        return C[i] * (1.0 - t) + C[i + 1] * t

    def _warp_resample(h, phi_inv, N):
        n_ = h.size
        C = _cumint(h)
        total = C[-1]
        if total <= 0:
            return np.zeros(N)
        j = np.arange(N + 1, dtype=float)
        y = j / N
        x = phi_inv(y) * n_
        Cv = _sample_cum(C, x)
        out = np.clip(np.diff(Cv), 0.0, None)
        return out

    def _build_warp(xp_, w, c, N=4096):
        xs = np.linspace(0.0, 1.0, N + 1)
        rho = 1.0 + c * np.exp(-((xs - xp_) / w) ** 2)
        dx = xs[1] - xs[0]
        cum = np.concatenate(([0.0], np.cumsum(0.5 * (rho[:-1] + rho[1:]) * dx)))
        phi = cum / cum[-1]
        phi[0] = 0.0
        phi[-1] = 1.0

        def phi_inv(y):
            return np.interp(np.clip(y, 0, 1), phi, xs)
        return phi_inv, phi, xs

    warp_best = bestH.copy()
    warp_bestR = bestR
    Nw = bestH.size
    for w in (0.05, 0.10, 0.15):
        for c in (1.0, 2.0, 4.0):
            if time.process_time() >= deadline - 6.0:
                break
            for direction in (1, -1):
                if time.process_time() >= deadline - 6.0:
                    break
                try:
                    phi_inv, phi, xs = _build_warp(xp, w, c)
                    if direction == -1:
                        def phi_inv_swap(y, _phi=phi, _xs=xs):
                            return np.interp(np.clip(y, 0, 1), _phi, _xs)
                        phi_inv = phi_inv_swap
                    hw = _warp_resample(bestH, phi_inv, Nw)
                    hw = _rescale(hw)
                    rw = R_of(hw)
                    cap = min(deadline - 4.0, time.process_time() + 2.0)
                    hp = _lbfgs_log(hw, 100, cap, beta=0.0)
                    rp = R_of(hp)
                    if rp > rw:
                        hw, rw = hp, rp
                    delta = rw - bestR
                    print("  warp w=%.2f c=%.1f dir=%+d -> R=%.9f (delta %.2e)" %
                          (w, c, direction, rw, delta))
                    if rw > warp_bestR + 1e-14:
                        warp_best, warp_bestR = hw.copy(), rw
                except Exception as e:
                    print("  warp error:", e)

    if warp_bestR > bestR + 1e-14:
        bestH, bestR = warp_best.copy(), warp_bestR
        print("warp improved: R=%.9f" % bestR)
    else:
        alternative = warp_best.copy()
        alternativeR = warp_bestR
        print("warp: no improvement (warp R=%.9f vs %.9f)" % (warp_bestR, bestR))

    # ---- Strategy C: alternating fine/peak L-BFGS with occasional flat kicks ----
    it = 0
    loop_end = deadline - 3.0
    since_flat = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        improved = False
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            improved = True
            print("  iter=%d global R=%.9f" % (it, bestR))

        # Occasional flat kick to escape local optima
        if (not improved) and since_flat >= 2 and time.process_time() < loop_end - 3.0:
            since_flat = 0
            cap = min(loop_end, time.process_time() + 3.0)
            hf = _lbfgs_log(bestH, 150, cap, fg=_flat_fg)
            rf = R_of(hf)
            if rf > bestR + 1e-14:
                bestH, bestR = hf.copy(), rf
                print("  iter=%d flat-kick R=%.9f" % (it, bestR))
                improved = True
            else:
                # Try true polish on the flat result (may still improve)
                cap = min(loop_end, time.process_time() + 2.0)
                hp = _lbfgs_log(hf, 100, cap, beta=0.0)
                rp = R_of(hp)
                if rp > bestR + 1e-14:
                    bestH, bestR = hp.copy(), rp
                    print("  iter=%d flat+polish R=%.9f" % (it, bestR))
                    improved = True
        else:
            since_flat += 1

        if (not improved) and time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.07 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("  iter=%d peak frac=%.2f R=%.9f" % (it, frac, bestR))

    # Final polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hs = _lbfgs_log(bestH, 150, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    mx, m, near = _stats(bestH)
    print("final N=%d zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d R=%.9f" %
          (bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near, bestR))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": alternative}
    else:
        return {"best": baseH, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _rho(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_proj(h):
    # objective on the max=1 manifold: -log(num/s^2) with h projected to _rho(h)
    hp = _rho(h)
    s = hp.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(hp)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    g_hp = _backprop(gLf, hp) + 2.0 / s
    # chain through rho: hp = h / sqrt(M(h)), M = max knots(h)
    # dM/dh[a] = 2 * hp[m-1-a] for valid a (knot m = sum_{i+j=m-1} h_i h_j)
    n = h.size
    dM = np.zeros(n)
    lo = max(0, m - n)
    hi = min(n, m)
    # a ranges so that m-1-a in [0, n-1] -> a in [m-n, m-1]
    a_lo = max(0, m - n)
    a_hi = min(n, m)  # exclusive
    if a_hi > a_lo:
        idx = np.arange(a_lo, a_hi)
        dM[idx] = 2.0 * hp[m - 1 - idx]
    # hp = h * M^{-1/2}; d hp_i / d h_j = delta_ij M^{-1/2} - 0.5 h_i M^{-3/2} dM_j
    # grad_h = g_hp . d hp / d h
    proj = np.dot(g_hp, hp)  # = sum g_hp_i h_i M^{-1/2}
    grad = g_hp / np.sqrt(M) - 0.5 * proj * dM / M
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _frac_near_max(h, frac=0.01):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _kick(h, m, width, factor):
    hn = h.copy()
    n = h.size
    lo = max(0, m - width // 2)
    hi = min(n, lo + width)
    if hi <= lo:
        return hn
    hn[lo:hi] *= factor
    return _rescale(hn)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d) frac1%%=%.4f" %
          (bestR, best.size, _frac_near_max(best, 0.01)))

    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        Lf = _knots(best)
        m = int(np.argmax(Lf))
        n = best.size
        # deterministic kicks: (width, factor) list
        kicks = [
            (0, 1.0),                # untweaked
            (max(16, n // 64), 1.02),
            (max(16, n // 64), 0.98),
            (max(16, n // 16), 1.02),
            (max(16, n // 16), 0.98),
            (max(16, n // 4), 1.01),
            (max(16, n // 4), 0.99),
            (max(16, n // 256), 1.02),
        ]
        improved = False
        for (w, fac) in kicks:
            if time.process_time() >= deadline - 1.0:
                break
            if w == 0:
                seed = best.copy()
            else:
                seed = _kick(best, m, w, fac)
            cap = min(deadline - 0.8, time.process_time() + 2.0)
            hp = _lbfgs_log(seed, 150, cap, beta=0.0, fg=_fun_grad_proj)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                improved = True
                print("  proj kick w=%d fac=%.3f R=%.9f" % (w, fac, bestR))
        # exact-R peak-window polish
        for frac in [0.02, 0.05, 0.10]:
            if time.process_time() >= deadline - 0.8:
                break
            free = _peak_window(best, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 1.5)
            hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
            rb = R_of(hb)
            if rb > bestR + 1e-14:
                best, bestR = hb, rb
                improved = True
                print("    polish frac=%.2f R=%.9f" % (frac, bestR))
        # one full exact-R log-height L-BFGS
        if time.process_time() < deadline - 0.8:
            cap = min(deadline - 0.5, time.process_time() + 2.5)
            hp = _lbfgs_log(best, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                improved = True
                print("    full R=%.9f" % bestR)
        print("  cyc=%d R=%.9f frac1%%=%.4f improved=%s" %
              (cycle, bestR, _frac_near_max(best, 0.01), improved))
        if not improved and cycle >= 2:
            # small random-ish kick and continue a couple more cycles
            if cycle >= 4:
                break

    print("final R=%.9f (N=%d) frac1%%=%.4f" %
          (bestR, best.size, _frac_near_max(best, 0.01)))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

