    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _apply_transfer(h, i, j, alpha):
    """Move mass alpha (fraction) from window i to window j."""
    h2 = h.copy()
    mi = h[i].sum()
    if mi <= 0:
        return h2
    h2[i] *= (1.0 - alpha)
    h2[j] += alpha * mi / max(1, j.size)
    return _rescale(h2)


def _best_alpha(h, i, j, baseR, deadline):
    best = h
    bestR = baseR
    for alpha in (0.05, 0.1, 0.2, 0.35, 0.5):
        if time.process_time() > deadline:
            break
        c = _apply_transfer(h, i, j, alpha)
        r = R_of(c)
        if r > bestR:
            best, bestR = c, r
    return best, bestR


def _build_pairs(n, nwin=8):
    edges = np.linspace(0, n, nwin + 1).astype(int)
    wins = [np.arange(edges[k], edges[k + 1]) for k in range(nwin)]
    return wins


def _scan(h, deadline, nwin=8):
    """Try two-window mass transfers and window flattening; return best."""
    n = h.size
    if n < 4 * nwin:
        return h, R_of(h)
    wins = _build_pairs(n, nwin)
    baseR = R_of(h)
    best, bestR = h, baseR
    for i in range(nwin):
        for j in range(nwin):
            if i == j:
                continue
            if time.process_time() > deadline:
                return best, bestR
            c, r = _best_alpha(h, wins[i], wins[j], baseR, deadline)
            if r > bestR:
                best, bestR = c, r
    # window flattening
    for i in range(nwin):
        if time.process_time() > deadline:
            break
        c = h.copy()
        c[wins[i]] = c[wins[i]].mean()
        c = _rescale(c)
        r = R_of(c)
        if r > bestR:
            best, bestR = c, r
    return best, bestR


def _softmax_polish(h, beta, maxiter, deadline):
    """Beta-homotopy: optimize log-sum-exp softmax of f*f knots."""
    if time.process_time() >= deadline - 0.3:
        return h
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def fg(hh):
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(n)
        num, dq, Lf = _num_and_dq(hh)
        # softmax smooth approximation of max
        mx = Lf.max()
        e = np.exp(beta * (Lf - mx))
        Z = e.sum()
        p = e / Z
        logZ = mx + np.log(Z) / beta
        gLf = -dq / num
        gLf += p
        grad = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + logZ
        return val, grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _argmax_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, Lf.size - 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        best = base.copy()
        bestR = R_of(best)
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    def try_new(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f N=%d argmax=%.4f" %
                  (name, bestR, best.size, _argmax_pos(best)))
            return True
        return False

    loop_end = deadline - 0.5
    cycle = 0
    while time.process_time() < loop_end:
        cycle += 1
        # (a) scan pass
        cap = min(loop_end, time.process_time() + 8.0)
        hs, rs = _scan(best, cap, nwin=8)
        try_new("scan c=%d" % cycle, hs)

        # (b) peak-window block L-BFGS at several fracs
        for frac in (0.02, 0.05, 0.10):
            if time.process_time() >= loop_end - 1.0:
                break
            free = _peak_window(best, frac=frac)
            cap = min(loop_end, time.process_time() + 1.5)
            hp = _lbfgs_block(best, free, 120, cap)
            try_new("peak%.2f c=%d" % (frac, cycle), hp)

        # (c) full exact-R log-space L-BFGS
        if time.process_time() < loop_end - 1.0:
            cap = min(loop_end, time.process_time() + 3.0)
            hf = _lbfgs_log(best, 250, cap)
            try_new("full c=%d" % cycle, hf)

        # (d) beta-homotopy softmax polish
        for beta in (1e3, 3e3, 1e4, 3e4, 1e5):
            if time.process_time() >= loop_end - 1.0:
                break
            cap = min(loop_end, time.process_time() + 1.5)
            hb = _softmax_polish(best, beta, 120, cap)
            try_new("beta%.0e c=%d" % (beta, cycle), hb)

        # After first three cycles: single-sided zero/gap revival
        if cycle >= 3 and time.process_time() < loop_end - 2.0:
            n = best.size
            half = n // 2
            right = np.arange(half, n)
            if right.size > 20:
                thr = np.quantile(best[right], 0.20)
                cand = best.copy()
                cand[right[best[right] <= thr]] = 0.0
                cand = _rescale(cand)
                cap = min(loop_end, time.process_time() + 2.0)
                cand = _lbfgs_log(cand, 150, cap)
                try_new("revive c=%d" % cycle, cand)

        if time.process_time() >= loop_end:
            break

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    # Return alternative if genuinely different and not better
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _apply_transfer(h, a1, b1, a2, b2, alpha):
    hn = h.copy()
    m1 = h[a1:b1].sum()
    m2 = h[a2:b2].sum()
    if m1 <= 0 or m2 <= 0:
        return None
    hn[a1:b1] = h[a1:b1] * (1.0 + alpha)
    hn[a2:b2] = h[a2:b2] * (1.0 - alpha * m1 / m2)
    if np.any(hn < 0):
        return None
    return hn


def _best_alpha(h, a1, b1, a2, b2, lo=-0.45, hi=0.45, iters=24):
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    hc = _apply_transfer(h, a1, b1, a2, b2, c)
    hd = _apply_transfer(h, a1, b1, a2, b2, d)
    fc = R_of(hc) if hc is not None else -1.0
    fd = R_of(hd) if hd is not None else -1.0
    for _ in range(iters):
        if fc > fd:
            hi = d; d = c; fd = fc
            c = hi - gr * (hi - lo)
            hc = _apply_transfer(h, a1, b1, a2, b2, c)
            fc = R_of(hc) if hc is not None else -1.0
        else:
            lo = c; c = d; fc = fd
            d = lo + gr * (hi - lo)
            hd = _apply_transfer(h, a1, b1, a2, b2, d)
            fd = R_of(hd) if hd is not None else -1.0
    alpha = 0.5 * (lo + hi)
    ha = _apply_transfer(h, a1, b1, a2, b2, alpha)
    if ha is None:
        return 0.0, h
    return alpha, ha


def _best_flatten(h, a, b, lo=-0.45, hi=0.45, iters=20):
    win = h[a:b]
    if win.size == 0:
        return 0.0, h
    mean = h.mean()
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    def ev(alpha):
        hn = h.copy()
        hn[a:b] = (1.0 - alpha) * win + alpha * mean
        if np.any(hn < 0):
            return -1.0, None
        return R_of(hn), hn
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    fc, hc = ev(c)
    fd, hd = ev(d)
    for _ in range(iters):
        if fc > fd:
            hi = d; d = c; fd = fc; hd = hc
            c = hi - gr * (hi - lo)
            fc, hc = ev(c)
        else:
            lo = c; c = d; fc = fd; hc = hd
            d = lo + gr * (hi - lo)
            fd, hd = ev(d)
    alpha = 0.5 * (lo + hi)
    fa, ha = ev(alpha)
    if ha is None:
        return 0.0, h
    return alpha, ha


def _build_pairs(n, Lf):
    widths = [256, 1024, 4096, 16384]
    stride = 1024
    m = int(np.argmax(Lf))
    starts = list(range(0, max(1, n - 1), stride))
    pairs = []
    seen = set()
    def add(a1, b1, a2, b2):
        if a1 < 0 or b1 > n or a2 < 0 or b2 > n:
            return
        if b1 <= a1 or b2 <= a2:
            return
        if not (b1 <= a2 or b2 <= a1):
            return
        key = (a1, b1, a2, b2)
        if key in seen:
            return
        seen.add(key)
        pairs.append(key)
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = m - w // 2; b2 = a2 + w
            if a2 < 0:
                a2 = 0; b2 = w
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
    plateau_lo = max(0, m - 4096)
    plateau_hi = min(n, m + 4096)
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = plateau_lo; b2 = min(n, plateau_lo + w)
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
            a2 = max(0, plateau_hi - w); b2 = plateau_hi
            add(a1, b1, a2, b2)
            add(a2, b2, a1, b1)
    for w in widths:
        for s in starts:
            a1 = s; b1 = s + w
            a2 = n - s - w; b2 = n - s
            add(a1, b1, a2, b2)
    if len(pairs) > 400:
        idx = np.linspace(0, len(pairs) - 1, 400).astype(int)
        pairs = [pairs[i] for i in idx]
    return pairs


def _scan(h, bestR, deadline, verbose=True):
    n = h.size
    Lf = _knots(h)
    pairs = _build_pairs(n, Lf)
    deltas = []
    best_delta = -np.inf
    best_move = None
    best_h = None
    for (a1, b1, a2, b2) in pairs:
        if time.process_time() >= deadline:
            break
        alpha, hn = _best_alpha(h, a1, b1, a2, b2)
        if hn is None:
            continue
        rn = R_of(hn)
        d = rn - bestR
        deltas.append(d)
        if d > best_delta:
            best_delta = d
            best_move = (a1, b1, a2, b2, alpha)
            best_h = hn
    for w in [256, 1024, 4096, 16384]:
        for s in range(0, max(1, n - 1), 1024):
            if time.process_time() >= deadline:
                break
            a = s; b = min(n, s + w)
            alpha, hn = _best_flatten(h, a, b)
            if hn is None:
                continue
            rn = R_of(hn)
            d = rn - bestR
            deltas.append(d)
            if d > best_delta:
                best_delta = d
                best_move = ('flat', a, b, alpha)
                best_h = hn
    if verbose and deltas:
        arr = np.array(deltas)
        pos = arr[arr > 0]
        nonpos = arr[arr <= 0]
        print("  scan: n=%d best=%.3e pos=%d" %
              (len(arr), best_delta, pos.size))
        if nonpos.size:
            print("    nonpos min=%.3e med=%.3e max=%.3e near0=%d" %
                  (nonpos.min(), np.median(nonpos), nonpos.max(),
                   int(np.sum(np.abs(arr) < 1e-7))))
    return best_delta, best_move, best_h


def _shift(h, delta, direction):
    n = h.size
    if direction > 0:
        hn = (1.0 - delta) * h + delta * np.concatenate((h[1:], [0.0]))
    else:
        hn = (1.0 - delta) * h + delta * np.concatenate(([0.0], h[:-1]))
    return np.clip(hn, 0, None)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10)):
    best = h
    bestR = R_of(h)
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.0)
        hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    deltas = [0.125, 0.25, 0.5, 0.75]
    improved_any = True
    sweep = 0
    while time.process_time() < deadline - 1.0 and improved_any:
        sweep += 1
        improved_any = False
        for delta in deltas:
            for direction in (+1, -1):
                if time.process_time() >= deadline - 1.0:
                    break
                hs = _shift(best, delta, direction)
                rs0 = R_of(hs)
                # 3 s exact-R log-height L-BFGS
                cap = min(deadline - 0.5, time.process_time() + 3.0)
                hp = _lbfgs_log(hs, 200, cap, beta=0.0)
                rp = R_of(hp)
                # peak-window polish
                cap2 = min(deadline - 0.3, time.process_time() + 3.5)
                hp2, rp2 = _polish(hp, cap2)
                argmax_frac = float(np.argmax(_knots(hp2))) / max(1, hp2.size)
                print("  sweep=%d delta=%.3f dir=%+d R0=%.9f Rpol=%.9f argmax=%.3f" %
                      (sweep, delta, direction, rs0, rp2, argmax_frac))
                if rp2 > bestR + 1e-13:
                    best, bestR = hp2, rp2
                    improved_any = True
                    print("    accepted delta=%.3f dir=%+d R=%.9f" %
                          (delta, direction, bestR))
                    break
            if improved_any:
                break
        if improved_any:
            # short scan pass
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            bd, bm, bh = _scan(best, bestR, cap, verbose=True)
            if bd > 1e-13 and bh is not None:
                best = bh
                bestR = R_of(best)
                print("  scan applied delta=%.3e R=%.9f" % (bd, bestR))

    # final polish with remaining time
    while time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("  final polish R=%.9f" % bestR)
        else:
            break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.12f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Multi-resolution polish: start from best, do targeted block LBFGS ----
    polish_round = 0
    while time.process_time() < deadline - 1.0:
        polish_round += 1
        cap = min(deadline - 0.5, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 150, cap)
        rs = R_of(hs)
        if rs > bestRH + 1e-14:
            bestH, bestRH = hs.copy(), rs
            print("polish %d full: R=%.12f" % (polish_round, bestRH))

        if time.process_time() >= deadline - 1.0:
            break
        for frac in (0.03, 0.06, 0.12):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(bestH, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 2.5)
            hp = _lbfgs_block(bestH, free, 80, cap)
            rp = R_of(hp)
            if rp > bestRH + 1e-14:
                bestH, bestRH = hp.copy(), rp
                print("polish %d peak frac=%.2f: R=%.12f" % (polish_round, frac, bestRH))

        # try coarsening then re-refining (explores slightly different basin)
        if time.process_time() < deadline - 3.0:
            hc = 0.5 * (bestH[0::2] + bestH[1::2]) if bestH.size % 2 == 0 else bestH
            if hc.size > 8:
                cap = min(deadline - 0.5, time.process_time() + 2.0)
                hcr = _lbfgs_log(hc, 60, cap)
                hf = np.repeat(hcr, 2)
                if hf.size < bestH.size:
                    hf = np.concatenate((hf, np.zeros(bestH.size - hf.size)))
                else:
                    hf = hf[:bestH.size]
                hf = _rescale(hf)
                rf = R_of(hf)
                if rf > bestRH + 1e-14:
                    bestH, bestRH = hf.copy(), rf
                    print("polish %d coarsen-refine: R=%.12f" % (polish_round, bestRH))

    mx, m, near = _stats(bestH)
    print("final R=%.12f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))
    print("gain vs start: %.3e" % (bestRH - start_bestR))

    if bestRH > start_bestR + 1e-13:
        return {"best": bestH, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _flat_fg(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    c = Lf.max()
    w = Lf * Lf + 1e-12
    diff = Lf - c
    num = np.sum(w * diff * diff)
    den = np.sum(w)
    if den <= 0:
        return 1e18, np.zeros(h.size)
    val = np.log(num / den + 1e-300)
    gLf = 2.0 * w * diff / num
    grad = _backprop(gLf, h)
    return val, grad


def _lbfgs_log_fg(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA A: flat-target descent. Push the whole knot profile toward a flat
    # plateau (minimise weighted variance around the max) which tends to lift R
    # by widening the near-max region, then re-optimise R directly.
    if time.process_time() < deadline - 8.0:
        for frac in (0.0, 0.05, 0.10):
            if time.process_time() >= deadline - 6.0:
                break
            if frac > 0:
                n = best.size
                Lf = _knots(best)
                m = int(np.argmax(Lf))
                half = max(16, int(frac * n))
                lo = max(0, m - half); hi = min(n, m + half)
                hf = _lbfgs_block(best, np.arange(lo, hi), 200, deadline)
            else:
                hf = best
            hf = _lbfgs_log_fg(hf, 300, deadline, _flat_fg)
            hf = _lbfgs_log(hf, 400, deadline)
            r = R_of(hf)
            print("flat frac=%.2f R=%.7f" % (frac, r))
            if r > bestR + 1e-12:
                best, bestR = hf, r

    # NEW IDEA B: multi-resolution coarse-to-fine homotopy on the (possibly
    # flattened) best solution. Coarsen, optimise at low res, then lift back up.
    N = best.size
    levels = []
    for f in (8, 6, 4, 3, 2):
        Nc = max(256, int(N // f))
        if Nc < N:
            levels.append(Nc)
    levels = sorted(set(levels))

    cur = best
    for Nc in levels:
        if time.process_time() >= deadline - 5.0:
            break
        hc = _coarse(best, Nc)
        hc = _rescale(hc)
        hc = _lbfgs_log(hc, 500, deadline)
        hc = _window_polish_peak(hc, deadline, 0.35, 12)
        r = R_of(hc)
        print("coarse N=%d R=%.7f" % (Nc, r))
        cur = hc

    if time.process_time() < deadline - 6.0 and cur.size < N:
        for Nt in levels + [N]:
            if Nt <= cur.size:
                continue
            if time.process_time() >= deadline - 4.0:
                break
            hp = _prolongate(cur, Nt)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 500, deadline)
            hp = _window_polish_peak(hp, deadline, 0.30, 12)
            r = R_of(hp)
            print("lift %d -> R=%.7f" % (Nt, r))
            if r > bestR + 1e-12:
                best, bestR = hp, r
            cur = hp

    # Peak-focused multi-scale polish.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # Phase exploration.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = _lbfgs_log(hp, 400, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-12:
            best, bestR = hp, r

    # Final loop: alternate full and peak polish, with occasional flat push.
    stall = 0
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        improved = False
        h = _lbfgs_log(best, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if it % 3 == 0 and time.process_time() < deadline - 3.0:
            h = _lbfgs_log_fg(best, 200, deadline, _flat_fg)
            h = _lbfgs_log(h, 300, deadline)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h, r
                improved = True
                print("flatR R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
