        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _apply_transfer(h, i, j, alpha):
    h2 = h.copy()
    mi = h[i].sum()
    if mi <= 0:
        return h2
    h2[i] *= (1.0 - alpha)
    h2[j] += alpha * mi / max(1, j.size)
    return _rescale(h2)


def _best_alpha(h, i, j, baseR, deadline):
    best = h
    bestR = baseR
    for alpha in (0.05, 0.1, 0.2, 0.35, 0.5):
        if time.process_time() > deadline:
            break
        c = _apply_transfer(h, i, j, alpha)
        r = R_of(c)
        if r > bestR:
            best, bestR = c, r
    return best, bestR


def _build_pairs(n, nwin=8):
    edges = np.linspace(0, n, nwin + 1).astype(int)
    wins = [np.arange(edges[k], edges[k + 1]) for k in range(nwin)]
    return wins


def _scan(h, deadline, nwin=8):
    n = h.size
    if n < 4 * nwin:
        return h, R_of(h)
    wins = _build_pairs(n, nwin)
    baseR = R_of(h)
    best, bestR = h, baseR
    for i in range(nwin):
        for j in range(nwin):
            if i == j:
                continue
            if time.process_time() > deadline:
                return best, bestR
            c, r = _best_alpha(h, wins[i], wins[j], baseR, deadline)
            if r > bestR:
                best, bestR = c, r
    for i in range(nwin):
        if time.process_time() > deadline:
            break
        c = h.copy()
        c[wins[i]] = c[wins[i]].mean()
        c = _rescale(c)
        r = R_of(c)
        if r > bestR:
            best, bestR = c, r
    return best, bestR


def _argmax_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, Lf.size - 1)


def _decimate_even(h):
    n = h.size
    m = n // 2
    return 0.5 * (h[0:2 * m:2] + h[1:2 * m:2])


def _decimate_odd(h):
    n = h.size
    m = n // 2
    # hM2[i] = 0.5*(h[2i-1] + h[2i]) with boundary handling
    a = np.empty(m)
    b = np.empty(m)
    for i in range(m):
        lo = 2 * i - 1
        hi = 2 * i
        if lo < 0:
            a[i] = h[0]
        else:
            a[i] = h[lo]
        if hi >= n:
            b[i] = h[n - 1]
        else:
            b[i] = h[hi]
    return 0.5 * (a + b)


def _prolongate(hc):
    return np.repeat(hc, 2)


def _coarse_polish(hc, deadline):
    """Optimize at coarse resolution: full log L-BFGS + peak block polish."""
    best = hc.copy()
    bestR = R_of(best)
    # full exact-R log-space L-BFGS
    cap = min(deadline, time.process_time() + 6.0)
    hf = _lbfgs_log(best, 300, cap)
    r = R_of(hf)
    if r > bestR:
        best, bestR = hf, r
    # peak-window block polish
    for frac in (0.02, 0.05, 0.10):
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline, time.process_time() + 2.0)
        hp = _lbfgs_block(best, free, 150, cap)
        r = R_of(hp)
        if r > bestR:
            best, bestR = hp, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        best = base.copy()
        bestR = R_of(best)
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    def try_new(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f N=%d argmax=%.4f" %
                  (name, bestR, best.size, _argmax_pos(best)))
            return True
        return False

    loop_end = deadline - 0.5

    # Coarse-scale experiment: decimate, optimize, prolongate.
    # Try at M = N/2 and M = N/4, both even and odd decimations.
    n_full = best.size
    coarse_levels = []
    if n_full >= 8:
        coarse_levels.append(n_full // 2)
    if n_full >= 16:
        coarse_levels.append(n_full // 4)

    for M in coarse_levels:
        if time.process_time() >= loop_end - 2.0:
            break
        # even decimation
        hM = _decimate_even(best)
        if hM.size != M:
            # fall back: trim/pad
            if hM.size > M:
                hM = hM[:M]
        rM0 = R_of(hM)
        print("coarse M=%d even R=%.9f" % (M, rM0))
        cap = min(loop_end, time.process_time() + 8.0)
        hc, rc = _coarse_polish(hM, cap)
        print("coarse M=%d even polished R=%.9f" % (M, rc))
        # prolongate back to full size
        hp = _prolongate(hc)
        if hp.size != n_full:
            # adjust to n_full
            if hp.size > n_full:
                hp = hp[:n_full]
            else:
                hp = np.concatenate([hp, np.full(n_full - hp.size, hp[-1])])
        hp = _rescale(hp)
        rp0 = R_of(hp)
        cap = min(loop_end, time.process_time() + 3.0)
        hp = _lbfgs_log(hp, 200, cap)
        rp = R_of(hp)
        # one peak polish
        if time.process_time() < loop_end - 1.0:
            free = _peak_window(hp, frac=0.05)
            cap = min(loop_end, time.process_time() + 1.5)
            hp2 = _lbfgs_block(hp, free, 120, cap)
            if R_of(hp2) > rp:
                hp = hp2
                rp = R_of(hp)
        print("prolong even M=%d R=%.9f argmax=%.4f" % (M, rp, _argmax_pos(hp)))
        try_new("prolong-even M=%d" % M, hp)

        if time.process_time() >= loop_end - 2.0:
            break
        # odd decimation
        hM2 = _decimate_odd(best)
        if hM2.size != M:
            if hM2.size > M:
                hM2 = hM2[:M]
        rM0 = R_of(hM2)
        print("coarse M=%d odd R=%.9f" % (M, rM0))
        cap = min(loop_end, time.process_time() + 8.0)
        hc, rc = _coarse_polish(hM2, cap)
        print("coarse M=%d odd polished R=%.9f" % (M, rc))
        hp = _prolongate(hc)
        if hp.size != n_full:
            if hp.size > n_full:
                hp = hp[:n_full]
            else:
                hp = np.concatenate([hp, np.full(n_full - hp.size, hp[-1])])
        hp = _rescale(hp)
        cap = min(loop_end, time.process_time() + 3.0)
        hp = _lbfgs_log(hp, 200, cap)
        rp = R_of(hp)
        if time.process_time() < loop_end - 1.0:
            free = _peak_window(hp, frac=0.05)
            cap = min(loop_end, time.process_time() + 1.5)
            hp2 = _lbfgs_block(hp, free, 120, cap)
            if R_of(hp2) > rp:
                hp = hp2
                rp = R_of(hp)
        print("prolong odd M=%d R=%.9f argmax=%.4f" % (M, rp, _argmax_pos(hp)))
        try_new("prolong-odd M=%d" % M, hp)

    # Final two-window scan at full resolution if time remains
    if time.process_time() < loop_end - 2.0:
        cap = min(loop_end, time.process_time() + 6.0)
        hs, rs = _scan(best, cap, nwin=8)
        try_new("final-scan", hs)

    # If time still remains, keep polishing at full resolution
    cycle = 0
    while time.process_time() < loop_end:
        cycle += 1
        for frac in (0.02, 0.05, 0.10):
            if time.process_time() >= loop_end - 1.0:
                break
            free = _peak_window(best, frac=frac)
            cap = min(loop_end, time.process_time() + 1.5)
            hp = _lbfgs_block(best, free, 120, cap)
            try_new("peak%.2f c=%d" % (frac, cycle), hp)
        if time.process_time() < loop_end - 1.0:
            cap = min(loop_end, time.process_time() + 3.0)
            hf = _lbfgs_log(best, 250, cap)
            try_new("full c=%d" % cycle, hf)
        if time.process_time() >= loop_end:
            break

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _resample(h, n_new):
    n = h.size
    if n_new == n:
        return h.copy()
    edges_old = np.arange(n + 1) / n
    edges_new = np.arange(n_new + 1) / n_new
    cum = np.concatenate(([0.0], np.cumsum(h)))
    I = np.interp(edges_new, edges_old, cum)
    hn = np.diff(I) * (n_new / n)
    return np.clip(hn, 0.0, None)


# ---------- NEW: mass-transfer coordinate ascent on the plateau ----------

def _transfer_scan(h, R, deadline, n_trials=40, rng=None):
    """Try moving mass between two windows; accept if R improves.
    This is a genuinely different move from gradient/GN: it preserves
    total mass and can escape the local shape of the L-inf binding set."""
    if rng is None:
        rng = np.random.default_rng(0)
    n = h.size
    best = h
    bestR = R
    Lf = _knots(best)
    m = int(np.argmax(Lf))
    # windows: symmetric bands around the peak, a few scales
    scales = [max(8, n // 200), max(16, n // 50), max(32, n // 12)]
    for _ in range(n_trials):
        if time.process_time() > deadline:
            break
        sc = scales[rng.integers(len(scales))]
        # window 1 near the peak
        c1 = m + int(rng.integers(-sc, sc + 1))
        a1 = max(0, c1 - sc); b1 = min(n, c1 + sc)
        # window 2: random elsewhere
        c2 = int(rng.integers(0, n))
        a2 = max(0, c2 - sc); b2 = min(n, c2 + sc)
        if b1 - a1 < 1 or b2 - a2 < 1:
            continue
        if not (b1 <= a2 or b2 <= a1):
            continue
        m1 = best[a1:b1].sum(); m2 = best[a2:b2].sum()
        if m1 <= 0 or m2 <= 0:
            continue
        # line search on alpha (fraction of m1 moved)
        for alpha in (0.5, 0.2, 0.05, -0.05, -0.2, -0.5):
            hn = best.copy()
            hn[a1:b1] = best[a1:b1] * (1.0 - alpha)
            hn[a2:b2] = best[a2:b2] + alpha * m1 / (b2 - a2)
            if np.any(hn < 0):
                continue
            hn = _rescale(hn)
            rn = R_of(hn)
            if rn > bestR + 1e-15:
                best, bestR = hn, rn
                Lf = _knots(best)
                m = int(np.argmax(Lf))
                break
    return best, bestR


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    betas = [1.0, 5.0, 20.0, 80.0, 300.0, 1000.0]
    it = 0

    def _polish(h, R, cap_end):
        nonlocal it
        for beta in betas:
            if time.process_time() >= cap_end:
                break
            c = min(cap_end, time.process_time() + 3.0)
            hp = _lbfgs_log(h, 200, c, beta=beta)
            rp = R_of(hp)
            if rp > R + 1e-15:
                h, R = hp, rp
        if time.process_time() < cap_end - 0.5:
            c = min(cap_end, time.process_time() + 2.5)
            hp = _lbfgs_log(h, 200, c, beta=0.0)
            rp = R_of(hp)
            if rp > R + 1e-15:
                h, R = hp, rp
        if time.process_time() < cap_end - 0.5:
            free = _peak_window(h, frac=0.05)
            c = min(cap_end, time.process_time() + 2.0)
            hb = _lbfgs_block(h, free, 150, c)
            rb = R_of(hb)
            if rb > R + 1e-15:
                h, R = hb, rb
        return h, R

    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 10.0)
        best, bestR = _polish(best, bestR, cap)
        print("  polish init R=%.9f" % bestR)

    rng = np.random.default_rng(12345)

    while time.process_time() < deadline - 1.0:
        it += 1
        n_cur = best.size
        target = min(400000, int(n_cur * 1.4) + 256)
        hs = _resample(best, target)
        hs = _rescale(hs)
        rs = R_of(hs)
        cap = min(deadline - 0.5, time.process_time() + 10.0)
        hs, rs = _polish(hs, rs, cap)
        improved = False
        if rs > bestR + 1e-13:
            print("  upsample %d->%d: %.9f -> %.9f" %
                  (n_cur, target, bestR, rs))
            best, bestR = hs, rs
            improved = True

        # NEW: mass-transfer coordinate ascent on the current best
        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.5, time.process_time() + 6.0)
            ht, rt = _transfer_scan(best, bestR, cap, n_trials=60, rng=rng)
            if rt > bestR + 1e-13:
                print("  transfer: %.9f -> %.9f" % (bestR, rt))
                best, bestR = ht, rt
                improved = True
                # polish after transfer
                cap = min(deadline - 0.5, time.process_time() + 6.0)
                best, bestR = _polish(best, bestR, cap)

        if not improved and it % 3 == 0 and n_cur > 4096:
            t2 = max(2048, n_cur // 2)
            hc = _resample(best, t2)
            hc = _rescale(hc)
            rc = R_of(hc)
            cap = min(deadline - 0.5, time.process_time() + 8.0)
            hc, rc = _polish(hc, rc, cap)
            if rc > bestR + 1e-13:
                print("  downsample %d->%d: %.9f -> %.9f" %
                      (n_cur, t2, bestR, rc))
                best, bestR = hc, rc
        print("  iter %d R=%.9f N=%d" % (it, bestR, best.size))

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


def _smooth_shift(h, shift, deadline):
    """Shift the array by fractional `shift` via linear interpolation, then polish."""
    n = h.size
    i = np.arange(n, dtype=float)
    src = i - shift
    lo = np.floor(src).astype(int)
    w = src - lo
    lo_c = np.clip(lo, 0, n - 1)
    hi_c = np.clip(lo + 1, 0, n - 1)
    hn = (1.0 - w) * h[lo_c] + w * h[hi_c]
    return _rescale(hn)


def _symmetric(h):
    """Return symmetrized version (mirror + average)."""
    return _rescale(0.5 * (h + h[::-1]))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n = best.size
    # orient so spike is on left
    left_max = best[:max(1, n // 20)].max()
    right_max = best[n - max(1, n // 20):].max()
    reversed_ = right_max > left_max
    if reversed_:
        work = best[::-1].copy()
        print("  spike on right; operating on reversed array")
    else:
        work = best.copy()
        print("  spike on left")

    bestH = work.copy()
    bestRH = R_of(work)

    # ---- New idea: continuous-shift alignments + symmetrization ----
    # Try small fractional shifts of the profile to break the discrete grid bias,
    # then polish. Also test symmetric version.
    experiment_best = work.copy()
    experiment_bestR = bestRH

    def try_candidate(cand, label):
        nonlocal experiment_best, experiment_bestR
        if time.process_time() >= deadline - 8.0:
            return None
        r = R_of(cand)
        if r > experiment_bestR + 1e-13:
            experiment_best = cand.copy()
            experiment_bestR = r
            print("  NEW %s R=%.9f dR=%+.2e" % (label, r, r - bestRH))
        return r

    # Symmetrized
    try_candidate(_symmetric(work), "sym")

    # Fractional shifts
    for sh in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 8.0:
            break
        try_candidate(_smooth_shift(work, sh, deadline), "shift%.2f" % sh)

    # Polish the best of whatever we found
    if experiment_bestR > bestRH + 1e-13:
        cap_t = min(deadline - 6.0, time.process_time() + 8.0)
        hp, rp = _polish(experiment_best, cap_t, experiment_bestR)
        if rp > experiment_bestR:
            experiment_best, experiment_bestR = hp, rp
            print("  after polish R=%.9f" % experiment_bestR)

    if experiment_bestR > bestRH + 1e-13:
        bestH, bestRH = experiment_best.copy(), experiment_bestR

    # ---- Block-additive moves at multiple block sizes ----
    for B in (128, 256, 512, 1024, 2048):
        if time.process_time() >= deadline - 2.0:
            break
        cap_t = min(deadline - 1.0, time.process_time() + 6.0)
        hb = _block_additive(bestH, B, cap_t, maxiter=200)
        r_raw = R_of(hb)
        if r_raw >= bestRH - 2e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 6.0), bestRH)
        else:
            hp, rp = hb, r_raw
        print("  B=%-4d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # ---- Main loop: alternate L-BFGS-log, peak-window, block-additive ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  iter=%d log R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.5:
            frac = 0.05 + 0.12 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  iter=%d peak R=%.9f" % (it, bestRH))
                continue
        if time.process_time() < loop_end - 2.0 and (it % 3 == 0):
            B = int(2 ** np.random.randint(7, 12))
            cap_t = min(loop_end, time.process_time() + 3.0)
            hb = _block_additive(bestH, B, cap_t, maxiter=100)
            rb = R_of(hb)
            if rb > bestRH + 1e-13:
                bestH, bestRH = hb.copy(), rb
                print("  iter=%d block B=%d R=%.9f" % (it, B, bestRH))

    if reversed_:
        bestH = bestH[::-1].copy()
        experiment_best = experiment_best[::-1].copy()

    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _apply_transfer(h, i, j, alpha):
    h2 = h.copy()
    mi = h[i].sum()
    if mi <= 0:
        return h2
    h2[i] *= (1.0 - alpha)
    h2[j] += alpha * mi / max(1, j.size)
    return _rescale(h2)


def _best_alpha(h, i, j, baseR, deadline):
    best = h
    bestR = baseR
    for alpha in (0.05, 0.1, 0.2, 0.35, 0.5):
        if time.process_time() > deadline:
            break
        c = _apply_transfer(h, i, j, alpha)
        r = R_of(c)
        if r > bestR:
            best, bestR = c, r
    return best, bestR


def _build_pairs(n, nwin=8):
    edges = np.linspace(0, n, nwin + 1).astype(int)
    wins = [np.arange(edges[k], edges[k + 1]) for k in range(nwin)]
    return wins


def _scan(h, deadline, nwin=8):
    n = h.size
    if n < 4 * nwin:
        return h, R_of(h)
    wins = _build_pairs(n, nwin)
    baseR = R_of(h)
    best, bestR = h, baseR
    for i in range(nwin):
        for j in range(nwin):
            if i == j:
                continue
            if time.process_time() > deadline:
                return best, bestR
            c, r = _best_alpha(h, wins[i], wins[j], baseR, deadline)
            if r > bestR:
                best, bestR = c, r
    for i in range(nwin):
        if time.process_time() > deadline:
            break
        c = h.copy()
        c[wins[i]] = c[wins[i]].mean()
        c = _rescale(c)
        r = R_of(c)
        if r > bestR:
            best, bestR = c, r
    return best, bestR


def _argmax_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, Lf.size - 1)


def _decimate_even(h):
    n = h.size
    m = n // 2
    return 0.5 * (h[0:2 * m:2] + h[1:2 * m:2])


def _decimate_odd(h):
    n = h.size
    m = n // 2
    a = np.empty(m)
    b = np.empty(m)
    for i in range(m):
        lo = 2 * i - 1
        hi = 2 * i
        if lo < 0:
            a[i] = h[0]
        else:
            a[i] = h[lo]
        if hi >= n:
            b[i] = h[n - 1]
        else:
            b[i] = h[hi]
    return 0.5 * (a + b)


def _prolongate(hc):
    return np.repeat(hc, 2)


def _coarse_polish(hc, deadline):
    best = hc.copy()
    bestR = R_of(best)
    cap = min(deadline, time.process_time() + 6.0)
    hf = _lbfgs_log(best, 300, cap)
    r = R_of(hf)
    if r > bestR:
        best, bestR = hf, r
    for frac in (0.02, 0.05, 0.10):
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline, time.process_time() + 2.0)
        hp = _lbfgs_block(best, free, 150, cap)
        r = R_of(hp)
        if r > bestR:
            best, bestR = hp, r
    return best, bestR


# ---- New helpers for the experiment ----

def _block_average(h, k, offset):
    """h_k[i] = mean(h[k*i+offset : k*i+offset+k]), edge trimmed."""
    n = h.size
    start = offset
    if start >= n:
        return None
    m = (n - start) // k
    if m < 4:
        return None
    idx = start + np.arange(m)[:, None] * k + np.arange(k)[None, :]
    return h[idx].mean(axis=1)


def _prolongate_block(hc, k, offset, n_full):
    """Mass-preserving piecewise-constant resampling back to n_full."""
    m = hc.size
    out = np.empty(n_full)
    start = offset
    # fill [start : start + m*k] with repeated values
    end = start + m * k
    end = min(end, n_full)
    seg = np.repeat(hc, k)[:end - start]
    out[start:end] = seg
    # edges: pad with nearest
    if start > 0:
        out[:start] = hc[0]
    if end < n_full:
        out[end:] = hc[-1]
    return _rescale(out)


def _coarse_polish_fast(hc, deadline):
    """Lighter coarse polish: one log L-BFGS + a couple peak blocks."""
    best = hc.copy()
    bestR = R_of(best)
    cap = min(deadline, time.process_time() + 4.0)
    hf = _lbfgs_log(best, 200, cap)
    r = R_of(hf)
    if r > bestR:
        best, bestR = hf, r
    for frac in (0.03, 0.08):
        if time.process_time() >= deadline - 0.4:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline, time.process_time() + 1.5)
        hp = _lbfgs_block(best, free, 120, cap)
        r = R_of(hp)
        if r > bestR:
            best, bestR = hp, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        best = base.copy()
        bestR = R_of(best)
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    def try_new(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f N=%d argmax=%.4f" %
                  (name, bestR, best.size, _argmax_pos(best)))
            return True
        return False

    loop_end = deadline - 0.5
    n_full = best.size

    # ---- Experiment: repeated multi-factor, multi-offset coarse cycles ----
    cycle = 0
    while time.process_time() < loop_end - 3.0:
        cycle += 1
        improved_this_cycle = False
        for k in (2, 3, 4):
            if time.process_time() >= loop_end - 3.0:
                break
            for offset in range(k):
                if time.process_time() >= loop_end - 3.0:
                    break
                hk = _block_average(best, k, offset)
                if hk is None:
                    continue
                rk0 = R_of(hk)
                # gate: only polish if coarse R is reasonably close
                if rk0 < bestR - 1e-4:
                    continue
                cap = min(loop_end, time.process_time() + 4.0)
                hc, rc = _coarse_polish_fast(hk, cap)
                hp = _prolongate_block(hc, k, offset, n_full)
                # short full-resolution polish
                cap = min(loop_end, time.process_time() + 2.5)
                hp = _lbfgs_log(hp, 150, cap)
                rp = R_of(hp)
                if rp > bestR + 1e-14:
                    if try_new("k=%d o=%d c=%d" % (k, offset, cycle), hp):
                        improved_this_cycle = True
                # occasionally run a scan pass on the improved candidate
                if improved_this_cycle and time.process_time() < loop_end - 2.0:
                    cap = min(loop_end, time.process_time() + 2.0)
                    hs, rs = _scan(best, cap, nwin=6)
                    try_new("scan k=%d o=%d" % (k, offset), hs)
        if not improved_this_cycle:
            # try a full-resolution polish to squeeze more
            if time.process_time() < loop_end - 2.0:
                cap = min(loop_end, time.process_time() + 3.0)
                hf = _lbfgs_log(best, 250, cap)
                try_new("full c=%d" % cycle, hf)
            # if still no improvement, break to avoid spinning
            if not improved_this_cycle and time.process_time() > loop_end - 6.0:
                break

    # ---- Final polish loop at full resolution ----
    while time.process_time() < loop_end:
        cycle += 1
        for frac in (0.02, 0.05, 0.10):
            if time.process_time() >= loop_end - 1.0:
                break
            free = _peak_window(best, frac=frac)
            cap = min(loop_end, time.process_time() + 1.5)
            hp = _lbfgs_block(best, free, 120, cap)
            try_new("peak%.2f c=%d" % (frac, cycle), hp)
        if time.process_time() < loop_end - 1.0:
            cap = min(loop_end, time.process_time() + 3.0)
            hf = _lbfgs_log(best, 250, cap)
            try_new("full c=%d" % cycle, hf)
        if time.process_time() >= loop_end:
            break

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=1500):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _restrict(h_big, N_small):
    """Coarsen by averaging blocks (mass-preserving)."""
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    edges = np.linspace(0, n, N_small + 1).astype(int)
    out = np.empty(N_small)
    for i in range(N_small):
        a, b = edges[i], edges[i + 1]
        out[i] = h_big[a:b].mean() if b > a else 0.0
    # preserve total mass
    if out.sum() > 0:
        out *= h_big.sum() / out.sum()
    return out


def _perturb(h, rng, scale=0.03, nmodes=6):
    """Multiplicative low-frequency perturbation to escape local optima."""
    n = h.size
    x = np.linspace(0, 1, n)
    pert = np.zeros(n)
    for _ in range(nmodes):
        k = rng.integers(1, 8)
        ph = rng.uniform(0, 2 * np.pi)
        amp = rng.uniform(0.3, 1.0)
        pert += amp * np.sin(2 * np.pi * k * x + ph)
    if pert.max() - pert.min() > 0:
        pert = pert / (pert.max() - pert.min())
    h2 = h * (1.0 + scale * pert)
    return _rescale(np.clip(h2, 0, None))


def _refine(h, deadline, fg=None, maxiter=4000):
    """Log -> pnorm -> true-inf chain."""
    if time.process_time() >= deadline - 0.5:
        return h
    h = _lbfgs_log(h, maxiter=maxiter, deadline=deadline, fg=fg)
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(h, np.arange(h.size), maxiter=maxiter, deadline=deadline)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(12345)

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(200)
        best_r = R_of(best)

    base = best.copy()
    base_r = best_r

    def try_improve(cand, tol=1e-12):
        nonlocal best, best_r
        if cand is None:
            return False
        r = R_of(cand)
        if r > best_r + tol:
            best, best_r = cand.copy(), r
            return True
        return False

    # --- Phase 1: strong polish of start via pnorm chain (the core idea) ---
    if time.process_time() < deadline - 1.0:
        sub = time.process_time() + (deadline - time.process_time()) * 0.25
        for p in (12.0, 6.0, 3.0):
            if time.process_time() >= sub - 0.5:
                break
            fg = (lambda h, _p=p: _fun_grad_pnorm(h, _p))
            cand = _lbfgs_log(best, maxiter=5000, deadline=sub, fg=fg)
            try_improve(cand)
        try_improve(_lbfgs_block(best, np.arange(best.size),
                                 maxiter=6000, deadline=sub))

    # --- Phase 2: basin-hopping with perturbations on current grid ---
    n_restarts = 0
    while time.process_time() < deadline - 2.0:
        n_restarts += 1
        # alternate perturbation size; use progressively smaller steps
        scale = 0.05 if n_restarts % 3 == 1 else (0.02 if n_restarts % 3 == 2 else 0.01)
        cand = _perturb(best, rng, scale=scale, nmodes=rng.integers(2, 8))
        sub = min(deadline - 1.0,
                  time.process_time() + max(2.0, (deadline - time.process_time()) * 0.4))
        # quick smoothed then true polish
        fg = (lambda h: _fun_grad_pnorm(h, 6.0))
        cand = _lbfgs_log(cand, maxiter=3000, deadline=sub, fg=fg)
        cand = _lbfgs_block(cand, np.arange(cand.size), maxiter=3000, deadline=sub)
        try_improve(cand, tol=1e-10)

    # --- Phase 3: prolongate to finer grid and polish ---
    if time.process_time() < deadline - 4.0 and best.size < 40000:
        N_big = min(40000, best.size * 2)
        h_big = _prolongate(best, N_big)
        sub = min(deadline - 1.0,
                  time.process_time() + (deadline - time.process_time()) * 0.5)
        fg = (lambda h: _fun_grad_pnorm(h, 6.0))
        cand = _lbfgs_log(h_big, maxiter=4000, deadline=sub, fg=fg)
        cand = _lbfgs_block(cand, np.arange(cand.size), maxiter=4000, deadline=sub)
        if R_of(cand) > best_r + 1e-12:
            best, best_r = cand, R_of(cand)

    # --- Phase 4: final true-inf polish, plus peak-window ---
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_block(best, np.arange(best.size),
                            maxiter=8000, deadline=deadline)
        try_improve(cand)
    for frac, extra in [(0.5, 4), (0.2, 3), (0.08, 2)]:
        if time.process_time() >= deadline - 0.5:
            break
        sub = min(deadline - 0.3,
                  time.process_time() + (deadline - time.process_time()) * 0.5)
        try_improve(_window_polish_peak(best, sub, frac, extra, maxiter=2000))

    if base_r >= best_r:
        return {"best": base, "alternative": best}
    return {"best": best, "alternative": base}

