    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, bestR):
    best = h
    r = R_of(best)
    if r <= bestR:
        return best, r
    bestR = r
    if time.process_time() < deadline - 0.3:
        cap = min(deadline - 0.2, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 150, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
    for frac in (0.02, 0.05, 0.10):
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.0)
        hb = _lbfgs_block(best, free, 80, cap)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    return best, bestR


# ---------- spectral edge-blend proposals ----------

def _spectral_h(gt, N, rng, n_seeds, zero_phase=True):
    M = next_fast_len(2 * N - 1)
    tgt = np.zeros(M)
    tgt[:gt.size] = gt
    F = np.fft.rfft(tgt)
    amp = np.sqrt(np.abs(F))
    nf = amp.size
    out = []
    if zero_phase:
        Fh = amp.astype(complex)
        hf = np.fft.irfft(Fh, n=M)
        out.append(_trim(hf, N))
    for s in range(n_seeds):
        phi = rng.uniform(-np.pi, np.pi, nf)
        phi[0] = 0.0
        Fh = amp * np.exp(1j * phi)
        hf = np.fft.irfft(Fh, n=M)
        out.append(_trim(hf, N))
    return out


def _trim(hfull, N):
    if hfull.size >= N:
        h = hfull[:N].copy()
    else:
        h = np.zeros(N)
        h[:hfull.size] = hfull
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return None
    return _rescale(h)


def _edge_regions(N):
    e = max(1, int(0.10 * N))
    left = np.arange(0, e)
    right = np.arange(N - e, N)
    both = np.concatenate([left, right])
    return [("L", left), ("R", right), ("B", both)]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(20240808)
    N = best.size
    g = _knots(best)
    c = g.max()

    # Build target f*f shapes
    targets = []
    for gamma in (0.5, 0.3, 0.15):
        gt = c * np.clip(g / c, 0.0, 1.0) ** gamma
        gt = np.where(g > 0, gt, 0.0)
        targets.append(("pow%.2f" % gamma, gt))
    gt = np.minimum(c, g + 0.5 * (c - g))
    targets.append(("sh0.5", gt))
    gt = np.minimum(c, g + 1.0 * (c - g))
    targets.append(("sh1.0", gt))

    # Generate spectral candidates
    cands = []
    for name, gt in targets:
        hs = _spectral_h(gt, N, rng, n_seeds=4, zero_phase=True)
        for k, hc in enumerate(hs):
            if hc is not None:
                cands.append((name, k, hc))
    print("spectral cands: %d" % len(cands))

    regions = _edge_regions(N)
    alphas = (0.05, 0.10, 0.20, 0.35, 1.0)

    # Build blends and prefilter on raw R
    blends = []
    for name, k, hc in cands:
        for rname, idx in regions:
            for alpha in alphas:
                hnew = best.copy()
                hnew[idx] = (1.0 - alpha) * best[idx] + alpha * hc[idx]
                hnew = _rescale(hnew)
                r = R_of(hnew)
                blends.append((r, name, k, rname, alpha, hnew))
    blends.sort(key=lambda x: -x[0])
    print("blends: %d, top raw R=%.9f" % (len(blends), blends[0][0] if blends else -1))

    # Track best per family for reporting
    family_best = {}

    top = blends[:8]
    for i, (r0, name, k, rname, alpha, hnew) in enumerate(top):
        if time.process_time() >= deadline - 1.0:
            break
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        hp, rp = _polish(hnew, cap, bestR)
        key = "%s/%s/a%.2f" % (name, rname, alpha)
        family_best[key] = max(family_best.get(key, 0.0), rp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            print("  blend %s R=%.9f (raw %.9f)" % (key, bestR, r0))

    # Report family bests
    if family_best:
        top_fam = sorted(family_best.items(), key=lambda x: -x[1])[:6]
        for kk, vv in top_fam:
            print("  fam %s -> %.9f" % (kk, vv))

    # Use remaining budget: re-polish best and try new phase seeds on best family
    while time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hp = _lbfgs_log(best, 200, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            print("  polish full R=%.9f" % bestR)
        else:
            break
        for frac in (0.02, 0.05, 0.10):
            if time.process_time() >= deadline - 0.5:
                break
            free = _peak_window(best, frac=frac)
            cap = min(deadline - 0.3, time.process_time() + 1.0)
            hb = _lbfgs_block(best, free, 100, cap)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
                print("    polish frac=%.2f R=%.9f" % (frac, bestR))

    # Extra: new phase seeds on best target, edge blend with small alpha, polish
    if time.process_time() < deadline - 1.0:
        gt = np.minimum(c, g + 0.5 * (c - g))
        for trial in range(20):
            if time.process_time() >= deadline - 1.0:
                break
            hs = _spectral_h(gt, N, rng, n_seeds=1, zero_phase=False)
            hc = hs[0]
            if hc is None:
                continue
            for rname, idx in regions:
                for alpha in (0.05, 0.10, 0.20):
                    hnew = best.copy()
                    hnew[idx] = (1.0 - alpha) * best[idx] + alpha * hc[idx]
                    hnew = _rescale(hnew)
                    r0 = R_of(hnew)
                    if r0 < bestR - 0.02:
                        continue
                    cap = min(deadline - 0.5, time.process_time() + 2.0)
                    hp, rp = _polish(hnew, cap, bestR)
                    if rp > bestR + 1e-15:
                        best, bestR = hp, rp
                        print("  seed blend %s a%.2f R=%.9f" % (rname, alpha, bestR))

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _halve(h):
    n = h.size
    if n < 2:
        return h
    m = n // 2
    a = h[:2 * m].reshape(m, 2)
    return a.sum(axis=1)


def _double(h):
    return np.repeat(h, 2)


def _upsample(h, factor):
    # linear-ish upsample by factor via cumulative mass resampling
    n = h.size
    if factor <= 1:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return h.copy()
    c /= total
    newn = n * factor
    newx = np.arange(newn + 1, dtype=float) * (n / float(newn))
    cv = np.interp(newx, np.arange(n + 1, dtype=float), c)
    out = np.diff(cv)
    return np.clip(out, 0.0, None)


def _polish(h, deadline, budget, betas=(0.0, 1e3, 1e4)):
    best = h.copy()
    bestR = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        cap = min(deadline - 0.3, time.process_time() + budget / max(1, len(betas)))
        hs = _lbfgs_log(best, 200, cap, beta=beta)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            best, bestR = hs.copy(), rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.05)
        cap = min(deadline - 0.3, time.process_time() + budget / 3.0)
        hp = _lbfgs_block(best, free, 150, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    expH = baseH.copy()
    expR = baseR

    def try_update(hcand, tag):
        nonlocal bestH, bestR, expH, expR
        rc = R_of(hcand)
        if rc > bestR + 1e-15:
            bestH, bestR = hcand.copy(), rc
            print("  [%s] NEW best R=%.9f (+%.2e)" % (tag, bestR, bestR - baseR))
        if rc > expR + 1e-15 and rc <= bestR + 1e-15:
            expH, expR = hcand.copy(), rc
        return rc

    # ---- Resolution ladder: try doubling then polishing ----
    # This is the key new idea: the current best may be over-coarsened relative
    # to the true optimum, so refining resolution and re-polishing can help.
    if time.process_time() < deadline - 6.0:
        n = bestH.size
        if n * 2 <= 1_000_000:
            hd = _upsample(bestH, 2)
            hd = _rescale(hd)
            rd = R_of(hd)
            print("  [double] raw R=%.9f (delta %.2e)" % (rd, rd - bestR))
            cap = min(deadline - 4.0, time.process_time() + 6.0)
            hp, rp = _polish(hd, cap, 6.0)
            print("  [double] polished R=%.9f" % rp)
            try_update(hp, "double")
            if rp > bestR - 1e-12:
                # even if not improved, keep for experimentation
                if rp > expR + 1e-15:
                    expH, expR = hp.copy(), rp

    # ---- Global polish of current best ----
    if time.process_time() < deadline - 4.0:
        cap = min(deadline - 2.0, time.process_time() + 6.0)
        hp, rp = _polish(bestH, cap, 6.0)
        print("  [polish0] R=%.9f" % rp)
        try_update(hp, "polish0")

    # ---- Coordinate-wise refinement: small-peak windows at finer scales ----
    improved_round = 0
    while time.process_time() < deadline - 3.0 and improved_round < 6:
        improved_round += 1
        prevR = bestR
        for frac in (0.02, 0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 2.0:
                break
            free = _peak_window(bestH, frac=frac)
            cap = min(deadline - 1.0, time.process_time() + 2.0)
            hb = _lbfgs_block(bestH, free, 120, cap, beta=0.0)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                bestH, bestR = hb.copy(), rb
                print("  [peak %.2f] R=%.9f (+%.2e)" % (frac, bestR, bestR - prevR))
                try_update(hb, "peak")
        # beta ladder occasionally
        if time.process_time() < deadline - 4.0 and improved_round % 2 == 0:
            for beta in (1e3, 1e4):
                cap = min(deadline - 1.0, time.process_time() + 2.0)
                hs = _lbfgs_log(bestH, 150, cap, beta=beta)
                rs = R_of(hs)
                if rs > bestR + 1e-15:
                    bestH, bestR = hs.copy(), rs
                    print("  [beta %.0e] R=%.9f" % (beta, bestR))
                    try_update(hs, "beta")
        if bestR - prevR < 1e-10:
            break

    # ---- Final full polish ----
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            bestH, bestR = hs.copy(), rs
            try_update(hs, "final")

    print("final best R=%.9f (base %.9f, delta %.2e)" %
          (bestR, baseR, bestR - baseR))
    mx, m, near = _stats(bestH)
    print("final N=%d zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": expH}

