        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _refine(h, deadline, bestR, log):
    """Full log-height L-BFGS then peak-window block polish, until deadline."""
    best = h
    while time.process_time() < deadline - 0.6:
        cap = min(deadline - 0.4, time.process_time() + 3.0)
        hp = _lbfgs_log(best, 300, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            log("    full R=%.9f" % bestR)
        else:
            break
        for frac in (0.01, 0.02, 0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 0.4:
                break
            free = _peak_window(best, frac=frac)
            cap = min(deadline - 0.3, time.process_time() + 1.0)
            hb = _lbfgs_block(best, free, 150, cap)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
                log("    frac=%.2f R=%.9f" % (frac, bestR))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    lines = []
    def log(s):
        lines.append(s)
        if len(lines) <= 40:
            print(s)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 1: polish the start thoroughly (main work).
    best, bestR = _refine(best, deadline, bestR, log)
    print("after refine R=%.9f" % bestR)

    # Phase 2: if time remains, try a resolution increase (upsample + polish).
    if time.process_time() < deadline - 3.0 and bestR > start_bestR:
        try:
            n = best.size
            n2 = min(1000000, int(n * 1.5))
            x_old = (np.arange(n) + 0.5) / n
            x_new = (np.arange(n2) + 0.5) / n2
            hu = np.interp(x_new, x_old, best)
            hu = _rescale(hu)
            ru = R_of(hu)
            if ru > bestR - 0.01:
                cap = min(deadline - 0.5, time.process_time() + 8.0)
                hp = _lbfgs_log(hu, 400, cap)
                rp = R_of(hp)
                if rp > bestR + 1e-13:
                    best, bestR = hp, rp
                    print("upsampled N=%d R=%.9f" % (n2, bestR))
                    best, bestR = _refine(best, deadline, bestR, log)
        except Exception:
            pass

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h, beta=0.0):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if beta > 0:
        mx = Lf.max()
        if mx > 0:
            e = np.exp(beta * (Lf - mx))
            Z = e.sum()
            if Z > 0:
                w = e / Z
                sm = mx + np.log(Z) / beta
                gLf = -dq / num + w / sm
                grad = _backprop(gLf, h) + 2.0 / s
                val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
                return val, grad
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prolongate(h, N2):
    n = h.size
    if n == N2:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N2)
    old_x = np.arange(n + 1) / n
    new_x = np.arange(N2 + 1) / N2
    mass = np.interp(new_x, old_x, c)
    h2 = np.diff(mass) * N2
    return np.clip(h2, 0, None)


def _refine(h, deadline, budget_seconds, start_bestR, start_best):
    """Iterated full log-LBFGS + peak window polishes."""
    best = h.copy()
    bestR = R_of(best)
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h1 = _lbfgs_log(best, 400, deadline)
        r1 = R_of(h1)
        improved = False
        if r1 > bestR + 1e-13:
            best, bestR = h1, r1
            improved = True
        for frac in (0.02, 0.04, 0.08, 0.15):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(best, frac)
            hp = _lbfgs_block(best, free, 250, deadline)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                improved = True
        if not improved and it > 2:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Try a prolongated refinement in parallel to the direct refinement of the
    # start.  Higher resolution can capture structure the coarse grid misses.
    candidates = [(best.copy(), bestR)]

    N2 = min(170000, max(best.size * 2, best.size))
    if N2 != best.size and time.process_time() < deadline - 20.0:
        h_pro = _rescale(_prolongate(best, N2))
        r_pro = R_of(h_pro)
        print("prolongated R=%.7f (N=%d)" % (r_pro, h_pro.size))
        candidates.append((h_pro, r_pro))

    # Refine whichever candidate is best; use remaining time to iterate.
    # Give the prolongated version a dedicated refinement pass if we have time.
    results = []
    for idx, (cand, r_c) in enumerate(candidates):
        if time.process_time() >= deadline - 3.0:
            results.append((cand, r_c))
            continue
        # split the remaining budget generously to the bigger grid
        if idx == 0 and len(candidates) > 1:
            sub_deadline = min(deadline - 5.0,
                               time.process_time() + (deadline - time.process_time()) * 0.45)
        else:
            sub_deadline = deadline
        h_ref, r_ref = _refine(cand, sub_deadline, budget_seconds, start_bestR, start_best)
        print("refined[%d] R=%.7f (N=%d)" % (idx, r_ref, h_ref.size))
        results.append((h_ref, r_ref))

    # Pick the best; if it's the higher-resolution version and it wins, keep it.
    results.sort(key=lambda x: x[1], reverse=True)
    best, bestR = results[0][0], results[0][1]

    # Final polish on the winner with any remaining time.
    if time.process_time() < deadline - 2.0:
        h_fin, r_fin = _refine(best, deadline, budget_seconds, start_bestR, start_best)
        if r_fin > bestR:
            best, bestR = h_fin, r_fin

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_proj(h):
    """Objective on the max=1 manifold: h is rescaled so max knot = 1."""
    hp = _rescale(h)
    s = hp.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(hp)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    g_hp = _backprop(gLf, hp) + 2.0 / s
    n = h.size
    dM = np.zeros(n)
    a_lo = max(0, m - n)
    a_hi = min(n, m)
    if a_hi > a_lo:
        idx = np.arange(a_lo, a_hi)
        dM[idx] = 2.0 * hp[m - 1 - idx]
    proj = np.dot(g_hp, hp)
    grad = g_hp / np.sqrt(M) - 0.5 * proj * dM / M
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad_proj

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad_proj

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _polish(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 400, min(deadline - 0.3, time.process_time() + 8.0))
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.10)
        hs = _lbfgs_block(best, free, 200, min(deadline - 0.3, time.process_time() + 5.0))
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


# ---------- Gauss-Newton on near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=60):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(30):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn
        alpha *= 0.4
    return h, bestR


def _gn_plateau(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002, 0.001]
    lams = [1e-8, 1e-6, 1e-4, 1e-2]
    stall = 0
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-15:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
            if time.process_time() < deadline - 1.0:
                cap = min(deadline, time.process_time() + 2.0)
                hp, rp = _polish(best, cap)
                if rp > bestR:
                    best, bestR = hp, rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n_fine = best.size
    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Phase 1: coarsen and GN on multiple scales ----
    scales = []
    hs = bestH
    for _ in range(4):
        hs = _coarsen(hs)
        if hs.size < 64:
            break
        scales.append(hs.copy())

    for hc in reversed(scales):
        if time.process_time() >= deadline - 3.0:
            break
        gn_cap = min(deadline - 2.0, time.process_time() + budget_seconds * 0.10)
        gh, gr = _gn_plateau(hc, gn_cap)
        print("GN scale N=%d end: R=%.9f" % (hc.size, gr))
        if gr > R_of(hc) + 1e-14:
            hf = _prolongate(gh, n_fine)
            rf = R_of(hf)
            if time.process_time() < deadline - 3.0:
                cap = min(deadline - 2.0, time.process_time() + 4.0)
                hp, rp = _polish(hf, cap)
                if rp > experiment_bestR + 1e-14:
                    experiment_best, experiment_bestR = hp.copy(), rp
                if rp > bestRH + 1e-14:
                    bestH, bestRH = hp.copy(), rp
                    print("  NEW BEST R=%.9f (scale %d)" % (bestRH, hc.size))

    # ---- Phase 2: upsampling refinement ladder ----
    ladder = [n_fine * 2, n_fine * 4, n_fine * 8, n_fine * 12, n_fine * 16]
    ladder = [n for n in ladder if n <= 1000000]
    for target in ladder:
        if time.process_time() >= deadline - 8.0:
            break
        if bestH.size >= target:
            continue
        hu = _prolongate(bestH, target)
        ru = R_of(hu)
        cap = min(deadline - 4.0, time.process_time() + 6.0)
        hp = _lbfgs_log(hu, 250, cap)
        rp = R_of(hp)
        if rp < ru:
            hp, rp = hu, ru
        if time.process_time() < deadline - 3.0:
            cap = min(deadline - 2.0, time.process_time() + 4.0)
            hg, rg = _gn_plateau(hp, cap)
            if rg > rp:
                hp, rp = hg, rg
        if rp > bestRH + 1e-14:
            bestH, bestRH = hp.copy(), rp
            if rp > experiment_bestR + 1e-14:
                experiment_best, experiment_bestR = hp.copy(), rp
            print("  ladder NEW BEST N=%d R=%.9f" % (bestH.size, bestRH))

    # ---- Phase 3: full-N alternating L-BFGS/GN passes ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 3.5)
        hs = _lbfgs_log(bestH, 250, cap_t)
        rs = R_of(hs)
        if rs > bestRH + 1e-14:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
        if time.process_time() < loop_end - 1.5:
            gn_cap = min(loop_end, time.process_time() + 3.0)
            gh, gr = _gn_plateau(bestH, gn_cap)
            if gr > bestRH + 1e-14:
                bestH, bestRH = gh, gr
                print("  loop GN iter=%d R=%.9f" % (it, bestRH))
                continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.12 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 200, cap_t)
            rp = R_of(hp)
            if rp > bestRH + 1e-14:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else bestH
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": bestH, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_mean_and_grad(Lf, k):
    n = Lf.size
    if k >= n:
        idx = np.arange(n)
    else:
        idx = np.argpartition(-Lf, k - 1)[:k]
    m = Lf[idx].mean()
    g = np.zeros_like(Lf)
    g[idx] = 1.0 / idx.size
    return m, g


def _fun_grad_topk(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m, gm = _topk_mean_and_grad(Lf, k)
    if m <= 0:
        return _fun_grad(h)
    gLf = -dq / num + gm / m
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(m)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, tag):
    """Exact-R polish: full L-BFGS then peak-window block polish."""
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in [0.02, 0.05, 0.10]:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.0)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    cand = best.copy()
    candR = bestR

    k_ladders = [
        [64, 256, 1024, 4096, 16384, 65536],
        [32, 128, 512, 2048, 8192, 32768],
        [16, 64, 256, 1024, 4096, 16384],
    ]

    sweep = 0
    while time.process_time() < hard - 3.0:
        ks = k_ladders[sweep % len(k_ladders)]
        sweep += 1
        improved_this_sweep = False
        for k in ks:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, kk=k: _fun_grad_topk(hh, kk))
            cap = min(hard - 2.0, time.process_time() + 4.0)
            hk = _lbfgs_log(cand, 150, cap, fg=fg)
            # Rk value
            Lf = _knots(hk)
            mk, _ = _topk_mean_and_grad(Lf, min(k, Lf.size))
            rk = R_of(hk)
            # unconditional exact-R polish
            hp, rp = _polish(hk, min(hard - 1.0, time.process_time() + 3.0),
                             "k%d" % k)
            beat = rp > candR + 1e-9
            print("  [sweep%d k=%5d] Rk=%.9f exact=%.9f polish=%.9f %s" %
                  (sweep, k, rk, rk, rp, "BEAT" if beat else ""))
            if beat:
                cand, candR = hp, rp
                improved_this_sweep = True
                if candR > bestR + 1e-15:
                    best, bestR = cand.copy(), candR
                    print("    new best R=%.9f" % bestR)
        if not improved_this_sweep and sweep > len(k_ladders):
            # small perturbation: try from best with a fresh full polish
            if time.process_time() < hard - 3.0:
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hp = _lbfgs_log(cand, 300, cap, fg=_fun_grad)
                rp = R_of(hp)
                if rp > candR + 1e-12:
                    cand, candR = hp, rp
                    if candR > bestR + 1e-15:
                        best, bestR = cand.copy(), candR

    # Final exact-R polish of the best
    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard, "final")
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": cand if candR > start_bestR else start_best}
    else:
        return {"best": start_best, "alternative": cand}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- flat-target objective (drives a broad top on f*f) ----------

def _flat_fg(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    c = Lf.max()
    w = Lf * Lf + 1e-12
    diff = Lf - c
    num = np.sum(w * diff * diff)
    den = np.sum(w)
    if den <= 0:
        return 1e18, np.zeros(h.size)
    val = np.log(num / den + 1e-300)
    gLf = 2.0 * w * diff / num
    grad = _backprop(gLf, h)
    return val, grad


def _flat_descent(h0, seconds, deadline):
    cap = min(deadline - 0.3, time.process_time() + seconds)
    return _lbfgs_log(h0, 200, cap, fg=_flat_fg)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 5e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _lift(h, s, alpha):
    n = h.size
    N2 = n * s
    out = np.zeros(N2)
    mx = h.max()
    pos = np.flatnonzero(h > 1e-9 * mx)
    if pos.size == 0:
        pos = np.arange(n)
    lo = int(pos[0]); hi = int(pos[-1])
    j = np.arange(s, dtype=float)
    w_lo = (j + 0.5) ** (-alpha); w_lo /= w_lo.sum()
    w_hi = ((s - 1 - j) + 0.5) ** (-alpha); w_hi /= w_hi.sum()
    for k in range(n):
        base = k * s
        if k == lo:
            out[base:base + s] = h[k] * w_lo
        elif k == hi:
            out[base:base + s] = h[k] * w_hi
        else:
            out[base:base + s] = h[k] / s
    return out


def _mirror(h):
    return h[::-1].copy()


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    record_R = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), near0))

    # ---- Experiment: lift to a finer grid with non-staircase end profiles ----
    variants = []
    for s in (2, 3, 4):
        for alpha in (0.5, 0.75):
            hv = _rescale(_lift(best, s, alpha))
            rv = R_of(hv)
            variants.append(("lift s=%d a=%.2f" % (s, alpha), hv, rv))
            hv2 = _rescale(_mirror(hv))
            rv2 = R_of(hv2)
            variants.append(("mirror s=%d a=%.2f" % (s, alpha), hv2, rv2))

    print("pre-polish variant table:")
    for name, hv, rv in variants:
        print("  %-18s pre R=%.7f (d=%.2e)" % (name, rv, rv - record_R))

    keep = [v for v in variants if v[2] >= record_R - 5e-3]
    keep.sort(key=lambda v: -v[2])
    top = keep[:3]

    bestH = best.copy()
    bestRH = record_R

    for name, hv, rv in top:
        if time.process_time() >= deadline - 2.0:
            break
        cap = min(deadline - 1.0, time.process_time() + 14.0)
        hp, rp = _polish(hv, cap, record_R)
        print("  polish %-18s -> R=%.7f" % (name, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.7f" % bestRH)

    # ---- Flat-target descent: broaden the top of f*f (new idea vs start) ----
    flatH = bestH.copy()
    flatR = bestRH
    if time.process_time() < deadline - 8.0:
        cap = min(deadline - 0.5, time.process_time() + 12.0)
        hf = _flat_descent(bestH, 8.0, cap)
        rf = R_of(hf)
        print("  flat-target R=%.7f (d=%.2e)" % (rf, rf - bestRH))
        # re-polish the flat result with the true objective
        if time.process_time() < deadline - 4.0:
            hf2, rf2 = _polish(hf, min(deadline - 0.5, time.process_time() + 8.0), record_R)
            if rf2 > rf:
                hf, rf = hf2, rf2
        flatH, flatR = hf, rf
        if rf > bestRH + 1e-13:
            bestH, bestRH = hf.copy(), rf
            print("    NEW BEST (flat) R=%.7f" % bestRH)

    # remaining time: alternate sharp + peak + soft polish on best
    rng = np.random.default_rng(1234567)
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            improved = True
        if time.process_time() < loop_end:
            frac = 0.05 + 0.10 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
        if improved:
            print("  iter=%d R=%.7f" % (it, bestRH))
        else:
            if time.process_time() < loop_end - 2.0:
                beta = 10.0 ** rng.uniform(1.0, 4.0)
                cap = min(loop_end, time.process_time() + 3.0)
                hs = _lbfgs_log(bestH, 100, cap, beta=beta)
                rs = R_of(hs)
                if rs > bestRH + 1e-13:
                    bestH, bestRH = hs.copy(), rs
                    print("  soft beta=%.1e R=%.7f" % (beta, bestRH))

    print("final experiment R=%.7f" % bestRH)

    mx, m, near = _stats(bestH)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return bestH
    # genuinely different construction that didn't beat start -> alternative
    if flatH.size != start_best.size or flatR > start_bestR - 5e-3:
        return {"best": start_best, "alternative": flatH}
    return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    n_full = cur.size
    if n_full >= 4000:
        N_smalls = [max(1000, n_full // 8), max(1000, n_full // 4), max(1000, n_full // 2)]
    elif n_full >= 1500:
        N_smalls = [max(500, n_full // 3), max(500, n_full // 2)]
    else:
        N_smalls = [n_full]

    did_coarse = 0
    coarse_idx = 0

    while time.process_time() < deadline - 0.8:
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_log(cur, maxiter=300, deadline=deadline - 0.5, beta=beta)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        cand = _window_polish_peak(cur, deadline - 0.5, 0.4, 20, maxiter=500, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # NEW: grow resolution upward and re-polish
        if n_full <= 200000 and time.process_time() < deadline - 5.0 and rng.random() < 0.35:
            N_up = min(1000000, n_full * 2)
            h_up = _prolongate(cur, N_up)
            slice_end = min(deadline - 0.5, time.process_time() + 3.5)
            h_up = _lbfgs_log(h_up, maxiter=600, deadline=slice_end)
            h_up = _window_polish_peak(h_up, slice_end, 0.3, 16, maxiter=400, beta=600.0)
            h_up = _lbfgs_log(h_up, maxiter=400, deadline=slice_end)
            r = R_of(h_up)
            if r > cur_r:
                cur, cur_r = h_up, r
                n_full = N_up
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
            elif r > alt_r:
                alternative, alt_r = h_up.copy(), r

        do_coarse = (did_coarse < len(N_smalls)) or (rng.random() < 0.4)
        if do_coarse and time.process_time() < deadline - 4.0:
            N_small = N_smalls[coarse_idx % len(N_smalls)]
            coarse_idx += 1
            if N_small < n_full:
                did_coarse += 1
                h_small = _prolongate(cur, N_small)
                slice_end = min(deadline - 0.5, time.process_time() + 3.5)
                for beta in (300.0, 1000.0):
                    if time.process_time() >= slice_end - 0.5:
                        break
                    h_small = _lbfgs_log(h_small, maxiter=200, deadline=slice_end, beta=beta)
                h_small = _lbfgs_log(h_small, maxiter=400, deadline=slice_end)
                h_big = _prolongate(h_small, n_full)
                h_big = _lbfgs_log(h_big, maxiter=600, deadline=deadline - 0.5)
                h_big = _window_polish_peak(h_big, deadline - 0.5, 0.3, 16,
                                            maxiter=400, beta=600.0)
                r = R_of(h_big)
                if r > cur_r:
                    cur, cur_r = h_big, r
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                elif r > alt_r:
                    alternative, alt_r = h_big.copy(), r
        if time.process_time() >= deadline - 0.8:
            break

        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine_best(trial, deadline - 0.5,
                                          time_slice=min(6.0, deadline - time.process_time() - 0.5))
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

