        cap = min(deadline - 2.0, time.process_time() + 8.0)
        hs = _lbfgs_log(bestH, 300, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  global -> R=%.9f" % bestR)

    # Alternate global / peak-window until deadline
    it = 0
    loop_end = deadline - 3.0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 200, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  iter=%d global R=%.9f" % (it, bestR))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.07 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 150, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("  iter=%d peak frac=%.2f R=%.9f" % (it, frac, bestR))

    # Final short polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hs = _lbfgs_log(bestH, 150, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    # Try a coarsened version (same shape at half resolution, then re-polish)
    hc = _coarsen(bestH)
    rc = R_of(hc)
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hcp = _lbfgs_log(hc, 100, cap)
        rcp = R_of(hcp)
        if rcp > rc:
            hc, rc = hcp, rcp
    print("fine R=%.9f coarsened R=%.9f" % (bestR, rc))

    mx, m, near = _stats(bestH)
    print("final N=%d Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": bestH}

