    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    """Soft-supremum: sigmoid-weighted average of knots above c*M."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 200, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best


def _revive_zeros(h, level, win=256):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    if n < 4:
        return h
    pos = h > 0
    if not pos.any():
        return h
    k = max(1, min(win, n))
    kernel = np.ones(k) / k
    posf = pos.astype(float)
    num = np.convolve(h, kernel, mode='same')
    den = np.convolve(posf, kernel, mode='same')
    local_mean = np.where(den > 1e-12, num / np.maximum(den, 1e-12), 0.0)
    gmean = h[pos].mean()
    local_mean = np.where(local_mean > 0, local_mean, gmean)
    fill = level * local_mean
    zeros = ~pos
    h[zeros] = fill[zeros]
    return h


def _upsample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    cs = np.concatenate(([0.0], np.cumsum(h)))

    def F(t):
        t = np.clip(t, 0.0, 1.0)
        idx = np.clip((t * n).astype(int), 0, n - 1)
        frac = t * n - idx
        return cs[idx] + frac * h[idx]

    lo = np.arange(N) / N
    hi = (np.arange(N) + 1) / N
    out = (F(hi) - F(lo)) * N
    return np.clip(out, 0, None)


def _downsample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    cs = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(N + 1) / N * n
    idx = np.clip(edges.astype(int), 0, n - 1)
    frac = edges - idx
    vals = cs[idx] + frac * h[idx]
    out = np.diff(vals) * (n / N)
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    orig = None
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            orig = _rescale(base)
            best = orig.copy()
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
        orig = best.copy()

    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # New idea: Q-smoothing with sigmoid above c*M, sweeping c and beta.
    # This targets the flat plateau around the max (where many knots sit
    # near the sup) so we can raise them all, not just one knot.
    def try_Q(h, c, beta, maxiter=200):
        if time.process_time() >= deadline - 2.0:
            return h, R_of(h)
        fg = lambda hh: _fun_grad_Q(hh, c, beta)
        hh = _lbfgs_log(h, maxiter, deadline, fg=fg)
        return hh, R_of(hh)

    # Phase A: Q-smoothing sweep from current best.
    sched = [(0.999, 50.0), (0.995, 100.0), (0.99, 200.0),
             (0.98, 400.0), (0.97, 800.0), (0.95, 1500.0)]
    for c, beta in sched:
        if time.process_time() >= deadline - 15.0:
            break
        h, r = try_Q(best, c, beta)
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
            print("  Q c=%.3f b=%.0f R=%.7f" % (c, beta, bestR))

    # Phase B: exact-objective full + peak polish loop.
    it = 0
    while time.process_time() < deadline - 4.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline, fg=_fun_grad)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  full #%d R=%.7f" % (it, bestR))
        hp = _polish(best, deadline, fracs=(0.03, 0.06, 0.12, 0.25))
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
            print("  polish #%d R=%.7f" % (it, bestR))
        # Occasionally revive zeros and re-descend
        if it % 3 == 0:
            hz = _revive_zeros(best, level=0.05)
            hz = _rescale(hz)
            hz2 = _lbfgs_log(hz, 150, deadline, fg=_fun_grad)
            rz = R_of(hz2)
            if rz > bestR + 1e-13:
                best, bestR = hz2, rz
                print("  revive #%d R=%.7f" % (it, bestR))

    # Phase C: upsampling to a finer grid, then Q + exact descend.
    n_cur = best.size
    for factor in (2, 3):
        if time.process_time() >= deadline - 8.0:
            break
        N2 = min(1000000, n_cur * factor)
        if N2 <= n_cur:
            continue
        cand = _rescale(_upsample(best, N2))
        r0 = R_of(cand)
        h = cand
        r = r0
        for c, beta in ((0.98, 400.0), (0.95, 1000.0)):
            if time.process_time() >= deadline - 6.0:
                break
            fg = lambda hh, c=c, beta=beta: _fun_grad_Q(hh, c, beta)
            hh = _lbfgs_log(h, 200, deadline, fg=fg)
            rh = R_of(hh)
            if rh > r:
                h, r = hh, rh
        if time.process_time() < deadline - 4.0:
            hh = _lbfgs_log(h, 200, deadline, fg=_fun_grad)
            rh = R_of(hh)
            if rh > r:
                h, r = hh, rh
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
        print("upsample x%d N=%d R0=%.7f -> R=%.7f" % (factor, N2, r0, r))

    best = _rescale(best)
    bestR = R_of(best)
    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if orig is not None and bestR > start_bestR + 1e-12:
        return best
    if orig is not None:
        return {"best": orig,
                "alternative": best if bestR > start_bestR - 1e-6 else None}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=60):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(28):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def _gn_plateau(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002]
    lams = [1e-6, 1e-4, 1e-2, 1e-1]
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-15:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            break
        if time.process_time() < deadline - 0.5:
            cap = min(deadline, time.process_time() + 1.5)
            hp = _lbfgs_log(best, 100, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
    return best, bestR


# ---------- coarse-basis linearized least squares ----------

def _coarsen(h, M):
    n = h.size
    if n <= M:
        return h.copy()
    while h.size > M:
        m = h.size
        if m % 2 == 1:
            h = np.concatenate((h, [h[-1]]))
            m += 1
        h = 0.5 * (h[0::2] + h[1::2])
    return h


def _bspline_basis(M, K):
    x = np.arange(M, dtype=float) + 0.5
    B = np.zeros((K, M))
    centers = np.linspace(0, M, K)
    width = (M / (K - 1)) * 1.5 if K > 1 else M
    for k in range(K):
        t = (x - centers[k]) / width
        u = np.abs(t)
        w = np.where(u < 1.0, (4 - 6*u*u + 3*u**3)/6.0, 0.0)
        w = np.where((u >= 1.0) & (u < 2.0), (2 - u)**3 / 6.0, w)
        B[k] = w
    E = np.zeros((16, M))
    half = max(1, M // 64)
    for j in range(8):
        lo = j * half
        E[j, lo:lo+half] = np.linspace(1, 0, half) if half > 0 else 0
    for j in range(8):
        hi = M - j * half
        E[8+j, max(0, hi-half):hi] = np.linspace(0, 1, half) if half > 0 else 0
    B = np.vstack([B, E])
    s = B.sum(axis=1, keepdims=True)
    s[s <= 0] = 1
    B = B / s
    return B


def _basis_step(h, B, eps, lam, deadline):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None, 0.0
    thresh = (1.0 - eps) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * h.size - 1)]
    if A.size < 2:
        return None, 0.0
    c = L[A].mean()
    r = c - L[A]
    K = B.shape[0]
    J = np.zeros((A.size, K))
    for k in range(K):
        if time.process_time() > deadline:
            return None, 0.0
        cd = fftconvolve(h, B[k])
        J[:, k] = 2.0 * cd[A - 1]
    JtJ = J.T @ J
    Jtr = J.T @ r
    dg = np.diag(JtJ).copy()
    dg[dg <= 0] = 1.0
    reg = JtJ + lam * np.diag(dg)
    try:
        d = np.linalg.solve(reg, Jtr)
    except np.linalg.LinAlgError:
        return None, 0.0
    pred = float(r @ r - (r - J @ d) @ (r - J @ d))
    return d, pred


def _basis_try(h, bestR, B, eps, lam, deadline):
    d, pred = _basis_step(h, B, eps, lam, deadline)
    if d is None or not np.any(d):
        return h, bestR, 0.0
    delta = B.T @ d
    alpha = 1.0
    for _ in range(24):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * delta, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        hn = _rescale(hn)
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn, pred
        alpha *= 0.5
    return h, bestR, pred


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    M = 42496
    K = 256
    hc = _coarsen(best, M)
    B = _bspline_basis(hc.size, K)

    eps_list = [0.002, 0.005, 0.01, 0.02, 0.05]
    lam_list = [1e-6, 1e-4, 1e-2, 1e-1]

    coarse_best = hc.copy()
    coarse_bestR = R_of(coarse_best)
    for eps in eps_list:
        for lam in lam_list:
            if time.process_time() >= deadline - 2.0:
                break
            hn, rn, pred = _basis_try(coarse_best, coarse_bestR, B, eps, lam,
                                      min(deadline - 1.0, time.process_time() + 2.0))
            if rn > coarse_bestR + 1e-15:
                coarse_best, coarse_bestR = hn, rn

    if coarse_bestR > bestR + 1e-13 and coarse_best.size != best.size:
        n = best.size
        idx = (np.arange(n) * coarse_best.size // n).astype(int)
        up = _rescale(coarse_best[idx])
        ru = R_of(up)
        if ru > bestR + 1e-15:
            best, bestR = up, ru
            print("  upsample R=%.9f" % bestR)

    betas = [1.0, 5.0, 20.0, 80.0, 300.0, 1000.0]
    it = 0
    while time.process_time() < deadline - 0.5:
        it += 1
        improved = False

        if time.process_time() < deadline - 3.0:
            hc2 = _coarsen(best, M)
            Bc = _bspline_basis(hc2.size, K)
            cb = hc2.copy()
            cbR = R_of(cb)
            for eps in eps_list:
                for lam in lam_list:
                    if time.process_time() >= deadline - 2.0:
                        break
                    hn, rn, pred = _basis_try(cb, cbR, Bc, eps, lam,
                                              min(deadline - 1.0, time.process_time() + 1.5))
                    if rn > cbR + 1e-15:
                        cb, cbR = hn, rn
            if cbR > R_of(_coarsen(best, M)) + 1e-13:
                n = best.size
                idx = (np.arange(n) * cb.size // n).astype(int)
                up = _rescale(cb[idx])
                ru = R_of(up)
                if ru > bestR + 1e-15:
                    best, bestR = up, ru
                    improved = True
                    print("  basis iter=%d R=%.9f" % (it, bestR))

        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            hp = _lbfgs_log(best, 200, cap, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved = True
                print("  beta=%.0f iter=%d R=%.9f" % (beta, it, bestR))

        if time.process_time() < deadline - 0.5:
            gn_cap = min(deadline - 0.3, time.process_time() + 3.0)
            gh, gr = _gn_plateau(best, gn_cap)
            if gr > bestR + 1e-15:
                best, bestR = gh, gr
                improved = True
                print("  GN iter=%d R=%.9f" % (it, bestR))

        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.3, time.process_time() + 2.5)
            hp = _lbfgs_log(best, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved = True
                print("  hard iter=%d R=%.9f" % (it, bestR))

        if it % 2 == 0 and time.process_time() < deadline - 1.0:
            free = _peak_window(best, frac=0.05)
            cap = min(deadline - 0.3, time.process_time() + 1.5)
            hb = _lbfgs_block(best, free, 150, cap)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
                improved = True
                print("  block iter=%d R=%.9f" % (it, bestR))

        if not improved:
            rng = np.random.default_rng(it)
            pert = best * (1.0 + 0.001 * rng.standard_normal(best.size))
            pert = _rescale(np.clip(pert, 0, None))
            rp = R_of(pert)
            if rp > bestR:
                best, bestR = pert, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def _restrict(h, M):
    """Area-average restriction of h (length N) to M cells."""
    N = h.size
    if M == N:
        return h.copy()
    idx = (np.arange(M + 1) * N) // M
    out = np.empty(M)
    for i in range(M):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _lift(h, N):
    """Linear interpolation of h (length M) up to N cells."""
    M = h.size
    if M == N:
        return h.copy()
    xp = (np.arange(M) + 0.5) / M
    xq = (np.arange(N) + 0.5) / N
    out = np.interp(xq, xp, h)
    return np.clip(out, 0, None)


def _random_field(M, rng):
    """Low-order cosine series random multiplicative field."""
    k = rng.integers(4, 13)
    amp = rng.uniform(0.3, 1.0)
    x = np.linspace(0, np.pi, M)
    field = np.zeros(M)
    for j in range(1, k + 1):
        coeff = rng.normal(0, 1.0 / j)
        phase = rng.uniform(0, 2 * np.pi)
        field += coeff * np.cos(j * x + phase)
    field = field / (np.std(field) + 1e-12)
    return np.exp(amp * field)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    rng = np.random.default_rng(12345)

    # ---- coarse multistart phase ----
    coarse_end = min(hard - 15.0, t0 + budget_seconds * 0.55)
    Ms = [2048, 4096, 8192]
    refined_candidates = []  # (R_c, M, h_coarse)

    for M in Ms:
        if time.process_time() >= coarse_end:
            break
        h0c = _restrict(best, M)
        R0c = R_of(h0c)
        best_c = h0c.copy()
        best_Rc = R0c
        # seed: record restriction
        cap = min(coarse_end, time.process_time() + 1.2)
        hp = _lbfgs_log(h0c, 150, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > best_Rc:
            best_c, best_Rc = hp, rp
        # random multistarts
        n_trials = 25
        for trial in range(n_trials):
            if time.process_time() >= coarse_end:
                break
            field = _random_field(M, rng)
            cand = h0c * field
            if trial >= 19:
                # zero out 20-60% of cells at random
                frac = rng.uniform(0.2, 0.6)
                mask = rng.random(M) < frac
                cand = cand * (~mask)
            if cand.sum() <= 0:
                continue
            cap = min(coarse_end, time.process_time() + 1.2)
            hp = _lbfgs_log(cand, 150, cap, fg=_fun_grad)
            rp = R_of(hp)
            if rp > best_Rc:
                best_c, best_Rc = hp, rp
        print("  [M=%d] R0_c=%.9f best_Rc=%.9f" % (M, R0c, best_Rc))
        if best_Rc > R0c + 1e-5:
            refined_candidates.append((best_Rc, M, best_c))

    # ---- refinement ladder ----
    refined_results = []
    for (Rc, M, hc) in sorted(refined_candidates, key=lambda t: -t[0]):
        if time.process_time() >= hard - 15.0:
            break
        cur = hc.copy()
        curM = M
        while curM < N:
            if time.process_time() >= hard - 15.0:
                break
            curM = min(curM * 2, N)
            cur = _lift(cur, curM)
            cap = min(hard - 15.0, time.process_time() + 2.0)
            cur = _lbfgs_log(cur, 150, cap, fg=_fun_grad)
            # Q-surrogate sweep at this level
            for (c, beta) in [(0.90, 1e3), (0.95, 1e3), (0.95, 1e5), (0.99, 1e4)]:
                if time.process_time() >= hard - 15.0:
                    break
                fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
                cap = min(hard - 15.0, time.process_time() + 1.5)
                hq = _lbfgs_log(cur, 100, cap, fg=fg)
                if R_of(hq) > R_of(cur):
                    cur = hq
        if cur.size == N:
            hp, rp = _polish(cur, min(hard - 14.0, time.process_time() + 4.0))
            refined_results.append((rp, M, hp))
            print("  [refine M=%d] R=%.9f" % (M, rp))
            if rp > bestR + 1e-7:
                best, bestR = hp, rp
                print("    new best R=%.9f" % bestR)

    # ---- final pure exact-R polish of the record ----
    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp
            print("    final polish R=%.9f" % bestR)

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _interp_refine(h, factor=2):
    n = h.size
    m = n * factor
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(m, dtype=float) / factor
    return np.interp(x_new, x_old, h, left=0.0, right=0.0)


def _gauss_kernel(sigma):
    half = max(1, int(np.ceil(3.0 * sigma)))
    x = np.arange(-half, half + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return k


def _gauss_smooth(h, sigma):
    k = _gauss_kernel(sigma)
    hs = fftconvolve(h, k, mode='same')
    # restore outer 2*sigma cells from h to avoid edge mass loss
    edge = int(2 * sigma)
    if edge > 0 and edge < h.size:
        hs[:edge] = h[:edge]
        hs[-edge:] = h[-edge:]
    hs = np.clip(hs, 0, None)
    return _rescale(hs)


def _polish(h, deadline, iters=200, cap_seconds=2.5):
    """Global L-BFGS then peak-window block polish."""
    cap = min(deadline - 0.5, time.process_time() + cap_seconds)
    hs = _lbfgs_log(h, iters, cap, beta=0.0)
    rs = R_of(hs)
    best = hs if rs > R_of(h) else h
    bestR = max(rs, R_of(h))
    for frac in (0.02, 0.05, 0.10):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.5, time.process_time() + 1.5)
        hp = _lbfgs_block(best, free, 150, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), m0, near0))

    # ---------- Stage A: cheap screen ----------
    sigmas = [5, 20, 60]
    alphas = [0.3, 0.6, 1.0]
    screen = []
    stageA_end = t0 + budget_seconds * 0.42
    print("Stage A screen (sigma, alpha, R):")
    for sigma in sigmas:
        for alpha in alphas:
            if time.process_time() >= stageA_end:
                break
            hs = _gauss_smooth(baseH, sigma)
            hprime = (1.0 - alpha) * baseH + alpha * hs
            hprime = _rescale(np.clip(hprime, 0, None))
            cap = min(deadline - 3.0, time.process_time() + 0.8)
            hopt = _lbfgs_log(hprime, 40, cap, beta=0.0)
            r = R_of(hopt)
            screen.append((sigma, alpha, r, hopt))
            print("  sigma=%3d alpha=%.1f R=%.9f" % (sigma, alpha, r))
        if time.process_time() >= stageA_end:
            break

    if not screen:
        # fallback: just polish base
        bestH, bestR = _polish(baseH, deadline, iters=200, cap_seconds=3.0)
        alt = bestH if bestR > baseR + 1e-12 else baseH
        return {"best": alt, "alternative": baseH}

    screen.sort(key=lambda t: -t[2])
    top = screen[:3]

    # ---------- Stage B: deeper polish on top 3 ----------
    stageB_end = t0 + budget_seconds * 0.72
    bestH, bestR = baseH.copy(), baseR
    for sigma, alpha, r0, hopt in top:
        if time.process_time() >= stageB_end:
            break
        hp, rp = _polish(hopt, stageB_end, iters=200, cap_seconds=2.5)
        print("Stage B sigma=%d alpha=%.1f R=%.9f -> %.9f" %
              (sigma, alpha, r0, rp))
        if rp > bestR:
            bestH, bestR = hp, rp

    # ---------- Stage C: spend remaining budget ----------
    # Alternate global and peak-window passes on overall best.
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        cap = min(deadline - 1.0, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            bestH, bestR = hs, rs
            print("  C iter=%d global R=%.9f" % (it, bestR))
            continue
        if time.process_time() < deadline - 1.5:
            frac = 0.02 + 0.08 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(deadline - 1.0, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                bestH, bestR = hp, rp
                print("  C iter=%d peak frac=%.2f R=%.9f" % (it, frac, bestR))

    hc = _coarsen(bestH)
    rc = R_of(hc)
    print("fine R=%.9f coarsened R=%.9f (base %.9f)" % (bestR, rc, baseR))
    mx, m, near = _stats(bestH)
    print("final N=%d zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": bestH}

