def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _perturb_field(n, lam, amp, phase):
    x = np.arange(n, dtype=float)
    return np.exp(amp * np.sin(2.0 * np.pi * x / lam + phase))


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def _upsample(h, n):
    m = h.size
    x = (np.arange(n) + 0.5) * m / n
    return np.interp(x, np.arange(m) + 0.5, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    n = best.size
    print("base R=%.9f (N=%d)" % (bestR, n))

    # Stage 1: coarse-to-fine refinement. Downsample, optimise at small N,
    # then upsample back to refine at full resolution.
    working = best.copy()
    workingR = bestR
    factors = [8, 4, 2]
    for fac in factors:
        if time.process_time() >= hard - 10.0:
            break
        if n // fac < 32:
            continue
        hc = _downsample(working, fac)
        hc = _rescale(hc)
        cap = min(hard - 8.0, time.process_time() + 3.0)
        hq = _lbfgs_log(hc, 300, cap, fg=_fun_grad)
        cap2 = min(hard - 6.0, time.process_time() + 2.0)
        hq, rq = _polish(hq, cap2, fracs=(0.05, 0.15))
        # upscale
        hu = _upsample(hq, n)
        hu = _rescale(hu)
        cap3 = min(hard - 4.0, time.process_time() + 3.0)
        hu = _lbfgs_log(hu, 300, cap3, fg=_fun_grad)
        ru = R_of(hu)
        print("  coarse fac=%d R=%.9f -> up R=%.9f" % (fac, rq, ru))
        if ru > workingR:
            working, workingR = hu, ru
        if ru > bestR:
            best, bestR = hu, ru

    # Stage 2: band-limited perturbation random search.
    lams = [n / 8.0, n / 32.0, n / 128.0, n / 512.0]
    amps = [2e-3, 1e-2, 3e-2, 1e-1]
    rng = np.random.RandomState(12345)
    tol_log = 2e-3
    restart = 0

    while time.process_time() < hard - 8.0:
        restart += 1
        lam = lams[rng.randint(len(lams))]
        amp = amps[rng.randint(len(amps))]
        phase = rng.uniform(0, 2 * np.pi)
        p = _perturb_field(n, lam, amp, phase)
        src = working if workingR > bestR - tol_log else best
        h = _rescale(src * p)

        cap = min(hard - 6.0, time.process_time() + 3.0)
        hq = _lbfgs_log(h, 150, cap, fg=_fun_grad)
        cap2 = min(hard - 4.0, time.process_time() + 3.0)
        hp, rp = _polish(hq, cap2, fracs=(0.02, 0.05, 0.20))
        Rw = rp
        beat = Rw > bestR + 1e-14
        print("  [r%d lam=%.0f amp=%.0e] Rw=%.9f best=%.9f %s" %
              (restart, lam, amp, Rw, bestR, "BEAT" if beat else ""))
        if beat:
            best, bestR = hp, Rw
            working, workingR = hp, Rw
        elif np.log(max(Rw, 1e-300)) > np.log(bestR) - tol_log:
            working, workingR = hp, Rw
        else:
            working, workingR = best, bestR
        if restart % 8 == 0:
            working, workingR = best, bestR

    # Final long polish
    if time.process_time() < hard - 0.5:
        cap = min(hard - 2.0, time.process_time() + 4.0)
        hp = _lbfgs_log(best, 800, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
        cap2 = min(hard - 0.3, time.process_time() + 3.0)
        hp, rp = _polish(best, cap2)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            r = R_of(s)
            if r > 0:
                best = s.copy()
                best_R = r

    if best is None:
        n = 512
        x = np.linspace(0, 1, n)
        best = np.cos(np.pi * (x - 0.5))**2 + 1e-3
        best = _lbfgs_log(best, 250, deadline)
        best_R = R_of(best)

    print(f"seed R={best_R:.6f} N={len(best)}")

    cur = best.copy()
    cur_R = best_R

    def try_polish(h, R, label):
        nonlocal cur, cur_R
        h2 = _lbfgs_log(h, 400, deadline, beta=0.0)
        r2 = R_of(h2)
        if r2 > R + 1e-11:
            h, R = h2, r2
            print(f"  {label} logopt R={R:.6f} N={len(h)}")
        for beta in [32.0, 128.0, 512.0, 2048.0, 8192.0]:
            if time.process_time() > deadline - 1.0:
                break
            h3 = _lbfgs_log(h, 200, deadline, beta=beta)
            r3 = R_of(h3)
            if r3 > R + 1e-11:
                h, R = h3, r3
                print(f"  {label} beta={beta} R={R:.6f}")
        return h, R

    # If start is already large, don't waste time redoing the whole ladder:
    # polish it directly at its current N, then try higher N only if time remains.
    if len(best) >= 16384:
        cur, cur_R = try_polish(best, best_R, f"N={len(best)}")
        if cur_R > best_R:
            best = cur.copy(); best_R = cur_R
    else:
        for N in [8192, 16384, 32768, 65536]:
            if time.process_time() > deadline - 4.0:
                break
            cur = _prolong(cur, N)
            cur_R = R_of(cur)
            cur, cur_R = try_polish(cur, cur_R, f"N={N}")
            if cur_R > best_R:
                best = cur.copy()
                best_R = cur_R

    # Alternation: full logopt, peak-window polishes, prolongation
    while time.process_time() < deadline - 1.0:
        improved = False

        h2, r2 = try_polish(best, best_R, "full")
        if r2 > best_R + 1e-11:
            best, best_R = h2, r2
            improved = True

        for frac in [0.30, 0.15, 0.07]:
            if time.process_time() > deadline - 1.0:
                break
            win = _peak_window(best, frac=frac)
            if win.size < 4:
                continue
            h = best.copy()
            active = win
            x0 = h[active].copy()
            def f(x, h=h, active=active):
                hh = h.copy()
                hh[active] = np.clip(x, 0, None)
                val, g = _fun_grad(hh)
                return val, g[active]
            cb = _make_cb(deadline - 0.3)
            try:
                res = minimize(f, x0, jac=True, method='L-BFGS-B',
                               bounds=[(0.0, None)] * active.size,
                               callback=cb,
                               options={'maxiter': 300, 'maxfun': 600,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                h2 = h.copy()
                h2[active] = np.clip(res.x, 0, None)
                h2 = _rescale(h2)
                r3 = R_of(h2)
                if r3 > best_R + 1e-11:
                    best, best_R = h2, r3
                    improved = True
                    print(f"window frac={frac} R={best_R:.6f}")
            except (TimeoutError, Exception):
                pass

        if not improved:
            N = min(2 * len(best), 131072)
            if N <= len(best):
                break
            best = _prolong(best, N)
            best = _lbfgs_log(best, 200, deadline)
            best_R = R_of(best)
            print(f"prolong N={N} R={best_R:.6f}")

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={R_of(best):.6f} N={len(best)}")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def _q_sweep(h, deadline, grid):
    best = h
    bestR = R_of(h)
    for (c, beta) in grid:
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hq = _lbfgs_log(best, 150, cap, fg=fg)
        rq = R_of(hq)
        if rq > bestR:
            best, bestR = hq, rq
    return best, bestR


def _anneal(h, deadline, seed=0):
    """Simulated-annealing style perturbation + local descent to escape saddles."""
    rng = np.random.default_rng(seed)
    best = h
    bestR = R_of(h)
    n = h.size
    scale = 0.02 * (h.max() if h.max() > 0 else 1.0)
    while time.process_time() < deadline - 2.0:
        # perturb a random contiguous window
        w = max(32, n // 40)
        c = rng.integers(0, n)
        lo = max(0, c - w // 2)
        hi = min(n, lo + w)
        hp = best.copy()
        noise = rng.standard_normal(hi - lo) * scale
        hp[lo:hi] = np.clip(hp[lo:hi] + noise, 0.0, None)
        hp = _rescale(hp)
        cap = min(deadline - 1.0, time.process_time() + 2.0)
        hp = _lbfgs_log(hp, 120, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
            scale *= 0.9
        else:
            scale *= 0.98
        if scale < 1e-6 * (best.max() if best.max() > 0 else 1.0):
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    grid2 = [(0.90, 1e3), (0.95, 1e3), (0.95, 1e5),
             (0.99, 1e4), (0.99, 1e5), (0.97, 5e4)]

    sweep = 0
    stall = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        for (c, beta) in grid2:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
            cap = min(hard - 2.0, time.process_time() + 3.0)
            hq = _lbfgs_log(best, 150, cap, fg=fg)
            rq = R_of(hq)
            hp, rp = _polish(hq, min(hard - 1.0, time.process_time() + 5.0))
            beat = rp > bestR + 1e-14
            print("  [sweep%d c=%.2f beta=%.0e] Rq=%.9f polish=%.9f %s" %
                  (sweep, c, beta, rq, rp, "BEAT" if beat else ""))
            if beat:
                best, bestR = hp, rp
                improved = True
                stall = 0
                print("    new best R=%.9f" % bestR)
        if not improved:
            stall += 1
            if time.process_time() < hard - 3.0:
                # anneal to escape
                cap = min(hard - 2.0, time.process_time() + 6.0)
                ha, ra = _anneal(best, cap, seed=sweep)
                if ra > bestR + 1e-13:
                    best, bestR = ha, ra
                    print("    anneal best R=%.9f" % bestR)
                    stall = 0
        if stall >= 3 and time.process_time() < hard - 4.0:
            cap = min(hard - 2.0, time.process_time() + 4.0)
            hp = _lbfgs_log(best, 400, cap, fg=_fun_grad)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("    fallback best R=%.9f" % bestR)
                stall = 0

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _frac_near_max(h, frac=0.01):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def _upsample(h, n):
    m = h.size
    if m == n:
        return h.copy()
    x = (np.arange(n) + 0.5) * m / n
    idx = np.clip(x.astype(int), 0, m - 1)
    return h[idx]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    candidates = []

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
            candidates.append((bestR, best.copy()))
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
        candidates.append((bestR, best.copy()))

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d) frac1%%=%.4f" %
          (bestR, best.size, _frac_near_max(best, 0.01)))

    # Stage 1: coarse smoothing / reparametrization exploration.
    # Downsample, re-optimise at coarse resolution with a generous beta
    # schedule to escape local optima, then upsample back.
    n_orig = best.size
    for factor in [2, 4, 8]:
        if time.process_time() >= deadline - 2.0:
            break
        if n_orig // factor < 64:
            break
        hd = _downsample(best, factor)
        hd = _rescale(hd)
        # coarse beta-continuation to sharpen the peak
        cur = hd
        curR = R_of(cur)
        for beta in [0.0, 20.0, 100.0, 500.0]:
            if time.process_time() >= deadline - 2.0:
                break
            cap = min(deadline - 1.0, time.process_time() + 1.5)
            hh = _lbfgs_log(cur, 120, cap, beta=beta)
            r = R_of(hh)
            if r >= curR - 1e-12:
                cur, curR = hh, r
        # upsample back to original resolution
        hu = _upsample(cur, n_orig)
        hu = _rescale(hu)
        # refine at full resolution with exact-R objective
        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.8, time.process_time() + 2.0)
            hu = _lbfgs_log(hu, 200, cap, beta=0.0)
        ru = R_of(hu)
        candidates.append((ru, hu.copy()))
        print("  coarse factor=%d R=%.9f" % (factor, ru))
        if ru > bestR + 1e-14:
            best, bestR = hu, ru

    # Stage 2: exact-R peak-window polish at multiple scales, taking the
    # best available candidate each round (exploit the coarse exploration).
    for round_i in range(6):
        if time.process_time() >= deadline - 1.0:
            break
        improved = False
        for frac in [0.02, 0.05, 0.10, 0.20]:
            if time.process_time() >= deadline - 0.8:
                break
            free = _peak_window(best, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 1.2)
            hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
            rb = R_of(hb)
            if rb > bestR + 1e-14:
                best, bestR = hb, rb
                improved = True
        if time.process_time() < deadline - 0.8:
            cap = min(deadline - 0.5, time.process_time() + 2.5)
            hp = _lbfgs_log(best, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                improved = True
        print("  round=%d R=%.9f frac1%%=%.4f improved=%s" %
              (round_i, bestR, _frac_near_max(best, 0.01), improved))
        if not improved and round_i >= 1:
            break

    # Stage 3: if there is still time, try a final beta-continuation from
    # the current best to sharpen the maximum region.
    if time.process_time() < deadline - 1.0:
        cur = best
        curR = bestR
        for beta in [50.0, 200.0, 800.0, 2000.0]:
            if time.process_time() >= deadline - 0.8:
                break
            cap = min(deadline - 0.5, time.process_time() + 1.5)
            hh = _lbfgs_log(cur, 150, cap, beta=beta)
            r = R_of(hh)
            if r > curR + 1e-14:
                cur, curR = hh, r
                best, bestR = hh, r
        print("  beta-final R=%.9f" % bestR)

    print("final R=%.9f (N=%d) frac1%%=%.4f" %
          (bestR, best.size, _frac_near_max(best, 0.01)))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    n_full = cur.size

    # NEW: shrink-then-grow cycle. The key new idea is to first coarsen the
    # representation substantially (a smoothing/denoising pass), optimize the
    # coarse shape globally (which avoids local minima on the fine grid), then
    # prolongate back up and re-polish. This was not tried as the *primary*
    # early move before; doing it early gives a better basin.
    def _coarsen_grow(h, n_target_small, time_cap):
        """Coarsen to n_target_small, optimize, grow back to h.size."""
        slice_end = min(deadline - 0.5, time.process_time() + time_cap)
        hs = _prolongate(h, n_target_small)
        for beta in (200.0, 500.0, 1200.0):
            if time.process_time() >= slice_end - 0.5:
                break
            hs = _lbfgs_sm(hs, beta, maxiter=250, deadline=slice_end)
        hs = _lbfgs_log(hs, maxiter=500, deadline=slice_end)
        hb = _prolongate(hs, h.size)
        hb = _lbfgs_log(hb, maxiter=600, deadline=slice_end)
        hb = _window_polish_peak(hb, slice_end, 0.35, 20, maxiter=500, beta=600.0)
        hb = _lbfgs_log(hb, maxiter=400, deadline=slice_end)
        return hb

    # Early coarsen-grow at several scales
    early_small = max(800, n_full // 16)
    if early_small < n_full and time.process_time() < deadline - 8.0:
        cand = _coarsen_grow(cur, early_small, 8.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # Primary: increase resolution once (as before), but now with a
    # coarsen-grow pass in the middle to escape the fine-grid local min.
    target_N = min(1000000, max(n_full * 2, 64000))
    h_big = _prolongate(cur, target_N)
    slice_end = min(deadline - 0.5, time.process_time() + 6.0)
    for beta in (300.0, 800.0, 1500.0):
        if time.process_time() >= slice_end - 0.5:
            break
        h_big = _lbfgs_sm(h_big, beta, maxiter=250, deadline=slice_end)
    h_big = _lbfgs_log(h_big, maxiter=800, deadline=slice_end)
    h_big = _window_polish_peak(h_big, slice_end, 0.3, 16, maxiter=500, beta=600.0)
    h_big = _lbfgs_log(h_big, maxiter=500, deadline=slice_end)

    # coarsen-grow on the bigger grid
    if time.process_time() < deadline - 8.0:
        mid_small = max(1000, target_N // 12)
