    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 150, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    bestH = best.copy()
    bestRH = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    rng = np.random.default_rng(20240517)

    # ---- Q-surrogate with a range of (c, beta): sharpen the peak plateau ----
    for c in (0.90, 0.95, 0.98, 0.995):
        if time.process_time() >= deadline - 3.0:
            break
        for beta in (200.0, 2000.0):
            if time.process_time() >= deadline - 3.0:
                break
            cap = min(deadline - 2.0, time.process_time() + 3.0)
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
            hs = _lbfgs_log(bestH, 120, cap, fg=fg)
            r_raw = R_of(hs)
            cap2 = min(deadline - 1.5, time.process_time() + 2.0)
            hp, rp = _polish(hs, cap2, fracs=(0.03, 0.08))
            print("  [Q] c=%.3f beta=%.0f raw=%.9f polish=%.9f (best=%.9f)" %
                  (c, beta, r_raw, rp, bestRH))
            if rp > bestRH + 1e-12:
                bestH, bestRH = hp.copy(), rp
                print("    NEW BEST R=%.9f" % bestRH)

    # ---- Alternating block-coordinate refinement centred on the peak ----
    for frac in (0.02, 0.04, 0.08, 0.15, 0.30):
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(bestH, frac=frac)
        cap = min(deadline - 1.0, time.process_time() + 3.0)
        hp = _lbfgs_block(bestH, free, 150, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("  [peak] frac=%.2f R=%.9f" % (frac, bestRH))

    # ---- Final full-log polish loop ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, fg=_fun_grad)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.12 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 2.5)
            hp = _lbfgs_block(bestH, free, 120, cap, fg=_fun_grad)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            r = R_of(s)
            if r > 0:
                best = s.copy()
                best_R = r

    if best is None:
        n = 512
        x = np.linspace(0, 1, n)
        best = np.cos(np.pi * (x - 0.5))**2 + 1e-3
        best = _lbfgs_log(best, 250, deadline)
        best_R = R_of(best)

    print(f"seed R={best_R:.6f} N={len(best)}")

    cur = best.copy()
    cur_R = best_R

    def try_polish(h, R, label):
        nonlocal cur, cur_R
        h2 = _lbfgs_log(h, 400, deadline, beta=0.0)
        r2 = R_of(h2)
        if r2 > R + 1e-11:
            h, R = h2, r2
            print(f"  {label} logopt R={R:.6f} N={len(h)}")
        for beta in [32.0, 128.0, 512.0, 2048.0, 8192.0]:
            if time.process_time() > deadline - 1.0:
                break
            h3 = _lbfgs_log(h, 200, deadline, beta=beta)
            r3 = R_of(h3)
            if r3 > R + 1e-11:
                h, R = h3, r3
                print(f"  {label} beta={beta} R={R:.6f}")
        return h, R

    if len(best) >= 16384:
        cur, cur_R = try_polish(best, best_R, f"N={len(best)}")
        if cur_R > best_R:
            best = cur.copy(); best_R = cur_R
    else:
        for N in [8192, 16384, 32768, 65536]:
            if time.process_time() > deadline - 4.0:
                break
            cur = _prolong(cur, N)
            cur_R = R_of(cur)
            cur, cur_R = try_polish(cur, cur_R, f"N={N}")
            if cur_R > best_R:
                best = cur.copy()
                best_R = cur_R

    while time.process_time() < deadline - 1.0:
        improved = False

        h2, r2 = try_polish(best, best_R, "full")
        if r2 > best_R + 1e-11:
            best, best_R = h2, r2
            improved = True

        for frac in [0.30, 0.15, 0.07]:
            if time.process_time() > deadline - 1.0:
                break
            win = _peak_window(best, frac=frac)
            if win.size < 4:
                continue
            h = best.copy()
            active = win
            x0 = h[active].copy()
            def f(x, h=h, active=active):
                hh = h.copy()
                hh[active] = np.clip(x, 0, None)
                val, g = _fun_grad(hh)
                return val, g[active]
            cb = _make_cb(deadline - 0.3)
            try:
                res = minimize(f, x0, jac=True, method='L-BFGS-B',
                               bounds=[(0.0, None)] * active.size,
                               callback=cb,
                               options={'maxiter': 300, 'maxfun': 600,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                h2 = h.copy()
                h2[active] = np.clip(res.x, 0, None)
                h2 = _rescale(h2)
                r3 = R_of(h2)
                if r3 > best_R + 1e-11:
                    best, best_R = h2, r3
                    improved = True
                    print(f"window frac={frac} R={best_R:.6f}")
            except (TimeoutError, Exception):
                pass

        if not improved:
            N = min(2 * len(best), 131072)
            if N <= len(best):
                break
            best = _prolong(best, N)
            best = _lbfgs_log(best, 200, deadline)
            best_R = R_of(best)
            print(f"prolong N={N} R={best_R:.6f}")

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={R_of(best):.6f} N={len(best)}")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _fun_grad_Q(h, c, beta):
    """Smooth-max via scaled softplus: Q = sum L * sigmoid(beta*(L - c*max))."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, fg=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, fg=fg)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _refine_full(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        for beta in (500.0, 200.0, 80.0, 30.0):
            if time.process_time() >= t_end - 0.5:
                break
            cand = _lbfgs_log(cur, 1200, t_end,
                              fg=lambda hh, b=beta: _fun_grad_sm(hh, b))
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, 2000, t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.2, 8, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _refine_Q(h, deadline, c, beta):
    """One Q-smooth-max pass (soft-threshold peak) at given c, beta."""
    if time.process_time() >= deadline - 0.3:
        return h, R_of(h)
    fg = lambda hh: _fun_grad_Q(hh, c, beta)
    cand = _lbfgs_log(h, 1500, deadline, fg=fg)
    return cand, R_of(cand)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(987654321)

    if start_arr is None:
        # Cold start: multiscale search
        N0 = 1024
        cands = []
        for i in range(16):
            if time.process_time() >= deadline - 2.0:
                break
            h = np.zeros(N0)
            B = int(rng.integers(12, 40))
            widths = np.exp(rng.uniform(np.log(1.0), np.log(60.0), size=B))
            widths /= widths.sum()
            heights = np.exp(rng.uniform(np.log(1.0), np.log(200.0), size=B))
            edges = np.concatenate(([0.0], np.cumsum(widths)))
            for j in range(B):
                lo = int(edges[j] * N0); hi = int(edges[j + 1] * N0)
                hi = max(hi, lo + 1); lo = min(lo, N0 - 1); hi = min(hi, N0)
                h[lo:hi] = np.maximum(h[lo:hi], heights[j])
            h[rng.random(N0) < 0.55] = 0.0
            if h.sum() <= 0:
                h = np.ones(N0)
            h = _rescale(h)
            h = _lbfgs_log(h, 600, deadline)
            r = R_of(h)
            cands.append((r, h))
        cands.sort(key=lambda x: -x[0])
        pool = [(r, h) for r, h in cands[:4]] or [(best_r, best)]
        for N in (2048, 4096, 8192, 16384, 32000):
            if time.process_time() >= deadline - 1.0:
                break
            new_pool = []
            for r, h in pool:
                if time.process_time() >= deadline - 1.0:
                    new_pool.append((r, h)); continue
                cand = _prolongate(h, N)
                cand = _rescale(cand)
                cand = _lbfgs_log(cand, 500, deadline)
                cand = _window_polish_peak(cand, deadline, 0.25, 16, maxiter=400)
                rr = R_of(cand)
                new_pool.append((rr, cand))
                if rr > best_r:
                    best, best_r = cand.copy(), rr
            new_pool.sort(key=lambda x: -x[0])
            pool = new_pool[:4]
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < deadline - 0.5:
            cur, cur_r = _refine_full(cur, deadline,
                                      time_slice=min(15.0, deadline - time.process_time() - 0.5))
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        return best

    # Warm start: focus on Q-smooth-max passes at several (c, beta) to smooth the
    # argmax kink more aggressively than plain log-sum-exp, then exact polish.
    cur = start_arr.copy()
    cur_r = best_r
    n = cur.size
    alternative = None
    alt_r = -1.0

    # Cycle through Q-smoothing settings (c near 1 = close to exact max;
    # smaller c = softer, more global; larger beta = sharper)
    settings = [
        (0.9995, 3000.0),
        (0.999, 1500.0),
        (0.995, 800.0),
        (0.99, 400.0),
        (0.97, 200.0),
        (0.95, 120.0),
        (0.9998, 6000.0),
    ]
    si = 0
    while time.process_time() < deadline - 1.0:
        c, beta = settings[si % len(settings)]
        si += 1
        slice_t = min(8.0, deadline - time.process_time() - 1.0)
        if slice_t <= 0.5:
            break
        t_slice_end = time.process_time() + slice_t
        cand, cand_r = _refine_Q(cur, t_slice_end, c, beta)
        if time.process_time() >= t_slice_end - 0.5:
            pass
        # exact polish
        cand = _lbfgs_log(cand, 800, t_slice_end)
        cand = _window_polish_peak(cand, t_slice_end, 0.15, 8, maxiter=400)
        cand_r = R_of(cand)
        if cand_r > cur_r + 1e-12:
            cur, cur_r = cand, cand_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif cand_r > alt_r:
            alternative, alt_r = cand.copy(), cand_r
        if time.process_time() >= deadline - 1.0:
            break
        # perturbation restart occasionally
        if si % 3 == 0:
            trial = cur.copy()
            blk = int(rng.integers(max(4, n // 40), max(8, n // 8)))
            lo = int(rng.integers(0, max(1, n - blk)))
            hi = min(n, lo + blk)
            noise = np.exp(rng.normal(0.0, 0.2, size=hi - lo))
            trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
            trial = _rescale(trial)
            trial_r = R_of(trial)
            if trial_r > 0.6 * cur_r:
                trial, trial_r = _refine_full(trial, deadline,
                                              time_slice=min(5.0, deadline - time.process_time() - 1.0))
            if trial_r > cur_r:
                cur, cur_r = trial, trial_r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
            elif trial_r > alt_r:
                alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def _resample_shift(h, delta):
    N = h.size
    cum = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.arange(N + 1, dtype=float)
    t = delta + np.arange(N + 1, dtype=float)
    F = np.interp(t, xs, cum)
    hd = np.diff(F)
    return np.clip(hd, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # --- Stage 1: fractional-shift re-alignment sweep ---
    deltas = [0.5, 0.25, 0.75, 0.1, 0.9]
    for delta in deltas:
        if time.process_time() >= hard - 30.0:
            break
        hd = _resample_shift(best, delta)
        if hd.sum() <= 0:
            continue
        r0 = R_of(hd)
        hd = _rescale(hd)
        r1 = R_of(hd)
        print("  [delta=%.2f] resample R=%.9f (rescaled %.9f)" %
              (delta, r0, r1))
        cap = min(hard - 28.0, time.process_time() + 2.5)
        hl = _lbfgs_log(hd, 150, cap, fg=_fun_grad)
        r2 = R_of(hl)
        cap2 = min(hard - 26.0, time.process_time() + 2.0)
        hp, r3 = _polish(hl, cap2, fracs=(0.02, 0.05, 0.10))
        print("    log=%.9f window=%.9f" % (r2, r3))
        if r3 > bestR + 1e-13:
            best, bestR = hp, r3
            print("    delta %.2f BEAT R=%.9f" % (delta, bestR))

    # --- Stage 2: base Q-sweep + polish on current best ---
    grid = [(0.90, 1e3), (0.95, 1e3), (0.95, 1e5),
            (0.99, 1e4), (0.99, 1e5)]

    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        for (c, beta) in grid:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
            q0 = _Q_value(best, c, beta)
            cap = min(hard - 2.0, time.process_time() + 3.5)
            hq = _lbfgs_log(best, 150, cap, fg=fg)
            q1 = _Q_value(hq, c, beta)
            rq = R_of(hq)
            hp, rp = _polish(hq, min(hard - 1.0, time.process_time() + 6.0))
            beat = rp > bestR + 1e-14
            print("  [sweep%d c=%.2f beta=%.0e] Q %.6f->%.6f Rq=%.9f "
                  "polish=%.9f %s" %
                  (sweep, c, beta, q0, q1, rq, rp, "BEAT" if beat else ""))
            if beat:
                best, bestR = hp, rp
                improved = True
                print("    new best R=%.9f" % bestR)
        if not improved and sweep > 2:
            if time.process_time() < hard - 3.0:
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR = hp, rp
                    print("    fallback best R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

