    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _argmax_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, Lf.size - 1)


def _prolongate_linear(hc, n_full):
    m = hc.size
    xc = np.linspace(0.0, 1.0, m)
    xf = np.linspace(0.0, 1.0, n_full)
    out = np.interp(xf, xc, hc)
    out = np.clip(out, 0, None)
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        base = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    best = base.copy()
    bestR = R_of(best)
    start_best = base.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    def try_new(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f N=%d argmax=%.4f" %
                  (name, bestR, best.size, _argmax_pos(best)))
            return True
        return False

    loop_end = deadline - 0.5
    n_full = best.size

    # ---- Attempt a 2x refinement early, since the start is already a fine
    #      local optimum: doubling resolution lets the peak sharpen.
    if n_full * 2 <= 1000000 and time.process_time() < loop_end - 20.0:
        h2x = _prolongate_linear(best, 2 * n_full)
        cap = min(loop_end - 15.0, time.process_time() + 8.0)
        h2x = _lbfgs_log(h2x, 400, cap)
        for frac in (0.01, 0.02, 0.05):
            if time.process_time() >= loop_end - 12.0:
                break
            free = _peak_window(h2x, frac=frac)
            cap = min(loop_end - 10.0, time.process_time() + 2.0)
            hp = _lbfgs_block(h2x, free, 150, cap)
            if R_of(hp) > R_of(h2x):
                h2x = hp
        if try_new("2x", h2x):
            n_full = best.size

    # ---- Main polishing loop until ~92% of budget ----
    main_end = min(loop_end, t0 + budget_seconds * 0.92)
    round_id = 0
    while time.process_time() < main_end - 2.0:
        round_id += 1
        cap = min(main_end, time.process_time() + 4.0)
        hf = _lbfgs_log(best, 300, cap)
        try_new("A r=%d" % round_id, hf)

        for frac in (0.01, 0.02, 0.05, 0.10, 0.20):
            if time.process_time() >= main_end - 1.5:
                break
            free = _peak_window(best, frac=frac)
            cap = min(main_end, time.process_time() + 1.2)
            hp = _lbfgs_block(best, free, 120, cap)
            try_new("B%.2f r=%d" % (frac, round_id), hp)

    # ---- Final polish ----
    while time.process_time() < loop_end:
        for frac in (0.01, 0.02, 0.05):
            if time.process_time() >= loop_end - 1.0:
                break
            free = _peak_window(best, frac=frac)
            cap = min(loop_end, time.process_time() + 1.2)
            hp = _lbfgs_block(best, free, 120, cap)
            try_new("F%.2f" % frac, hp)
        if time.process_time() < loop_end - 1.0:
            cap = min(loop_end, time.process_time() + 2.5)
            hf = _lbfgs_log(best, 200, cap)
            try_new("Ffull", hf)
        if time.process_time() >= loop_end:
            break

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _mass_resample(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew) / Nnew
    x = np.linspace(0.0, 1.0, Nnew + 1)
    src_x = np.linspace(0.0, 1.0, N + 1)
    target_c = np.interp(x, src_x, c)
    out = np.diff(target_c)
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return np.ones(Nnew) / Nnew
    return out * (total / out.sum())


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    # ---- establish base best (start) ----
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        start_best = _rescale(np.ones(8192))
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    # ---- work directly on start's native grid, then polish ----
    best_h = start_best.copy()
    best_R = start_bestR

    # 1. Full-grid log-space L-BFGS on start (refine directly)
    if time.process_time() < deadline - 3.0:
        cap = min(deadline - 2.0, time.process_time() + 8.0)
        hp = _lbfgs_log(best_h, 300, cap)
        rp = R_of(hp)
        print("  full-grid log polish R=%.7f" % rp)
        if rp > best_R:
            best_h, best_R = hp, rp

    # 2. Multi-scale peak-window polishes (different fractions)
    for frac in (0.01, 0.02, 0.05, 0.10, 0.20, 0.35):
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(best_h, frac=frac)
        cap = min(deadline - 1.0, time.process_time() + 3.0)
        hb = _lbfgs_block(best_h, free, 150, cap)
        rb = R_of(hb)
        if rb > best_R + 1e-12:
            best_h, best_R = hb, rb
            print("  window frac=%.2f R=%.7f" % (frac, rb))

    # 3. Fine-grained polish on the peak region: multiple narrow windows
    for _ in range(6):
        if time.process_time() >= deadline - 1.5:
            break
        free = _peak_window(best_h, frac=0.02)
        cap = min(deadline - 1.0, time.process_time() + 2.0)
        hb = _lbfgs_block(best_h, free, 120, cap)
        rb = R_of(hb)
        if rb > best_R + 1e-12:
            best_h, best_R = hb, rb
        else:
            break

    # 4. Full-grid final log polish
    if time.process_time() < deadline - 1.5:
        cap = min(deadline - 1.0, time.process_time() + 4.0)
        hp = _lbfgs_log(best_h, 250, cap)
        rp = R_of(hp)
        print("  final full polish R=%.7f" % rp)
        if rp > best_R:
            best_h, best_R = hp, rp

    # 5. Compare with start
    if best_R > start_bestR + 1e-12:
        result = best_h
        print("final R=%.7f (beat start %.7f)" % (best_R, start_bestR))
    else:
        result = {"best": start_best,
                  "alternative": best_h if best_R > start_bestR - 1e-6 else None}
        print("final R=%.7f (start %.7f kept; alternative R=%.7f)" %
              (start_bestR, start_bestR, best_R))

    Lf = _knots(best_h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    print("best R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (best_R, best_h.size, 100.0 * np.mean(best_h <= 0), mx, m, near))
    return result

