    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _peak_window(h, frac, extra=8):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _diagnostics(h):
    Lf = _knots(h)
    mx = Lf.max()
    am = int(np.argmax(Lf))
    frac = lambda t: float(np.mean(Lf >= (1.0 - t) * mx))
    return {'N': h.size, 'R': R_of(h), 'zero_frac': float(np.mean(h <= 0)),
            'argmax': am, 'argmax_frac': am / max(1, h.size),
            'f01': frac(1e-3), 'f1': frac(1e-2), 'f5': frac(5e-2)}


# ---------- new idea: shrink the grid by factor 2 (coarse-grain) ----------

def _coarsen(h, factor):
    """Average consecutive blocks of `factor` cells. Returns N//factor array."""
    n = h.size
    m = n // factor
    if m < 8:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _refine(h, factor):
    """Upsample by repeating each cell `factor` times."""
    return np.repeat(h, factor)


def _try_refine_coarsen_cycle(best, bestR, deadline, _try):
    """Build a genuinely different construction by coarse-graining the start,
    optimising the smaller problem hard, then refining back and polishing."""
    got_any = False
    for factor in (2, 3, 4):
        if time.process_time() > deadline - 15.0:
            break
        hc = _coarsen(best, factor)
        # hard optimisation on small grid (cheap per eval)
        for beta in (0.0, 1e3, 1e4, 1e5):
            if time.process_time() > deadline - 12.0:
                break
            hc = _lbfgs_log(hc, 400,
                            min(deadline - 8.0, time.process_time() + 3.0),
                            beta=beta)
        # refine back
        hr = _refine(hc, factor)
        if hr.size != best.size:
            # pad/trim to best size
            if hr.size < best.size:
                hr = np.concatenate([hr, np.zeros(best.size - hr.size)])
            else:
                hr = hr[:best.size]
        hr = _rescale(hr)
        if _try(hr, "coarse f%d" % factor):
            got_any = True
            # polish refined version
            hp = _lbfgs_log(best, 250,
                            min(deadline - 6.0, time.process_time() + 4.0),
                            beta=0.0)
            if _try(hp, "  refine-polish f%d" % factor):
                got_any = True
    return got_any


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR

    d = _diagnostics(best)
    print("start N=%d R=%.7f zero=%.3f argmax=%d (%.3f) f01=%.3f f1=%.3f f5=%.3f"
          % (d['N'], d['R'], d['zero_frac'], d['argmax'], d['argmax_frac'],
             d['f01'], d['f1'], d['f5']))

    def _try(h, tag):
        nonlocal best, bestR
        if h is None:
            return False
        r = R_of(h)
        print("  %s R=%.7f" % (tag, r))
        if r > bestR + 1e-13:
            best, bestR = h, r
            return True
        return False

    # ---- Step A: sharp polish of start ----
    if time.process_time() < deadline - 25.0:
        h = _lbfgs_log(best, 200,
                       min(deadline - 22.0, time.process_time() + 4.0), beta=0.0)
        _try(h, "A sharp")

    # ---- NEW: coarse-grain / refine cycles (genuinely different construction) ----
    _try_refine_coarsen_cycle(best, bestR, deadline, _try)

    # ---- Block polish on peak window + flanks ----
    if time.process_time() < deadline - 8.0:
        n = best.size
        free = _peak_window(best, 0.15, extra=16)
        hp = _lbfgs_block(best, free, 300,
                          min(deadline - 6.0, time.process_time() + 4.0),
                          beta=0.0)
        _try(hp, "B block peak")

    # ---- beta-continuation to sharpen the peak ----
    if time.process_time() < deadline - 4.0:
        for beta in (1e3, 1e4, 1e5):
            if time.process_time() > deadline - 3.0:
                break
            hp = _lbfgs_log(best, 200,
                            min(deadline - 2.0, time.process_time() + 2.0),
                            beta=beta)
            _try(hp, "C beta%.0e" % beta)

    # ---- Final sharp polish loop ----
    while time.process_time() < deadline - 1.0:
        hp = _lbfgs_log(best, 250,
                        min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        if not _try(hp, "D sharp"):
            break

    d = _diagnostics(best)
    print("final R=%.7f (N=%d) zero=%.3f f01=%.3f"
          % (bestR, best.size, d['zero_frac'], d['f01']))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cap(h, delta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    c = (1.0 - delta) * mx
    ramp = 0.1 * delta * c
    if ramp <= 0:
        w = (Lf < c).astype(float)
    else:
        w = np.clip((c - Lf) / ramp + 0.5, 0.0, 1.0)
    sw = np.sum(w * Lf)
    if sw <= 0:
        return _fun_grad(h)
    dLf = -w / sw
    grad = _backprop(dLf, h) + 2.0 / s
    val = -np.log(sw) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _duplicate(h, k):
    return np.repeat(h, k)


def _restrict(h, f, o):
    """Roll left by o, then average contiguous blocks of f. Length floor(N/f)."""
    n = h.size
    hr = np.roll(h, -o)
    m = n // f
    hr = hr[:m * f]
    return hr.reshape(m, f).mean(axis=1)


def _prolong(hc, f, o, n):
    """Assign each original cell the coarse value it overlaps (undo roll)."""
    up = np.repeat(hc, f)
    # up has length m*f where m = len(hc); pad to n
    if up.size < n:
        up = np.concatenate((up, np.full(n - up.size, up[-1] if up.size else 0.0)))
    else:
        up = up[:n]
    # undo roll: original index i corresponds to rolled index (i - o) mod n
    # rolled[j] = original[(j + o) mod n]  => original[i] = rolled[(i - o) mod n]
    out = np.roll(up, o)
    return out


def _polish(h, deadline, iters=150):
    if time.process_time() >= deadline - 0.3:
        return h
    cap = min(deadline - 0.2, time.process_time() + 2.0)
    hs = _lbfgs_log(h, iters, cap, beta=0.0)
    if R_of(hs) > R_of(h):
        return hs
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    experiment_best = baseH.copy()
    experiment_bestR = baseR

    n = baseH.size

    def try_cycle(h_cur, f, o, time_cap):
        """Restrict at (f,o), optimize coarse, prolongate, polish, return (h, R)."""
        if time.process_time() >= time_cap - 0.5:
            return h_cur, R_of(h_cur)
        hc = _restrict(h_cur, f, o)
        if hc.size < 8:
            return h_cur, R_of(h_cur)
        hc = _rescale(hc)
        rc0 = R_of(hc)
        cap = min(time_cap - 0.3, time.process_time() + 6.0)
        hc = _lbfgs_log(hc, 400, cap, beta=0.0)
        rc = R_of(hc)
        hp = _prolong(hc, f, o, n)
        hp = _rescale(hp)
        rp = R_of(hp)
        cap = min(time_cap - 0.2, time.process_time() + 3.0)
        hp = _lbfgs_log(hp, 300, cap, beta=0.0)
        rp2 = R_of(hp)
        hp = _polish(hp, time_cap)
        rp3 = R_of(hp)
        print("  f=%d o=%d: coarse R %.9f -> %.9f | prolong R %.9f -> %.9f -> %.9f" %
              (f, o, rc0, rc, rp, rp2, rp3))
        return hp, rp3

    # Phase 1: scan all (f, o) for f in (2,3)
    results = {}
    scan_cap = min(deadline, t0 + budget_seconds * 0.55)
    for f in (2, 3):
        for o in range(f):
            if time.process_time() >= scan_cap - 1.0:
                break
            hp, rp = try_cycle(bestH, f, o, scan_cap)
            results[(f, o)] = (hp, rp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("  >>> new best from f=%d o=%d: R=%.9f" % (f, o, bestR))

    # Pick the best (f,o)
    if results:
        best_key = max(results.keys(), key=lambda k: results[k][1])
        print("selected (f=%d, o=%d) with R=%.9f" %
              (best_key[0], best_key[1], results[best_key][1]))
    else:
        best_key = (2, 0)

    # Phase 2: repeat best cycle from current best, plus chaining
    f_best, o_best = best_key
    other_f = 3 if f_best == 2 else 2
    # find best offset for other f
    other_keys = [k for k in results if k[0] == other_f]
    if other_keys:
        other_key = max(other_keys, key=lambda k: results[k][1])
    else:
        other_key = (other_f, 0)

    round_i = 0
    while time.process_time() < deadline - 2.0:
        round_i += 1
        improved = False
        # best cycle
        hp, rp = try_cycle(bestH, f_best, o_best, deadline - 1.0)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            improved = True
            print("  round %d best-cycle improved: R=%.9f" % (round_i, bestR))
        # chaining: other factor then best factor
        if time.process_time() < deadline - 2.0:
            hp, rp = try_cycle(bestH, other_key[0], other_key[1], deadline - 1.0)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                improved = True
                print("  round %d chain-step1 improved: R=%.9f" % (round_i, bestR))
        if time.process_time() < deadline - 2.0:
            hp, rp = try_cycle(bestH, f_best, o_best, deadline - 1.0)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                improved = True
                print("  round %d chain-step2 improved: R=%.9f" % (round_i, bestR))
        if not improved and time.process_time() > deadline - 6.0:
            break

    # Final polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hs = _lbfgs_log(bestH, 150, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    if bestR > experiment_bestR + 1e-14:
        experiment_best, experiment_bestR = bestH.copy(), bestR

    mx, m, near = _stats(bestH)
    print("final N=%d R=%.9f zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, bestR, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
