        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = _rescale(s.copy())
            bestR = R_of(best)
    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    # Core idea: stronger, longer smoothing continuation + more aggressive
    # window polishing at the current resolution, plus fine-scale polishing
    # at the fixed N of the start (avoid wasteful up-sampling that the old
    # program attempted and abandoned).
    cur = best.copy()
    curR = bestR
    N = cur.size
    print("start R=%.6f N=%d" % (curR, N))

    # Multi-scale smoothing continuation at the SAME resolution.
    for beta in (1, 2, 4, 8, 16, 32, 64, 128, 256):
        if time.process_time() >= deadline - 3.0:
            break
        cap = min(deadline - 2.0, time.process_time() + 3.0)
        cand = _lbfgs_log(cur, 300, cap, fg=lambda h, b=beta: _fun_grad_sm(h, b))
        r = R_of(cand)
        if r > curR:
            cur, curR = cand, r
        if curR > bestR:
            best, bestR = cur.copy(), curR
        print("  beta=%d R=%.6f" % (beta, curR))

    # Main loop: alternate full log-space and peak-window polishing.
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        cand = _lbfgs_log(cur, 800, cap)
        r = R_of(cand)
        if r > curR:
            cur, curR = cand, r
        if curR > bestR:
            best, bestR = cur.copy(), curR

        for frac in (0.01, 0.03, 0.07, 0.15, 0.30):
            if time.process_time() >= deadline - 0.8:
                break
            free = _peak_window(cur, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 2.0)
            hb = _lbfgs_block(cur, free, 150, cap)
            rb = R_of(hb)
            if rb > curR:
                cur, curR = hb, rb
            if curR > bestR:
                best, bestR = cur.copy(), curR
        print("iter %d R=%.6f (best %.6f)" % (it, curR, bestR))

    # Final attempt with smoothing at low beta to escape shallow local min.
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 2.0)
        hb = _lbfgs_log(best, 400, cap, fg=lambda h: _fun_grad_sm(h, 64))
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb

    print("final R=%.6f N=%d" % (bestR, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _lbfgs_log_beta(h0, maxiter, deadline, beta):
    return _lbfgs_log(h0, maxiter, deadline, beta=beta)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


# ---------- New: alternating-cell (checkerboard) probes ----------
# The pair-difference idea failed because the record is not pair-symmetric.
# Instead we probe a *coarse* checkerboard: split into blocks, alternate
# scaling of even vs odd blocks. This is a much more global, structured
# perturbation that can escape the pair-symmetry dead end.

def _rand_field(M, rng, nk=6):
    e = np.zeros(M)
    for _ in range(nk):
        f = np.exp(rng.uniform(np.log(1.0), np.log(64.0)))
        ph = rng.uniform(0, 2 * np.pi)
        c = rng.normal()
        i = np.arange(M)
        e += c * np.sin(2 * np.pi * f * i / M + ph)
    m = np.max(np.abs(e))
    if m > 0:
        e /= m
    return e


def _apply_block_check(h, e, B):
    """Multiply block i by (1 + (-1)^i * e_i); e has length B."""
    n = h.size
    edges = (np.arange(B + 1) * n) // B
    h2 = h.copy()
    for i in range(B):
        sign = 1.0 if (i % 2 == 0) else -1.0
        h2[edges[i]:edges[i + 1]] *= (1.0 + sign * e[i])
    h2 = np.clip(h2, 0.0, None)
    return _rescale(h2)


def _apply_block_scale(h, e, B):
    n = h.size
    edges = (np.arange(B + 1) * n) // B
    h2 = h.copy()
    for i in range(B):
        h2[edges[i]:edges[i + 1]] *= (1.0 + e[i])
    h2 = np.clip(h2, 0.0, None)
    return _rescale(h2)


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(98765)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n = best.size
    if n < 4:
        return {"best": start_best, "alternative": start_best}

    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Phase 1: block checkerboard / scale probes (coarse, multi-scale) ----
    probe_deadline = min(deadline - 25.0, time.process_time() + 15.0)
    candidates = []
    for B in (8, 16, 32, 64, 128, 256):
        for k in range(min(12, 4 + B // 16)):
            if time.process_time() >= probe_deadline:
                break
            if k == 0:
                e = np.zeros(B)
            else:
                e = _rand_field(B, rng, nk=3)
            for d in (1e-3, 1e-2, 3e-2, 0.1):
                cand = _apply_block_check(best, d * e, B)
                r = R_of(cand)
                candidates.append((r, e.copy(), d, B, 'check'))
        # also scale (non-alternating) at small deltas
        for k in range(min(6, 2 + B // 32)):
            if time.process_time() >= probe_deadline:
                break
            e = _rand_field(B, rng, nk=3) if k > 0 else np.zeros(B)
            for d in (1e-3, 1e-2, 3e-2):
                cand = _apply_block_scale(best, d * e, B)
                r = R_of(cand)
                candidates.append((r, e.copy(), d, B, 'scale'))

    candidates.sort(key=lambda t: -t[0])
    print("  probes: %d evaluated, best raw R=%.9f (base %.9f, dR=%+.2e)" %
          (len(candidates), candidates[0][0], bestR, candidates[0][0] - bestR))
    for r, e, d, B, kind in candidates[:5]:
        print("    R=%.9f d=%.0e B=%d %s" % (r, d, B, kind))

    # ---- Phase 2: polish top candidates ----
    seen = set()
    top = []
    for c in candidates:
        key = (c[3], c[4], round(c[2], 8))
        if key in seen:
            continue
        seen.add(key)
        top.append(c)
        if len(top) >= 4:
            break

    for idx, (r, e, d, B, kind) in enumerate(top):
        if time.process_time() >= deadline - 8.0:
            break
        if kind == 'check':
            cand = _apply_block_check(best, d * e, B)
        else:
            cand = _apply_block_scale(best, d * e, B)
        cap_t = min(deadline - 2.0, time.process_time() + 8.0)
        hp, rp = _polish(cand, cap_t, r)
        print("  polish top%d (B=%d %s) raw %.9f -> %.9f" % (idx, B, kind, r, rp))
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp
            print("    NEW BEST R=%.9f" % experiment_bestR)

    # ---- Phase 3: block-additive at several scales ----
    for B in (64, 128, 256, 512, 1024, 2048):
        if time.process_time() >= deadline - 3.0:
            break
        cap_t = min(deadline - 1.5, time.process_time() + 5.0)
        hb = _block_additive(experiment_best, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= experiment_bestR - 3e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 5.0), experiment_bestR)
        else:
            hp, rp = hb, r_raw
        print("  B=%-5d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp
            print("    NEW BEST R=%.9f" % experiment_bestR)

    # ---- Phase 4: keep polishing until deadline ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(experiment_best, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, experiment_bestR))
            continue
        if time.process_time() < loop_end - 1.0:
            beta = (1e3, 1e4, 1e5)[it % 3]
            cap_t = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(experiment_best, 150, cap_t, beta=beta)
            rs = R_of(hs)
            if rs > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hs.copy(), rs
                print("  final beta=%g iter=%d R=%.9f" % (beta, it, experiment_bestR))
                continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.02 + 0.18 * np.random.random()
            free = _peak_window(experiment_best, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(experiment_best, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, experiment_bestR))

    print("final R=%.9f (best of experiment)" % experiment_bestR)
    mx, m, near = _stats(experiment_best)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (experiment_bestR, experiment_best.size,
           100.0 * np.mean(experiment_best <= 0), mx, m, near))

    if experiment_bestR > start_bestR + 1e-12:
        return {"best": experiment_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": experiment_best}

