def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # New idea: try a finer-resolution prolongation of the start, then
    # optimize at the higher resolution. The optimum tends to sharpen
    # near the plateau as resolution grows, so a finer grid can capture
    # structure the coarse grid cannot express. Use it as an alternative
    # if it doesn't beat the start.
    N = base.size
    # Choose a modest upscale factor so we can still afford several
    # L-BFGS passes on the FFT convolution within budget.
    for factor in (2,):
        if time.process_time() >= hard_end - 6.0:
            break
        M = min(1000000, N * factor)
        if M <= N:
            continue
        hf = _prolongate(base, M)
        rf = R_of(hf)
        # softmax homotopy at fine resolution
        for beta in (800.0, 300.0, 120.0):
            if time.process_time() >= hard_end - 3.0:
                break
            c = _lbfgs_sm(hf, beta, maxiter=80, deadline=hard_end)
            rc = R_of(c)
            if rc > rf:
                hf, rf = c, rc
        if time.process_time() < hard_end - 2.0:
            c = _lbfgs_log(hf, maxiter=200, deadline=hard_end)
            rc = R_of(c)
            if rc > rf:
                hf, rf = c, rc
        # peak-window polish at fine resolution
        for frac, extra in ((0.10, 8), (0.04, 4)):
            if time.process_time() >= hard_end - 1.0:
                break
            c = _window_polish_peak(hf, hard_end, frac, extra, maxiter=200)
            rc = R_of(c)
            if rc > rf:
                hf, rf = c, rc
        print("upscale x%d R=%.6f (base %.6f)" % (factor, rf, base_r))
        _consider(hf, rf)

    # Fallback: refine the base at its own resolution, plus one more
    # fine-grid attempt if time remains.
    try:
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.20, 12), (0.10, 6), (0.05, 3)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=300, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

