    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # New idea: try a finer-resolution prolongation of the start, then
    # optimize at the higher resolution. The optimum tends to sharpen
    # near the plateau as resolution grows, so a finer grid can capture
    # structure the coarse grid cannot express. Use it as an alternative
    # if it doesn't beat the start.
    N = base.size
    # Choose a modest upscale factor so we can still afford several
    # L-BFGS passes on the FFT convolution within budget.
    for factor in (2,):
        if time.process_time() >= hard_end - 6.0:
            break
        M = min(1000000, N * factor)
        if M <= N:
            continue
        hf = _prolongate(base, M)
        rf = R_of(hf)
        # softmax homotopy at fine resolution
        for beta in (800.0, 300.0, 120.0):
            if time.process_time() >= hard_end - 3.0:
                break
            c = _lbfgs_sm(hf, beta, maxiter=80, deadline=hard_end)
            rc = R_of(c)
            if rc > rf:
                hf, rf = c, rc
        if time.process_time() < hard_end - 2.0:
            c = _lbfgs_log(hf, maxiter=200, deadline=hard_end)
            rc = R_of(c)
            if rc > rf:
                hf, rf = c, rc
        # peak-window polish at fine resolution
        for frac, extra in ((0.10, 8), (0.04, 4)):
            if time.process_time() >= hard_end - 1.0:
                break
            c = _window_polish_peak(hf, hard_end, frac, extra, maxiter=200)
            rc = R_of(c)
            if rc > rf:
                hf, rf = c, rc
        print("upscale x%d R=%.6f (base %.6f)" % (factor, rf, base_r))
        _consider(hf, rf)

    # Fallback: refine the base at its own resolution, plus one more
    # fine-grid attempt if time remains.
    try:
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.20, 12), (0.10, 6), (0.05, 3)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=300, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h, N_small):
    n = h.size
    if n == N_small:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(N_small)
    return hc


def _smooth(h, sigma):
    if sigma <= 0:
        return h
    n = h.size
    r = max(1, int(np.ceil(3 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    if n > 4000:
        return np.clip(fftconvolve(h, k, mode='same'), 0, None)
    return np.clip(np.convolve(h, k, mode='same'), 0, None)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _refine_at_scale(h, deadline, betas=(0.0, 200.0, 1000.0, 5000.0)):
    if time.process_time() >= deadline - 1.0:
        return h
    best = h.copy()
    bestR = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(best, 800, deadline, beta=beta)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand, r
        for frac in (0.08, 0.20, 0.40, 0.70):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(best, frac)
            cand = _lbfgs_block(best, free, 500, deadline, beta=beta)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt, altR = None, 0.0

    def consider(h, r, tag):
        nonlocal best, bestR, alt, altR
        print("%s R=%.7f" % (tag, r))
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))
            return True
        elif alt is None or r > altR:
            alt, altR = h, r
        return False

    # Stage A: higher-resolution prolongation attempt. The start is likely
    # near-optimal at its own N; a finer grid can capture extra structure near
    # the peak, which is where R is most sensitive.
    if time.process_time() < deadline - 20.0:
        for factor in (2, 4):
            if time.process_time() >= deadline - 18.0:
                break
            Nb = min(1000000, N * factor)
            hp = _rescale(_prolongate(best, Nb))
            cap = min(time.process_time() + 8.0, deadline - 12.0)
            hp = _refine_at_scale(hp, cap, betas=(0.0, 500.0, 2000.0))
            consider(hp, R_of(hp), "up%d" % Nb)
            # if it beats, keep working at this N
            if best.size == Nb and bestR > startR + 1e-12:
                break

    # Stage B: polish at current resolution.
    if time.process_time() < deadline - 8.0:
        h = _refine_at_scale(best, min(time.process_time() + 10.0, deadline - 8.0))
        consider(h, R_of(h), "polish")

    # Stage C: coarsen-refine-prolongate cycle.
    for Nc in (4096, 8192, 16384, 32768):
        if time.process_time() >= deadline - 6.0:
            break
        if Nc >= best.size:
            continue
        hc = _coarsen(best, Nc)
        cap = min(time.process_time() + 4.0, deadline - 6.0)
        hc = _refine_at_scale(hc, cap, betas=(0.0, 500.0, 2000.0))
        hp = _rescale(_prolongate(hc, best.size))
        cap = min(time.process_time() + 4.0, deadline - 4.0)
        hp = _refine_at_scale(hp, cap, betas=(0.0, 1000.0))
        consider(hp, R_of(hp), "scale%d" % Nc)

    # Stage D: smoothing escapes.
    for sigma in (5.0, 20.0, 60.0):
        if time.process_time() >= deadline - 4.0:
            break
        hs = _rescale(_smooth(best, sigma))
        if hs.sum() <= 0:
            continue
        cap = min(time.process_time() + 3.0, deadline - 3.0)
        hs = _refine_at_scale(hs, cap, betas=(0.0, 300.0))
        consider(hs, R_of(hs), "smooth%.0f" % sigma)

    # Stage E: final polish loop.
