def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _peak_window(h, frac, extra=8):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    h = _lbfgs_log(h, 200, min(deadline, time.process_time() + 2.0), beta=0.0)
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() > deadline - 0.5:
            break
        h = _lbfgs_log(h, 150, min(deadline, time.process_time() + 1.5), beta=beta)
    if time.process_time() < deadline - 0.3:
        h = _lbfgs_log(h, 200, min(deadline, time.process_time() + 1.5), beta=0.0)
    return h


def _diagnostics(h):
    Lf = _knots(h)
    mx = Lf.max()
    am = int(np.argmax(Lf))
    frac = lambda t: float(np.mean(Lf >= (1.0 - t) * mx))
    return {'N': h.size, 'R': R_of(h), 'zero_frac': float(np.mean(h <= 0)),
            'argmax': am, 'argmax_frac': am / max(1, h.size),
            'f01': frac(1e-3), 'f1': frac(1e-2), 'f5': frac(5e-2)}


def _perturb(h, rng, sigma, gamma, revive_prob):
    """Perturbed copy: log-normal multiplicative noise, linear tilt, optional zero revival."""
    h = h.copy()
    n = h.size
    pos = h > 0
    if pos.any():
        h[pos] *= np.exp(rng.normal(0.0, sigma, size=int(pos.sum())))
    # linear tilt
    x = np.linspace(0.0, 1.0, n)
    h *= np.clip(1.0 + gamma * (x - 0.5), 0.05, None)
    # optional zero revival in a random window
    if rng.random() < revive_prob:
        zeros = np.flatnonzero(h <= 0)
        if zeros.size > 0:
            w = int(rng.uniform(0.10, 0.20) * n)
            w = max(8, min(w, n))
            lo = int(rng.integers(0, max(1, n - w)))
            hi = lo + w
            win_zeros = np.flatnonzero(h[lo:hi] <= 0)
            if win_zeros.size > 0:
                nz = h[h > 0]
                scale = 0.01 * (nz.mean() if nz.size > 0 else 1.0)
                h[lo + win_zeros] = scale * rng.uniform(0.3, 3.0, size=win_zeros.size)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds * 0.90
    margin = 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 42496
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    N = best.size

    d = _diagnostics(best)
    print("start N=%d R=%.7f zero=%.3f argmax=%d (%.3f) f01=%.3f f1=%.3f f5=%.3f"
          % (d['N'], d['R'], d['zero_frac'], d['argmax'], d['argmax_frac'],
             d['f01'], d['f1'], d['f5']))

    rng = np.random.default_rng(987654321)

    def _try(h, tag):
        nonlocal best, bestR
        if h is None:
            return False
        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h, r
            print("  %s R=%.7f" % (tag, r))
            return True
        return False

    # initial sharp polish of start
    if time.process_time() < hard - 40.0:
        h = _lbfgs_log(best, 200,
                       min(hard - 35.0, time.process_time() + 4.0), beta=0.0)
        _try(h, "A sharp")

    sigmas = [0.05, 0.10, 0.20]
    gammas = [-0.3, -0.15, 0.0, 0.15, 0.3]
    trial = 0
    best_trial_R = bestR
    distinct_hits = 0

    while time.process_time() < hard - margin:
        sigma = sigmas[trial % len(sigmas)]
        gamma = gammas[(trial // len(sigmas)) % len(gammas)]
        revive_prob = 0.5

        src = best if rng.random() < 0.85 else start_best
        h = _perturb(src, rng, sigma, gamma, revive_prob)

        # (2) polish: exact-R log-space L-BFGS
        h = _lbfgs_log(h, 200,
                       min(hard - margin - 0.5, time.process_time() + 3.0),
                       beta=0.0)
        # beta ladder
        for beta in (1e2, 1e3, 1e4, 1e5):
            if time.process_time() >= hard - margin - 0.5:
                break
            h = _lbfgs_log(h, 150,
                           min(hard - margin - 0.3, time.process_time() + 1.5),
                           beta=beta)
        # final polish with block windows
        if time.process_time() < hard - margin - 0.5:
            h = _polish(h, min(hard - margin - 0.2, time.process_time() + 3.0))
        for frac in (0.02, 0.05, 0.10, 0.20):
            if time.process_time() >= hard - margin - 0.3:
                break
            free = _peak_window(h, frac, extra=16)
            h = _lbfgs_block(h, free, 150,
                             min(hard - margin - 0.1, time.process_time() + 1.0),
                             beta=0.0)

        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h, r
            print("  trial %d sigma=%.2f gamma=%.2f R=%.7f (+%.2e)"
                  % (trial, sigma, gamma, r, r - start_bestR))
            if r > start_bestR + 1e-4:
                distinct_hits += 1
        elif r > start_bestR + 1e-4:
            distinct_hits += 1

        if trial % 5 == 0:
            d = _diagnostics(best)
            print("trial %d R=%.7f zero=%.3f distinct=%d"
                  % (trial, bestR, d['zero_frac'], distinct_hits))
        trial += 1
        if trial > 500:
            break

    # final polish
    if time.process_time() < hard - 0.5:
        hp = _polish(best, hard - 0.3)
        _try(hp, "final polish")

    d = _diagnostics(best)
    print("final R=%.7f (N=%d) zero=%.3f f01=%.3f trials=%d distinct=%d"
          % (bestR, best.size, d['zero_frac'], d['f01'], trial, distinct_hits))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _smooth_max_refine(h, deadline, betas=(200.0, 800.0, 3000.0)):
    """Refine using smoothed max (softmax) then exact."""
    cur = h
    curR = R_of(h)
    for beta in betas:
        if time.process_time() >= deadline - 0.3:
            break
        fg = lambda hh, b=beta: _fun_grad_sm(hh, b)
        cand = _lbfgs_log(cur, maxiter=300, deadline=deadline, fg=fg)
        # finalize with exact objective
        cand = _lbfgs_log(cand, maxiter=200, deadline=deadline)
        cR = R_of(cand)
        if cR > curR:
            cur, curR = cand, cR
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(987654)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Track A: alternative resolution refinement
    alt = None
    alt_r = -1.0
    N_alt = max(4096, cur.size // 2)
    if cur.size >= N_alt and time.process_time() < deadline - 25.0:
        c = _rescale(_coarsen(cur, N_alt))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        c = _rescale(_prolongate(c, cur.size))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        alt = c
        alt_r = R_of(c)
        print("alt coarsen R = %.6f" % alt_r)
        if alt_r > best_r:
            cur, cur_r = alt.copy(), alt_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    # Main loop: alternate exact-max LBFGS with smoothed-max refinement
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        # Smoothed max refinement (new idea: helps navigate max's kinks)
        if time.process_time() < deadline - 5.0:
            cand, cr = _smooth_max_refine(cur, deadline)
            if cr > cur_r:
                cur, cur_r = cand, cr
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if time.process_time() >= deadline - 1.0:
            break

        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, extra in ((0.05, 4), (0.15, 10)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
