    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _symmetrize(h):
    # f symmetric about center => autoconvolution symmetric, peak at center.
    n = h.size
    hh = h.copy()
    m = n // 2
    for i in range(m):
        j = n - 1 - i
        v = 0.5 * (hh[i] + hh[j])
        hh[i] = v
        hh[j] = v
    return hh


def _polish(h, deadline):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in (0.02, 0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 2.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # --- NEW: symmetrization. The optimal f for this problem is symmetric
    # about its center (autoconvolution then peaks at the center). Enforce
    # symmetry then re-optimize: this removes half the free parameters and
    # moves toward the true symmetric optimum, which the hard-max gradient
    # (which only sees the single peak knot) tends to drift away from.
    sym = _symmetrize(best)
    symR = R_of(sym)
    if symR > bestR - 1e-6:
        # optimize in symmetric space: only half the array is free
        n = best.size
        m = n // 2
        free = np.arange(m)
        cap = min(hard - 8.0, time.process_time() + 6.0)

        def f_sym(x):
            hh = np.empty(n)
            hh[free] = np.clip(x, 0.0, None)
            hh[n - 1 - free] = hh[free]
            val, g = _fun_grad(hh)
            # gradient w.r.t. unique half: sum of both contributions
            gf = g[free] + g[n - 1 - free]
            return val, gf

        cb = _make_cb(cap - 0.2)
        try:
            res = minimize(f_sym, np.clip(sym[free], 1e-9, None),
                           jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * m, callback=cb,
                           options={'maxiter': 400, 'maxfun': 800,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is not None:
                hh = np.empty(n)
                hh[free] = np.clip(res.x, 0.0, None)
                hh[n - 1 - free] = hh[free]
                hh = _rescale(hh)
                rr = R_of(hh)
                if rr > bestR:
                    best, bestR = hh, rr
                    print("  symmetric: R=%.9f" % bestR)
        except (TimeoutError, Exception):
            pass

    # --- Soft-max continuation ---
    betas = [1.0, 3.0, 10.0, 30.0, 100.0, 300.0, 1000.0, 3000.0, 10000.0]
    cur = best
    curR = bestR
    for beta in betas:
        if time.process_time() >= hard - 6.0:
            break
        cap = min(hard - 5.0, time.process_time() + 4.0)
        hb = _lbfgs_log(cur, 300, cap, beta=beta)
        rb = R_of(hb)
        if rb > curR - 1e-9:
            cur, curR = hb, rb
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
            print("  beta=%.0f: R=%.9f" % (beta, bestR))

    # --- Hard-max polish ---
    if time.process_time() < hard - 3.0:
        cap = min(hard - 2.5, time.process_time() + 4.0)
        hp = _lbfgs_log(best, 400, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
            print("  lbfgs hard: R=%.9f" % bestR)

    # --- Local block polish around peak ---
    if time.process_time() < hard - 1.0:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp
            print("  polish: R=%.9f" % bestR)

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

