def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolong2(h, soften=1.0):
    n = h.size
    h = np.asarray(h, dtype=float)
    nxt = np.empty(n)
    nxt[:-1] = h[1:]
    nxt[-1] = h[-1]
    d = (nxt - h) / 4.0 * soften
    a = np.clip(h - d, 0.0, None)
    b = np.clip(h + d, 0.0, None)
    out = np.empty(2 * n)
    out[0::2] = a
    out[1::2] = b
    return out


def _ladder(h, deadline, best, bestR, tag=""):
    cur = h.copy()
    curR = R_of(cur)
    if curR > bestR:
        best, bestR = cur.copy(), curR
        print("  %s init R=%.7f" % (tag, bestR))

    beta_list = (1e4, 1e5, 1e6, 1e7)

    for beta in beta_list:
        if time.process_time() >= deadline - 3.0:
            return best, bestR
        hb = _lbfgs_log(cur, 150, deadline, beta=beta)
        hs = _lbfgs_log(hb, 150, deadline)
        hw = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=150)
        rs = R_of(hs); rw = R_of(hw)
        cand, rc = (hw, rw) if rw > rs else (hs, rs)
        if rc > curR + 1e-13:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  %s beta=%.0e R=%.7f" % (tag, beta, bestR))

    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Main strategy: fine-grained peak-region polish of the start.
    cur = start_best.copy()
    curR = start_bestR
    for frac, extra in ((0.05, 64), (0.10, 64), (0.15, 128), (0.25, 128)):
        if time.process_time() >= deadline - 2.0:
            break
        hw = _window_polish_peak(cur, deadline, frac, extra, maxiter=300)
        rw = R_of(hw)
        if rw > curR + 1e-13:
            cur, curR = hw, rw
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  win frac=%.2f R=%.7f" % (frac, bestR))
        hp = _window_polish_peak(cur, deadline, frac, extra, maxiter=200, beta=1e6)
        rp = R_of(hp)
        if rp > curR + 1e-13:
            cur, curR = hp, rp
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  winB frac=%.2f R=%.7f" % (frac, bestR))

    # Full sharp polish on all active entries
    if time.process_time() < deadline - 1.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf
            print("  sharp R=%.7f" % bestR)

    # Alternative: prolong 2x then ladder, in case finer N helps
    if time.process_time() < deadline - 6.0:
        h2 = _rescale(_prolong2(start_best, soften=0.5))
        r2 = R_of(h2)
        print("prolong2 soften R=%.7f (N=%d)" % (r2, h2.size))
        if r2 > start_bestR - 5e-3:
            best, bestR = _ladder(h2, deadline, best, bestR, tag="2x")

    # Final polish
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _ratio_spread(h):
    if h.size < 2 or h.size % 2 != 0:
        return 1.0
    a = h[0::2]
    b = h[1::2]
    eps = 1e-12
    r = (a + eps) / (b + eps)
    return float(r.max() / max(r.min(), 1e-12))


def _smooth_modulate(h, A, k, phi):
    n = h.size
    if n % 2 != 0:
        return h
    M = n // 2
    a = h[0::2].copy()
    i = np.arange(M, dtype=float)
    u = A * np.sin(2.0 * np.pi * k * i / M + phi)
    h2 = np.empty(n, dtype=float)
    h2[0::2] = a * (1.0 + u)
    h2[1::2] = a * (1.0 - u)
    h2 = np.clip(h2, 0.0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best
    bestR = start_bestR
    print("start R=%.9f (N=%d) spread=%.4f" %
          (start_bestR, start_best.size, _ratio_spread(start_best)))

    # Large smooth odd/even modulation seeds
    As = [0.10, 0.25, 0.50]
    ks = [1, 3, 8, 32]
    phis = [0.0, np.pi / 2.0]

    seeds = []
    for A in As:
        for k in ks:
            for phi in phis:
                if time.process_time() >= hard - 3.0:
                    break
                hs = _smooth_modulate(start_best, A, k, phi)
                rs = R_of(hs)
                sp = _ratio_spread(hs)
                seeds.append((rs, hs, A, k, phi))
                print("  seed A=%.2f k=%d phi=%.2f R=%.9f spread=%.4f" %
                      (A, k, phi, rs, sp))

    seeds.sort(key=lambda t: -t[0])

    # Polish top seeds
    for (rs, hs, A, k, phi) in seeds[:8]:
        if time.process_time() >= hard - 2.0:
            break
        cap = min(hard - 1.0, time.process_time() + 2.5)
        hx = _lbfgs_log(hs, 150, cap, fg=_fun_grad)
        rx = R_of(hx)
        if time.process_time() < hard - 1.0:
            hp, rp = _polish(hx, min(hard - 0.5,
                                     time.process_time() + 3.0))
            if rp > rx:
                hx, rx = hp, rp
        print("  polish A=%.2f k=%d phi=%.2f -> R=%.9f spread=%.4f" %
              (A, k, phi, rx, _ratio_spread(hx)))
        if rx > bestR + 1e-14:
            best, bestR = hx, rx
            print("    new best R=%.9f" % bestR)

    # Cycle full exact-R + peak polish on best
    sweep = 0
    while time.process_time() < hard - 1.0:
        sweep += 1
        improved = False
        if time.process_time() < hard - 1.0:
            cap = min(hard - 0.5, time.process_time() + 2.5)
            hx = _lbfgs_log(best, 200, cap, fg=_fun_grad)
            rx = R_of(hx)
            if rx > bestR + 1e-14:
                best, bestR = hx, rx
                improved = True
                print("  [sweep%d exact] R=%.9f spread=%.4f" %
                      (sweep, bestR, _ratio_spread(best)))
        if time.process_time() < hard - 1.0:
            hp, rp = _polish(best, min(hard - 0.3,
                                       time.process_time() + 3.0))
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                improved = True
                print("  [sweep%d polish] R=%.9f spread=%.4f" %
                      (sweep, bestR, _ratio_spread(best)))
        if not improved and sweep > 2:
            # try a fresh smooth modulation from best
            hs = _smooth_modulate(best, 0.25, 8, 0.0)
            rs = R_of(hs)
            if rs > bestR + 1e-13:
                best, bestR = hs, rs
                print("    remodulate best R=%.9f" % bestR)

    print("final R=%.9f (N=%d) spread=%.4f" %
          (bestR, best.size, _ratio_spread(best)))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

