    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def _inv_sqrt_profile(L, eps):
    # cell-average of (x+eps)^-1/2 over [i, i+1), i=0..L-1, x measured inward
    x0 = np.arange(L, dtype=float)
    x1 = x0 + 1.0
    return 2.0 * (np.sqrt(x1 + eps) - np.sqrt(x0 + eps))


def _blend_edge(h, side, L, alpha, eps):
    n = h.size
    nz = np.flatnonzero(h > 1e-12 * h.max())
    if nz.size == 0:
        return h
    a, b = nz[0], nz[-1] + 1
    L = min(L, (b - a) // 2)
    if L < 4:
        return h
    p = _inv_sqrt_profile(L, eps)
    h2 = h.copy()
    if side == 'left':
        idx = np.arange(a, a + L)
        p = p[::-1]  # inner boundary is at a+L-1
        # normalize so p at inner boundary matches h there
        target = h[a + L - 1]
        if p[-1] <= 0:
            return h
        p = p * (target / p[-1])
    else:
        idx = np.arange(b - L, b)
        target = h[b - L]
        if p[0] <= 0:
            return h
        p = p * (target / p[0])
    h2[idx] = (1.0 - alpha) * h[idx] + alpha * p
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # --- Experiment: analytic inverse-sqrt edge blends ---
    N = best.size
    L_fracs = (0.05, 0.10, 0.20)
    alphas = (0.1, 0.3, 0.6, 1.0)
    eps_list = (0.5, 1.0)
    cand_best = best
    cand_bestR = bestR
    for Lf_ in L_fracs:
        if time.process_time() >= hard - 8.0:
            break
        L = max(8, int(Lf_ * N))
        for eps in eps_list:
            for side in ('left', 'right'):
                for alpha in alphas:
                    if time.process_time() >= hard - 8.0:
                        break
                    hb = _blend_edge(best, side, L, alpha, eps)
                    hb = _rescale(hb)
                    rb0 = R_of(hb)
                    cap = min(hard - 3.0, time.process_time() + 3.0)
                    hp = _lbfgs_log(hb, 200, cap, fg=_fun_grad)
                    rp = R_of(hp)
                    print("  [blend %s L=%.2f eps=%.1f a=%.1f] R %.6f->%.6f" %
                          (side, Lf_, eps, alpha, rb0, rp))
                    if rp > cand_bestR + 1e-14:
                        cand_best, cand_bestR = hp, rp
                        print("    cand best R=%.9f" % cand_bestR)
    # polish the best candidate
    if cand_bestR > bestR + 1e-14:
        cap = min(hard - 2.0, time.process_time() + 4.0)
        hp, rp = _polish(cand_best, cap)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("  edge-blend improved best R=%.9f" % bestR)

    # --- Continue base's sweep/polish with remaining budget ---
    grid = [(0.90, 1e3), (0.95, 1e3), (0.95, 1e5),
            (0.99, 1e4), (0.99, 1e5)]

    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        for (c, beta) in grid:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
            q0 = _Q_value(best, c, beta)
            cap = min(hard - 2.0, time.process_time() + 3.5)
            hq = _lbfgs_log(best, 150, cap, fg=fg)
            q1 = _Q_value(hq, c, beta)
            rq = R_of(hq)
            hp, rp = _polish(hq, min(hard - 1.0, time.process_time() + 6.0))
            beat = rp > bestR + 1e-14
            print("  [sweep%d c=%.2f beta=%.0e] Q %.6f->%.6f Rq=%.9f "
                  "polish=%.9f %s" %
                  (sweep, c, beta, q0, q1, rq, rp, "BEAT" if beat else ""))
            if beat:
                best, bestR = hp, rp
                improved = True
                print("    new best R=%.9f" % bestR)
        if not improved and sweep > 2:
            if time.process_time() < hard - 3.0:
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR = hp, rp
                    print("    fallback best R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}
